def queue_item_is_activeish(row):
    """Canonical queue lifecycle truth: every active, nonterminal row is work."""
    row = row if isinstance(row, dict) else {}
    state = str(row.get("state") or "").strip().lower()
    return bool(row.get("active")) and state not in QUEUE_TERMINAL_STATES
