def ensure_columns(con, table, columns):
    existing = {row["name"] for row in con.execute(f"pragma table_info({table})")}
    for name, sql_type in columns.items():
        if name not in existing:
            con.execute(f"alter table {table} add column {name} {sql_type}")


def ensure_schema(db_path):
    with connect(db_path) as con:
        init_schema(con)
    return True


def backfill_queue_retry_columns(con):
    if not table_exists(con, "queue_items"):
        return 0
    columns = {row["name"] for row in con.execute("pragma table_info(queue_items)")}
    if "retry_after" not in columns or "retry_after_iso" not in columns:
        return 0
    rows = con.execute(
        """
        select id, raw_json
        from queue_items
        where retry_after is null
          and coalesce(raw_json, '') like '%retry_after%'
        """
    ).fetchall()
    changed = 0
    for row in rows:
        raw = json_loads(row["raw_json"] or "{}", {})
        retry_after, retry_after_iso = queue_retry_columns_from_raw(raw)
        if retry_after is None and retry_after_iso is None:
            continue
        con.execute(
            "update queue_items set retry_after=?, retry_after_iso=? where id=?",
            (retry_after, retry_after_iso, row["id"]),
        )
        changed += 1
    return changed


def normalize_source_attempt_payload(attempt):
    if not isinstance(attempt, dict):
        return attempt
    if inkdrop_sources is not None:
        try:
            return inkdrop_sources.normalize_source_attempt(attempt)
        except Exception:
            pass
    out = dict(attempt)
    source = metadata_provider_key(out.get("source") or out.get("provider_id") or out.get("download_client") or "source")
    status = str(out.get("status") or "").strip().lower()
    out.setdefault("provider_id", source)
    out.setdefault("source_type", "source")
    out.setdefault("lifecycle_phase", status or "observed")
    out.setdefault("retry_eligible", 1 if any(token in status for token in ("retry", "fail", "error", "blocked", "no_candidate")) else 0)
    out.setdefault("failure_reason", str(out.get("reason") or status or "").strip() if out.get("retry_eligible") else "")
    return out


SENSITIVE_EVIDENCE_HEADER_KEYS = {
    "authorization",
    "cookie",
    "proxy-authorization",
    "set-cookie",
    "x-api-key",
    "x-auth-token",
}

# Credential-bearing query parameters as they appear INSIDE free text. The
# URL-hashing above only catches strings that START with http(s); a transport
# exception ("Max retries exceeded with url: /api?apikey=...") embeds the
# key mid-string and sails straight into failure_reason / raw evidence.
# SABnzbd and Prowlarr both authenticate via ?apikey=, so one stack trace
# recorded verbatim is a durable credential leak.
CREDENTIAL_QUERY_PARAM_PATTERN = re.compile(
    r"(?i)\b(apikey|api_key|api-key|token|access_token|refresh_token|password|passwd|secret|auth)"
    r"(\s*[=:]\s*)([^&\s\"'<>#;,]+)"
)


def scrub_credential_query_params(text):
    """Redact credential-shaped key=value pairs anywhere inside free text."""
    return CREDENTIAL_QUERY_PARAM_PATTERN.sub(r"\1\2[redacted]", text)

def _replayable_page_image_url(text):
    """True for page-image URLs whose shape cannot carry a reusable credential.

    page_image_urls is the one URL list that is OPERATIONAL, not evidence: the
    page-pack downloader executes straight from the stored task, so hashing
    these bricks the download outright -- measured live 2026-07-29, 44 tasks
    (32 Suwayomi + 12 MangaDex) failed unsupported_page_image_scheme because
    every stored page URL read 'sha256:...'. MangaDex CDN and Suwayomi page
    URLs are plain paths; anything shaped like a credential carrier (userinfo,
    query string such as Prowlarr's apikey=..., fragment) still gets hashed.
    """
    try:
        parts = urlsplit(str(text or ""))
    except ValueError:
        return False
    if parts.scheme.lower() not in {"http", "https"}:
        return False
    if not parts.hostname:
        return False
    if parts.username is not None or parts.password is not None:
        return False
    if parts.query or parts.fragment:
        return False
    return True


def privacy_safe_evidence_payload(value, key=""):
    """Return history/source evidence without reusable URLs or header secrets."""
    key_text = str(key or "").strip().lower()
    if isinstance(value, dict):
        out = {}
        for child_key, child_value in value.items():
            child_name = str(child_key)
            child_lower = child_name.lower()
            if child_lower in SENSITIVE_EVIDENCE_HEADER_KEYS:
                out[child_name] = "[redacted]"
                continue
            safe_value = privacy_safe_evidence_payload(child_value, child_name)
            out[child_name] = safe_value
        return out
    if isinstance(value, list):
        return [privacy_safe_evidence_payload(item, key_text) for item in value]
    if isinstance(value, tuple):
        return [privacy_safe_evidence_payload(item, key_text) for item in value]
    if isinstance(value, str):
        text = value.strip()
        if text.startswith(("http://", "https://")):
            if key_text == "page_image_urls" and _replayable_page_image_url(text):
                return value
            return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()
        if key_text in SENSITIVE_EVIDENCE_HEADER_KEYS:
            return "[redacted]"
        return scrub_credential_query_params(value)
    return value


SLSKD_PRIVATE_CREDENTIAL_KEYS = {
    "password", "passwd", "api_key", "apikey", "token", "secret",
    "access_token", "refresh_token",
} | SENSITIVE_EVIDENCE_HEADER_KEYS
SLSKD_PRIVATE_PEER_KEYS = {"peer", "peer_name", "peername", "username", "user_name", "user"}
SLSKD_PRIVATE_REMOTE_LOCATOR_KEYS = {
    "download_url", "downloadurl", "url", "magnet", "magnet_url", "magneturl",
    "remote_filename", "remotefilename", "remote_path", "remotepath",
    "source_path", "sourcepath", "candidate_path", "candidate_locator", "locator",
    "filename", "file_name", "name", "path",
}
SLSKD_SAFE_BASENAME_KEYS = {"filename", "file_name", "name", "remote_filename", "remotefilename"}
SLSKD_LOCAL_EVIDENCE_PATH_KEYS = {
    "local_path", "localpath", "destination_path", "destinationpath", "dest_path",
    "save_path", "staging_path", "managed_path", "import_path",
}


def slskd_private_evidence_payload(value, key=""):
    """Recursively remove reusable SLSKD peer, credential, and remote-locator evidence."""
    key_text = str(key or "").strip().lower()
    if isinstance(value, dict):
        out = {}
        for child_key, child_value in value.items():
            child_name = str(child_key)
            child_lower = child_name.lower()
            if child_lower in SLSKD_PRIVATE_CREDENTIAL_KEYS or child_lower in SLSKD_PRIVATE_PEER_KEYS:
                out[child_name] = "[redacted]"
            else:
                out[child_name] = slskd_private_evidence_payload(child_value, child_name)
        return out
    if isinstance(value, (list, tuple)):
        return [slskd_private_evidence_payload(item, key_text) for item in value]
    if not isinstance(value, str):
        return value
    text = value.strip()
    if key_text in SLSKD_PRIVATE_CREDENTIAL_KEYS or key_text in SLSKD_PRIVATE_PEER_KEYS:
        return "[redacted]"
    if key_text == "provider" and text.lower() not in {"slskd", "soulseek"}:
        return "[redacted]"
    url_or_magnet = text.lower().startswith(("http://", "https://", "magnet:?"))
    directory_qualified = bool(
        text.startswith(("\\\\", "//"))
        or re.match(r"^[A-Za-z]:[\\/]", text)
        or "\\" in text
        or "/" in text
    )
    remote_path = bool(
        directory_qualified
        and key_text not in SLSKD_LOCAL_EVIDENCE_PATH_KEYS
        and (key_text in SLSKD_PRIVATE_REMOTE_LOCATOR_KEYS or key_text not in SLSKD_SAFE_BASENAME_KEYS)
    )
    if (url_or_magnet or remote_path) and key_text in SLSKD_SAFE_BASENAME_KEYS and not url_or_magnet:
        return text.replace("/", "\\").rstrip("\\").rsplit("\\", 1)[-1]
    if url_or_magnet or remote_path:
        return "sha256:" + hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()
    return scrub_credential_query_params(value)


def slskd_private_evidence(attempt):
    attempt = attempt if isinstance(attempt, dict) else {}
    return bool(
        str(attempt.get("source") or "").strip().lower() in {"slskd", "soulseek"}
        or str(attempt.get("protocol") or "").strip().lower() in {"slskd", "soulseek"}
        or normalized_download_client(attempt.get("download_client")).lower() == "slskd"
    )


IMPORT_RECONCILIATION_STAGES = {
    "completed_download_detection", "artifact_discovery", "artifact_validation",
    "library_classification", "canonical_folder_resolution", "canonical_filename_generation",
    "file_placement", "metadata_writing", "reader_scan_request",
    "reader_visibility_projection", "final_completion_projection",
}


def _record_import_reconciliation_stage(con, import_result_id, stage, *, status, error_code="", error_category="", now=None):
    import_result_id = str(import_result_id or "").strip()
    stage = str(stage or "").strip().lower()
    status = str(status or "").strip().lower()
    if stage not in IMPORT_RECONCILIATION_STAGES:
        raise ValueError(f"unsupported import reconciliation stage: {stage}")
    if status not in {"succeeded", "failed", "pending"}:
        raise ValueError(f"unsupported import reconciliation status: {status}")
    now = float(now or time.time())
    row = con.execute(
        "select series_id,issue_id,raw_json from import_results where id=? limit 1",
        (import_result_id,),
    ).fetchone()
    if not row:
        return False
    raw = json_loads(row["raw_json"] or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    stages = raw.get("import_reconciliation_stages_v1")
    stages = stages if isinstance(stages, list) else []
    outcome = {
        "stage": stage, "status": status, "recorded_at": now,
        "error_code": metadata_provider_key(error_code)[:80] if error_code else "",
        "error_category": metadata_provider_key(error_category)[:40] if error_category else "",
    }
    stages = [item for item in stages if isinstance(item, dict) and item.get("stage") != stage]
    stages.append(outcome)
    raw["import_reconciliation_stages_v1"] = stages[-len(IMPORT_RECONCILIATION_STAGES):]
    if status == "failed":
        raw["last_import_reconciliation_error"] = outcome
    con.execute("update import_results set raw_json=? where id=?", (json_dumps(raw), import_result_id))
    con.execute(
        """
        insert or replace into history_events(
            id,entity_type,entity_id,series_id,issue_id,event_type,source,message,
            outcome,display_phase,created_at,raw_json
        ) values(?,?,?,?,?,?,?,?,?,?,?,?)
        """,
        (
            stable_id("import_reconciliation_stage", import_result_id, stage),
            "import_result", import_result_id, row["series_id"], row["issue_id"],
            "import_reconciliation_stage", "import_reconciliation",
            f"Import reconciliation stage {stage} {status}",
            "problem" if status == "failed" else "productive" if status == "succeeded" else "retry_later",
            "problem" if status == "failed" else "importing", now, json_dumps(outcome),
        ),
    )
    return True


def record_import_reconciliation_stage(db_path, import_result_id, stage, *, status, error_code="", error_category="", now=None):
    """Append one bounded, privacy-safe stage outcome to durable import evidence."""
    with connect(db_path) as con:
        con.execute("begin immediate")
        return _record_import_reconciliation_stage(
            con, import_result_id, stage, status=status, error_code=error_code,
            error_category=error_category, now=now,
        )


def metadata_provider_key(value):
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")


def split_prefixed_identity(value):
    value = str(value or "").strip()
    if ":" not in value:
        return "", ""
    provider, raw_id = value.split(":", 1)
    provider = metadata_provider_key(provider)
    raw_id = str(raw_id or "").strip()
    if not provider or not raw_id:
        return "", ""
    return provider, raw_id


def metadata_identity(row):
    row = row if isinstance(row, dict) else {}
    provider = metadata_provider_key(row.get("metadataProvider") or row.get("metadata_provider"))
    metadata_id = row.get("metadataId") or row.get("metadata_id")
    issue_provider = metadata_provider_key(
        row.get("issue_metadata_provider")
        or row.get("issueProvider")
        or row.get("issue_metadataProvider")
    )
    issue_metadata_id = (
        row.get("issue_metadata_id")
        or row.get("issueMetadataId")
        or row.get("issue_metadataId")
    )
    if not provider and not metadata_id:
        for value in (
            row.get("native_series_id"),
            row.get("inkdrop_series_id"),
            row.get("series_id"),
            row.get("seriesId"),
            row.get("comicvine_series_id"),
            row.get("mangadex_series_id"),
            row.get("native_issue_id"),
            row.get("inkdrop_issue_id"),
            issue_metadata_id,
            row.get("issue_id"),
            row.get("issueId"),
            row.get("mangadex_chapter_id"),
            row.get("chapterId"),
            row.get("chapter_id"),
        ):
            candidate_provider, candidate_id = split_prefixed_identity(value)
            if candidate_provider and candidate_id:
                provider = candidate_provider
                metadata_id = candidate_id
                break
    if not metadata_id and issue_provider == provider:
        metadata_id = issue_metadata_id
    if not provider and issue_provider:
        provider = issue_provider
        if not metadata_id:
            metadata_id = issue_metadata_id
    for field, key in (
        ("comicvineId", "comicvine"),
        ("comicvine_id", "comicvine"),
        ("mangadexId", "mangadex"),
        ("mangadex_id", "mangadex"),
        ("issue_metadata_id", issue_provider),
        ("issueMetadataId", issue_provider),
        ("issue_metadataId", issue_provider),
        ("issueId", issue_provider),
        ("id", issue_provider),
        ("comicvine_issue_id", "comicvine"),
        ("mangadex_chapter_id", "mangadex"),
    ):
        value = row.get(field)
        if value in (None, ""):
            continue
        if not key:
            continue
        if not provider:
            provider = key
        if not metadata_id and provider == key:
            metadata_id = value
    return provider, metadata_id


def series_identity(row):
    provider, metadata_id = metadata_identity(row)
    if provider and metadata_id not in (None, ""):
        return f"{provider}:{metadata_id}"
    kapowarr_id = row.get("kapowarrId") or row.get("kapowarr_id")
    if kapowarr_id not in (None, ""):
        return f"kapowarr:{kapowarr_id}"
    return f"title:{normalize_key(row.get('name') or row.get('series') or row.get('title'))}"


def series_raw_user_removed(raw):
    raw = raw if isinstance(raw, dict) else {}
    return bool(raw.get("removed_by_user")) or str(raw.get("automation_parked_reason") or "") == "user_removed"


def series_row_user_removed(row):
    if not row:
        return False
    raw = json_loads(row_value(row, "raw_json") or "{}", {})
    return series_raw_user_removed(raw if isinstance(raw, dict) else {})


def series_id_user_removed(con, series_id):
    series_id = str(series_id or "").strip()
    if not series_id:
        return False
    row = con.execute("select raw_json from series where id=? limit 1", (series_id,)).fetchone()
    return series_row_user_removed(row)


def removed_series_guard_raw(raw, now, message=None, source="inkdrop_state"):
    raw = raw if isinstance(raw, dict) else {}
    raw.update(
        {
            "series_removed_guard": True,
            "series_removed_guard_source": source,
            "series_removed_guard_message": message or REMOVED_SERIES_MESSAGE,
            "series_removed_guard_at": now,
            "series_removed_guard_at_iso": utc_stamp(now),
        }
    )
    return raw


def retire_removed_series_work(con, series_id, now=None, message=None, source="inkdrop_state"):
    series_id = str(series_id or "").strip()
    if not series_id or not series_id_user_removed(con, series_id):
        return {"series_removed": False, "queue_retired": 0, "wanted_inactivated": 0}
    now = float(now or time.time())
    message = str(message or REMOVED_SERIES_MESSAGE).strip() or REMOVED_SERIES_MESSAGE
    queue_rows = con.execute(
        f"""
        select id, state, last_event, raw_json
        from queue_items
        where series_id=?
          and (
            active=1
            or state in ({",".join("?" for _ in REMOVED_SERIES_ACTIVE_QUEUE_STATES)})
          )
        """,
        (series_id, *REMOVED_SERIES_ACTIVE_QUEUE_STATES),
    ).fetchall()
    queue_retired = 0
    for row in queue_rows:
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = removed_series_guard_raw(raw if isinstance(raw, dict) else {}, now, message, source)
        raw.update(
            {
                "previous_state": row["state"],
                "previous_event": row["last_event"],
                "parked_reason": "user_removed",
                "parked_at": now,
                "parked_at_iso": utc_stamp(now),
            }
        )
        cur = con.execute(
            """
            update queue_items
            set state='stale_source_absent',
                current_source=null,
                last_event=?,
                active=0,
                updated_at=?,
                retry_after=null,
                retry_after_iso=null,
                outcome='stale_source_absent',
                display_phase='retired',
                provider_status_state='historical',
                provider_status_phase='retired',
                provider_status_provider=coalesce(nullif(provider_status_provider, ''), 'series_removed'),
                provider_status_actionability='historical',
                raw_json=?
            where id=?
            """,
            (message, now, json_dumps(raw), row["id"]),
        )
        queue_retired += int(cur.rowcount or 0)
    wanted_cur = con.execute(
        f"""
        update wanted_items
        set status='inactive', updated_at=?
        where series_id=?
          and status in ({",".join("?" for _ in REMOVED_SERIES_ACTIVE_WANTED_STATUSES)})
        """,
        (now, series_id, *REMOVED_SERIES_ACTIVE_WANTED_STATUSES),
    )
    return {
        "series_removed": True,
        "queue_retired": queue_retired,
        "wanted_inactivated": int(wanted_cur.rowcount or 0),
    }


def retire_all_removed_series_work(con, now=None, source="inkdrop_state"):
    now = float(now or time.time())
    totals = {"removed_series": 0, "queue_retired": 0, "wanted_inactivated": 0}
    rows = con.execute("select id, raw_json from series").fetchall()
    for row in rows:
        if not series_row_user_removed(row):
            continue
        totals["removed_series"] += 1
        result = retire_removed_series_work(con, row["id"], now, source=source)
        totals["queue_retired"] += int(result.get("queue_retired") or 0)
        totals["wanted_inactivated"] += int(result.get("wanted_inactivated") or 0)
    return totals


def series_raw_removed_or_parked(raw):
    raw = raw if isinstance(raw, dict) else {}
    reason = str(raw.get("automation_parked_reason") or "").strip().lower()
    return bool(raw.get("removed_by_user")) or reason in SERIES_REMOVED_PARK_REASONS


def series_row_allows_removed_reactivation(row):
    if not isinstance(row, dict):
        return False
    return bool(
        row.get("inkdrop_explicit_user_add")
        or row.get("explicit_user_add")
        or row.get("inkdropUserAdded")
        or row.get("createdBy") == "inkdrop_add_series"
    )


class SeriesIdentityTombstoneBlocked(RuntimeError):
    def __init__(self, result):
        self.result = dict(result or {})
        super().__init__(self.result.get("reason") or "series_identity_tombstone_blocked")


def series_identity_tombstone_resolution(con, row, proposed_series_id):
    proposed_series_id = str(proposed_series_id or "").strip()
    proposed_provider, proposed_metadata_id = split_prefixed_identity(proposed_series_id)
    if proposed_provider not in {"title", "kapowarr", "manual", "watch"}:
        return None
    title = row_value(row, "name") or row_value(row, "series") or row_value(row, "title")
    title_key = normalize_key(title)
    if not title_key:
        return None
    rows = con.execute(
        """
        select id, title, year, publisher, metadata_provider, metadata_id, kapowarr_id, raw_json
        from series
        where sort_title=?
        order by id
        """,
        (title_key,),
    ).fetchall()
    removed = [candidate for candidate in rows if series_row_user_removed(candidate)]
    if not removed:
        return None
    active = [candidate for candidate in rows if not series_row_user_removed(candidate)]
    base = {
        "proposed_series_id": proposed_series_id,
        "proposed_identity_provider": proposed_provider,
        "proposed_identity_id": proposed_metadata_id,
        "title": str(title or ""),
        "normalized_title": title_key,
        "removed_candidate_ids": [str(candidate["id"] or "") for candidate in removed],
        "active_conflict_ids": [str(candidate["id"] or "") for candidate in active],
    }
    if len(removed) != 1 or active:
        return {**base, "action": "blocked", "reason": "removed_series_title_ambiguous"}
    candidate = removed[0]
    incoming_year = str(row_value(row, "year") or row_value(row, "watch_year") or "").strip()
    candidate_year = str(candidate["year"] or "").strip()
    if incoming_year and candidate_year and incoming_year != candidate_year:
        return {**base, "action": "blocked", "reason": "removed_series_year_conflict"}
    incoming_publisher = normalize_key(row_value(row, "publisher") or row_value(row, "watch_publisher"))
    candidate_publisher = normalize_key(candidate["publisher"])
    if incoming_publisher and candidate_publisher and incoming_publisher != candidate_publisher:
        return {**base, "action": "blocked", "reason": "removed_series_publisher_conflict"}
    incoming_kapowarr_id = str(
        row_value(row, "kapowarrId")
        or row_value(row, "kapowarr_id")
        or (proposed_metadata_id if proposed_provider == "kapowarr" else "")
        or ""
    ).strip()
    candidate_provider = metadata_provider_key(candidate["metadata_provider"])
    candidate_kapowarr_id = str(
        candidate["kapowarr_id"]
        or (candidate["metadata_id"] if candidate_provider == "kapowarr" else "")
        or ""
    ).strip()
    if incoming_kapowarr_id and candidate_kapowarr_id and incoming_kapowarr_id != candidate_kapowarr_id:
        return {**base, "action": "blocked", "reason": "removed_series_kapowarr_id_conflict"}
    incoming_provider = metadata_provider_key(
        row_value(row, "metadataProvider")
        or row_value(row, "metadata_provider")
        or (
            row_value(row, "source")
            if metadata_provider_key(row_value(row, "source")) in {"comicvine", "mangadex"}
            else ""
        )
    )
    if incoming_provider in {"kapowarr", "manual", "watch"}:
        incoming_provider = ""
    if incoming_provider and candidate_provider and incoming_provider != candidate_provider:
        return {**base, "action": "blocked", "reason": "removed_series_provider_conflict"}
    return {
        **base,
        "action": "alias_removed_canonical",
        "reason": "removed_series_legacy_alias",
        "series_id": str(candidate["id"] or ""),
        "metadata_provider": candidate_provider,
        "metadata_id": str(candidate["metadata_id"] or ""),
    }


def _first_text(*values):
    for value in values:
        text = str(value or "").strip()
        if text:
            return text
    return ""


def sanitize_path_component(value):
    value = str(value or "").strip().replace("\\", "/").strip()
    if not value:
        return ""
    value = re.sub(r"[\\/:*?\"<>|]", "-", value)
    value = re.sub(r"\s+", " ", value).strip()
    value = value.replace("/", "-").replace("\\", "-")
    value = re.sub(r"-{2,}", "-", value)
    return value or "Unknown"


def _app_setting_value_from_connection(con, key, default=None):
    if con is None:
        return default
    try:
        row = con.execute("select value_json from app_settings where key = ?", (key,)).fetchone()
    except Exception:
        return default
    if not row:
        return default
    raw = row["value_json"] if hasattr(row, "keys") else row[0]
    try:
        value = json.loads(raw or "null")
    except Exception:
        value = raw
    if value is None or str(value).strip() == "":
        return default
    return value


def managed_duplicate_quarantine_root_from_connection(con=None, *, db_path=None, override=None):
    explicit = str(override or "").strip()
    if explicit:
        return explicit
    env_value = str(os.environ.get(MANAGED_DUPLICATE_QUARANTINE_ENV) or "").strip()
    if env_value:
        return env_value
    if con is not None:
        for key in MANAGED_DUPLICATE_QUARANTINE_SETTING_KEYS:
            value = str(_app_setting_value_from_connection(con, key, "") or "").strip()
            if value:
                return value
    if db_path:
        try:
            with connect(db_path, timeout_seconds=5.0, busy_timeout_ms=5000) as setting_con:
                for key in MANAGED_DUPLICATE_QUARANTINE_SETTING_KEYS:
                    value = str(_app_setting_value_from_connection(setting_con, key, "") or "").strip()
                    if value:
                        return value
        except Exception:
            pass
    return DEFAULT_MANAGED_DUPLICATE_QUARANTINE_ROOT


def normalized_media_type(value):
    media = str(value or "").strip().lower()
    if media in MANGA_MEDIA_TYPES:
        return "manga"
    if media in {"comic", "comics", "graphic_novel", "graphic novel"}:
        return "comic"
    if media in {"ebook", "book", "novel"}:
        return "ebook"
    return media or ""


def publisher_manga_hint(publisher):
    publisher_key = normalize_key(publisher)
    if not publisher_key:
        return ""
    for hint in sorted(MANGA_PUBLISHER_HINTS, key=len, reverse=True):
        hint_key = normalize_key(hint)
        if publisher_key == hint_key or hint_key in publisher_key:
            return hint
    return ""


def title_manga_hint(title):
    title_key = normalize_key(title)
    if not title_key:
        return ""
    compact = title_key.replace(" ", "")
    for hint in MANGA_TITLE_HINTS:
        hint_key = normalize_key(hint)
        if title_key == hint_key or compact == hint_key.replace(" ", ""):
            return hint
    return ""


def native_series_media_decision(row, provider=None):
    provider_key = metadata_provider_key(
        provider
        or row_value(row, "metadataProvider")
        or row_value(row, "metadata_provider")
        or row_value(row, "source")
    )
    explicit = normalized_media_type(row_value(row, "mediaType") or row_value(row, "media_type"))
    if provider_key == "mangadex" or row_value(row, "mangadexId") or row_value(row, "mangadex_id"):
        return {"media_type": "manga", "source": "provider", "reason": "mangadex_provider"}
    if explicit and explicit != "comic":
        return {"media_type": explicit, "source": "explicit", "reason": "explicit_media_type"}
    publisher = row_value(row, "publisher") or row_value(row, "watch_publisher")
    publisher_hint = publisher_manga_hint(publisher)
    if publisher_hint:
        return {
            "media_type": "manga",
            "source": "metadata_hint",
            "reason": "publisher_hint",
            "hint": publisher_hint,
        }
    title = row_value(row, "name") or row_value(row, "series") or row_value(row, "title")
    title_hint = title_manga_hint(title)
    if title_hint:
        return {
            "media_type": "manga",
            "source": "metadata_hint",
            "reason": "title_hint",
            "hint": title_hint,
        }
    return {"media_type": explicit or "comic", "source": "default", "reason": "default_comic"}


def default_library_root_for_media_type(media_type, con=None):
    media = str(media_type or "").strip().lower()
    if media in MANGA_MEDIA_TYPES:
        return str(
            _app_setting_value_from_connection(
                con,
                "media_management.manga_root",
                _app_setting_value_from_connection(con, "path.manga_root", DEFAULT_LIBRARY_ROOTS["manga"]),
            )
        )
    if media == "comic":
        return str(
            _app_setting_value_from_connection(
                con,
                "media_management.comic_root",
                _app_setting_value_from_connection(con, "path.comic_root", DEFAULT_LIBRARY_ROOTS["comic"]),
            )
        )
    return DEFAULT_LIBRARY_ROOTS.get(media, DEFAULT_LIBRARY_ROOT_FALLBACK)


def has_path_contract_values(row):
    if not row:
        return False
    for key in ("library_root", "library_path", "library_path_template", "library_path_source", "library_adapter_path"):
        if str(row_value(row, key, "" ) or "") not in ("",):
            return True
    return False


def native_series_path_contract(row, *, media_type=None, con=None, prefer_existing_root=True):
    media_type = media_type or native_series_media_decision(row).get("media_type")
    root_values = []
    if prefer_existing_root:
        root_values.extend(
            [
                row_value(row, "libraryRoot"),
                row_value(row, "library_root"),
                row_value(row, "rootFolder"),
                row_value(row, "root_folder"),
            ]
        )
    root_values.append(default_library_root_for_media_type(media_type, con=con))
    root = _first_text(*root_values)
    if not root:
        return None
    series_title = row_value(row, "name") or row_value(row, "series") or row_value(row, "title")
    series_year = row_value(row, "series_year") or row_value(row, "year")
    series_format = "{Series Title}"
    replace_illegal = True
    colon_replacement = "smart"
    try:
        series_format = str(
            _app_setting_value_from_connection(
                con,
                "media_management.series_folder_format",
                _app_setting_value_from_connection(con, "media_management.series_folder_format", "{Series Title} ({Year})"),
            )
            or "{Series Title} ({Year})"
        )
        replace_illegal = boolish(
            _app_setting_value_from_connection(con, "media_management.replace_illegal_characters", True),
            True,
        )
        colon_replacement = str(_app_setting_value_from_connection(con, "media_management.colon_replacement", "smart") or "smart")
    except Exception:
        series_format = "{Series Title} ({Year})" if series_year not in (None, "") else "{Series Title}"
    if series_year in (None, "") and "{Year}" in series_format:
        series_format = series_format.replace(" ({Year})", "").replace("{Year}", "").strip() or "{Series Title}"
    try:
        raw_segment = media_management_format_template(
            series_format,
            {
                "series_title": series_title,
                "year": series_year,
                "series_year": series_year,
            },
        )
        segment = media_management_sanitize_component(
            raw_segment,
            replace_illegal=replace_illegal,
            colon_replacement=colon_replacement,
        )
    except Exception:
        segment = sanitize_path_component(series_title)
    if not segment:
        return None
    root = root.rstrip("/")
    return {
        "library_root": root,
        "library_path": f"{root}/{segment}",
        "library_path_template": series_format,
        "library_path_source": "inkdrop",
        "library_adapter_path": None,
    }


def _path_has_prefix(path, prefix):
    path = str(path or "").replace("\\", "/").rstrip("/")
    prefix = str(prefix or "").replace("\\", "/").rstrip("/")
    return bool(path == prefix or path.startswith(prefix + "/"))


def media_management_roots_from_connection(con):
    roots = []
    seen = set()
    for setting_key, fallback_key, default in (
        ("media_management.comic_root", "path.comic_root", DEFAULT_LIBRARY_ROOTS["comic"]),
        ("media_management.manga_root", "path.manga_root", DEFAULT_LIBRARY_ROOTS["manga"]),
    ):
        value = _app_setting_value_from_connection(
            con,
            setting_key,
            _app_setting_value_from_connection(con, fallback_key, default),
        )
        root = str(value or default or "").replace("\\", "/").rstrip("/")
        if not root or root in seen:
            continue
        seen.add(root)
        roots.append(root)
    return roots


def path_under_any_root(path, roots):
    return any(_path_has_prefix(path, root) for root in roots or [])


def path_exists_quietly(path):
    path = str(path or "").strip()
    if not path:
        return False
    try:
        return Path(path).exists()
    except OSError:
        return False


def import_result_managed_dest_path_exists(con, dest_path, managed_roots=None):
    dest_path = str(dest_path or "").strip()
    if not dest_path:
        return False
    roots = managed_roots if managed_roots is not None else media_management_roots_from_connection(con)
    if roots and not path_under_any_root(dest_path, roots):
        return False
    return path_exists_quietly(dest_path)


def canonical_managed_media_file_path(dest_path, managed_roots):
    """Return a canonical regular media file contained by an existing managed root."""
    text = str(dest_path or "").strip()
    roots = [str(root or "").strip() for root in (managed_roots or []) if str(root or "").strip()]
    if not text or not roots:
        return None
    try:
        candidate = Path(text).resolve(strict=True)
    except (OSError, RuntimeError):
        return None
    if not candidate.is_file() or not media_library_archive_extension(candidate.name):
        return None
    for root in roots:
        try:
            canonical_root = Path(root).resolve(strict=True)
        except (OSError, RuntimeError):
            continue
        if canonical_root.is_dir() and canonical_root in candidate.parents:
            return candidate
    return None


def media_file_normalized_path(path):
    text = str(path or "").strip().replace("\\", "/")
    if not text:
        return ""
    text = re.sub(r"/+", "/", text)
    if re.match(r"^[a-zA-Z]:/", text):
        text = text[0].lower() + text[1:]
    return text.rstrip("/")


def media_file_path_snapshot(path):
    text = str(path or "").strip()
    if not text:
        return {"exists": False, "size_bytes": None, "mtime": None}
    try:
        p = Path(text)
        if not p.exists():
            return {"exists": False, "size_bytes": None, "mtime": None}
        stat = p.stat()
        return {"exists": True, "size_bytes": int(stat.st_size), "mtime": float(stat.st_mtime)}
    except OSError:
        return {"exists": False, "size_bytes": None, "mtime": None}


def media_file_sha256(path, max_bytes=512 * 1024 * 1024):
    text = str(path or "").strip()
    try:
        max_bytes = max(1, int(max_bytes or 512 * 1024 * 1024))
    except (TypeError, ValueError):
        max_bytes = 512 * 1024 * 1024
    if not text:
        return {"ok": False, "skipped": True, "reason": "missing_path"}
    try:
        file_path = Path(text)
        stat = file_path.stat()
        size = int(stat.st_size)
        if size > max_bytes:
            return {
                "ok": False,
                "skipped": True,
                "reason": "file_too_large",
                "size_bytes": size,
                "max_bytes": max_bytes,
            }
        digest = hashlib.sha256()
        with file_path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return {
            "ok": True,
            "skipped": False,
            "sha256": digest.hexdigest(),
            "size_bytes": size,
            "max_bytes": max_bytes,
        }
    except OSError as exc:
        return {
            "ok": False,
            "skipped": True,
            "reason": "hash_read_failed",
            "error": str(exc),
            "max_bytes": max_bytes,
        }


def media_type_for_managed_file_path(con, path, fallback=None):
    media = normalized_media_type(fallback)
    if media:
        return media
    normalized = media_file_normalized_path(path)
    manga_root = media_file_normalized_path(
        _app_setting_value_from_connection(con, "media_management.manga_root",
            _app_setting_value_from_connection(con, "path.manga_root", DEFAULT_LIBRARY_ROOTS["manga"]))
    )
    comic_root = media_file_normalized_path(
        _app_setting_value_from_connection(con, "media_management.comic_root",
            _app_setting_value_from_connection(con, "path.comic_root", DEFAULT_LIBRARY_ROOTS["comic"]))
    )
    if manga_root and _path_has_prefix(normalized, manga_root):
        return "manga"
    if comic_root and _path_has_prefix(normalized, comic_root):
        return "comic"
    return media or ""


def sync_managed_media_files(con, now=None, limit=5000):
    now = float(now or time.time())
    limit = max(1, min(int(limit or 5000), 50000))
    roots = media_management_roots_from_connection(con)
    normalized_roots = [media_file_normalized_path(root) for root in roots if media_file_normalized_path(root)]
    if not normalized_roots:
        return {"observed": 0, "present": 0, "missing": 0, "skipped": 0}
    rows = con.execute(
        """
        select ir.id, ir.queue_id, ir.source_attempt_id, ir.series_id, ir.issue_id,
               ir.source_path, ir.dest_path, ir.status, ir.verified, ir.outcome,
               ir.display_phase, ir.completion_truth, ir.folder_imported,
               ir.library_visibility_status, ir.library_visibility_provider,
               ir.created_at, ir.raw_json,
               s.title as series_title, s.media_type as series_media_type,
               i.issue_number as issue_number, i.normalized_number as normalized_number,
               q.wanted_id as queue_wanted_id
        from import_results ir
        left join series s on s.id = ir.series_id
        left join issues i on i.id = ir.issue_id
        left join queue_items q on q.id = ir.queue_id
        where coalesce(ir.dest_path, '') != ''
          and (
            coalesce(ir.verified, 0) = 1
            or coalesce(ir.folder_imported, 0) = 1
            or lower(coalesce(ir.completion_truth, '')) = 'folder'
            or lower(coalesce(ir.library_visibility_status, '')) = 'library_visible'
            or lower(coalesce(ir.status, '')) in (
                'folder_verified', 'library_visible', 'verified',
                'imported', 'skipped_existing', 'waiting_for_library_scan',
                'library_scan_timeout', 'waiting_for_kavita_scan', 'kavita_scan_timeout'
            )
          )
        order by coalesce(ir.created_at, 0) desc, ir.id desc
        limit ?
        """,
        (limit,),
    ).fetchall()
    observed = 0
    present = 0
    missing = 0
    skipped = 0
    for row in rows:
        dest_path = str(row["dest_path"] or "").strip()
        normalized_path = media_file_normalized_path(dest_path)
        if not normalized_path or not path_under_any_root(normalized_path, normalized_roots):
            skipped += 1
            continue
        snapshot = media_file_path_snapshot(dest_path)
        exists = bool(snapshot["exists"])
        status = "present" if exists else "missing"
        active = 1 if exists else 0
        media_type = media_type_for_managed_file_path(con, dest_path, row["series_media_type"])
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        payload = {
            "import_result_id": row["id"],
            "queue_id": row["queue_id"],
            "wanted_id": row["queue_wanted_id"],
            "source_attempt_id": row["source_attempt_id"],
            "series_id": row["series_id"],
            "series_title": row["series_title"],
            "issue_id": row["issue_id"],
            "issue_number": row["issue_number"],
            "normalized_number": row["normalized_number"],
            "source_path": row["source_path"],
            "dest_path": dest_path,
            "normalized_path": normalized_path,
            "status": status,
            "completion_truth": row["completion_truth"],
            "folder_imported": bool(row["folder_imported"]),
            "library_visibility_status": row["library_visibility_status"],
            "library_visibility_provider": row["library_visibility_provider"],
            "import_status": row["status"],
            "import_verified": bool(row["verified"]),
            "import_outcome": row["outcome"],
            "import_display_phase": row["display_phase"],
            "size_bytes": snapshot["size_bytes"],
            "mtime": snapshot["mtime"],
            "observed_at": now,
            "observed_at_iso": utc_stamp(now),
            "import_raw": raw,
        }
        media_id = stable_id("media_file", normalized_path)
        con.execute(
            """
            insert into media_files(
                id, path, normalized_path, media_type, series_id, issue_id, queue_id,
                import_result_id, source_path, status, active, completion_truth,
                folder_imported, size_bytes, mtime, first_seen_at, last_seen_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(normalized_path) do update set
                path=excluded.path,
                media_type=coalesce(nullif(excluded.media_type, ''), media_files.media_type),
                series_id=excluded.series_id,
                issue_id=excluded.issue_id,
                queue_id=excluded.queue_id,
                import_result_id=excluded.import_result_id,
                source_path=excluded.source_path,
                status=excluded.status,
                active=excluded.active,
                completion_truth=excluded.completion_truth,
                folder_imported=excluded.folder_imported,
                size_bytes=excluded.size_bytes,
                mtime=excluded.mtime,
                last_seen_at=excluded.last_seen_at,
                raw_json=excluded.raw_json
            """,
            (
                media_id,
                dest_path,
                normalized_path,
                media_type,
                row["series_id"],
                row["issue_id"],
                row["queue_id"],
                row["id"],
                row["source_path"],
                status,
                active,
                row["completion_truth"],
                1 if row["folder_imported"] else 0,
                snapshot["size_bytes"],
                snapshot["mtime"],
                now,
                now,
                json_dumps(payload),
            ),
        )
        observed += 1
        if exists:
            present += 1
        else:
            missing += 1
    return {"observed": observed, "present": present, "missing": missing, "skipped": skipped}


def media_file_inventory_rollup(con):
    if not table_exists(con, "media_files"):
        return {
            "media_files": 0,
            "media_files_active": 0,
            "media_files_missing": 0,
            "media_files_by_status": {},
            "media_files_by_type": {},
        }
    by_status = {
        str(row["key"] or "unknown"): int(row["count"] or 0)
        for row in con.execute(
            """
            select coalesce(nullif(status, ''), 'unknown') as key, count(*) as count
            from media_files
            group by key
            """
        )
    }
    by_type = {
        str(row["key"] or "unknown"): int(row["count"] or 0)
        for row in con.execute(
            """
            select coalesce(nullif(media_type, ''), 'unknown') as key, count(*) as count
            from media_files
            where active=1
            group by key
            """
        )
    }
    return {
        "media_files": table_count(con, "media_files"),
        "media_files_active": table_count(con, "media_files", "where active=1"),
        "media_files_missing": int(by_status.get("missing") or 0),
        "media_files_by_status": by_status,
        "media_files_by_type": by_type,
    }


def media_file_inventory_rows(db_path, limit=100, include_missing=True):
    path = Path(db_path)
    if not path.exists():
        return []
    limit = max(1, min(int(limit or 100), 5000))
    where = "" if include_missing else "where active=1"
    with connect(path) as con:
        init_schema(con)
        rows = con.execute(
            f"""
            select mf.*, s.title as series_title, i.issue_number as issue_number
            from media_files mf
            left join series s on s.id = mf.series_id
            left join issues i on i.id = mf.issue_id
            {where}
            order by active desc, last_seen_at desc, path asc
            limit ?
            """,
            (limit,),
        ).fetchall()
        out = []
        for row in rows:
            item = dict(row)
            item["raw"] = json_loads(item.pop("raw_json", None) or "{}", {})
            out.append(item)
        return out


def media_library_archive_extension(path):
    name = str(path or "").strip().lower()
    for suffix in MEDIA_LIBRARY_ARCHIVE_COMPOUND_EXTENSIONS:
        if name.endswith(suffix):
            return suffix
    ext = Path(name).suffix.lower()
    return ext if ext in MEDIA_LIBRARY_ARCHIVE_EXTENSIONS else ""


def media_library_duplicate_stem(path):
    name = Path(str(path or "")).name
    lower_name = name.lower()
    suffix = media_library_archive_extension(name)
    stem = name[: -len(suffix)] if suffix and lower_name.endswith(suffix) else Path(name).stem
    stem = re.sub(r"\s+\(\d{1,3}\)$", "", stem)
    stem = re.sub(r"\s+-\s+copy(?:\s+\d+)?$", "", stem, flags=re.IGNORECASE)
    stem = re.sub(r"\s+copy(?:\s+\d+)?$", "", stem, flags=re.IGNORECASE)
    return normalize_key(stem)


def media_library_duplicate_copy_marker(path):
    name = Path(str(path or "")).name
    lower_name = name.lower()
    suffix = media_library_archive_extension(name)
    stem = name[: -len(suffix)] if suffix and lower_name.endswith(suffix) else Path(name).stem
    if re.search(r"\s+\(\d{1,3}\)$", stem):
        return "numbered_copy_suffix"
    if re.search(r"\s+-\s+copy(?:\s+\d+)?$", stem, flags=re.IGNORECASE):
        return "dash_copy_suffix"
    if re.search(r"\s+copy(?:\s+\d+)?$", stem, flags=re.IGNORECASE):
        return "copy_suffix"
    return ""


def managed_root_entries_from_connection(con):
    entries = []
    for media_type, setting_key, fallback_key, default in (
        ("comic", "media_management.comic_root", "path.comic_root", DEFAULT_LIBRARY_ROOTS["comic"]),
        ("manga", "media_management.manga_root", "path.manga_root", DEFAULT_LIBRARY_ROOTS["manga"]),
    ):
        root = str(
            _app_setting_value_from_connection(
                con,
                setting_key,
                _app_setting_value_from_connection(con, fallback_key, default),
            )
            or default
            or ""
        ).strip()
        normalized = media_file_normalized_path(root)
        if not normalized:
            continue
        entries.append({"media_type": media_type, "root": root, "normalized_root": normalized})
    return entries


def managed_library_file_duplicate_key(path, media_type, root):
    path_text = str(path or "").replace("\\", "/")
    root_text = str(root or "").replace("\\", "/").rstrip("/")
    try:
        rel = Path(path_text).relative_to(Path(root_text)).as_posix()
    except ValueError:
        rel = path_text[len(root_text):].lstrip("/") if root_text and _path_has_prefix(path_text, root_text) else path_text
    parent = str(Path(rel).parent).replace("\\", "/")
    if parent == ".":
        parent = ""
    return "|".join(
        (
            str(media_type or ""),
            normalize_key(parent),
            media_library_duplicate_stem(path_text),
            media_library_archive_extension(path_text),
        )
    )


def managed_library_scan_files(con, max_files=50000, sample_limit=50):
    max_files = max(1, min(int(max_files or 50000), 250000))
    sample_limit = max(0, min(int(sample_limit or 50), 500))
    roots = managed_root_entries_from_connection(con)
    files = []
    root_summaries = []
    truncated = False
    errors = []
    for entry in roots:
        root = Path(entry["root"])
        root_summary = {
            "root": str(root),
            "media_type": entry["media_type"],
            "exists": root.exists(),
            "files": 0,
            "errors": [],
        }
        if not root_summary["exists"]:
            root_summary["error"] = "root_missing"
            root_summaries.append(root_summary)
            continue
        for current_root, dirnames, filenames in os.walk(root):
            dirnames[:] = [
                name
                for name in dirnames
                if name.lower() not in MEDIA_LIBRARY_SCAN_SKIP_DIRS and not name.startswith(".")
            ]
            for filename in filenames:
                if len(files) >= max_files:
                    truncated = True
                    break
                candidate = Path(current_root) / filename
                suffix = media_library_archive_extension(candidate)
                if not suffix:
                    continue
                snapshot = media_file_path_snapshot(candidate)
                normalized_path = media_file_normalized_path(candidate)
                duplicate_key = managed_library_file_duplicate_key(candidate, entry["media_type"], root)
                files.append(
                    {
                        "path": str(candidate),
                        "normalized_path": normalized_path,
                        "media_type": entry["media_type"],
                        "root": str(root),
                        "extension": suffix,
                        "size_bytes": snapshot["size_bytes"],
                        "mtime": snapshot["mtime"],
                        "duplicate_key": duplicate_key,
                    }
                )
                root_summary["files"] += 1
            if truncated:
                break
        root_summaries.append(root_summary)
        if truncated:
            break
    return {
        "files": files,
        "roots": root_summaries,
        "errors": errors,
        "truncated": truncated,
        "max_files": max_files,
        "sample_limit": sample_limit,
    }


def _library_import_series_summary(row):
    row = row if isinstance(row, dict) else dict(row or {})
    return {
        "id": row.get("id"),
        "title": row.get("title"),
        "media_type": row.get("media_type"),
        "year": row.get("year"),
        "publisher": row.get("publisher"),
        "metadata_provider": row.get("metadata_provider"),
        "metadata_id": row.get("metadata_id"),
        "source": row.get("source"),
        "library_root": row.get("library_root"),
        "library_path": row.get("library_path"),
        "library_path_source": row.get("library_path_source"),
        "monitored": bool(int(row.get("monitored") or 0)),
        "monitor_new": bool(int(row.get("monitor_new") or 0)),
        "auto_grab": bool(int(row.get("auto_grab") or 0)),
    }


def _library_import_series_indexes(con):
    if not table_exists(con, "series"):
        return {}, {}
    rows = [
        dict(row)
        for row in con.execute(
            """
            select id, title, media_type, year, publisher, metadata_provider, metadata_id,
                   source, library_root, library_path, library_path_source,
                   monitored, monitor_new, auto_grab
            from series
            """
        )
    ]
    by_path = {}
    by_title = {}
    for row in rows:
        path_key = media_file_normalized_path(row.get("library_path"))
        if path_key:
            by_path.setdefault(path_key, []).append(row)
        title_key = normalize_key(row.get("title"))
        if title_key:
            media_type = str(row.get("media_type") or "").strip().lower()
            by_title.setdefault((media_type, title_key), []).append(row)
            by_title.setdefault(("", title_key), []).append(row)
    return by_path, by_title


def _library_import_top_level_folder(file_path, root_path):
    file_text = str(file_path or "").replace("\\", "/")
    root_text = str(root_path or "").replace("\\", "/").rstrip("/")
    if not file_text or not root_text:
        return "", "", "outside_root"
    try:
        rel = Path(file_text).relative_to(Path(root_text))
    except ValueError:
        if not _path_has_prefix(file_text, root_text):
            return "", "", "outside_root"
        rel = Path(file_text[len(root_text):].lstrip("/"))
    parts = [part for part in rel.parts if str(part or "") not in {"", "."}]
    if len(parts) <= 1:
        return str(Path(root_text)), "", "root_file"
    folder = Path(root_text) / parts[0]
    return str(folder), str(parts[0]), ""


def _library_import_root_summary(root):
    summary = dict(root or {})
    try:
        if summary.get("exists"):
            usage = shutil.disk_usage(summary.get("root"))
            summary["free_bytes"] = int(usage.free)
            summary["total_bytes"] = int(usage.total)
    except (OSError, TypeError, ValueError):
        pass
    return summary


def managed_library_import_plan_from_connection(con, *, max_files=50000, sample_limit=50):
    scan = managed_library_scan_files(con, max_files=max_files, sample_limit=sample_limit)
    sample_limit = max(0, min(int(sample_limit or 50), 500))
    series_by_path, series_by_title = _library_import_series_indexes(con)
    grouped = {}
    for row in scan["files"]:
        folder_path, folder_name, reason = _library_import_top_level_folder(row.get("path"), row.get("root"))
        if not folder_path:
            folder_path = str(row.get("root") or "")
        if not folder_name:
            folder_name = Path(str(row.get("path") or "")).stem if reason == "root_file" else Path(folder_path).name
        group_key = "|".join(
            (
                str(row.get("media_type") or ""),
                media_file_normalized_path(row.get("root")),
                media_file_normalized_path(folder_path),
                reason,
            )
        )
        group = grouped.setdefault(
            group_key,
            {
                "media_type": row.get("media_type"),
                "root": row.get("root"),
                "folder_path": folder_path,
                "normalized_folder_path": media_file_normalized_path(folder_path),
                "folder_name": folder_name,
                "reason": reason,
                "files": [],
                "extensions": {},
                "total_size_bytes": 0,
            },
        )
        group["files"].append(row)
        group["extensions"][row.get("extension") or ""] = group["extensions"].get(row.get("extension") or "", 0) + 1
        group["total_size_bytes"] += int(row.get("size_bytes") or 0)

    candidates = []
    summary = {
        "folders": 0,
        "mapped_existing_series": 0,
        "existing_series_folder_candidates": 0,
        "new_series_candidates": 0,
        "blocked": 0,
        "loose_root_files": 0,
        "archive_files": len(scan["files"]),
    }
    for group in sorted(grouped.values(), key=lambda item: (str(item.get("media_type") or ""), normalize_key(item.get("folder_name")), str(item.get("folder_path") or ""))):
        files = sorted(group.pop("files"), key=lambda item: str(item.get("path") or ""))
        folder_key = media_file_normalized_path(group.get("folder_path"))
        media_type = str(group.get("media_type") or "").strip().lower()
        folder_title_key = normalize_key(group.get("folder_name"))
        path_matches = [_library_import_series_summary(row) for row in series_by_path.get(folder_key, [])]
        title_matches = [
            _library_import_series_summary(row)
            for row in (series_by_title.get((media_type, folder_title_key), []) or series_by_title.get(("", folder_title_key), []))
        ]
        reason = str(group.get("reason") or "")
        if reason == "root_file":
            status = "root_file_requires_series_folder"
            action = "organize_into_series_folder"
            eligible = False
            summary["blocked"] += 1
            summary["loose_root_files"] += len(files)
        elif path_matches:
            status = "mapped_existing_series"
            action = "already_imported"
            eligible = False
            summary["mapped_existing_series"] += 1
        elif title_matches:
            status = "existing_series_folder_candidate"
            action = "attach_existing_series"
            eligible = True
            summary["existing_series_folder_candidates"] += 1
        else:
            status = "new_series_candidate"
            action = "add_series_from_folder"
            eligible = True
            summary["new_series_candidates"] += 1
        summary["folders"] += 1
        candidates.append(
            {
                "id": stable_id("library_import_candidate", group.get("media_type"), group.get("folder_path"), status),
                "media_type": group.get("media_type"),
                "root": group.get("root"),
                "folder_path": group.get("folder_path"),
                "normalized_folder_path": folder_key,
                "folder_name": group.get("folder_name"),
                "status": status,
                "action": action,
                "eligible": eligible,
                "archive_count": len(files),
                "total_size_bytes": int(group.get("total_size_bytes") or 0),
                "extensions": dict(sorted(group.get("extensions", {}).items())),
                "matched_series": path_matches[:5],
                "title_matches": title_matches[:5],
                "sample_files": files[:sample_limit],
            }
        )
    return {
        "ok": True,
        "schema": "inkdrop.library_import_plan.v1",
        "schema_version": 1,
        "checked_at": time.time(),
        "roots": [_library_import_root_summary(root) for root in scan["roots"]],
        "summary": summary,
        "candidates": candidates,
        "truncated": scan["truncated"],
        "max_files": scan["max_files"],
        "sample_limit": sample_limit,
    }


def managed_library_import_plan(db_path, *, max_files=50000, sample_limit=50):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    with connect_read(path, timeout_seconds=10, busy_timeout_ms=10000) as con:
        return managed_library_import_plan_from_connection(
            con,
            max_files=max_files,
            sample_limit=sample_limit,
        )


def media_file_ledger_index(con):
    if not table_exists(con, "media_files"):
        return {}
    return {
        str(row["normalized_path"] or ""): dict(row)
        for row in con.execute(
            """
            select id, path, normalized_path, media_type, series_id, issue_id, queue_id,
                   import_result_id, status, active, completion_truth, folder_imported,
                   size_bytes, mtime, last_seen_at
            from media_files
            """
        )
        if str(row["normalized_path"] or "")
    }


def classify_frontend_duplicate_group(
    *,
    provider,
    frontend_path,
    row_count,
    host_path,
    ledger_index,
    scanned_index,
    actual_duplicate_index,
):
    normalized_host = media_file_normalized_path(host_path)
    scanned = scanned_index.get(normalized_host) if normalized_host else None
    ledger = ledger_index.get(normalized_host) if normalized_host else None
    host_exists = bool(scanned) or path_exists_quietly(host_path)
    actual_duplicate_files = []
    duplicate_key = scanned.get("duplicate_key") if isinstance(scanned, dict) else ""
    if duplicate_key:
        actual_duplicate_files = [
            item["path"]
            for item in actual_duplicate_index.get(duplicate_key, [])
            if media_file_normalized_path(item.get("path")) != normalized_host
        ]
    if not host_exists:
        classification = "stale_frontend_duplicate"
        action = "frontend_scan_cleanup"
    elif actual_duplicate_files:
        classification = "real_duplicate_files_present"
        action = "review_or_quarantine_duplicate_files"
    else:
        classification = "frontend_only_duplicate"
        action = "frontend_database_cleanup_or_rescan"
    return {
        "provider": provider,
        "frontend_path": str(frontend_path or ""),
        "row_count": int(row_count or 0),
        "host_path": str(host_path or ""),
        "normalized_host_path": normalized_host,
        "host_exists": host_exists,
        "ledger_tracked": bool(ledger),
        "ledger_status": ledger.get("status") if isinstance(ledger, dict) else None,
        "actual_duplicate_files": actual_duplicate_files[:10],
        "actual_duplicate_file_count": len(actual_duplicate_files),
        "classification": classification,
        "next_action": action,
    }


def frontend_duplicate_classification_summary(rows):
    counts = {}
    for row in rows or []:
        key = str(row.get("classification") or "unknown")
        counts[key] = int(counts.get(key) or 0) + 1
    return counts


def kavita_duplicate_media_file_audit(
    state_con,
    *,
    kavita_db_path=None,
    ledger_index=None,
    scanned_index=None,
    actual_duplicate_index=None,
    limit=500,
):
    limit = max(1, min(int(limit or 500), 5000))
    path = Path(kavita_db_path or DEFAULT_KAVITA_DB)
    if not path.exists():
        return {
            "checked": False,
            "provider": "kavita",
            "path": str(path),
            "reason": "kavita_db_missing",
            "duplicates": [],
            "by_classification": {},
        }
    ledger_index = ledger_index if isinstance(ledger_index, dict) else media_file_ledger_index(state_con)
    scanned_index = scanned_index if isinstance(scanned_index, dict) else {}
    actual_duplicate_index = actual_duplicate_index if isinstance(actual_duplicate_index, dict) else {}
    duplicates = []
    try:
        with connect_read(path, timeout_seconds=2, busy_timeout_ms=2000) as con:
            if not table_exists(con, "MangaFile"):
                return {
                    "checked": False,
                    "provider": "kavita",
                    "path": str(path),
                    "reason": "kavita_schema_missing",
                    "duplicates": [],
                    "by_classification": {},
                }
            rows = con.execute(
                """
                select FilePath as file_path, count(*) as row_count
                from MangaFile
                where coalesce(FilePath, '') != ''
                group by FilePath
                having count(*) > 1
                order by row_count desc, file_path asc
                limit ?
                """,
                (limit,),
            ).fetchall()
            for row in rows:
                frontend_path = str(row["file_path"] or "")
                host_path = frontend_path_to_host_path_for_provider(state_con, frontend_path, "kavita")
                duplicates.append(
                    classify_frontend_duplicate_group(
                        provider="kavita",
                        frontend_path=frontend_path,
                        row_count=row["row_count"],
                        host_path=host_path,
                        ledger_index=ledger_index,
                        scanned_index=scanned_index,
                        actual_duplicate_index=actual_duplicate_index,
                    )
                )
    except sqlite3.Error as exc:
        return {
            "checked": False,
            "provider": "kavita",
            "path": str(path),
            "reason": "kavita_query_failed",
            "error": str(exc),
            "duplicates": [],
            "by_classification": {},
        }
    return {
        "checked": True,
        "provider": "kavita",
        "path": str(path),
        "duplicates": duplicates,
        "duplicate_groups": len(duplicates),
        "duplicate_rows": sum(max(0, int(row.get("row_count") or 0) - 1) for row in duplicates),
        "by_classification": frontend_duplicate_classification_summary(duplicates),
    }


def frontend_path_to_host_path_for_provider(con, frontend_path, provider="kavita"):
    path = str(frontend_path or "").strip().replace("\\", "/").rstrip("/")
    if not path:
        return ""
    provider_key = metadata_provider_key(provider or "kavita")
    comic_root = str(
        _app_setting_value_from_connection(con, "media_management.comic_root",
            _app_setting_value_from_connection(con, "path.comic_root", DEFAULT_LIBRARY_ROOTS["comic"]))
        or DEFAULT_LIBRARY_ROOTS["comic"]
    ).strip()
    manga_root = str(
        _app_setting_value_from_connection(con, "media_management.manga_root",
            _app_setting_value_from_connection(con, "path.manga_root", DEFAULT_LIBRARY_ROOTS["manga"]))
        or DEFAULT_LIBRARY_ROOTS["manga"]
    ).strip()
    adapter_pairs = []
    for media_type, host_root, default_adapter in (
        ("comic", comic_root, KAVITA_PATH_MAPPINGS[0][0]),
        ("manga", manga_root, KAVITA_PATH_MAPPINGS[1][0]),
    ):
        setting_key = f"path.{provider_key}_{media_type}_root"
        media_setting_key = f"media_management.{provider_key}_{media_type}_root"
        adapter_root = str(
            _app_setting_value_from_connection(
                con,
                media_setting_key,
                _app_setting_value_from_connection(con, setting_key, default_adapter),
            )
            or default_adapter
        ).strip()
        adapter_pairs.append((adapter_root, host_root))
    for adapter_root, host_root in adapter_pairs:
        adapter = str(adapter_root or "").replace("\\", "/").rstrip("/")
        host = str(host_root or "").replace("\\", "/").rstrip("/")
        if adapter and host and _path_has_prefix(path, adapter):
            rel = path[len(adapter):].lstrip("/")
            return "/".join(part for part in (host, rel) if part)
    return host_library_path_from_adapter_path(path)


def managed_library_scan_audit_from_connection(
    con,
    *,
    max_files=50000,
    sample_limit=50,
    include_frontend=True,
    kavita_db_path=None,
    include_cleanup_plan=False,
    include_hash_proof=False,
    hash_max_bytes=512 * 1024 * 1024,
):
    scan = managed_library_scan_files(con, max_files=max_files, sample_limit=sample_limit)
    ledger_index = media_file_ledger_index(con)
    scanned_index = {row["normalized_path"]: row for row in scan["files"]}
    actual_duplicate_index = {}
    for row in scan["files"]:
        actual_duplicate_index.setdefault(row["duplicate_key"], []).append(row)
    actual_duplicate_groups = [
        {
            "duplicate_key": key,
            "count": len(rows),
            "media_type": rows[0].get("media_type") if rows else "",
            "paths": [item["path"] for item in rows[:10]],
        }
        for key, rows in sorted(actual_duplicate_index.items(), key=lambda item: (-len(item[1]), item[0]))
        if len(rows) > 1
    ]
    tracked = []
    untracked = []
    for row in scan["files"]:
        if row["normalized_path"] in ledger_index:
            tracked.append(row)
        else:
            untracked.append(row)
    missing_ledger = [
        row
        for key, row in ledger_index.items()
        if int(row.get("active") or 0) and key not in scanned_index and not path_exists_quietly(row.get("path"))
    ]
    frontend = {}
    if include_frontend:
        frontend["kavita"] = kavita_duplicate_media_file_audit(
            con,
            kavita_db_path=kavita_db_path,
            ledger_index=ledger_index,
            scanned_index=scanned_index,
            actual_duplicate_index=actual_duplicate_index,
            limit=max(100, sample_limit),
        )
        frontend["komga"] = {
            "checked": False,
            "provider": "komga",
            "reason": "komga_api_duplicate_listing_not_available_in_state_audit",
            "duplicates": [],
            "by_classification": {},
        }
    payload = {
        "ok": True,
        "checked_at": time.time(),
        "roots": scan["roots"],
        "truncated": scan["truncated"],
        "max_files": scan["max_files"],
        "scanned_files": len(scan["files"]),
        "ledger_files": len(ledger_index),
        "tracked_files": len(tracked),
        "untracked_files": len(untracked),
        "missing_ledger_files": len(missing_ledger),
        "actual_duplicate_file_groups": len(actual_duplicate_groups),
        "actual_duplicate_file_rows": sum(max(0, int(group["count"] or 0) - 1) for group in actual_duplicate_groups),
        "samples": {
            "untracked": untracked[:sample_limit],
            "missing_ledger": [dict(row) for row in missing_ledger[:sample_limit]],
            "actual_duplicate_groups": actual_duplicate_groups[:sample_limit],
        },
        "frontend_duplicates": frontend,
    }
    if include_cleanup_plan:
        payload["duplicate_cleanup_plan"] = managed_library_duplicate_file_cleanup_plan_from_scan(
            con,
            scan=scan,
            ledger_index=ledger_index,
            actual_duplicate_index=actual_duplicate_index,
            sample_limit=sample_limit,
            include_hash_proof=include_hash_proof,
            hash_max_bytes=hash_max_bytes,
        )
    return payload


def managed_library_scan_audit(db_path, *, max_files=50000, sample_limit=50, include_frontend=True, kavita_db_path=None, include_cleanup_plan=False, include_hash_proof=False, hash_max_bytes=512 * 1024 * 1024):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    with connect_read(path, timeout_seconds=10, busy_timeout_ms=10000) as con:
        return managed_library_scan_audit_from_connection(
            con,
            max_files=max_files,
            sample_limit=sample_limit,
            include_frontend=include_frontend,
            kavita_db_path=kavita_db_path,
            include_cleanup_plan=include_cleanup_plan,
            include_hash_proof=include_hash_proof,
            hash_max_bytes=hash_max_bytes,
        )


def managed_library_duplicate_file_row_for_plan(row, ledger_index, hash_result=None):
    row = row if isinstance(row, dict) else dict(row or {})
    normalized_path = str(row.get("normalized_path") or media_file_normalized_path(row.get("path")) or "")
    ledger = ledger_index.get(normalized_path) if isinstance(ledger_index, dict) else None
    copy_marker = media_library_duplicate_copy_marker(row.get("path"))
    hash_result = hash_result if isinstance(hash_result, dict) else None
    item = {
        "path": row.get("path") or "",
        "normalized_path": normalized_path,
        "media_type": row.get("media_type") or "",
        "root": row.get("root") or "",
        "extension": row.get("extension") or media_library_archive_extension(row.get("path")),
        "size_bytes": row.get("size_bytes"),
        "mtime": row.get("mtime"),
        "duplicate_key": row.get("duplicate_key") or "",
        "copy_marker": copy_marker,
        "obvious_copy": bool(copy_marker),
        "ledger_tracked": bool(ledger),
        "ledger_active": bool(ledger and int(ledger.get("active") or 0)),
        "ledger_status": ledger.get("status") if isinstance(ledger, dict) else None,
        "series_id": ledger.get("series_id") if isinstance(ledger, dict) else None,
        "issue_id": ledger.get("issue_id") if isinstance(ledger, dict) else None,
        "queue_id": ledger.get("queue_id") if isinstance(ledger, dict) else None,
        "import_result_id": ledger.get("import_result_id") if isinstance(ledger, dict) else None,
    }
    if hash_result is not None:
        item["hash_proof"] = hash_result
        item["sha256"] = hash_result.get("sha256") if hash_result.get("ok") else None
        item["hash_status"] = "ok" if hash_result.get("ok") else hash_result.get("reason") or "unavailable"
    return item


def managed_library_duplicate_keep_file(files):
    files = [row for row in (files or []) if isinstance(row, dict)]
    if not files:
        return None

    def rank(row):
        return (
            0 if bool(row.get("ledger_active")) and not bool(row.get("obvious_copy")) else 1,
            0 if not bool(row.get("obvious_copy")) else 1,
            0 if bool(row.get("ledger_active")) else 1,
            0 if bool(row.get("ledger_tracked")) else 1,
            -float(row.get("size_bytes") or 0),
            str(row.get("path") or "").lower(),
        )

    return sorted(files, key=rank)[0]


def managed_library_duplicate_file_cleanup_plan_from_scan(
    con,
    *,
    scan,
    ledger_index=None,
    actual_duplicate_index=None,
    sample_limit=50,
    include_hash_proof=False,
    hash_max_bytes=512 * 1024 * 1024,
):
    del con
    sample_limit = max(0, min(int(sample_limit or 50), 500))
    try:
        hash_max_bytes = max(1, min(int(hash_max_bytes or 512 * 1024 * 1024), 8 * 1024 * 1024 * 1024))
    except (TypeError, ValueError):
        hash_max_bytes = 512 * 1024 * 1024
    ledger_index = ledger_index if isinstance(ledger_index, dict) else {}
    actual_duplicate_index = actual_duplicate_index if isinstance(actual_duplicate_index, dict) else {}
    truncated = bool((scan or {}).get("truncated"))
    candidates = []
    safe_groups = 0
    review_groups = 0
    duplicate_file_rows = 0
    hash_files_hashed = 0
    hash_files_skipped = 0
    hash_match_groups = 0
    hash_mismatch_groups = 0
    hash_unavailable_groups = 0
    for key, rows in sorted(actual_duplicate_index.items(), key=lambda item: (-len(item[1]), item[0])):
        if len(rows) <= 1:
            continue
        size_values_for_group = {
            int(row.get("size_bytes") or -1)
            for row in rows
            if row.get("size_bytes") is not None
        }
        hash_results = {}
        if include_hash_proof and len(size_values_for_group) == 1:
            for row in rows:
                normalized_path = str(row.get("normalized_path") or media_file_normalized_path(row.get("path")) or "")
                result = media_file_sha256(row.get("path"), max_bytes=hash_max_bytes)
                hash_results[normalized_path] = result
                if result.get("ok"):
                    hash_files_hashed += 1
                else:
                    hash_files_skipped += 1
        elif include_hash_proof:
            hash_files_skipped += len(rows)
        files = [
            managed_library_duplicate_file_row_for_plan(
                row,
                ledger_index,
                hash_result=hash_results.get(str(row.get("normalized_path") or media_file_normalized_path(row.get("path")) or "")) if include_hash_proof else None,
            )
            for row in rows
        ]
        keep = managed_library_duplicate_keep_file(files)
        if not keep:
            continue
        keep_path = keep.get("normalized_path")
        duplicate_files = [row for row in files if row.get("normalized_path") != keep_path]
        duplicate_file_rows += len(duplicate_files)
        blockers = []
        size_values = {
            int(row.get("size_bytes") or -1)
            for row in files
            if row.get("size_bytes") is not None
        }
        if len(size_values) > 1:
            blockers.append("size_mismatch")
        hash_status = "not_requested"
        content_hash = None
        content_match = None
        if include_hash_proof:
            if len(size_values) > 1:
                hash_status = "skipped_size_mismatch"
                content_match = False
                hash_unavailable_groups += 1
            else:
                ok_hashes = [row.get("sha256") for row in files if row.get("sha256")]
                unavailable = [row for row in files if not row.get("sha256")]
                unique_hashes = sorted({value for value in ok_hashes if value})
                if unavailable:
                    hash_status = "unavailable"
                    content_match = None
                    blockers.append("hash_unavailable")
                    hash_unavailable_groups += 1
                elif len(unique_hashes) == 1:
                    hash_status = "matched"
                    content_match = True
                    content_hash = unique_hashes[0]
                    hash_match_groups += 1
                else:
                    hash_status = "mismatch"
                    content_match = False
                    blockers.append("hash_mismatch")
                    hash_mismatch_groups += 1
        if not any(row.get("obvious_copy") for row in duplicate_files):
            blockers.append("no_obvious_copy_suffix")
        if any(row.get("ledger_active") for row in duplicate_files):
            blockers.append("duplicate_file_has_active_ledger_proof")
        if sum(1 for row in files if row.get("ledger_active")) > 1:
            blockers.append("multiple_active_ledger_files")
        if truncated:
            blockers.append("scan_truncated")
        if not duplicate_files:
            blockers.append("no_duplicate_files")
        safe_to_quarantine = not blockers
        if safe_to_quarantine:
            safe_groups += 1
        else:
            review_groups += 1
        candidate = {
            "id": stable_id("managed_library_duplicate_cleanup_plan", key),
            "duplicate_key": key,
            "media_type": keep.get("media_type") or "",
            "extension": keep.get("extension") or "",
            "file_count": len(files),
            "duplicate_file_count": len(duplicate_files),
            "keep_path": keep.get("path") or "",
            "keep_ledger_tracked": bool(keep.get("ledger_tracked")),
            "keep_ledger_status": keep.get("ledger_status"),
            "duplicate_paths": [row.get("path") or "" for row in duplicate_files],
            "duplicate_files": duplicate_files,
            "safe_to_quarantine": safe_to_quarantine,
            "action": "quarantine_candidate" if safe_to_quarantine else "review_only",
            "blockers": blockers,
            "hash_status": hash_status,
            "hash_proof_requested": bool(include_hash_proof),
            "content_match": content_match,
            "content_hash": content_hash,
            "requires_confirmation": ["duplicate_key", "keep_path", "duplicate_file_count"],
            "files": files,
        }
        candidates.append(candidate)
    return {
        "ok": True,
        "checked_at": time.time(),
        "truncated": truncated,
        "max_files": (scan or {}).get("max_files"),
        "duplicate_groups": len(candidates),
        "safe_quarantine_groups": safe_groups,
        "review_only_groups": review_groups,
        "duplicate_file_rows": duplicate_file_rows,
        "hash_proof_requested": bool(include_hash_proof),
        "hash_max_bytes": hash_max_bytes,
        "hash_files_hashed": hash_files_hashed,
        "hash_files_skipped": hash_files_skipped,
        "hash_match_groups": hash_match_groups,
        "hash_mismatch_groups": hash_mismatch_groups,
        "hash_unavailable_groups": hash_unavailable_groups,
        "candidates": candidates[:sample_limit],
        "sample_limit": sample_limit,
        "total_candidates": len(candidates),
    }


def managed_library_duplicate_quarantine_destination(path, quarantine_root, stamp, duplicate_key, *, create=True):
    source_path = Path(str(path or ""))
    batch_root = Path(managed_duplicate_quarantine_root_from_connection(override=quarantine_root))
    dest_dir = batch_root / str(stamp or time.strftime("%Y%m%d-%H%M%S", time.gmtime())) / sanitize_path_component(duplicate_key)
    if create:
        dest_dir.mkdir(parents=True, exist_ok=True)
    filename = sanitize_path_component(source_path.name) or "duplicate-file"
    dest = dest_dir / filename
    if not create or not dest.exists():
        return dest
    stem = dest.stem
    suffix = dest.suffix
    marker = stable_id("managed_duplicate_quarantine_dest", path, time.time())[:8]
    return dest.with_name(f"{stem}-{marker}{suffix}")


def managed_duplicate_quarantine_journal_path(quarantine_root, operation_id):
    root = Path(managed_duplicate_quarantine_root_from_connection(override=quarantine_root))
    return root / ".operations" / f"{sanitize_path_component(operation_id)}.json"


def managed_duplicate_quarantine_write_journal(journal_path, payload):
    path = Path(journal_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    temp.write_text(json_dumps(payload) + "\n", encoding="utf-8")
    os.replace(temp, path)


def managed_duplicate_quarantine_finalize(con, operation, *, now=None):
    now = float(now or time.time())
    duplicate_key = str(operation.get("duplicate_key") or "").strip()
    keep_path = str(operation.get("keep_path") or "").strip()
    source = str(operation.get("source") or "inkdrop_state").strip() or "inkdrop_state"
    moves = [row for row in (operation.get("moves") or []) if isinstance(row, dict)]
    for move in moves:
        normalized = media_file_normalized_path(move.get("source_path"))
        raw = {
            "status": "quarantined_duplicate",
            "duplicate_key": duplicate_key,
            "keep_path": keep_path,
            "quarantine_dest_path": str(move.get("dest_path") or ""),
            "quarantined_at": now,
            "quarantined_at_iso": utc_stamp(now),
            "source": source,
            "operation_id": operation.get("operation_id"),
        }
        con.execute(
            """
            update media_files
               set status='quarantined_duplicate',
                   active=0,
                   last_seen_at=?,
                   raw_json=?
             where normalized_path=?
            """,
            (now, json_dumps(raw), normalized),
        )
    event_id = stable_id("managed_duplicate_file_quarantined", operation.get("operation_id"), duplicate_key)
    con.execute(
        """
        insert or ignore into history_events(
            id, entity_type, entity_id, event_type, source, message,
            outcome, display_phase, created_at, raw_json
        ) values(?,?,?,?,?,?,?,?,?,?)
        """,
        (
            event_id,
            "media_file",
            duplicate_key,
            "managed_duplicate_file_quarantined",
            source,
            f"Managed duplicate file group quarantined: {len(moves)} file(s) moved",
            "repaired",
            "cleanup",
            now,
            json_dumps({
                "operation_id": operation.get("operation_id"),
                "duplicate_key": duplicate_key,
                "keep_path": keep_path,
                "moved": moves,
                "candidate": operation.get("candidate"),
                "hash_status": operation.get("hash_status"),
                "content_hash": operation.get("content_hash"),
                "rollback": [
                    {"move": item.get("dest_path"), "back_to": item.get("source_path")}
                    for item in moves
                ],
            }),
        ),
    )
    update_sync_meta(con, now, "managed_duplicate_file_quarantined")
    return event_id


def managed_duplicate_quarantine_recover(db_path, quarantine_root, *, duplicate_key=None):
    journal_root = Path(managed_duplicate_quarantine_root_from_connection(override=quarantine_root)) / ".operations"
    if not journal_root.exists():
        return []
    recovered = []
    for journal_path in sorted(journal_root.glob("*.json")):
        try:
            operation = json.loads(journal_path.read_text(encoding="utf-8"))
        except (OSError, ValueError, TypeError):
            continue
        if not isinstance(operation, dict):
            continue
        if duplicate_key and str(operation.get("duplicate_key") or "") != str(duplicate_key):
            continue
        if str(operation.get("status") or "") in {"finalized", "rolled_back"}:
            continue
        moves = [row for row in (operation.get("moves") or []) if isinstance(row, dict)]
        states = []
        for move in moves:
            source_exists = path_exists_quietly(move.get("source_path"))
            dest_exists = path_exists_quietly(move.get("dest_path"))
            states.append((source_exists, dest_exists))
        fully_moved = bool(states) and all(not source_exists and dest_exists for source_exists, dest_exists in states)
        untouched = bool(states) and all(source_exists and not dest_exists for source_exists, dest_exists in states)
        if fully_moved:
            if not path_exists_quietly(operation.get("keep_path")):
                operation["status"] = "recovery_blocked"
                operation["recovered_at"] = time.time()
                operation["recovery_reason"] = "keep_file_missing"
                managed_duplicate_quarantine_write_journal(journal_path, operation)
                recovered.append({"operation_id": operation.get("operation_id"), "status": "recovery_blocked", "reason": operation["recovery_reason"]})
                continue
            with connect(db_path, timeout_seconds=20.0, busy_timeout_ms=20000) as con:
                init_schema(con)
                event_id = managed_duplicate_quarantine_finalize(con, operation)
                con.commit()
            operation["status"] = "finalized"
            operation["finalized_at"] = time.time()
            operation["finalized_at_iso"] = utc_stamp(operation["finalized_at"])
            operation["history_event_id"] = event_id
            managed_duplicate_quarantine_write_journal(journal_path, operation)
            recovered.append({"operation_id": operation.get("operation_id"), "status": "finalized", "history_event_id": event_id})
            continue
        if untouched:
            operation["status"] = "rolled_back"
            operation["recovered_at"] = time.time()
            operation["recovery_reason"] = "planned_operation_had_not_started"
            managed_duplicate_quarantine_write_journal(journal_path, operation)
            recovered.append({"operation_id": operation.get("operation_id"), "status": "rolled_back"})
            continue
        conflict = any(source_exists and dest_exists for source_exists, dest_exists in states)
        missing = any(not source_exists and not dest_exists for source_exists, dest_exists in states)
        if conflict or missing:
            operation["status"] = "recovery_blocked"
            operation["recovered_at"] = time.time()
            operation["recovery_reason"] = "source_destination_conflict" if conflict else "source_and_destination_missing"
            managed_duplicate_quarantine_write_journal(journal_path, operation)
            recovered.append({"operation_id": operation.get("operation_id"), "status": "recovery_blocked", "reason": operation["recovery_reason"]})
            continue
        rolled_back = []
        for move, (source_exists, dest_exists) in reversed(list(zip(moves, states))):
            if not source_exists and dest_exists:
                source_path = Path(str(move.get("source_path") or ""))
                source_path.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(move.get("dest_path")), str(source_path))
                rolled_back.append(move)
        operation["status"] = "rolled_back"
        operation["recovered_at"] = time.time()
        operation["recovery_reason"] = "partial_move_rolled_back"
        operation["rollback"] = rolled_back
        managed_duplicate_quarantine_write_journal(journal_path, operation)
        recovered.append({"operation_id": operation.get("operation_id"), "status": "rolled_back", "rollback": rolled_back})
    return recovered


def managed_library_duplicate_file_quarantine(
    db_path,
    *,
    duplicate_key=None,
    confirm_duplicate_key=None,
    keep_path=None,
    confirm_keep_path=None,
    duplicate_file_count=None,
    confirm_duplicate_file_count=None,
    apply=False,
    enable_apply=False,
    max_files=25000,
    sample_limit=500,
    hash_max_bytes=512 * 1024 * 1024,
    quarantine_root=None,
    source="inkdrop_state",
):
    duplicate_key = str(duplicate_key or "").strip()
    confirm_duplicate_key = str(confirm_duplicate_key or "").strip()
    keep_path = str(keep_path or "").strip()
    confirm_keep_path = str(confirm_keep_path or "").strip()
    try:
        expected_duplicate_count = int(duplicate_file_count if duplicate_file_count is not None else confirm_duplicate_file_count or 0)
    except (TypeError, ValueError):
        expected_duplicate_count = 0
    try:
        confirmed_duplicate_count = int(confirm_duplicate_file_count if confirm_duplicate_file_count is not None else duplicate_file_count or 0)
    except (TypeError, ValueError):
        confirmed_duplicate_count = 0
    try:
        max_files = max(1, min(int(max_files or 25000), 100000))
    except (TypeError, ValueError):
        max_files = 25000
    try:
        sample_limit = max(1, min(int(sample_limit or 500), 5000))
    except (TypeError, ValueError):
        sample_limit = 500
    try:
        hash_max_bytes = max(1, min(int(hash_max_bytes or 512 * 1024 * 1024), 8 * 1024 * 1024 * 1024))
    except (TypeError, ValueError):
        hash_max_bytes = 512 * 1024 * 1024
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    if not duplicate_key:
        return {"ok": False, "reason": "duplicate_key_required", "db_path": str(path)}
    effective_quarantine_root = managed_duplicate_quarantine_root_from_connection(
        db_path=path,
        override=quarantine_root,
    )
    recovery = []
    if apply and enable_apply and confirm_duplicate_key == duplicate_key:
        recovery = managed_duplicate_quarantine_recover(path, effective_quarantine_root, duplicate_key=duplicate_key)
        blocked_recovery = next((row for row in recovery if row.get("status") == "recovery_blocked"), None)
        if blocked_recovery:
            return {
                "ok": False,
                "reason": "managed_duplicate_quarantine_recovery_blocked",
                "db_path": str(path),
                "duplicate_key": duplicate_key,
                "quarantine_root": str(effective_quarantine_root),
                "recovery": recovery,
            }
        finalized_recovery = next((row for row in recovery if row.get("status") == "finalized"), None)
        if finalized_recovery:
            clear_state_view_summary_cache()
            return {
                "ok": True,
                "reason": "managed_duplicate_quarantine_recovered",
                "dry_run": False,
                "apply_requested": True,
                "apply_supported": True,
                "apply_enabled": True,
                "db_path": str(path),
                "duplicate_key": duplicate_key,
                "quarantine_root": str(effective_quarantine_root),
                "history_event_id": finalized_recovery.get("history_event_id"),
                "recovery": recovery,
            }

    audit = managed_library_scan_audit(
        path,
        max_files=max_files,
        sample_limit=sample_limit,
        include_frontend=False,
        include_cleanup_plan=True,
        include_hash_proof=True,
        hash_max_bytes=hash_max_bytes,
    )
    plan = audit.get("duplicate_cleanup_plan") if isinstance(audit, dict) else {}
    candidates = plan.get("candidates") if isinstance(plan, dict) else []
    candidates = candidates if isinstance(candidates, list) else []
    candidate = next((item for item in candidates if str(item.get("duplicate_key") or "") == duplicate_key), None)
    base = {
        "ok": bool(candidate),
        "reason": None if candidate else "duplicate_candidate_not_found",
        "dry_run": True,
        "apply_requested": bool(apply),
        "apply_supported": True,
        "apply_enabled": False,
        "apply_requires": [
            "apply=true",
            "enableApply=true",
            "duplicate_key",
            "confirmDuplicateKey matching duplicate_key",
            "confirmKeepPath matching keep_path",
            "confirmDuplicateFileCount matching duplicate_file_count",
            "hash_status=matched",
        ],
        "db_path": str(path),
        "duplicate_key": duplicate_key,
        "candidate": candidate,
        "audit_summary": {
            "scanned_files": audit.get("scanned_files"),
            "actual_duplicate_file_groups": audit.get("actual_duplicate_file_groups"),
            "plan_duplicate_groups": plan.get("duplicate_groups") if isinstance(plan, dict) else None,
            "hash_files_hashed": plan.get("hash_files_hashed") if isinstance(plan, dict) else None,
            "hash_files_skipped": plan.get("hash_files_skipped") if isinstance(plan, dict) else None,
        },
        "quarantine_root": str(effective_quarantine_root),
    }
    if not candidate:
        return base
    blockers = list(candidate.get("blockers") or [])
    if not candidate.get("safe_to_quarantine"):
        return {**base, "ok": False, "reason": "candidate_not_safe_to_quarantine", "blockers": blockers}
    if candidate.get("hash_status") != "matched" or candidate.get("content_match") is not True:
        return {**base, "ok": False, "reason": "candidate_not_hash_proven", "blockers": blockers, "hash_status": candidate.get("hash_status")}
    candidate_keep_path = str(candidate.get("keep_path") or "").strip()
    candidate_duplicate_count = int(candidate.get("duplicate_file_count") or 0)
    duplicate_paths = [str(value or "").strip() for value in (candidate.get("duplicate_paths") or []) if str(value or "").strip()]
    operations = [
        {
            "operation": "move_to_quarantine",
            "source_path": value,
            "dest_path": str(managed_library_duplicate_quarantine_destination(value, effective_quarantine_root, "DRY-RUN", duplicate_key, create=False)),
        }
        for value in duplicate_paths
    ]
    preview = {
        **base,
        "ok": True,
        "reason": None,
        "candidate": {**candidate, "files": candidate.get("files") or []},
        "keep_path": candidate_keep_path,
        "duplicate_file_count": candidate_duplicate_count,
        "operations": operations,
        "operation_counts": {"move_to_quarantine": len(operations), "record_history": 1},
        "mutation_count": len(operations) + 1,
    }
    if not apply:
        return preview
    if not enable_apply:
        return {**preview, "ok": False, "reason": "managed_duplicate_quarantine_apply_disabled"}
    if confirm_duplicate_key != duplicate_key:
        return {**preview, "ok": False, "reason": "confirm_duplicate_key_mismatch"}
    if keep_path and media_file_normalized_path(keep_path) != media_file_normalized_path(candidate_keep_path):
        return {**preview, "ok": False, "reason": "keep_path_mismatch"}
    if media_file_normalized_path(confirm_keep_path) != media_file_normalized_path(candidate_keep_path):
        return {**preview, "ok": False, "reason": "confirm_keep_path_mismatch"}
    if expected_duplicate_count and expected_duplicate_count != candidate_duplicate_count:
        return {**preview, "ok": False, "reason": "duplicate_file_count_mismatch"}
    if confirmed_duplicate_count != candidate_duplicate_count:
        return {**preview, "ok": False, "reason": "confirm_duplicate_file_count_mismatch"}
    for duplicate_path in duplicate_paths:
        if not path_exists_quietly(duplicate_path):
            return {**preview, "ok": False, "reason": "duplicate_file_missing_before_apply", "missing_path": duplicate_path}
    if not path_exists_quietly(candidate_keep_path):
        return {**preview, "ok": False, "reason": "keep_file_missing_before_apply", "missing_path": candidate_keep_path}

    now = time.time()
    operation_id = stable_id("managed_duplicate_quarantine", duplicate_key, candidate_keep_path, int(now * 1000))
    journal_path = managed_duplicate_quarantine_journal_path(effective_quarantine_root, operation_id)
    moves = [
        {
            "source_path": duplicate_path,
            "dest_path": str(
                managed_library_duplicate_quarantine_destination(
                    duplicate_path,
                    effective_quarantine_root,
                    operation_id,
                    duplicate_key,
                    create=False,
                )
            ),
        }
        for duplicate_path in duplicate_paths
    ]
    operation = {
        "schema_version": 1,
        "operation_id": operation_id,
        "operation": "managed_duplicate_quarantine",
        "status": "planned",
        "planned_at": now,
        "planned_at_iso": utc_stamp(now),
        "duplicate_key": duplicate_key,
        "keep_path": candidate_keep_path,
        "source": source,
        "hash_status": candidate.get("hash_status"),
        "content_hash": candidate.get("content_hash"),
        "candidate": candidate,
        "moves": moves,
        "moved": [],
    }
    managed_duplicate_quarantine_write_journal(journal_path, operation)
    moved = []
    try:
        with connect(path, timeout_seconds=20.0, busy_timeout_ms=20000) as con:
            init_schema(con)
            normalized_roots = [media_file_normalized_path(entry["root"]) for entry in managed_root_entries_from_connection(con)]
            normalized_roots = [root for root in normalized_roots if root]
        for move in moves:
            normalized = media_file_normalized_path(move["source_path"])
            if normalized_roots and not path_under_any_root(normalized, normalized_roots):
                operation["status"] = "recovery_blocked"
                operation["recovery_reason"] = "duplicate_path_outside_managed_roots"
                managed_duplicate_quarantine_write_journal(journal_path, operation)
                return {**preview, "ok": False, "reason": "duplicate_path_outside_managed_roots", "blocked_path": move["source_path"]}
            dest = Path(move["dest_path"])
            if dest.exists():
                operation["status"] = "recovery_blocked"
                operation["recovery_reason"] = "quarantine_destination_exists"
                managed_duplicate_quarantine_write_journal(journal_path, operation)
                return {**preview, "ok": False, "reason": "quarantine_destination_exists", "blocked_path": str(dest)}
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(move["source_path"]), str(dest))
            if path_exists_quietly(move["source_path"]) or not path_exists_quietly(dest):
                raise RuntimeError(f"duplicate_quarantine_move_not_verified:{move['source_path']}->{dest}")
            moved.append(move)
            operation["status"] = "moving"
            operation["moved"] = list(moved)
            managed_duplicate_quarantine_write_journal(journal_path, operation)
    except Exception as exc:
        rollback = []
        for item in reversed(moved):
            try:
                if path_exists_quietly(item["dest_path"]) and not path_exists_quietly(item["source_path"]):
                    Path(item["source_path"]).parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(item["dest_path"], item["source_path"])
                    rollback.append(item)
            except Exception:
                pass
        operation["status"] = "rolled_back" if len(rollback) == len(moved) else "recovery_blocked"
        operation["error"] = f"{type(exc).__name__}: {exc}"
        operation["rollback"] = rollback
        operation["recovered_at"] = time.time()
        managed_duplicate_quarantine_write_journal(journal_path, operation)
        return {
            **preview,
            "ok": False,
            "reason": "managed_duplicate_quarantine_failed",
            "error": f"{type(exc).__name__}: {exc}",
            "moved_before_failure": moved,
            "rollback_attempted": rollback,
        }
    operation["status"] = "awaiting_finalize"
    operation["moved"] = list(moved)
    operation["moved_at"] = time.time()
    managed_duplicate_quarantine_write_journal(journal_path, operation)
    try:
        with connect(path, timeout_seconds=20.0, busy_timeout_ms=20000) as con:
            init_schema(con)
            event_id = managed_duplicate_quarantine_finalize(con, operation, now=now)
            con.commit()
    except Exception as exc:
        operation["finalize_error"] = f"{type(exc).__name__}: {exc}"
        operation["finalize_failed_at"] = time.time()
        managed_duplicate_quarantine_write_journal(journal_path, operation)
        return {
            **preview,
            "ok": False,
            "reason": "managed_duplicate_quarantine_finalize_pending",
            "error": operation["finalize_error"],
            "moved": moved,
            "operation_id": operation_id,
            "journal_path": str(journal_path),
            "retryable": True,
        }
    operation["status"] = "finalized"
    operation["history_event_id"] = event_id
    operation["finalized_at"] = time.time()
    operation["finalized_at_iso"] = utc_stamp(operation["finalized_at"])
    managed_duplicate_quarantine_write_journal(journal_path, operation)
    clear_state_view_summary_cache()
    return {
        **preview,
        "ok": True,
        "reason": None,
        "dry_run": False,
        "apply_enabled": True,
        "applied_count": len(moved),
        "moved": moved,
        "history_event_id": event_id,
        "operation_id": operation_id,
        "journal_path": str(journal_path),
        "recovery": recovery,
        "applied_at": now,
        "applied_at_iso": utc_stamp(now),
        "operation_counts": {"move_to_quarantine": len(moved), "record_history": 1},
        "mutation_count": len(moved) + 1,
    }


def path_contract_host_path(contract):
    contract = contract if isinstance(contract, dict) or hasattr(contract, "keys") else {}
    host_path = _first_text(row_value(contract, "library_path"), row_value(contract, "libraryPath"))
    if not host_path:
        adapter_path = _first_text(row_value(contract, "library_adapter_path"), row_value(contract, "libraryAdapterPath"))
        host_path = host_library_path_from_adapter_path(adapter_path)
    return host_path or _first_text(row_value(contract, "library_root"), row_value(contract, "libraryRoot"))


def path_contract_needs_media_root_repair(contract, media_type, *, con=None):
    media = normalized_media_type(media_type)
    if media not in MANGA_MEDIA_TYPES:
        return False
    source = str(row_value(contract, "library_path_source") or row_value(contract, "libraryPathSource") or "").strip().lower()
    if source == "user":
        return False
    expected_root = str(default_library_root_for_media_type(media, con=con) or "").replace("\\", "/").rstrip("/")
    if not expected_root:
        return False
    current_path = str(path_contract_host_path(contract) or "").replace("\\", "/").rstrip("/")
    if not current_path:
        return False
    return not _path_has_prefix(current_path, expected_root)


def host_library_path_from_adapter_path(value):
    path = str(value or "").strip().replace("\\", "/").rstrip("/")
    if not path:
        return ""
    for adapter_root, host_root in KAVITA_PATH_MAPPINGS:
        adapter_root = adapter_root.rstrip("/")
        host_root = host_root.rstrip("/")
        if _path_has_prefix(path, adapter_root):
            rel = path[len(adapter_root):].lstrip("/")
            return "/".join(part for part in (host_root, rel) if part)
    if path.startswith("/mnt/") or path.startswith("/home/"):
        return path
    return ""


def library_root_for_path(path):
    path = str(path or "").strip().replace("\\", "/").rstrip("/")
    if not path:
        return ""
    for _adapter_root, host_root in KAVITA_PATH_MAPPINGS:
        host_root = host_root.rstrip("/")
        if _path_has_prefix(path, host_root):
            return host_root
    return ""


def series_path_contract(row, provider=None, kapowarr_id=None, source=None):
    row = row if isinstance(row, dict) else {}
    host_path = _first_text(
        row.get("libraryPath"),
        row.get("library_path"),
        row.get("hostFolder"),
        row.get("host_folder"),
        row.get("destinationPath"),
        row.get("destination_path"),
    )
    adapter_path = _first_text(
        row.get("libraryAdapterPath"),
        row.get("library_adapter_path"),
        row.get("adapterPath"),
        row.get("adapter_path"),
        row.get("kavitaPath"),
        row.get("kavita_path"),
        row.get("folder"),
    )
    if not host_path and adapter_path:
        host_path = host_library_path_from_adapter_path(adapter_path)
    root = _first_text(row.get("libraryRoot"), row.get("library_root"), row.get("rootFolder"), row.get("root_folder"))
    if not root:
        root = library_root_for_path(host_path)
    template = _first_text(row.get("libraryPathTemplate"), row.get("library_path_template"), row.get("pathTemplate"), row.get("path_template"))
    path_source = _first_text(row.get("libraryPathSource"), row.get("library_path_source"), row.get("pathSource"), row.get("path_source"))
    if not path_source and (host_path or adapter_path or template):
        provider_key = metadata_provider_key(source or provider)
        path_source = "kapowarr_adapter" if kapowarr_id not in (None, "") or provider_key == "kapowarr" or adapter_path else (provider_key or "inkdrop")
    return {
        "library_root": root or None,
        "library_path": host_path or None,
        "library_path_template": template or None,
        "library_path_source": path_source or None,
        "library_adapter_path": adapter_path or None,
    }


def upsert_series(con, row, now):
    row = dict(row or {})
    title = row.get("name") or row.get("series") or row.get("title") or "Unknown"
    provider, metadata_id = metadata_identity(row)
    cv_id = row.get("comicvineId") or row.get("comicvine_id")
    kapowarr_id = row.get("kapowarrId") or row.get("kapowarr_id")
    sid = series_identity(row)
    provider = provider or ("comicvine" if cv_id not in (None, "") else ("kapowarr" if kapowarr_id not in (None, "") else "manual"))
    metadata_id = metadata_id if metadata_id not in (None, "") else (cv_id if provider == "comicvine" else (kapowarr_id if provider == "kapowarr" else ""))
    tombstone_resolution = series_identity_tombstone_resolution(con, row, sid)
    if tombstone_resolution and tombstone_resolution.get("action") == "blocked":
        raise SeriesIdentityTombstoneBlocked(tombstone_resolution)
    if tombstone_resolution and tombstone_resolution.get("action") == "alias_removed_canonical":
        sid = tombstone_resolution["series_id"]
        provider = tombstone_resolution.get("metadata_provider") or provider
        metadata_id = tombstone_resolution.get("metadata_id") or metadata_id
        row["series_identity_tombstone_resolution"] = tombstone_resolution
    media_decision = native_series_media_decision(row, provider=provider)
    media_type = media_decision.get("media_type") or "comic"
    path_contract = series_path_contract(row, provider=provider, kapowarr_id=kapowarr_id, source=row.get("source"))
    default_contract = None
    if not has_path_contract_values(path_contract) and str(provider or "").lower() != "kapowarr":
        default_contract = native_series_path_contract(row, media_type=media_type, con=con)
        if default_contract:
            path_contract = default_contract
    existing = con.execute(
        """
        select monitored, monitor_new, auto_grab, source, raw_json,
               metadata_provider, metadata_id, kapowarr_id, media_type,
               library_root, library_path, library_path_template,
               library_path_source, library_adapter_path
        from series
        where id=?
        """,
        (sid,),
    ).fetchone()
    existing_raw = json_loads(existing["raw_json"] or "{}", {}) if existing else {}
    existing_parked_reason = str(existing_raw.get("automation_parked_reason") or "").strip().lower()
    existing_removed_or_parked = bool(existing and series_raw_removed_or_parked(existing_raw))
    explicit_removed_reactivation = bool(
        existing
        and series_raw_user_removed(existing_raw)
        and existing_parked_reason == "user_removed"
        and series_row_allows_removed_reactivation(row)
    )
    preserve_removed_or_parked = bool(existing_removed_or_parked and not explicit_removed_reactivation)
    preserve_existing_default_path = bool(
        existing
        and default_contract
        and (
            str(existing["library_path"] or "").strip()
            or str(existing["library_adapter_path"] or "").strip()
            or str(existing["library_path_template"] or "").strip()
        )
        and not path_contract_needs_media_root_repair(existing, media_type, con=con)
    )
    if preserve_existing_default_path:
        default_contract = None
        path_contract = {
            "library_root": existing["library_root"],
            "library_path": existing["library_path"],
            "library_path_template": existing["library_path_template"],
            "library_path_source": existing["library_path_source"],
            "library_adapter_path": existing["library_adapter_path"],
        }
    preserve_user_path = bool(
        existing
        and str(existing["library_path_source"] or "").strip().lower() == "user"
        and str(path_contract.get("library_path_source") or "").strip().lower() != "user"
    )
    if preserve_user_path:
        default_contract = None
        path_contract = {
            "library_root": existing["library_root"],
            "library_path": existing["library_path"],
            "library_path_template": existing["library_path_template"],
            "library_path_source": existing["library_path_source"],
            "library_adapter_path": existing["library_adapter_path"],
        }
    row_raw = dict(row)
    row_raw["media_type_decision"] = dict(media_decision)
    if has_path_contract_values(path_contract):
        row_raw["path_contract"] = dict(path_contract)
        if default_contract:
            repaired_media_root = bool(existing and path_contract_needs_media_root_repair(existing, media_type, con=con))
            previous_contract = None
            if repaired_media_root:
                previous_contract = {
                    "library_root": existing["library_root"],
                    "library_path": existing["library_path"],
                    "library_path_template": existing["library_path_template"],
                    "library_path_source": existing["library_path_source"],
                    "library_adapter_path": existing["library_adapter_path"],
                    "media_type": existing["media_type"],
                }
            row_raw["path_contract"].update(
                {
                    "source": "inkdrop",
                    "contract_source": "native_root_template",
                    "reason": "media_root_mismatch_repaired" if repaired_media_root else "missing_kapowarr_path_contract",
                    "backfilled_at": now,
                    "backfilled_at_iso": utc_stamp(now),
                },
            )
            if previous_contract:
                row_raw["path_contract"]["previous_path_contract"] = previous_contract
    if preserve_removed_or_parked:
        default_contract = None
        provider = existing["metadata_provider"] or provider
        metadata_id = existing["metadata_id"] if existing["metadata_id"] not in (None, "") else metadata_id
        kapowarr_id = existing["kapowarr_id"] if existing["kapowarr_id"] not in (None, "") else kapowarr_id
        parked_reason = existing_raw.get("automation_parked_reason") or ("user_removed" if series_raw_user_removed(existing_raw) else "automation_parked")
        row_raw.update(
            {
                "automation_parked": True,
                "automation_parked_reason": parked_reason,
                "automation_parked_message": existing_raw.get("automation_parked_message") or "Series automation parked",
                "removed_by_user": bool(existing_raw.get("removed_by_user")) or str(parked_reason).strip().lower() == "user_removed",
                "removed_preserved_from_sync": True,
                "removed_preserved_at": now,
                "removed_preserved_at_iso": utc_stamp(now),
                "parked_preserved_from_sync": True,
                "parked_preserved_at": now,
                "parked_preserved_at_iso": utc_stamp(now),
                "sync_payload": row,
            }
        )
        for key in (
            "automation_parked_at",
            "automation_parked_at_iso",
            "removed_at",
            "removed_at_iso",
            "retired_at",
            "retired_at_iso",
            "retired_target_series_id",
            "retired_shadow",
            "retired_shadow_kind",
            "retired_after_adapter_drain",
            "drained_wanted_ids",
        ):
            if key in existing_raw:
                row_raw[key] = existing_raw.get(key)
    elif explicit_removed_reactivation:
        row_raw.update(
            {
                "removed_by_user": False,
                "removed_reactivated_by_user": True,
                "removed_reactivated_at": now,
                "removed_reactivated_at_iso": utc_stamp(now),
                "previous_removed_reason": existing_raw.get("automation_parked_reason"),
            }
        )
        for key in (
            "automation_parked",
            "automation_parked_reason",
            "automation_parked_message",
            "automation_parked_at",
            "automation_parked_at_iso",
            "removed_at",
            "removed_at_iso",
        ):
            row_raw.pop(key, None)
    row_raw = merge_series_image_metadata(row_raw, existing_raw)
    monitored = 0 if preserve_removed_or_parked else (1 if row.get("enabled", True) else 0)
    monitor_new = 0 if preserve_removed_or_parked else (1 if row.get("monitorNew", row.get("monitor_new", True)) else 0)
    auto_grab = 0 if preserve_removed_or_parked else (1 if row.get("autoGrab", row.get("watch_auto_grab", True)) else 0)
    source = (
        "removed"
        if preserve_removed_or_parked and series_raw_user_removed(row_raw)
        else ((existing["source"] if preserve_removed_or_parked and existing else None) or row.get("source") or provider)
    )
    con.execute(
        """
        insert into series(
            id, title, sort_title, media_type, year, publisher, metadata_provider,
            metadata_id, kapowarr_id, source, library_root, library_path,
            library_path_template, library_path_source, library_adapter_path,
            monitored, monitor_new, auto_grab, created_at, updated_at, raw_json
        ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        on conflict(id) do update set
            title=excluded.title,
            sort_title=excluded.sort_title,
            media_type=case
                when coalesce(series.library_path_source, '') = 'user' and coalesce(excluded.media_type, '') = '' then series.media_type
                else excluded.media_type
            end,
            year=coalesce(excluded.year, series.year),
            publisher=coalesce(excluded.publisher, series.publisher),
            metadata_provider=excluded.metadata_provider,
            metadata_id=excluded.metadata_id,
            kapowarr_id=coalesce(excluded.kapowarr_id, series.kapowarr_id),
            source=excluded.source,
            library_root=coalesce(excluded.library_root, series.library_root),
            library_path=coalesce(excluded.library_path, series.library_path),
            library_path_template=coalesce(excluded.library_path_template, series.library_path_template),
            library_path_source=coalesce(excluded.library_path_source, series.library_path_source),
            library_adapter_path=coalesce(excluded.library_adapter_path, series.library_adapter_path),
            monitored=excluded.monitored,
            monitor_new=excluded.monitor_new,
            auto_grab=excluded.auto_grab,
            updated_at=excluded.updated_at,
            raw_json=excluded.raw_json
        """,
        (
            sid,
            title,
            normalize_key(title),
            media_type,
            row.get("year") or row.get("watch_year"),
            row.get("publisher") or row.get("watch_publisher"),
            provider,
            str(metadata_id or ""),
            int(kapowarr_id) if str(kapowarr_id or "").isdigit() else None,
            source,
            path_contract.get("library_root"),
            path_contract.get("library_path"),
            path_contract.get("library_path_template"),
            path_contract.get("library_path_source"),
            path_contract.get("library_adapter_path"),
            monitored,
            monitor_new,
            auto_grab,
            row.get("created") or row.get("created_at") or now,
            now,
            json_dumps(row_raw),
        ),
    )
    return sid


def upsert_issue(con, series_id, issue, now):
    number = str(issue.get("issueNumber") or issue.get("issue") or "").strip()
    issue_provider, explicit_metadata_id = metadata_identity(issue)
    metadata_id = explicit_metadata_id or issue.get("id") or issue.get("issue_id")
    issue_id = f"{series_id}:issue:{metadata_id or normalize_issue_number(number)}"
    if not issue_provider:
        issue_provider = "comicvine" if metadata_id and not str(metadata_id).startswith("kapowarr-") else "kapowarr"
    normalized_number = normalize_issue_number(number)
    release_date = (
        issue.get("date")
        or issue.get("release_date")
        or issue.get("releaseDate")
        or issue.get("store_date")
        or issue.get("storeDate")
        or issue.get("cover_date")
        or issue.get("coverDate")
        or issue.get("publishAt")
        or issue.get("publishedAt")
        or issue.get("readableAt")
    )
    con.execute(
        """
        insert into issues(
            id, series_id, issue_number, normalized_number, title, release_date,
            metadata_provider, metadata_id, kapowarr_issue_id, monitored,
            created_at, updated_at, raw_json
        ) values(?,?,?,?,?,?,?,?,?,?,?,?,?)
        on conflict(id) do update set
            issue_number=excluded.issue_number,
            normalized_number=excluded.normalized_number,
            title=coalesce(nullif(excluded.title, ''), issues.title),
            release_date=coalesce(nullif(excluded.release_date, ''), issues.release_date),
            metadata_provider=excluded.metadata_provider,
            metadata_id=excluded.metadata_id,
            kapowarr_issue_id=coalesce(excluded.kapowarr_issue_id, issues.kapowarr_issue_id),
            monitored=case
                when issues.monitored_user_override is not null then issues.monitored_user_override
                else excluded.monitored
            end,
            updated_at=excluded.updated_at,
            raw_json=excluded.raw_json
        """,
        (
            issue_id,
            series_id,
            number,
            normalized_number,
            issue.get("title") or issue.get("issue_title") or "",
            release_date,
            issue_provider,
            str(metadata_id or ""),
            issue.get("kapowarrIssueId") or issue.get("kapowarr_issue_id"),
            1 if issue.get("monitored", True) else 0,
            issue.get("firstSeen") or now,
            now,
            json_dumps(issue),
        ),
    )
    if issue_provider in {"comicvine", "mangadex"} and normalized_number and release_date:
        con.execute(
            """
            update issues
            set release_date=coalesce(nullif(release_date, ''), ?),
                title=case
                    when coalesce(title, '') = '' and coalesce(?, '') != '' then ?
                    else title
                end,
                updated_at=?
            where series_id=?
              and normalized_number=?
              and id<>?
              and coalesce(metadata_provider, '') in ('', 'kapowarr', 'manual')
              and coalesce(release_date, '') = ''
            """,
            (
                release_date,
                issue.get("title") or issue.get("issue_title") or "",
                issue.get("title") or issue.get("issue_title") or "",
                now,
                series_id,
                normalized_number,
                issue_id,
            ),
        )
    return issue_id


def set_issue_monitored(db_path, issue_id, monitored):
    """User-facing per-issue monitor toggle ("I already own this one, stop re-acquiring it").

    Distinct from the plain `monitored` column upsert_issue writes on every metadata
    sync: this also stamps `monitored_user_override` so the next ComicVine/Kapowarr/
    MangaDex sync doesn't silently stomp the user's choice back to the provider's value.
    """
    issue_id = str(issue_id or "").strip()
    if not issue_id:
        raise ValueError("issue id is required")
    monitored = bool(monitored)
    now = time.time()
    with connect(db_path) as con:
        init_schema(con)
        row = con.execute(
            "select id, series_id, issue_number, title, monitored from issues where id=?",
            (issue_id,),
        ).fetchone()
        if not row:
            return {"ok": False, "reason": "issue_not_found"}
        con.execute(
            "update issues set monitored=?, monitored_user_override=?, updated_at=? where id=?",
            (1 if monitored else 0, 1 if monitored else 0, now, issue_id),
        )
        wanted_items_cleared = 0
        if not monitored:
            open_ids = [
                r["id"]
                for r in con.execute(
                    """
                    select w.id from wanted_items w
                    where w.issue_id=?
                      and lower(coalesce(w.status,'')) = 'wanted'
                      and not exists (
                          select 1 from queue_items q
                          where (q.wanted_id = w.id or q.issue_id = w.issue_id)
                            and q.active = 1
                      )
                    """,
                    (issue_id,),
                ).fetchall()
            ]
            for wanted_id in open_ids:
                con.execute("delete from wanted_items where id=?", (wanted_id,))
            wanted_items_cleared = len(open_ids)
        record_settings_history(
            con,
            "issue_monitor_set" if monitored else "issue_monitor_clear",
            "issue",
            issue_id,
            "web",
            f"Issue {row['issue_number'] or issue_id} {'monitored' if monitored else 'set to not monitored'}",
            {"issue_id": issue_id, "series_id": row["series_id"], "monitored": monitored, "wanted_items_cleared": wanted_items_cleared},
            now,
        )
        return {
            "ok": True,
            "issue": {
                "id": issue_id,
                "series_id": row["series_id"],
                "issue_number": row["issue_number"],
                "title": row["title"],
                "monitored": monitored,
            },
            "wanted_items_cleared": wanted_items_cleared,
        }


def upsert_wanted(con, series_id, issue_id, reason, status, raw, now):
    raw = raw if isinstance(raw, dict) else {}
    if series_id_user_removed(con, series_id):
        status = "inactive"
        reason = reason or "series_removed_by_user"
        removed_series_guard_raw(raw, now, REMOVED_SERIES_MESSAGE, "upsert_wanted")
    wid = f"wanted:{issue_id or stable_id(series_id, reason)}"
    con.execute(
        """
        insert into wanted_items(id, series_id, issue_id, reason, status, created_at, updated_at, raw_json)
        values(?,?,?,?,?,?,?,?)
        on conflict(id) do update set
            reason=excluded.reason,
            status=case
                -- queue_missing is sync_queue's own write, computed fresh from the
                -- live queue_items.state every pass -- it is the authoritative source
                -- for in_progress, so it must be allowed to demote back to wanted
                -- when the item is no longer actually in flight. Every other caller
                -- (provider/watch/readiness syncs) can still only add a *new* wanted
                -- item, never accidentally downgrade one that's genuinely in progress
                -- elsewhere. Without this, in_progress became a one-way ratchet:
                -- once set, nothing ever cleared it even after the download failed
                -- and went idle, so Wanted rows sat mislabeled "in progress" for
                -- weeks (see docs/inkdrop -- All Star Superman investigation).
                when wanted_items.status='in_progress' and excluded.status='wanted' and excluded.reason!='queue_missing' then wanted_items.status
                when wanted_items.status in ('satisfied','superseded_duplicate') and excluded.status='wanted' then wanted_items.status
                else excluded.status
            end,
            updated_at=excluded.updated_at,
            raw_json=case
                when wanted_items.status='superseded_duplicate' and excluded.status='wanted' then wanted_items.raw_json
                else excluded.raw_json
            end
        """,
        (wid, series_id, issue_id, reason, status, raw.get("created_at") or raw.get("firstSeen") or now, now, json_dumps(raw)),
    )
    return wid


def upsert_manga_companion_link(
    db_path,
    *,
    comicvine_series_id,
    mangadex_series_id,
    normalized_title,
    raw=None,
    status="linked",
    now=None,
):
    """Persist one provider-native ComicVine/MangaDex relationship idempotently."""
    comicvine_series_id = str(comicvine_series_id or "").strip()
    mangadex_series_id = str(mangadex_series_id or "").strip()
    normalized_title = str(normalized_title or "").strip()
    if not comicvine_series_id or not mangadex_series_id or not normalized_title:
        return {"ok": False, "error": "both provider series ids and normalized_title are required"}
    now = float(now or time.time())
    status = "preparing" if str(status or "linked").strip().lower() == "preparing" else "linked"
    link_id = stable_id("manga_companion", comicvine_series_id, mangadex_series_id)
    with connect(Path(db_path)) as con:
        init_schema(con)
        provider_rows = con.execute(
            "select id, title, metadata_provider from series where id in (?, ?)",
            (comicvine_series_id, mangadex_series_id),
        ).fetchall()
        by_id = {str(row["id"]): row for row in provider_rows}
        if comicvine_series_id not in by_id or mangadex_series_id not in by_id:
            return {"ok": False, "error": "both referenced provider series must exist", "code": "series_not_found"}
        if metadata_provider_key(by_id[comicvine_series_id]["metadata_provider"]) != "comicvine":
            return {"ok": False, "error": "comicvine_series_id is not a ComicVine series", "code": "provider_mismatch"}
        if metadata_provider_key(by_id[mangadex_series_id]["metadata_provider"]) != "mangadex":
            return {"ok": False, "error": "mangadex_series_id is not a MangaDex series", "code": "provider_mismatch"}
        def companion_title_key(value):
            text = unicodedata.normalize("NFKC", str(value or "")).casefold()
            return re.sub(r"[^\w]+", " ", text, flags=re.UNICODE).strip()

        comicvine_title = companion_title_key(by_id[comicvine_series_id]["title"])
        mangadex_title = companion_title_key(by_id[mangadex_series_id]["title"])
        expected_title = companion_title_key(normalized_title)
        if not expected_title or comicvine_title != expected_title or mangadex_title != expected_title:
            return {"ok": False, "error": "provider series normalized titles do not match", "code": "title_mismatch"}
        conflict = con.execute(
            """
            select id from manga_companion_links
            where status in ('linked','preparing') and id<>?
              and (comicvine_series_id=? or mangadex_series_id=?)
            limit 1
            """,
            (link_id, comicvine_series_id, mangadex_series_id),
        ).fetchone()
        if conflict:
            return {"ok": False, "error": "one provider series is already linked to another companion", "code": "one_to_one_conflict"}
        before = con.execute("select id from manga_companion_links where id=?", (link_id,)).fetchone()
        try:
            con.execute(
                """
                insert into manga_companion_links(
                    id, comicvine_series_id, mangadex_series_id, normalized_title,
                    status, created_at, updated_at, raw_json
                ) values(?,?,?,?,?,?,?,?)
                on conflict(id) do update set
                    normalized_title=excluded.normalized_title,
                    status=excluded.status,
                    updated_at=excluded.updated_at,
                    raw_json=excluded.raw_json
                """,
                (
                    link_id,
                    comicvine_series_id,
                    mangadex_series_id,
                    normalized_title,
                    status,
                    now,
                    now,
                    json_dumps(raw if isinstance(raw, dict) else {}),
                ),
            )
        except sqlite3.IntegrityError:
            return {"ok": False, "error": "one provider series is already linked to another companion", "code": "one_to_one_conflict"}
    return {
        "ok": True,
        "link_id": link_id,
        "created": before is None,
        "comicvine_series_id": comicvine_series_id,
        "mangadex_series_id": mangadex_series_id,
        "normalized_title": normalized_title,
    }


def schedule_manga_companion_job(
    db_path,
    *,
    seed_provider,
    seed_series_id,
    counterpart_provider,
    counterpart_metadata_id,
    normalized_title,
    candidate=None,
    auto_grab=True,
    raw=None,
    now=None,
):
    """Persist and reserve one provider-native companion before provider mutation."""
    seed_provider = metadata_provider_key(seed_provider)
    counterpart_provider = metadata_provider_key(counterpart_provider)
    seed_series_id = str(seed_series_id or "").strip()
    counterpart_metadata_id = str(counterpart_metadata_id or "").strip()
    normalized_title = str(normalized_title or "").strip()
    if seed_provider not in {"comicvine", "mangadex"} or counterpart_provider not in {"comicvine", "mangadex"}:
        return {"ok": False, "error": "unsupported companion provider", "code": "provider_mismatch"}
    if seed_provider == counterpart_provider:
        return {"ok": False, "error": "companion providers must differ", "code": "provider_mismatch"}
    if not seed_series_id or not counterpart_metadata_id or not normalized_title:
        return {"ok": False, "error": "companion job identity is incomplete", "code": "missing_identity"}
    now = float(now or time.time())
    counterpart_series_id = f"{counterpart_provider}:{counterpart_metadata_id}"
    comicvine_series_id = seed_series_id if seed_provider == "comicvine" else counterpart_series_id
    mangadex_series_id = seed_series_id if seed_provider == "mangadex" else counterpart_series_id
    job_id = stable_id("manga_companion_job", comicvine_series_id, mangadex_series_id)
    with connect(Path(db_path)) as con:
        init_schema(con)
        seed = con.execute(
            "select id, title, metadata_provider from series where id=?",
            (seed_series_id,),
        ).fetchone()
        if not seed:
            return {"ok": False, "error": "seed provider series does not exist", "code": "series_not_found"}
        if metadata_provider_key(seed["metadata_provider"]) != seed_provider:
            return {"ok": False, "error": "seed provider does not match the series", "code": "provider_mismatch"}

        def title_key(value):
            text = unicodedata.normalize("NFKC", str(value or "")).casefold()
            return re.sub(r"[^\w]+", " ", text, flags=re.UNICODE).strip()

        if title_key(seed["title"]) != title_key(normalized_title):
            return {"ok": False, "error": "seed title does not match the companion title", "code": "title_mismatch"}
        existing_link = con.execute(
            """
            select id, comicvine_series_id, mangadex_series_id, status
            from manga_companion_links
            where status in ('linked','preparing') and (
                comicvine_series_id in (?, ?) or mangadex_series_id in (?, ?)
            ) limit 1
            """,
            (seed_series_id, counterpart_series_id, seed_series_id, counterpart_series_id),
        ).fetchone()
        if existing_link:
            expected = {seed_series_id, counterpart_series_id}
            actual = {str(existing_link["comicvine_series_id"]), str(existing_link["mangadex_series_id"])}
            if actual == expected and str(existing_link["status"]) == "linked":
                return {"ok": True, "job_id": job_id, "status": "completed", "already_linked": True}
            if actual != expected:
                return {"ok": False, "error": "one provider series is already linked to another companion", "code": "one_to_one_conflict"}
        try:
            con.execute(
                """
                insert into manga_companion_jobs(
                    id, seed_provider, seed_series_id, counterpart_provider,
                    counterpart_metadata_id, comicvine_series_id, mangadex_series_id,
                    normalized_title, candidate_json,
                    auto_grab, status, attempt_count, created_at, updated_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                on conflict(id) do update set
                    candidate_json=case
                        when manga_companion_jobs.seed_provider=excluded.seed_provider then excluded.candidate_json
                        else manga_companion_jobs.candidate_json
                    end,
                    auto_grab=case
                        when manga_companion_jobs.seed_provider=excluded.seed_provider then excluded.auto_grab
                        else manga_companion_jobs.auto_grab
                    end,
                    status=case
                        when manga_companion_jobs.status in ('completed','running') then manga_companion_jobs.status
                        else 'scheduled'
                    end,
                    next_retry_at=case when manga_companion_jobs.status='running' then manga_companion_jobs.next_retry_at else null end,
                    lease_expires_at=case when manga_companion_jobs.status='running' then manga_companion_jobs.lease_expires_at else null end,
                    lease_token=case when manga_companion_jobs.status='running' then manga_companion_jobs.lease_token else null end,
                    updated_at=excluded.updated_at,
                    raw_json=excluded.raw_json
                """,
                (
                    job_id, seed_provider, seed_series_id, counterpart_provider,
                    counterpart_metadata_id, comicvine_series_id, mangadex_series_id, normalized_title,
                    json_dumps(candidate if isinstance(candidate, dict) else {}),
                    1 if auto_grab else 0, "scheduled", 0, now, now,
                    json_dumps(raw if isinstance(raw, dict) else {}),
                ),
            )
        except sqlite3.IntegrityError:
            return {"ok": False, "error": "one provider series already has another companion job", "code": "one_to_one_conflict"}
        row = con.execute("select status from manga_companion_jobs where id=?", (job_id,)).fetchone()
    return {"ok": True, "job_id": job_id, "status": str(row["status"] if row else "scheduled")}


def claim_manga_companion_jobs(db_path, *, limit=1, lease_seconds=900, now=None, job_id=None):
    now = float(now or time.time())
    limit = max(1, min(int(limit or 1), 4))
    lease_expires_at = now + max(60, int(lease_seconds or 0))
    with connect(Path(db_path), autocommit=True) as con:
        init_schema(con)
        con.execute("begin immediate")
        job_clause = " and id=?" if job_id else ""
        params = [now, now]
        if job_id:
            params.append(str(job_id))
        params.append(limit)
        rows = con.execute(
            f"""
            select * from manga_companion_jobs
            where (
                (status in ('scheduled','retry') and coalesce(next_retry_at, 0)<=?)
                or (status='running' and coalesce(lease_expires_at, 0)<=?)
            ){job_clause}
            order by created_at, updated_at
            limit ?
            """,
            tuple(params),
        ).fetchall()
        claimed = []
        for row in rows:
            lease_token = secrets.token_urlsafe(24)
            con.execute(
                """
                update manga_companion_jobs
                set status='running', attempt_count=attempt_count+1,
                    lease_expires_at=?, lease_token=?, updated_at=?
                where id=?
                """,
                (lease_expires_at, lease_token, now, row["id"]),
            )
            item = dict(row)
            item.update({"status": "running", "lease_expires_at": lease_expires_at, "lease_token": lease_token, "attempt_count": int(row["attempt_count"] or 0) + 1})
            item["candidate"] = json_loads(item.pop("candidate_json", "{}"), {})
            claimed.append(item)
        con.commit()
    return claimed


def renew_manga_companion_job_lease(db_path, job_id, *, lease_token, lease_seconds=900, now=None):
    now = float(now or time.time())
    lease_expires_at = now + max(60, int(lease_seconds or 0))
    with connect(Path(db_path)) as con:
        init_schema(con)
        cur = con.execute(
            """
            update manga_companion_jobs
            set lease_expires_at=?, updated_at=?
            where id=? and status='running' and lease_token=? and coalesce(lease_expires_at, 0)>?
            """,
            (lease_expires_at, now, str(job_id or ""), str(lease_token or ""), now),
        )
    return {"ok": bool(cur.rowcount), "job_id": str(job_id or ""), "lease_expires_at": lease_expires_at if cur.rowcount else None}


def activate_manga_companion_link_and_finish_job(db_path, job_id, *, lease_token, now=None):
    """Activate the prepared link only while the caller still owns the durable job."""
    now = float(now or time.time())
    with connect(Path(db_path), autocommit=True) as con:
        init_schema(con)
        con.execute("begin immediate")
        job = con.execute(
            """
            select comicvine_series_id, mangadex_series_id
            from manga_companion_jobs
            where id=? and status='running' and lease_token=? and coalesce(lease_expires_at, 0)>?
            """,
            (str(job_id or ""), str(lease_token or ""), now),
        ).fetchone()
        if not job:
            con.rollback()
            return {"ok": False, "job_id": str(job_id or ""), "reason": "lease_not_owned"}
        link = con.execute(
            """
            select id from manga_companion_links
            where comicvine_series_id=? and mangadex_series_id=? and status='preparing'
            """,
            (job["comicvine_series_id"], job["mangadex_series_id"]),
        ).fetchone()
        if not link:
            con.rollback()
            return {"ok": False, "job_id": str(job_id or ""), "reason": "prepared_link_missing"}
        con.execute(
            "update manga_companion_links set status='linked', last_refresh_status=null, updated_at=? where id=?",
            (now, link["id"]),
        )
        con.execute(
            """
            update manga_companion_jobs
            set status='completed', next_retry_at=null, lease_expires_at=null,
                lease_token=null, last_error=null, updated_at=?
            where id=? and status='running' and lease_token=?
            """,
            (now, str(job_id or ""), str(lease_token or "")),
        )
        converged = _sync_companion_folder_to_canonical(
            con, db_path, job["comicvine_series_id"], job["mangadex_series_id"], now
        )
        con.commit()
    return {
        "ok": True,
        "job_id": str(job_id or ""),
        "link_id": str(link["id"]),
        "status": "completed",
        "folder_converged": converged,
    }


def _sync_companion_folder_to_canonical(con, db_path, comicvine_series_id, mangadex_series_id, now):
    """Point a newly-linked manga companion at the canonical series' own folder.

    Kavita and Komga both group by the physical folder a file lives in, not by a
    matching ComicInfo Series name across folders -- verified live against a real
    Kavita instance on 2026-07-28: a companion left in its own separate folder
    displays as a second, incomplete series tile, and whichever folder a scan
    touches most recently silently drops the other folder's chapters from the
    reader's index. Skips if the setting is off or the canonical series has no
    real folder yet; never touches a companion pinned by library_path_source='user'.
    """
    if not media_management_bool_setting(db_path, "manga_companion_folder_convergence", True):
        return False
    canonical = con.execute(
        "select library_root, library_path from series where id=?", (comicvine_series_id,)
    ).fetchone()
    companion = con.execute(
        "select library_root, library_path, library_path_source from series where id=?",
        (mangadex_series_id,),
    ).fetchone()
    if not canonical or not companion:
        return False
    if str(companion["library_path_source"] or "").strip().lower() == "user":
        return False
    canonical_path = str(canonical["library_path"] or "").strip()
    if not canonical_path or canonical_path == str(companion["library_path"] or "").strip():
        return False
    con.execute(
        "update series set library_root=?, library_path=?, library_path_source='canonical_identity_sync', updated_at=? where id=?",
        (canonical["library_root"], canonical_path, now, mangadex_series_id),
    )
    return True


def finish_manga_companion_job(db_path, job_id, *, lease_token, ok, error=None, retry_seconds=300, now=None):
    now = float(now or time.time())
    status = "completed" if ok else "retry"
    next_retry_at = None if ok else now + max(60, int(retry_seconds or 0))
    with connect(Path(db_path)) as con:
        init_schema(con)
        cur = con.execute(
            """
            update manga_companion_jobs
            set status=?, next_retry_at=?, lease_expires_at=null, lease_token=null,
                last_error=?, updated_at=?
            where id=? and status='running' and lease_token=?
            """,
            (status, next_retry_at, None if ok else str(error or "companion job failed")[:300], now, str(job_id or ""), str(lease_token or "")),
        )
    return {"ok": bool(cur.rowcount), "job_id": str(job_id or ""), "status": status, "next_retry_at": next_retry_at}


def park_failed_manga_companion_setup(db_path, *, counterpart_series_id, job_id=None, error=None, now=None):
    """Keep partial companion setup from becoming acquisition or completion truth."""
    counterpart_series_id = str(counterpart_series_id or "").strip()
    now = float(now or time.time())
    if not counterpart_series_id:
        return {"ok": True, "parked": False}
    with connect(Path(db_path)) as con:
        init_schema(con)
        con.execute(
            "update series set monitored=0, monitor_new=0, auto_grab=0, updated_at=? where id=?",
            (now, counterpart_series_id),
        )
        con.execute(
            """
            update wanted_items set status='inactive', updated_at=?
            where series_id=? and status not in ('satisfied','superseded_duplicate')
            """,
            (now, counterpart_series_id),
        )
        con.execute(
            """
            update queue_items
            set state='inactive', active=0, last_event='Companion setup will retry', updated_at=?
            where series_id=? and state<>'verified'
            """,
            (now, counterpart_series_id),
        )
        con.execute(
            """
            update manga_companion_links
            set status='preparing', last_refresh_status='setup_retry', updated_at=?, raw_json=?
            where (comicvine_series_id=? or mangadex_series_id=?) and status in ('linked','preparing')
            """,
            (
                now,
                json_dumps({"job_id": str(job_id or ""), "error": str(error or "companion setup failed")[:300]}),
                counterpart_series_id,
                counterpart_series_id,
            ),
        )
    return {"ok": True, "parked": True, "series_id": counterpart_series_id}


