def record_manga_companion_reconcile_attempt(db_path, series_id, *, status, raw=None, retry_seconds=6 * 3600, now=None):
    now = float(now or time.time())
    status = str(status or "warning").strip().lower()
    next_retry_at = None if status == "linked" else now + max(60, int(retry_seconds or 0))
    with connect(Path(db_path)) as con:
        init_schema(con)
        con.execute(
            """
            insert into manga_companion_reconcile_attempts(
                series_id, status, attempt_count, last_attempt_at, next_retry_at, raw_json
            ) values(?,?,?,?,?,?)
            on conflict(series_id) do update set
                status=excluded.status,
                attempt_count=manga_companion_reconcile_attempts.attempt_count+1,
                last_attempt_at=excluded.last_attempt_at,
                next_retry_at=excluded.next_retry_at,
                raw_json=excluded.raw_json
            """,
            (str(series_id or ""), status, 1, now, next_retry_at, json_dumps(raw if isinstance(raw, dict) else {})),
        )
    return {"ok": True, "series_id": str(series_id or ""), "status": status, "next_retry_at": next_retry_at}


def due_mangadex_companion_links(db_path, *, limit=3, min_age_seconds=6 * 3600, now=None):
    now = float(now or time.time())
    cutoff = now - max(0, int(min_age_seconds or 0))
    limit = max(1, min(int(limit or 1), 20))
    with connect(Path(db_path), configure_wal=False) as con:
        init_schema(con)
        rows = con.execute(
            """
            select l.*, s.metadata_id as mangadex_id, s.title as mangadex_title,
                   s.monitored as mangadex_monitored, s.auto_grab as mangadex_auto_grab
            from manga_companion_links l
            join series s on s.id=l.mangadex_series_id
            where l.status='linked'
              and s.monitored=1
              and (l.last_refresh_at is null or l.last_refresh_at<=?)
            order by coalesce(l.last_refresh_at, 0), l.created_at
            limit ?
            """,
            (cutoff, limit),
        ).fetchall()
    return [dict(row) for row in rows]


