def record_series_added(
    db_path,
    volume,
    *,
    auto_grab=True,
    status="requested",
    source="comicvine",
    watch=None,
    kapowarr_volume=None,
    queue_update=None,
    error=None,
    include_summary=True,
    timeout_seconds=None,
    busy_timeout_ms=None,
    attempts=4,
    initial_delay=0.5,
):
    db_path = Path(db_path)
    now = time.time()
    volume = dict(volume or {})
    watch = dict(watch or {})
    kapowarr_volume = dict(kapowarr_volume or {})
    queue_update = dict(queue_update or {})
    payload = {}
    payload.update(volume)
    payload.update({key: value for key, value in watch.items() if value not in (None, "")})
    if kapowarr_volume.get("id") not in (None, ""):
        payload["kapowarrId"] = kapowarr_volume.get("id")
    payload.setdefault("comicvineId", volume.get("comicvineId") or volume.get("comicvine_id"))
    payload.setdefault("name", volume.get("name") or volume.get("title") or watch.get("name"))
    payload.setdefault("publisher", volume.get("publisher") or watch.get("publisher"))
    payload.setdefault("year", volume.get("year") or watch.get("year"))
    payload["source"] = source
    payload["enabled"] = True
    payload["autoGrab"] = bool(auto_grab)
    payload["monitorNew"] = True
    payload["created_at"] = now
    payload["inkdrop_explicit_user_add"] = True

    raw = {
        "volume": volume,
        "watch": watch,
        "kapowarr": kapowarr_volume,
        "queue": queue_update,
        "autoGrab": bool(auto_grab),
        "status": status,
        "error": error,
        "recorded_at": now,
        "recorded_at_iso": utc_stamp(now),
    }
    message_bits = [str(payload.get("name") or "Series"), str(status or "requested").replace("_", " ")]
    missing_issues = [issue for issue in watch.get("missingIssues") or [] if isinstance(issue, dict)]
    if queue_update or missing_issues:
        created = int(queue_update.get("created") or 0)
        updated = int(queue_update.get("updated") or 0)
        resurrected = int(queue_update.get("resurrected") or 0)
        missing = int(queue_update.get("missingIssues") or 0) or len(missing_issues)
        queued_hint = created + updated + resurrected
        if not queued_hint and not queue_update:
            queued_hint = len(missing_issues)
        message_bits.append(f"{queued_hint} queued")
        message_bits.append(f"{missing} missing")
    if error:
        message_bits.append(str(error)[:180])
    message = " - ".join(bit for bit in message_bits if bit)

    def _record():
        with connect(
            db_path,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
            configure_wal=timeout_seconds is None and busy_timeout_ms is None,
        ) as con:
            init_schema(con)
            series_id = upsert_series(con, payload, now)
            wanted_count = 0
            queue_count = 0
            should_record_queue = bool(queue_update) or bool(missing_issues)
            queue_recording_source = "legacy_queue_update" if queue_update else ("inkdrop_state_missing_issues" if missing_issues else "")
            for issue in missing_issues:
                issue_id = upsert_issue(con, series_id, issue, now)
                wanted_id = upsert_wanted(con, series_id, issue_id, "series_add_missing", "wanted", issue, now)
                wanted_count += 1
                if should_record_queue:
                    queue_id = upsert_queue_item_from_watch_issue(con, series_id, issue_id, wanted_id, watch or payload, issue, now)
                    if queue_id:
                        queue_count += 1
            dedupe_series_issue_numbers(con, series_id, now)
            event_type = "series_add_failed" if error else "series_added"
            event_id = stable_id("series_add", series_id, status, now)
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    event_id,
                    "series",
                    series_id,
                    series_id,
                    None,
                    event_type,
                    source,
                    message,
                    now,
                    json_dumps(raw),
                ),
            )
            update_sync_meta(con, now, "series_add")
        summary = state_summary(db_path) if include_summary else {"ok": True, "summary_skipped": True}
        summary.update(
            {
                "ok": True,
                "series_id": series_id,
                "event_type": event_type,
                "wanted_recorded": wanted_count,
                "queue_recorded": queue_count,
                "queue_recording_source": queue_recording_source,
                "recorded_at": now,
                "recorded_at_iso": utc_stamp(now),
            }
        )
        return summary

    lock_metrics = {}
    summary = with_db_lock_retry(
        _record,
        attempts=attempts,
        initial_delay=initial_delay,
        attempt_metrics=lock_metrics,
    )
    summary["lock_attempts"] = int(lock_metrics.get("attempts", 0) or 0)
    summary["lock_retries"] = int(lock_metrics.get("retries", 0) or 0)
    if "last_retry_error" in lock_metrics:
        summary["lock_last_retry_error"] = lock_metrics["last_retry_error"]
    return summary


def record_provider_series_catalog(
    db_path,
    *,
    provider,
    provider_series_id,
    title,
    metadata=None,
    items=None,
    monitored=True,
    auto_grab=True,
    now=None,
):
    provider = metadata_provider_key(provider)
    provider_series_id = str(provider_series_id or "").strip()
    if not provider:
        return {"ok": False, "error": "provider is required"}
    if not provider_series_id:
        return {"ok": False, "error": "provider_series_id is required"}
    metadata = metadata if isinstance(metadata, dict) else {}
    items = [item for item in (items or []) if isinstance(item, dict)]
    now = float(now or time.time())
    series_title = str(title or metadata.get("name") or metadata.get("title") or "Unknown").strip() or "Unknown"
    series_payload = {
        **metadata,
        "name": series_title,
        "title": series_title,
        "metadataProvider": provider,
        "metadataId": provider_series_id,
        "mediaType": metadata.get("mediaType") or metadata.get("media_type") or ("manga" if provider == "mangadex" else "comic"),
        "publisher": metadata.get("publisher") or source_display_label(provider),
        "year": metadata.get("year"),
        "source": provider,
        "owner": "inkdrop",
        "ownership": "native",
        "enabled": bool(monitored),
        "autoGrab": bool(auto_grab),
        "monitorNew": True,
        "created_at": now,
        "inkdrop_explicit_user_add": True,
        "provider_catalog": True,
        "provider_series_id": provider_series_id,
    }
    if provider == "mangadex":
        series_payload["mangadexId"] = provider_series_id
    issue_rows = []
    skipped = []
    with connect(Path(db_path)) as con:
        init_schema(con)
        series_id = upsert_series(con, series_payload, now)
        for item in items:
            number = str(item.get("issueNumber") or item.get("issue") or item.get("chapter") or "").strip()
            metadata_id = item.get("metadataId") or item.get("metadata_id") or item.get("id") or item.get("chapterId") or item.get("chapter_id")
            if not number and not metadata_id:
                skipped.append({"reason": "missing_issue_number_and_metadata_id", "item": item})
                continue
            issue_payload = {
                **item,
                "issueNumber": number or str(item.get("title") or metadata_id),
                "metadataProvider": item.get("metadataProvider") or item.get("metadata_provider") or provider,
                "metadataId": metadata_id,
                "title": item.get("title") or item.get("chapterTitle") or item.get("chapter_title") or "",
                "date": item.get("date") or item.get("publishAt") or item.get("readableAt"),
                "monitored": bool(item.get("monitored", monitored)),
                "status": item.get("status") or "catalog",
                "provider": provider,
                "provider_series_id": provider_series_id,
                "catalog_recorded_at": now,
                "catalog_recorded_at_iso": utc_stamp(now),
            }
            issue_id = upsert_issue(con, series_id, issue_payload, now)
            issue_rows.append(
                {
                    "issue_id": issue_id,
                    "issue_number": issue_payload["issueNumber"],
                    "metadata_id": str(metadata_id or ""),
                    "title": issue_payload.get("title") or "",
                    "raw": issue_payload,
                }
            )
        dedupe_series_issue_numbers(con, series_id, now)
        history_id = stable_id("provider_catalog_recorded", provider, provider_series_id, int(now * 1000))
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                history_id,
                "series",
                series_id,
                series_id,
                None,
                "provider_catalog_recorded",
                provider,
                f"{series_title} catalog recorded from {source_display_label(provider)}",
                now,
                json_dumps(
                    {
                        "provider": provider,
                        "provider_series_id": provider_series_id,
                        "series": series_title,
                        "items": len(issue_rows),
                        "skipped": skipped[:50],
                    }
                ),
            ),
        )
        update_sync_meta(con, now, "provider_catalog_recorded")
    return {
        "ok": True,
        "series_id": series_id,
        "series": series_title,
        "provider": provider,
        "provider_series_id": provider_series_id,
        "issue_recorded": len(issue_rows),
        "issues": issue_rows,
        "skipped": skipped,
        "history": {"ok": True, "event_id": history_id, "created_at": now, "created_at_iso": utc_stamp(now)},
    }


def upsert_provider_wanted_items(
    db_path,
    *,
    provider,
    series_id,
    missing_items,
    reason="provider_catalog_missing",
    now=None,
):
    provider = metadata_provider_key(provider)
    series_id = str(series_id or "").strip()
    if not provider:
        return {"ok": False, "error": "provider is required"}
    if not series_id:
        return {"ok": False, "error": "series_id is required"}
    now = float(now or time.time())
    wanted_rows = []
    skipped = []
    with connect(Path(db_path)) as con:
        init_schema(con)
        series = con.execute("select * from series where id=? limit 1", (series_id,)).fetchone()
        if not series:
            return {"ok": False, "error": "series not found", "series_id": series_id}
        if series_row_user_removed(series):
            retired = retire_removed_series_work(con, series_id, now, source="provider_wanted_removed_series")
            return {
                "ok": True,
                "series_id": series_id,
                "provider": provider,
                "wanted_recorded": 0,
                "wanted_ids": [],
                "wanted": [],
                "skipped": [{"reason": "series_removed_by_user", "series_id": series_id}],
                "retired": retired,
            }
        for item in missing_items or []:
            if not isinstance(item, dict):
                continue
            issue_id = str(item.get("issue_id") or "").strip()
            raw = item.get("raw") if isinstance(item.get("raw"), dict) else dict(item)
            if not issue_id:
                number = str(raw.get("issueNumber") or raw.get("issue") or raw.get("chapter") or item.get("issue_number") or "").strip()
                metadata_id = raw.get("metadataId") or raw.get("metadata_id") or raw.get("id") or item.get("metadata_id")
                if not number and not metadata_id:
                    skipped.append({"reason": "missing_issue_reference", "item": item})
                    continue
                raw.update(
                    {
                        "issueNumber": number or str(raw.get("title") or metadata_id),
                        "metadataProvider": raw.get("metadataProvider") or provider,
                        "metadataId": metadata_id,
                        "provider": provider,
                    }
                )
                issue_id = upsert_issue(con, series_id, raw, now)
            wanted_id = upsert_wanted(con, series_id, issue_id, reason, "wanted", raw, now)
            wanted_rows.append({"wanted_id": wanted_id, "issue_id": issue_id, "issue_number": raw.get("issueNumber") or item.get("issue_number")})
        history_id = stable_id("provider_wanted_upserted", provider, series_id, reason, int(now * 1000))
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                history_id,
                "series",
                series_id,
                series_id,
                None,
                "provider_wanted_upserted",
                provider,
                f"{len(wanted_rows)} wanted row(s) recorded from {source_display_label(provider)}",
                now,
                json_dumps({"provider": provider, "series_id": series_id, "wanted": len(wanted_rows), "skipped": skipped[:50]}),
            ),
        )
        update_sync_meta(con, now, "provider_wanted_upserted")
    return {
        "ok": True,
        "series_id": series_id,
        "provider": provider,
        "wanted_recorded": len(wanted_rows),
        "wanted_ids": [row["wanted_id"] for row in wanted_rows],
        "wanted": wanted_rows,
        "skipped": skipped,
        "history": {"ok": True, "event_id": history_id, "created_at": now, "created_at_iso": utc_stamp(now)},
    }


def enqueue_wanted_items(
    db_path,
    *,
    wanted_ids,
    source_order=None,
    recovery_steps=None,
    reason="provider_monitor_backfill",
    now=None,
):
    created_at = float(now or time.time())
    queued = []
    skipped = []
    for wanted_id in wanted_ids or []:
        wanted_id = str(wanted_id or "").strip()
        if not wanted_id:
            continue
        result = request_wanted_search(
            db_path,
            wanted_id,
            source_order=source_order,
            recovery_steps=recovery_steps,
            source=reason,
        )
        if result.get("ok"):
            queued.append(result)
        else:
            skipped.append({"wanted_id": wanted_id, "reason": result.get("reason") or result.get("error") or "queue_failed", "result": result})
    return {
        "ok": True,
        "queued": len(queued),
        "skipped": len(skipped),
        "queue_rows": queued,
        "skipped_rows": skipped,
        "wanted_ids": [row.get("wanted_id") for row in queued if row.get("wanted_id")],
        "created_at": created_at,
        "created_at_iso": utc_stamp(created_at),
    }


def _json_obj(value):
    if isinstance(value, dict):
        return dict(value)
    try:
        loaded = json.loads(value or "{}")
    except (TypeError, ValueError):
        return {}
    return loaded if isinstance(loaded, dict) else {}


def _row_value(row, key, default=None):
    if row is None:
        return default
    try:
        return row[key]
    except (KeyError, IndexError, TypeError):
        if isinstance(row, dict):
            return row.get(key, default)
    return default


def _issue_number_from_row(row, raw=None):
    raw = raw if isinstance(raw, dict) else {}
    return str(
        _row_value(row, "issue_number")
        or raw.get("issueNumber")
        or raw.get("issue")
        or raw.get("issue_number")
        or ""
    ).strip()


def replace_series_metadata(
    db_path,
    old_series_id,
    new_volume,
    *,
    issues=None,
    watch=None,
    auto_grab=None,
    source="comicvine",
):
    db_path = Path(db_path)
    old_series_id = str(old_series_id or "").strip()
    if old_series_id.isdigit():
        old_series_id = f"comicvine:{old_series_id}"
    if not old_series_id:
        raise ValueError("old series id is required")
    now = time.time()
    new_volume = dict(new_volume or {})
    watch = dict(watch or {})
    issues = [issue for issue in (issues or []) if isinstance(issue, dict)]
    payload = {}
    payload.update(new_volume)
    payload.update({key: value for key, value in watch.items() if value not in (None, "")})
    payload.setdefault("comicvineId", new_volume.get("comicvineId") or new_volume.get("comicvine_id"))
    payload.setdefault("name", new_volume.get("name") or new_volume.get("title") or watch.get("name"))
    payload.setdefault("publisher", new_volume.get("publisher") or watch.get("publisher"))
    payload.setdefault("year", new_volume.get("year") or watch.get("year"))
    payload["source"] = source

    with connect(db_path) as con:
        init_schema(con)
        old = con.execute("select * from series where id = ?", (old_series_id,)).fetchone()
        if not old:
            raise ValueError("old series was not found")
        if auto_grab is None:
            auto_grab = bool(old["auto_grab"])
        payload["enabled"] = bool(old["monitored"])
        payload["monitorNew"] = bool(old["monitor_new"])
        payload["autoGrab"] = bool(auto_grab)
        payload["created_at"] = now
        new_series_id = upsert_series(con, payload, now)
        new_title = payload.get("name") or payload.get("title") or old["title"]
        new_identity = new_series_id
        if new_series_id == old_series_id:
            update_sync_meta(con, now, "series_metadata_replaced")
            # state_summary opens its own connection, so without this commit it
            # reads the database as it was BEFORE this function's write -- and
            # then caches that pre-write snapshot for the next minute, undoing
            # the invalidation update_sync_meta just did two lines up. Report
            # what we wrote, not what was there before we wrote it.
            con.commit()
            summary = state_summary(db_path)
            summary.update(
                {
                    "ok": True,
                    "old_series_id": old_series_id,
                    "new_series_id": new_series_id,
                    "new_title": new_title,
                    "new_publisher": payload.get("publisher"),
                    "issue_mapped": 0,
                    "unmapped_issues": 0,
                    "wanted_moved": 0,
                    "queue_moved": 0,
                    "replaced_at": now,
                    "replaced_at_iso": utc_stamp(now),
                    "no_op": True,
                }
            )
            return summary

        new_issue_by_number = {}
        new_issue_raw_by_number = {}
        for issue in issues:
            new_issue_id = upsert_issue(con, new_series_id, issue, now)
            number = normalize_issue_number(issue.get("issueNumber") or issue.get("issue"))
            if number:
                new_issue_by_number[number] = new_issue_id
                new_issue_raw_by_number[number] = dict(issue)

        old_issues = con.execute(
            "select id, issue_number, normalized_number, raw_json from issues where series_id = ?",
            (old_series_id,),
        ).fetchall()
        issue_map = {}
        unmapped_issue_ids = []
        for old_issue in old_issues:
            number = normalize_issue_number(old_issue["normalized_number"] or old_issue["issue_number"])
            new_issue_id = new_issue_by_number.get(number)
            if new_issue_id:
                issue_map[old_issue["id"]] = new_issue_id
            else:
                unmapped_issue_ids.append(old_issue["id"])

        wanted_rows = con.execute("select * from wanted_items where series_id = ?", (old_series_id,)).fetchall()
        wanted_map = {}
        for row in wanted_rows:
            new_issue_id = issue_map.get(row["issue_id"])
            new_wanted_id = f"wanted:{new_issue_id or stable_id(new_series_id, row['reason'] or 'metadata_replace')}"
            wanted_map[row["id"]] = new_wanted_id
            raw = _json_obj(row["raw_json"])
            raw["metadata_replaced_from_series_id"] = old_series_id
            raw["metadata_replaced_from_wanted_id"] = row["id"]
            raw["metadata_replaced_at"] = now
            existing = con.execute("select status, priority from wanted_items where id = ?", (new_wanted_id,)).fetchone()
            if existing:
                chosen_status = row["status"]
                if existing["status"] in {"in_progress", "satisfied"}:
                    chosen_status = existing["status"]
                elif row["status"] == "wanted" and existing["status"]:
                    chosen_status = existing["status"]
                con.execute(
                    """
                    update wanted_items
                    set series_id=?, issue_id=?, reason=coalesce(reason, ?),
                        status=?, priority=max(priority, ?), updated_at=?, raw_json=?
                    where id=?
                    """,
                    (
                        new_series_id,
                        new_issue_id,
                        row["reason"],
                        chosen_status,
                        int(row["priority"] or 50),
                        now,
                        json_dumps(raw),
                        new_wanted_id,
                    ),
                )
            else:
                con.execute(
                    """
                    insert into wanted_items(id, series_id, issue_id, reason, status, priority, created_at, updated_at, raw_json)
                    values(?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        new_wanted_id,
                        new_series_id,
                        new_issue_id,
                        row["reason"],
                        row["status"],
                        int(row["priority"] or 50),
                        row["created_at"] or now,
                        now,
                        json_dumps(raw),
                    ),
                )

        queue_rows = con.execute("select * from queue_items where series_id = ?", (old_series_id,)).fetchall()
        queue_map = {}
        for row in queue_rows:
            raw = _json_obj(row["raw_json"])
            issue_number = _issue_number_from_row(
                con.execute("select issue_number, normalized_number from issues where id = ?", (row["issue_id"],)).fetchone(),
                raw,
            )
            new_issue_id = issue_map.get(row["issue_id"])
            if not issue_number and new_issue_id:
                new_issue_row = con.execute("select issue_number from issues where id = ?", (new_issue_id,)).fetchone()
                issue_number = str(_row_value(new_issue_row, "issue_number", "") or "").strip()
            if not issue_number:
                new_queue_id = stable_id("queue", new_series_id, row["id"])
            else:
                new_queue_id = queue_key_for_series_issue(new_title, issue_number, new_identity)
            queue_map[row["id"]] = new_queue_id
            new_wanted_id = wanted_map.get(row["wanted_id"])
            query = f"{new_title} {issue_number}".strip() if issue_number else (row["query"] or new_title)
            raw.update(
                {
                    "key": new_queue_id,
                    "queue_identity": new_identity,
                    "series": new_title,
                    "comicvine_id": payload.get("comicvineId") or payload.get("comicvine_id"),
                    "watch_year": payload.get("year"),
                    "watch_publisher": payload.get("publisher"),
                    "query": query,
                    "metadata_replaced_from_series_id": old_series_id,
                    "metadata_replaced_from_queue_id": row["id"],
                    "metadata_replaced_at": now,
                    "metadata_replaced_at_iso": utc_stamp(now),
                }
            )
            existing = con.execute("select * from queue_items where id = ?", (new_queue_id,)).fetchone()
            if existing:
                chosen_state = existing["state"]
                chosen_source = existing["current_source"]
                chosen_event = existing["last_event"]
                chosen_active = existing["active"]
                if queue_state_rank(row["state"]) > queue_state_rank(existing["state"]):
                    chosen_state = row["state"]
                    chosen_source = row["current_source"]
                    chosen_event = row["last_event"]
                    chosen_active = row["active"]
                status_columns = queue_provider_status_column_values(
                    chosen_state,
                    chosen_source,
                    chosen_event or "metadata replaced",
                    raw,
                )
                con.execute(
                    """
                    update queue_items
                    set wanted_id=coalesce(?, wanted_id), series_id=?, issue_id=coalesce(?, issue_id),
                        state=?, current_source=?, query=?, last_event=?,
                        active=max(active, ?), updated_at=?, outcome=?, display_phase=?,
                        provider_status_state=?, provider_status_phase=?, provider_status_provider=?,
                        provider_status_actionability=?, raw_json=?
                    where id=?
                    """,
                    (
                        new_wanted_id,
                        new_series_id,
                        new_issue_id,
                        chosen_state,
                        chosen_source,
                        query,
                        chosen_event or "metadata replaced",
                        int(chosen_active or 0),
                        now,
                        *status_columns,
                        json_dumps(raw),
                        new_queue_id,
                    ),
                )
            else:
                status_columns = queue_provider_status_column_values(
                    row["state"],
                    row["current_source"],
                    row["last_event"] or "metadata replaced",
                    raw,
                )
                con.execute(
                    """
                    insert into queue_items(
                        id, wanted_id, series_id, issue_id, state, current_source, query,
                        last_event, active, created_at, updated_at, source_order_json,
                        recovery_steps_json, outcome, display_phase, provider_status_state,
                        provider_status_phase, provider_status_provider,
                        provider_status_actionability, raw_json
                    ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        new_queue_id,
                        new_wanted_id,
                        new_series_id,
                        new_issue_id,
                        row["state"],
                        row["current_source"],
                        query,
                        row["last_event"] or "metadata replaced",
                        int(row["active"] or 0),
                        row["created_at"] or now,
                        now,
                        row["source_order_json"],
                        row["recovery_steps_json"],
                        *status_columns,
                        json_dumps(raw),
                    ),
                )

        for old_queue_id, new_queue_id in queue_map.items():
            con.execute("update source_attempts set queue_id=? where queue_id=?", (new_queue_id, old_queue_id))
            con.execute("update import_results set queue_id=? where queue_id=?", (new_queue_id, old_queue_id))
            con.execute(
                "update history_events set entity_id=? where entity_type='queue_item' and entity_id=?",
                (new_queue_id, old_queue_id),
            )
            con.execute("delete from queue_items where id=?", (old_queue_id,))

        for old_wanted_id, new_wanted_id in wanted_map.items():
            con.execute("update queue_items set wanted_id=? where wanted_id=?", (new_wanted_id, old_wanted_id))
            con.execute("update source_attempts set wanted_id=? where wanted_id=?", (new_wanted_id, old_wanted_id))
            con.execute("delete from wanted_items where id=?", (old_wanted_id,))

        for old_issue_id, new_issue_id in issue_map.items():
            for table in ("source_attempts", "import_results", "review_exceptions", "history_events"):
                con.execute(
                    f"update {table} set issue_id=? where series_id=? and issue_id=?",
                    (new_issue_id, old_series_id, old_issue_id),
                )
        for old_issue_id in unmapped_issue_ids:
            for table in ("source_attempts", "import_results", "review_exceptions", "history_events"):
                con.execute(
                    f"update {table} set issue_id=null where series_id=? and issue_id=?",
                    (old_series_id, old_issue_id),
                )

        for table in ("source_attempts", "import_results", "review_exceptions", "history_events"):
            con.execute(f"update {table} set series_id=? where series_id=?", (new_series_id, old_series_id))
        con.execute(
            "update history_events set entity_id=? where entity_type='series' and entity_id=?",
            (new_series_id, old_series_id),
        )
        for old_issue_id in [row["id"] for row in old_issues]:
            referenced = False
            for table in ("wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
                if con.execute(f"select 1 from {table} where issue_id=? limit 1", (old_issue_id,)).fetchone():
                    referenced = True
                    break
            if not referenced:
                con.execute("delete from issues where id=?", (old_issue_id,))

        dependent = False
        for table in ("issues", "wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
            if con.execute(f"select 1 from {table} where series_id=? limit 1", (old_series_id,)).fetchone():
                dependent = True
                break
        if dependent:
            con.execute(
                """
                update series
                set monitored=0, monitor_new=0, auto_grab=0, source='replaced_metadata',
                    updated_at=?, raw_json=?
                where id=?
                """,
                (
                    now,
                    json_dumps(
                        {
                            "replaced_by": new_series_id,
                            "new_volume": new_volume,
                            "replaced_at": now,
                            "replaced_at_iso": utc_stamp(now),
                        }
                    ),
                    old_series_id,
                ),
            )
        else:
            con.execute("delete from series where id=?", (old_series_id,))

        event_id = stable_id("series_metadata_replaced", old_series_id, new_series_id, now)
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                event_id,
                "series",
                new_series_id,
                new_series_id,
                None,
                "series_metadata_replaced",
                source,
                f"{old['title']} metadata replaced with {new_title}",
                now,
                json_dumps(
                    {
                        "old_series_id": old_series_id,
                        "old_title": old["title"],
                        "old_publisher": old["publisher"],
                        "new_series_id": new_series_id,
                        "new_title": new_title,
                        "new_publisher": payload.get("publisher"),
                        "issue_mapped": len(issue_map),
                        "wanted_moved": len(wanted_map),
                        "queue_moved": len(queue_map),
                    }
                ),
            ),
        )
        update_sync_meta(con, now, "series_metadata_replaced")

    summary = state_summary(db_path)
    summary.update(
        {
            "ok": True,
            "old_series_id": old_series_id,
            "new_series_id": new_series_id,
            "new_title": new_title,
            "new_publisher": payload.get("publisher"),
            "issue_mapped": len(issue_map),
            "unmapped_issues": len(unmapped_issue_ids),
            "wanted_moved": len(wanted_map),
            "queue_moved": len(queue_map),
            "replaced_at": now,
            "replaced_at_iso": utc_stamp(now),
        }
    )
    return summary


def wanted_status_for_queue_state(state):
    state = str(state or "").lower()
    if state == "verified":
        return "satisfied"
    if state in {"stale_source_absent", "inactive", "retired"}:
        return "inactive"
    if state in {"downloading", "importing", "searching", "source_wait"}:
        return "in_progress"
    if state in {"needs_you", "failed", "blocked"}:
        return "blocked"
    return "wanted"


def park_series_automation(db_path, series_id, reason="automation_parked", message=None, source="inkdrop_state", raw=None):
    series_id = str(series_id or "").strip()
    if not series_id:
        return {"ok": False, "error": "series_id is required"}
    now = time.time()
    message = str(message or "Series automation parked").strip() or "Series automation parked"
    raw = raw if isinstance(raw, dict) else {}
    with connect(Path(db_path)) as con:
        init_schema(con)
        series = con.execute("select * from series where id=?", (series_id,)).fetchone()
        if not series:
            return {"ok": False, "error": "series not found", "series_id": series_id}
        series_raw = json_loads(series["raw_json"] or "{}", {})
        if not isinstance(series_raw, dict):
            series_raw = {}
        wanted_active_statuses = ("wanted", "in_progress", "grabbed", "blocked", "searching")
        active_queue_count = int(
            con.execute(
                "select count(1) from queue_items where series_id=? and active=1",
                (series_id,),
            ).fetchone()[0]
            or 0
        )
        active_wanted_count = int(
            con.execute(
                f"""
                select count(1)
                from wanted_items
                where series_id=? and status in ({",".join("?" for _ in wanted_active_statuses)})
                """,
                (series_id, *wanted_active_statuses),
            ).fetchone()[0]
            or 0
        )
        if (
            series_raw.get("automation_parked")
            and series_raw.get("automation_parked_reason") == reason
            and not bool(series["monitored"])
            and not active_queue_count
            and not active_wanted_count
        ):
            return {
                "ok": True,
                "series_id": series_id,
                "series": series["title"],
                "reason": reason,
                "message": message,
                "alreadyParked": True,
                "queueParked": 0,
                "wantedInactivated": 0,
                "parkedAt": now,
                "parkedAtIso": utc_stamp(now),
            }
        series_raw.update(
            {
                "automation_parked": True,
                "automation_parked_reason": reason,
                "automation_parked_message": message,
                "automation_parked_at": now,
                "automation_parked_at_iso": utc_stamp(now),
            }
        )
        if str(reason or "").strip().lower() == "user_removed":
            series_raw.update(
                {
                    "removed_by_user": True,
                    "removed_at": now,
                    "removed_at_iso": utc_stamp(now),
                }
            )
        if raw:
            series_raw["automation_parked_context"] = raw
        con.execute(
            """
            update series
            set monitored=0,
                monitor_new=0,
                auto_grab=0,
                updated_at=?,
                raw_json=?
            where id=?
            """,
            (now, json_dumps(series_raw), series_id),
        )

        queue_rows = con.execute(
            """
            select id, wanted_id, issue_id, state, last_event, raw_json
            from queue_items
            where series_id=? and active=1
            """,
            (series_id,),
        ).fetchall()
        queue_count = 0
        for row in queue_rows:
            queue_raw = json_loads(row["raw_json"] or "{}", {})
            if not isinstance(queue_raw, dict):
                queue_raw = {}
            queue_raw.update(
                {
                    "previous_state": row["state"],
                    "previous_event": row["last_event"],
                    "parked_reason": reason,
                    "parked_at": now,
                    "parked_at_iso": utc_stamp(now),
                }
            )
            if raw:
                queue_raw["parked_context"] = raw
            cur = con.execute(
                """
                update queue_items
                set state='stale_source_absent',
                    current_source=null,
                    last_event=?,
                    active=0,
                    updated_at=?,
                    raw_json=?
                where id=? and active=1
                """,
                (message, now, json_dumps(queue_raw), row["id"]),
            )
            queue_count += int(cur.rowcount or 0)

        wanted_cur = con.execute(
            f"""
            update wanted_items
            set status='inactive', updated_at=?
            where series_id=? and status in ({",".join("?" for _ in wanted_active_statuses)})
            """,
            (now, series_id, *wanted_active_statuses),
        )
        wanted_count = int(wanted_cur.rowcount or 0)

        event_raw = {
            "reason": reason,
            "message": message,
            "series_id": series_id,
            "series_title": series["title"],
            "queue_parked": queue_count,
            "wanted_inactivated": wanted_count,
            "parked_at": now,
            "parked_at_iso": utc_stamp(now),
        }
        if raw:
            event_raw["context"] = raw
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("series_automation_parked", series_id, reason, now),
                "series",
                series_id,
                series_id,
                None,
                "series_automation_parked",
                source,
                message,
                now,
                json_dumps(event_raw),
            ),
        )
        update_sync_meta(con, now, "series_automation_parked")
    return {
        "ok": True,
        "series_id": series_id,
        "series": series["title"],
        "reason": reason,
        "message": message,
        "queueParked": queue_count,
        "wantedInactivated": wanted_count,
        "parkedAt": now,
        "parkedAtIso": utc_stamp(now),
    }


def series_ownership(source=None, metadata_provider=None, kapowarr_id=None):
    source = str(source or "").strip().lower()
    metadata_provider = str(metadata_provider or "").strip().lower()
    if source == "kapowarr":
        return "adapter"
    if source and source not in {"kapowarr", "watch", "manual"}:
        return "native"
    if metadata_provider and metadata_provider not in {"kapowarr", "watch", "manual"}:
        return "native"
    if kapowarr_id not in (None, ""):
        return "adapter"
    return source or metadata_provider or "manual"


def series_provenance(source=None, metadata_provider=None, kapowarr_id=None, raw=None):
    raw = raw if isinstance(raw, dict) else json_loads(raw or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    source_key = str(source or raw.get("source") or "").strip().lower()
    metadata_key = str(metadata_provider or raw.get("metadataProvider") or raw.get("metadata_provider") or "").strip().lower()
    adapter = str(raw.get("metadataAdapter") or raw.get("metadata_adapter") or "").strip().lower()
    adapter_role = str(raw.get("metadataAdapterRole") or raw.get("metadata_adapter_role") or raw.get("kapowarrRole") or "").strip()
    migrated_identity = str(raw.get("migrated_from_queue_identity") or raw.get("migratedFromQueueIdentity") or "").strip()
    adapter_state_source = str(raw.get("metadata_adapter_state_source") or raw.get("metadataAdapterStateSource") or "").strip()
    has_kapowarr = kapowarr_id not in (None, "") or raw.get("kapowarrId") not in (None, "") or raw.get("kapowarr_id") not in (None, "")
    adapter_adopted = bool(
        adapter
        or adapter_role
        or migrated_identity.startswith("kapowarr:")
        or adapter_state_source
        or (has_kapowarr and (source_key == "comicvine" or metadata_key == "comicvine"))
    )
    if adapter_adopted:
        origin = "kapowarr_adopted"
        label = "Metadata adopted"
        detail = "ComicVine-owned with an optional metadata/library adapter"
    elif source_key == "kapowarr" or metadata_key == "kapowarr":
        origin = "kapowarr_adapter"
        label = "Optional metadata adapter"
        detail = "Optional metadata adapter record"
    elif (source_key and source_key not in {"kapowarr", "watch", "manual"}) or (
        metadata_key and metadata_key not in {"kapowarr", "watch", "manual"}
    ):
        origin = f"{source_key or metadata_key}_native"
        label = "InkDrop-owned"
        provider_label = (source_key or metadata_key).replace("_", " ").title()
        detail = f"{provider_label} metadata owned by InkDrop"
    else:
        origin = source_key or metadata_key or "manual"
        label = origin.replace("_", " ").title() if origin != "manual" else "Manual"
        detail = label
    policy = str(raw.get("adapterBackfillPolicy") or raw.get("adapter_backfill_policy") or "").strip().lower()
    allowed_value = raw.get("adapterBackfillAllowed")
    allowed = None
    if allowed_value is not None:
        allowed = bool(allowed_value)
    if policy == "metadata_only":
        backfill_label = "metadata-only"
    elif policy == "explicit_backfill":
        backfill_label = "backfill allowed"
    elif adapter_adopted:
        backfill_label = "adapter bridge"
    else:
        backfill_label = ""
    return {
        "origin": origin,
        "label": label,
        "detail": detail,
        "adapter": adapter or ("kapowarr" if has_kapowarr else ""),
        "adapter_role": adapter_role,
        "adapter_state_source": adapter_state_source,
        "migrated_from_queue_identity": migrated_identity,
        "backfill_policy": policy,
        "backfill_allowed": allowed,
        "backfill_label": backfill_label,
        "backfill_missing_count": int(safe_float(raw.get("adapterBackfillMissingCount") or raw.get("adapter_backfill_missing_count"))),
        "backfill_updated_at": raw.get("adapterBackfillUpdatedAt"),
        "backfill_updated_at_iso": raw.get("adapterBackfillUpdatedAtIso") or raw.get("adapter_backfill_updated_at_iso"),
        "backfill_suppressed_at": raw.get("adapterBackfillSuppressedAt"),
        "backfill_suppressed_at_iso": raw.get("adapterBackfillSuppressedAtIso") or raw.get("adapter_backfill_suppressed_at_iso"),
    }


def ownership_evidence(source=None, metadata_provider=None, metadata_id=None, kapowarr_id=None, raw=None):
    raw = raw if isinstance(raw, dict) else json_loads(raw or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    source_key = str(source or raw.get("source") or "").strip().lower()
    metadata_key = str(metadata_provider or raw.get("metadataProvider") or raw.get("metadata_provider") or "").strip().lower()
    ownership = series_ownership(source_key, metadata_key, kapowarr_id)
    provenance = series_provenance(source_key, metadata_key, kapowarr_id, raw)
    adapter_provider = provenance.get("adapter") or ("kapowarr" if ownership == "adapter" else "")
    if metadata_key in {"comicvine", "mangadex"}:
        metadata_authority = metadata_key
        metadata_authority_role = "native_metadata"
    elif source_key in {"comicvine", "mangadex"}:
        metadata_authority = source_key
        metadata_authority_role = "native_metadata"
    elif adapter_provider:
        metadata_authority = adapter_provider
        metadata_authority_role = "metadata_adapter"
    elif metadata_key and metadata_key not in {"watch"}:
        metadata_authority = metadata_key
        metadata_authority_role = "manual_metadata" if metadata_key == "manual" else "metadata"
    else:
        metadata_authority = source_key or "manual"
        metadata_authority_role = "manual_metadata" if metadata_authority == "manual" else "metadata"
    detail = "InkDrop owns this state row."
    if adapter_provider:
        detail = f"InkDrop owns this state row; {source_display_label(adapter_provider)} supplies adapter metadata."
    elif metadata_authority_role == "native_metadata":
        detail = f"InkDrop owns this state row using {source_display_label(metadata_authority)} metadata."
    raw_truth = str(raw.get("source_of_truth") or "").strip().lower()
    raw_confidence = str(raw.get("source_of_truth_confidence") or "").strip().lower()
    raw_evidence = str(
        raw.get("source_of_truth_evidence")
        or raw.get("source_of_truth_detail")
        or raw.get("source_of_truth_label")
        or raw.get("provenance", {}).get("origin")
        or ""
    ).strip()
    confidence = raw_confidence if raw_confidence else (
        "high"
        if ownership == "native"
        else "adapter_only" if adapter_provider else "low"
    )
    evidence = raw_evidence or (
        f"{raw_truth}_owned" if raw_truth else
        "native_metadata_owned" if ownership == "native"
        else "kapowarr_adapter" if adapter_provider
        else "ownership_inferred"
    )
    return {
        "owner": "inkdrop",
        "ownership": ownership,
        "source_of_truth": "inkdrop_state",
        "source_of_truth_label": "InkDrop state",
        "source_of_truth_detail": detail,
        "source_of_truth_confidence": confidence,
        "source_of_truth_evidence": evidence,
        "metadata_authority": metadata_authority,
        "metadata_authority_id": str(metadata_id or raw.get("metadataId") or raw.get("metadata_id") or "").strip(),
        "metadata_authority_role": metadata_authority_role,
        "adapter_provider": adapter_provider or None,
        "adapter_role": provenance.get("adapter_role") or ("metadata_adapter" if adapter_provider else ""),
        "adapter_backed": bool(adapter_provider),
        "kapowarr_role": "metadata_adapter" if adapter_provider == "kapowarr" else "",
        "provenance": provenance,
    }


def apply_ownership_evidence(row, raw=None):
    evidence = ownership_evidence(
        source=row.get("series_source") or row.get("source"),
        metadata_provider=row.get("metadata_provider"),
        metadata_id=row.get("metadata_id"),
        kapowarr_id=row.get("kapowarr_id"),
        raw=raw,
    )
    row["owner"] = evidence["owner"]
    row["ownership"] = evidence["ownership"]
    row["source_of_truth"] = evidence["source_of_truth"]
    row["source_of_truth_label"] = evidence["source_of_truth_label"]
    row["source_of_truth_detail"] = evidence["source_of_truth_detail"]
    row["source_of_truth_confidence"] = evidence["source_of_truth_confidence"]
    row["source_of_truth_evidence"] = evidence["source_of_truth_evidence"]
    row["metadata_authority"] = evidence["metadata_authority"]
    row["metadata_authority_id"] = evidence["metadata_authority_id"]
    row["metadata_authority_role"] = evidence["metadata_authority_role"]
    row["adapter_provider"] = evidence["adapter_provider"]
    row["adapter_role"] = evidence["adapter_role"]
    row["adapter_backed"] = evidence["adapter_backed"]
    row["kapowarr_role"] = evidence["kapowarr_role"]
    row["ownership_evidence"] = evidence
    row.setdefault("provenance", evidence["provenance"])
    return row


def source_attempt_title(attempt):
    for key in ("title", "filename", "release_title", "name"):
        value = str((attempt or {}).get(key) or "").strip()
        if value:
            return value
    return ""


def source_attempt_message(attempt):
    source = str((attempt or {}).get("source") or "source").strip()
    status = str((attempt or {}).get("status") or "attempt").strip()
    title = source_attempt_title(attempt)
    reason = str((attempt or {}).get("reason") or "").strip()
    client = str((attempt or {}).get("download_client") or "").strip()
    provider = str((attempt or {}).get("provider") or (attempt or {}).get("indexer") or "").strip()
    message = f"{source} {status}".strip()
    if client:
        message = f"{message} via {client}"
    elif provider:
        message = f"{message} via {provider}"
    if title:
        message = f"{message}: {title}"
    if reason:
        message = f"{message} ({reason})"
    source_labels = (attempt or {}).get("source_order_labels")
    if source == "source_ladder" and isinstance(source_labels, list):
        plan = " -> ".join(str(value) for value in source_labels if str(value or "").strip())
        if plan:
            message = f"{message}; plan {plan}"
    slskd_status = str((attempt or {}).get("last_slskd_status") or "").strip()
    if source == "source_ladder" and slskd_status:
        candidate_count = int(safe_float((attempt or {}).get("last_slskd_candidate_count")))
        detected_count = int(safe_float((attempt or {}).get("last_slskd_detected_count")))
        if candidate_count or detected_count:
            message = f"{message}; SLSKD {slskd_status.replace('_', ' ')} ({candidate_count} candidates)"
        else:
            message = f"{message}; SLSKD {slskd_status.replace('_', ' ')}"
    repeat_count = int(safe_float((attempt or {}).get("coalesced_count") or (attempt or {}).get("repeat_count")))
    if repeat_count > 1:
        message = f"{message}; repeated {repeat_count} times"
    return message


