def normalize_slskd_terminal_recovery_attempt(attempt):
    """Apply one durable failed-candidate contract to every SLSKD terminal path."""
    attempt = dict(attempt or {})
    status = str(attempt.get("status") or "").strip().lower()
    source = str(attempt.get("source") or attempt.get("provider_id") or "").strip().lower()
    protocol = str(attempt.get("protocol") or "").strip().lower()
    client = normalized_download_client(
        attempt.get("download_client") or attempt.get("downloadClient") or attempt.get("client")
    ).lower()
    if (
        status not in SLSKD_TERMINAL_RECOVERY_STATUSES
        or (source not in {"slskd", "soulseek"} and protocol not in {"slskd", "soulseek"} and client != "slskd")
    ):
        return attempt
    attempt["lifecycle_phase"] = "failed_candidate"
    attempt["outcome"] = "problem"
    attempt["display_phase"] = "failed_candidate"
    attempt["retry_eligible"] = True
    attempt["terminal_recovery"] = True
    attempt.setdefault("retry_scope", "slskd_candidate")
    attempt.setdefault("next_automatic_step", "slskd_try_next_candidate")
    return attempt


def slskd_terminal_recovery_attempt(attempt):
    normalized = normalize_slskd_terminal_recovery_attempt(attempt)
    return bool(normalized.get("terminal_recovery"))


def active_slskd_successor_for_terminal_attempt(con, queue_id, attempt):
    """Return a different active SLSKD task that fences a late terminal event."""
    if not con or not queue_id or not slskd_terminal_recovery_attempt(attempt):
        return None
    attempt_ids = {
        normalize_download_task_identity(value)
        for value in (
            attempt.get("transfer_id"),
            attempt.get("slskd_transfer_id"),
            attempt.get("client_id"),
            attempt.get("candidate_identity"),
            attempt.get("filename"),
            attempt.get("source_path"),
            attempt.get("title"),
        )
        if value not in (None, "")
    }
    rows = con.execute(
        """
        select id, queue_id, source, provider, protocol, download_client, external_id,
               candidate_identity, title, status, state, started_at, updated_at, raw_json
        from download_tasks
        where queue_id=?
          and lower(coalesce(state, '')) in ('queued','downloading','import_ready','importing')
          and coalesce(completed_at, 0)<=0
          and (
                lower(coalesce(source, '')) in ('slskd','soulseek')
             or lower(coalesce(protocol, '')) in ('slskd','soulseek')
             or lower(coalesce(download_client, ''))='slskd'
          )
        order by coalesce(updated_at, started_at, 0) desc, id desc
        """,
        (queue_id,),
    ).fetchall()
    for row in rows:
        task = dict(row)
        task_ids = {
            normalize_download_task_identity(value)
            for value in (
                task.get("external_id"),
                task.get("candidate_identity"),
                task.get("title"),
            )
            if value not in (None, "")
        }
        if attempt_ids and task_ids and attempt_ids & task_ids:
            continue
        return task
    return None


