def normalize_download_task_identity(value):
    text = str(value or "").strip().lower().replace("/", "\\")
    text = re.sub(r"\s+", " ", text)
    return text


def download_task_path_leaf(value):
    text = str(value or "").strip().replace("/", "\\").rstrip("\\")
    if not text:
        return ""
    return text.rsplit("\\", 1)[-1]


def slskd_private_locator_digest(locator):
    """Bind an SLSKD locator to its peer, canonical remote path, and size."""
    locator = locator if isinstance(locator, dict) else {}
    provider = str(
        locator.get("username") or locator.get("provider") or locator.get("user") or ""
    ).strip().casefold()
    filename = str(
        locator.get("filename") or locator.get("remoteFilename") or locator.get("path") or ""
    ).strip()
    directory = str(locator.get("directory") or locator.get("remoteDirectory") or "").strip()

    def normalized(value):
        return re.sub(r"/+", "/", str(value or "").replace("\\", "/")).strip("/").casefold()

    filename = normalized(filename)
    directory = normalized(directory)
    if directory:
        if "/" not in filename:
            remote_path = f"{directory}/{filename}" if filename else ""
        elif filename == directory or filename.startswith(f"{directory}/"):
            remote_path = filename
        else:
            return ""
    else:
        remote_path = filename
    size = int(safe_float(
        locator.get("size") or locator.get("size_bytes") or locator.get("bytes"), 0
    ) or 0)
    if not all((provider, remote_path, size > 0)):
        return ""
    return hashlib.sha256(
        "|".join(("slskd", provider, remote_path, str(size))).encode("utf-8", errors="replace")
    ).hexdigest()


def download_task_raw_payload(task):
    task = task if isinstance(task, dict) else {}
    raw = task.get("raw_json") or task.get("raw") or {}
