def slskd_download_task_identity(task):
    task = task if isinstance(task, dict) else {}
    raw = download_task_raw_payload(task)
    raw = raw if isinstance(raw, dict) else {}
    username = normalize_key(
        download_task_first_value(
            task.get("provider"),
            raw.get("username"),
            raw.get("user"),
            raw.get("provider"),
        )
    )
    leaf = download_task_path_leaf(
        download_task_first_value(
            task.get("filename"),
            raw.get("filename"),
            raw.get("file_name"),
            raw.get("name"),
            task.get("local_path"),
            raw.get("local_path"),
            raw.get("localPath"),
            raw.get("path"),
            raw.get("download_path"),
            raw.get("downloadPath"),
            task.get("title"),
            raw.get("title"),
            task.get("external_id"),
            raw.get("external_id"),
            raw.get("externalId"),
        )
    )
    if username and leaf:
        return normalize_download_task_identity(f"{username}|{leaf}")
    return normalize_download_task_identity(leaf)


