def media_management_settings_contract(db_path):
    """Return effective persisted Media Management values with UI-safe schema."""
    db_path = Path(db_path)
    effective = media_management_settings_context(db_path)
    stored = {}
    if db_path.exists():
        with connect_read(db_path) as con:
            for row in con.execute(
                "select key, source, updated_at from app_settings where key like 'media_management.%'"
            ):
                stored[str(row["key"])] = {
                    "source": row["source"] or "sqlite",
                    "updated_at": row["updated_at"],
                }
    fields = {}
    for field, default in MEDIA_MANAGEMENT_SETTING_DEFAULTS.items():
        key = f"media_management.{field}"
        schema = inkdrop_settings_registry.field_schema(key)
        stored_row = stored.get(key)
        fields[field] = {
            "key": key,
            "value": effective.get(field, default),
            "default": default,
            "configured": stored_row is not None,
            "source": (stored_row or {}).get("source") or "default",
            "help": MEDIA_MANAGEMENT_SETTING_HELP.get(field, ""),
            "choices": list(schema.get("choices") or []),
            "validation": {
                name: schema[name]
                for name in ("kind", "min", "max", "integer")
                if name in schema
            },
            "editable": True,
            "restart_required": False,
            "advanced": field in {
                "library_visibility_required",
                "library_visibility_checks_enabled",
                "frontend_sync_after_import",
                "library_visibility_provider_order",
            },
            "updated_at": (stored_row or {}).get("updated_at"),
        }
    return {
        "schema": "inkdrop.media_management_settings.v1",
        "storage": "sqlite",
        "fields": fields,
        "effective_values": {field: item["value"] for field, item in fields.items()},
    }


def media_management_sanitize_component(value, *, replace_illegal=True, colon_replacement="smart"):
    text = str(value or "").strip().replace("\\", "/").strip()
    if not text:
        return ""
    colon_mode = str(colon_replacement or "smart").strip().lower()
    if colon_mode == "delete":
        text = text.replace(":", "")
    elif colon_mode in {"space", "smart"}:
        text = text.replace(":", " - ")
    else:
        text = text.replace(":", "-")
    replacement = "-" if boolish(replace_illegal, True) else ""
    text = re.sub(r"[\\/*?\"<>|]", replacement, text)
    text = re.sub(r"\s+", " ", text).strip()
    text = text.replace("/", replacement or "-").replace("\\", replacement or "-")
    text = re.sub(r"-{2,}", "-", text)
    text = text.strip(" .-")
    return text or "Unknown"


def media_management_format_number(value, fmt=None):
    text = str(value or "").strip()
    if not text:
        return ""
    fmt = str(fmt or "").strip()
    if not fmt:
        return text
    if re.fullmatch(r"0+", fmt):
        width = len(fmt)
        if re.fullmatch(r"\d+", text):
            return str(int(text)).zfill(width)
        if re.fullmatch(r"\d+\.0+", text):
            return str(int(text.split(".", 1)[0])).zfill(width)
    return text


def media_management_format_template(template, values):
    values = values if isinstance(values, dict) else {}

    def token_value(match):
        token = str(match.group(1) or "").strip().lower().replace("_", " ")
        fmt = match.group(2)
        aliases = {
            "series": "series_title",
            "series title": "series_title",
            "title": "series_title",
            "year": "year",
            "series year": "series_year",
            "start year": "series_year",
            "issue year": "issue_year",
            "release year": "issue_year",
            "publication year": "issue_year",
            "issue": "issue",
            "issue number": "issue",
            "volume": "volume",
            "chapter": "chapter",
            "chapter number": "chapter",
            "issue title": "issue_title",
            "extension": "extension",
        }
        key = aliases.get(token, token.replace(" ", "_"))
        value = values.get(key, "")
        if key in {"issue", "volume", "chapter"}:
            return media_management_format_number(value, fmt)
        return str(value or "")

    return re.sub(r"\{([^{}:]+)(?::([^{}]+))?\}", token_value, str(template or ""))


def media_management_manga_effective_chapter_format(template, values):
    template = str(template or "{Series Title} c{Chapter:000}")
    values = values if isinstance(values, dict) else {}
    if str(values.get("volume") or "").strip():
        return template, ""
    adjusted = re.sub(
        r"(?i)(^|\s+)v\s*\{\s*Volume\s*(?::[^{}]+)?\s*\}",
        " ",
        template,
    )
    adjusted = re.sub(
        r"(?i)(^|\s+)vol(?:ume)?\.?\s*\{\s*Volume\s*(?::[^{}]+)?\s*\}",
        " ",
        adjusted,
    )
    adjusted = re.sub(r"\s+", " ", adjusted).strip()
    if not adjusted or "{Chapter" not in adjusted:
        adjusted = "{Series Title} c{Chapter:000}"
    if adjusted != template:
        return adjusted, "dropped_empty_volume_token"
    return template, ""


def persisted_series_library_identity(db_path, work_id):
    work_id = str(work_id or "").strip()
    if not work_id or not Path(db_path).exists():
        return {}
    with connect_read(db_path) as con:
        if table_exists(con, "canonical_library_identities"):
            columns = {row["name"] for row in con.execute("pragma table_info(canonical_library_identities)")}
            reader_series_sql = "reader_series_id" if "reader_series_id" in columns else "null"
            reader_library_sql = "reader_library_id" if "reader_library_id" in columns else "null"
            reader_source_sql = "reader_binding_source" if "reader_binding_source" in columns else "null"
            identity_row = con.execute(
                f"select work_id,library_type,series_folder,{reader_series_sql} as reader_series_id,{reader_library_sql} as reader_library_id,{reader_source_sql} as reader_binding_source,created_at,updated_at from canonical_library_identities where work_id=? limit 1",
                (work_id,),
            ).fetchone()
            if identity_row:
                return dict(identity_row)
        row = con.execute("select raw_json from series where id=? limit 1", (work_id,)).fetchone()
    raw = json_loads(row["raw_json"] or "{}", {}) if row else {}
    identity = raw.get("canonical_library_identity_v1") if isinstance(raw, dict) else {}
    return dict(identity or {}) if isinstance(identity, dict) else {}


def persisted_series_folder_identity(db_path, work_id):
    return str(persisted_series_library_identity(db_path, work_id).get("series_folder") or "").strip()


def normalized_library_folder_identity(value):
    return re.sub(r"\s+", " ", str(value or "").strip().replace("\\", "/").rstrip("/")).casefold()


def normalized_reader_identity(value):
    return str(value or "").strip().casefold()


def reader_binding_for_work(db_path, work_id):
    identity = persisted_series_library_identity(db_path, work_id)
    if not identity.get("reader_series_id") or not identity.get("reader_library_id"):
        return {}
    source = str(identity.get("reader_binding_source") or "").strip()
    if source != "operator_approved_cli":
        return {}
    normalized_pair = (
        normalized_reader_identity(identity["reader_library_id"]),
        normalized_reader_identity(identity["reader_series_id"]),
    )
    with connect_read(db_path) as con:
        if table_exists(con, "canonical_library_identities"):
            columns = {row["name"] for row in con.execute("pragma table_info(canonical_library_identities)")}
            if {"reader_series_id", "reader_library_id"}.issubset(columns):
                rows = con.execute(
                    "select work_id,reader_series_id,reader_library_id from canonical_library_identities "
                    "where reader_series_id is not null and reader_library_id is not null"
                ).fetchall()
                owners = {
                    str(row["work_id"])
                    for row in rows
                    if (
                        normalized_reader_identity(row["reader_library_id"]),
                        normalized_reader_identity(row["reader_series_id"]),
                    ) == normalized_pair
                }
                if owners != {str(work_id)}:
                    return {}
    return {
        "work_id": str(work_id),
        "reader_series_id": str(identity["reader_series_id"]),
        "reader_library_id": str(identity["reader_library_id"]),
        "source": source,
    }


def persist_reader_binding(db_path, work_id, reader_series_id, reader_library_id, *, source, now=None):
    source = str(source or "").strip()
    if source != "operator_approved_cli":
        return {"ok": False, "reason": "reader_binding_not_authoritative"}
    work_id = str(work_id or "").strip()
    proposed = (str(reader_series_id or "").strip(), str(reader_library_id or "").strip())
    normalized_proposed = (normalized_reader_identity(proposed[0]), normalized_reader_identity(proposed[1]))
    if not work_id or not all(normalized_proposed):
        return {"ok": False, "reason": "reader_binding_identity_missing"}
    now = float(now or time.time())
    with connect(db_path) as con:
        con.execute("begin immediate")
        if not table_exists(con, "canonical_library_identities"):
            return {"ok": False, "reason": "canonical_work_identity_missing"}
        ensure_columns(
            con,
            "canonical_library_identities",
            {
                "reader_series_id": "text", "reader_library_id": "text",
                "normalized_reader_series_id": "text", "normalized_reader_library_id": "text",
                "reader_binding_source": "text",
            },
        )
        bound_rows = con.execute(
            "select work_id,reader_series_id,reader_library_id from canonical_library_identities "
            "where reader_series_id is not null and reader_library_id is not null"
        ).fetchall()
        owners = {}
        duplicate_work_ids = set()
        for bound_row in bound_rows:
            key = (
                normalized_reader_identity(bound_row["reader_library_id"]),
                normalized_reader_identity(bound_row["reader_series_id"]),
            )
            if not all(key):
                continue
            previous = owners.get(key)
            if previous and previous != bound_row["work_id"]:
                duplicate_work_ids.update({previous, bound_row["work_id"]})
            owners[key] = bound_row["work_id"]
        if duplicate_work_ids:
            placeholders = ",".join("?" for _ in duplicate_work_ids)
            con.execute(
                f"update canonical_library_identities set review_reason='existing_reader_binding_collision',updated_at=? where work_id in ({placeholders})",
                (now, *sorted(duplicate_work_ids)),
            )
            return {"ok": False, "reason": "existing_reader_binding_collision", "conflicting_work_ids": sorted(duplicate_work_ids)}
        for bound_row in bound_rows:
            con.execute(
                "update canonical_library_identities set normalized_reader_series_id=?,normalized_reader_library_id=? where work_id=?",
                (
                    normalized_reader_identity(bound_row["reader_series_id"]),
                    normalized_reader_identity(bound_row["reader_library_id"]),
                    bound_row["work_id"],
                ),
            )
        con.execute(
            "create unique index if not exists idx_canonical_reader_binding_unique "
            "on canonical_library_identities(normalized_reader_library_id,normalized_reader_series_id) "
            "where normalized_reader_library_id is not null and normalized_reader_library_id<>'' "
            "and normalized_reader_series_id is not null and normalized_reader_series_id<>''"
        )
        row = con.execute(
            "select reader_series_id,reader_library_id from canonical_library_identities where work_id=? limit 1",
            (work_id,),
        ).fetchone()
        if not row:
            return {"ok": False, "reason": "canonical_work_identity_missing"}
        existing = (str(row["reader_series_id"] or "").strip(), str(row["reader_library_id"] or "").strip())
        normalized_existing = (normalized_reader_identity(existing[0]), normalized_reader_identity(existing[1]))
        if all(normalized_existing) and normalized_existing != normalized_proposed:
            return {"ok": False, "reason": "reader_binding_conflict"}
        collision = con.execute(
            "select work_id from canonical_library_identities where normalized_reader_library_id=? "
            "and normalized_reader_series_id=? and work_id<>? limit 1",
            (normalized_proposed[1], normalized_proposed[0], work_id),
        ).fetchone()
        if collision:
            return {"ok": False, "reason": "reader_binding_collision", "conflicting_work_id": collision["work_id"]}
        con.execute(
            "update canonical_library_identities set reader_series_id=?,reader_library_id=?,normalized_reader_series_id=?,"
            "normalized_reader_library_id=?,reader_binding_source=?,updated_at=? where work_id=?",
            (*proposed, normalized_proposed[0], normalized_proposed[1], source, now, work_id),
        )
        return {"ok": True, "reader_series_id": proposed[0], "reader_library_id": proposed[1], "source": source}


def _sync_series_library_path_to_canonical_folder(con, work_id, series_folder, now):
    """Repoint series.library_path at the durable canonical folder once confirmed.

    Without this, a series row can keep the folder name it was created with
    (from an earlier, differently-normalized title-to-folder computation)
    even after canonical_library_identities has locked in a different folder
    as the one imports actually use. The stale folder is left behind, empty,
    and library readers keep rescanning it as a second, incomplete copy of
    the same series.
    """
    row = con.execute(
        "select library_root, library_path, library_path_source from series where id=? limit 1",
        (work_id,),
    ).fetchone()
    if not row:
        return
    if str(row["library_path_source"] or "").strip().lower() == "user":
        return
    library_root = str(row["library_root"] or "").strip()
    series_folder = str(series_folder or "").strip()
    if not library_root or not series_folder:
        return
    expected_path = f"{library_root.rstrip('/')}/{series_folder}"
    current_path = str(row["library_path"] or "").strip()
    if current_path.rstrip("/") == expected_path.rstrip("/"):
        return
    con.execute(
        "update series set library_path=?,library_path_source='canonical_identity_sync',updated_at=max(coalesce(updated_at,0),?) where id=?",
        (expected_path, now, work_id),
    )


def persist_series_folder_identity(db_path, work_id, series_folder, *, library_type, now=None):
    work_id = str(work_id or "").strip()
    series_folder = str(series_folder or "").strip()
    if not work_id or not series_folder:
        return {"ok": False, "reason": "missing_work_or_folder_identity"}
    now = float(now or time.time())
    with connect(db_path) as con:
        con.execute("begin immediate")
        con.execute(
            """
            create table if not exists canonical_library_identities(
                work_id text primary key,
                library_type text not null,
                series_folder text not null,
                normalized_library_type text not null,
                normalized_series_folder text not null,
                reader_series_id text,
                reader_library_id text,
                normalized_reader_series_id text,
                normalized_reader_library_id text,
                reader_binding_source text,
                created_at real not null,
                updated_at real not null,
                review_reason text,
                proposed_library_type text,
                proposed_series_folder text
            )
            """
        )
        ensure_columns(
            con,
            "canonical_library_identities",
            {
                "normalized_library_type": "text", "normalized_series_folder": "text",
                "reader_series_id": "text", "reader_library_id": "text",
                "normalized_reader_series_id": "text", "normalized_reader_library_id": "text",
                "reader_binding_source": "text",
            },
        )
        existing_rows = con.execute(
            "select work_id,library_type,series_folder from canonical_library_identities"
        ).fetchall()
        owners = {}
        duplicate_work_ids = set()
        for existing_row in existing_rows:
            key = (
                normalized_library_folder_identity(existing_row["library_type"]),
                normalized_library_folder_identity(existing_row["series_folder"]),
            )
            previous = owners.get(key)
            if previous and previous != existing_row["work_id"]:
                duplicate_work_ids.update({previous, existing_row["work_id"]})
            owners[key] = existing_row["work_id"]
        if duplicate_work_ids:
            placeholders = ",".join("?" for _ in duplicate_work_ids)
            con.execute(
                f"update canonical_library_identities set review_reason='existing_canonical_series_folder_collision',updated_at=? where work_id in ({placeholders})",
                (now, *sorted(duplicate_work_ids)),
            )
            return {"ok": False, "reason": "existing_canonical_series_folder_collision", "conflicting_work_ids": sorted(duplicate_work_ids)}
        for existing_row in existing_rows:
            con.execute(
                "update canonical_library_identities set normalized_library_type=?,normalized_series_folder=? where work_id=?",
                (
                    normalized_library_folder_identity(existing_row["library_type"]),
                    normalized_library_folder_identity(existing_row["series_folder"]),
                    existing_row["work_id"],
                ),
            )
        con.execute(
            "create unique index if not exists idx_canonical_library_folder_unique on canonical_library_identities(normalized_library_type,normalized_series_folder)"
        )
        normalized_library = normalized_library_folder_identity(library_type)
        normalized_folder = normalized_library_folder_identity(series_folder)
        collision = con.execute(
            "select work_id from canonical_library_identities where normalized_library_type=? and normalized_series_folder=? and work_id<>? limit 1",
            (normalized_library, normalized_folder, work_id),
        ).fetchone()
        if collision:
            return {"ok": False, "reason": "canonical_series_folder_collision", "conflicting_work_id": collision["work_id"]}
        durable = con.execute(
            "select library_type,series_folder from canonical_library_identities where work_id=? limit 1",
            (work_id,),
        ).fetchone()
        if durable:
            persisted_library = str(durable["library_type"] or "").strip()
            persisted = str(durable["series_folder"] or "").strip()
            if persisted_library != str(library_type or "") or persisted.casefold() != series_folder.casefold():
                reason = "persisted_library_classification_requires_review" if persisted_library != str(library_type or "") else "persisted_folder_migration_requires_review"
                con.execute(
                    "update canonical_library_identities set review_reason=?,proposed_library_type=?,proposed_series_folder=?,updated_at=? where work_id=?",
                    (reason, str(library_type or ""), series_folder, now, work_id),
                )
                return {"ok": False, "reason": reason, "library_type": persisted_library, "series_folder": persisted}
            _sync_series_library_path_to_canonical_folder(con, work_id, persisted, now)
            return {"ok": True, "reason": "persisted_folder_identity", "library_type": persisted_library, "series_folder": persisted}
        con.execute(
            "insert into canonical_library_identities(work_id,library_type,series_folder,normalized_library_type,normalized_series_folder,created_at,updated_at) values(?,?,?,?,?,?,?)",
            (work_id, str(library_type or "unknown"), series_folder, normalized_library, normalized_folder, now, now),
        )
        row = con.execute("select raw_json from series where id=? limit 1", (work_id,)).fetchone()
        if not row:
            return {"ok": True, "reason": "persisted_folder_identity", "library_type": str(library_type or "unknown"), "series_folder": series_folder}
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        current = raw.get("canonical_library_identity_v1")
        current = current if isinstance(current, dict) else {}
        persisted = str(current.get("series_folder") or "").strip()
        persisted_library = str(current.get("library_type") or "").strip()
        if persisted_library and library_type and persisted_library != str(library_type):
            current.update({
                "library_classification_review_required": True,
                "proposed_library_type": str(library_type),
                "library_classification_drift_at": now,
            })
            raw["canonical_library_identity_v1"] = current
            con.execute("update series set raw_json=?,updated_at=max(coalesce(updated_at,0),?) where id=?", (json_dumps(raw), now, work_id))
            return {"ok": False, "reason": "persisted_library_classification_requires_review", "library_type": persisted_library, "series_folder": persisted}
        if persisted and persisted.casefold() != series_folder.casefold():
            current.update({
                "folder_migration_required": True,
                "proposed_series_folder": series_folder,
                "folder_migration_detected_at": now,
            })
            raw["canonical_library_identity_v1"] = current
            con.execute("update series set raw_json=?,updated_at=max(coalesce(updated_at,0),?) where id=?", (json_dumps(raw), now, work_id))
            return {"ok": False, "reason": "persisted_folder_migration_requires_review", "series_folder": persisted}
        current.update({
            "contract_version": 1,
            "work_id": work_id,
            "library_type": str(library_type or "unknown"),
            "series_folder": persisted or series_folder,
            "persisted_at": current.get("persisted_at") or now,
            "updated_at": now,
        })
        raw["canonical_library_identity_v1"] = current
        con.execute("update series set raw_json=?,updated_at=max(coalesce(updated_at,0),?) where id=?", (json_dumps(raw), now, work_id))
        _sync_series_library_path_to_canonical_folder(con, work_id, current["series_folder"], now)
        return {"ok": True, "reason": "persisted_folder_identity", "series_folder": current["series_folder"]}


def media_management_source_extension(path, default=".cbz"):
    leaf = str(path or "").replace("\\", "/").rsplit("/", 1)[-1].strip()
    if "." not in leaf:
        return default
    ext = leaf.rsplit(".", 1)[-1].strip().lower()
    if not ext or len(ext) > 12 or not re.fullmatch(r"[a-z0-9]+", ext):
        return default
    return f".{ext}"


def media_management_minimum_free_space_gb(settings):
    try:
        return max(0.0, float((settings or {}).get("minimum_free_space_gb") or 0))
    except (TypeError, ValueError):
        return 0.0


def media_management_disk_usage(path):
    text = str(path or "").strip()
    if not text:
        return {"available": False, "reason": "missing_path"}
    probe = Path(text)
    try:
        while not probe.exists() and probe != probe.parent:
            probe = probe.parent
        if not probe.exists():
            return {"available": False, "reason": "path_missing", "probe_path": str(probe)}
        usage = shutil.disk_usage(probe)
        return {
            "available": True,
            "probe_path": str(probe),
            "free_bytes": int(usage.free),
            "free_space_gb": round(float(usage.free) / float(1024 ** 3), 2),
        }
    except (OSError, RuntimeError, ValueError) as exc:
        return {
            "available": False,
            "reason": f"{type(exc).__name__}: {exc}",
            "probe_path": str(probe),
        }


def media_management_preview_year(row):
    row = row if isinstance(row, dict) else {}
    for key in ("issue_year", "canonical_year", "release_year", "year", "start_year", "watch_year", "series_year"):
        value = str(row.get(key) or "").strip()
        if re.fullmatch(r"\d{4}", value):
            return value
    for key in ("release_date", "issue_date", "date", "created_at_iso"):
        value = str(row.get(key) or "").strip()
        match = re.search(r"\b(19|20)\d{2}\b", value)
        if match:
            return match.group(0)
    return ""


def media_management_series_year(row):
    row = row if isinstance(row, dict) else {}
    for key in ("series_year", "start_year", "watch_year", "year"):
        value = str(row.get(key) or "").strip()
        if re.fullmatch(r"\d{4}", value):
            return value
    return ""


def media_management_issue_year(row):
    row = row if isinstance(row, dict) else {}
    for key in ("issue_year", "canonical_year", "release_year"):
        value = str(row.get(key) or "").strip()
        if re.fullmatch(r"\d{4}", value):
            return value
    for key in ("release_date", "issue_date", "date", "created_at_iso"):
        value = str(row.get(key) or "").strip()
        match = re.search(r"\b(19|20)\d{2}\b", value)
        if match:
            return match.group(0)
    for key in ("year", "series_year", "start_year", "watch_year"):
        value = str(row.get(key) or "").strip()
        if re.fullmatch(r"\d{4}", value):
            return value
    return ""


MANGA_UNIT_POLICY_TO_MODEL = {
    "volume_only": "volume",
    "chapter_native": "chapter",
    "pack_only": "pack",
    "mixed_allowed": "mixed_volume_preferred",
    "mixed_volume_preferred": "mixed_volume_preferred",
    "mixed_chapter_preferred": "mixed_chapter_preferred",
    "manual_review": "unknown/manual",
    "unknown_manual": "unknown/manual",
    "unknown/manual": "unknown/manual",
}
MANGA_UNIT_MODEL_TO_POLICY = {
    "volume": "volume_only",
    "chapter": "chapter_native",
    "pack": "pack_only",
    "mixed_volume_preferred": "mixed_allowed",
    "mixed_chapter_preferred": "mixed_allowed",
    "unknown/manual": "manual_review",
}
MANGA_UNIT_POLICY_LABELS = {
    "volume_only": "Volume only",
    "chapter_native": "Chapter native",
    "pack_only": "Pack only",
    "mixed_allowed": "Volumes and chapters",
    "mixed_volume_preferred": "Volumes and chapters",
    "mixed_chapter_preferred": "Chapters and volumes",
    "manual_review": "Manual review",
}
MANGA_UNIT_CHAPTER_ALLOWED_MODELS = {"chapter", "mixed_volume_preferred", "mixed_chapter_preferred"}
MANGA_UNIT_VOLUME_ALLOWED_MODELS = {"volume", "pack", "mixed_volume_preferred", "mixed_chapter_preferred"}


def normalize_manga_unit_model(value):
    raw = str(value or "unknown/manual").strip().lower().replace("-", "_").replace(" ", "_")
    if raw in MANGA_UNIT_POLICY_TO_MODEL:
        return MANGA_UNIT_POLICY_TO_MODEL[raw]
    raw = raw.replace("unknown_manual", "unknown/manual")
    return raw if raw in MANGA_UNIT_MODEL_TO_POLICY else "unknown/manual"


def manga_unit_policy_for_model(model):
    return MANGA_UNIT_MODEL_TO_POLICY.get(normalize_manga_unit_model(model), "manual_review")


def manga_unit_policy_label(policy_or_model):
    raw = str(policy_or_model or "").strip().lower().replace("-", "_").replace(" ", "_")
    policy = raw if raw in MANGA_UNIT_POLICY_TO_MODEL else manga_unit_policy_for_model(policy_or_model)
    return MANGA_UNIT_POLICY_LABELS.get(policy, policy.replace("_", " ").title())


def media_management_manga_unit_policy(row):
    row = row if isinstance(row, dict) else {}
    raw_dicts = []
    for key in ("raw_json", "queue_raw_json", "import_raw_json", "issue_raw_json", "attempt_raw_json", "download_raw_json"):
        value = row.get(key)
        if isinstance(value, str):
            value = json_loads(value or "{}", {})
        if isinstance(value, dict):
            raw_dicts.extend(list(iter_import_result_raw_sources(value)))
    raw_dicts.insert(0, row)

    policy = None
    policy_source = None
    model = None
    model_source = None
    source_unit = ""
    for item in raw_dicts:
        if not isinstance(item, dict):
            continue
        if not source_unit:
            unit = str(item.get("source_unit") or item.get("unit_type") or item.get("unitType") or "").strip().lower()
            if unit:
                source_unit = normalize_manga_unit_model(unit) if unit in MANGA_UNIT_MODEL_TO_POLICY else unit
        for key in ("manga_unit_policy", "series_unit_policy", "unit_policy", "mangaUnitPolicy"):
            raw_policy = str(item.get(key) or "").strip().lower().replace("-", "_").replace(" ", "_")
            if raw_policy in MANGA_UNIT_POLICY_TO_MODEL:
                policy = raw_policy if raw_policy in MANGA_UNIT_POLICY_LABELS else manga_unit_policy_for_model(raw_policy)
                model = normalize_manga_unit_model(raw_policy)
                policy_source = key
                model_source = key
                break
        if policy:
            break
        for key in ("manga_unit_model", "series_unit_model", "unit_model", "mangaUnitModel"):
            raw_model = item.get(key)
            if raw_model not in (None, ""):
                model = normalize_manga_unit_model(raw_model)
                policy = manga_unit_policy_for_model(model)
                model_source = key
                policy_source = key
                break
        if policy:
            break
    has_policy_evidence = bool(policy_source or model_source or source_unit)
    if not policy and source_unit in MANGA_UNIT_MODEL_TO_POLICY:
        model = normalize_manga_unit_model(source_unit)
        policy = manga_unit_policy_for_model(model)
        policy_source = "source_unit"
        model_source = "source_unit"
        has_policy_evidence = True
    model = normalize_manga_unit_model(model)
    policy = policy or manga_unit_policy_for_model(model)
    return {
        "has_manga_unit_policy": has_policy_evidence,
        "source_unit": source_unit,
        "manga_unit_model": model,
        "manga_unit_policy": policy,
        "manga_unit_policy_label": MANGA_UNIT_POLICY_LABELS.get(model) or manga_unit_policy_label(policy),
        "manga_unit_policy_source": policy_source or model_source or "default",
        "manga_unit_allows_chapter": model in MANGA_UNIT_CHAPTER_ALLOWED_MODELS,
        "manga_unit_allows_volume": model in MANGA_UNIT_VOLUME_ALLOWED_MODELS,
    }


def media_management_destination_preview(db_path, row, *, source_path=None, dest_path=None, settings=None, check_storage=True):
    row = row if isinstance(row, dict) else {}
    settings = settings if isinstance(settings, dict) else media_management_settings_context(db_path)
    work_id = str(row.get("work_id") or row.get("native_series_id") or "").strip()
    persisted_identity = persisted_series_library_identity(db_path, work_id)
    classification = inkdrop_library_identity.canonical_library_classification(row)
    if persisted_identity.get("library_type"):
        classification = {
            "ok": True,
            "library_type": persisted_identity["library_type"],
            "media_type": "manga" if persisted_identity["library_type"] == "manga" else "comic",
            "reason": "persisted_work_library_identity",
            "evidence": [["canonical_library_identity_v1", persisted_identity["library_type"]]],
        }
    media_type = classification.get("media_type") if classification.get("ok") else normalized_media_type(row.get("media_type")) or "comic"
    manga_unit_policy = media_management_manga_unit_policy(row) if media_type in MANGA_MEDIA_TYPES else {}
    root_value = (
        settings.get("manga_root") or DEFAULT_LIBRARY_ROOTS["manga"]
        if media_type in MANGA_MEDIA_TYPES
        else settings.get("comic_root") or DEFAULT_LIBRARY_ROOTS["comic"]
    )
    root = str(root_value).replace("\\", "/").rstrip("/")
    replace_illegal = boolish(settings.get("replace_illegal_characters"), True)
    colon_replacement = str(settings.get("colon_replacement") or "smart")
    use_series_folders = boolish(settings.get("use_series_folders"), True)
    rename_imported_files = boolish(settings.get("rename_imported_files"), True)
    apply_planned_path = boolish(settings.get("apply_planned_path"), True)
    conflict_policy = str(settings.get("import_conflict_policy") or "skip_existing").strip() or "skip_existing"
    series = str(row.get("series") or row.get("title") or "Unknown Series").strip() or "Unknown Series"
    issue = str(row.get("issue_number") or row.get("issue") or row.get("normalized_number") or "").strip()
    issue_title = str(row.get("issue_title") or "").strip()
    raw_source_path = str(source_path or row.get("source_path") or "").strip()
    raw_dest_path = str(dest_path or row.get("dest_path") or "").strip()
    extension = media_management_source_extension(raw_dest_path or raw_source_path)
    series_year = media_management_series_year(row)
    issue_year = media_management_issue_year(row) or series_year
    explicit_unit = inkdrop_library_identity.canonical_unit_identity(row)
    values = {
        "series_title": series,
        "issue_title": issue_title,
        "year": issue_year,
        "series_year": series_year or issue_year,
        "issue_year": issue_year,
        "issue": issue,
        "volume": explicit_unit.get("number") if explicit_unit.get("unit_type") == "volume" else "",
        "chapter": explicit_unit.get("number") if explicit_unit.get("unit_type") == "chapter" else "",
        "extension": extension.lstrip("."),
    }
    series_format = str(settings.get("series_folder_format") or "{Series Title} ({Year})")
    configured_issue_format = (
        str(settings.get("manga_chapter_format") or "{Series Title} v{Volume:00} c{Chapter:000}")
        if media_type in MANGA_MEDIA_TYPES
        else str(settings.get("comic_issue_format") or "{Series Title} #{Issue:000} ({Year})")
    )
    folder_values = {**values, "year": series_year or issue_year}
    file_values = {**values, "year": issue_year or series_year}
    issue_format_adjustment = ""
    if media_type in MANGA_MEDIA_TYPES:
        issue_format, issue_format_adjustment = media_management_manga_effective_chapter_format(
            configured_issue_format,
            file_values,
        )
    else:
        issue_format = configured_issue_format
    raw_series_folder = media_management_format_template(series_format, folder_values)
    raw_filename_stem = ""
    if rename_imported_files and explicit_unit.get("ok") and explicit_unit.get("unit_type") != "issue":
        raw_filename_stem = Path(inkdrop_library_identity.canonical_filename(series, explicit_unit, extension)).stem
    elif rename_imported_files and media_type not in MANGA_MEDIA_TYPES:
        raw_filename_stem = media_management_format_template(issue_format, file_values)
    if not raw_filename_stem:
        raw_filename_stem = str(raw_source_path or raw_dest_path).replace("\\", "/").rsplit("/", 1)[-1].rsplit(".", 1)[0] or series
    series_folder = media_management_sanitize_component(
        raw_series_folder,
        replace_illegal=replace_illegal,
        colon_replacement=colon_replacement,
    )
    persisted_folder = str(persisted_identity.get("series_folder") or "").strip()
    folder_decision = inkdrop_library_identity.stable_folder_decision(series_folder, persisted_folder)
    series_folder = folder_decision["series_folder"]
    filename_stem = media_management_sanitize_component(
        raw_filename_stem,
        replace_illegal=replace_illegal,
        colon_replacement=colon_replacement,
    )
    filename = f"{filename_stem}{extension}"
    series_path_contract = str(
        row.get("library_path")
        or row.get("series_library_path")
        or row_value(row.get("path_contract") if isinstance(row.get("path_contract"), dict) else {}, "library_path")
        or ""
    ).strip().replace("\\", "/").rstrip("/")
    path_contract_row = row.get("path_contract") if isinstance(row.get("path_contract"), dict) else {}
    path_source = str(
        row.get("library_path_source")
        or row_value(path_contract_row, "library_path_source")
        or ""
    ).strip().lower()
    adapter_series_path = str(
        row.get("library_adapter_path")
        or row_value(path_contract_row, "library_adapter_path")
        or ""
    ).strip()
    adapter_host_path = host_library_path_from_adapter_path(adapter_series_path).replace("\\", "/").rstrip("/")
    planned_dir_source = "series_folder_format"
    adapter_matches_template = bool(
        adapter_host_path
        and _path_has_prefix(adapter_host_path, root)
        and adapter_host_path.rsplit("/", 1)[-1] == series_folder
        and path_source != "user"
    )
    if use_series_folders and adapter_matches_template and path_exists_quietly(adapter_host_path):
        planned_dir = adapter_host_path
        planned_dir_source = "library_adapter_path_existing"
    elif use_series_folders and series_path_contract and _path_has_prefix(series_path_contract, root):
        planned_dir = series_path_contract
        series_folder = series_path_contract.rsplit("/", 1)[-1] or series_folder
        planned_dir_source = "series_path_contract"
    else:
        planned_dir = posixpath.join(root, series_folder) if use_series_folders else root
        if not use_series_folders:
            planned_dir_source = "root"
    planned_path = posixpath.join(planned_dir, filename)
    minimum_free_space_gb = media_management_minimum_free_space_gb(settings)
    check_storage = boolish(check_storage, True)
    if check_storage:
        try:
            root_exists = Path(root).exists()
        except OSError:
            root_exists = False
        try:
            planned_dir_exists = Path(planned_dir).exists()
        except OSError:
            planned_dir_exists = False
        free_snapshot = media_management_disk_usage(root) if root_exists else {"available": False, "reason": "root_missing", "probe_path": root}
    else:
        root_exists = None
        planned_dir_exists = None
        free_snapshot = {"available": False, "reason": "storage_probe_skipped", "probe_path": root}
    free_space_gb = free_snapshot.get("free_space_gb")
    free_space_ok = None
    if minimum_free_space_gb <= 0:
        free_space_ok = True
    elif free_snapshot.get("available") and free_space_gb is not None:
        free_space_ok = float(free_space_gb) >= float(minimum_free_space_gb)
    conflict_exists = False
    if check_storage:
        try:
            conflict_exists = bool(planned_path and Path(planned_path).exists())
        except OSError:
            conflict_exists = False
    else:
        conflict_exists = False
    if raw_dest_path and raw_dest_path.replace("\\", "/") == planned_path:
        conflict_action = "already_target"
    elif conflict_exists:
        conflict_action = str(conflict_policy or "skip_existing").strip().lower() or "skip_existing"
    else:
        conflict_action = "none"
    confidence = "concrete" if raw_source_path or raw_dest_path else "template"
    if not work_id:
        apply_status = "blocked_work_identity"
    elif not classification.get("ok"):
        apply_status = "blocked_library_classification"
    elif rename_imported_files and not explicit_unit.get("ok"):
        apply_status = "blocked_unit_identity"
    elif not apply_planned_path:
        apply_status = "disabled"
    elif check_storage and not root_exists:
        apply_status = "blocked_root_missing"
    elif free_space_ok is False:
        apply_status = "blocked_free_space_floor"
    elif conflict_action == "already_target":
        apply_status = "already_target"
    elif conflict_exists:
        apply_status = "blocked_existing_destination"
    else:
        apply_status = "eligible"
    if apply_status == "blocked_work_identity":
        next_action = "Resolve a stable canonical work identity before import"
    elif apply_status == "blocked_library_classification":
        next_action = "Resolve conflicting or missing durable library classification"
    elif apply_status == "blocked_unit_identity":
        next_action = "Resolve explicit issue, chapter, volume, collected, or pack-member identity"
    elif apply_status == "blocked_root_missing":
        next_action = f"Root folder is missing: {root}"
    elif apply_status == "blocked_free_space_floor":
        next_action = f"Free space below {minimum_free_space_gb:g} GB floor"
    elif conflict_action == "already_target":
        next_action = f"Would use existing target {planned_path}"
    elif conflict_exists:
        next_action = f"Conflict at target; policy is {conflict_action}"
    else:
        next_action = f"Would import to {planned_path}"
    return {
        "preview_only": True,
        "mutates_filesystem": False,
        "media_type": media_type,
        "library_classification": classification,
        "canonical_unit_identity": explicit_unit,
        "root": root,
        "root_exists": root_exists,
        "series_folder": series_folder,
        "series_folder_identity": folder_decision,
        "filename": filename,
        "planned_dir": planned_dir,
        "planned_dir_source": planned_dir_source,
        "series_path_contract": series_path_contract,
        "planned_dir_exists": planned_dir_exists,
        "planned_path": planned_path,
        "source_path": raw_source_path,
        "existing_dest_path": raw_dest_path,
        "rename_imported_files": rename_imported_files,
        "apply_planned_path": apply_planned_path,
        "apply_planned_path_enabled": apply_planned_path,
        "use_series_folders": use_series_folders,
        "replace_illegal_characters": replace_illegal,
        "colon_replacement": colon_replacement,
        "series_folder_format": series_format,
        "file_format": issue_format,
        "configured_file_format": configured_issue_format,
        "file_format_adjustment": issue_format_adjustment,
        "folder_completion_policy": str(settings.get("folder_completion_policy") or "folder_first"),
        "library_visibility_required": boolish(settings.get("library_visibility_required"), False),
        "library_visibility_checks_enabled": boolish(settings.get("library_visibility_checks_enabled"), False),
        "conflict_policy": conflict_policy,
        "minimum_free_space_gb": minimum_free_space_gb,
        "free_space_gb": free_space_gb,
        "free_space_ok": free_space_ok,
        "free_space_probe_path": free_snapshot.get("probe_path"),
        "free_space_status": "ok" if free_space_ok is True else ("blocked" if free_space_ok is False else "unknown"),
        "conflict_exists": conflict_exists,
        "conflict_action": conflict_action,
        "planned_path_apply_status": apply_status,
        "extension": extension,
        "confidence": confidence,
        "tokens": {key: value for key, value in values.items() if value},
        **manga_unit_policy,
        "next_action": next_action,
    }


def kavita_path_mappings(db_path=None):
    if not db_path:
        return KAVITA_PATH_MAPPINGS
    return (
        (
            str(app_setting_value(db_path, "path.kavita_comic_root", KAVITA_PATH_MAPPINGS[0][0])),
            str(app_setting_value(db_path, "path.comic_root", KAVITA_PATH_MAPPINGS[0][1])),
        ),
        (
            str(app_setting_value(db_path, "path.kavita_manga_root", KAVITA_PATH_MAPPINGS[1][0])),
            str(app_setting_value(db_path, "path.manga_root", KAVITA_PATH_MAPPINGS[1][1])),
        ),
    )


def host_path_for_kavita_path(path, db_path=None):
    if not path:
        return None
    text = str(path)
    for kavita_root, host_root in kavita_path_mappings(db_path):
        prefix = f"{kavita_root}/"
        if text == kavita_root:
            return host_root
        if text.startswith(prefix):
            return str(Path(host_root) / text[len(prefix):])
    return None


def kavita_path_for_host_path(path, db_path=None):
    if not path:
        return None
    text = str(path)
    normalized = text.replace("\\", "/")
    for kavita_root, host_root in kavita_path_mappings(db_path):
        host_text = str(host_root).replace("\\", "/").rstrip("/")
        if normalized == host_text:
            return str(kavita_root).rstrip("/")
        prefix = f"{host_text}/"
        if normalized.startswith(prefix):
            rel = normalized[len(prefix):]
            return f"{str(kavita_root).rstrip('/')}/{rel}"
    return text if normalized.startswith("/data/") else None


def kavita_db_path(db_path=None):
    try:
        config = provider_config(db_path, "kavita") if db_path else None
    except Exception:
        config = None
    settings = config.get("settings") if isinstance(config, dict) and isinstance(config.get("settings"), dict) else {}
    value = None
    if isinstance(config, dict):
        value = settings.get("db_path") or settings.get("database_path") or config.get("db_path")
    return Path(str(value or DEFAULT_KAVITA_DB))


def kavita_file_visible_for_import_path(path, db_path=None):
    kavita_path = kavita_path_for_host_path(path, db_path=db_path)
    if not kavita_path:
        return None
    db = kavita_db_path(db_path)
    if not db.exists():
        return None
    con = sqlite3.connect(db, timeout=SQLITE_CONNECT_TIMEOUT_SECONDS)
    con.row_factory = sqlite3.Row
    try:
        row = con.execute(
            """
            select
                s.Name as series,
                c.Number as number,
                c.Range as chapter_range,
                c.Title as title,
                mf.FilePath as file_path,
                mf.FileName as file_name,
                mf.Pages as pages,
                mf.Bytes as bytes
            from MangaFile mf
            left join Chapter c on mf.ChapterId = c.Id
            left join Volume v on c.VolumeId = v.Id
            left join Series s on v.SeriesId = s.Id
            where mf.FilePath = ?
            limit 1
            """,
            (kavita_path,),
        ).fetchone()
    finally:
        con.close()
    return dict(row) if row else None


def manual_source_resolved_destination_paths(row):
    if not isinstance(row, dict):
        return []
    paths = []

    def add_path(value):
        if value:
            paths.append(str(value))

    for field in ("dest", "destination", "last_import_dest"):
        add_path(row.get(field))
    destinations = row.get("destinations") if isinstance(row.get("destinations"), list) else []
    for path in destinations:
        add_path(path)
    verification = row.get("verification") if isinstance(row.get("verification"), dict) else {}
    for checked in verification.get("checked") or []:
        if isinstance(checked, dict):
            add_path(checked.get("dest"))
    out = []
    seen = set()
    for path in paths:
        key = str(path or "").replace("\\", "/").rstrip("/")
        if key and key not in seen:
            seen.add(key)
            out.append(path)
    return out


def manual_source_resolved_has_existing_destination(row, db_path=None):
    paths = manual_source_resolved_destination_paths(row)
    if not paths:
        return True
    for path in paths:
        host_path = host_path_for_kavita_path(path, db_path=db_path) or path
        try:
            if Path(str(host_path)).exists():
                return True
        except OSError:
            continue
    return False


def issue_number_keys_in_text(value):
    keys = set()
    for raw in re.findall(r"(?<!\d)\d{1,4}(?:\.\d+)?(?!\d)", str(value or "")):
        keys |= issue_number_keys(raw)
    return {key for key in keys if key}


def manual_source_resolved_matches_issue(row):
    wanted = issue_number_keys(row.get("issue") or row.get("issue_number") or row.get("canonical_issue_number"))
    if not wanted:
        return True
    paths = manual_source_resolved_destination_paths(row)
    if not paths:
        return False
    return any(wanted & issue_number_keys_in_text(path) for path in paths)


def ambiguous_queue_issue_keys(items):
    buckets = {}
    for item in items or []:
        if not isinstance(item, dict):
            continue
        series = normalize_key(item.get("series") or item.get("query") or "")
        if not series:
            continue
        identity = queue_identity(item) or str(item.get("key") or "")
        for issue in issue_number_keys(item.get("issue")):
            buckets.setdefault((series, issue), set()).add(identity)
    return {key for key, identities in buckets.items() if len({value for value in identities if value}) > 1}


def resolved_queue_state(item, resolved_keys, ambiguous_issue_keys):
    state = str((item or {}).get("state") or "queued").lower()
    if not isinstance(item, dict) or not resolved_keys:
        return state
    series = normalize_key(item.get("series") or item.get("query") or "")
    if not series:
        return state
    identities = equivalent_queue_identities(item)
    for issue in issue_number_keys(item.get("issue")):
        for identity in identities:
            if identity and (series, issue, identity) in resolved_keys:
                return "verified"
        if (series, issue, "") in resolved_keys and (series, issue) not in ambiguous_issue_keys:
            return "verified"
    return state


def manual_source_resolved_row_for_item(item, resolved_by_queue, resolved_by_issue, ambiguous_issue_keys):
    if not isinstance(item, dict):
        return None
    for key in (item.get("key"), item.get("legacy_key")):
        key = str(key or "").strip()
        if key and key in resolved_by_queue:
            return resolved_by_queue[key]
    series = normalize_key(item.get("series") or item.get("query") or "")
    if not series:
        return None
    identities = equivalent_queue_identities(item)
    for issue in issue_number_keys(item.get("issue")):
        for identity in identities:
            if identity and (series, issue, identity) in resolved_by_issue:
                return resolved_by_issue[(series, issue, identity)]
        if (series, issue, "") in resolved_by_issue and (series, issue) not in ambiguous_issue_keys:
                return resolved_by_issue[(series, issue, "")]
    return None


MANUAL_SOURCE_IMPORT_STATUSES = {
    "import_busy",
    "verification_pending",
    "imported_not_resolved",
    "preview_importable",
    "ready_import",
}
MANUAL_SOURCE_DOWNLOAD_STATUSES = {
    "transfer_in_progress",
    "transfer_settling",
    "waiting_for_staged_file",
    "staged_file_settling",
    "transfer_unknown",
    "transfer_lookup_error",
    "waiting_for_transfer",
    "already_downloading",
}
MANUAL_SOURCE_QUEUE_STATUSES = {
    "retry_exhausted",
}
MANUAL_SOURCE_SEARCH_STATUSES = {
    "transfer_failed",
    "transfer_stalled",
    "transfer_succeeded_missing_stage",
    "transfer_stale_unknown",
    "transfer_missing_stale",
    "retry_pending",
    "candidate_failed",
    "transient_error",
}
MANUAL_SOURCE_VERIFIED_STATUSES = {
    "resolved",
    "already_verified",
    "verified",
    "kavita_verified",
}


def manual_source_overlay_rows(state_dir):
    state_dir = Path(state_dir)
    rows = []

    def add_result(result, fallback_ts=0):
        if not isinstance(result, dict):
            return
        for bucket in ("processed", "skipped"):
            values = result.get(bucket)
            if not isinstance(values, list):
                continue
            for row in values:
                if not isinstance(row, dict):
                    continue
                queue_id = str(row.get("autopilot_queue_key") or "").strip()
                if not queue_id:
                    continue
                item = dict(row)
                item["_overlay_bucket"] = bucket
                item["_overlay_ts"] = safe_float(row.get("ts")) or fallback_ts or safe_float(result.get("updated_at")) or safe_float(result.get("generated_at")) or 0
                rows.append(item)

    pending = read_json(state_dir / "manual-source-queue-sync-pending.json", {}) or {}
    for entry in (pending.get("items") if isinstance(pending, dict) else []) or []:
        if not isinstance(entry, dict):
            continue
        result = entry.get("result") if isinstance(entry.get("result"), dict) else {}
        add_result(result, safe_float(entry.get("created_at") or entry.get("ts")))
    status = read_json(state_dir / "manual-source-autoresolve-status.json", {}) or {}
    add_result(status, safe_float(status.get("updated_at") or status.get("generated_at")) if isinstance(status, dict) else 0)

    latest = {}
    for row in rows:
        queue_id = str(row.get("autopilot_queue_key") or "").strip()
        if not queue_id:
            continue
        current = latest.get(queue_id)
        if not current or safe_float(row.get("_overlay_ts")) >= safe_float(current.get("_overlay_ts")):
            latest[queue_id] = row
    return latest


def manual_source_overlay_source(row, fallback=None):
    row = row if isinstance(row, dict) else {}
    recovery = row.get("recovery") if isinstance(row.get("recovery"), dict) else {}
    bad_candidate = recovery.get("bad_candidate") if isinstance(recovery.get("bad_candidate"), dict) else {}
    marker = " ".join(
        str(value or "").lower()
        for value in (
            row.get("path"),
            row.get("source"),
            row.get("candidate_source"),
            row.get("slskd_transfer_id"),
            row.get("username"),
            bad_candidate.get("source"),
            bad_candidate.get("candidate_source"),
            bad_candidate.get("slskd_transfer_id"),
            bad_candidate.get("username"),
        )
    )
    if (
        "slskd" in marker
        or row.get("username")
        or row.get("slskd_transfer_id")
        or bad_candidate.get("username")
        or bad_candidate.get("slskd_transfer_id")
    ):
        return "slskd"
    return fallback or "manual_source"


def manual_source_overlay_event(row):
    row = row if isinstance(row, dict) else {}
    live = row.get("live") if isinstance(row.get("live"), dict) else {}
    preview = row.get("preview") if isinstance(row.get("preview"), dict) else {}
    for value in (
        row.get("verification_pending_note"),
        row.get("reason"),
        row.get("error"),
        live.get("note"),
        preview.get("note"),
        row.get("status"),
    ):
        text = str(value or "").strip()
        if text:
            return text
    return "SLSKD/manual source resolver updated queue state"


def apply_manual_source_overlay(item, raw_item, state, current_source, last_event, overlay_row):
    status = str((overlay_row or {}).get("status") or "").strip().lower()
    if not status or state == "verified":
        return item, raw_item, state, current_source, last_event
    if status in MANUAL_SOURCE_VERIFIED_STATUSES:
        next_state = "verified"
    elif status in MANUAL_SOURCE_IMPORT_STATUSES:
        next_state = "importing"
    elif status in MANUAL_SOURCE_DOWNLOAD_STATUSES:
        next_state = "downloading"
    elif status in MANUAL_SOURCE_QUEUE_STATUSES:
        next_state = "queued"
    elif status in MANUAL_SOURCE_SEARCH_STATUSES:
        next_state = "searching"
    else:
        return item, raw_item, state, current_source, last_event
    updated_at = safe_float((overlay_row or {}).get("_overlay_ts")) or safe_float((overlay_row or {}).get("ts")) or safe_float(item.get("updated_at")) or time.time()
    item = dict(item)
    raw_item = dict(raw_item or item)
    source = manual_source_overlay_source(overlay_row, current_source or item.get("current_source"))
    event = manual_source_overlay_event(overlay_row)
    item["state"] = next_state
    item["current_source"] = None if status in MANUAL_SOURCE_QUEUE_STATUSES else source
    item["last_event"] = event
    item["updated_at"] = updated_at
    item["updated_at_iso"] = utc_stamp(updated_at)
    item["last_manual_source_status"] = status
    item["last_slskd_autoresolve_status"] = status if source == "slskd" else item.get("last_slskd_autoresolve_status")
    item["last_slskd_autoresolve_reason"] = event if source == "slskd" else item.get("last_slskd_autoresolve_reason")
    item["last_slskd_autoresolve_at"] = updated_at if source == "slskd" else item.get("last_slskd_autoresolve_at")
    item["last_slskd_autoresolve_at_iso"] = utc_stamp(updated_at) if source == "slskd" else item.get("last_slskd_autoresolve_at_iso")
    raw_item["manual_source_autoresolve_overlay"] = overlay_row
    raw_item["state_resolution"] = "manual_source_autoresolve_overlay"
    return item, raw_item, next_state, source, event


def queue_item_activity_at(item, now=None):
    item = item if isinstance(item, dict) else {}
    best = 0
    for key in (
        "updated_at",
        "last_slskd_autoresolve_at",
        "last_download_started_at",
        "last_import_failed_at",
        "source_ladder_attempted_at",
        "last_attempt_at",
        "last_slskd_at",
        "last_source_outcome_at",
        "last_failed_retry_at",
        "stale_downloader_normalized_at",
        "stale_downloader_cleared_at",
        "retry_waiting_normalized_at",
        "completed_at",
        "created_at",
    ):
        best = max(best, safe_float(item.get(key)) or 0)
    return best or now or time.time()


def sync_watches(con, state_dir, now):
    data = read_json(Path(state_dir) / "comic-series-watches.json", {})
    count = 0
    for watch in data.get("watches") or []:
        if not isinstance(watch, dict):
            continue
        try:
            series_id = upsert_series(con, watch, now)
        except SeriesIdentityTombstoneBlocked:
            continue
        if series_id_user_removed(con, series_id):
            retire_removed_series_work(con, series_id, now, source="sync_watches_removed_series")
            continue
        for issue in (watch.get("knownIssues") or {}).values():
            if isinstance(issue, dict):
                upsert_issue(con, series_id, issue, now)
        for issue in watch.get("missingIssues") or []:
            if not isinstance(issue, dict):
                continue
            issue_id = upsert_issue(con, series_id, issue, now)
            status = "grabbed" if str(issue.get("status") or "").lower() == "grabbed" else "wanted"
            upsert_wanted(con, series_id, issue_id, "watch_missing", status, issue, now)
        dedupe_series_issue_numbers(con, series_id, now)
        count += 1
    return count


def sync_queue(
    con,
    state_dir,
    now,
    *,
    retire_absent_json=False,
    verify_filesystem=True,
    perform_backfills=True,
):
    data = read_json(Path(state_dir) / "series-autopilot-queue.json", {})
    can_retire_absent = isinstance(data, dict) and isinstance(data.get("items"), dict)
    items = data.get("items") if can_retire_absent else {}
    queue_items = [item for item in (items or {}).values() if isinstance(item, dict)]
    resolved_by_queue, resolved_by_issue = manual_source_resolved_indexes(
        state_dir,
        require_existing_destination=verify_filesystem,
    )
    manual_source_overlays = manual_source_overlay_rows(state_dir)
    resolved_keys = set(resolved_by_issue.keys())
    ambiguous_issue_keys = ambiguous_queue_issue_keys(queue_items)
    count = 0
    seen_queue_ids = set()
    for queue_key, item in (items or {}).items():
        if not isinstance(item, dict):
            continue
        effective_state = resolved_queue_state(item, resolved_keys, ambiguous_issue_keys)
        try:
            series_id = upsert_series(con, item, now)
        except SeriesIdentityTombstoneBlocked:
            count += 1
            continue
        if series_id_user_removed(con, series_id):
            retire_removed_series_work(con, series_id, now, source="sync_queue_removed_series")
            count += 1
            continue
        issue = {
            "id": item.get("issue_id"),
            "issueNumber": item.get("issue"),
            "title": item.get("issue_title"),
            "kapowarrIssueId": item.get("kapowarr_issue_id"),
            "date": item.get("issue_date"),
        }
        issue_id = upsert_issue(con, series_id, issue, now)
        queue_id = item.get("key") or str(queue_key)
        state = effective_state
        resolved_row = manual_source_resolved_row_for_item(item, resolved_by_queue, resolved_by_issue, ambiguous_issue_keys)
        raw_item = dict(item)
        last_event = item.get("last_event")
        if state == "verified" and str(item.get("state") or "").lower() != "verified":
            raw_item["raw_state"] = item.get("state")
            raw_item["effective_state"] = "verified"
            raw_item["state_resolution"] = "manual_source_resolved"
            last_event = "manual source resolved and verified"
            verification = resolved_row.get("verification") if isinstance(resolved_row, dict) and isinstance(resolved_row.get("verification"), dict) else {}
            verified_ts = (
                safe_float(verification.get("verified_at"))
                or safe_float((resolved_row or {}).get("verified_at") if isinstance(resolved_row, dict) else None)
                or safe_float((resolved_row or {}).get("updated_at") if isinstance(resolved_row, dict) else None)
                or safe_float(item.get("updated_at"))
                or safe_float(item.get("completed_at"))
                or safe_float(item.get("created_at"))
                or now
            )
            item = dict(item)
            item["updated_at"] = verified_ts
            item["updated_at_iso"] = utc_stamp(verified_ts)
        overlay_row = manual_source_overlays.get(str(queue_id))
        if overlay_row and state != "verified":
            item, raw_item, state, _overlay_source, last_event = apply_manual_source_overlay(
                item,
                raw_item,
                state,
                item.get("current_source"),
                last_event,
                overlay_row,
            )
        verified_import = None
        resolved_proof_pending = False
        if verify_filesystem or state == "verified":
            verified_import = verified_import_for_queue(
                con,
                queue_id,
                series_id,
                issue_id,
                require_existing_destination=verify_filesystem,
            )
        if state == "verified" and not verified_import:
            # A manual resolver row contains the destination needed to create
            # strict import proof, but the queue row must exist first for exact
            # linkage. Defer its proof attempt until immediately after upsert.
            resolved_proof_pending = bool(resolved_row)
            durable_snapshot = None if resolved_proof_pending else queue_verified_snapshot_durable_evidence(
                con, item, resolved_row=resolved_row, series_id=series_id, issue_id=issue_id, queue_id=queue_id
            )
            if not resolved_proof_pending and not durable_snapshot:
                state = "searching"
                item = dict(item)
                raw_item = dict(raw_item)
                raw_item.update(
                    {
                        "raw_state": "verified",
                        "effective_state": "searching",
                        "state_resolution": "unproven_verified_snapshot_rejected",
                        "verified_snapshot_rejected_reason": "missing_durable_managed_import_proof",
                        "verified_snapshot_rejected_at": now,
                        "verified_snapshot_rejected_at_iso": utc_stamp(now),
                    }
                )
                item["state"] = "searching"
                item["current_source"] = None
                last_event = "This looked complete, but there is no imported file behind it. Searching again."
                item["last_event"] = last_event
        if verified_import and state != "verified" and verify_filesystem:
            state = "verified"
            raw_item["raw_state"] = item.get("state")
            raw_item["effective_state"] = "verified"
            raw_item["state_resolution"] = "verified_import_result"
            raw_item["verified_import_result_id"] = verified_import["id"]
            last_event = "Confirmed in your library"
            item = dict(item)
            verified_ts = max(
                safe_float(item.get("updated_at")) or 0,
                safe_float(verified_import["created_at"]) or 0,
            ) or now
            item["updated_at"] = verified_ts
            item["updated_at_iso"] = utc_stamp(verified_ts)
        item_updated_at = (
            safe_float(item.get("updated_at") or item.get("completed_at"))
            if state == "verified"
            else queue_item_activity_at(item, now)
        ) or now
        if item_updated_at != safe_float(item.get("updated_at")):
            item = dict(item)
            raw_item = dict(raw_item)
            item["updated_at"] = item_updated_at
            item["updated_at_iso"] = utc_stamp(item_updated_at)
            raw_item["activity_updated_at"] = item_updated_at
            raw_item["activity_updated_at_iso"] = utc_stamp(item_updated_at)
        wanted_id = upsert_wanted(con, series_id, issue_id, "queue_missing", wanted_status_for_queue_state(state), item, now)
        canonical_ref = canonical_wanted_reference(con, wanted_id, issue_id)
        if canonical_ref.get("changed"):
            wanted_id = canonical_ref.get("wanted_id") or wanted_id
            issue_id = canonical_ref.get("issue_id") or issue_id
            raw_item = dict(raw_item)
            raw_item["canonical_wanted_reference"] = canonical_ref
        seen_queue_ids.add(str(queue_id))
        retry_after, retry_after_iso = queue_retry_columns_from_raw(raw_item)
        status_columns = queue_provider_status_column_values(
            state,
            item.get("current_source"),
            last_event,
            raw_item,
        )
        con.execute(
            """
            insert into queue_items(
                id, wanted_id, series_id, issue_id, state, current_source, query,
                last_event, active, created_at, updated_at, source_order_json,
                recovery_steps_json, retry_after, retry_after_iso, outcome, display_phase,
                provider_status_state, provider_status_phase, provider_status_provider,
                provider_status_actionability, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(id) do update set
                wanted_id=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.wanted_id
                    else excluded.wanted_id
                end,
                series_id=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.series_id
                    else excluded.series_id
                end,
                issue_id=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.issue_id
                    else excluded.issue_id
                end,
                state=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.state
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.state
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.state
                    else excluded.state
                end,
                current_source=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.current_source
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.current_source
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.current_source
                    else excluded.current_source
                end,
                query=excluded.query,
                last_event=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.last_event
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.last_event
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.last_event
                    else excluded.last_event
                end,
                active=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.active
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.active
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.active
                    else excluded.active
                end,
                updated_at=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.updated_at
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.updated_at
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.updated_at
                    else excluded.updated_at
                end,
                source_order_json=excluded.source_order_json,
                recovery_steps_json=excluded.recovery_steps_json,
                retry_after=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.retry_after
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.retry_after
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.retry_after
                    else excluded.retry_after
                end,
                retry_after_iso=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.retry_after_iso
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.retry_after_iso
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.retry_after_iso
                    else excluded.retry_after_iso
                end,
                outcome=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.outcome
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.outcome
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.outcome
                    else excluded.outcome
                end,
                display_phase=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.display_phase
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.display_phase
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.display_phase
                    else excluded.display_phase
                end,
                provider_status_state=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.provider_status_state
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.provider_status_state
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.provider_status_state
                    else excluded.provider_status_state
                end,
                provider_status_phase=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.provider_status_phase
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.provider_status_phase
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.provider_status_phase
                    else excluded.provider_status_phase
                end,
                provider_status_provider=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.provider_status_provider
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.provider_status_provider
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.provider_status_provider
                    else excluded.provider_status_provider
                end,
                provider_status_actionability=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.provider_status_actionability
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.provider_status_actionability
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.provider_status_actionability
                    else excluded.provider_status_actionability
                end,
                raw_json=case
                    when queue_items.state = 'superseded_duplicate' then queue_items.raw_json
                    when queue_items.state in ('source_wait','downloading','importing')
                     and excluded.state in ('queued','searching') then queue_items.raw_json
                    when excluded.state != 'verified'
                     and coalesce(excluded.updated_at, 0) < coalesce(queue_items.updated_at, 0)
                    then queue_items.raw_json
                    else excluded.raw_json
                end
            """,
            (
                queue_id,
                wanted_id,
                series_id,
                issue_id,
                state,
                item.get("current_source"),
                item.get("query"),
                last_event,
                1 if state in {"queued", "searching", "source_wait", "downloading", "importing", "needs_you"} else 0,
                item.get("created_at") or now,
                item_updated_at,
                json_dumps(item.get("source_order") or []),
                json_dumps(item.get("recovery_steps") or []),
                retry_after,
                retry_after_iso,
                *status_columns,
                json_dumps(raw_item),
                ),
            )
        if state == "verified":
            record_verified_queue_import_result(
                con,
                queue_id,
                wanted_id,
                series_id,
                issue_id,
                raw_item,
                item.get("updated_at") or item.get("completed_at") or now,
                resolved_row=resolved_row,
            )
            # A row that was already verified before this sync, with no fresh
            # manual-source resolution pending, and whose pre-upsert check above
            # already confirmed durable proof, has nothing new to establish here.
            # Re-running the archive-backed strict check (and mark_queue_verified_
            # for_import's own internal copy of it) for every already-settled
            # verified row every sync cycle is pure repeated filesystem I/O with
            # no behavior change -- skip it for that one narrow, already-proven case.
            already_verified_and_confirmed = (
                not resolved_proof_pending
                and str(item.get("state") or "").lower() == "verified"
                and bool(verified_import)
            )
            if not already_verified_and_confirmed:
                verified_import = verified_import_for_queue(
                    con,
                    queue_id,
                    series_id,
                    issue_id,
                    require_existing_destination=verify_filesystem,
                )
                if verified_import:
                    mark_queue_verified_for_import(
                        con,
                        queue_id,
                        wanted_id,
                        item.get("updated_at") or item.get("completed_at") or now,
                        current_source=queue_verified_import_source(
                            queue_verified_source_path(raw_item, resolved_row),
                            raw_item,
                            resolved_row,
                        ),
                    )
                elif resolved_proof_pending:
                    raw_item = dict(raw_item)
                    raw_item.update(
                        {
                            "raw_state": "verified",
                            "effective_state": "searching",
                            "state_resolution": "unproven_manual_source_resolution_rejected",
                            "verified_snapshot_rejected_reason": "missing_strict_managed_import_proof",
                            "verified_snapshot_rejected_at": now,
                            "verified_snapshot_rejected_at_iso": utc_stamp(now),
                        }
                    )
                    con.execute(
                        """
                        update queue_items
                           set state='searching',active=1,current_source=null,
                               last_event='The download reported success, but the file never landed in the library. Searching again.',
                               updated_at=?,raw_json=?
                         where id=?
                        """,
                        (now, json_dumps(raw_item), queue_id),
                    )
                    con.execute(
                        """
                        update wanted_items set status='in_progress',updated_at=?
                        where id=? and lower(coalesce(status,'')) not in ('ignored','removed_by_user')
                        """,
                        (now, wanted_id),
                    )
                    state = "searching"
        for attempt in item.get("attempts") or []:
            if not isinstance(attempt, dict):
                continue
            record_source_attempt(
                con,
                queue_id,
                wanted_id,
                series_id,
                issue_id,
                attempt,
                started_at=attempt.get("ts") or attempt.get("started_at") or item.get("updated_at") or now,
                refresh_queue_rollup=False,
                skip_existing=True,
            )
        slskd_check_attempt_id, slskd_check_attempt, slskd_check_ts = queue_slskd_check_attempt(item, queue_id)
        if slskd_check_attempt:
            record_source_attempt(
                con,
                queue_id,
                wanted_id,
                series_id,
                issue_id,
                slskd_check_attempt,
                attempt_id=slskd_check_attempt_id,
                started_at=slskd_check_ts or now,
                completed_at=slskd_check_ts or now,
                refresh_queue_rollup=False,
                skip_existing=True,
            )
        activity_attempt_id, activity_attempt, activity_ts = queue_activity_attempt(item, queue_id, state, last_event)
        if activity_attempt:
            record_source_attempt(
                con,
                queue_id,
                wanted_id,
                series_id,
                issue_id,
                activity_attempt,
                attempt_id=activity_attempt_id,
                started_at=activity_ts or now,
                completed_at=activity_ts or now,
                refresh_queue_rollup=False,
                skip_existing=True,
            )
        if item.get("last_event"):
            event_id = queue_event_history_id(queue_id, item, item.get("last_event"))
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    event_id,
                    "queue_item",
                    queue_id,
                    series_id,
                    issue_id,
                    "queue_event",
                    item.get("current_source"),
                    item.get("last_event"),
                    item.get("updated_at") or item.get("completed_at") or now,
                    json_dumps(item),
                ),
            )
            count += 1
    if can_retire_absent and retire_absent_json:
        retire_absent_queue_items(con, seen_queue_ids, now)
    retire_all_removed_series_work(con, now, source="sync_queue_removed_series_sweep")
    if perform_backfills:
        backfill_verified_queue_import_results(con, now)
        supersede_duplicate_queue_items(con, now)
    backfill_queue_provider_status_columns(con, active_only=True, only_missing=False, limit=5000)
    return count


def queue_state_rank(state):
    return {
        "verified": 100,
        "importing": 95,
        "downloading": 90,
        "source_wait": 88,
        "searching": 85,
        "queued": 80,
        "needs_you": 70,
        "failed": 50,
        "blocked": 45,
        "stale_source_absent": 10,
        "inactive": 5,
        "superseded_duplicate": 0,
    }.get(str(state or "").lower(), 20)


def queue_canonical_rank(row):
    state = str(row["state"] or "").lower()
    return (
        queue_state_rank(state),
        1 if row["active"] else 0,
        safe_float(row["updated_at"]) or 0,
        safe_float(row["created_at"]) or 0,
        str(row["id"] or ""),
    )


def supersede_duplicate_queue_items(con, now):
    groups = con.execute(
        """
        select series_id, issue_id
        from queue_items
        where state != 'superseded_duplicate' and issue_id is not null
        group by series_id, issue_id
        having count(*) > 1
        """
    ).fetchall()
    superseded = 0
    for group in groups:
        rows = con.execute(
            """
            select id, wanted_id, series_id, issue_id, state, active, current_source,
                   last_event, created_at, updated_at, raw_json
            from queue_items
            where series_id = ? and issue_id = ? and state != 'superseded_duplicate'
            """,
            (group["series_id"], group["issue_id"]),
        ).fetchall()
        if len(rows) <= 1:
            continue
        canonical = max(rows, key=queue_canonical_rank)
        canonical_id = str(canonical["id"])
        for row in rows:
            queue_id = str(row["id"])
            if queue_id == canonical_id:
                continue
            previous_state = row["state"]
            raw = json_loads(row["raw_json"], {}) or {}
            if not isinstance(raw, dict):
                raw = {}
            raw.update({
                "previous_state": previous_state,
                "previous_last_event": row["last_event"],
                "superseded_by_queue_id": canonical_id,
                "superseded_duplicate_at": now,
                "superseded_duplicate_at_iso": utc_stamp(now),
            })
            message = f"Duplicate queue row superseded by {canonical_id}"
            con.execute(
                """
                update queue_items
                set state='superseded_duplicate',
                    active=0,
                    last_event=?,
                    updated_at=?,
                    retry_after=null,
                    retry_after_iso=null,
                    outcome='historical',
                    display_phase='retired',
                    provider_status_state='historical',
                    provider_status_phase='retired',
                    provider_status_provider=coalesce(nullif(provider_status_provider, ''), lower(coalesce(current_source, 'source_ladder'))),
                    provider_status_actionability='diagnostic',
                    raw_json=?
                where id=?
                """,
                (message, now, json_dumps(raw), queue_id),
            )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("queue_superseded_duplicate", queue_id, canonical_id),
                    "queue_item",
                    queue_id,
                    row["series_id"],
                    row["issue_id"],
                    "queue_superseded_duplicate",
                    "inkdrop_state",
                    message,
                    now,
                    json_dumps(raw),
                ),
            )
            superseded += 1
    return superseded


def retire_absent_queue_items(con, seen_queue_ids, now):
    seen_queue_ids = {str(value) for value in (seen_queue_ids or set()) if str(value or "")}
    rows = con.execute(
        """
        select id, wanted_id, series_id, issue_id, state, last_event
        from queue_items
        where active = 1
        """
    ).fetchall()
    for row in rows:
        queue_id = str(row["id"])
        if queue_id in seen_queue_ids:
            continue
        previous_state = row["state"]
        message = "queue source no longer lists this item"
        raw = {
            "previous_state": previous_state,
            "previous_event": row["last_event"],
            "retired_at": now,
            "retired_at_iso": utc_stamp(now),
            "reason": "source_absent",
        }
        con.execute(
            """
            update queue_items
            set state='stale_source_absent',
                active=0,
                last_event=?,
                updated_at=?,
                retry_after=null,
                retry_after_iso=null,
                raw_json=?
            where id=?
            """,
            (message, now, json_dumps(raw), queue_id),
        )
        if row["wanted_id"]:
            con.execute(
                """
                update wanted_items
                set status='inactive', updated_at=?
                where id=? and status in ('wanted','in_progress','blocked')
                """,
                (now, row["wanted_id"]),
            )
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("queue_retired", queue_id, previous_state, now),
                "queue_item",
                queue_id,
                row["series_id"],
                row["issue_id"],
                "queue_retired",
                "inkdrop_state",
                message,
                now,
                json_dumps(raw),
            ),
        )


def find_queue_for_import(con, row, series_id, issue_id, *, require_exact_queue_id=False):
    if not isinstance(row, dict):
        return None
    direct_queue_id = str(row.get("queue_id") or row.get("autopilot_queue_key") or "").strip()
    if require_exact_queue_id and not direct_queue_id:
        return None
    if direct_queue_id:
        found = con.execute(
            """
            select q.id, q.wanted_id, q.series_id, q.issue_id, q.state
            from queue_items q
            where q.id = ?
            limit 1
            """,
            (direct_queue_id,),
        ).fetchone()
        if found:
            return found
        if require_exact_queue_id:
            return None

    issue_number = row.get("canonical_issue_number") or row.get("normalized_number") or row.get("issue")
    issue_keys = sorted(issue_number_keys(issue_number))
    if not issue_keys and issue_id:
        issue_keys = sorted(issue_number_keys(str(issue_id).rsplit(":", 1)[-1]))
    if not issue_keys:
        return None

    series_terms = []
    params = []
    if series_id:
        series_terms.append("s.id = ?")
        params.append(series_id)
    kapowarr_id = row.get("matched_kapowarr_id") or row.get("kapowarr_id") or row.get("volume_id")
    if str(kapowarr_id or "").isdigit():
        series_terms.append("s.kapowarr_id = ?")
        params.append(int(kapowarr_id))
    comicvine_id = row.get("matched_comicvine_id") or row.get("comicvine_id") or row.get("comicvineId")
    if comicvine_id not in (None, ""):
        series_terms.append("(s.metadata_provider = 'comicvine' and s.metadata_id = ?)")
        params.append(str(comicvine_id))
    title_key = normalize_key(row.get("matched_series") or row.get("series") or "")
    if title_key:
        series_terms.append("s.sort_title = ?")
        params.append(title_key)
    if not series_terms:
        return None

    issue_terms = []
    for key in issue_keys:
        issue_terms.append("(i.normalized_number = ? or i.issue_number = ?)")
        params.extend([normalize_issue_number(key), key])

    found = con.execute(
        f"""
        select q.id, q.wanted_id, q.series_id, q.issue_id, q.state
        from queue_items q
        join series s on s.id = q.series_id
        left join issues i on i.id = q.issue_id
        where ({' or '.join(series_terms)})
          and ({' or '.join(issue_terms)})
        order by
          case q.state when 'verified' then 0 when 'importing' then 1 when 'downloading' then 2 else 3 end,
          coalesce(q.updated_at, q.created_at, 0) desc
        limit 1
        """,
        params,
    ).fetchone()
    return found


def mark_queue_verified_for_import(con, queue_id, wanted_id, ts, message=None, current_source=None):
    if not queue_id:
        return False
    queue = con.execute(
        "select id,wanted_id,series_id,issue_id from queue_items where id=? limit 1",
        (queue_id,),
    ).fetchone()
    if not queue:
        return False
    # This re-derives proof rather than trusting the caller's, so it stays an
    # independent second check. It has to know about sibling issue ids for the
    # same reason the callers do: two metadata providers can file the same
    # physical issue under two ids, and without this the write is vetoed even
    # though the caller just validated the evidence.
    if not verified_import_for_queue(
        con,
        queue_id,
        queue["series_id"],
        queue["issue_id"],
        require_existing_destination=True,
    ) and not verified_import_by_sibling_normalized_number(
        con,
        queue["series_id"],
        queue["issue_id"],
        require_linkage_consistent=True,
    ):
        return False
    wanted_id = queue["wanted_id"] or wanted_id
    message = str(message or "Managed-folder import proof confirmed").strip()
    current_source = str(current_source or "").strip() or None
    con.execute(
        """
        update queue_items
        set state='verified',
            active=0,
            display_phase='verified',
            current_source=?,
            last_event=?,
            updated_at=?,
            retry_after=null,
            retry_after_iso=null
        where id=?
        """,
        (current_source, message, ts, queue_id),
    )
    changed = int(con.execute("select changes() as changed").fetchone()["changed"] or 0)
    if wanted_id:
        con.execute(
            """
            update wanted_items
            set status='satisfied', updated_at=?
            where id=?
            """,
            (ts, wanted_id),
        )
    cleanup_active_download_tasks_for_queue(con, queue_id, ts)
    return bool(changed)


def reconcile_verified_queue_wanted_statuses(con, now):
    rows = con.execute(
        """
        select distinct q.id as queue_id, w.id as wanted_id, q.wanted_id as queue_wanted_id,
               q.series_id, q.issue_id,
               q.state as queue_state, w.status as wanted_status
        from queue_items q
        join wanted_items w on (
            w.id = q.wanted_id
            or (coalesce(q.issue_id, '') <> '' and w.issue_id = q.issue_id)
        )
        where lower(coalesce(q.state, '')) in ('verified', 'satisfied')
          and lower(coalesce(w.status, '')) not in ('satisfied', 'ignored', 'removed_by_user')
        """
    ).fetchall()
    changed = 0
    for row in rows:
        if not verified_import_for_queue(
            con,
            row["queue_id"],
            row["series_id"],
            row["issue_id"],
            require_existing_destination=True,
        ):
            continue
        con.execute(
            """
            update wanted_items
               set status='satisfied', updated_at=?
             where id=?
            """,
            (now, row["wanted_id"]),
        )
        if int(con.execute("select changes() as changed").fetchone()["changed"] or 0):
            changed += 1
            _record_search_history(
                con,
                event_type="wanted_satisfied_by_verified_queue",
                entity_type="wanted_item",
                entity_id=row["wanted_id"],
                series_id=row["series_id"],
                issue_id=row["issue_id"],
                message="Verified queue state satisfied wanted row",
                raw={
                    "queue_id": row["queue_id"],
                    "wanted_id": row["wanted_id"],
                    "queue_wanted_id": row["queue_wanted_id"],
                    "queue_state": row["queue_state"],
                    "wanted_status_before": row["wanted_status"],
                    "wanted_status_after": "satisfied",
                },
                source="inkdrop_state",
                now=now,
            )
    return changed


def reconcile_duplicate_issue_number_wanted_statuses(con, now, *, limit=500):
    """Satisfy duplicate issue rows when a sibling issue number is verified."""
    limit = max(1, min(int(limit or 500), 2000))
    rows = con.execute(
        """
        select w.id as wanted_id, w.series_id, w.issue_id,
               i.issue_number, i.normalized_number,
               (
                   select p.id
                   from issues p
                   left join wanted_items pw on pw.issue_id = p.id
                   left join queue_items pq on pq.issue_id = p.id
                   left join import_results pir on pir.issue_id = p.id
                   where p.series_id = i.series_id
                     and p.id <> i.id
                     and (
                         coalesce(nullif(p.normalized_number,''), p.issue_number, '') =
                         coalesce(nullif(i.normalized_number,''), i.issue_number, '')
                         or coalesce(p.issue_number, '') = coalesce(i.issue_number, '')
                     )
                     and (
                         lower(coalesce(pw.status,'')) in ('satisfied','verified')
                         or lower(coalesce(pq.state,'')) in ('verified','satisfied')
                         or coalesce(pir.verified, 0) = 1
                         or coalesce(pir.folder_imported, 0) = 1
                         or lower(coalesce(pir.status,'')) in ('verified','folder_verified','library_visible','kavita_verified')
                         or lower(coalesce(pir.completion_truth,'')) = 'folder'
                     )
                   limit 1
               ) as verified_peer_issue_id
        from wanted_items w
        join issues i on i.id = w.issue_id
        where lower(coalesce(w.status,'')) in ('wanted','queued','searching','retry','missing','in_progress')
          and coalesce(w.issue_id, '') <> ''
          and verified_peer_issue_id is not null
        limit ?
        """,
        (limit,),
    ).fetchall()
    changed = 0
    for row in rows:
        if not verified_import_for_queue(
            con,
            None,
            row["series_id"],
            row["verified_peer_issue_id"],
            require_existing_destination=True,
        ):
            continue
        message = "Duplicate issue row satisfied by verified sibling issue"
        con.execute(
            "update wanted_items set status='satisfied', updated_at=? where id=?",
            (now, row["wanted_id"]),
        )
        wanted_changed = int(con.execute("select changes() as changed").fetchone()["changed"] or 0)
        con.execute(
            """
            update queue_items
               set state='verified',
                   active=0,
                   current_source='duplicate_issue_presence',
                   last_event=?,
                   updated_at=?,
                   outcome='complete',
                   display_phase='verified'
             where active=1
               and (
                   wanted_id=?
                   or issue_id=?
               )
            """,
            (message, now, row["wanted_id"], row["issue_id"]),
        )
        queue_changed = int(con.execute("select changes() as changed").fetchone()["changed"] or 0)
        if wanted_changed or queue_changed:
            changed += 1
            _record_search_history(
                con,
                event_type="duplicate_issue_wanted_satisfied",
                entity_type="wanted_item",
                entity_id=row["wanted_id"],
                series_id=row["series_id"],
                issue_id=row["issue_id"],
                message=message,
                raw={
                    "wanted_id": row["wanted_id"],
                    "issue_id": row["issue_id"],
                    "issue_number": row["issue_number"],
                    "normalized_number": row["normalized_number"],
                    "verified_peer_issue_id": row["verified_peer_issue_id"],
                    "queue_rows_settled": queue_changed,
                },
                source="inkdrop_state",
                now=now,
            )
    return changed


def reconcile_monitored_metadata_only_wanted(con, now, *, limit=250, series_id=None):
    today = datetime.datetime.utcfromtimestamp(now).date().isoformat()
    series_id = str(series_id or "").strip() or None
    rows = con.execute(
        """
        select
            s.id as series_id,
            s.title as series_title,
            s.year as series_year,
            s.publisher as publisher,
            s.metadata_provider as series_metadata_provider,
            s.metadata_id as series_metadata_id,
            s.source as series_source,
            s.raw_json as series_raw_json,
            i.id as issue_id,
            i.issue_number,
            i.normalized_number,
            i.title as issue_title,
            i.release_date,
            i.metadata_provider as issue_metadata_provider,
            i.metadata_id as issue_metadata_id,
            i.kapowarr_issue_id,
            i.raw_json as issue_raw_json
        from issues i
        join series s on s.id = i.series_id
        left join wanted_items w on w.issue_id = i.id
        left join queue_items q on q.issue_id = i.id and q.active = 1
        left join import_results ir on ir.issue_id = i.id and ir.verified = 1
        where coalesce(s.monitored, 0) = 1
          and coalesce(s.auto_grab, 0) = 1
          and coalesce(i.monitored, 1) = 1
          and w.id is null
          and q.id is null
          and ir.id is null
          and coalesce(i.issue_number, '') <> ''
          and coalesce(i.release_date, '') <> ''
          and date(i.release_date) <= date(?)
          and lower(coalesce(s.source, s.metadata_provider, '')) in ('comicvine', 'mangadex')
          and (? is null or s.id = ?)
        order by
          coalesce(s.updated_at, s.created_at, 0) desc,
          s.title asc,
          cast(coalesce(nullif(i.normalized_number, ''), i.issue_number, '999999') as real) asc
        limit ?
        """,
        (today, series_id, series_id, int(limit or 250)),
    ).fetchall()
    changed = 0
    for row in rows:
        series_raw = json_loads(row["series_raw_json"] or "{}", {})
        issue_raw = json_loads(row["issue_raw_json"] or "{}", {})
        watch = dict(series_raw) if isinstance(series_raw, dict) else {}
        watch.update(
            {
                "name": row["series_title"],
                "title": row["series_title"],
                "year": row["series_year"],
                "publisher": row["publisher"],
                "source": row["series_source"] or row["series_metadata_provider"],
                "metadata_provider": row["series_metadata_provider"],
                "metadataProvider": row["series_metadata_provider"],
                "metadata_id": row["series_metadata_id"],
                "metadataId": row["series_metadata_id"],
                "autoGrab": True,
                "monitorNew": True,
            }
        )
        if str(row["series_metadata_provider"] or "").lower() == "comicvine":
            watch["comicvineId"] = row["series_metadata_id"]
        issue = dict(issue_raw) if isinstance(issue_raw, dict) else {}
        issue.update(
            {
                "id": row["issue_metadata_id"] or row["issue_id"],
                "issue_id": row["issue_id"],
                "issueNumber": row["issue_number"],
                "issue": row["issue_number"],
                "title": row["issue_title"] or "",
                "date": row["release_date"],
                "release_date": row["release_date"],
                "metadata_provider": row["issue_metadata_provider"],
                "metadataProvider": row["issue_metadata_provider"],
                "metadata_id": row["issue_metadata_id"],
                "metadataId": row["issue_metadata_id"],
                "kapowarrIssueId": row["kapowarr_issue_id"],
                "status": "missing",
                "created_by": "inkdrop_state.metadata_only_reconcile",
            }
        )
        wanted_id = upsert_wanted(
            con,
            row["series_id"],
            row["issue_id"],
            "metadata_only_reconcile",
            "wanted",
            issue,
            now,
        )
        queue_id = upsert_queue_item_from_watch_issue(
            con,
            row["series_id"],
            row["issue_id"],
            wanted_id,
            watch,
            issue,
            now,
        )
        if wanted_id or queue_id:
            changed += 1
            _record_search_history(
                con,
                event_type="metadata_only_issue_queued",
                entity_type="issue",
                entity_id=row["issue_id"],
                series_id=row["series_id"],
                issue_id=row["issue_id"],
                message="Released metadata-only issue promoted to Wanted queue",
                raw={
                    "wanted_id": wanted_id,
                    "queue_id": queue_id,
                    "series_id": row["series_id"],
                    "issue_id": row["issue_id"],
                    "issue_number": row["issue_number"],
                    "release_date": row["release_date"],
                    "limit": limit,
                },
                source="inkdrop_state",
                now=now,
            )
    return changed


def reconcile_retired_duplicate_wanted_enrollment(con, now, *, limit=500):
    """Re-enroll due wanted units stranded behind only retired duplicate queues."""

    today = datetime.datetime.utcfromtimestamp(now).date().isoformat()
    limit = max(1, min(int(limit or 500), 1000))
    rows = con.execute(
        """
        select w.id as wanted_id, w.series_id, w.issue_id,
               s.title as series, s.media_type, s.year, s.publisher,
               s.metadata_provider, s.metadata_id, s.kapowarr_id,
               s.source as series_source, s.auto_grab, s.raw_json as series_raw_json,
               i.issue_number, i.title as issue_title, i.release_date,
               i.metadata_provider as issue_metadata_provider,
               i.metadata_id as issue_metadata_id, i.kapowarr_issue_id,
               i.raw_json as issue_raw_json, w.raw_json as wanted_raw_json,
               (
                   select q.source_order_json from queue_items q
                   where q.wanted_id=w.id or q.issue_id=w.issue_id
                   order by coalesce(q.updated_at,q.created_at,0) desc, q.id desc limit 1
               ) as queue_source_order_json,
               (
                   select q.recovery_steps_json from queue_items q
                   where q.wanted_id=w.id or q.issue_id=w.issue_id
                   order by coalesce(q.updated_at,q.created_at,0) desc, q.id desc limit 1
               ) as queue_recovery_steps_json
        from wanted_items w
        join series s on s.id=w.series_id
        join issues i on i.id=w.issue_id
        where lower(coalesce(w.status,'wanted')) in ('wanted','queued','searching','retry','missing','in_progress')
          and coalesce(s.monitored,0)=1
          and coalesce(s.auto_grab,0)=1
          and coalesce(i.monitored,1)=1
          and coalesce(i.release_date,'')<>''
          and date(i.release_date)<=date(?)
          and exists (
              select 1 from queue_items retired
              where (retired.wanted_id=w.id or retired.issue_id=w.issue_id)
                and lower(coalesce(retired.state,''))='superseded_duplicate'
          )
          and not exists (
              select 1 from queue_items live
              left join issues live_issue on live_issue.id=live.issue_id
              where (
                    live.wanted_id=w.id
                    or live.issue_id=w.issue_id
                    or (
                        live_issue.series_id=w.series_id
                        and coalesce(nullif(live_issue.normalized_number,''),live_issue.issue_number,'')=
                            coalesce(nullif(i.normalized_number,''),i.issue_number,'')
                    )
                )
                and (
                    coalesce(live.active,0)=1
                    or lower(coalesce(live.state,''))<>'superseded_duplicate'
                )
          )
          and not exists (
              select 1 from import_results ir
              left join issues import_issue on import_issue.id=ir.issue_id
              where (
                    ir.issue_id=w.issue_id
                    or exists (
                        select 1 from queue_items iq
                        where iq.id=ir.queue_id and iq.wanted_id=w.id
                    )
                    or (
                        import_issue.series_id=w.series_id
                        and coalesce(nullif(import_issue.normalized_number,''),import_issue.issue_number,'')=
                            coalesce(nullif(i.normalized_number,''),i.issue_number,'')
                    )
                )
                and (
                    coalesce(ir.verified,0)=1
                    or coalesce(ir.folder_imported,0)=1
                    or lower(coalesce(ir.status,'')) in (
                        'imported','verified','folder_verified','library_visible','kavita_verified'
                    )
                    or lower(coalesce(ir.completion_truth,''))='folder'
                )
          )
          and not exists (
              select 1 from download_tasks dt
              left join issues download_issue on download_issue.id=dt.issue_id
              where (
                    dt.issue_id=w.issue_id
                    or dt.wanted_id=w.id
                    or (
                        download_issue.series_id=w.series_id
                        and coalesce(nullif(download_issue.normalized_number,''),download_issue.issue_number,'')=
                            coalesce(nullif(i.normalized_number,''),i.issue_number,'')
                    )
                )
                and lower(coalesce(dt.state,'')) in ('queued','downloading','import_ready','importing')
                and lower(coalesce(dt.status,'')) not in (
                    'bad_archive','failed','failed_download','retired','superseded_duplicate',
                    'wrong_edition','wrong_series_or_subseries'
                )
          )
        order by coalesce(w.updated_at,w.created_at,0) asc, w.id asc
        limit ?
        """,
        (today, limit),
    ).fetchall()
    changed = 0
    for raw_row in rows:
        row = dict(raw_row)
        watch = series_watch_payload_from_row(row)
        issue = wanted_issue_payload_from_row(row)
        source_order = row_policy_list(row, "source_order")
        recovery_steps = row_policy_list(row, "recovery_steps")
        if source_order:
            watch["source_order"] = source_order
        if recovery_steps:
            watch["recovery_steps"] = recovery_steps
        queue_id = upsert_queue_item_from_watch_issue(
            con,
            row["series_id"],
            row["issue_id"],
            row["wanted_id"],
            watch,
            issue,
            now,
        )
        if not queue_id:
            continue
        queue_row = con.execute("select raw_json from queue_items where id=?", (queue_id,)).fetchone()
        queue_raw = json_loads((queue_row or {})["raw_json"] or "{}", {}) if queue_row else {}
        queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
        queue_raw.update(
            {
                "retired_duplicate_reenrolled": True,
                "retired_duplicate_reenrolled_at": now,
                "retired_duplicate_reenrolled_at_iso": utc_stamp(now),
                "retired_duplicate_reenrolled_wanted_id": row["wanted_id"],
            }
        )
        message = "Retired duplicate history cleared; wanted unit re-enrolled for automatic source selection"
        con.execute(
            """
            update queue_items
               set state='queued', active=1, current_source=null,
                   last_event=?, updated_at=?, retry_after=null, retry_after_iso=null,
                   outcome='pending', display_phase='queued', raw_json=?
             where id=?
            """,
            (message, now, json_dumps(queue_raw), queue_id),
        )
        refresh_queue_provider_status_columns(con, queue_id)
        con.execute(
            "update wanted_items set status='wanted', updated_at=? where id=?",
            (now, row["wanted_id"]),
        )
        _record_search_history(
            con,
            event_type="retired_duplicate_wanted_reenrolled",
            entity_type="wanted_item",
            entity_id=row["wanted_id"],
            series_id=row["series_id"],
            issue_id=row["issue_id"],
            message=message,
            raw={"wanted_id": row["wanted_id"], "queue_id": queue_id},
            source="inkdrop_state",
            now=now,
        )
        changed += 1
    return changed


def wanted_status_rank(status):
    return {
        "satisfied": 100,
        "in_progress": 90,
        "wanted": 50,
        "blocked": 40,
        "failed": 30,
        "inactive": 0,
    }.get(str(status or "").lower(), 10)


def dedupe_series_issue_numbers(con, series_id, now):
    series_id = str(series_id or "").strip()
    if not series_id:
        return 0
    groups = con.execute(
        """
        select normalized_number, count(*) as count
        from issues
        where series_id = ?
          and coalesce(normalized_number, '') <> ''
        group by normalized_number
        having count(*) > 1
        """,
        (series_id,),
    ).fetchall()
    changed = 0
    for group in groups:
        issues = con.execute(
            """
            select i.*,
                   (select count(*) from queue_items q where q.issue_id = i.id) as queue_refs,
                   (select count(*) from source_attempts sa where sa.issue_id = i.id) as source_refs,
                   (select count(*) from import_results ir where ir.issue_id = i.id) as import_refs
            from issues i
            where i.series_id = ?
              and i.normalized_number = ?
            order by
              queue_refs desc,
              source_refs desc,
              import_refs desc,
              case when lower(coalesce(i.title, '')) like 'vol.%' then 0 else 1 end,
              cast(coalesce(i.metadata_id, '999999999') as integer) asc,
              i.updated_at desc
            """,
            (series_id, group["normalized_number"]),
        ).fetchall()
        if len(issues) < 2:
            continue
        providers = {str(row["metadata_provider"] or "").strip().lower() for row in issues}
        metadata_ids = {str(row["metadata_id"] or "").strip() for row in issues if str(row["metadata_id"] or "").strip()}
        if providers == {"mangadex"} and len(metadata_ids) == len(issues):
            continue
        canonical = issues[0]
        canonical_issue_id = canonical["id"]
        canonical_wanted_id = f"wanted:{canonical_issue_id}"
        issue_ids = [row["id"] for row in issues]
        placeholders = ",".join("?" for _ in issue_ids)
        wanted_rows = con.execute(
            f"select * from wanted_items where series_id = ? and issue_id in ({placeholders})",
            (series_id, *issue_ids),
        ).fetchall()
        if wanted_rows:
            best_status = "wanted"
            best_reason = "issue_number_dedupe"
            best_priority = 50
            best_created = now
            raw_rows = []
            for wanted in wanted_rows:
                raw_rows.append(dict(wanted))
                if wanted_status_rank(wanted["status"]) > wanted_status_rank(best_status):
                    best_status = wanted["status"]
                if wanted["reason"]:
                    best_reason = wanted["reason"]
                best_priority = max(best_priority, int(wanted["priority"] or 50))
                best_created = min(best_created, float(wanted["created_at"] or now))
            con.execute(
                """
                insert into wanted_items(id, series_id, issue_id, reason, status, priority, created_at, updated_at, raw_json)
                values(?,?,?,?,?,?,?,?,?)
                on conflict(id) do update set
                  series_id=excluded.series_id,
                  issue_id=excluded.issue_id,
                  reason=excluded.reason,
                  status=excluded.status,
                  priority=max(priority, excluded.priority),
                  updated_at=excluded.updated_at,
                  raw_json=excluded.raw_json
                """,
                (
                    canonical_wanted_id,
                    series_id,
                    canonical_issue_id,
                    best_reason,
                    best_status,
                    best_priority,
                    best_created,
                    now,
                    json_dumps({"deduped_wanted_rows": raw_rows, "deduped_at": now, "deduped_at_iso": utc_stamp(now)}),
                ),
            )
            for wanted in wanted_rows:
                if wanted["id"] == canonical_wanted_id:
                    continue
                con.execute("update queue_items set wanted_id=? where wanted_id=?", (canonical_wanted_id, wanted["id"]))
                con.execute("update source_attempts set wanted_id=? where wanted_id=?", (canonical_wanted_id, wanted["id"]))
                con.execute("delete from wanted_items where id=?", (wanted["id"],))
                changed += 1
        for issue in issues[1:]:
            old_issue_id = issue["id"]
            for table in ("queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
                con.execute(f"update {table} set issue_id=? where issue_id=?", (canonical_issue_id, old_issue_id))
            still_referenced = False
            for table in ("wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
                if con.execute(f"select 1 from {table} where issue_id=? limit 1", (old_issue_id,)).fetchone():
                    still_referenced = True
                    break
            if not still_referenced:
                con.execute("delete from issues where id=?", (old_issue_id,))
                changed += 1
    return changed


def first_nonempty(*values):
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return None


def queue_item_destination_paths(raw_item):
    raw_item = raw_item if isinstance(raw_item, dict) else {}
    paths = []

    def add(value):
        if value:
            paths.append(str(value))

    for key in ("last_import_dest", "imported_path", "dest", "destination"):
        add(raw_item.get(key))
    for key in ("last_import_destinations", "destinations"):
        values = raw_item.get(key)
        if isinstance(values, list):
            for value in values:
                add(value)
    manual = raw_item.get("manual_source_resolution") if isinstance(raw_item.get("manual_source_resolution"), dict) else {}
    for path in manual_source_resolved_destination_paths(manual):
        add(path)
    out = []
    seen = set()
    for path in paths:
        marker = path.replace("\\", "/").rstrip("/")
        if marker and marker not in seen:
            seen.add(marker)
            out.append(path)
    return out


def queue_verified_source_path(raw_item, resolved_row=None):
    raw_item = raw_item if isinstance(raw_item, dict) else {}
    resolved_row = resolved_row if isinstance(resolved_row, dict) else {}
    return first_nonempty(
        resolved_row.get("source_path"),
        resolved_row.get("source_filename"),
        raw_item.get("last_pack_import_source"),
        raw_item.get("last_slskd_candidate"),
        raw_item.get("last_candidate_title"),
        raw_item.get("source_path"),
        raw_item.get("query"),
    )


def queue_verified_import_source(source_path, raw_item=None, resolved_row=None):
    raw_item = raw_item if isinstance(raw_item, dict) else {}
    resolved_row = resolved_row if isinstance(resolved_row, dict) else {}
    explicit_source = str(first_nonempty(resolved_row.get("import_source"), resolved_row.get("source_kind")) or "").strip()
    if explicit_source:
        return explicit_source
    source_text = str(source_path or "")
    if "slskd" in source_text.lower() or resolved_row.get("review_id"):
        return "slskd"
    if raw_item.get("current_source"):
        return str(raw_item.get("current_source"))
    if resolved_row.get("source"):
        return str(resolved_row.get("source"))
    return "queue"


def record_verified_queue_import_result(con, queue_id, wanted_id, series_id, issue_id, raw_item, ts, resolved_row=None):
    if not queue_id:
        return None
    stale_verified_ids = []
    for existing in con.execute(
        "select * from import_results where queue_id=? and verified=1 order by coalesce(created_at,0) desc,id desc",
        (str(queue_id),),
    ).fetchall():
        if (
            import_result_linkage_consistent(con, existing, series_id, issue_id)
            and import_result_strict_completion_valid(con, existing, series_id, issue_id)
        ):
            return existing["id"]
        stale_verified_ids.append(existing["id"])
    raw_item = raw_item if isinstance(raw_item, dict) else {}
    resolved_row = resolved_row if isinstance(resolved_row, dict) else {}
    destinations = manual_source_resolved_destination_paths(resolved_row) if resolved_row else []
    if not destinations:
        destinations = queue_item_destination_paths(raw_item)
    dest_path = destinations[0] if destinations else None
    source_path = queue_verified_source_path(raw_item, resolved_row)
    created_at = safe_float(
        first_nonempty(
            resolved_row.get("ts"),
            (resolved_row.get("verification") or {}).get("verified_at") if isinstance(resolved_row.get("verification"), dict) else None,
            raw_item.get("completed_at"),
            raw_item.get("updated_at"),
        ),
        ts,
    )
    try:
        imported_count = int(resolved_row.get("imported_count") if resolved_row else 0)
    except (TypeError, ValueError):
        imported_count = 0
    try:
        skipped_count = int(resolved_row.get("already_present_count") if resolved_row else 0)
    except (TypeError, ValueError):
        skipped_count = 0
    if not resolved_row and dest_path:
        imported_count = 1
    if not import_result_managed_dest_path_exists(con, dest_path):
        return None
    kind = "manual_source_resolved" if resolved_row else "queue_verified_backfill"
    status = "verified" if resolved_row else "queue_verified"
    outcome = import_result_outcome(status, True, imported_count, skipped_count)
    display_phase = import_result_display_phase(status, True, imported_count, skipped_count, outcome)
    completion_evidence = import_result_completion_evidence(
        status=status,
        verified=True,
        imported_count=imported_count,
        dest_path=dest_path,
        library_visibility_provider="library",
        library_visibility_required=False,
        folder_path_exists=True,
    )
    import_id = stable_id("queue_verified_import", queue_id, dest_path, source_path)
    source_attempt_id = None
    requested_source_attempt_id = str(resolved_row.get("source_attempt_id") or "").strip()
    if requested_source_attempt_id:
        linked_attempt = con.execute(
            """
            select id from source_attempts
            where id=? and queue_id=? and series_id=? and issue_id=?
            limit 1
            """,
            (requested_source_attempt_id, queue_id, series_id, issue_id),
        ).fetchone()
        if linked_attempt:
            source_attempt_id = linked_attempt["id"]
    if not source_attempt_id:
        source_attempt_id = latest_source_attempt_id_for_queue(con, queue_id, created_at)
    payload = {
        "kind": kind,
        "queue_id": queue_id,
        "wanted_id": wanted_id,
        "source_attempt_id": source_attempt_id,
        "source_path": source_path,
        "dest_path": dest_path,
        "destinations": destinations,
        "outcome": outcome,
        "display_phase": display_phase,
        **completion_evidence,
        "resolved_row": resolved_row,
        "queue_item": raw_item,
        "recorded_at": created_at,
        "recorded_at_iso": utc_stamp(created_at),
    }
    con.execute(
        """
        insert into import_results(
            id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path, status, verified,
            outcome, display_phase, completion_truth, folder_imported, library_visibility_required,
            library_visibility_status, library_visibility_provider, imported_count, skipped_count,
            created_at, raw_json
        ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        on conflict(id) do update set
            queue_id=excluded.queue_id,
            source_attempt_id=excluded.source_attempt_id,
            series_id=excluded.series_id,
            issue_id=excluded.issue_id,
            source_path=excluded.source_path,
            dest_path=excluded.dest_path,
            status=excluded.status,
            verified=excluded.verified,
            outcome=excluded.outcome,
            display_phase=excluded.display_phase,
            completion_truth=excluded.completion_truth,
            folder_imported=excluded.folder_imported,
            library_visibility_required=excluded.library_visibility_required,
            library_visibility_status=excluded.library_visibility_status,
            library_visibility_provider=excluded.library_visibility_provider,
            imported_count=excluded.imported_count,
            skipped_count=excluded.skipped_count,
            raw_json=excluded.raw_json
        """,
        (
            import_id,
            queue_id,
            source_attempt_id,
            series_id,
            issue_id,
            source_path,
            dest_path,
            status,
            1,
            outcome,
            display_phase,
            completion_evidence["completion_truth"],
            1 if completion_evidence["folder_imported"] else 0,
            1 if completion_evidence["library_visibility_required"] else 0,
            completion_evidence["library_visibility_status"],
            completion_evidence["library_visibility_provider"],
            imported_count,
            skipped_count,
            created_at,
            json_dumps(payload),
        ),
    )
    proof_row = con.execute(
        "select * from import_results where id=? limit 1",
        (import_id,),
    ).fetchone()
    if not import_result_strict_completion_valid(con, proof_row, series_id, issue_id):
        payload.update(
            {
                "status": "verification_pending",
                "verified": False,
                "outcome": "problem",
                "display_phase": "retry_later",
                "state_resolution": "unproven_verified_snapshot_rejected",
            }
        )
        con.execute(
            """
            update import_results
               set status='verification_pending',verified=0,outcome='problem',
                   display_phase='retry_later',completion_truth='',folder_imported=0,
                   raw_json=?
             where id=?
            """,
            (json_dumps(payload), import_id),
        )
        return None
    if stale_verified_ids:
        placeholders = ",".join("?" for _value in stale_verified_ids)
        con.execute(
            f"""
            update import_results
               set status='stale_verified_proof_superseded',verified=0,
                   outcome='historical',display_phase='retired',folder_imported=0
             where id in ({placeholders}) and id<>? and verified=1
            """,
            (*stale_verified_ids, import_id),
        )
    source = queue_verified_import_source(source_path, raw_item, resolved_row)
    message = dest_path or source_path or raw_item.get("last_event") or "Confirmed in your library"
    con.execute(
        """
        insert or ignore into history_events(
            id, entity_type, entity_id, series_id, issue_id, event_type,
            source, message, outcome, display_phase, created_at, raw_json
        ) values(?,?,?,?,?,?,?,?,?,?,?,?)
        """,
        (
            stable_id("import_history", import_id),
            "import_result",
            import_id,
            series_id,
            issue_id,
            "import_verified",
            source,
            message,
            outcome,
            display_phase,
            created_at,
            json_dumps(payload),
        ),
    )
    if wanted_id:
        con.execute(
            """
            update wanted_items
            set status='satisfied', updated_at=?
            where id=?
            """,
            (created_at, wanted_id),
        )
    refresh_queue_provider_status_columns(con, queue_id)
    return import_id


def pack_import_path_key(value):
    text = str(value or "").replace("\\", "/").rstrip("/")
    return text.lower()


def pack_import_verification_index(verification):
    verification = verification if isinstance(verification, dict) else {}
    out = {}
    for row in verification.get("checked") or []:
        if not isinstance(row, dict):
            continue
        for value in (row.get("dest"), row.get("original_dest"), row.get("last_import_dest")):
            key = pack_import_path_key(value)
            if key:
                out[key] = row
    return out


def pack_import_event_dest(row):
    row = row if isinstance(row, dict) else {}
    return first_nonempty(row.get("dest"), row.get("existing_path"), row.get("destination"), row.get("last_import_dest"))


def pack_import_event_verified(row, kind, verification_by_dest):
    row = row if isinstance(row, dict) else {}
    if kind == "skipped_existing":
        reason = str(row.get("skip_reason") or row.get("reason") or "").lower()
        return bool(
            row.get("state") == "suppressed_completed"
            or row.get("existing_path")
            or "already" in reason
            or "same_file" in reason
            or "present" in reason
        )
    dest = pack_import_event_dest(row)
    verified_row = verification_by_dest.get(pack_import_path_key(dest))
    if not verified_row:
        return False
    return str(verified_row.get("verification_status") or "").lower() in {
        "folder_verified",
        "library_visible",
        "kavita_verified",
        "verified",
    }


def pack_import_event_verification_row(row, verification_by_dest):
    dest = pack_import_event_dest(row)
    if not dest:
        return {}
    verified_row = verification_by_dest.get(pack_import_path_key(dest))
    return verified_row if isinstance(verified_row, dict) else {}


def pack_import_event_library_provider(row, verification_row=None):
    row = row if isinstance(row, dict) else {}
    verification_row = verification_row if isinstance(verification_row, dict) else {}
    provider = str(
        first_nonempty(
            verification_row.get("library_visibility_provider"),
            row.get("library_visibility_provider"),
            row.get("verification_provider"),
        )
        or ""
    ).strip().lower()
    if provider:
        return provider
    if boolish(verification_row.get("komga_visible"), False) or boolish(row.get("komga_visible"), False):
        return "komga"
    if boolish(verification_row.get("kavita_visible"), False) or boolish(row.get("kavita_visible"), False):
        return "kavita"
    return "library"


def pack_import_event_library_visible(row, verification_row=None):
    row = row if isinstance(row, dict) else {}
    verification_row = verification_row if isinstance(verification_row, dict) else {}
    return bool(
        boolish(verification_row.get("library_visible"), False)
        or boolish(verification_row.get("kavita_visible"), False)
        or boolish(verification_row.get("komga_visible"), False)
        or boolish(row.get("library_visible"), False)
        or boolish(row.get("kavita_visible"), False)
        or boolish(row.get("komga_visible"), False)
        or str(verification_row.get("verification_status") or "").strip().lower() in {
            "folder_verified",
            "library_visible",
            "kavita_verified",
            "verified",
        }
    )


def import_status_sync_verification_status(row_kind, verified, verification_row=None):
    verification_row = verification_row if isinstance(verification_row, dict) else {}
    verification_status = str(verification_row.get("verification_status") or "").strip().lower()
    if verified:
        return verification_status if verification_status in {"folder_verified", "library_visible", "kavita_verified"} else "verified"
    if verification_status in {
        "folder_verified",
        "library_visible",
        "waiting_for_library_scan",
        "waiting_for_kavita_scan",
        "library_scan_timeout",
        "kavita_scan_timeout",
        "imported_not_resolved",
        "verification_pending",
    }:
        return verification_status
    if row_kind == "skipped_existing":
        return "suppressed_completed"
    return "imported"


def adapter_neutral_library_status(status, library_visibility_provider=None, library_visible=False):
    status = str(status or "").strip().lower()
    if not bool(library_visible):
        return status
    if status in {"verified", "kavita_verified"}:
        return "library_visible"
    return status


def record_pack_import_results(
    db_path,
    imported=None,
    skipped_existing=None,
    review_id=None,
    pack_path=None,
    series=None,
    title=None,
    verification=None,
    source="pack_import",
):
    def collection_expanded_rows(kind, row):
        row = row if isinstance(row, dict) else {}
        coverage = row.get("collection_coverage")
        if str(row.get("source_unit") or "").strip().lower() != "collected_edition" or not isinstance(coverage, list):
            return [(kind, dict(row))]
        expanded = []
        for coverage_row in coverage:
            if not isinstance(coverage_row, dict):
                continue
            issue_number = first_nonempty(
                coverage_row.get("issue"),
                coverage_row.get("issue_number"),
                coverage_row.get("calculated"),
                coverage_row.get("normalized_number"),
            )
            normalized = normalize_issue_number(issue_number) if issue_number not in (None, "") else ""
            out = dict(row)
            out.update(
                {
                    "queue_id": coverage_row.get("queue_id") or row.get("queue_id"),
                    "wanted_id": coverage_row.get("wanted_id") or row.get("wanted_id"),
                    "series_id": coverage_row.get("series_id") or row.get("series_id"),
                    "issue_id": coverage_row.get("issue_id") or coverage_row.get("native_issue_id") or row.get("issue_id"),
                    "issue": issue_number,
                    "issue_number": issue_number,
                    "normalized_number": normalized or coverage_row.get("calculated") or row.get("normalized_number"),
                    "canonical_issue_number": normalized or issue_number,
                    "collection_coverage_row": dict(coverage_row),
                    "collection_anchor_issue_number": row.get("issue_number"),
                    "collection_coverage_count": len(coverage),
                }
            )
            expanded.append((kind, out))
        return expanded or [(kind, dict(row))]

    def pack_attempt_title(row, fallback_title=None):
        row = row if isinstance(row, dict) else {}
        return first_nonempty(
            row.get("matched_series"),
            row.get("series"),
            row.get("series_title"),
            row.get("title"),
            fallback_title,
        )

    def _record():
        path = Path(db_path)
        if not path.exists():
            return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
        now = time.time()
        rows = []
        for kind, values in (("imported", imported or []), ("skipped_existing", skipped_existing or [])):
            for row in values:
                if isinstance(row, dict):
                    rows.extend(collection_expanded_rows(kind, row))
        verification_by_dest = pack_import_verification_index(verification)
        matched = 0
        recorded = 0
        source_attempts = 0
        deferred = 0
        already_recorded = 0
        unmatched = []
        with connect(path) as con:
            init_schema(con)
            for kind, row in rows:
                row.setdefault("matched_series", row.get("series") or row.get("series_title") or series)
                row.setdefault("series", row.get("matched_series") or row.get("series_title") or series)
                row.setdefault("issue", row.get("issue_number") or row.get("normalized_number"))
                queue = find_queue_for_import(
                    con,
                    row,
                    row.get("series_id"),
                    row.get("issue_id"),
                    require_exact_queue_id=boolish(row.get("require_exact_queue_id"), False),
                )
                if not queue:
                    unmatched.append(
                        {
                            "kind": kind,
                            "series": row.get("series") or row.get("matched_series"),
                            "issue_number": row.get("issue_number") or row.get("normalized_number"),
                            "dest": pack_import_event_dest(row),
                        }
                    )
                    continue
                matched += 1
                dest = pack_import_event_dest(row)
                source_path = row.get("source") or row.get("source_path") or pack_path
                verified = pack_import_event_verified(row, kind, verification_by_dest)
                verification_row = verification_by_dest.get(pack_import_path_key(dest)) or {}
                if verified and verification_row.get("dest"):
                    dest = pack_import_event_dest(verification_row) or dest
                dest_path_ready = import_result_managed_dest_path_exists(con, dest)
                if verified and not dest_path_ready:
                    verified = False
                    verification_row = dict(verification_row or {})
                    verification_row["verification_status"] = "missing_file"
                    verification_row["managed_dest_missing"] = True
                    verification_row["managed_dest_missing_path"] = dest
                attempt_status = (
                    "already_present"
                    if kind == "skipped_existing" and verified
                    else "verified"
                    if verified
                    else str(verification_row.get("verification_status") or "verification_pending")
                )
                attempt = {
                    "source": source,
                    "provider": "local_pack",
                    "protocol": "local",
                    "status": attempt_status,
                    "title": pack_attempt_title(row, title),
                    "pack_title": title or "",
                    "filename": Path(str(source_path)).name if source_path else "",
                    "save_path": str(pack_path or ""),
                    "reason": row.get("skip_reason") or row.get("reason") or kind,
                    "review_id": review_id,
                    "pack_path": str(pack_path or ""),
                    "dest": dest,
                    "raw_event": row,
                    "verification": verification_row,
                }
                source_attempt_id = None
                requested_attempt_id = str(row.get("source_attempt_id") or "").strip()
                if requested_attempt_id:
                    linked_attempt = con.execute(
                        """
                        select id from source_attempts
                        where id=? and queue_id=? and series_id=? and issue_id=?
                        limit 1
                        """,
                        (requested_attempt_id, queue["id"], queue["series_id"], queue["issue_id"]),
                    ).fetchone()
                    if linked_attempt:
                        source_attempt_id = linked_attempt["id"]
                requested_task_id = str(row.get("download_task_id") or "").strip()
                if requested_task_id:
                    linked_task = con.execute(
                        """
                        select id, source_attempt_id, external_id from download_tasks
                        where id=? and queue_id=? and series_id=? and issue_id=?
                          and (?='' or source_attempt_id=?)
                        limit 1
                        """,
                        (
                            requested_task_id,
                            queue["id"],
                            queue["series_id"],
                            queue["issue_id"],
                            requested_attempt_id,
                            requested_attempt_id,
                        ),
                    ).fetchone()
                    if not linked_task:
                        row.pop("download_task_id", None)
                        row.pop("external_id", None)
                        row.pop("slskd_transfer_id", None)
                    else:
                        row["download_task_id"] = linked_task["id"]
                        if not source_attempt_id and linked_task["source_attempt_id"]:
                            task_attempt = con.execute(
                                """
                                select id from source_attempts
                                where id=? and queue_id=? and series_id=? and issue_id=?
                                limit 1
                                """,
                                (
                                    linked_task["source_attempt_id"],
                                    queue["id"],
                                    queue["series_id"],
                                    queue["issue_id"],
                                ),
                            ).fetchone()
                            if task_attempt:
                                source_attempt_id = task_attempt["id"]
                        if linked_task["external_id"]:
                            row["external_id"] = linked_task["external_id"]
                            row["slskd_transfer_id"] = linked_task["external_id"]
                if not source_attempt_id:
                    source_attempt_id = stable_id("pack_import_attempt", queue["id"], review_id, source_path, dest, attempt_status)
                    record_source_attempt(
                        con,
                        queue["id"],
                        queue["wanted_id"],
                        queue["series_id"],
                        queue["issue_id"],
                        attempt,
                        attempt_id=source_attempt_id,
                        started_at=now,
                        completed_at=now,
                    )
                    source_attempts += 1
                if not verified:
                    imported_count = 1 if kind == "imported" else 0
                    skipped_count = 1 if kind == "skipped_existing" else 0
                    outcome = import_result_outcome(attempt_status, False, imported_count, skipped_count)
                    display_phase = import_result_display_phase(attempt_status, False, imported_count, skipped_count, outcome)
                    pending_import_id = stable_id("pack_import_pending", queue["id"], review_id, source_path, dest)
                    pending_payload = {
                        "kind": "pack_import_pending",
                        "queue_id": queue["id"],
                        "wanted_id": queue["wanted_id"],
                        "source_attempt_id": source_attempt_id,
                        "download_task_id": row.get("download_task_id"),
                        "external_id": row.get("external_id") or row.get("slskd_transfer_id"),
                        "source": source,
                        "provider": "local_pack",
                        "protocol": "local",
                        "review_id": review_id,
                        "pack_path": str(pack_path or ""),
                        "pack_title": title or "",
                        "source_path": source_path,
                        "dest_path": dest,
                        "status": attempt_status,
                        "outcome": outcome,
                        "display_phase": display_phase,
                        "raw_event": row,
                        "verification": verification_row,
                        "recorded_at": now,
                        "recorded_at_iso": utc_stamp(now),
                    }
                    con.execute(
                        """
                        insert into import_results(
                            id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path, status, verified,
                            outcome, display_phase, imported_count, skipped_count, created_at, raw_json
                        ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                        on conflict(id) do update set
                            queue_id=excluded.queue_id,
                            source_attempt_id=coalesce(import_results.source_attempt_id, excluded.source_attempt_id),
                            series_id=excluded.series_id,
                            issue_id=excluded.issue_id,
                            source_path=excluded.source_path,
                            dest_path=excluded.dest_path,
                            status=excluded.status,
                            verified=excluded.verified,
                            outcome=excluded.outcome,
                            display_phase=excluded.display_phase,
                            imported_count=excluded.imported_count,
                            skipped_count=excluded.skipped_count,
                            raw_json=excluded.raw_json
                        """,
                        (
                            pending_import_id,
                            queue["id"],
                            source_attempt_id,
                            queue["series_id"],
                            queue["issue_id"],
                            source_path,
                            dest,
                            attempt_status,
                            0,
                            outcome,
                            display_phase,
                            imported_count,
                            skipped_count,
                            now,
                            json_dumps(pending_payload),
                        ),
                    )
                    con.execute(
                        """
                        insert or ignore into history_events(
                            id, entity_type, entity_id, series_id, issue_id, event_type,
                            source, message, outcome, display_phase, created_at, raw_json
                        ) values(?,?,?,?,?,?,?,?,?,?,?,?)
                        """,
                        (
                            stable_id("pack_import_pending_history", pending_import_id, attempt_status),
                            "import_result",
                            pending_import_id,
                            queue["series_id"],
                            queue["issue_id"],
                            "pack_import_pending_verification",
                            source,
                            "Pack import copied file; waiting for library visibility",
                            outcome,
                            display_phase,
                            now,
                            json_dumps(pending_payload),
                        ),
                    )
                    deferred += 1
                    continue
                resolved_row = dict(row)
                resolved_row.update(
                    {
                        "review_id": review_id,
                        "source_path": source_path,
                        "dest": dest,
                        "destinations": [dest] if dest else [],
                        "import_source": source,
                        "pack_path": str(pack_path or ""),
                        "verification": {"checked": [verification_row]} if verification_row else {},
                        "imported_count": 1 if kind == "imported" else 0,
                        "already_present_count": 1 if kind == "skipped_existing" else 0,
                        "source_attempt_id": source_attempt_id,
                        "download_task_id": row.get("download_task_id"),
                        "external_id": row.get("external_id") or row.get("slskd_transfer_id"),
                        "slskd_transfer_id": row.get("slskd_transfer_id") or row.get("external_id"),
                    }
                )
                raw_item = {
                    "current_source": source,
                    "last_pack_import_source": source_path,
                    "last_import_dest": dest,
                    "last_import_destinations": [dest] if dest else [],
                    "last_event": "Pack imported and visible in your library",
                }
                existing_verified = bool(
                    con.execute(
                        "select 1 from import_results where queue_id = ? and verified = 1 limit 1",
                        (queue["id"],),
                    ).fetchone()
                )
                result_id = record_verified_queue_import_result(
                    con,
                    queue["id"],
                    queue["wanted_id"],
                    queue["series_id"],
                    queue["issue_id"],
                    raw_item,
                    now,
                    resolved_row=resolved_row,
                )
                if result_id:
                    recorded += 1
                elif existing_verified:
                    already_recorded += 1
                else:
                    deferred += 1
                    continue
                mark_queue_verified_for_import(con, queue["id"], queue["wanted_id"], now)
            update_sync_meta(con, now, "pack_import_results")
            con.commit()
        return {
            "ok": True,
            "source": source,
            "review_id": review_id,
            "pack_path": str(pack_path or ""),
            "matched": matched,
            "recorded": recorded,
            "already_recorded": already_recorded,
            "source_attempts": source_attempts,
            "deferred": deferred,
            "unmatched": len(unmatched),
            "unmatched_rows": unmatched[:20],
            "synced_at": now,
            "synced_at_iso": utc_stamp(now),
        }

    return with_db_lock_retry(_record, attempts=4, initial_delay=0.75)


def queue_verified_raw_retracted(raw_item):
    if not isinstance(raw_item, dict):
        return False
    retract_reason = str(raw_item.get("retract_reason") or "").strip().lower()
    if retract_reason:
        return True
    event = str(raw_item.get("last_event") or "").strip().lower()
    return bool("retracted" in event or ("quarantined" in event and "language" in event))


def backfill_verified_queue_import_results(con, now):
    rows = con.execute(
        """
        select q.id, q.wanted_id, q.series_id, q.issue_id, q.updated_at, q.raw_json
        from queue_items q
        where q.state = 'verified'
          and not exists (
              select 1
              from import_results ir
              where ir.queue_id = q.id and ir.verified = 1
          )
        """
    ).fetchall()
    count = 0
    for row in rows:
        raw_item = json_loads(row["raw_json"], {}) or {}
        if queue_verified_raw_retracted(raw_item):
            continue
        result_id = record_verified_queue_import_result(
            con,
            row["id"],
            row["wanted_id"],
            row["series_id"],
            row["issue_id"],
            raw_item,
            row["updated_at"] or raw_item.get("completed_at") or now,
            resolved_row=None,
        )
        if result_id:
            count += 1
    return count


QUEUE_VERIFIED_PENDING_SCAN_STATUSES = {
    "verification_pending",
    "waiting_for_library_scan",
    "waiting_for_kavita_scan",
    "imported_not_resolved",
    "library_scan_timeout",
    "kavita_scan_timeout",
}


def backfill_queue_verified_pending_scan_import_results(con, now=None, batch_size=1000, limit=None):
    now = now or time.time()
    batch_size = max(1, min(int(batch_size or 1000), 10000))
    remaining = None if limit is None else max(0, int(limit or 0))
    updated = 0
    db_path_row = con.execute("pragma database_list").fetchone()
    unmonitor_deleted_issues = media_management_bool_setting(
        db_path_row[2] if db_path_row else None, "unmonitor_deleted_issues", False
    )
    status_placeholders = ",".join("?" for _ in QUEUE_VERIFIED_PENDING_SCAN_STATUSES)
    status_params = sorted(QUEUE_VERIFIED_PENDING_SCAN_STATUSES)
    # Keyset cursor on ir.id alone, for the same reason as the legacy
    # folder-completion backfill above: the predicate only stops matching a row
    # once that row is written, and both skip branches below leave their row
    # untouched. Without a cursor the same batch is re-selected forever and
    # every valid row queued behind a skip is starved.
    # id, not (created_at, id): created_at has no type affinity and takes
    # unvalidated importer timestamps, and SQLite sorts TEXT above every
    # numeric, so a non-numeric timestamp compares greater than any float
    # cursor and pins the scan in place.
    cursor = None
    while remaining is None or remaining > 0:
        fetch_limit = batch_size if remaining is None else min(batch_size, remaining)
        cursor_clause = "" if cursor is None else "and ir.id > ?"
        cursor_params = () if cursor is None else (cursor,)
        rows = con.execute(
            f"""
            select
                ir.id,
                ir.queue_id,
                ir.series_id,
                ir.issue_id,
                ir.source_path,
                ir.dest_path,
                ir.status,
                ir.imported_count,
                ir.skipped_count,
                ir.folder_imported,
                ir.library_visibility_required,
                ir.library_visibility_provider,
                ir.created_at,
                ir.raw_json,
                q.wanted_id,
                q.state as queue_state,
                q.raw_json as queue_raw_json
            from import_results ir
            join queue_items q on q.id = ir.queue_id
            where coalesce(ir.verified, 0) = 0
              and q.state = 'verified'
              and lower(coalesce(ir.status, '')) in ({status_placeholders})
            {cursor_clause}
            order by ir.id asc
            limit ?
            """,
            (*status_params, *cursor_params, fetch_limit),
        ).fetchall()
        if not rows:
            break
        # Advance before processing, so both `continue` branches below still move
        # the scan forward. A skip leaves its row matching the predicate, so a
        # cursor advanced only on success would never get past the first one.
        cursor = str(rows[-1]["id"])
        for row in rows:
            queue_raw = json_loads(row["queue_raw_json"] or "{}", {}) or {}
            if queue_verified_raw_retracted(queue_raw):
                continue
            raw = json_loads(row["raw_json"] or "{}", {}) or {}
            if not isinstance(raw, dict):
                raw = {}
            if import_result_wrong_unit_rejected(row, raw):
                continue
            previous_status = str(row["status"] or "").strip()
            imported_count = int(row["imported_count"] or 0)
            skipped_count = int(row["skipped_count"] or 0)
            provider = str(
                raw.get("library_visibility_provider") or row["library_visibility_provider"] or "library"
            ).strip().lower() or "library"
            visibility_required = boolish(
                raw.get("library_visibility_required")
                if "library_visibility_required" in raw
                else row["library_visibility_required"],
                False,
            )
            if not import_result_managed_dest_path_exists(con, row["dest_path"]):
                missing_file_display_phase = "" if unmonitor_deleted_issues else "retry_later"
                raw.update(
                    {
                        "status": "missing_file",
                        "verified": False,
                        "outcome": "problem",
                        "display_phase": missing_file_display_phase,
                        "completion_truth": "",
                        "folder_imported": False,
                        "library_visibility_required": visibility_required,
                        "library_visibility_status": "missing_file",
                        "library_visibility_provider": provider,
                        "managed_dest_missing": True,
                        "managed_dest_missing_path": row["dest_path"],
                        "managed_dest_missing_at": now,
                        "managed_dest_missing_at_iso": utc_stamp(now),
                        "queue_verified_pending_scan_backfill_blocked": True,
                        "previous_status": previous_status,
                        "unmonitored_after_deletion": bool(unmonitor_deleted_issues),
                    }
                )
                con.execute(
                    """
                    update import_results
                       set status='missing_file',
                           verified=0,
                           outcome='problem',
                           display_phase=?,
                           completion_truth='',
                           folder_imported=0,
                           library_visibility_required=?,
                           library_visibility_status='missing_file',
                           library_visibility_provider=?,
                           raw_json=?
                     where id=?
                    """,
                    (
                        missing_file_display_phase,
                        1 if visibility_required else 0,
                        provider,
                        json_dumps(raw),
                        row["id"],
                    ),
                )
                if unmonitor_deleted_issues and row["issue_id"]:
                    con.execute(
                        "update issues set monitored=0, monitored_user_override=0, updated_at=? where id=?",
                        (now, row["issue_id"]),
                    )
                updated += int(con.execute("select changes()").fetchone()[0] or 0)
                continue
            status_value = "library_visible"
            completion_evidence = import_result_completion_evidence(
                status=status_value,
                verified=True,
                imported_count=imported_count,
                dest_path=row["dest_path"],
                library_visibility_provider=provider,
                library_visibility_required=visibility_required,
                folder_path_exists=True,
            )
            raw.update(
                {
                    "status": status_value,
                    "verified": True,
                    "outcome": "productive",
                    "display_phase": "verified",
                    **completion_evidence,
                    "queue_verified_pending_scan_backfilled_at": now,
                    "queue_verified_pending_scan_backfilled_at_iso": utc_stamp(now),
                    "queue_verified_pending_scan_previous_status": previous_status,
                    "verification_source": "queue_verified_pending_scan_backfill",
                }
            )
            con.execute(
                """
                update import_results
                set status=?,
                    verified=1,
                    outcome='productive',
                    display_phase='verified',
                    completion_truth=?,
                    folder_imported=?,
                    library_visibility_required=?,
                    library_visibility_status='library_visible',
                    library_visibility_provider=?,
                    raw_json=?
                where id=?
                """,
                (
                    status_value,
                    completion_evidence["completion_truth"],
                    1 if completion_evidence["folder_imported"] else 0,
                    1 if completion_evidence["library_visibility_required"] else 0,
                    completion_evidence["library_visibility_provider"],
                    json_dumps(raw),
                    row["id"],
                ),
            )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, outcome, display_phase, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("queue_verified_pending_scan_import_history", row["id"], row["queue_id"]),
                    "import_result",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "queue_verified_pending_scan_import",
                    "inkdrop",
                    "Queue verification satisfied legacy library-scan-pending import result",
                    "productive",
                    "verified",
                    now,
                    json_dumps(
                        {
                            "import_id": row["id"],
                            "queue_id": row["queue_id"],
                            "previous_status": previous_status,
                            "completion_truth": completion_evidence["completion_truth"],
                            "folder_imported": completion_evidence["folder_imported"],
                            "library_visibility_status": "library_visible",
                            "library_visibility_provider": completion_evidence["library_visibility_provider"],
                        }
                    ),
                ),
            )
            updated += 1
        con.commit()
        if remaining is not None:
            remaining -= len(rows)
    return updated


def backfill_pending_pack_import_results_from_attempts(con, now, limit=500):
    pending_statuses = {
        "verification_pending",
        "waiting_for_kavita_scan",
        "kavita_scan_timeout",
        "imported_not_resolved",
    }
    rows = con.execute(
        """
        select
            sa.id,
            sa.queue_id,
            sa.wanted_id,
            sa.series_id,
            sa.issue_id,
            sa.source,
            sa.provider,
            sa.status,
            sa.started_at,
            sa.completed_at,
            sa.raw_json,
            q.wanted_id as queue_wanted_id
        from source_attempts sa
        left join queue_items q on q.id = sa.queue_id
        where lower(coalesce(sa.source, '')) = 'pack_import'
          and lower(coalesce(sa.provider, '')) = 'local_pack'
          and lower(coalesce(sa.status, '')) in (
              'verification_pending',
              'waiting_for_kavita_scan',
              'kavita_scan_timeout',
              'imported_not_resolved'
          )
          and not exists (
              select 1 from import_results ir
              where ir.source_attempt_id = sa.id
          )
        order by coalesce(sa.completed_at, sa.started_at, 0) desc
        limit ?
        """,
        (max(1, int(limit or 500)),),
    ).fetchall()
    count = 0
    for row in rows:
        raw = json_loads(row["raw_json"] or "{}", {}) or {}
        if not isinstance(raw, dict):
            raw = {}
        raw_event = raw.get("raw_event") if isinstance(raw.get("raw_event"), dict) else {}
        dest = first_nonempty(raw.get("dest"), raw.get("dest_path"), raw_event.get("dest"))
        if not dest:
            continue
        source_path = first_nonempty(raw_event.get("source"), raw.get("source_path"), raw.get("source"))
        if source_path == "pack_import":
            source_path = first_nonempty(raw_event.get("source"), raw.get("pack_path"), raw.get("save_path"), source_path)
        status = str(first_nonempty(raw.get("status"), row["status"], "verification_pending")).strip().lower()
        if status not in pending_statuses:
            continue
        if con.execute(
            """
            select 1
            from import_results
            where queue_id = ?
              and coalesce(dest_path, '') = ?
            limit 1
            """,
            (row["queue_id"], str(dest)),
        ).fetchone():
            continue
        created_at = safe_float(row["completed_at"] or row["started_at"], now)
        imported_count = 1 if raw_event.get("event") == "pack_import_file" or raw.get("dest") else 0
        skipped_count = 1 if str(raw_event.get("event") or "").startswith("pack_skip") else 0
        outcome = import_result_outcome(status, False, imported_count, skipped_count)
        display_phase = import_result_display_phase(status, False, imported_count, skipped_count, outcome)
        import_id = stable_id(
            "pack_import_pending",
            row["queue_id"],
            raw.get("review_id") or raw_event.get("review_id"),
            source_path,
            dest,
        )
        payload = {
            "kind": "pack_import_pending_backfill",
            "queue_id": row["queue_id"],
            "wanted_id": row["wanted_id"] or row["queue_wanted_id"],
            "source_attempt_id": row["id"],
            "source": "pack_import",
            "provider": "local_pack",
            "protocol": "local",
            "review_id": raw.get("review_id") or raw_event.get("review_id"),
            "pack_path": raw.get("pack_path") or raw.get("save_path"),
            "pack_title": raw.get("pack_title"),
            "source_path": source_path,
            "dest_path": dest,
            "status": status,
            "outcome": outcome,
            "display_phase": display_phase,
            "raw_event": raw_event,
            "source_attempt": raw,
            "backfilled_at": now,
            "backfilled_at_iso": utc_stamp(now),
        }
        con.execute(
            """
            insert into import_results(
                id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path, status, verified,
                outcome, display_phase, imported_count, skipped_count, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(id) do update set
                queue_id=excluded.queue_id,
                source_attempt_id=coalesce(import_results.source_attempt_id, excluded.source_attempt_id),
                series_id=excluded.series_id,
                issue_id=excluded.issue_id,
                source_path=excluded.source_path,
                dest_path=excluded.dest_path,
                status=excluded.status,
                verified=excluded.verified,
                outcome=excluded.outcome,
                display_phase=excluded.display_phase,
                imported_count=excluded.imported_count,
                skipped_count=excluded.skipped_count,
                raw_json=excluded.raw_json
            """,
            (
                import_id,
                row["queue_id"],
                row["id"],
                row["series_id"],
                row["issue_id"],
                source_path,
                dest,
                status,
                0,
                outcome,
                display_phase,
                imported_count,
                skipped_count,
                created_at,
                json_dumps(payload),
            ),
        )
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("pack_import_pending_backfill_history", import_id, status),
                "import_result",
                import_id,
                row["series_id"],
                row["issue_id"],
                "pack_import_pending_backfilled",
                "pack_import",
                "Backfilled pending pack import verification",
                outcome,
                display_phase,
                now,
                json_dumps(payload),
            ),
        )
        count += 1
    return count


QUEUE_ARCHIVE_VALIDATION_CACHE_MAX_AGE_SECONDS = int(
    os.environ.get("INKDROP_ARCHIVE_VALIDATION_CACHE_MAX_AGE_SECONDS") or (14 * 24 * 3600)
)
# The thresholds cached_strict_archive_validation() hands to
# validate_comic_archive(). They live here, next to the max-age window, because
# they are the window's silent partner: a cached verdict is only reusable if it
# was reached under the same definition of "valid". Passing them as bare
# literals at the call site is what let them drift out of the cache key before.
QUEUE_ARCHIVE_VALIDATION_MIN_PAGES = 1
QUEUE_ARCHIVE_VALIDATION_MIN_PAYLOAD_BYTES = 1
# Stored on every cached row and compared on every read. Rows written under a
# different key are ignored, so changing a threshold above -- or the identity
# fields the cache keys on -- retires the old verdicts immediately instead of
# leaving them to answer for up to the full max-age window. Bump the leading
# version whenever either of those changes.
QUEUE_ARCHIVE_VALIDATION_CACHE_VALIDATOR_KEY = (
    f"v2|min_pages={QUEUE_ARCHIVE_VALIDATION_MIN_PAGES}"
    f"|min_payload_bytes={QUEUE_ARCHIVE_VALIDATION_MIN_PAYLOAD_BYTES}"
)


def cached_strict_archive_validation(con, candidate):
    """validate_comic_archive() wrapped with a (path, size, mtime, ctime) cache.

    import_result_strict_completion_valid() is called from ~10 places across
    the queue/wanted reconciliation passes, and those passes re-check every
    already-verified item on every cycle -- not just newly-imported ones.
    Measured live: this was the dominant cost of a full series-autopilot
    sync (500-670s of a ~600-700s cycle), because a .cbr recheck means a real
    RAR extraction every single time, for files that haven't changed since
    they last passed. If the file still looks byte-for-byte like the one that
    passed, skip the real extraction and reuse that result.

    "Still looks like" is size + mtime + ctime, all three, and only for a row
    written under the current validator key. size and mtime alone were not
    enough: every restore-shaped write preserves mtime on purpose. `rsync -a`,
    `cp -p`, `tar -x` and a restic/Backrest restore all put the old mtime back,
    and this deployment runs Backrest nightly. mtime is also trivially forged
    -- os.utime() sets it to anything -- so a rewrite followed by a utime call
    used to ride a cached PASS for the rest of the max-age window. ctime is
    the discriminator that survives all of that: POSIX ctime is the inode
    change time, no syscall can set it, and it moves on an in-place write and
    on a utime() call alike. Verified against a real SMB3 (CIFS vers=3.0)
    library mount rather than assumed: the server keeps a real SMB
    ChangeTime distinct from LastWriteTime, it is stable across reads, and
    live library files carry ctime values days-to-months newer than their
    mtime -- exactly the mtime-preserving copies this now catches.

    What this still does NOT catch, stated plainly:
      * Corruption that never transits the filesystem -- storage-layer bit rot
        on the underlying disk -- changes no stat field at all. Only the
        max-age window forces that back through a real CRC pass.
      * A server that does not maintain a change time (or Windows, where
        st_ctime is the creation time) degrades this to the old size + mtime
        behaviour. That is the pre-existing weakness, not a new one.
    Both are bounded by QUEUE_ARCHIVE_VALIDATION_CACHE_MAX_AGE_SECONDS, which
    is why that window stays.

    Only passes are cached. A failure is never stored, and it deletes any row
    for that path, so a transient fault -- an unrar hiccup, a short read, a
    CIFS blip on a mount measured at 22-24% I/O pressure stall -- costs one
    re-extraction next cycle instead of pinning a healthy file as a problem
    for two weeks. That matters because a False here downgrades a verified
    import to verification_pending/problem/unsafe_completion_rejected. The
    asymmetry is affordable: failures short-circuit (measured 0.19-0.21s on
    the two genuinely bad .cbr files in this library) while passes are the
    expensive full extraction, so re-testing failures every cycle costs well
    under 1% of the sync budget.

    Reading and writing the cache is strictly best-effort. This runs on
    read-only connections (connect_read sets mode=ro and query_only=1) and
    inside contended write transactions, and a cache row we could not read or
    could not store must never change the answer -- the caller treats an
    exception here as "this archive is not valid proof", which on the
    terminal-false-duplicate path is fail-open and would retire an already
    verified file back into search. A database that has not run the ctime
    migration yet fails the SELECT the same way and simply gets no caching.
    Worst case we pay the full validation again next cycle.
    """
    try:
        stat = candidate.stat()
    except OSError:
        return {"ok": False, "reason": "missing_file"}
    size = stat.st_size
    mtime = stat.st_mtime
    ctime = stat.st_ctime
    now = time.time()
    dest_key = str(candidate)
    try:
        row = con.execute(
            "select size, mtime, ctime, validator_key, ok, reason, page_count, validated_at "
            "from queue_archive_validation_cache where dest_path=?",
            (dest_key,),
        ).fetchone()
    except sqlite3.Error:
        row = None
    if (
        row is not None
        # Only passes are reusable. Rows written before failures stopped being
        # cached are still in production databases; re-test them.
        and row["ok"]
        # NULL means the row predates the ctime column: weaker rules, so it is
        # a miss, not a verdict.
        and row["ctime"] is not None
        and row["validator_key"] == QUEUE_ARCHIVE_VALIDATION_CACHE_VALIDATOR_KEY
        and row["size"] == size
        and row["mtime"] == mtime
        and row["ctime"] == ctime
        and (now - (row["validated_at"] or 0)) < QUEUE_ARCHIVE_VALIDATION_CACHE_MAX_AGE_SECONDS
    ):
        return {"ok": True, "reason": row["reason"], "page_count": row["page_count"]}
    import inkdrop_completed_import as completed_import

    archive_check = completed_import.validate_comic_archive(
        candidate,
        min_pages=QUEUE_ARCHIVE_VALIDATION_MIN_PAGES,
        min_payload_bytes=QUEUE_ARCHIVE_VALIDATION_MIN_PAYLOAD_BYTES,
    )
    ok = bool(isinstance(archive_check, dict) and archive_check.get("ok"))
    reason = (archive_check or {}).get("reason") if isinstance(archive_check, dict) else "invalid_result"
    page_count = (archive_check or {}).get("page_count") if isinstance(archive_check, dict) else None
    try:
        if ok:
            con.execute(
                """
                insert into queue_archive_validation_cache (
                    dest_path, size, mtime, ctime, validator_key, ok, reason, page_count, validated_at
                )
                values (?, ?, ?, ?, ?, ?, ?, ?, ?)
                on conflict(dest_path) do update set
                    size=excluded.size,
                    mtime=excluded.mtime,
                    ctime=excluded.ctime,
                    validator_key=excluded.validator_key,
                    ok=excluded.ok,
                    reason=excluded.reason,
                    page_count=excluded.page_count,
                    validated_at=excluded.validated_at
                """,
                (dest_key, size, mtime, ctime, QUEUE_ARCHIVE_VALIDATION_CACHE_VALIDATOR_KEY,
                 1, reason, page_count, now),
            )
        else:
            # A failure is not remembered. Dropping any stored row matters as
            # much as not writing one: without the delete, a pass recorded
            # minutes ago would keep being served for the rest of the max-age
            # window even though the very next real check just failed.
            con.execute(
                "delete from queue_archive_validation_cache where dest_path=?",
                (dest_key,),
            )
    except sqlite3.Error:
        # Read-only connection, or the write lock was held past busy_timeout.
        # We already know the real answer; not being able to remember it is
        # a slower next cycle, not a verdict.
        pass
    return archive_check if isinstance(archive_check, dict) else {"ok": False, "reason": "invalid_result"}


ARCHIVE_COMICINFO_CACHE_MAX_AGE_SECONDS = int(
    os.environ.get("INKDROP_ARCHIVE_COMICINFO_CACHE_MAX_AGE_SECONDS") or (14 * 24 * 3600)
)
# Bump when read_comicinfo() changes what it extracts, so stored rows written
# under the old recipe are misses rather than wrong answers. v2 retires every row
# written by v1: that build could not tell a failed read from a confirmed absence,
# so any stored "no ComicInfo" from it is unsafe to trust and cheap to re-derive.
ARCHIVE_COMICINFO_CACHE_READER_KEY = "comicinfo-v2"
ARCHIVE_COMICINFO_CACHE_MAX_JSON_BYTES = 256 * 1024


def cached_archive_comicinfo(con, path):
    """read_comicinfo() behind the same (size, mtime, ctime) cache as archives.

    Measured on production 2026-08-01: read_comicinfo cost 199s of a 408s import
    sync -- 48.7% -- and all of it ran inside the SQLite write transaction, which
    is most of why the write lock was held 66% of the wall clock. Nearly all of
    that is archive_entry_names(), which has no cache of its own and, for a .cbr,
    forks `7z l -slt` per call (712ms average).

    An in-process memo cannot fix this: the import child is a fresh process every
    pass, so it can only ever catch the within-pass repeats (56 of 277 calls). The
    reconciliation passes re-examine every already-verified row on every cycle, so
    the same unchanged files are re-read forever. Persisting the result is what
    makes the steady state free.

    Cache key discipline is deliberately identical to
    cached_strict_archive_validation(): size AND mtime AND ctime, because every
    restore-shaped write (rsync -a, cp -p, restic/Backrest, which runs nightly
    here) preserves mtime, and os.utime() can forge it -- ctime is the field no
    syscall can set. A row that cannot be read or stored must never change the
    answer; worst case is paying the real read again next cycle.
    """
    import inkdrop_completed_import as completed_import

    try:
        candidate = Path(path)
        stat = candidate.stat()
    except (OSError, TypeError, ValueError):
        return {}
    size = stat.st_size
    mtime = stat.st_mtime
    ctime = stat.st_ctime
    now = time.time()
    key = str(candidate)
    try:
        row = con.execute(
            "select size, mtime, ctime, reader_key, comicinfo_json, read_at "
            "from archive_comicinfo_cache where archive_path=?",
            (key,),
        ).fetchone()
    except sqlite3.Error:
        row = None
    if (
        row is not None
        and row["ctime"] is not None
        and row["reader_key"] == ARCHIVE_COMICINFO_CACHE_READER_KEY
        and row["size"] == size
        and row["mtime"] == mtime
        and row["ctime"] == ctime
        and (now - (row["read_at"] or 0)) < ARCHIVE_COMICINFO_CACHE_MAX_AGE_SECONDS
    ):
        cached = json_loads(row["comicinfo_json"] or "{}", {})
        if isinstance(cached, dict):
            return cached
    info, readable = completed_import.read_comicinfo_status(candidate)
    info = info if isinstance(info, dict) else {}
    if not readable:
        # A read that failed is not evidence that the archive has no ComicInfo,
        # and this cache holds its answer for 14 days. Storing the failure turned
        # one momentary 7z error or locked file into a durable "confirmed no
        # metadata", after which a classifier reading only the filename could
        # take a file whose ComicInfo says issue 7 and accept it as issue 1.
        # Return what we have for this call and remember nothing.
        return info
    payload = json_dumps(info)
    # An oversized ComicInfo is still returned to the caller; it just is not
    # stored, so one pathological archive cannot bloat the state database.
    if len(payload.encode("utf-8", "replace")) <= ARCHIVE_COMICINFO_CACHE_MAX_JSON_BYTES:
        try:
            con.execute(
                """
                insert into archive_comicinfo_cache (
                    archive_path, size, mtime, ctime, reader_key, comicinfo_json, read_at
                )
                values (?, ?, ?, ?, ?, ?, ?)
                on conflict(archive_path) do update set
                    size=excluded.size,
                    mtime=excluded.mtime,
                    ctime=excluded.ctime,
                    reader_key=excluded.reader_key,
                    comicinfo_json=excluded.comicinfo_json,
                    read_at=excluded.read_at
                """,
                (key, size, mtime, ctime, ARCHIVE_COMICINFO_CACHE_READER_KEY, payload, now),
            )
        except sqlite3.Error:
            pass
    return info


ARCHIVE_MEMBER_SEMANTICS_CACHE_MAX_AGE_SECONDS = int(
    os.environ.get("INKDROP_ARCHIVE_SEMANTICS_CACHE_MAX_AGE_SECONDS") or (14 * 24 * 3600)
)
# Bump when archive_member_semantics() changes how it derives semantic_unit or its
# marker coverage, so rows written under the old recipe are misses.
ARCHIVE_MEMBER_SEMANTICS_CACHE_READER_KEY = "semantics-v1"
ARCHIVE_MEMBER_SEMANTICS_CACHE_MAX_JSON_BYTES = 512 * 1024


def cached_archive_member_semantics(con, path, *, fresh=False):
    """archive_member_semantics() persisted across passes.

    It already has an in-process LRU, which is why 162 of 306 calls in a measured
    sync cost nothing. The other 144 are distinct files and cost 199.63s -- 72% of
    a 277s import sync after the ComicInfo cache landed -- because the import child
    is a fresh process every pass, so the LRU starts empty every time and the same
    unchanged files are re-decompressed and re-decoded (PIL) forever.

    fresh=True still means what it says: the caller has evidence the file changed
    (cleanup_wrong_unit_page_pack_import_proofs passes it on a central-directory
    signature mismatch) and must not be served any remembered answer.

    Key discipline matches the other archive caches -- size AND mtime AND ctime.
    Note this is deliberately stronger than the in-process LRU's own key, which is
    (path, mtime_ns, size) and would ride an mtime-preserving in-place rewrite.
    """
    if fresh:
        return inkdrop_artifact_acceptance.archive_member_semantics(path, fresh=True)
    try:
        candidate = Path(path)
        stat = candidate.stat()
    except (OSError, TypeError, ValueError):
        return inkdrop_artifact_acceptance.archive_member_semantics(path)
    size = stat.st_size
    mtime = stat.st_mtime
    ctime = stat.st_ctime
    now = time.time()
    key = str(candidate)
    try:
        row = con.execute(
            "select size, mtime, ctime, reader_key, semantics_json, derived_at "
            "from archive_member_semantics_cache where archive_path=?",
            (key,),
        ).fetchone()
    except sqlite3.Error:
        row = None
    if (
        row is not None
        and row["ctime"] is not None
        and row["reader_key"] == ARCHIVE_MEMBER_SEMANTICS_CACHE_READER_KEY
        and row["size"] == size
        and row["mtime"] == mtime
        and row["ctime"] == ctime
        and (now - (row["derived_at"] or 0)) < ARCHIVE_MEMBER_SEMANTICS_CACHE_MAX_AGE_SECONDS
    ):
        cached = json_loads(row["semantics_json"] or "{}", {})
        if isinstance(cached, dict) and cached.get("checked"):
            return cached
    semantics = inkdrop_artifact_acceptance.archive_member_semantics(path)
    semantics = semantics if isinstance(semantics, dict) else {}
    # Only a completed read is worth remembering. An unchecked result means the
    # path was not a readable .cbz at all, and that is cheap to re-derive.
    if semantics.get("checked"):
        payload = json_dumps(semantics)
        if len(payload.encode("utf-8", "replace")) <= ARCHIVE_MEMBER_SEMANTICS_CACHE_MAX_JSON_BYTES:
            try:
                con.execute(
                    """
                    insert into archive_member_semantics_cache (
                        archive_path, size, mtime, ctime, reader_key, semantics_json, derived_at
                    )
                    values (?, ?, ?, ?, ?, ?, ?)
                    on conflict(archive_path) do update set
                        size=excluded.size,
                        mtime=excluded.mtime,
                        ctime=excluded.ctime,
                        reader_key=excluded.reader_key,
                        semantics_json=excluded.semantics_json,
                        derived_at=excluded.derived_at
                    """,
                    (key, size, mtime, ctime, ARCHIVE_MEMBER_SEMANTICS_CACHE_READER_KEY, payload, now),
                )
            except sqlite3.Error:
                pass
    return semantics


QUEUE_ARTIFACT_IDENTITY_CACHE_MAX_AGE_SECONDS = int(
    os.environ.get("INKDROP_ARTIFACT_IDENTITY_CACHE_MAX_AGE_SECONDS") or (14 * 24 * 3600)
)
# Written on every row and compared on every read, exactly like the archive
# cache's validator key. A stored hash is only reusable if it came out of the
# same recipe, so bump the leading version whenever
# archive_member_semantics() changes how it builds ordered_page_manifest_hash
# or archive_member_manifest_hash, or whenever
# artifact_content_identity_evidence() changes which fields it returns. Rows
# under an older key are a miss immediately instead of answering for the rest
# of the max-age window.
QUEUE_ARTIFACT_IDENTITY_CACHE_VALIDATOR_KEY = (
    "v1|ordered_page_manifest+archive_member_manifest+file_sha256"
)


def cached_artifact_content_identity(con, candidate):
    """artifact_content_identity_evidence() with a (path, size, mtime, ctime) cache.

    Measured on production build 598: direct_import_destination_unit_gate()
    spent 1.11s of a 1.77s-per-item reconciliation deriving this identity --
    0.92s in inkdrop_artifact_acceptance.page_manifest(), which decodes every
    page image in the archive through PIL, and 0.17s hashing the whole file.
    Across the 2438 queue_items sitting in state=verified that is ~72 minutes
    per pass, all of it inside the state write lock. WAL lets readers through
    but not writers, so it is also why auth_login (a write) hangs and why the
    SLSKD staging sweep gets starved. Filesystem stats were 1.5% of the cost:
    the mount is not the problem, the recomputation is.

    The absurdity being fixed is the ratio. All of that work exists to produce
    three hashes that are then looked up in artifact_bad_content_memory, which
    holds twelve rows. A library file that has not changed since the last pass
    has the same identity it had last pass, so derive it once.

    archive_member_semantics() already has an in-process LRU, and it does not
    help here: it dies with the process, and reconciliation runs in short
    passes rather than one long-lived worker. It also never covered the
    sha256, which is a third of the cost on its own.

    What is cached is the identity, not the verdict. That is deliberate and it
    is the whole safety argument. A cached "this file is not on the blocklist"
    would go stale the moment a thirteenth row landed in
    artifact_bad_content_memory, and a known-bad artifact would then walk
    through the gate; guarding that would mean stamping every row with a
    blocklist generation and getting the stamp exactly right forever. Caching
    the identity has no such failure mode. sha256 and the page manifests are
    properties of the bytes on disk, nothing about the blocklist can change
    them, and find_artifact_bad_content_memory() still runs its SELECT against
    the live table on every single call. Do not "optimize" this into a verdict
    cache.

    Staleness is the archive cache's problem, solved the archive cache's way:
    size + mtime + ctime, all three, and only for a row under the current
    validator key. mtime alone is not enough because every restore-shaped
    write preserves it on purpose and os.utime() forges it outright; POSIX
    ctime is the inode change time and no syscall can set it. On a platform
    with no real change time (Windows reports creation time) this degrades to
    size + mtime, which is the same pre-existing weakness the archive cache
    carries, bounded the same way by the max-age window. Nothing sweeps rows
    for files that were later deleted or moved -- neither does
    queue_archive_validation_cache -- so the table tracks library size, at a
    few hundred bytes a row.

    Only a complete-enough identity is stored: a row is written when the
    derivation produced a well-formed sha256, and dropped otherwise, so an
    unreadable file or a short read costs one re-derivation next pass instead
    of pinning a bad answer for two weeks. Manifest hashes are stored as
    derived, empty included -- .cbr archives never produce them (page_manifest
    only reads .cbz) and a .cbz that fails integrity does not either. Empty is
    the safe value to store: artifact_content_identity_evidence() re-runs
    page_manifest() whenever either manifest it is handed is blank, so such a
    file keeps getting a fresh page scan and only skips the sha256.

    That blank-manifest retry means those files enter page_manifest() twice
    per cold pass -- once here, once in the caller's blocklist lookup -- where
    the old code entered once. Measured with a 25-page 13 MiB fixture rather
    than estimated: the second entry costs 0.014 ms for a .cbr (the extension
    check in comic_archive_suffix() ends it), 0.210 ms for a .cbz with corrupt
    members (the failed scan is in ARCHIVE_MEMBER_SEMANTICS_CACHE by then, so
    the retry is an LRU hit) and 0.223 ms for a zip that will not open, against
    291 ms for a first real scan and 9 ms for the sha256 this now skips.
    Storing only complete identities would remove that second entry and cost
    every .cbr its sha256 on every pass, which is the worse trade. Do not make
    blank manifests sticky to save it.

    Cache I/O is best-effort in both directions. This is called on read-only
    connections (connect_read sets mode=ro and query_only=1) and inside
    contended write transactions, and a row we cannot read or cannot store
    must never change the answer. An exception escaping here does not become
    a False: import_result_strict_completion_valid() only wraps its archive
    check, so the unit-gate call on its last line is unguarded and the error
    would tear down the whole reconciliation pass. A database that has not
    created the table yet fails the SELECT the same way and just gets no
    caching.
    """
    try:
        stat = candidate.stat()
    except OSError:
        return None
    size = stat.st_size
    mtime = stat.st_mtime
    ctime = stat.st_ctime
    now = time.time()
    evidence_key = str(candidate)
    try:
        row = con.execute(
            "select size, mtime, ctime, validator_key, file_sha256, content_manifest_hash, "
            "archive_member_manifest_hash, derived_at from queue_artifact_identity_cache "
            "where evidence_path=?",
            (evidence_key,),
        ).fetchone()
    except sqlite3.Error:
        row = None
    if (
        row is not None
        # NULL ctime means the row was written without the discriminator, so
        # it is a miss, not an identity.
        and row["ctime"] is not None
        and row["validator_key"] == QUEUE_ARTIFACT_IDENTITY_CACHE_VALIDATOR_KEY
        and row["size"] == size
        and row["mtime"] == mtime
        and row["ctime"] == ctime
        and (now - (row["derived_at"] or 0)) < QUEUE_ARTIFACT_IDENTITY_CACHE_MAX_AGE_SECONDS
    ):
        digest = str(row["file_sha256"] or "").strip().lower()
        # Re-check the digest shape on the way out, not only on the way in. A
        # truncated or hand-edited value is worse than no cache at all:
        # artifact_content_identity_evidence() skips the real hash for any
        # non-empty digest, then drops the malformed one on its own fullmatch,
        # which leaves find_artifact_bad_content_memory() with no clause to
        # match on and turns the gate into a silent pass. Treat it as a miss.
        if re.fullmatch(r"[a-f0-9]{64}", digest):
            return {
                "file_sha256": digest,
                "content_manifest_hash": str(row["content_manifest_hash"] or "").strip().lower(),
                "archive_member_manifest_hash": str(row["archive_member_manifest_hash"] or "").strip().lower(),
            }
    import inkdrop_completed_import as completed_import

    evidence = completed_import.artifact_content_identity_evidence(candidate)
    evidence = evidence if isinstance(evidence, dict) else {}
    digest = str(evidence.get("file_sha256") or "").strip().lower()
    content_manifest = str(evidence.get("content_manifest_hash") or "").strip().lower()
    member_manifest = str(evidence.get("archive_member_manifest_hash") or "").strip().lower()
    try:
        if re.fullmatch(r"[a-f0-9]{64}", digest):
            con.execute(
                """
                insert into queue_artifact_identity_cache (
                    evidence_path, size, mtime, ctime, validator_key, file_sha256,
                    content_manifest_hash, archive_member_manifest_hash, derived_at
                )
                values (?, ?, ?, ?, ?, ?, ?, ?, ?)
                on conflict(evidence_path) do update set
                    size=excluded.size,
                    mtime=excluded.mtime,
                    ctime=excluded.ctime,
                    validator_key=excluded.validator_key,
                    file_sha256=excluded.file_sha256,
                    content_manifest_hash=excluded.content_manifest_hash,
                    archive_member_manifest_hash=excluded.archive_member_manifest_hash,
                    derived_at=excluded.derived_at
                """,
                (evidence_key, size, mtime, ctime, QUEUE_ARTIFACT_IDENTITY_CACHE_VALIDATOR_KEY,
                 digest, content_manifest or None, member_manifest or None, now),
            )
        else:
            # Dropping the old row matters as much as not writing a new one:
            # without the delete, an identity recorded minutes ago would keep
            # being served even though the derivation we just ran could not
            # reproduce it.
            con.execute(
                "delete from queue_artifact_identity_cache where evidence_path=?",
                (evidence_key,),
            )
    except sqlite3.Error:
        # Read-only connection, missing table, or the write lock was held past
        # busy_timeout. We already have the real answer; not being able to
        # remember it is a slower next pass, not a different verdict.
        pass
    return {
        "file_sha256": digest,
        "content_manifest_hash": content_manifest,
        "archive_member_manifest_hash": member_manifest,
    }


def import_result_strict_completion_valid(con, row, series_id, issue_id, managed_roots=None):
    """Validate one import row before any path may mark queue/wanted complete."""
    if not row or not series_id or not issue_id:
        return False
    if str(row_value(row, "series_id") or "") != str(series_id) or str(row_value(row, "issue_id") or "") != str(issue_id):
        return False
    raw = json_loads(row_value(row, "raw_json") or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    if import_result_is_bad_or_retracted(row) or import_result_has_unsafe_completion_evidence(row, raw):
        return False
    roots = managed_roots if managed_roots is not None else media_management_roots_from_connection(con)
    candidate = canonical_managed_media_file_path(row_value(row, "dest_path"), roots)
    if not candidate:
        return False
    try:
        archive_check = cached_strict_archive_validation(con, candidate)
    except Exception:
        return False
    if not isinstance(archive_check, dict) or not archive_check.get("ok"):
        return False
    identity_row = con.execute(
        """
        select s.title as series, s.media_type, s.raw_json as series_raw_json,
               i.title as issue_title, i.issue_number, i.normalized_number,
               i.raw_json as issue_raw_json
        from series s
        left join issues i on i.id=?
        where s.id=?
        limit 1
        """,
        (issue_id, series_id),
    ).fetchone()
    if not identity_row:
        return False
    series_raw = json_loads(identity_row["series_raw_json"] or "{}", {})
    issue_raw = json_loads(identity_row["issue_raw_json"] or "{}", {})
    queue_context = {
        "series_id": series_id,
        "issue_id": issue_id,
        "raw_json": json_dumps({
            **(series_raw if isinstance(series_raw, dict) else {}),
            **(issue_raw if isinstance(issue_raw, dict) else {}),
            "media_type": identity_row["media_type"],
        }),
        **dict(identity_row),
    }
    queue_context["query"] = " ".join(
        value for value in (
            str(queue_context.get("series") or "").strip(),
            str(queue_context.get("issue_title") or queue_context.get("issue_number") or "").strip(),
        ) if value
    )
    if collection_target_single_part_block_reason(
        queue_context,
        collection_guard_record_from_import_result(row, queue_context),
    ):
        return False
    return not direct_import_destination_unit_gate(con, queue_context, row_value(row, "dest_path"), raw)


def import_result_download_task_ids(raw):
    task_ids = set()
    if not isinstance(raw, dict):
        return task_ids
    stack = [(raw, 0)]
    seen = set()
    nested_keys = {
        "raw", "event", "raw_event", "import_event", "source_event",
        "download_task", "download_client_handoff", "handoff", "record",
    }
    id_keys = ("download_task_id", "task_id", "source_download_task_id", "inkdrop_download_task_id")
    while stack:
        item, depth = stack.pop()
        if not isinstance(item, dict) or depth > 6 or id(item) in seen:
            continue
        seen.add(id(item))
        for key in id_keys:
            value = str(item.get(key) or "").strip()
            if value:
                task_ids.add(value)
        for key in nested_keys:
            nested = item.get(key)
            if isinstance(nested, dict):
                stack.append((nested, depth + 1))
            elif isinstance(nested, list):
                stack.extend((value, depth + 1) for value in nested if isinstance(value, dict))
    return task_ids


def chunks(values, size):
    values = list(values)
    size = max(1, int(size or 1))
    for offset in range(0, len(values), size):
        yield values[offset:offset + size]


def same_unit_issue_ids(con, series_id, issue_id):
    """Every issues row that is the same comic as issue_id.

    A provider sync can leave more than one issues row for a single unit -- a second
    ComicVine id for the same series and the same issue number -- and work recorded
    against one of them then looks like evidence for a different unit. Sibling here
    means all three of: same series, same normalized issue number, and that number is
    actually known. A different series, a different number, an unknown id, or a blank
    number cannot enter this set, so this widens identity only across rows that are the
    same comic by construction.
    """
    series_id = str(series_id or "").strip()
    issue_id = str(issue_id or "").strip()
    ids = [issue_id] if issue_id else []
    if not series_id or not issue_id:
        return ids
    row = con.execute(
        "select series_id, normalized_number from issues where id=? limit 1",
        (issue_id,),
    ).fetchone()
    if not row or str(row["series_id"] or "").strip() != series_id:
        return ids
    number = str(row["normalized_number"] or "").strip()
    if not number:
        return ids
    for other in con.execute(
        "select id from issues where series_id=? and normalized_number=? and id<>? limit 8",
        (series_id, number, issue_id),
    ).fetchall():
        sibling = str(other["id"] or "").strip()
        if sibling:
            ids.append(sibling)
    return ids


def import_result_linkage_consistent(con, row, series_id, issue_id):
    """Require every present proof linkage to resolve to one canonical unit.

    "One unit" means one comic, which is not always one issues row: a duplicate
    provider row for the same series and issue number is the same comic, and a queue
    row on one id with its source attempt on the other must not read as a wrong-unit
    proof. Identity is therefore membership in same_unit_issue_ids() rather than a
    single id. The series check and every wrong-unit check below are unchanged.
    """
    series_id = str(series_id or "").strip()
    issue_id = str(issue_id or "").strip()
    if not row or not series_id or not issue_id:
        return False
    unit_issue_ids = same_unit_issue_ids(con, series_id, issue_id)

    def identity_matches(linked, *, allow_indirect=False):
        if not linked:
            return False
        linked_series = str(row_value(linked, "series_id") or "").strip()
        linked_issue = str(row_value(linked, "issue_id") or "").strip()
        if linked_series and linked_series != series_id:
            return False
        if linked_issue and linked_issue not in unit_issue_ids:
            return False
        return allow_indirect or (linked_series == series_id and linked_issue in unit_issue_ids)

    def queue_matches(queue_id):
        queue_id = str(queue_id or "").strip()
        if not queue_id:
            return False
        linked = con.execute(
            "select id,series_id,issue_id from queue_items where id=? limit 1",
            (queue_id,),
        ).fetchone()
        return identity_matches(linked)

    def attempt_matches(attempt_id):
        attempt_id = str(attempt_id or "").strip()
        if not attempt_id:
            return False
        linked = con.execute(
            "select id,queue_id,series_id,issue_id from source_attempts where id=? limit 1",
            (attempt_id,),
        ).fetchone()
        if not identity_matches(linked, allow_indirect=True):
            return False
        linked_queue_id = str(row_value(linked, "queue_id") or "").strip()
        if linked_queue_id:
            return queue_matches(linked_queue_id)
        return (
            str(row_value(linked, "series_id") or "").strip() == series_id
            and str(row_value(linked, "issue_id") or "").strip() in unit_issue_ids
        )

    import_queue_id = str(row_value(row, "queue_id") or "").strip()
    import_attempt_id = str(row_value(row, "source_attempt_id") or "").strip()
    if import_queue_id and not queue_matches(import_queue_id):
        return False
    if import_attempt_id and not attempt_matches(import_attempt_id):
        return False

    raw = json_loads(row_value(row, "raw_json") or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    explicit_task_ids = import_result_download_task_ids(raw)
    clauses = []
    params = []
    if import_attempt_id:
        clauses.append("source_attempt_id=?")
        params.append(import_attempt_id)
    elif import_queue_id:
        # A queue can contain historical task rows from an older unit after
        # legacy queue-id reuse. When the import carries an exact canonical
        # source attempt, validate only that task lineage; queue_matches() and
        # attempt_matches() above still bind both records to this series/unit.
        clauses.append("queue_id=?")
        params.append(import_queue_id)
    # Same unit, possibly recorded under a duplicate issues row: compare against the
    # sibling set instead of one id. Series comparisons stay exact.
    issue_ph = ",".join("?" for _value in unit_issue_ids)

    def task_mismatch(task_predicate, task_params):
        return con.execute(
            f"""
        select 1
        from download_tasks dt
        where ({task_predicate})
          and (
            (coalesce(dt.series_id,'')<>'' and dt.series_id<>?)
            or (coalesce(dt.issue_id,'')<>'' and dt.issue_id not in ({issue_ph}))
            or (
              coalesce(dt.queue_id,'')<>''
              and not exists (
                select 1 from queue_items tq
                where tq.id=dt.queue_id and tq.series_id=? and tq.issue_id in ({issue_ph})
              )
            )
            or (
              coalesce(dt.source_attempt_id,'')<>''
              and not exists (
                select 1
                from source_attempts tsa
                left join queue_items tsq on tsq.id=tsa.queue_id
                where tsa.id=dt.source_attempt_id
                  and (coalesce(tsa.series_id,'')='' or tsa.series_id=?)
                  and (coalesce(tsa.issue_id,'')='' or tsa.issue_id in ({issue_ph}))
                  and (
                    (coalesce(tsa.queue_id,'')<>'' and tsq.series_id=? and tsq.issue_id in ({issue_ph}))
                    or (
                      coalesce(tsa.queue_id,'')=''
                      and tsa.series_id=? and tsa.issue_id in ({issue_ph})
                    )
                  )
              )
            )
            or (
              coalesce(dt.queue_id,'')=''
              and coalesce(dt.source_attempt_id,'')=''
              and not (dt.series_id=? and dt.issue_id in ({issue_ph}))
            )
          )
        limit 1
        """,
        (
            *task_params,
            series_id, *unit_issue_ids,
            series_id, *unit_issue_ids,
            series_id, *unit_issue_ids, series_id, *unit_issue_ids, series_id, *unit_issue_ids,
            series_id, *unit_issue_ids,
        ),
        ).fetchone()

    if clauses and task_mismatch(" or ".join(clauses), params):
        return False

    # Import events can contain a large list of task references. Validate all
    # of them in bounded IN clauses so crafted evidence cannot exceed SQLite's
    # expression or parameter limits.
    for task_id_batch in chunks(sorted(explicit_task_ids), 200):
        placeholders = ",".join("?" for _value in task_id_batch)
        found = con.execute(
            f"select count(*) from download_tasks where id in ({placeholders})",
            task_id_batch,
        ).fetchone()[0]
        if int(found or 0) != len(task_id_batch):
            return False
        if task_mismatch(f"id in ({placeholders})", task_id_batch):
            return False
    return True


def verified_import_proof_cursor_key(queue_id, series_id=None, issue_id=None):
    identity = f"{queue_id or ''}\n{series_id or ''}\n{issue_id or ''}"
    digest = hashlib.sha256(identity.encode("utf-8", "ignore")).hexdigest()
    return f"verified_import_proof_cursor:{digest}"


def verified_import_proof_cursor(con, key):
    row = con.execute("select value from schema_meta where key=? limit 1", (key,)).fetchone()
    value = json_loads(row["value"] if row else "{}", {})
    return value if isinstance(value, dict) else {}


def set_verified_import_proof_cursor(con, key, cursor=None):
    if not cursor:
        con.execute("delete from schema_meta where key=?", (key,))
        return
    con.execute(
        """
        insert into schema_meta(key,value) values(?,?)
        on conflict(key) do update set value=excluded.value
        """,
        (key, json_dumps(cursor or {})),
    )


# Statuses that mean "we stopped believing this proof", not "this file is bad". A
# folder rename strands dest_path, the proof is written off, and nothing ever looks
# again -- the unit then re-searches forever for a file it already owns. Deliberately
# excludes wrong_unit_quarantined: that is a safety verdict about the file's identity,
# and it is not this pass's job to overturn one.
REVERIFIABLE_IMPORT_STATUSES = frozenset({
    "verification_pending",
    "stale_folder_proof_retracted",
    "missing_file",
})
REVERIFIED_IMPORT_STATUS = "reverified_managed_file"
# validate_comic_archive() CRC-checks every member, so a unit that cannot be re-verified
# must not be re-tested on every reconciliation pass.
REVERIFY_RETRY_SECONDS = 6 * 3600
REVERIFY_ATTEMPTS_PER_PASS = 25


def managed_file_relocation_candidates(con, dest_path, series_id):
    """Where a recorded destination might live now, after a library folder rename."""
    dest_path = str(dest_path or "").strip().replace("\\", "/")
    if not dest_path:
        return []
    candidates = [dest_path]
    leaf = dest_path.rsplit("/", 1)[-1]
    if leaf:
        row = con.execute("select library_path from series where id=? limit 1", (str(series_id),)).fetchone()
        library_path = str((row["library_path"] if row else "") or "").strip().replace("\\", "/").rstrip("/")
        if library_path:
            relocated = f"{library_path}/{leaf}"
            if relocated not in candidates:
                candidates.append(relocated)
    return candidates


def managed_file_identity_signature(path):
    """Cheap fingerprint so a replaced file re-tests immediately, not after a cooldown."""
    try:
        stat = Path(path).stat()
    except OSError:
        return ""
    return f"{path}|{stat.st_size}|{int(stat.st_mtime)}"


def reverify_managed_file_import_proof(con, queue, now, managed_roots=None):
    """Record a fresh proof when a written-off import's file is still in the library.

    This does not resurrect the written-off row. That row's raw_json carries the
    reason it was retracted, and import_result_strict_completion_valid() is right to
    keep rejecting it. Instead this re-checks the file on disk right now -- it exists,
    it is under a managed root, it is a readable archive, and it still resolves to this
    unit -- and writes a new proof carrying that evidence. Every existing safety gate
    runs unchanged against the candidate; nothing is loosened.
    """
    series_id = str(row_value(queue, "series_id") or "").strip()
    issue_id = str(row_value(queue, "issue_id") or "").strip()
    queue_id = str(row_value(queue, "id") or "").strip()
    if not series_id or not issue_id:
        return None
    roots = managed_roots if managed_roots is not None else media_management_roots_from_connection(con)
    rows = con.execute(
        """
        select id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
               status, outcome, display_phase, completion_truth, folder_imported,
               verified, created_at, raw_json
        from import_results
        where series_id=? and issue_id=? and coalesce(verified,0)=0
        order by coalesce(created_at, 0) desc
        limit 25
        """,
        (series_id, issue_id),
    ).fetchall()
    cooldown_key = f"reverify_import_proof:{series_id}:{issue_id}"
    cooldown = json_loads((lambda r: r["value"] if r else "")(
        con.execute("select value from schema_meta where key=? limit 1", (cooldown_key,)).fetchone()
    ) or "{}", {})
    cooldown = cooldown if isinstance(cooldown, dict) else {}
    seen_paths = set()
    for row in rows:
        if str(row["status"] or "").strip().lower() not in REVERIFIABLE_IMPORT_STATUSES:
            continue
        for candidate_path in managed_file_relocation_candidates(con, row["dest_path"], series_id):
            if candidate_path in seen_paths:
                continue
            seen_paths.add(candidate_path)
            # Cheap screens before the archive read: the file has to be there, and has to
            # be somewhere InkDrop manages.
            if not canonical_managed_media_file_path(candidate_path, roots):
                continue
            signature = managed_file_identity_signature(candidate_path)
            if (
                signature
                and signature == str(cooldown.get("signature") or "")
                and safe_float(cooldown.get("at"), 0) > now - REVERIFY_RETRY_SECONDS
            ):
                continue
            probe = dict(row)
            probe["dest_path"] = candidate_path
            probe["queue_id"] = queue_id or row["queue_id"]
            # Judge the file as if it had just landed. The recorded status is the
            # write-off being re-tested, so it must not veto its own re-test -- but the
            # archive, identity, collection and unit gates below all still run.
            probe["status"] = REVERIFIED_IMPORT_STATUS
            probe["outcome"] = ""
            probe["display_phase"] = ""
            probe["completion_truth"] = ""
            probe["raw_json"] = json_dumps({
                "reverified_from_import_id": row["id"],
                "reverified_from_dest_path": row["dest_path"],
                "reverified_at": now,
                "reverified_at_iso": utc_stamp(now),
                "evidence": "managed_file_present",
            })
            con.execute(
                """
                insert into schema_meta(key,value) values(?,?)
                on conflict(key) do update set value=excluded.value
                """,
                (cooldown_key, json_dumps({"at": now, "signature": signature, "path": candidate_path})),
            )
            if not import_result_linkage_consistent(con, probe, series_id, issue_id):
                continue
            if not import_result_strict_completion_valid(con, probe, series_id, issue_id, roots):
                continue
            proof_id = stable_id("reverified_import", series_id, issue_id, candidate_path)
            con.execute(
                """
                insert into import_results(
                    id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
                    status, verified, imported_count, skipped_count, created_at, raw_json,
                    outcome, display_phase, completion_truth, folder_imported
                ) values(?,?,?,?,?,?,?,?,1,1,0,?,?,?,?,?,?)
                on conflict(id) do update set
                    dest_path=excluded.dest_path,
                    status=excluded.status,
                    verified=1,
                    raw_json=excluded.raw_json,
                    outcome=excluded.outcome,
                    display_phase=excluded.display_phase,
                    completion_truth=excluded.completion_truth,
                    folder_imported=excluded.folder_imported
                """,
                (
                    proof_id,
                    probe["queue_id"],
                    row["source_attempt_id"],
                    series_id,
                    issue_id,
                    row["source_path"],
                    candidate_path,
                    REVERIFIED_IMPORT_STATUS,
                    now,
                    probe["raw_json"],
                    "verified",
                    "verified",
                    "file",
                    0,
                ),
            )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, outcome, display_phase, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("import_proof_reverified", proof_id, int(now * 1000)),
                    "import_result",
                    proof_id,
                    series_id,
                    issue_id,
                    "import_proof_reverified",
                    "importer",
                    f"Found this issue's file still in the library at {candidate_path}; import re-verified.",
                    "verified",
                    "verified",
                    now,
                    probe["raw_json"],
                ),
            )
            return proof_id
    return None


def verified_import_for_queue(
    con,
    queue_id,
    series_id=None,
    issue_id=None,
    managed_roots=None,
    *,
    require_existing_destination=True,
    page_size=25,
    max_candidates=100,
    bounded_progress=False,
):
    params = []
    if series_id and issue_id:
        # Canonical content identity is authoritative. A stale or crafted queue
        # id must not relabel another series/unit's import proof.
        params.extend([series_id, issue_id])
        identity_clause = "series_id=? and issue_id=?"
        proof_index = "idx_import_results_series_issue_verified_keyset"
        if queue_id:
            target_queue = con.execute(
                "select series_id,issue_id from queue_items where id=? limit 1",
                (str(queue_id),),
            ).fetchone()
            if (
                not target_queue
                or str(target_queue["series_id"] or "") != str(series_id)
                or str(target_queue["issue_id"] or "") != str(issue_id)
            ):
                return None
    elif queue_id:
        params.append(str(queue_id))
        identity_clause = "queue_id=?"
        proof_index = "idx_import_results_queue_verified_keyset"
    if not ((series_id and issue_id) or queue_id):
        return None
    page_size = max(1, min(int(page_size or 25), 50))
    max_candidates = max(page_size, min(int(max_candidates or 100), 250))
    roots = (
        managed_roots if managed_roots is not None else media_management_roots_from_connection(con)
    ) if require_existing_destination else None
    cursor_key = verified_import_proof_cursor_key(queue_id, series_id, issue_id)
    cursor = verified_import_proof_cursor(con, cursor_key) if bounded_progress else {}
    checked = 0
    before_created_at = safe_float(cursor.get("created_at")) if cursor.get("id") else None
    before_id = str(cursor.get("id") or "")
    wrapped = False
    last_examined = None
    while not bounded_progress or checked < max_candidates:
        page_params = list(params)
        cursor_clause = ""
        if before_created_at is not None:
            cursor_clause = " and (coalesce(created_at, 0) < ? or (coalesce(created_at, 0) = ? and id < ?))"
            page_params.extend([before_created_at, before_created_at, before_id])
        rows = con.execute(
            f"""
            select id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
                   status, outcome, display_phase, completion_truth, folder_imported,
                   verified, created_at, raw_json
            from import_results
                 indexed by {proof_index}
            where {identity_clause} and verified=1{cursor_clause}
            order by coalesce(created_at, 0) desc, id desc
            limit ?
            """,
            (
                *page_params,
                min(page_size, max_candidates - checked) if bounded_progress else page_size,
            ),
        ).fetchall()
        if not rows:
            if bounded_progress and before_id and not wrapped:
                before_created_at = None
                before_id = ""
                wrapped = True
                set_verified_import_proof_cursor(con, cursor_key, {})
                continue
            break
        for row in rows:
            checked += 1
            last_examined = row
            canonical_series_id = series_id or row["series_id"]
            canonical_issue_id = issue_id or row["issue_id"]
            if not import_result_linkage_consistent(
                con,
                row,
                canonical_series_id,
                canonical_issue_id,
            ):
                continue
            if require_existing_destination and not import_result_strict_completion_valid(
                con,
                row,
                canonical_series_id,
                canonical_issue_id,
                managed_roots=roots,
            ):
                continue
            if bounded_progress:
                set_verified_import_proof_cursor(con, cursor_key, {})
            return row
        before_created_at = safe_float(rows[-1]["created_at"]) or 0
        before_id = str(rows[-1]["id"])
        if len(rows) < page_size:
            break
    if bounded_progress and last_examined is not None and checked >= max_candidates:
        set_verified_import_proof_cursor(
            con,
            cursor_key,
            {"created_at": safe_float(last_examined["created_at"]) or 0, "id": str(last_examined["id"])},
        )
    elif bounded_progress and checked < max_candidates:
        set_verified_import_proof_cursor(con, cursor_key, {})
    return None


def verified_import_by_sibling_normalized_number(
    con, series_id, issue_id, managed_roots=None, *, require_linkage_consistent=False
):
    """Two metadata providers (observed: comicvine + kapowarr) can each mint
    their own issues row for the same physical issue -- same series,
    identical normalized_number, different id. When the queue's own issue_id
    has no proof, check whether a sibling issues row in the same series with
    the same normalized_number does. The candidate is re-validated against
    its OWN issue_id through the full strict check (archive contents, unit
    gate, collection guard, live destination existence) -- this widens which
    issue_id counts as "this issue," it does not weaken what counts as
    proof. Confirmed against production data: 649 of 650 duplicate
    (series_id, normalized_number) pairs are exactly a comicvine/kapowarr
    pair for the same content; the one exception is the same issue in two
    title spellings, not a different issue.

    require_linkage_consistent adds the second gate verified_import_for_queue
    applies on the exact-issue path. Callers that are about to *write*
    satisfied state pass it; the durable-snapshot caller, which only decides
    whether to leave an already-verified item alone, does not -- the same
    asymmetry that path already takes with require_existing_destination.
    Measured live: of 95 reopened items a sibling proof could satisfy, 85 also
    clear linkage. The 10 that do not are one queue item that produced imports
    filed under both ids of the pair, so its queue row matches one side and the
    proof the other."""
    series_id = str(series_id or "").strip()
    issue_id = str(issue_id or "").strip()
    if not series_id or not issue_id:
        return None
    normalized_row = con.execute(
        "select normalized_number from issues where id=? and series_id=?",
        (issue_id, series_id),
    ).fetchone()
    normalized_number = str((normalized_row[0] if normalized_row else "") or "").strip()
    if not normalized_number:
        return None
    siblings = con.execute(
        "select id from issues where series_id=? and normalized_number=? and id<>?",
        (series_id, normalized_number, issue_id),
    ).fetchall()
    if not siblings:
        return None
    roots = managed_roots if managed_roots is not None else media_management_roots_from_connection(con)
    for (sibling_issue_id,) in siblings:
        rows = con.execute(
            """
            select id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
                   status, outcome, display_phase, completion_truth, folder_imported,
                   verified, created_at, raw_json
            from import_results
            where series_id=? and issue_id=? and verified=1
            order by coalesce(created_at, 0) desc
            limit 10
            """,
            (series_id, sibling_issue_id),
        ).fetchall()
        for row in rows:
            # Linkage first: it is pure SQL, while the strict check opens the
            # archive off disk.
            if require_linkage_consistent and not import_result_linkage_consistent(
                con, row, series_id, sibling_issue_id
            ):
                continue
            if import_result_strict_completion_valid(con, row, series_id, sibling_issue_id, managed_roots=roots):
                return row
    return None


def queue_verified_snapshot_durable_evidence(
    con, item, resolved_row=None, managed_roots=None, *, series_id=None, issue_id=None, queue_id=None
):
    """A verified import ledger row is durable proof even when the live
    destination recheck can't be repeated right now (e.g. a transient mount
    hiccup) -- unlike the caller's strict check, this does not require
    require_existing_destination. Still goes through the same series_id +
    issue_id + queue_id linkage-consistency check verified_import_for_queue
    always applies, so a queue item whose identity has since drifted from
    the import_results row it produced is correctly left unrecovered rather
    than trusted. Falls back to a sibling-issue-id match (see
    verified_import_by_sibling_normalized_number) when the exact match
    fails."""
    if resolved_row or not ((series_id and issue_id) or queue_id):
        return None
    direct = verified_import_for_queue(
        con,
        queue_id,
        series_id,
        issue_id,
        managed_roots=managed_roots,
        require_existing_destination=False,
    )
    if direct:
        return direct
    if series_id and issue_id:
        return verified_import_by_sibling_normalized_number(con, series_id, issue_id, managed_roots=managed_roots)
    return None


def settle_queue_items_with_verified_imports(
    con,
    now,
    *,
    limit=None,
    after_queue_id="",
    return_progress=False,
):
    limit_value = None if limit is None else max(1, min(int(limit or 100), 1000))
    cursor = str(after_queue_id or "") if limit_value is not None else ""
    query = """
        select q.id, q.wanted_id, q.series_id, q.issue_id, q.state, q.active,
               q.updated_at, q.query, q.raw_json, s.title as series,
               i.title as issue_title, i.issue_number, i.normalized_number
        from queue_items q
        left join series s on s.id = q.series_id
        left join issues i on i.id = q.issue_id
        where q.state not in ('verified', 'satisfied', 'superseded_duplicate')
          and coalesce(q.series_id, '') <> ''
          and coalesce(q.issue_id, '') <> ''
          and (
              exists (
                  select 1
                  from import_results ir
                  where ir.verified = 1
                    and ir.series_id = q.series_id
                    and ir.issue_id = q.issue_id
              )
              -- Proof filed under a sibling issue row for the same issue. Two
              -- metadata providers can each mint an issues row for the same
              -- series and normalized_number, and the queue item and its own
              -- import proof can end up on opposite sides of that pair. Without
              -- this arm those items are never even candidates, so nothing ever
              -- promotes them and their Wanted rows stay open forever.
              or exists (
                  select 1
                  from issues si
                  join import_results ir2
                    on ir2.verified = 1
                   and ir2.series_id = q.series_id
                   and ir2.issue_id = si.id
                  where si.series_id = q.series_id
                    and coalesce(si.normalized_number, '') <> ''
                    and si.normalized_number = i.normalized_number
                    and si.id <> q.issue_id
              )
          )
    """
    params = []
    if cursor:
        query += " and q.id > ?"
        params.append(cursor)
    query += """
        order by q.id asc
        """
    if limit_value is not None:
        query += " limit ?"
        params.append(limit_value)
    rows = con.execute(query, params).fetchall()
    if not rows and cursor:
        return settle_queue_items_with_verified_imports(
            con,
            now,
            limit=limit_value,
            after_queue_id="",
            return_progress=return_progress,
        )
    settled = 0
    for row in rows:
        verified_import = verified_import_for_queue(
            con,
            row["id"],
            row["series_id"],
            row["issue_id"],
            require_existing_destination=True,
            bounded_progress=True,
        )
        if not verified_import:
            verified_import = verified_import_by_sibling_normalized_number(
                con,
                row["series_id"],
                row["issue_id"],
                require_linkage_consistent=True,
            )
        if not verified_import:
            continue
        proof_issue_id = str(row_value(verified_import, "issue_id") or "")
        from_sibling_issue = bool(proof_issue_id) and proof_issue_id != str(row["issue_id"] or "")
        cursor_key = verified_import_proof_cursor_key(row["id"], row["series_id"], row["issue_id"])
        ts = max(
            safe_float(row["updated_at"]) or 0,
            safe_float(verified_import["created_at"]) or 0,
            now,
        )
        if mark_queue_verified_for_import(con, row["id"], row["wanted_id"], ts):
            set_verified_import_proof_cursor(
                con,
                cursor_key,
                {},
            )
            settled += 1
            try:
                import inkdrop_notifications
                db_path_row = con.execute("pragma database_list").fetchone()
                notify_db_path = db_path_row[2] if db_path_row else None
                inkdrop_notifications.notify_wanted_cleared(
                    notify_db_path,
                    series=row["series"],
                    issue_title=row["issue_title"],
                    issue_number=row["issue_number"],
                    dest_path=row_value(verified_import, "dest_path"),
                    source_path=row_value(verified_import, "source_path"),
                )
            except Exception:
                pass
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("queue_verified_by_import", row["id"], verified_import["id"]),
                    "queue_item",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "queue_verified_by_import",
                    "importer",
                    (
                        "Managed-folder import proof, filed under this issue's duplicate row, satisfied this queue item"
                        if from_sibling_issue
                        else "Managed-folder import proof satisfied this queue item"
                    ),
                    ts,
                    json_dumps(
                        {
                            "queue_id": row["id"],
                            "wanted_id": row["wanted_id"],
                            "import_id": verified_import["id"],
                            "previous_state": row["state"],
                            "previous_active": bool(row["active"]),
                            **(
                                {"proof_issue_id": proof_issue_id, "proof_from_sibling_issue": True}
                                if from_sibling_issue
                                else {}
                            ),
                        }
                    ),
                ),
            )
    if not return_progress:
        return settled
    next_cursor = rows[-1]["id"] if limit_value is not None and len(rows) >= limit_value else ""
    return {
        "settled": settled,
        "examined": len(rows),
        "cursor": next_cursor,
    }


def sync_verified_import_projection(
    db_path,
    *,
    limit=100,
    timeout_seconds=None,
    busy_timeout_ms=None,
    lock_attempts=2,
    lock_initial_delay=0.25,
):
    """Promptly project strict verified-import evidence without a broad state scan."""
    path = Path(db_path)

    def _sync():
        started = time.perf_counter()
        now = time.time()
        with connect(
            path,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
            autocommit=True,
        ) as con:
            init_schema(con)
            cursor_row = con.execute(
                "select value from schema_meta where key='verified_import_projection_cursor' limit 1"
            ).fetchone()
            cursor = str(cursor_row["value"] or "") if cursor_row else ""
            projection = settle_queue_items_with_verified_imports(
                con,
                now,
                limit=limit,
                after_queue_id=cursor,
                return_progress=True,
            )
            folder_cursor_row = con.execute(
                "select value from schema_meta where key='folder_presence_projection_cursor' limit 1"
            ).fetchone()
            folder_cursor = str(folder_cursor_row["value"] or "") if folder_cursor_row else ""
            folder_projection = backfill_existing_folder_presence_import_results(
                con,
                now,
                limit=limit,
                apply_limit=limit,
                after_queue_id=folder_cursor,
                return_progress=True,
            )
            con.execute(
                """
                insert into schema_meta(key,value) values('verified_import_projection_cursor',?)
                on conflict(key) do update set value=excluded.value
                """,
                (projection["cursor"],),
            )
            con.execute(
                """
                insert into schema_meta(key,value) values('folder_presence_projection_cursor',?)
                on conflict(key) do update set value=excluded.value
                """,
                (folder_projection["cursor"],),
            )
            update_sync_meta(con, now, "verified_import_projection")
            con.commit()
        return {
            "ok": True,
            "db_path": str(path),
            "sync_mode": "projection",
            "verified_import_queue_settled": projection["settled"],
            "verified_import_candidates_examined": projection["examined"],
            "projection_cursor_advanced": bool(projection["cursor"]),
            "folder_presence_checked": folder_projection["checked"],
            "folder_presence_verified": folder_projection["verified"],
            "folder_presence_skipped": folder_projection["skipped"],
            "folder_presence_cursor_advanced": bool(folder_projection["cursor"]),
            "limit": max(1, min(int(limit or 100), 1000)),
            "elapsed_seconds": round(time.perf_counter() - started, 6),
            "synced_at": now,
            "synced_at_iso": utc_stamp(now),
        }

    return with_db_lock_retry(
        _sync,
        attempts=max(1, int(lock_attempts or 1)),
        initial_delay=max(0.01, float(lock_initial_delay or 0.01)),
    )


def sync_completion_integrity(
    db_path,
    *,
    limit=500,
    timeout_seconds=None,
    busy_timeout_ms=None,
    lock_attempts=2,
    lock_initial_delay=0.25,
):
    """Run bounded completion-proof safety cleanup without broad ingestion."""
    path = Path(db_path)
    bounded_limit = max(1, min(int(limit or 500), 1000))

    def _sync():
        started = time.perf_counter()
        now = time.time()
        with connect(
            path,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
            autocommit=True,
        ) as con:
            init_schema(con)

            def run_stage(stage, callback):
                key = f"completion_integrity_cursor:{stage}"
                cursor_row = con.execute(
                    "select value from schema_meta where key=? limit 1",
                    (key,),
                ).fetchone()
                cursor = json_loads(cursor_row["value"] if cursor_row else "{}", {})
                cursor = cursor if isinstance(cursor, dict) else {}
                result = callback(con, now, limit=bounded_limit, cursor=cursor)
                result = result if isinstance(result, dict) else {"count": int(result or 0)}
                progress = result.pop("_progress", {})
                next_cursor = progress.get("cursor") if isinstance(progress, dict) else None
                con.execute(
                    """
                    insert into schema_meta(key,value) values(?,?)
                    on conflict(key) do update set value=excluded.value
                    """,
                    (key, json_dumps(next_cursor or {})),
                )
                result["examined"] = int((progress or {}).get("examined") or 0)
                result["cursor_advanced"] = bool(next_cursor)
                return result

            missing = run_stage("missing_folder", cleanup_missing_folder_verified_import_proofs)
            wrong_unit = run_stage("wrong_unit_page_pack", cleanup_wrong_unit_page_pack_import_proofs)
            contradictory = run_stage("contradictory_provenance", cleanup_contradictory_completion_provenance)
            update_sync_meta(con, now, "completion_integrity")
            con.commit()
        return {
            "ok": True,
            "db_path": str(path),
            "sync_mode": "integrity",
            "limit": bounded_limit,
            "synced": {
                "missing_folder_import_proofs_retracted": missing,
                "wrong_unit_page_pack_import_proofs_retracted": wrong_unit,
                "contradictory_completion_provenance_retracted": contradictory,
            },
            "elapsed_seconds": round(time.perf_counter() - started, 6),
            "synced_at": now,
            "synced_at_iso": utc_stamp(now),
        }

    return with_db_lock_retry(
        _sync,
        attempts=max(1, int(lock_attempts or 1)),
        initial_delay=max(0.01, float(lock_initial_delay or 0.01)),
    )


# --- Event-history retention -------------------------------------------------
#
# history_events and source_attempts are append-only evidence tables with no
# natural ceiling. Measured against the production state database, which held
# 46 days of history: history_events was at 2.01M rows growing ~60k rows/day at
# ~3.2KB per row, and source_attempts was at 644k rows growing ~20k rows/day at
# ~1.2KB per row. That is roughly 215 MB/day of pure log growth and it is most
# of a 13 GB state file -- which is what makes `pragma quick_check` and backup
# passes crawl.
#
# Retention is age-based and split per category so the user-facing Lifecycle
# feed can outlive throwaway Diagnostic telemetry if an install wants that.
# All three windows are still far wider than anything that actually reads
# these rows for a decision: the widest programmatic lookback against
# source_attempts is 24h (the retry and provider-cooldown queries in
# inkdrop_source_worker_scheduler) and the widest analytic one is the 7-day
# cap in inkdrop_acquisition_funnel.
#
# The lifecycle and attempt windows were 90 days, which is wider than any
# install had existed, so those two categories had never aged out a single
# row anywhere. A month of evidence is a month more than anything queries,
# and it is the difference between a state file that levels off and one that
# only grows. Installs that want the old behaviour set INKDROP_RETENTION_*.
RETENTION_HISTORY_DIAGNOSTIC_DAYS = 30
RETENTION_HISTORY_LIFECYCLE_DAYS = 30
RETENTION_SOURCE_ATTEMPT_DAYS = 30
RETENTION_BATCH_SIZE = 500
RETENTION_MAX_DELETES_PER_RUN = 5000
# Bound the "how much is left" probe so reporting never turns into a full scan
# of a multi-million row table while the write lock is contended.
RETENTION_REMAINING_PROBE_CAP = 100000
# These two event types back the rollback templates in the series-merge tooling
# (see retire_series_shadow / merge_series_shadow_refs). They are a few dozen
# rows in total; never age them out.
RETENTION_PROTECTED_EVENT_TYPES = ("series_shadow_retired", "series_shadow_refs_merged")


def _retention_int_env(name, default, minimum, maximum):
    raw = str(os.environ.get(name, "")).strip()
    try:
        value = int(raw) if raw else int(default)
    except ValueError:
        value = int(default)
    return max(int(minimum), min(int(maximum), value))


def _retention_categories(con, now, *, diagnostic_days, lifecycle_days, source_attempt_days):
    """Build the ordered prune plan for this database.

    source_attempts comes first so its paired history rows are removed as a
    cascade in the same transaction, matching how the existing download-task and
    duplicate-activity cleanups already retire an entity together with its
    history. Guards below are not cosmetic: on production 260k of 644k
    source_attempts rows are referenced by a download task, an import result or
    a manual-search grab, and those references are how imports prove provenance.
    """
    categories = []
    history_present = table_exists(con, "history_events")

    if table_exists(con, "source_attempts"):
        guards = []
        for table, column in (
            ("download_tasks", "source_attempt_id"),
            ("import_results", "source_attempt_id"),
            ("manual_search_grab_results", "source_attempt_id"),
        ):
            if table_exists(con, table):
                guards.append(f"not exists (select 1 from {table} ref where ref.{column} = t.id)")
        if table_exists(con, "queue_items"):
            # An active queue item is still being reasoned about by the
            # autoresolve and source-worker guards, several of which correlate
            # over that item's whole attempt history with no time bound.
            guards.append(
                "not exists (select 1 from queue_items q where q.id = t.queue_id and coalesce(q.active, 0) = 1)"
            )
        guard_sql = ("\n              and " + "\n              and ".join(guards)) if guards else ""
        categories.append({
            "name": "source_attempts",
            "table": "source_attempts",
            "id_column": "id",
            # Matches idx_source_attempts_recent_activity, so the oldest
            # eligible rows are found by an index seek instead of a table scan
            # that gets slower the more of the backlog has already drained.
            "order_expr": "coalesce(t.completed_at, t.started_at, 0)",
            "cascade_history_entity_type": "source_attempt" if history_present else "",
            "cutoff": float(now) - source_attempt_days * 86400,
            "retention_days": source_attempt_days,
            "predicate": (
                "coalesce(t.completed_at, t.started_at, 0) > 0"
                "\n              and coalesce(t.completed_at, t.started_at, 0) < ?"
                f"{guard_sql}"
            ),
            "params": (),
        })

    if history_present:
        history_guards = [
            "t.event_type not in ({})".format(", ".join("?" for _ in RETENTION_PROTECTED_EVENT_TYPES)),
        ]
        history_params = tuple(RETENTION_PROTECTED_EVENT_TYPES)
        if table_exists(con, "queue_items"):
            # inkdrop_source_worker_batch counts a queue item's
            # 'source_worker_aged_zero_coverage_reserved' events with no time
            # bound to decide whether a reservation already happened. Aging that
            # evidence out from under a live queue item would silently change
            # scheduling behaviour, so live items keep their whole history.
            history_guards.append(
                "not (t.entity_type = 'queue_item' and exists ("
                "select 1 from queue_items q where q.id = t.entity_id and coalesce(q.active, 0) = 1))"
            )
        guard_sql = "\n              and " + "\n              and ".join(history_guards)
        for bucket, days in (("diagnostic", diagnostic_days), ("lifecycle", lifecycle_days)):
            categories.append({
                "name": f"history_events_{bucket}",
                "table": "history_events",
                "id_column": "id",
                # Matches idx_history_bucket_created(history_bucket, created_at).
                "order_expr": "t.created_at",
                "cascade_history_entity_type": "",
                "cutoff": float(now) - days * 86400,
                "retention_days": days,
                "predicate": (
                    "t.created_at > 0"
                    "\n              and t.created_at < ?"
                    "\n              and t.history_bucket = ?"
                    f"{guard_sql}"
                ),
                "params": (bucket, *history_params),
            })
    return categories


def prune_event_history(
    db_path,
    *,
    diagnostic_days=None,
    lifecycle_days=None,
    source_attempt_days=None,
    batch_size=None,
    max_deletes=None,
    now=None,
    timeout_seconds=None,
    busy_timeout_ms=None,
    lock_attempts=2,
    lock_initial_delay=0.25,
):
    """Age out append-only evidence rows in short, bounded write transactions.

    Every batch is its own `begin immediate` transaction so the write lock is
    handed back between batches. A single large DELETE against a 2M row table
    would hold that lock long enough to stall the acquisition workers, which all
    write to this same database.
    """
    path = Path(db_path)
    diagnostic_days = (
        _retention_int_env("INKDROP_RETENTION_HISTORY_DIAGNOSTIC_DAYS", RETENTION_HISTORY_DIAGNOSTIC_DAYS, 1, 3650)
        if diagnostic_days is None
        else max(1, int(diagnostic_days))
    )
    lifecycle_days = (
        _retention_int_env("INKDROP_RETENTION_HISTORY_LIFECYCLE_DAYS", RETENTION_HISTORY_LIFECYCLE_DAYS, 1, 3650)
        if lifecycle_days is None
        else max(1, int(lifecycle_days))
    )
    source_attempt_days = (
        _retention_int_env("INKDROP_RETENTION_SOURCE_ATTEMPT_DAYS", RETENTION_SOURCE_ATTEMPT_DAYS, 1, 3650)
        if source_attempt_days is None
        else max(1, int(source_attempt_days))
    )
    batch_size = (
        _retention_int_env("INKDROP_RETENTION_BATCH_SIZE", RETENTION_BATCH_SIZE, 25, 5000)
        if batch_size is None
        else max(1, min(int(batch_size), 5000))
    )
    max_deletes = (
        _retention_int_env("INKDROP_RETENTION_MAX_DELETES_PER_RUN", RETENTION_MAX_DELETES_PER_RUN, 100, 500000)
        if max_deletes is None
        else max(0, int(max_deletes))
    )

    def _prune():
        started = time.perf_counter()
        stamp = time.time() if now is None else float(now)
        deleted = {}
        remaining = {}
        cutoffs = {}
        cascaded = 0
        budget = int(max_deletes)
        with connect(
            path,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
            autocommit=True,
        ) as con:
            init_schema(con)
            categories = _retention_categories(
                con,
                stamp,
                diagnostic_days=diagnostic_days,
                lifecycle_days=lifecycle_days,
                source_attempt_days=source_attempt_days,
            )
            for category in categories:
                name = category["name"]
                table = category["table"]
                id_column = category["id_column"]
                params = (category["cutoff"], *category["params"])
                where_sql = category["predicate"]
                # Oldest first: retention should retire the coldest evidence, and
                # ascending order on the matching age index lets each batch be an
                # index seek rather than a scan.
                select_sql = (
                    f"select t.{id_column} from {table} t"
                    f"\n            where {where_sql}"
                    f"\n            order by {category['order_expr']} asc"
                    "\n            limit ?"
                )
                deleted[name] = 0
                cutoffs[name] = {
                    "retention_days": category["retention_days"],
                    "cutoff_at": category["cutoff"],
                    "cutoff_at_iso": utc_stamp(category["cutoff"]),
                }
                entity_type = category.get("cascade_history_entity_type") or ""
                while budget > 0:
                    limit = min(batch_size, budget)
                    con.execute("begin immediate")
                    try:
                        ids = [row[0] for row in con.execute(select_sql, (*params, limit)).fetchall()]
                        if not ids:
                            con.commit()
                            break
                        placeholders = ", ".join("?" for _ in ids)
                        cascade_removed = 0
                        if entity_type:
                            cascade_removed = int(con.execute(
                                f"delete from history_events where entity_type = ? and entity_id in ({placeholders})",
                                (entity_type, *ids),
                            ).rowcount or 0)
                        removed = int(con.execute(
                            f"delete from {table} where {id_column} in ({placeholders})",
                            ids,
                        ).rowcount or 0)
                        con.commit()
                    except BaseException:
                        con.rollback()
                        raise
                    deleted[name] += removed
                    cascaded += cascade_removed
                    # Cascaded history rows are real write work, so they spend
                    # the same per-run budget the primary rows do.
                    budget -= removed + cascade_removed
                    if len(ids) < limit:
                        break
                remaining[name] = int(con.execute(
                    f"select count(*) from (select 1 from {table} t where {where_sql} limit ?)",
                    (*params, RETENTION_REMAINING_PROBE_CAP),
                ).fetchone()[0] or 0)
            con.execute("begin immediate")
            try:
                update_sync_meta(con, stamp, "event_history_retention")
                con.commit()
            except BaseException:
                con.rollback()
                raise
        total = sum(deleted.values()) + cascaded
        return {
            "ok": True,
            "db_path": str(path),
            "sync_mode": "retention",
            "deleted": deleted,
            "history_events_cascaded": cascaded,
            "deleted_total": total,
            "remaining_eligible": remaining,
            "remaining_probe_capped_at": RETENTION_REMAINING_PROBE_CAP,
            "budget_exhausted": budget <= 0,
            "retention": cutoffs,
            "batch_size": batch_size,
            "max_deletes_per_run": int(max_deletes),
            "elapsed_seconds": round(time.perf_counter() - started, 6),
            "synced_at": stamp,
            "synced_at_iso": utc_stamp(stamp),
        }

    return with_db_lock_retry(
        _prune,
        attempts=max(1, int(lock_attempts or 1)),
        initial_delay=max(0.01, float(lock_initial_delay or 0.01)),
    )


def settle_queue_items_with_optional_folder_imports(con, now):
    rows = con.execute(
        """
        select
            q.id as queue_id,
            q.wanted_id,
            q.series_id,
            q.issue_id,
            q.state,
            q.active,
            q.current_source,
            q.query,
            q.updated_at,
            q.raw_json as queue_raw_json,
            s.title as series,
            i.title as issue_title,
            i.issue_number,
            i.normalized_number,
            ir.id as import_id,
            ir.id as id,
            ir.source_path,
            ir.dest_path,
            ir.status,
            ir.verified,
            ir.created_at,
            ir.raw_json as raw_json
        from import_results ir
        join queue_items q on q.id = ir.queue_id
        left join series s on s.id = q.series_id
        left join issues i on i.id = q.issue_id
        where q.state not in ('verified', 'satisfied', 'superseded_duplicate')
          and coalesce(q.active, 0) = 1
          and coalesce(ir.folder_imported, 0) = 1
          and coalesce(ir.library_visibility_required, 0) = 0
          and coalesce(ir.verified, 0) = 0
          and lower(coalesce(ir.status, '')) in (
              'imported',
              'verification_pending',
              'waiting_for_kavita_scan',
              'imported_not_resolved',
              'kavita_scan_timeout'
          )
          and lower(coalesce(ir.library_visibility_status, '')) in ('pending', 'unknown', 'scan_timeout', 'timeout', '')
        order by coalesce(ir.created_at, 0) desc, ir.id desc
        """
    ).fetchall()
    settled = 0
    seen_queue_ids = set()
    for row in rows:
        queue_id = row["queue_id"]
        if queue_id in seen_queue_ids:
            continue
        seen_queue_ids.add(queue_id)
        if not import_result_strict_completion_valid(
            con,
            row,
            row["series_id"],
            row["issue_id"],
        ):
            continue
        import_record = collection_guard_record_from_import_result(row, row)
        reason = collection_target_single_part_block_reason(row, import_record)
        if reason:
            mark_import_result_single_part_mismatch(con, row, reason, now)
            continue
        ts = max(
            safe_float(row["updated_at"]) or 0,
            safe_float(row["created_at"]) or 0,
            now,
        )
        message = "Folder completion confirmed for imported file; library visibility will follow"
        if mark_queue_verified_for_import(
            con,
            queue_id,
            row["wanted_id"],
            ts,
            message=message,
            current_source=row["current_source"] or "importer",
        ):
            settled += 1
            try:
                import inkdrop_notifications
                db_path_row = con.execute("pragma database_list").fetchone()
                notify_db_path = db_path_row[2] if db_path_row else None
                inkdrop_notifications.notify_wanted_cleared(
                    notify_db_path,
                    series=row["series"],
                    issue_title=row["issue_title"],
                    issue_number=row["issue_number"],
                    dest_path=row["dest_path"],
                    source_path=row["source_path"],
                )
            except Exception:
                pass
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("queue_satisfied_by_folder_import", queue_id, row["import_id"]),
                    "queue_item",
                    queue_id,
                    row["series_id"],
                    row["issue_id"],
                    "queue_satisfied_by_folder_import",
                    "importer",
                    message,
                    ts,
                    json_dumps(
                        {
                            "queue_id": queue_id,
                            "wanted_id": row["wanted_id"],
                            "import_id": row["import_id"],
                            "dest_path": row["dest_path"],
                            "previous_state": row["state"],
                            "previous_active": bool(row["active"]),
                            "completion_truth": "folder",
                            "library_visibility_required": False,
                        }
                    ),
                ),
            )
    return settled

def promote_optional_folder_scan_pending_import_results(con, now, limit=500):
    rows = con.execute(
        """
        select
            ir.id,
            ir.queue_id,
            ir.source_attempt_id,
            ir.series_id,
            ir.issue_id,
            ir.source_path,
            ir.dest_path,
            ir.status,
            ir.imported_count,
            ir.library_visibility_provider,
            ir.created_at,
            ir.raw_json,
            q.wanted_id,
            q.current_source,
            sa.source as source_attempt_source
        from import_results ir
        left join queue_items q on q.id = ir.queue_id
        left join source_attempts sa on sa.id = ir.source_attempt_id
        where coalesce(ir.verified, 0) = 0
          and coalesce(ir.folder_imported, 0) = 1
          and coalesce(ir.library_visibility_required, 0) = 0
          and coalesce(ir.dest_path, '') != ''
          and lower(coalesce(ir.status, '')) in (
              'imported',
              'verification_pending',
              'waiting_for_library_scan',
              'waiting_for_kavita_scan',
              'library_scan_timeout',
              'kavita_scan_timeout',
              'imported_not_resolved'
          )
          and lower(coalesce(ir.library_visibility_status, '')) in ('pending', 'unknown', 'scan_timeout', 'timeout', '')
        order by coalesce(ir.created_at, 0) asc, ir.id asc
        limit ?
        """,
        (max(1, int(limit or 500)),),
    ).fetchall()
    promoted = 0
    for row in rows:
        raw = json_loads(row["raw_json"] or "{}", {}) or {}
        raw = raw if isinstance(raw, dict) else {}
        if not import_result_strict_completion_valid(
            con,
            row,
            row["series_id"],
            row["issue_id"],
        ):
            continue
        result_source = str(
            raw.get("source")
            or row["source_attempt_source"]
            or row["current_source"]
            or "importer"
        ).strip().lower() or "importer"
        visibility_provider = str(
            raw.get("library_visibility_provider") or row["library_visibility_provider"] or "library"
        ).strip().lower() or "library"
        previous_status = str(row["status"] or "").strip().lower()
        if not import_result_managed_dest_path_exists(con, row["dest_path"]):
            raw.update(
                {
                    "status": "missing_file",
                    "verified": False,
                    "outcome": "problem",
                    "display_phase": "retry_later",
                    "completion_truth": "",
                    "folder_imported": False,
                    "library_visibility_required": False,
                    "library_visibility_status": "missing_file",
                    "library_visibility_provider": visibility_provider,
                    "previous_status": previous_status,
                    "managed_dest_missing": True,
                    "managed_dest_missing_path": row["dest_path"],
                    "managed_dest_missing_at": now,
                    "managed_dest_missing_at_iso": utc_stamp(now),
                    "optional_folder_scan_pending_backfill_blocked": True,
                }
            )
            con.execute(
                """
                update import_results
                   set status='missing_file',
                       verified=0,
                       outcome='problem',
                       display_phase='retry_later',
                       completion_truth='',
                       folder_imported=0,
                       library_visibility_required=0,
                       library_visibility_status='missing_file',
                       library_visibility_provider=?,
                       raw_json=?
                 where id=?
                """,
                (visibility_provider, json_dumps(raw), row["id"]),
            )
            promoted += int(con.execute("select changes()").fetchone()[0] or 0)
            continue
        raw.update(
            {
                "status": "folder_verified",
                "verified": True,
                "outcome": "productive",
                "display_phase": "verified",
                "completion_truth": "folder",
                "folder_imported": True,
                "library_visibility_required": False,
                "library_visibility_status": "optional",
                "library_visibility_provider": visibility_provider,
                "previous_status": previous_status,
                "optional_folder_scan_pending_promoted_at": now,
                "optional_folder_scan_pending_promoted_at_iso": utc_stamp(now),
                "verification_source": "optional_folder_scan_pending_backfill",
            }
        )
        con.execute(
            """
            update import_results
            set status='folder_verified',
                verified=1,
                outcome='productive',
                display_phase='verified',
                completion_truth='folder',
                folder_imported=1,
                library_visibility_required=0,
                library_visibility_status='optional',
                library_visibility_provider=?,
                raw_json=?
            where id=?
            """,
            (visibility_provider, json_dumps(raw), row["id"]),
        )
        if row["queue_id"]:
            mark_queue_verified_for_import(
                con,
                row["queue_id"],
                row["wanted_id"],
                now,
                message=f"{source_display_label(result_source)} import verified from managed folder",
                current_source=result_source,
            )
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("optional_folder_scan_pending_import_history", row["id"], row["dest_path"]),
                "import_result",
                row["id"],
                row["series_id"],
                row["issue_id"],
                "optional_folder_scan_pending_promoted",
                result_source,
                f"{source_display_label(result_source)} import verified from managed folder",
                "productive",
                "verified",
                now,
                json_dumps(
                    {
                        "import_id": row["id"],
                        "queue_id": row["queue_id"],
                        "source_path": row["source_path"],
                        "dest_path": row["dest_path"],
                        "previous_status": previous_status,
                        "completion_truth": "folder",
                        "library_visibility_required": False,
                        "library_visibility_status": "optional",
                        "library_visibility_provider": visibility_provider,
                    }
                ),
            ),
        )
        promoted += 1
    return promoted


def settle_verified_import_queue_state(
    db_path,
    attempts=3,
    initial_delay=0.35,
    timeout_seconds=None,
    busy_timeout_ms=None,
    ensure_schema=True,
):
    db_path = Path(db_path)
    if not db_path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(db_path), "settled": 0}

    def _settle():
        now = time.time()
        with connect(
            db_path,
            timeout_seconds=timeout_seconds,
            busy_timeout_ms=busy_timeout_ms,
            configure_wal=timeout_seconds is None and busy_timeout_ms is None,
        ) as con:
            if ensure_schema:
                init_schema(con)
            settled = settle_queue_items_with_verified_imports(con, now)
            if settled:
                update_sync_meta(con, now, "queue_settlement")
            con.commit()
        return {"ok": True, "db_path": str(db_path), "settled": settled, "settled_at": now, "settled_at_iso": utc_stamp(now)}

    return with_db_lock_retry(_settle, attempts=attempts, initial_delay=initial_delay)


def direct_import_row_is_verification_candidate(row):
    if not row:
        return False
    status = str(row["status"] or "").strip().lower()
    if status not in {"verification_pending", "waiting_for_library_scan", "waiting_for_kavita_scan", "library_scan_timeout", "kavita_scan_timeout", "imported_not_resolved"}:
        return False
    raw = json_loads(row["raw_json"] or "{}", {}) or {}
    if not isinstance(raw, dict):
        raw = {}
    raw_source = str(raw.get("source") or "").strip().lower()
    raw_kind = str(raw.get("kind") or "").strip().lower()
    attempt_source = str(row["source_attempt_source"] or "").strip().lower()
    return bool(
        raw_source in {"mangadex", "pack_import"}
        or attempt_source in {"mangadex", "pack_import"}
        or raw_kind in {"direct_import", "pack_import_pending", "pack_import_pending_backfill"}
        or str((raw.get("raw") or {}).get("source") if isinstance(raw.get("raw"), dict) else "").strip().lower() == "mangadex"
    )


def direct_import_verified_sibling(con, row):
    if not row:
        return None
    terms = []
    params = []
    row_id = row["id"]
    series_id = row["series_id"]
    issue_id = row["issue_id"]
    if series_id and issue_id:
        terms.append("series_id = ? and issue_id = ?")
        params.extend([series_id, issue_id])
    if not terms:
        return None
    params.append(row_id)
    rows = con.execute(
        f"""
        select id, queue_id, series_id, issue_id, source_path, dest_path,
               status, outcome, display_phase, completion_truth, folder_imported,
               verified, created_at, raw_json
        from import_results
        where verified = 1
          and ({' or '.join(terms)})
          and id != ?
        order by coalesce(created_at, 0) desc
        limit 25
        """,
        params,
    ).fetchall()
    for sibling in rows:
        if import_result_strict_completion_valid(con, sibling, series_id, issue_id):
            return sibling
    return None


def verify_pending_direct_import_results(con, db_path, now):
    rows = con.execute(
        """
        select
            ir.id,
            ir.queue_id,
            ir.source_attempt_id,
            ir.series_id,
            ir.issue_id,
            ir.source_path,
            ir.dest_path,
            ir.status,
            ir.imported_count,
            ir.folder_imported,
            ir.library_visibility_required,
            ir.library_visibility_provider,
            ir.created_at,
            ir.raw_json,
            q.wanted_id,
            q.state as queue_state,
            q.raw_json as queue_raw_json,
            sa.source as source_attempt_source
        from import_results ir
        left join queue_items q on q.id = ir.queue_id
        left join source_attempts sa on sa.id = ir.source_attempt_id
        where ir.verified = 0
          and ir.dest_path is not null
          and length(trim(ir.dest_path)) > 0
          and lower(coalesce(ir.status, '')) in (
              'verification_pending',
              'waiting_for_library_scan',
              'waiting_for_kavita_scan',
              'library_scan_timeout',
              'kavita_scan_timeout',
              'imported_not_resolved'
          )
        order by coalesce(ir.created_at, 0) asc
        """
    ).fetchall()
    verified = 0
    already_verified = 0
    timed_out = 0
    missing_file = 0
    checked = 0
    for row in rows:
        if not direct_import_row_is_verification_candidate(row):
            continue
        checked += 1
        raw = json_loads(row["raw_json"] or "{}", {}) or {}
        if not isinstance(raw, dict):
            raw = {}
        if import_result_wrong_unit_rejected(row, raw):
            continue
        result_source = str(raw.get("source") or row["source_attempt_source"] or "direct").strip().lower() or "direct"
        result_provider = str(raw.get("provider") or source_display_label(result_source)).strip() or source_display_label(result_source)
        folder_path_ready = import_result_managed_dest_path_exists(con, row["dest_path"])
        folder_imported = bool(row["folder_imported"]) or bool(
            str(row["dest_path"] or "").strip() and int(row["imported_count"] or 0) > 0
        )
        if not folder_path_ready:
            folder_imported = False
        live_sibling_for_missing = direct_import_verified_sibling(con, row) if not folder_path_ready else None
        library_visibility_provider = str(
            raw.get("library_visibility_provider") or row["library_visibility_provider"] or "library"
        ).strip().lower() or "library"
        library_visibility_required = boolish(row["library_visibility_required"], False)
        completion_truth = "folder" if folder_imported else "library"
        if row["dest_path"] and not folder_path_ready:
            raw.update(
                {
                    "status": "missing_file",
                    "verified": False,
                    "outcome": "problem",
                    "display_phase": "retry_later",
                    "completion_truth": "",
                    "folder_imported": False,
                    "library_visibility_required": library_visibility_required,
                    "library_visibility_status": "missing_file",
                    "library_visibility_provider": library_visibility_provider,
                    "managed_dest_missing": True,
                    "managed_dest_missing_path": row["dest_path"],
                    "managed_dest_missing_at": now,
                    "managed_dest_missing_at_iso": utc_stamp(now),
                    "verification_source": "direct_import_managed_dest_missing",
                }
            )
            con.execute(
                """
                update import_results
                set status='missing_file',
                    verified=0,
                    outcome='problem',
                    display_phase='retry_later',
                    completion_truth='',
                    folder_imported=0,
                    library_visibility_required=?,
                    library_visibility_status='missing_file',
                    library_visibility_provider=?,
                    raw_json=?
                where id=?
                """,
                (
                    1 if library_visibility_required else 0,
                    library_visibility_provider,
                    json_dumps(raw),
                    row["id"],
                ),
            )
            if (
                row["queue_id"]
                and not live_sibling_for_missing
                and str(row["queue_state"] or "").strip().lower() not in MISSING_FOLDER_PROOF_NO_REOPEN_QUEUE_STATES
            ):
                queue_raw = json_loads(row["queue_raw_json"] or "{}", {}) or {}
                queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
                queue_raw.update(
                    {
                        "last_import_status": "missing_file",
                        "last_import_source": result_source,
                        "last_import_source_path": row["source_path"],
                        "last_import_dest": row["dest_path"],
                        "last_import_completion_truth": "",
                        "last_import_folder_imported": False,
                        "last_library_visibility_required": library_visibility_required,
                        "last_library_visibility_status": "missing_file",
                        "last_library_visibility_provider": library_visibility_provider,
                        "managed_dest_missing": True,
                        "managed_dest_missing_at": now,
                        "managed_dest_missing_at_iso": utc_stamp(now),
                    }
                )
                message = f"The file {source_display_label(result_source)} imported is not in the library folder any more. Searching again."
                con.execute(
                    """
                    update queue_items
                    set state='queued',
                        current_source=null,
                        last_event=?,
                        active=1,
                        updated_at=?,
                        outcome='retry_later',
                        display_phase='queued',
                        raw_json=?
                    where id=?
                    """,
                    (message, now, json_dumps(queue_raw), row["queue_id"]),
                )
                if row["wanted_id"]:
                    con.execute(
                        "update wanted_items set status=?, updated_at=? where id=?",
                        (wanted_status_for_queue_state("queued"), now, row["wanted_id"]),
                    )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, outcome, display_phase, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("direct_import_managed_dest_missing", row["id"], row["dest_path"]),
                    "import_result",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "direct_import_managed_dest_missing",
                    result_source,
                    f"The file {source_display_label(result_source)} imported is not in the library folder any more. Searching again.",
                    "problem",
                    "retry_later",
                    now,
                    json_dumps({"import_id": row["id"], "queue_id": row["queue_id"], "dest_path": row["dest_path"]}),
                ),
            )
            missing_file += 1
            continue
        if folder_imported and not library_visibility_required:
            raw.update(
                {
                    "status": "folder_verified",
                    "verified": True,
                    "outcome": "productive",
                    "display_phase": "verified",
                    "completion_truth": "folder",
                    "folder_imported": True,
                    "library_visibility_required": False,
                    "library_visibility_status": raw.get("library_visibility_status") or "optional",
                    "library_visibility_provider": library_visibility_provider,
                    "verified_at": now,
                    "verified_at_iso": utc_stamp(now),
                    "verification_source": "folder_completion_optional_visibility",
                }
            )
            con.execute(
                """
                update import_results
                set status='folder_verified',
                    verified=1,
                    outcome='productive',
                    display_phase='verified',
                    completion_truth='folder',
                    folder_imported=1,
                    library_visibility_required=0,
                    library_visibility_status='optional',
                    library_visibility_provider=?,
                    raw_json=?
                where id=?
                """,
                (library_visibility_provider, json_dumps(raw), row["id"]),
            )
            if row["queue_id"]:
                mark_queue_verified_for_import(
                    con,
                    row["queue_id"],
                    row["wanted_id"],
                    now,
                    message=f"{source_display_label(result_source)} import verified from managed folder",
                    current_source=result_source,
                )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("direct_import_folder_verified_history", row["id"], row["dest_path"]),
                    "import_result",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "direct_import_folder_verified",
                    result_source,
                    f"{source_display_label(result_source)} import verified from managed folder",
                    now,
                    json_dumps(
                        {
                            "import_id": row["id"],
                            "queue_id": row["queue_id"],
                            "source_path": row["source_path"],
                            "dest_path": row["dest_path"],
                            "completion_truth": "folder",
                            "library_visibility_required": False,
                        }
                    ),
                ),
            )
            verified += 1
            continue
        sibling = direct_import_verified_sibling(con, row)
        if row["queue_state"] == "verified" or sibling:
            status_value = "library_visible"
            raw.update(
                {
                    "status": status_value,
                    "verified": True,
                    "outcome": "productive",
                    "display_phase": "verified",
                    "completion_truth": completion_truth,
                    "folder_imported": folder_imported,
                    "library_visibility_required": library_visibility_required,
                    "library_visibility_status": "library_visible",
                    "library_visibility_provider": library_visibility_provider,
                    "verified_at": now,
                    "verified_at_iso": utc_stamp(now),
                    "verification_source": "queue_already_verified",
                    "verified_sibling_import_id": sibling["id"] if sibling else None,
                }
            )
            con.execute(
                """
                update import_results
                set status=?,
                    verified=1,
                    outcome='productive',
                    display_phase='verified',
                    completion_truth=?,
                    folder_imported=?,
                    library_visibility_required=?,
                    library_visibility_status='library_visible',
                    library_visibility_provider=?,
                    raw_json=?
                where id=?
                """,
                (
                    status_value,
                    completion_truth,
                    1 if folder_imported else 0,
                    1 if library_visibility_required else 0,
                    library_visibility_provider,
                    json_dumps(raw),
                    row["id"],
                ),
            )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("direct_import_already_verified_history", row["id"], sibling["id"] if sibling else row["queue_id"]),
                    "import_result",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "direct_import_already_verified",
                    result_source,
                    f"{source_display_label(result_source)} import already satisfied by verified queue state",
                    now,
                    json_dumps(
                        {
                            "import_id": row["id"],
                            "queue_id": row["queue_id"],
                            "verified_sibling_import_id": sibling["id"] if sibling else None,
                            "queue_state": row["queue_state"],
                        }
                    ),
                ),
            )
            already_verified += 1
            continue
        visible = kavita_file_visible_for_import_path(row["dest_path"], db_path=db_path)
        if not visible:
            age = now - safe_float(row["created_at"] or 0)
            if age >= DIRECT_IMPORT_VERIFICATION_TIMEOUT_SECONDS:
                timeout_status = "library_scan_timeout"
                raw.update(
                    {
                        "status": timeout_status,
                        "verified": False,
                        "outcome": "problem",
                        "display_phase": "problem",
                        "verification_source": "direct_import_reaper",
                        "verification_age_seconds": age,
                        "verification_timeout_seconds": DIRECT_IMPORT_VERIFICATION_TIMEOUT_SECONDS,
                        "verification_timeout_at": now,
                        "verification_timeout_at_iso": utc_stamp(now),
                        "completion_truth": "folder" if folder_imported else "",
                        "folder_imported": folder_imported,
                        "library_visibility_required": library_visibility_required,
                        "library_visibility_status": "scan_timeout",
                        "library_visibility_provider": library_visibility_provider,
                    }
                )
                con.execute(
                    """
                    update import_results
                    set status=?,
                        verified=0,
                        outcome='problem',
                        display_phase='problem',
                        completion_truth=coalesce(nullif(completion_truth, ''), ?),
                        folder_imported=?,
                        library_visibility_required=?,
                        library_visibility_status='scan_timeout',
                        library_visibility_provider=?,
                        raw_json=?
                    where id=?
                    """,
                    (
                        timeout_status,
                        "folder" if folder_imported else "",
                        1 if folder_imported else 0,
                        1 if library_visibility_required else 0,
                        library_visibility_provider,
                        json_dumps(raw),
                        row["id"],
                    ),
                )
                if row["queue_id"] and row["queue_state"] != "verified":
                    queue_raw = json_loads(row["queue_raw_json"] or "{}", {}) or {}
                    if not isinstance(queue_raw, dict):
                        queue_raw = {}
                    queue_raw.update(
                        {
                            "last_import_status": timeout_status,
                            "last_import_source": result_source,
                            "last_import_source_path": row["source_path"],
                            "last_import_dest": row["dest_path"],
                            "last_import_verification_age_seconds": age,
                            "last_import_verification_timeout_seconds": DIRECT_IMPORT_VERIFICATION_TIMEOUT_SECONDS,
                            "last_import_completion_truth": "folder" if folder_imported else "",
                            "last_import_folder_imported": folder_imported,
                            "last_library_visibility_required": library_visibility_required,
                            "last_library_visibility_status": "scan_timeout",
                            "last_library_visibility_provider": library_visibility_provider,
                        }
                    )
                    provider_label = library_visibility_provider_label(library_visibility_provider)
                    message = f"{source_display_label(result_source)} import copied, but {provider_label} has not reported visibility after {int(age // 60)} min; verification will keep retrying"
                    con.execute(
                        """
                        update queue_items
                        set state='importing',
                            current_source=?,
                            last_event=?,
                            active=1,
                            updated_at=?,
                            raw_json=?
                        where id=?
                        """,
                        (result_source, message, now, json_dumps(queue_raw), row["queue_id"]),
                    )
                    if row["wanted_id"]:
                        con.execute(
                            "update wanted_items set status=?, updated_at=? where id=?",
                            (wanted_status_for_queue_state("importing"), now, row["wanted_id"]),
                        )
                con.execute(
                    """
                    insert or ignore into history_events(
                        id, entity_type, entity_id, series_id, issue_id, event_type,
                        source, message, created_at, raw_json
                    ) values(?,?,?,?,?,?,?,?,?,?)
                    """,
                    (
                        stable_id("direct_import_scan_timeout_history", row["id"], row["dest_path"]),
                        "import_result",
                        row["id"],
                        row["series_id"],
                        row["issue_id"],
                        "direct_import_scan_timeout",
                        result_source,
                        f"{source_display_label(result_source)} import waiting on library scan timeout",
                        now,
                        json_dumps(
                            {
                                "import_id": row["id"],
                                "queue_id": row["queue_id"],
                                "source_path": row["source_path"],
                                "dest_path": row["dest_path"],
                                "age_seconds": age,
                                "timeout_seconds": DIRECT_IMPORT_VERIFICATION_TIMEOUT_SECONDS,
                                "completion_truth": "folder" if folder_imported else "",
                                "folder_imported": folder_imported,
                                "library_visibility_status": "scan_timeout",
                                "library_visibility_required": library_visibility_required,
                                "library_visibility_provider": library_visibility_provider,
                            }
                        ),
                    ),
                )
                timed_out += 1
            continue
        raw.update(
            {
                "status": "library_visible",
                "verified": True,
                "outcome": "productive",
                "display_phase": "verified",
                "completion_truth": completion_truth,
                "folder_imported": folder_imported,
                "library_visibility_required": library_visibility_required,
                "library_visibility_status": "library_visible",
                "library_visibility_provider": library_visibility_provider,
                "verified_at": now,
                "verified_at_iso": utc_stamp(now),
                "library_visible": True,
                "kavita_visible": visible,
            }
        )
        provider_label = library_visibility_provider_label(library_visibility_provider)
        attempt = {
            "source": result_source,
            "provider": result_provider,
            "protocol": raw.get("protocol") or "local",
            "download_client": raw.get("download_client") or result_provider,
            "status": "library_visible",
            "reason": f"{provider_label} reported {source_display_label(result_source)} import visible",
            "title": row["dest_path"],
            "source_path": row["source_path"],
            "dest_path": row["dest_path"],
            "local_path": row["dest_path"],
            "library_file_path": visible.get("file_path"),
            "kavita_file_path": visible.get("file_path"),
            "kind": "direct_import_verification",
            "ts": now,
            "completed_at": now,
        }
        attempt_id = stable_id("direct_import_verified_attempt", row["id"], row["dest_path"])
        source_attempt_id = record_source_attempt(
            con,
            row["queue_id"],
            row["wanted_id"],
            row["series_id"],
            row["issue_id"],
            attempt,
            attempt_id=attempt_id,
            started_at=row["created_at"] or now,
            completed_at=now,
        )
        con.execute(
            """
            update import_results
            set status='library_visible',
                verified=1,
                outcome='productive',
                display_phase='verified',
                completion_truth=?,
                folder_imported=?,
                library_visibility_required=?,
                library_visibility_status='library_visible',
                library_visibility_provider=?,
                source_attempt_id=coalesce(?, source_attempt_id),
                raw_json=?
            where id=?
            """,
            (
                completion_truth,
                1 if folder_imported else 0,
                1 if library_visibility_required else 0,
                library_visibility_provider,
                source_attempt_id,
                json_dumps(raw),
                row["id"],
            ),
        )
        if row["queue_id"]:
            mark_queue_verified_for_import(con, row["queue_id"], row["wanted_id"], now)
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("direct_import_verified_history", row["id"], visible.get("file_path")),
                "import_result",
                row["id"],
                row["series_id"],
                row["issue_id"],
                "direct_import_verified",
                result_source,
                f"{provider_label} reported {source_display_label(result_source)} import visible",
                now,
                json_dumps(
                    {
                        "import_id": row["id"],
                        "queue_id": row["queue_id"],
                        "dest_path": row["dest_path"],
                        "kavita_visible": visible,
                    }
                ),
            ),
        )
        verified += 1
    return {
        "checked": checked,
        "verified": verified,
        "already_verified": already_verified,
        "timed_out": timed_out,
        "missing_file": missing_file,
    }


LEGACY_FOLDER_COMPLETION_STATUSES = {
    "imported",
    "folder_verified",
    "library_visible",
    "verification_pending",
    "waiting_for_library_scan",
    "waiting_for_kavita_scan",
    "imported_not_resolved",
    "library_scan_timeout",
    "kavita_scan_timeout",
    "kavita_verified",
    "verified",
    "queue_verified",
    "resolved",
}


def backfill_legacy_folder_completion_import_results(con, now=None, batch_size=1000, limit=None):
    now = now or time.time()
    batch_size = max(1, min(int(batch_size or 1000), 10000))
    remaining = None if limit is None else max(0, int(limit or 0))
    updated = 0
    status_placeholders = ",".join("?" for _ in LEGACY_FOLDER_COMPLETION_STATUSES)
    status_params = sorted(LEGACY_FOLDER_COMPLETION_STATUSES)
    # Keyset cursor on id ALONE. Required for termination, not for speed -- see
    # the note at the batch fetch below.
    #
    # Deliberately not (created_at, id). created_at has no type affinity here,
    # and sync_import_status binds importer-supplied timestamps into it without
    # validating them, so a single malformed event can store TEXT. SQLite orders
    # storage classes NULL < numeric < TEXT < BLOB, so a TEXT timestamp compares
    # greater than EVERY float -- measured: with the cursor at 1e18 a 'not-a-time'
    # row still satisfies coalesce(created_at,0) > ?. Python's safe_float()
    # collapses that same value to 0.0, so the cursor can never advance past it
    # and the batch re-selects forever: exactly the loop this cursor exists to
    # prevent, reintroduced through the comparison itself.
    # id is the primary key, always present, and totally ordered under one
    # storage class. This backfill has no need for chronological order.
    cursor = None
    while remaining is None or remaining > 0:
        fetch_limit = batch_size if remaining is None else min(batch_size, remaining)
        if cursor is None:
            cursor_clause = ""
            cursor_params = ()
        else:
            cursor_clause = "and id > ?"
            cursor_params = (cursor,)
        rows = con.execute(
            f"""
            select id, status, verified, imported_count, skipped_count, outcome, display_phase,
                   dest_path, completion_truth, folder_imported, library_visibility_required,
                   library_visibility_status, library_visibility_provider, raw_json, created_at
            from import_results
            where dest_path is not null
              and length(trim(dest_path)) > 0
              and lower(coalesce(status, '')) not in ('missing_file', 'stale_folder_proof_retracted')
              and (
                    coalesce(folder_imported, 0) = 0
                 or nullif(trim(coalesce(completion_truth, '')), '') is null
                 or nullif(trim(coalesce(library_visibility_status, '')), '') is null
                 or nullif(trim(coalesce(library_visibility_provider, '')), '') is null
              )
              and (
                    lower(coalesce(status, '')) in ({status_placeholders})
                 or coalesce(imported_count, 0) > 0
                 or coalesce(verified, 0) = 1
              )
            {cursor_clause}
            order by id asc
            limit ?
            """,
            (*status_params, *cursor_params, fetch_limit),
        ).fetchall()
        if not rows:
            break
        # Advance past this batch before doing anything with it. The predicate
        # above only stops matching a row once that row is UPDATED, and rows
        # rejected below are deliberately left untouched -- so without a keyset
        # cursor the next iteration re-selects the identical batch, `rows` is
        # never empty, and with limit=None (the only caller's default) the loop
        # never terminates. Measured on production: all 861 matching rows are
        # wrong-unit rejects, so the loop spun until the sweep's 900s per-file
        # timeout killed the child -- on every single import.
        cursor = str(rows[-1]["id"])
        for row in rows:
            raw = json_loads(row["raw_json"] or "{}", {}) or {}
            if not isinstance(raw, dict):
                raw = {}
            if import_result_wrong_unit_rejected(row, raw):
                continue
            status = str(row["status"] or "").strip().lower()
            imported_count = int(row["imported_count"] or 0)
            skipped_count = int(row["skipped_count"] or 0)
            verified = bool(row["verified"])
            provider = str(
                raw.get("library_visibility_provider") or row["library_visibility_provider"] or "library"
            ).strip().lower() or "library"
            visibility_required = boolish(
                raw.get("library_visibility_required")
                if "library_visibility_required" in raw
                else row["library_visibility_required"],
                False,
            )
            evidence = import_result_completion_evidence(
                status=status,
                verified=verified,
                imported_count=imported_count,
                dest_path=row["dest_path"],
                library_visibility_provider=provider,
                library_visibility_required=visibility_required,
                folder_path_exists=import_result_managed_dest_path_exists(con, row["dest_path"]),
            )
            if not evidence["folder_imported"]:
                if row["dest_path"] and not import_result_managed_dest_path_exists(con, row["dest_path"]):
                    raw.update(
                        {
                            "managed_dest_missing": True,
                            "managed_dest_missing_path": row["dest_path"],
                            "managed_dest_missing_at": now,
                            "managed_dest_missing_at_iso": utc_stamp(now),
                            "legacy_folder_completion_backfill_blocked": True,
                            "previous_status": row["status"],
                        }
                    )
                    con.execute(
                        """
                        update import_results
                           set status='missing_file',
                               verified=0,
                               outcome='problem',
                               display_phase='retry_later',
                               completion_truth='',
                               folder_imported=0,
                               library_visibility_status='missing_file',
                               library_visibility_provider=?,
                               raw_json=?
                         where id=?
                        """,
                        (provider, json_dumps(raw), row["id"]),
                    )
                    updated += int(con.execute("select changes()").fetchone()[0] or 0)
                continue
            outcome = row["outcome"] or import_result_outcome(status, verified, imported_count, skipped_count)
            display_phase = row["display_phase"] or import_result_display_phase(
                status,
                verified,
                imported_count,
                skipped_count,
                outcome,
            )
            raw.update(
                {
                    "completion_truth": evidence["completion_truth"],
                    "folder_imported": evidence["folder_imported"],
                    "library_visibility_required": evidence["library_visibility_required"],
                    "library_visibility_status": evidence["library_visibility_status"],
                    "library_visibility_provider": evidence["library_visibility_provider"],
                    "legacy_folder_completion_backfilled_at": now,
                    "legacy_folder_completion_backfilled_at_iso": utc_stamp(now),
                }
            )
            con.execute(
                """
                update import_results
                set outcome=?,
                    display_phase=?,
                    completion_truth=?,
                    folder_imported=?,
                    library_visibility_required=?,
                    library_visibility_status=?,
                    library_visibility_provider=?,
                    raw_json=?
                where id=?
                """,
                (
                    outcome,
                    display_phase,
                    evidence["completion_truth"],
                    1 if evidence["folder_imported"] else 0,
                    1 if evidence["library_visibility_required"] else 0,
                    evidence["library_visibility_status"],
                    evidence["library_visibility_provider"],
                    json_dumps(raw),
                    row["id"],
                ),
            )
            updated += 1
        con.commit()
        if remaining is not None:
            remaining -= len(rows)
    return updated


def backfill_import_queue_links(con, now):
    rows = con.execute(
        """
        select ir.*,
               s.title as series, s.kapowarr_id, s.metadata_provider, s.metadata_id,
               i.issue_number, i.normalized_number
        from import_results ir
        left join series s on s.id = ir.series_id
        left join issues i on i.id = ir.issue_id
        where ir.queue_id is null
        """
    ).fetchall()
    linked = 0
    for existing in rows:
        payload = json_loads(existing["raw_json"], {}) or {}
        if not isinstance(payload, dict):
            payload = {}
        payload.setdefault("matched_series", existing["series"])
        payload.setdefault("matched_kapowarr_id", existing["kapowarr_id"])
        if existing["metadata_provider"] == "comicvine":
            payload.setdefault("matched_comicvine_id", existing["metadata_id"])
        payload.setdefault("canonical_issue_number", existing["issue_number"] or existing["normalized_number"])
        queue_match = find_queue_for_import(con, payload, existing["series_id"], existing["issue_id"])
        if not queue_match:
            continue
        if (
            str(queue_match["series_id"] or "") != str(existing["series_id"] or "")
            or str(queue_match["issue_id"] or "") != str(existing["issue_id"] or "")
        ):
            continue
        if existing["verified"] and not import_result_strict_completion_valid(
            con,
            existing,
            existing["series_id"],
            existing["issue_id"],
        ):
            continue
        queue_id = queue_match["id"]
        wanted_id = queue_match["wanted_id"]
        con.execute(
            """
            update import_results
            set queue_id=?
            where id=?
            """,
            (queue_id, existing["id"]),
        )
        if existing["verified"]:
            mark_queue_verified_for_import(con, queue_id, wanted_id, existing["created_at"] or now)
        linked += 1
    return linked


def backfill_import_source_attempt_links(con):
    rows = con.execute(
        """
        select id, queue_id, created_at
        from import_results
        where queue_id is not null
          and source_attempt_id is null
        """
    ).fetchall()
    linked = 0
    for row in rows:
        source_attempt_id = latest_source_attempt_id_for_queue(con, row["queue_id"], row["created_at"])
        if not source_attempt_id:
            continue
        con.execute(
            """
            update import_results
            set source_attempt_id=?
            where id=?
            """,
            (source_attempt_id, row["id"]),
        )
        linked += 1
    return linked


BAD_IMPORT_STATUS_TOKENS = (
    "false",
    "wrong",
    "reject",
    "retired",
    "quarantine",
    "retract",
    "collision",
    "mismatch",
)


def import_result_supersede_key(row, managed_roots):
    status = str(row["status"] or "").strip().lower()
    outcome = str(row["outcome"] or "").strip().lower()
    display_phase = str(row["display_phase"] or "").strip().lower()
    dest_path = str(row["dest_path"] or "").strip()
    source_path = str(row["source_path"] or "").strip()
    folder_truth = bool(row["completion_truth"] == "folder" and int(row["folder_imported"] or 0))
    managed_dest = bool(dest_path and path_under_any_root(dest_path, managed_roots))
    library_visible = str(row["library_visibility_status"] or "").strip().lower() == "library_visible"
    return (
        1 if folder_truth and managed_dest else 0,
        1 if folder_truth else 0,
        1 if managed_dest else 0,
        1 if int(row["verified"] or 0) else 0,
        1 if library_visible else 0,
        1 if int(row["imported_count"] or 0) > 0 else 0,
        0 if any(token in " ".join((status, outcome, display_phase)) for token in BAD_IMPORT_STATUS_TOKENS) else 1,
        float(row["created_at"] or 0),
        str(row["id"] or ""),
    )


def import_result_should_supersede(row, survivor, managed_roots):
    if row["id"] == survivor["id"]:
        return False
    raw = json_loads(row["raw_json"] or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    if raw.get("superseded_adapter_import_result"):
        return False
    status_bits = " ".join(
        str(row[key] or "").strip().lower()
        for key in ("status", "outcome", "display_phase")
    )
    if any(token in status_bits for token in BAD_IMPORT_STATUS_TOKENS):
        return False
    if not int(row["verified"] or 0) and int(row["imported_count"] or 0) <= 0:
        return False
    dest_path = str(row["dest_path"] or "").strip()
    source_path = str(row["source_path"] or "").strip()
    survivor_dest = str(survivor["dest_path"] or "").strip()
    if not survivor_dest or not path_under_any_root(survivor_dest, managed_roots):
        return False
    if not dest_path:
        return True
    if source_path and dest_path.replace("\\", "/").rstrip("/") == source_path.replace("\\", "/").rstrip("/"):
        return True
    if not path_under_any_root(dest_path, managed_roots):
        return True
    if str(row["completion_truth"] or "").strip().lower() != "folder":
        return True
    return bool(dest_path == survivor_dest and row["id"] != survivor["id"])


def cleanup_superseded_adapter_import_results(con, now):
    managed_roots = media_management_roots_from_connection(con)
    if not managed_roots:
        return 0
    queue_rows = con.execute(
        """
        select queue_id
        from import_results
        where queue_id is not null
          and length(trim(queue_id)) > 0
        group by queue_id
        having count(*) > 1
           and sum(case when coalesce(folder_imported, 0) = 1 and lower(coalesce(completion_truth, '')) = 'folder' then 1 else 0 end) > 0
        """
    ).fetchall()
    updated = 0
    for queue_row in queue_rows:
        rows = con.execute(
            """
            select id, queue_id, series_id, issue_id, source_path, dest_path, status, outcome, display_phase,
                   completion_truth, folder_imported, library_visibility_status,
                   library_visibility_provider, verified, imported_count, skipped_count,
                   created_at, raw_json
            from import_results
            where queue_id=?
            """,
            (queue_row["queue_id"],),
        ).fetchall()
        strong_rows = [
            row
            for row in rows
            if str(row["completion_truth"] or "").strip().lower() == "folder"
            and int(row["folder_imported"] or 0)
            and str(row["dest_path"] or "").strip()
            and path_under_any_root(row["dest_path"], managed_roots)
            and not any(
                token in " ".join(
                    str(row[key] or "").strip().lower()
                    for key in ("status", "outcome", "display_phase")
                )
                for token in BAD_IMPORT_STATUS_TOKENS
            )
        ]
        if not strong_rows:
            continue
        survivor = sorted(strong_rows, key=lambda item: import_result_supersede_key(item, managed_roots), reverse=True)[0]
        for row in rows:
            if not import_result_should_supersede(row, survivor, managed_roots):
                continue
            raw = json_loads(row["raw_json"] or "{}", {})
            raw = raw if isinstance(raw, dict) else {}
            raw.update(
                {
                    "superseded_adapter_import_result": True,
                    "superseded_reason": "managed_folder_truth_supersedes_adapter_duplicate",
                    "superseded_by_import_result_id": survivor["id"],
                    "superseded_by_dest_path": survivor["dest_path"],
                    "superseded_at": now,
                    "superseded_at_iso": utc_stamp(now),
                    "previous_status": row["status"],
                    "previous_outcome": row["outcome"],
                    "previous_display_phase": row["display_phase"],
                }
            )
            con.execute(
                """
                update import_results
                   set status='superseded_adapter_import',
                       outcome='historical',
                       display_phase='superseded',
                       raw_json=?
                 where id=?
                """,
                (json_dumps(raw), row["id"]),
            )
            con.execute(
                """
                insert or ignore into history_events(
                    id, entity_type, entity_id, series_id, issue_id, event_type,
                    source, message, created_at, raw_json
                ) values(?,?,?,?,?,?,?,?,?,?)
                """,
                (
                    stable_id("import_result_superseded_adapter_duplicate", row["id"], survivor["id"]),
                    "import_result",
                    row["id"],
                    row["series_id"],
                    row["issue_id"],
                    "import_result_superseded_adapter_duplicate",
                    "inkdrop_state",
                    "Adapter-era import evidence superseded by managed-folder truth",
                    now,
                    json_dumps(raw),
                ),
            )
            updated += 1
    return updated


MISSING_FOLDER_PROOF_STATUS = "stale_folder_proof_retracted"
MISSING_FOLDER_PROOF_MESSAGE = "The folder this download landed in is gone. Searching again."
MISSING_FOLDER_PROOF_NO_REOPEN_QUEUE_STATES = {
    "duplicate",
    "ignored",
    "inactive",
    "removed_by_user",
    "retired",
    "stale_source_absent",
    "superseded_duplicate",
    "suppressed_duplicate",
}
WRONG_UNIT_PAGE_PACK_PROOF_STATUS = "wrong_unit_quarantined"
# How long a wrong-unit archive-semantics stamp stays fresh before the row is
# re-evaluated. The stamp marks a completed check of one (path, mtime, size)
# identity; re-checking sooner just re-decompresses unchanged archives.
WRONG_UNIT_SEMANTICS_RECHECK_SECONDS = int(
    os.environ.get("INKDROP_WRONG_UNIT_SEMANTICS_RECHECK_SECONDS", 7 * 24 * 3600)
)
# Wall-clock budget for one cleanup pass. Auditing a row means decompressing
# and PIL-validating every page of its archive over CIFS -- 10-30s for a real
# volume -- so a 100-row pass can outlive the whole import child by itself.
# The child gets killed, the surrounding sync's single transaction rolls back
# every stamp it wrote, and the next child starts the same audit from zero:
# observed live on build 625, 2026-07-29, as children still burning their full
# 900s inside this stage AFTER the stamp skip-filter shipped. A pass that
# stops early commits what it finished; the ordering prefers unstamped rows,
# so progress is monotonic across children instead of all-or-nothing.
WRONG_UNIT_CLEANUP_PASS_BUDGET_SECONDS = float(
    os.environ.get("INKDROP_WRONG_UNIT_CLEANUP_PASS_BUDGET_SECONDS", 45)
)

# Same rollback trap, different stage: the folder-presence backfills verify
# on-disk archives (decompress + PIL over CIFS) for every active queue/wanted
# row, up to 2,500 rows a pass, inside the same single sync transaction. With
# the wrong-unit retraction scope fixed (2026-07-29) roughly 290 wanted rows
# with files already on disk became eligible at once -- genuinely productive
# work, but a pass that outlives the import child loses ALL of it to the
# rollback. Bound the pass; verified rows leave the active set when the sync
# commits, so progress is monotonic across children.
FOLDER_PRESENCE_BACKFILL_PASS_BUDGET_SECONDS = float(
    os.environ.get("INKDROP_FOLDER_PRESENCE_BACKFILL_PASS_BUDGET_SECONDS", 120)
)
WRONG_UNIT_PAGE_PACK_PROOF_MESSAGE = "That download was chapters, not the volume this series collects. Searching again."
WRONG_UNIT_PAGE_PACK_PROOF_REASON = "A chapter archive cannot complete a series that is set to collect volumes"
WRONG_UNIT_PAGE_PACK_PROOF_EVENT = "wrong_unit_page_pack_proof_retracted"
PROVENANCE_IDENTITY_RETRACTION_EVENT = "completion_provenance_identity_retracted"
PROVENANCE_IDENTITY_RETRACTION_MESSAGE = "The download that claimed to finish this does not match what InkDrop asked for. Searching again."
WRONG_UNIT_PAGE_PACK_CHAPTER_NATIVE_PROVIDERS = {"mangadex", "suwayomi", "tachiyomi"}
WRONG_UNIT_PAGE_PACK_VOLUME_MANAGED_PROVIDERS = {
    "comicvine",
    "kapowarr",
    "watch",
    "inkdrop",
    "inkdrop_series",
}
WRONG_UNIT_PAGE_PACK_SOURCE_TOKENS = {
    "mangadex",
    "suwayomi",
    "inkdrop_page_pack",
    "local_page_pack",
    "manual_page_pack",
    "page_pack",
}


def import_result_positive_status_bits(row):
    return " ".join(
        str(row[key] or "").strip().lower()
        for key in ("status", "outcome", "display_phase", "completion_truth")
        if key in row.keys()
    )


UNSAFE_COMPLETION_EVIDENCE_PATTERN = re.compile(
    r"(?:wrong[_ -]?unit|unit[_ -]?mismatch|known[_ -]?bad|malicious|"
    r"invalid[_ -]?archive|bad[_ -]?archive|corrupt[_ -]?archive|"
    r"\bpreview\b|sample|unsafe[_ -]?locator|quarantin|retract|"
    r"rejected|duplicate)",
    re.I,
)


def import_result_has_unsafe_completion_evidence(row, raw=None):
    """Reject current contradictory safety evidence even on a verified ledger row."""
    values = [
        row_value(row, "status"),
        row_value(row, "outcome"),
        row_value(row, "display_phase"),
        row_value(row, "completion_truth"),
    ]
    raw = raw if isinstance(raw, dict) else json_loads(row_value(row, "raw_json") or "{}", {})
    raw = raw if isinstance(raw, dict) else {}
    safety_keys = {
        "status",
        "state",
        "outcome",
        "decision",
        "verdict",
        "reason",
        "failure_reason",
        "repair_reason",
        "completion_truth",
        "artifact_status",
        "artifact_type",
        "archive_status",
        "block_reason",
        "block_reasons",
    }
    unsafe_boolean_keys = {
        "known_bad",
        "malicious",
        "invalid_archive",
        "bad_archive",
        "corrupt_archive",
        "preview",
        "sample",
        "duplicate",
        "wrong_unit",
        "unit_mismatch",
        "unsafe_locator",
        "quarantined",
        "retracted",
    }
    stack = [raw]
    seen = set()
    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            marker = id(current)
            if marker in seen:
                continue
            seen.add(marker)
            for key, value in current.items():
                key_text = str(key or "").strip().lower()
                if key_text.startswith(("previous_", "prior_", "history_")):
                    continue
                if key_text in unsafe_boolean_keys and boolish(value, False):
                    return True
                if key_text in safety_keys:
                    if isinstance(value, list):
                        values.extend(str(entry) for entry in value if not isinstance(entry, (dict, list)))
                    elif not isinstance(value, (dict, list)):
                        values.append(str(value))
                if isinstance(value, (dict, list)):
                    stack.append(value)
        elif isinstance(current, list):
            stack.extend(value for value in current if isinstance(value, (dict, list)))
    return bool(UNSAFE_COMPLETION_EVIDENCE_PATTERN.search(" ".join(str(value or "") for value in values)))


def import_result_is_bad_or_retracted(row):
    bits = import_result_positive_status_bits(row)
    return bool(
        any(token in bits for token in BAD_IMPORT_STATUS_TOKENS)
        or MISSING_FOLDER_PROOF_STATUS in bits
        or import_result_has_unsafe_completion_evidence(row)
    )


def import_result_folder_truth(row):
    if not row:
        return False
    return bool(
        str(row["completion_truth"] or "").strip().lower() == "folder"
        or int(row["folder_imported"] or 0)
    )


def import_result_dest_exists(row, managed_roots):
    dest_path = str(row["dest_path"] or "").strip()
    if not dest_path or not path_under_any_root(dest_path, managed_roots):
        return False
    try:
        return Path(dest_path).exists()
    except OSError:
        return False


def live_folder_import_proof_exists(con, queue_id, stale_import_id, managed_roots):
    if not queue_id:
        return False
    rows = con.execute(
        """
        select id, status, outcome, display_phase, completion_truth, folder_imported,
               verified, dest_path
        from import_results
        where queue_id=?
          and id<>?
          and coalesce(verified, 0)=1
          and coalesce(dest_path, '') <> ''
        """,
        (queue_id, stale_import_id),
    ).fetchall()
    for row in rows:
        if import_result_is_bad_or_retracted(row):
            continue
        if not import_result_folder_truth(row):
            continue
        if import_result_dest_exists(row, managed_roots):
            return True
    return False


def wrong_unit_page_pack_raw_dicts(row):
    values = (
        row_value(row, "import_raw_json"),
        row_value(row, "issue_raw_json"),
        row_value(row, "queue_raw_json"),
        row_value(row, "attempt_raw_json"),
    )
    raw_dicts = list(manga_import_raw_dicts(*values))
    seen = {id(item) for item in raw_dicts}
    for value in values:
        raw = json_loads(value or "{}", {}) if isinstance(value, str) else value
        if not isinstance(raw, dict):
            continue
        for key in ("record", "resolved_row", "queue_item", "source_candidate", "candidate"):
            nested = raw.get(key)
            if not isinstance(nested, dict):
                continue
            for item in iter_import_result_raw_sources(nested):
                marker = id(item)
                if marker in seen:
                    continue
                seen.add(marker)
                raw_dicts.append(item)
    return raw_dicts


def wrong_unit_page_pack_raw_declares_volume_source(raw_dicts):
    for raw in raw_dicts or []:
        if not isinstance(raw, dict):
            continue
        for key in ("source_unit", "unit_type", "unitType", "manga_unit_model", "series_unit_model", "unit_model"):
            if manga_import_normalized_unit(raw.get(key)) == "volume":
                return True
        if boolish(raw.get("volume_page_pack"), False) or boolish(raw.get("mangadex_volume_page_pack"), False):
            return True
        for key in ("candidate_type", "page_pack_unit", "pack_unit"):
            if manga_import_normalized_unit(raw.get(key)) == "volume":
                return True
    return False


def wrong_unit_page_pack_volume_managed_manga_target(row):
    media_decision = native_series_media_decision(
        {
            "title": row_value(row, "series_title"),
            "media_type": row_value(row, "series_media_type"),
            "publisher": row_value(row, "publisher"),
        },
        provider=row_value(row, "series_metadata_provider"),
    )
    if media_decision.get("media_type") not in MANGA_MEDIA_TYPES:
        return False
    series_provider = metadata_provider_key(row_value(row, "series_metadata_provider"))
    issue_provider = metadata_provider_key(row_value(row, "issue_metadata_provider"))
    if series_provider in WRONG_UNIT_PAGE_PACK_CHAPTER_NATIVE_PROVIDERS:
        return False
    if issue_provider in WRONG_UNIT_PAGE_PACK_CHAPTER_NATIVE_PROVIDERS:
        return False
    if series_provider in WRONG_UNIT_PAGE_PACK_VOLUME_MANAGED_PROVIDERS:
        return True
    if issue_provider in WRONG_UNIT_PAGE_PACK_VOLUME_MANAGED_PROVIDERS:
        return True
    series_id = str(row_value(row, "series_id") or "").strip().lower()
    return series_id.startswith(("comicvine:", "kapowarr:"))


def wrong_unit_page_pack_source_evidence(row, raw_dicts=None):
    raw_dicts = raw_dicts if raw_dicts is not None else wrong_unit_page_pack_raw_dicts(row)
    source_hint = manga_import_source_unit_hint(row)
    if source_hint.get("source_unit") != "chapter":
        return {}
    source_values = [
        row_value(row, "source_path"),
        row_value(row, "dest_path"),
        row_value(row, "attempt_title"),
        row_value(row, "attempt_source"),
        row_value(row, "attempt_provider_id"),
        row_value(row, "attempt_provider"),
        row_value(row, "attempt_protocol"),
        row_value(row, "attempt_download_client"),
    ]
    # Page-pack provenance must be declared, not inferred from substrings.
    # This used to also scan source_path/dest_path/title and the serialized
    # raw JSON for tokens like 'mangadex' -- which appears by design in every
    # comicvine series that has a MangaDex companion link, so verified volume
    # proofs qualified as "page packs" purely for mentioning their own
    # companion. Structured attempt fields and the explicit boolean flags
    # below are how a real page-pack import actually records itself.
    structured_values = {
        str(row_value(row, key) or "").strip().lower()
        for key in (
            "attempt_source",
            "attempt_provider",
            "attempt_provider_id",
            "attempt_protocol",
            "attempt_download_client",
        )
    }
    page_pack_hit = any(value in WRONG_UNIT_PAGE_PACK_SOURCE_TOKENS for value in structured_values)
    page_pack_hit = page_pack_hit or any(
        isinstance(raw, dict)
        and any(
            boolish(raw.get(key), False)
            for key in (
                "mangadex_page_pack",
                "suwayomi_page_pack",
                "page_pack",
                "pagePack",
                "local_page_pack",
                "inkdrop_page_pack",
            )
        )
        for raw in raw_dicts or []
    )
    if not page_pack_hit:
        return {}
    chapter_text = " ".join(str(value or "") for value in source_values[:3])
    chapter_number = manga_import_number_from_text(chapter_text, "chapter")
    if not chapter_number:
        chapter_number = str(manga_import_first_raw_value(raw_dicts, "chapter", "chapter_number", "chapterNumber") or "").strip()
    return {
        "source_unit": "chapter",
        "source_unit_confidence": source_hint.get("confidence"),
        "source_unit_evidence": source_hint.get("evidence") or [],
        "page_pack_evidence": True,
        "chapter_number": chapter_number,
    }


def wrong_unit_page_pack_import_row(row, *, fresh_archive_semantics=False, con=None):
    if not row:
        return {}
    if import_result_is_bad_or_retracted(row):
        status_bits = import_result_positive_status_bits(row)
        half_retracted_verified = bool(int(row_value(row, "verified") or 0)) and "wrong_unit" in status_bits
        if not half_retracted_verified:
            return {}
    if not wrong_unit_page_pack_volume_managed_manga_target(row):
        return {}
    seen_candidate_paths = set()
    archive_says_volume = False
    for candidate_path in (row_value(row, "dest_path"), row_value(row, "source_path")):
        candidate_path = str(candidate_path or "").strip()
        candidate_key = os.path.normcase(os.path.abspath(candidate_path)) if candidate_path else ""
        if not candidate_key or candidate_key in seen_candidate_paths:
            continue
        seen_candidate_paths.add(candidate_key)
        semantics = (
            cached_archive_member_semantics(con, candidate_path, fresh=fresh_archive_semantics)
            if con is not None
            else inkdrop_artifact_acceptance.archive_member_semantics(
                candidate_path,
                fresh=fresh_archive_semantics,
            )
        )
        if semantics.get("semantic_unit") == "chapter":
            return {
                "source_unit": "chapter",
                "source_unit_confidence": "high",
                "source_unit_evidence": semantics.get("evidence") or [],
                "archive_member_evidence": semantics,
                "archive_path": candidate_path,
                "generalized_archive_semantic_guard": True,
            }
        if semantics.get("checked") and semantics.get("semantic_unit") == "volume":
            archive_says_volume = True
    if archive_says_volume:
        # The archive itself was read and its members identify a volume. That
        # outranks every text-derived hint below: retracting on raw-JSON
        # chapter fields here is how 891 verified volume proofs (Bleach v14,
        # Hunter x Hunter v04/v29, ...) were quarantined while their perfectly
        # good volume files sat on disk -- measured live 2026-07-29.
        return {}
    raw_dicts = wrong_unit_page_pack_raw_dicts(row)
    if wrong_unit_page_pack_raw_declares_volume_source(raw_dicts):
        return {}
    return wrong_unit_page_pack_source_evidence(row, raw_dicts)


def wrong_unit_page_pack_task_or_attempt_matches(record, import_row, *, con=None):
    if not record:
        return False
    import_attempt_id = str(row_value(import_row, "source_attempt_id") or "").strip()
    record_attempt_id = str(row_value(record, "source_attempt_id") or row_value(record, "id") or "").strip()
    if import_attempt_id and record_attempt_id == import_attempt_id:
        return True
    semantic_path = str(row_value(import_row, "dest_path") or row_value(import_row, "source_path") or "").strip()
    semantic_evidence = (
        cached_archive_member_semantics(con, semantic_path)
        if con is not None
        else inkdrop_artifact_acceptance.archive_member_semantics(semantic_path)
    )
    source_values = [
        row_value(record, "source"),
        row_value(record, "provider_id"),
        row_value(record, "provider"),
        row_value(record, "protocol"),
        row_value(record, "download_client"),
        row_value(record, "title"),
        row_value(record, "local_path"),
        row_value(record, "save_path"),
        row_value(record, "raw_json"),
    ]
    source_text = " ".join(str(value or "") for value in source_values).lower()
    if semantic_evidence.get("semantic_unit") == "chapter" and any(
        token in source_text for token in ("local_pack", "pack_import", "folder_presence", "kavita")
    ):
        return True
    if not any(token in source_text for token in WRONG_UNIT_PAGE_PACK_SOURCE_TOKENS):
        return False
    chapter_text = " ".join(str(value or "") for value in source_values[5:8])
    if manga_import_number_from_text(chapter_text, "chapter"):
        return True
    raw = json_loads(row_value(record, "raw_json") or "{}", {})
    return bool(isinstance(raw, dict) and (raw.get("chapter") or raw.get("chapter_id") or raw.get("mangadex_chapter_id")))


def live_positive_import_proof_exists(con, queue_id, stale_import_id, target_row=None):
    if not queue_id:
        return False
    rows = con.execute(
        """
        select id, status, outcome, display_phase, completion_truth, folder_imported,
               verified, imported_count, source_path, dest_path, raw_json
        from import_results
        where queue_id=?
          and id<>?
          and (
            coalesce(verified, 0)=1
            or coalesce(imported_count, 0)>0
            or coalesce(folder_imported, 0)=1
          )
        """,
        (queue_id, stale_import_id),
    ).fetchall()
    for row in rows:
        if import_result_is_bad_or_retracted(row):
            continue
        dest_path = str(row_value(row, "dest_path") or "").strip()
        if not dest_path:
            continue
        try:
            if not Path(dest_path).is_file():
                continue
        except OSError:
            continue
        if target_row and wrong_unit_page_pack_volume_managed_manga_target(target_row):
            semantics = inkdrop_artifact_acceptance.archive_member_semantics(dest_path, fresh=True)
            if semantics.get("semantic_unit") == "chapter":
                continue
        return True
    return False


def cleanup_wrong_unit_page_pack_import_proofs(con, now, limit=5000, *, cursor=None):
    """Retract chapter page-pack proofs that satisfied volume-managed manga rows."""
    try:
        limit = max(1, min(int(limit or 5000), 5000))
    except Exception:
        limit = 5000
    semantic_scan_limit = max(1, min(limit, 100))
    cursor = cursor if isinstance(cursor, dict) else None
    cursor_created = safe_float((cursor or {}).get("created_at")) if cursor else None
    cursor_id = str((cursor or {}).get("id") or "")
    cursor_clause = ""
    cursor_params = []
    if cursor is not None and (cursor_created is not None or cursor_id):
        cursor_created = cursor_created or 0
        cursor_clause = "and (coalesce(ir.created_at,0)>? or (coalesce(ir.created_at,0)=? and ir.id>?))"
        cursor_params = [cursor_created, cursor_created, cursor_id]
    # json_extract raises sqlite3.OperationalError on malformed JSON text
    # rather than returning NULL, and this ordering has no per-row recovery.
    # coalesce(ir.raw_json, '{}') only covers NULL; guard with json_valid too
    # so a corrupt raw_json string degrades this row's sort key instead of
    # aborting the whole pass -- this cleanup can run under
    # inkdrop_state_maintenance.py, which has no catch-all around it.
    ir_raw_or_empty = "case when json_valid(ir.raw_json) then ir.raw_json else '{}' end"
    order_sql = (
        "coalesce(ir.created_at,0) asc, ir.id asc"
        if cursor is not None
        else f"""case when json_extract({ir_raw_or_empty}, '$.wrong_unit_archive_semantics_checked_at') is null then 0 else 1 end,
          coalesce(json_extract({ir_raw_or_empty}, '$.wrong_unit_archive_semantics_checked_at'), 0) asc,
          coalesce(ir.created_at, 0) asc, ir.id asc"""
    )
    rows = con.execute(
        f"""
        select ir.id, ir.queue_id, q.wanted_id, ir.source_attempt_id,
               ir.series_id, ir.issue_id, ir.source_path, ir.dest_path,
               ir.status, ir.outcome, ir.display_phase, ir.completion_truth,
               ir.folder_imported, ir.verified, ir.imported_count, ir.raw_json as import_raw_json,
               s.title as series_title, s.media_type as series_media_type,
               s.publisher, s.metadata_provider as series_metadata_provider,
               s.metadata_id as series_metadata_id, s.raw_json as series_raw_json,
               i.issue_number, i.normalized_number, i.title as issue_title,
               i.metadata_provider as issue_metadata_provider, i.metadata_id as issue_metadata_id,
               i.raw_json as issue_raw_json,
               q.state as queue_state, q.active as queue_active, q.current_source,
               q.last_event as queue_last_event, q.raw_json as queue_raw_json,
               w.status as wanted_status,
               sa.source as attempt_source, sa.provider_id as attempt_provider_id,
               sa.provider as attempt_provider, sa.protocol as attempt_protocol,
               sa.download_client as attempt_download_client, sa.title as attempt_title,
               sa.status as attempt_status, sa.outcome as attempt_outcome,
               sa.lifecycle_phase as attempt_lifecycle_phase, sa.raw_json as attempt_raw_json,
               coalesce(ir.created_at,0) as integrity_created_at
        from import_results ir
        join series s on s.id = ir.series_id
        left join issues i on i.id = ir.issue_id
        left join queue_items q on q.id = ir.queue_id
        left join wanted_items w on w.id = q.wanted_id
        left join source_attempts sa on sa.id = ir.source_attempt_id
        where (
            coalesce(ir.verified, 0)=1
            or coalesce(ir.imported_count, 0)>0
            or coalesce(ir.folder_imported, 0)=1
          )
          and (
            -- Structured provenance only. The four raw_json LIKE clauses that
            -- used to sit here ('%mangadex%' and friends) selected proofs by
            -- substring over the whole blob: measured live 2026-07-29, 891 of
            -- 1,049 quarantined rows were source-evidence retractions and the
            -- worst-hit series were comicvine volumes whose raw JSON mentions
            -- mangadex BY DESIGN via the companion-series bridge (One Piece:
            -- 316 retracted, 1 genuinely page-pack). The structured fields
            -- below caught that 1 -- they are the precise signal.
            lower(coalesce(sa.source, '')) in ('mangadex','suwayomi','pack_import','local_pack','folder_presence')
            or lower(coalesce(sa.provider_id, '')) in ('mangadex','suwayomi','local_pack','page_pack')
            or lower(coalesce(sa.download_client, '')) in ('inkdrop_page_pack','inkdrop_local_pack')
            or exists (
                select 1 from import_results neg
                where neg.id <> ir.id
                  and (neg.queue_id = ir.queue_id or neg.issue_id = ir.issue_id)
                  and lower(coalesce(neg.dest_path, '')) = lower(coalesce(ir.dest_path, ''))
                  and coalesce(neg.verified, 0)=0
                  -- A row this cleanup itself quarantined must not come back
                  -- as the wrong-unit neighbour that justifies retracting its
                  -- verified sibling at the same path -- that loop manufactured
                  -- its own evidence, one retraction per pass.
                  and lower(coalesce(neg.status, '')) <> '{WRONG_UNIT_PAGE_PACK_PROOF_STATUS}'
                  -- And the neighbour must share provenance with this row (same
                  -- source attempt), not merely a dest_path: unrelated attempts
                  -- landing on the same file say nothing about THIS proof.
                  and coalesce(neg.source_attempt_id, '') <> ''
                  and neg.source_attempt_id = ir.source_attempt_id
                  and (
                    lower(coalesce(neg.status, '')) like '%wrong_unit%'
                    or lower(coalesce(neg.status, '')) like '%single_part_file%'
                    or lower(coalesce(neg.raw_json, '')) like '%rejected_wrong_unit%'
                  )
            )
          )
          {cursor_clause}
        order by {order_sql}
        limit ?
        """,
        (*cursor_params, semantic_scan_limit),
    ).fetchall()
    counts = {
        "import_results": 0,
        "queue_items": 0,
        "download_tasks": 0,
        "source_attempts": 0,
        "archive_semantics_audited": 0,
    }
    reopened_queues = set()
    pass_started = time.time()
    for row in rows:
        if time.time() - pass_started > WRONG_UNIT_CLEANUP_PASS_BUDGET_SECONDS:
            # Stop, don't starve: rows finished this pass keep their stamps
            # when the surrounding sync commits, and the unstamped-first
            # ordering resumes exactly here next pass. Without this bound a
            # heavy batch outlived the import child, the kill rolled back the
            # whole transaction, and no audit ever persisted.
            counts["pass_budget_exhausted"] = 1
            break
        # A row audited recently is verified against its PERSISTED archive
        # identity with a central-directory read (milliseconds) instead of the
        # full decompress-and-PIL pass (10-30s over CIFS). A signature match
        # means the archive is byte-for-byte the members we already judged --
        # skip. A mismatch means the file changed underneath the stamp,
        # including the in-place swap that preserves size and mtime, so the
        # row falls through to the full evidence path. Rows this cleanup
        # already quarantined carry no positive proof to protect and are
        # skipped on the stamp alone.
        row_raw = json_loads(row["import_raw_json"] or "{}", {})
        row_raw = row_raw if isinstance(row_raw, dict) else {}
        stamp_fresh = (
            safe_float(row_raw.get("wrong_unit_archive_semantics_checked_at"), 0)
            > now - WRONG_UNIT_SEMANTICS_RECHECK_SECONDS
        )
        signature_mismatch = False
        if stamp_fresh:
            if str(row["status"] or "").strip().lower() == WRONG_UNIT_PAGE_PACK_PROOF_STATUS:
                counts["stamp_skipped"] = counts.get("stamp_skipped", 0) + 1
                continue
            stored_identity = row_raw.get("wrong_unit_archive_semantics_identity")
            stored_signature = (
                str(stored_identity.get("central_directory_signature") or "")
                if isinstance(stored_identity, dict)
                else ""
            )
            if stored_signature:
                current_signature = inkdrop_artifact_acceptance.archive_central_directory_light_signature(
                    str(stored_identity.get("path") or row["dest_path"] or row["source_path"] or "")
                )
                if current_signature == stored_signature:
                    counts["stamp_skipped"] = counts.get("stamp_skipped", 0) + 1
                    continue
                signature_mismatch = True
        # fresh only when the signature said the file changed underneath a
        # fresh stamp: a same-stat in-place swap keeps the (path, mtime_ns,
        # size) cache key, so only a forced re-read can see the new members.
        # Everywhere else the cache key is sufficient and fresh=True would
        # just re-decompress unchanged archives.
        evidence = wrong_unit_page_pack_import_row(row, fresh_archive_semantics=signature_mismatch, con=con)
        if not evidence:
            raw = json_loads(row["import_raw_json"] or "{}", {})
            raw = raw if isinstance(raw, dict) else {}
            audit_path = str(row["dest_path"] or row["source_path"] or "").strip()
            audit_semantics = inkdrop_artifact_acceptance.archive_member_semantics(
                audit_path, fresh=signature_mismatch
            )
            raw.update(
                {
                    "wrong_unit_archive_semantics_checked_v2": True,
                    "wrong_unit_archive_semantics_checked_at": now,
                    "wrong_unit_archive_semantics_checked_at_iso": utc_stamp(now),
                    "wrong_unit_archive_semantics_identity": {
                        "path": audit_path,
                        "central_directory_signature": audit_semantics.get("central_directory_signature"),
                        "image_count": audit_semantics.get("image_count"),
                        "semantic_unit": audit_semantics.get("semantic_unit"),
                    },
                }
            )
            con.execute("update import_results set raw_json=? where id=?", (json_dumps(raw), row["id"]))
            counts["archive_semantics_audited"] += int(con.execute("select changes()").fetchone()[0] or 0)
            continue
        raw = json_loads(row["import_raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        raw.update(
            {
                "wrong_unit_page_pack_proof_retracted": True,
                "wrong_unit_page_pack_reason": WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                "wrong_unit_page_pack_evidence": evidence,
                "wrong_unit_page_pack_retracted_at": now,
                "wrong_unit_page_pack_retracted_at_iso": utc_stamp(now),
                # Also a completed semantics check: without this stamp the
                # retracted row re-qualifies next pass just to be re-read once
                # more before the audit branch finally stamps it.
                "wrong_unit_archive_semantics_checked_at": now,
                "wrong_unit_archive_semantics_checked_at_iso": utc_stamp(now),
                "previous_status": row["status"],
                "previous_verified": row["verified"],
                "previous_outcome": row["outcome"],
                "previous_display_phase": row["display_phase"],
                "previous_completion_truth": row["completion_truth"],
                "repair_status": WRONG_UNIT_PAGE_PACK_PROOF_STATUS,
            }
        )
        con.execute(
            """
            update import_results
               set status=?,
                   verified=0,
                   outcome='failed',
                   display_phase='retry_later',
                   completion_truth='wrong_unit',
                   folder_imported=0,
                   library_visibility_status='not_applicable',
                   raw_json=?
             where id=?
            """,
            (WRONG_UNIT_PAGE_PACK_PROOF_STATUS, json_dumps(raw), row["id"]),
        )
        counts["import_results"] += int(con.execute("select changes()").fetchone()[0] or 0)
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id(WRONG_UNIT_PAGE_PACK_PROOF_EVENT, "import_result", row["id"]),
                "import_result",
                row["id"],
                row["series_id"],
                row["issue_id"],
                WRONG_UNIT_PAGE_PACK_PROOF_EVENT,
                "inkdrop_state",
                WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                "problem",
                "retry_later",
                now,
                json_dumps(raw),
            ),
        )
        task_rows = con.execute(
            """
            select id, source_attempt_id, source, provider_id, provider, protocol,
                   download_client, title, local_path, save_path, status, state,
                   outcome, display_phase, lifecycle_phase, failure_reason,
                   retry_eligible, raw_json
            from download_tasks
            where queue_id=?
            """,
            (row["queue_id"],),
        ).fetchall() if row["queue_id"] else []
        for task in task_rows:
            if not wrong_unit_page_pack_task_or_attempt_matches(task, row, con=con):
                continue
            task_raw = json_loads(task["raw_json"] or "{}", {})
            task_raw = task_raw if isinstance(task_raw, dict) else {}
            task_raw.update(
                {
                    "wrong_unit_page_pack_proof_retracted": True,
                    "wrong_unit_page_pack_import_result_id": row["id"],
                    "wrong_unit_page_pack_reason": WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                    "wrong_unit_page_pack_retracted_at": now,
                    "wrong_unit_page_pack_retracted_at_iso": utc_stamp(now),
                    "previous_status": task["status"],
                    "previous_state": task["state"],
                }
            )
            con.execute(
                """
                update download_tasks
                   set status=?,
                       state='failed',
                       outcome='problem',
                       display_phase='retry_later',
                       lifecycle_phase='failed_candidate',
                       failure_reason=?,
                       retry_eligible=1,
                       updated_at=?,
                       completed_at=coalesce(completed_at, ?),
                       raw_json=?
                 where id=?
                """,
                (
                    WRONG_UNIT_PAGE_PACK_PROOF_STATUS,
                    WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                    now,
                    now,
                    json_dumps(task_raw),
                    task["id"],
                ),
            )
            counts["download_tasks"] += int(con.execute("select changes()").fetchone()[0] or 0)
        attempt_rows = con.execute(
            """
            select id, source, provider_id, provider, protocol, download_client,
                   title, status, outcome, display_phase, lifecycle_phase,
                   failure_reason, retry_eligible, raw_json
            from source_attempts
            where queue_id=?
            """,
            (row["queue_id"],),
        ).fetchall() if row["queue_id"] else []
        for attempt in attempt_rows:
            if not wrong_unit_page_pack_task_or_attempt_matches(attempt, row, con=con):
                continue
            attempt_raw = json_loads(attempt["raw_json"] or "{}", {})
            attempt_raw = attempt_raw if isinstance(attempt_raw, dict) else {}
            attempt_raw.update(
                {
                    "wrong_unit_page_pack_proof_retracted": True,
                    "wrong_unit_page_pack_import_result_id": row["id"],
                    "wrong_unit_page_pack_reason": WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                    "wrong_unit_page_pack_retracted_at": now,
                    "wrong_unit_page_pack_retracted_at_iso": utc_stamp(now),
                    "previous_status": attempt["status"],
                    "previous_outcome": attempt["outcome"],
                    "previous_lifecycle_phase": attempt["lifecycle_phase"],
                }
            )
            con.execute(
                """
                update source_attempts
                   set status=?,
                       outcome='problem',
                       display_phase='retry_later',
                       lifecycle_phase='failed_candidate',
                       failure_reason=?,
                       retry_eligible=1,
                       completed_at=coalesce(completed_at, ?),
                       raw_json=?
                 where id=?
                """,
                (
                    WRONG_UNIT_PAGE_PACK_PROOF_STATUS,
                    WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                    now,
                    json_dumps(attempt_raw),
                    attempt["id"],
                ),
            )
            counts["source_attempts"] += int(con.execute("select changes()").fetchone()[0] or 0)
        queue_id = row["queue_id"]
        if (
            not queue_id
            or queue_id in reopened_queues
            or live_positive_import_proof_exists(con, queue_id, row["id"], row)
            or str(row["queue_state"] or "").strip().lower() in MISSING_FOLDER_PROOF_NO_REOPEN_QUEUE_STATES
        ):
            continue
        queue_raw = json_loads(row["queue_raw_json"] or "{}", {})
        queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
        queue_raw.update(
            {
                "previous_state": row["queue_state"],
                "previous_active": row["queue_active"],
                "previous_last_event": row["queue_last_event"],
                "wrong_unit_page_pack_proof_retracted": True,
                "wrong_unit_page_pack_import_result_id": row["id"],
                "wrong_unit_page_pack_reason": WRONG_UNIT_PAGE_PACK_PROOF_REASON,
                "wrong_unit_page_pack_retracted_at": now,
                "wrong_unit_page_pack_retracted_at_iso": utc_stamp(now),
            }
        )
        con.execute(
            """
            update queue_items
               set state='queued',
                   current_source=null,
                   last_event=?,
                   active=1,
                   updated_at=?,
                   retry_after=?,
                   retry_after_iso=?,
                   outcome='retry_later',
                   display_phase='queued',
                   provider_status_state=null,
                   provider_status_phase=null,
                   provider_status_provider=null,
                   provider_status_actionability=null,
                   raw_json=?
             where id=?
            """,
            (WRONG_UNIT_PAGE_PACK_PROOF_MESSAGE, now, now, utc_stamp(now), json_dumps(queue_raw), queue_id),
        )
        changed = int(con.execute("select changes()").fetchone()[0] or 0)
        counts["queue_items"] += changed
        if changed:
            reopened_queues.add(queue_id)
        if row["wanted_id"]:
            con.execute(
                "update wanted_items set status=?, updated_at=? where id=?",
                (wanted_status_for_queue_state("queued"), now, row["wanted_id"]),
            )
        refresh_queue_provider_status_columns(con, queue_id)
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id(WRONG_UNIT_PAGE_PACK_PROOF_EVENT, "queue_item", queue_id, row["id"]),
                "queue_item",
                queue_id,
                row["series_id"],
                row["issue_id"],
                WRONG_UNIT_PAGE_PACK_PROOF_EVENT,
                "inkdrop_state",
                WRONG_UNIT_PAGE_PACK_PROOF_MESSAGE,
                "retry_later",
                "queued",
                now,
                json_dumps(queue_raw),
            ),
        )
    if cursor is not None:
        counts["_progress"] = {
            "examined": len(rows),
            "cursor": (
                {"created_at": rows[-1]["integrity_created_at"], "id": rows[-1]["id"]}
                if len(rows) >= semantic_scan_limit else None
            ),
        }
    return counts


def completion_bound_download_task(con, row):
    """Return only a download task structurally bound to an import proof."""
    import_raw = json_loads(row_value(row, "import_raw_json") or "{}", {})
    import_raw = import_raw if isinstance(import_raw, dict) else {}
    task_id = str(
        import_raw.get("download_task_id")
        or import_raw.get("task_id")
        or import_raw.get("source_download_task_id")
        or ""
    ).strip()
    source_attempt_id = str(row_value(row, "source_attempt_id") or "").strip()
    if not task_id and not source_attempt_id:
        return None
    clauses = []
    params = [row_value(row, "queue_id")]
    if task_id:
        clauses.append("id=?")
        params.append(task_id)
    if source_attempt_id:
        clauses.append("source_attempt_id=?")
        params.append(source_attempt_id)
    task = con.execute(
        f"""
        select id, queue_id, source_attempt_id, source, provider_id, provider,
               protocol, download_client, external_id, candidate_identity,
               title, status, state, local_path, save_path, raw_json,
               started_at, updated_at, completed_at
        from download_tasks
        where queue_id=? and ({' or '.join(clauses)})
        order by case when id=? then 1 else 0 end desc,
                 coalesce(completed_at, updated_at, started_at, 0) desc, id desc
        limit 1
        """,
        (*params, task_id),
    ).fetchone()
    return dict(task) if task else None


def completion_provenance_texts(task):
    task = task if isinstance(task, dict) else {}
    texts = []
    explicit_series = []

    def add(value, target):
        text = str(value or "").strip()
        if text and text not in target:
            target.append(text)

    add(task.get("title"), texts)
    add(task.get("local_path"), texts)
    raw = json_loads(task.get("raw_json") or "{}", {})
    raw = raw if isinstance(raw, dict) else {}

    def visit(item, depth=0):
        if not isinstance(item, dict) or depth > 5:
            return
        for key in (
            "title", "filename", "file_name", "remote_path", "remotePath",
            "candidate_path", "full_path", "path", "source_path", "folder",
        ):
            add(item.get(key), texts)
        for key in ("series", "series_title", "seriesTitle"):
            add(item.get(key), explicit_series)
        for key in (
            "download_task", "source_candidate", "candidate", "record", "raw",
            "download_client_handoff", "slskd", "result", "selected_candidate",
        ):
            visit(item.get(key), depth + 1)

    visit(raw)
    return texts, explicit_series


def completion_provenance_identity_contradiction(row, task):
    """Return redacted evidence only for explicit series/unit contradictions."""
    row = dict(row or {})
    task = task if isinstance(task, dict) else {}
    texts, explicit_series = completion_provenance_texts(task)
    if not texts and not explicit_series:
        return {}
    series_key = normalize_key(row.get("series_title"))
    explicit_series_keys = {normalize_key(value) for value in explicit_series if normalize_key(value)}
    series_mismatch = bool(series_key and explicit_series_keys and series_key not in explicit_series_keys)
    wanted_keys = issue_number_keys(row.get("normalized_number") or row.get("issue_number"))
    explicit_units = set()
    for text in texts:
        lowered = str(text).lower()
        if re.search(r"\b(complete|collection|omnibus|pack)\b", lowered):
            continue
        for unit in ("chapter",):
            value = manga_import_number_from_text(text, unit)
            if value:
                explicit_units |= issue_number_keys(value)
        for pattern in (
            r"\bissue\s*#?\s*0*(\d+(?:\.\d+)?)\b",
            r"(?<![a-z0-9])#\s*0*(\d+(?:\.\d+)?)(?![a-z0-9])",
        ):
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                explicit_units |= issue_number_keys(match.group(1))
    unit_mismatch = bool(wanted_keys and explicit_units and not (wanted_keys & explicit_units))
    if not series_mismatch and not unit_mismatch:
        return {}
    provenance_display = bad_source_candidate_path_title(texts[0]) if texts else "download provenance"
    provenance_digest = hashlib.sha256("\n".join(texts).encode("utf-8", "ignore")).hexdigest()
    return {
        "reason": "series_mismatch" if series_mismatch else "unit_mismatch",
        "series_mismatch": series_mismatch,
        "unit_mismatch": unit_mismatch,
        "canonical_series": row.get("series_title"),
        "canonical_issue": row.get("normalized_number") or row.get("issue_number"),
        "explicit_candidate_series": sorted(explicit_series_keys)[:4],
        "explicit_candidate_units": sorted(explicit_units)[:8],
        "provenance_display": provenance_display,
        "provenance_digest": provenance_digest,
        "download_task_id": task.get("id"),
        "source_attempt_id": task.get("source_attempt_id"),
    }


def cleanup_contradictory_completion_provenance(con, now, limit=5000, *, cursor=None):
    """Retract completion whose bound download provenance contradicts identity.

    The managed artifact is deliberately left in place. It is marked as
    quarantine-pending so an operator can move it with an authorized file
    operation while automatic acquisition resumes safely.
    """
    limit = max(1, min(int(limit or 5000), 5000))
    cursor = cursor if isinstance(cursor, dict) else None
    cursor_created = safe_float((cursor or {}).get("created_at")) if cursor else None
    cursor_id = str((cursor or {}).get("id") or "")
    cursor_clause = ""
    cursor_params = []
    if cursor is not None and (cursor_created is not None or cursor_id):
        cursor_created = cursor_created or 0
        cursor_clause = "and (coalesce(ir.created_at,0)>? or (coalesce(ir.created_at,0)=? and ir.id>?))"
        cursor_params = [cursor_created, cursor_created, cursor_id]
    rows = con.execute(
        f"""
        select ir.id, ir.queue_id, ir.source_attempt_id, ir.series_id, ir.issue_id,
               ir.source_path, ir.dest_path, ir.status, ir.outcome, ir.display_phase,
               ir.completion_truth, ir.folder_imported, ir.verified, ir.imported_count,
               ir.library_visibility_status, ir.raw_json as import_raw_json,
               q.wanted_id, q.state as queue_state, q.active as queue_active,
               q.current_source, q.last_event as queue_last_event,
               q.raw_json as queue_raw_json,
               s.title as series_title, i.issue_number, i.normalized_number,
               coalesce(ir.created_at,0) as integrity_created_at
        from import_results ir
        join queue_items q on q.id=ir.queue_id
        join series s on s.id=ir.series_id
        join issues i on i.id=ir.issue_id
        where (
            coalesce(ir.verified, 0)=1
            or coalesce(ir.folder_imported, 0)=1
            or lower(coalesce(ir.library_visibility_status, ''))='library_visible'
          )
          and lower(coalesce(ir.status, '')) not like '%wrong_unit%'
          and lower(coalesce(ir.status, '')) not like '%retracted%'
          {cursor_clause}
        order by coalesce(ir.created_at, 0) asc, ir.id asc
        limit ?
        """,
        (*cursor_params, limit),
    ).fetchall()
    counts = {"checked": 0, "retracted": 0, "queue_items": 0, "download_tasks": 0, "source_attempts": 0}
    for raw_row in rows:
        row = dict(raw_row)
        task = completion_bound_download_task(con, row)
        if not task:
            continue
        counts["checked"] += 1
        evidence = completion_provenance_identity_contradiction(row, task)
        if not evidence:
            continue
        import_raw = json_loads(row.get("import_raw_json") or "{}", {})
        import_raw = import_raw if isinstance(import_raw, dict) else {}
        import_raw.update(
            {
                "completion_provenance_identity_retracted": True,
                "completion_provenance_identity_evidence": evidence,
                "artifact_quarantine_pending": True,
                "artifact_quarantine_reason": "bound_download_provenance_identity_mismatch",
                "artifact_quarantine_requires_authorized_move": True,
                "completion_provenance_identity_retracted_at": now,
                "completion_provenance_identity_retracted_at_iso": utc_stamp(now),
                "previous_status": row.get("status"),
                "previous_verified": row.get("verified"),
                "previous_completion_truth": row.get("completion_truth"),
            }
        )
        con.execute(
            """
            update import_results
               set status='wrong_unit_quarantined', verified=0, outcome='failed',
                   display_phase='retry_later', completion_truth='wrong_unit',
                   folder_imported=0, library_visibility_status='not_applicable', raw_json=?
             where id=?
            """,
            (json_dumps(import_raw), row["id"]),
        )
        counts["retracted"] += int(con.execute("select changes()").fetchone()[0] or 0)

        task_raw = json_loads(task.get("raw_json") or "{}", {})
        task_raw = task_raw if isinstance(task_raw, dict) else {}
        task_raw.update(
            {
                "completion_provenance_identity_retracted": True,
                "completion_provenance_identity_evidence": evidence,
                "artifact_quarantine_pending": True,
                "artifact_quarantine_requires_authorized_move": True,
                "previous_status": task.get("status"),
                "previous_state": task.get("state"),
                "retracted_at": now,
                "retracted_at_iso": utc_stamp(now),
            }
        )
        con.execute(
            """
            update download_tasks
               set status='wrong_unit_quarantined', state='failed', outcome='problem',
                   display_phase='retry_later', lifecycle_phase='failed_candidate',
                   failure_reason='bound download provenance contradicts canonical series or unit',
                   retry_eligible=0, updated_at=?, completed_at=coalesce(completed_at, ?), raw_json=?
             where id=?
            """,
            (now, now, json_dumps(task_raw), task["id"]),
        )
        counts["download_tasks"] += int(con.execute("select changes()").fetchone()[0] or 0)
        if task.get("source_attempt_id"):
            con.execute(
                """
                update source_attempts
                   set status='wrong_unit_quarantined', outcome='problem',
                       display_phase='retry_later', lifecycle_phase='failed_candidate',
                       failure_reason='bound download provenance contradicts canonical series or unit',
                       retry_eligible=0, completed_at=coalesce(completed_at, ?)
                 where id=?
                """,
                (now, task["source_attempt_id"]),
            )
            counts["source_attempts"] += int(con.execute("select changes()").fetchone()[0] or 0)
        record_bad_source_candidate_row(
            con,
            {
                "source": task.get("source"),
                "provider": task.get("provider"),
                "protocol": task.get("protocol"),
                "series": row.get("series_title"),
                "title": evidence.get("provenance_display"),
                "reason": "completion_provenance_identity_mismatch",
                "raw": {
                    "kind": "completion_provenance_identity_mismatch",
                    "queue_id": row.get("queue_id"),
                    "issue_id": row.get("issue_id"),
                    "download_task_id": task.get("id"),
                    "provenance_digest": evidence.get("provenance_digest"),
                    "canonical_issue": evidence.get("canonical_issue"),
                    "explicit_candidate_units": evidence.get("explicit_candidate_units"),
                },
                "seen_at": now,
            },
            increment=False,
        )
        queue_raw = json_loads(row.get("queue_raw_json") or "{}", {})
        queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
        queue_raw.update(
            {
                "completion_provenance_identity_retracted": True,
                "completion_provenance_identity_evidence": evidence,
                "artifact_quarantine_pending": True,
                "artifact_quarantine_requires_authorized_move": True,
                "needs_user": False,
                "next_automatic_step": "source_ladder_try_next_candidate",
                "previous_state": row.get("queue_state"),
                "previous_last_event": row.get("queue_last_event"),
                "retracted_at": now,
                "retracted_at_iso": utc_stamp(now),
            }
        )
        con.execute(
            """
            update queue_items
               set state='queued', current_source=null, last_event=?, active=1,
                   updated_at=?, retry_after=?, retry_after_iso=?, outcome='retry_later',
                   display_phase='queued', provider_status_state=null,
                   provider_status_phase=null, provider_status_provider=null,
                   provider_status_actionability=null, raw_json=?
             where id=?
            """,
            (PROVENANCE_IDENTITY_RETRACTION_MESSAGE, now, now, utc_stamp(now), json_dumps(queue_raw), row["queue_id"]),
        )
        counts["queue_items"] += int(con.execute("select changes()").fetchone()[0] or 0)
        if row.get("wanted_id"):
            con.execute(
                "update wanted_items set status=?, updated_at=? where id=?",
                (wanted_status_for_queue_state("queued"), now, row["wanted_id"]),
            )
        refresh_queue_provider_status_columns(con, row["queue_id"])
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id(PROVENANCE_IDENTITY_RETRACTION_EVENT, row["id"], task["id"]),
                "import_result", row["id"], row["series_id"], row["issue_id"],
                PROVENANCE_IDENTITY_RETRACTION_EVENT, "inkdrop_state",
                PROVENANCE_IDENTITY_RETRACTION_MESSAGE, "problem", "retry_later", now,
                json_dumps(
                    {
                        "queue_id": row["queue_id"],
                        "import_result_id": row["id"],
                        "download_task_id": task["id"],
                        "reason": evidence.get("reason"),
                        "canonical_issue": evidence.get("canonical_issue"),
                        "explicit_candidate_units": evidence.get("explicit_candidate_units"),
                        "provenance_digest": evidence.get("provenance_digest"),
                        "artifact_quarantine_pending": True,
                    }
                ),
            ),
        )
    if cursor is not None:
        counts["_progress"] = {
            "examined": len(rows),
            "cursor": (
                {"created_at": rows[-1]["integrity_created_at"], "id": rows[-1]["id"]}
                if len(rows) >= limit else None
            ),
        }
    return counts


def download_task_matches_missing_folder_proof(row, import_row):
    if not row or not import_row:
        return False
    proof_attempt_id = str(import_row["source_attempt_id"] or "").strip()
    task_attempt_id = str(row["source_attempt_id"] or "").strip()
    if proof_attempt_id and task_attempt_id and proof_attempt_id == task_attempt_id:
        return True
    proof_paths = {
        str(import_row["dest_path"] or "").replace("\\", "/").rstrip("/").lower(),
        str(import_row["source_path"] or "").replace("\\", "/").rstrip("/").lower(),
    }
    proof_paths = {path for path in proof_paths if path}
    for key in ("local_path", "save_path", "title"):
        value = str(row[key] or "").replace("\\", "/").rstrip("/").lower()
        if value and value in proof_paths:
            return True
    return False


def download_tasks_matching_missing_folder_proof(con, import_row):
    rows = con.execute(
        """
        select id, source_attempt_id, title, local_path, save_path, status, state,
               outcome, display_phase, lifecycle_phase, failure_reason,
               retry_eligible, raw_json
        from download_tasks
        where queue_id=?
          and (
            lower(coalesce(state, '')) in ('verified', 'downloading', 'import_ready', 'importing')
            or lower(coalesce(status, '')) in (
              'verified', 'queue_verified', 'folder_verified', 'library_visible',
              'started_waiting', 'staged_file_ready', 'verification_pending'
            )
          )
        """,
        (import_row["queue_id"],),
    ).fetchall()
    return [row for row in rows if download_task_matches_missing_folder_proof(row, import_row)]


def cleanup_missing_folder_verified_import_proofs(
    con, now, limit=5000, *, series_id=None, issue_number=None, dry_run=False, cursor=None
):
    """Retract stale folder proofs and finish their linked media cleanup.

    This is intentionally conservative. It only considers import results that
    claimed managed-folder completion, or this cleanup's exact retracted status,
    and point to a destination under an InkDrop media root. If another verified
    folder proof for the same queue has a live file, the stale proof is retired
    but the queue remains verified.
    """
    managed_roots = media_management_roots_from_connection(con)
    if not managed_roots:
        return {"import_results": 0, "queue_items": 0, "download_tasks": 0, "media_files": 0}
    try:
        limit = max(1, min(int(limit or 5000), 5000))
    except Exception:
        limit = 5000
    cursor = cursor if isinstance(cursor, dict) else None
    cursor_created = safe_float((cursor or {}).get("created_at")) if cursor else None
    cursor_id = str((cursor or {}).get("id") or "")
    cursor_clause = ""
    cursor_params = []
    if cursor is not None and (cursor_created is not None or cursor_id):
        cursor_created = cursor_created or 0
        cursor_clause = "and (coalesce(ir.created_at,0)>? or (coalesce(ir.created_at,0)=? and ir.id>?))"
        cursor_params = [cursor_created, cursor_created, cursor_id]
    rows = con.execute(
        f"""
        select ir.id, ir.queue_id, ir.source_attempt_id, ir.series_id, ir.issue_id,
               ir.source_path, ir.dest_path, ir.status, ir.verified, ir.imported_count,
               ir.outcome, ir.display_phase, ir.completion_truth, ir.folder_imported,
               ir.library_visibility_status, ir.library_visibility_provider,
               ir.raw_json, q.wanted_id, q.state as queue_state,
               q.active as queue_active, q.current_source, q.last_event as queue_last_event,
               q.raw_json as queue_raw_json,
               coalesce(ir.created_at,0) as integrity_created_at
        from import_results ir
        left join queue_items q on q.id = ir.queue_id
        left join issues scoped_issue on scoped_issue.id = ir.issue_id
        where coalesce(ir.dest_path, '') <> ''
          and (
            (
              coalesce(ir.verified, 0)=1
              and (
                lower(coalesce(ir.completion_truth, '')) = 'folder'
                or coalesce(ir.folder_imported, 0)=1
              )
            )
            or lower(coalesce(ir.status, '')) = ?
          )
          and (? is null or ir.series_id = ?)
          and (? is null or scoped_issue.issue_number = ? or scoped_issue.normalized_number = ?)
          {cursor_clause}
        order by coalesce(ir.created_at, 0) asc, ir.id asc
        limit ?
        """,
        (
            MISSING_FOLDER_PROOF_STATUS.lower(),
            series_id, series_id, issue_number, issue_number, issue_number, *cursor_params, limit,
        ),
    ).fetchall()
    import_results = 0
    queue_items = 0
    download_tasks = 0
    media_files = 0
    handled_media_ids = set()
    handled_task_ids = set()
    handled_queue_ids = set()
    for row in rows:
        already_retracted = str(row["status"] or "").strip().lower() == MISSING_FOLDER_PROOF_STATUS.lower()
        if not already_retracted and import_result_is_bad_or_retracted(row):
            continue
        dest_path = str(row["dest_path"] or "").strip()
        if not path_under_any_root(dest_path, managed_roots):
            continue
        try:
            dest_exists = Path(dest_path).exists()
        except OSError:
            dest_exists = False
        if dest_exists:
            continue
        live_sibling = False
        if not already_retracted:
            live_sibling = live_folder_import_proof_exists(con, row["queue_id"], row["id"], managed_roots)
        if table_exists(con, "media_files"):
            normalized_dest = media_file_normalized_path(dest_path)
            linked_media = con.execute(
                """
                select id, status, active, completion_truth, folder_imported,
                       size_bytes, mtime, raw_json
                  from media_files
                 where (
                       import_result_id=?
                    or (
                      import_result_id is null
                      and ? <> '' and normalized_path=?
                      and series_id=? and issue_id=?
                      and (queue_id is null or queue_id=?)
                    )
                 )
                   and (
                     coalesce(active, 0)<>0
                     or lower(coalesce(status, ''))<>'missing'
                     or completion_truth is not null
                     or coalesce(folder_imported, 0)<>0
                     or size_bytes is not null
                     or mtime is not null
                   )
                """,
                (
                    row["id"], normalized_dest, normalized_dest,
                    row["series_id"], row["issue_id"], row["queue_id"],
                ),
            ).fetchall()
            linked_media = [row for row in linked_media if row["id"] not in handled_media_ids]
            handled_media_ids.update(row["id"] for row in linked_media)
            media_files += len(linked_media) if dry_run else 0
            if not dry_run:
                for media_row in linked_media:
                    media_raw = json_loads(media_row["raw_json"] or "{}", {})
                    media_raw = media_raw if isinstance(media_raw, dict) else {}
                    media_raw.update({
                        "status": "missing",
                        "reason": "managed_destination_missing",
                        "import_result_id": row["id"],
                        "observed_at": now,
                        "observed_at_iso": utc_stamp(now),
                    })
                    con.execute(
                        """
                        update media_files
                           set status='missing', active=0, completion_truth=null,
                               folder_imported=0, size_bytes=null, mtime=null,
                               last_seen_at=?, raw_json=?
                         where id=?
                        """,
                        (now, json_dumps(media_raw), media_row["id"]),
                    )
                    media_files += int(con.execute("select changes()").fetchone()[0] or 0)
        if already_retracted:
            continue
        if dry_run:
            import_results += 1
            matching_tasks = download_tasks_matching_missing_folder_proof(con, row)
            new_task_ids = {task["id"] for task in matching_tasks} - handled_task_ids
            download_tasks += len(new_task_ids)
            handled_task_ids.update(new_task_ids)
            queue_state_key = str(row["queue_state"] or "").strip().lower()
            if (
                not live_sibling
                and row["queue_id"]
                and row["queue_id"] not in handled_queue_ids
                and queue_state_key not in MISSING_FOLDER_PROOF_NO_REOPEN_QUEUE_STATES
            ):
                handled_queue_ids.add(row["queue_id"])
                queue_items += 1
            continue
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        raw.update(
            {
                "stale_folder_proof_retracted": True,
                "stale_folder_proof_reason": "managed_destination_missing",
                "stale_folder_proof_dest_path": dest_path,
                "stale_folder_proof_retracted_at": now,
                "stale_folder_proof_retracted_at_iso": utc_stamp(now),
                "stale_folder_proof_live_sibling": live_sibling,
                "previous_status": row["status"],
                "previous_verified": row["verified"],
                "previous_outcome": row["outcome"],
                "previous_display_phase": row["display_phase"],
                "previous_completion_truth": row["completion_truth"],
            }
        )
        con.execute(
            """
            update import_results
               set status=?,
                   verified=0,
                   outcome='failed',
                   display_phase='retry_later',
                   completion_truth='missing_file',
                   folder_imported=0,
                   library_visibility_status='missing_file',
                   raw_json=?
             where id=?
            """,
            (MISSING_FOLDER_PROOF_STATUS, json_dumps(raw), row["id"]),
        )
        import_results += int(con.execute("select changes()").fetchone()[0] or 0)
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("missing_folder_import_proof_retracted", row["id"]),
                "import_result",
                row["id"],
                row["series_id"],
                row["issue_id"],
                "missing_folder_import_proof_retracted",
                "inkdrop_state",
                f"Verified folder proof missing from disk: {dest_path}",
                "problem",
                "retry_later",
                now,
                json_dumps(raw),
            ),
        )
        task_rows = download_tasks_matching_missing_folder_proof(con, row)
        for task in task_rows:
            if task["id"] in handled_task_ids:
                continue
            handled_task_ids.add(task["id"])
            task_raw = json_loads(task["raw_json"] or "{}", {})
            task_raw = task_raw if isinstance(task_raw, dict) else {}
            task_raw.update(
                {
                    "stale_folder_proof_retracted": True,
                    "stale_folder_proof_import_result_id": row["id"],
                    "stale_folder_proof_dest_path": dest_path,
                    "stale_folder_proof_retracted_at": now,
                    "stale_folder_proof_retracted_at_iso": utc_stamp(now),
                    "previous_status": task["status"],
                    "previous_state": task["state"],
                }
            )
            con.execute(
                """
                update download_tasks
                   set status=?,
                       state='failed',
                       outcome='problem',
                       display_phase='retry_later',
                       lifecycle_phase='failed_candidate',
                       failure_reason='Verified folder proof missing from disk',
                       retry_eligible=1,
                       updated_at=?,
                       completed_at=coalesce(completed_at, ?),
                       raw_json=?
                 where id=?
                """,
                (MISSING_FOLDER_PROOF_STATUS, now, now, json_dumps(task_raw), task["id"]),
            )
            download_tasks += int(con.execute("select changes()").fetchone()[0] or 0)
        queue_state_key = str(row["queue_state"] or "").strip().lower()
        if (
            live_sibling
            or not row["queue_id"]
            or row["queue_id"] in handled_queue_ids
            or queue_state_key in MISSING_FOLDER_PROOF_NO_REOPEN_QUEUE_STATES
        ):
            continue
        handled_queue_ids.add(row["queue_id"])
        queue_raw = json_loads(row["queue_raw_json"] or "{}", {})
        queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
        queue_raw.update(
            {
                "previous_state": row["queue_state"],
                "previous_active": row["queue_active"],
                "previous_last_event": row["queue_last_event"],
                "stale_folder_proof_retracted": True,
                "stale_folder_proof_import_result_id": row["id"],
                "stale_folder_proof_dest_path": dest_path,
                "stale_folder_proof_retracted_at": now,
                "stale_folder_proof_retracted_at_iso": utc_stamp(now),
            }
        )
        con.execute(
            """
            update queue_items
               set state='queued',
                   current_source=null,
                   last_event=?,
                   active=1,
                   updated_at=?,
                   retry_after=?,
                   retry_after_iso=?,
                   outcome='retry_later',
                   display_phase='queued',
                   provider_status_state=null,
                   provider_status_phase=null,
                   provider_status_provider=null,
                   provider_status_actionability=null,
                   raw_json=?
             where id=?
            """,
            (MISSING_FOLDER_PROOF_MESSAGE, now, now, utc_stamp(now), json_dumps(queue_raw), row["queue_id"]),
        )
        queue_items += int(con.execute("select changes()").fetchone()[0] or 0)
        if row["wanted_id"]:
            con.execute(
                "update wanted_items set status=?, updated_at=? where id=?",
                (wanted_status_for_queue_state("queued"), now, row["wanted_id"]),
            )
        refresh_queue_provider_status_columns(con, row["queue_id"])
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("missing_folder_queue_reopened", row["queue_id"], row["id"]),
                "queue_item",
                row["queue_id"],
                row["series_id"],
                row["issue_id"],
                "missing_folder_queue_reopened",
                "inkdrop_state",
                MISSING_FOLDER_PROOF_MESSAGE,
                "retry_later",
                "queued",
                now,
                json_dumps(queue_raw),
            ),
        )
    result = {
        "import_results": import_results,
        "queue_items": queue_items,
        "download_tasks": download_tasks,
        "media_files": media_files,
    }
    if cursor is not None:
        result["_progress"] = {
            "examined": len(rows),
            "cursor": (
                {"created_at": rows[-1]["integrity_created_at"], "id": rows[-1]["id"]}
                if len(rows) >= limit else None
            ),
        }
    return result


def collapse_import_status_adapter_series(con, now):
    rows = con.execute(
        """
        select old.id as old_id, old.kapowarr_id, native.id as native_id
        from series old
        join series native
          on native.kapowarr_id = old.kapowarr_id
         and native.metadata_provider = 'comicvine'
        where old.source = 'import_status'
          and old.metadata_provider = 'kapowarr'
          and old.kapowarr_id is not null
          and old.id <> native.id
        """
    ).fetchall()
    collapsed = 0
    for row in rows:
        old_id = row["old_id"]
        native_id = row["native_id"]
        issue_map = {}
        for issue in con.execute(
            "select id, normalized_number, issue_number from issues where series_id = ?",
            (old_id,),
        ):
            native_issue = con.execute(
                """
                select id from issues
                where series_id = ?
                  and (
                    normalized_number = ?
                    or issue_number = ?
                    or normalized_number = ?
                  )
                order by
                  case when metadata_provider = 'comicvine' then 0 else 1 end,
                  updated_at desc
                limit 1
                """,
                (
                    native_id,
                    issue["normalized_number"],
                    issue["issue_number"],
                    normalize_issue_number(issue["issue_number"]),
                ),
            ).fetchone()
            if native_issue:
                issue_map[issue["id"]] = native_issue["id"]

        for table in ("wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
            con.execute(f"update {table} set series_id = ? where series_id = ?", (native_id, old_id))
            for old_issue_id, native_issue_id in issue_map.items():
                con.execute(
                    f"update {table} set issue_id = ? where issue_id = ?",
                    (native_issue_id, old_issue_id),
                )

        old_issue_ids = list(issue_map.keys())
        if old_issue_ids:
            placeholders = ",".join("?" for _ in old_issue_ids)
            still_referenced = False
            for table in ("wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
                ref = con.execute(
                    f"select 1 from {table} where issue_id in ({placeholders}) limit 1",
                    old_issue_ids,
                ).fetchone()
                if ref:
                    still_referenced = True
                    break
            if not still_referenced:
                con.execute(f"delete from issues where id in ({placeholders})", old_issue_ids)

        dependent = False
        for table in ("issues", "wanted_items", "queue_items", "source_attempts", "import_results", "review_exceptions", "history_events"):
            ref = con.execute(f"select 1 from {table} where series_id = ? limit 1", (old_id,)).fetchone()
            if ref:
                dependent = True
                break
        if not dependent:
            con.execute("delete from series where id = ?", (old_id,))
        else:
            con.execute(
                """
                update series
                set source='comicvine',
                    metadata_provider='comicvine',
                    metadata_id=replace(?, 'comicvine:', ''),
                    updated_at=?
                where id=?
                """,
                (native_id, now, old_id),
            )
        collapsed += 1
    return collapsed


def sync_import_status(con, state_dir, now, data=None, finalize=True):
    if data is None:
        data = read_json(Path(state_dir) / "import-status.json", {})
    imported = data.get("imported") if isinstance(data, dict) else []
    skipped_rows = data.get("skipped") if isinstance(data, dict) else []
    verification_by_dest = pack_import_verification_index(data.get("verification") if isinstance(data, dict) else {})
    sync_rows = [("imported", row) for row in (imported or []) if isinstance(row, dict)]
    for row in skipped_rows or []:
        if not isinstance(row, dict):
            continue
        if not pack_import_event_verified(row, "skipped_existing", verification_by_dest):
            continue
        dest = pack_import_event_dest(row)
        if not dest:
            continue
        normalized_row = dict(row)
        normalized_row.setdefault("dest", dest)
        normalized_row.setdefault("canonical_issue_number", row.get("issue_number") or row.get("normalized_number"))
        sync_rows.append(("skipped_existing", normalized_row))
    count = 0
    library_visibility_required = boolish(
        _app_setting_value_from_connection(con, "media_management.library_visibility_required", False),
        False,
    )
    for row_kind, row in sync_rows:
        verification_row = pack_import_event_verification_row(row, verification_by_dest)
        if row_kind == "skipped_existing":
            verified = pack_import_event_verified(row, "skipped_existing", verification_by_dest)
        else:
            verified = pack_import_event_verified(row, row_kind, verification_by_dest)
            if not verification_row and bool(((data.get("verification") or {}).get("failure_count") or 0) == 0):
                verified = True
        dest_path = pack_import_event_dest(row) or row.get("dest")
        queue_match = find_queue_for_import(con, row, None, None)
        queue_id = queue_match["id"] if queue_match else None
        wanted_id = queue_match["wanted_id"] if queue_match else None
        if queue_match:
            series_id = queue_match["series_id"]
            issue_id = queue_match["issue_id"]
        else:
            series_payload = {
                "series": row.get("matched_series"),
                "kapowarr_id": row.get("matched_kapowarr_id"),
                "source": "import_status",
            }
            try:
                series_id = upsert_series(con, series_payload, now)
            except SeriesIdentityTombstoneBlocked:
                continue
            issue_id = None
        if series_id_user_removed(con, series_id):
            retire_removed_series_work(con, series_id, now, source="sync_import_status_removed_series")
            continue
        if not queue_match:
            issue_payload = {
                "issueNumber": row.get("canonical_issue_number") or row.get("normalized_number"),
                "title": row.get("canonical_issue_title"),
            }
            issue_id = upsert_issue(con, series_id, issue_payload, now)
        import_id = stable_id(
            "import",
            row_kind,
            row.get("sha256"),
            row.get("source"),
            row.get("dest"),
            row.get("native_series_id") or row.get("comicvine_id") or row.get("matched_kapowarr_id"),
            row.get("canonical_issue_number") or row.get("normalized_number") or row.get("issue"),
        )
        existing_import = con.execute(
            """
            select id, status, outcome, display_phase, completion_truth,
                   library_visibility_status, raw_json
            from import_results
            where id=?
            limit 1
            """,
            (import_id,),
        ).fetchone()
        if import_result_wrong_unit_rejected(existing_import):
            continue
        source_attempt_id = latest_source_attempt_id_for_queue(con, queue_id, data.get("updated_at") or now) if queue_id else None
        library_visibility_provider = pack_import_event_library_provider(row, verification_row)
        library_visible = pack_import_event_library_visible(row, verification_row)
        imported_count_value = 1 if row_kind == "imported" else 0
        skipped_count_value = int(data.get("skipped_count") or 0) if row_kind == "imported" else 1
        status_value = import_status_sync_verification_status(row_kind, verified, verification_row)
        status_value = adapter_neutral_library_status(status_value, library_visibility_provider, library_visible)
        folder_path_ready = import_result_managed_dest_path_exists(con, dest_path)
        if dest_path and not folder_path_ready and (verified or imported_count_value > 0 or library_visible):
            verified = False
            library_visible = False
            status_value = "missing_file"
        folder_first_satisfied_statuses = {
            "imported",
            "verification_pending",
            "waiting_for_library_scan",
            "waiting_for_kavita_scan",
            "library_scan_timeout",
            "kavita_scan_timeout",
            "imported_not_resolved",
        }
        if (
            imported_count_value > 0
            and dest_path
            and not library_visibility_required
            and not library_visible
            and status_value in folder_first_satisfied_statuses
        ):
            status_value = "folder_verified"
            verified = True
        verified_value = 1 if verified else 0
        completion_evidence = import_result_completion_evidence(
            status_value,
            verified,
            imported_count_value,
            dest_path,
            library_visibility_provider,
            library_visibility_required,
            folder_path_exists=folder_path_ready,
        )
        if library_visible:
            completion_evidence["library_visibility_status"] = "library_visible"
        folder_completion_satisfied = bool(
            completion_evidence["folder_imported"]
            and not completion_evidence["library_visibility_required"]
        )
        if queue_id and (verified or folder_completion_satisfied):
            library_confirmation = bool(library_visible and status_value != "folder_verified")
            verification_message = (
                "Confirmed in your library"
                if library_confirmation
                else "Folder completion confirmed for imported file; library visibility will follow"
            )
            mark_queue_verified_for_import(
                con,
                queue_id,
                wanted_id,
                data.get("updated_at") or now,
                message=verification_message,
                current_source=None if library_confirmation else "importer",
            )
        outcome = import_result_outcome(status_value, verified, imported_count_value, skipped_count_value)
        display_phase = import_result_display_phase(status_value, verified, imported_count_value, skipped_count_value, outcome)
        raw_payload = dict(row)
        raw_payload.setdefault("import_row_kind", row_kind)
        raw_payload.setdefault("outcome", outcome)
        raw_payload.setdefault("display_phase", display_phase)
        raw_payload.setdefault("completion_truth", completion_evidence["completion_truth"])
        raw_payload.setdefault("folder_imported", completion_evidence["folder_imported"])
        raw_payload.setdefault("library_visibility_required", completion_evidence["library_visibility_required"])
        raw_payload.setdefault("library_visibility_status", completion_evidence["library_visibility_status"])
        raw_payload.setdefault("library_visibility_provider", completion_evidence["library_visibility_provider"])
        if dest_path and not folder_path_ready:
            raw_payload.setdefault("managed_dest_missing", True)
            raw_payload.setdefault("managed_dest_missing_path", dest_path)
            raw_payload.setdefault("managed_dest_missing_at", now)
            raw_payload.setdefault("managed_dest_missing_at_iso", utc_stamp(now))
        if verification_row:
            raw_payload.setdefault("verification", verification_row)
        con.execute(
            """
            insert into import_results(
                id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path, status, verified,
                outcome, display_phase, completion_truth, folder_imported, library_visibility_required,
                library_visibility_status, library_visibility_provider, imported_count, skipped_count, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(id) do update set
                queue_id=excluded.queue_id,
                source_attempt_id=coalesce(import_results.source_attempt_id, excluded.source_attempt_id),
                series_id=excluded.series_id,
                issue_id=excluded.issue_id,
                source_path=excluded.source_path,
                dest_path=excluded.dest_path,
                status=excluded.status,
                verified=excluded.verified,
                outcome=excluded.outcome,
                display_phase=excluded.display_phase,
                completion_truth=excluded.completion_truth,
                folder_imported=excluded.folder_imported,
                library_visibility_required=excluded.library_visibility_required,
                library_visibility_status=excluded.library_visibility_status,
                library_visibility_provider=excluded.library_visibility_provider,
                imported_count=excluded.imported_count,
                skipped_count=excluded.skipped_count,
                raw_json=excluded.raw_json
            """,
            (
                import_id,
                queue_id,
                source_attempt_id,
                series_id,
                issue_id,
                row.get("source"),
                dest_path,
                status_value,
                verified_value,
                outcome,
                display_phase,
                completion_evidence["completion_truth"],
                1 if completion_evidence["folder_imported"] else 0,
                1 if completion_evidence["library_visibility_required"] else 0,
                completion_evidence["library_visibility_status"],
                completion_evidence["library_visibility_provider"],
                imported_count_value,
                skipped_count_value,
                data.get("updated_at") or now,
                json_dumps(raw_payload),
            ),
        )
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("import_history", import_id),
                "import_result",
                import_id,
                series_id,
                issue_id,
                "import_verified" if verified else "imported",
                "importer",
                row.get("dest") or row.get("source"),
                outcome,
                display_phase,
                data.get("updated_at") or now,
                json_dumps(raw_payload),
            ),
        )
        count += 1
    if finalize:
        backfill_import_queue_links(con, now)
        backfill_import_source_attempt_links(con)
        collapse_import_status_adapter_series(con, now)
    return count


def pending_import_status_events(state_dir, limit=100, max_batch_bytes=64 * 1024 * 1024):
    events_dir = Path(state_dir) / "import-status-events"
    if not events_dir.is_dir():
        return [], []
    events = []
    rejected = []
    valid_limit = max(1, min(int(limit or 100), 100))
    byte_limit = max(1024 * 1024, min(int(max_batch_bytes or 64 * 1024 * 1024), 64 * 1024 * 1024))
    selected_bytes = 0
    for path in sorted(events_dir.iterdir(), key=lambda item: item.name):
        if not path.is_file() or path.suffix.lower() != ".json":
            continue
        reason = None
        try:
            event_bytes = path.stat().st_size
            if event_bytes > 64 * 1024 * 1024:
                reason = "event_too_large"
                payload = None
            elif events and selected_bytes + event_bytes > byte_limit:
                break
            else:
                payload = read_json(path, None)
        except OSError:
            continue
        if not isinstance(payload, dict):
            reason = reason or "invalid_json"
        if reason:
            rejected_path = quarantine_import_status_event(path, reason)
            if rejected_path:
                rejected.append({"path": rejected_path, "reason": reason})
            continue
        events.append((path, payload))
        selected_bytes += event_bytes
        if len(events) >= valid_limit:
            break
    events.sort(key=lambda item: item[0].name)
    return events, rejected


def quarantine_import_status_event(path, reason):
    path = Path(path)
    rejected_dir = path.parent / "rejected"
    try:
        rejected_dir.mkdir(parents=True, exist_ok=True)
        target = rejected_dir / path.name
        if target.exists():
            target = rejected_dir / f"{path.stem}-{stable_id(path.name, time.time_ns())[:12]}{path.suffix}"
        path.replace(target)
        reason_path = target.with_suffix(target.suffix + ".reason.json")
        reason_path.write_text(json_dumps({"reason": str(reason or "invalid_event")}), encoding="utf-8")
        return str(target)
    except OSError:
        return None


def sync_import_status_sources(con, state_dir, now):
    state = Path(state_dir)
    events, rejected = pending_import_status_events(state)
    count = 0
    for _, payload in events:
        count += sync_import_status(con, state, now, data=payload, finalize=False)
    latest = read_json(state / "import-status.json", {})
    event_digests = {
        hashlib.sha256(json_dumps(payload).encode("utf-8")).hexdigest()
        for _, payload in events
    }
    latest_digest = (
        hashlib.sha256(json_dumps(latest).encode("utf-8")).hexdigest()
        if isinstance(latest, dict) and latest else ""
    )
    marker = con.execute(
        "select value from schema_meta where key='last_import_status_digest' limit 1"
    ).fetchone()
    previous_digest = str(marker["value"] or "") if marker else ""
    if latest_digest and not events and latest_digest not in event_digests and latest_digest != previous_digest:
        count += sync_import_status(con, state, now, data=latest, finalize=False)
    if latest_digest:
        con.execute(
            "insert into schema_meta(key,value) values('last_import_status_digest',?) "
            "on conflict(key) do update set value=excluded.value",
            (latest_digest,),
        )
    backfill_import_queue_links(con, now)
    collapse_import_status_adapter_series(con, now)
    return {"count": count, "events": events, "rejected": rejected}


def retire_import_status_events(events):
    retired = 0
    for event_path, _ in events or []:
        try:
            event_path.unlink()
            retired += 1
        except FileNotFoundError:
            retired += 1
        except OSError:
            pass
    return retired


def backfill_series_history(con):
    count = 0
    rows = con.execute(
        """
        select id, title, source, metadata_provider, metadata_id, kapowarr_id,
               monitored, monitor_new, auto_grab, created_at, updated_at, raw_json
        from series
        """
    ).fetchall()
    for row in rows:
        series_id = row["id"]
        created_at = safe_float(row["created_at"]) or safe_float(row["updated_at"]) or time.time()
        event_id = stable_id("series_monitor_synced", series_id)
        ownership = series_ownership(row["source"], row["metadata_provider"], row["kapowarr_id"])
        source = row["source"] or row["metadata_provider"] or ownership or "inkdrop"
        raw = {
            "series_id": series_id,
            "title": row["title"],
            "source": row["source"],
            "metadata_provider": row["metadata_provider"],
            "metadata_id": row["metadata_id"],
            "kapowarr_id": row["kapowarr_id"],
            "ownership": ownership,
            "monitored": bool(row["monitored"]),
            "monitor_new": bool(row["monitor_new"]),
            "auto_grab": bool(row["auto_grab"]),
            "backfilled": True,
        }
        detail = []
        if ownership:
            detail.append(ownership)
        if row["monitor_new"]:
            detail.append("auto future")
        if row["auto_grab"]:
            detail.append("auto grab")
        message = f"{row['title']} monitor synced"
        if detail:
            message = f"{message}: {', '.join(detail)}"
        cur = con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?)
            """,
            (
                event_id,
                "series",
                series_id,
                series_id,
                None,
                "series_monitor_synced",
                source,
                message,
                created_at,
                json_dumps(raw),
            ),
        )
        count += int(cur.rowcount or 0)
    return count


def provider_contract_payload(row, fields):
    row = row if row is not None else {}
    raw = json_loads(row["raw_json"] or "{}", {}) if "raw_json" in row.keys() else {}
    payload = raw if isinstance(raw, dict) else {}
    payload = dict(payload)
    for field in fields:
        try:
            value = row[field]
        except (KeyError, IndexError):
            continue
        if value not in (None, "", [], {}) and field not in payload:
            payload[field] = value
    return normalize_source_attempt_payload(payload)


def backfill_provider_contract_fields(con):
    source_attempt_count = 0
    download_task_count = 0
    attempt_rows = con.execute(
        """
        select id, source, provider_id, source_type, provider, protocol,
               download_client, category, save_path, download_url_hash,
               candidate_identity, lifecycle_phase, failure_reason,
               retry_eligible, status, title, username, score, raw_json
        from source_attempts
        where provider_id is null
           or source_type is null
           or candidate_identity is null
           or lifecycle_phase is null
           or retry_eligible is null
        """
    ).fetchall()
    for row in attempt_rows:
        payload = provider_contract_payload(
            row,
            (
                "source",
                "provider_id",
                "source_type",
                "provider",
                "protocol",
                "download_client",
                "category",
                "save_path",
                "download_url_hash",
                "candidate_identity",
                "lifecycle_phase",
                "failure_reason",
                "retry_eligible",
                "status",
                "title",
                "username",
                "score",
            ),
        )
        cur = con.execute(
            """
            update source_attempts
            set provider_id=?,
                source_type=?,
                candidate_identity=?,
                lifecycle_phase=?,
                failure_reason=?,
                retry_eligible=?,
                raw_json=?
            where id=?
            """,
            (
                payload.get("provider_id"),
                payload.get("source_type"),
                payload.get("candidate_identity"),
                payload.get("lifecycle_phase"),
                payload.get("failure_reason"),
                1 if payload.get("retry_eligible") else 0,
                json_dumps(payload),
                row["id"],
            ),
        )
        source_attempt_count += int(cur.rowcount or 0)
    task_rows = con.execute(
        """
        select id, source_attempt_id, source, provider_id, provider, protocol,
               download_client, external_id, candidate_identity, lifecycle_phase,
               failure_reason, retry_eligible, title, status, category, save_path,
               local_path, raw_json
        from download_tasks
        where provider_id is null
           or candidate_identity is null
           or lifecycle_phase is null
           or retry_eligible is null
        """
    ).fetchall()
    for row in task_rows:
        payload = provider_contract_payload(
            row,
            (
                "source_attempt_id",
                "source",
                "provider_id",
                "provider",
                "protocol",
                "download_client",
                "external_id",
                "candidate_identity",
                "lifecycle_phase",
                "failure_reason",
                "retry_eligible",
                "title",
                "status",
                "category",
                "save_path",
                "local_path",
            ),
        )
        if row["source_attempt_id"]:
            linked = con.execute(
                """
                select provider_id, candidate_identity, lifecycle_phase, failure_reason, retry_eligible
                from source_attempts
                where id=?
                """,
                (row["source_attempt_id"],),
            ).fetchone()
            if linked:
                for field in ("provider_id", "candidate_identity", "lifecycle_phase", "failure_reason", "retry_eligible"):
                    if linked[field] not in (None, ""):
                        payload[field] = linked[field]
        cur = con.execute(
            """
            update download_tasks
            set provider_id=?,
                candidate_identity=?,
                lifecycle_phase=?,
                failure_reason=?,
                retry_eligible=?,
                raw_json=?
            where id=?
            """,
            (
                payload.get("provider_id"),
                payload.get("candidate_identity"),
                payload.get("lifecycle_phase"),
                payload.get("failure_reason"),
                1 if payload.get("retry_eligible") else 0,
                json_dumps(payload),
                row["id"],
            ),
        )
        download_task_count += int(cur.rowcount or 0)
    return {
        "source_attempts": source_attempt_count,
        "download_tasks": download_task_count,
    }


def backfill_series_path_contracts(con, now=None):
    now = float(now or time.time())
    rows = con.execute(
        """
        select id, title, publisher, metadata_provider, metadata_id, kapowarr_id,
               source, media_type,
               library_root, library_path, library_path_template,
               library_path_source, library_adapter_path, raw_json
        from series
        where coalesce(library_path_source, '') != 'user'
        """
    ).fetchall()
    updated = 0
    for row in rows:
        media_decision = native_series_media_decision(row, provider=row["metadata_provider"] or row["source"])
        media_type = media_decision.get("media_type") or normalized_media_type(row["media_type"]) or "comic"
        repair_media_root = bool(
            has_path_contract_values(row)
            and path_contract_needs_media_root_repair(row, media_type, con=con)
        )
        if has_path_contract_values(row) and not repair_media_root:
            continue
        row_source = str(row["source"] or "").strip().lower()
        if row_source == "kapowarr" or str(row["metadata_provider"] or "").strip().lower() == "kapowarr":
            continue
        contract = native_series_path_contract(
            row,
            media_type=media_type,
            con=con,
            prefer_existing_root=not repair_media_root,
        )
        if not contract:
            continue
        previous_contract = None
        if repair_media_root:
            previous_contract = {
                "library_root": row["library_root"],
                "library_path": row["library_path"],
                "library_path_template": row["library_path_template"],
                "library_path_source": row["library_path_source"],
                "library_adapter_path": row["library_adapter_path"],
                "media_type": row["media_type"],
            }
        contract_source = {
            "source": "inkdrop",
            "contract_source": "native_root_template",
            "reason": "media_root_mismatch_repaired" if repair_media_root else "missing_path_contract",
            "media_type_decision": media_decision,
        }
        if previous_contract:
            contract_source["previous_path_contract"] = previous_contract
        if not contract.get("library_path") and not contract.get("library_adapter_path"):
            continue
        current = {
            "library_root": row["library_root"],
            "library_path": row["library_path"],
            "library_path_template": row["library_path_template"],
            "library_path_source": row["library_path_source"],
            "library_adapter_path": row["library_adapter_path"],
        }
        if all((current.get(key) or None) == (contract.get(key) or None) for key in current):
            continue
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        raw_payload = dict(raw.get("path_contract") or {})
        raw_payload.update(contract)
        raw_payload.update(contract_source)
        raw_payload["backfilled_at"] = now
        raw_payload["backfilled_at_iso"] = utc_stamp(now)
        raw["path_contract"] = raw_payload
        cur = con.execute(
            """
            update series
            set library_root=?,
                library_path=?,
                library_path_template=?,
                library_path_source=?,
                library_adapter_path=?,
                media_type=?,
                updated_at=?,
                raw_json=?
            where id=?
            """,
            (
                contract.get("library_root"),
                contract.get("library_path"),
                contract.get("library_path_template"),
                contract.get("library_path_source"),
                contract.get("library_adapter_path"),
                media_type,
                now,
                json_dumps(raw),
                row["id"],
            ),
        )
        updated += int(cur.rowcount or 0)
    return updated


def sync_state(state_dir, db_path=None, *, retire_absent_json=False):
    def _sync():
        state = Path(state_dir)
        path = Path(db_path or db_path_for_state_dir(state))
        state.mkdir(parents=True, exist_ok=True)
        now = time.time()
        source = state_source_snapshot(state)
        import_status_sync = None
        with connect(path, autocommit=True) as con:
            init_schema(con)
            watchdog = queue_watchdog_policy(con)
            watch_count = sync_watches(con, state, now)
            queue_count = sync_queue(con, state, now, retire_absent_json=retire_absent_json)
            import_status_sync = sync_import_status_sources(con, state, now)
            counts = {
                "watches": watch_count,
                "queue_items": queue_count,
                "imports": import_status_sync["count"],
            }
            counts["series_history"] = backfill_series_history(con)
            counts["download_reconciliation"] = sync_download_reconciliation(con, state, now)
            counts["download_tasks"] = backfill_download_tasks_from_attempts(con)
            counts["provider_contract_backfill"] = backfill_provider_contract_fields(con)
            counts["series_path_contracts"] = backfill_series_path_contracts(con, now)
            counts["superseded_download_tasks_retired"] = cleanup_superseded_active_download_tasks(con, now)
            counts["superseded_sent_download_tasks_retired"] = cleanup_superseded_sent_download_tasks(con, now)
            counts["local_pack_superseded_handoff_tasks_retired"] = cleanup_local_pack_superseded_download_client_tasks(con, now)
            counts["queue_watchdog"] = watchdog
            counts["stale_download_client_handoff_tasks_retired"] = (
                cleanup_stale_download_client_handoff_tasks(con, now, watchdog["handoff_stale_seconds"])
                if watchdog["enabled"] else 0
            )
            counts["stale_active_slskd_download_tasks_retired"] = (
                cleanup_stale_active_slskd_download_tasks(
                    con,
                    now,
                    watchdog["slskd_stale_seconds"],
                    watchdog["slskd_never_started_stale_seconds"],
                )
                if watchdog["enabled"] else 0
            )
            counts["stale_download_task_bad_candidates"] = sync_stale_download_task_bad_candidates(con, now)
            counts["retired_download_queue_items_requeued"] = cleanup_queue_items_with_retired_download_tasks(con, now)
            counts["superseded_slskd_queue_active_download_tasks_retired"] = cleanup_superseded_slskd_queue_active_download_tasks(con, now)
            counts["duplicate_active_handoff_tasks_retired"] = cleanup_duplicate_active_handoff_download_tasks(con, now)
            counts["inactive_download_tasks_retired"] = cleanup_inactive_active_download_tasks(con, now)
            counts["duplicate_download_tasks_removed"] = cleanup_duplicate_download_tasks(con)
            counts["stale_slskd_wrong_title_bad_candidates"] = sync_stale_slskd_wrong_title_bad_candidates(con, now)
            counts["download_task_history"] = backfill_download_task_history(con)
            counts["import_source_attempt_links"] = backfill_import_source_attempt_links(con)
            counts["superseded_adapter_import_results"] = cleanup_superseded_adapter_import_results(con, now)
            counts["missing_folder_import_proofs_retracted"] = cleanup_missing_folder_verified_import_proofs(con, now)
            counts["wrong_unit_page_pack_import_proofs_retracted"] = cleanup_wrong_unit_page_pack_import_proofs(con, now)
            counts["contradictory_completion_provenance_retracted"] = cleanup_contradictory_completion_provenance(con, now)
            counts["history_event_activity"] = backfill_history_event_activity_columns(con, limit=5000)
            counts["active_download_queue_settled"] = settle_queue_items_with_active_download_tasks(con, now)
            counts["stale_download_client_searching_cleared"] = (
                cleanup_stale_download_client_searching_queue_rows(con, now, watchdog["retry_delay_seconds"])
                if watchdog["enabled"] else 0
            )
            counts["retryable_source_candidate_searching_requeued"] = cleanup_retryable_source_candidate_searching_queue_rows(con, now)
            counts["verified_import_queue_settled"] = settle_queue_items_with_verified_imports(con, now)
            counts["verified_queue_wanted_reconciled"] = reconcile_verified_queue_wanted_statuses(con, now)
            counts["duplicate_issue_wanted_reconciled"] = reconcile_duplicate_issue_number_wanted_statuses(con, now)
            counts["queue_scheduler_evidence_backfilled"] = backfill_queue_scheduler_evidence_fields(con, now)
            counts["metadata_only_wanted_queued"] = reconcile_monitored_metadata_only_wanted(con, now)
            counts["retired_duplicate_wanted_reenrolled"] = reconcile_retired_duplicate_wanted_enrollment(con, now)
            counts["folder_presence_backfill"] = backfill_existing_folder_presence_import_results(con, now)
            counts["folder_presence_wanted_backfill"] = backfill_existing_folder_presence_wanted_items(con, now)
            counts["collection_single_part_verified_reopened"] = cleanup_collection_single_part_verified_queue_rows(con, now)
            counts["superseded_duplicates"] = supersede_duplicate_queue_items(con, now)
            counts["duplicate_verified_activity_attempts_removed"] = cleanup_duplicate_verified_activity_attempts(con)
            counts["media_files"] = sync_managed_media_files(con, now)
            update_sync_meta(con, now, "full", source.get("source_mtime"))
            con.commit()
        counts["import_status_events"] = retire_import_status_events(import_status_sync["events"])
        counts["rejected_import_status_events"] = len(import_status_sync["rejected"])
        summary = state_summary(path)
        summary.update(source)
        summary.update({
            "ok": True,
            "db_path": str(path),
            "synced": counts,
            "retire_absent_json": bool(retire_absent_json),
            "synced_at": now,
            "synced_at_iso": utc_stamp(now),
        })
        return summary

    return with_db_lock_retry(_sync, attempts=4, initial_delay=1.0)



MANGADEX_SUPERSEDED_DEFAULT_CONTENT_RATINGS = ["safe", "suggestive"]
MANGADEX_UPGRADED_DEFAULT_CONTENT_RATINGS = ["safe", "suggestive", "erotica"]


def upgrade_mangadex_default_content_ratings(con):
    """One-shot: carry the corrected MangaDex rating default onto existing installs.

    The old default excluded ``erotica``, which is stricter than MangaDex's own API
    default and hid acclaimed titles outright -- Berserk is rated erotica, so it
    returned no results at all. Changing the fallback was not enough: first-run
    seeding persists the value into provider_configs, so every existing install
    keeps the old list forever and stays broken. Verified on production, where the
    corrected build still searched with ["safe", "suggestive"].

    Only a value that is *exactly* the superseded default is touched, because that
    is indistinguishable from never having chosen. The schema_meta guard makes this
    run once per database, so an operator who deliberately narrows the list back
    afterwards keeps their choice.
    """
    try:
        done = con.execute(
            "select value from schema_meta where key='mangadex_content_ratings_erotica_default'"
        ).fetchone()
    except sqlite3.Error:
        return
    if done and str(done["value"] if not isinstance(done, tuple) else done[0]) == "1":
        return
    try:
        row = con.execute(
            "select settings_json from provider_configs where id='mangadex'"
        ).fetchone()
    except sqlite3.Error:
        return
    if row is not None:
        raw = row["settings_json"] if not isinstance(row, tuple) else row[0]
        settings = json_loads(raw or "{}", {})
        if isinstance(settings, dict):
            current = settings.get("content_ratings")
            if isinstance(current, list) and [str(v) for v in current] == MANGADEX_SUPERSEDED_DEFAULT_CONTENT_RATINGS:
                settings["content_ratings"] = list(MANGADEX_UPGRADED_DEFAULT_CONTENT_RATINGS)
                try:
                    con.execute(
                        "update provider_configs set settings_json=? where id='mangadex'",
                        (json_dumps(settings),),
                    )
                except sqlite3.Error:
                    return
    try:
        con.execute(
            "insert into schema_meta(key,value) values('mangadex_content_ratings_erotica_default','1') "
            "on conflict(key) do update set value='1'"
        )
    except sqlite3.Error:
        pass

def update_sync_meta(con, now, scope="full", source_mtime=None):
    # Every write that matters to the summaries stamps its sync here -- adding
    # a series, finishing a queue or import sync, replacing metadata. Dropping
    # the cached summaries at this one seam means a caller that just wrote
    # reports what it wrote, without every writer having to remember to opt
    # out. Doing it before the commit is deliberate: if the transaction later
    # rolls back the only cost is one extra rebuild, whereas invalidating
    # afterwards would leave a window serving pre-write numbers.
    clear_state_view_summary_cache()
    con.execute(
        "insert into schema_meta(key, value) values('last_sync_at', ?) "
        "on conflict(key) do update set value=excluded.value",
        (str(now),),
    )
    con.execute(
        "insert into schema_meta(key, value) values('last_sync_at_iso', ?) "
        "on conflict(key) do update set value=excluded.value",
        (utc_stamp(now),),
    )
    con.execute(
        "insert into schema_meta(key, value) values('last_sync_scope', ?) "
        "on conflict(key) do update set value=excluded.value",
        (str(scope or "unknown"),),
    )
    if source_mtime:
        con.execute(
            "insert into schema_meta(key, value) values('last_source_mtime', ?) "
            "on conflict(key) do update set value=excluded.value",
            (str(source_mtime),),
        )
        con.execute(
            "insert into schema_meta(key, value) values('last_source_mtime_iso', ?) "
            "on conflict(key) do update set value=excluded.value",
            (utc_stamp(source_mtime),),
        )


def sync_state_if_stale(state_dir, db_path=None, max_age_seconds=45):
    state_dir = Path(state_dir)
    db_path = Path(db_path or db_path_for_state_dir(state_dir))
    source = state_source_snapshot(state_dir)
    # Never decide whether to WRITE from a cached read. This function compares
    # last_sync_at against max_age_seconds; served from a 60s cache, that value
    # goes on ageing after a sync has already refreshed it, so every call for
    # the rest of the TTL saw a stale age, decided a sync was due, and ran a
    # real write sync -- which then did not invalidate the cache either. A
    # cache meant to remove load became a generator of it, against a database
    # already under write-lock pressure.
    summary = state_summary(db_path, use_cache=False)
    if not summary.get("ok"):
        refreshed = sync_state(state_dir, db_path)
        refreshed["auto_synced"] = True
        refreshed["auto_sync_reason"] = summary.get("reason") or "state_unavailable"
        refreshed["state_age_seconds"] = 0
        refreshed["state_stale"] = False
        return refreshed

    now = time.time()
    last_sync = safe_float(summary.get("last_sync_at"))
    source_mtime = safe_float(source.get("source_mtime"))
    age = max(0.0, now - last_sync) if last_sync else None
    source_changed = bool(source_mtime and (not last_sync or source_mtime > last_sync + 0.001))
    age_stale = bool(max_age_seconds and age is not None and age > max_age_seconds)
    never_synced = not bool(last_sync)
    if never_synced or source_changed or age_stale:
        reason = "never_synced" if never_synced else ("source_changed" if source_changed else "age")
        if never_synced:
            refreshed = sync_state(state_dir, db_path)
        else:
            refreshed = sync_queue_state(
                state_dir,
                db_path,
                mode="queue" if source_changed else "maintenance",
                include_summary=True,
                timeout_seconds=5.0,
                busy_timeout_ms=5000,
                lock_attempts=1,
            )
        refreshed["auto_synced"] = True
        refreshed["auto_sync_reason"] = reason
        refreshed["state_age_seconds"] = 0
        refreshed["state_stale"] = False
        return refreshed

    summary.update(source)
    summary["auto_synced"] = False
    summary["auto_sync_reason"] = "fresh"
    summary["state_age_seconds"] = age
    summary["state_stale"] = False
    return summary


NONREPLACEABLE_ARTIFACT_SAFETY_KEYS = {
    "known_bad",
    "malicious",
    "invalid_archive",
    "bad_archive",
    "corrupt_archive",
    "preview",
    "sample",
    "duplicate",
    "unsafe_locator",
}
NONREPLACEABLE_ARTIFACT_SAFETY_PATTERN = re.compile(
    r"(?:known[_ -]?bad|malicious|invalid[_ -]?archive|bad[_ -]?archive|"
    r"corrupt[_ -]?archive|preview|sample|duplicate|unsafe[_ -]?locator)",
    re.I,
)
NONREPLACEABLE_ARTIFACT_TEXT_KEYS = {
    "status",
    "state",
    "outcome",
    "decision",
    "verdict",
    "reason",
    "failure_reason",
    "artifact_status",
    "archive_status",
    "block_reason",
    "block_reasons",
}


def raw_has_nonreplaceable_artifact_safety_evidence(raw):
    raw = raw if isinstance(raw, dict) else {}
    safety_stack = [raw]
    while safety_stack:
        current = safety_stack.pop()
        if isinstance(current, dict):
            for key, value in current.items():
                key_text = str(key or "").strip().lower()
                if key_text.startswith(("previous_", "prior_", "history_")):
                    continue
                if key_text in NONREPLACEABLE_ARTIFACT_SAFETY_KEYS and boolish(value, False):
                    return True
                if key_text in NONREPLACEABLE_ARTIFACT_TEXT_KEYS:
                    values = value if isinstance(value, list) else [value]
                    if any(
                        NONREPLACEABLE_ARTIFACT_SAFETY_PATTERN.search(str(item or ""))
                        for item in values
                        if not isinstance(item, (dict, list))
                    ):
                        return True
                if isinstance(value, (dict, list)):
                    safety_stack.append(value)
        elif isinstance(current, list):
            safety_stack.extend(value for value in current if isinstance(value, (dict, list)))
    return False


def folder_presence_has_negative_import_proof(con, queue_id, issue_id, dest_path):
    dest_key = media_file_normalized_path(dest_path)
    if not dest_key:
        return False
    rows = con.execute(
        """
        select status, verified, dest_path, raw_json
        from import_results
        where (queue_id=? or issue_id=?)
          and coalesce(dest_path, '') <> ''
        """,
        (queue_id, issue_id),
    ).fetchall()
    for row in rows:
        if media_file_normalized_path(row_value(row, "dest_path")) != dest_key:
            continue
        status = str(row_value(row, "status") or "").strip().lower()
        raw = json_loads(row_value(row, "raw_json") or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        if raw_has_nonreplaceable_artifact_safety_evidence(raw):
            return True
        artifact_acceptance = raw.get("artifact_acceptance") if isinstance(raw.get("artifact_acceptance"), dict) else {}
        raw_decision = str(
            raw.get("edition_completion_guard")
            or raw.get("skip_reason")
            or artifact_acceptance.get("decision")
            or ""
        ).strip().lower()
        negative_text = f"{status} {raw_decision}"
        if not int(row_value(row, "verified") or 0) and any(
            token in negative_text
            for token in ("wrong_unit", "single_part_file", "artifact_acceptance_rejected", "rejected_wrong_unit")
        ):
            # A user/provider may replace the rejected chapter in place. Fresh,
            # authoritative volume evidence supersedes a stale path-only
            # rejection; chapter or ambiguous content remains blocked.
            current_semantics = inkdrop_artifact_acceptance.archive_member_semantics(dest_path, fresh=True)
            current_unit = str(current_semantics.get("semantic_unit") or "").strip().lower()
            authoritative_volume_replacement = current_unit in {"volume", "multi_chapter_archive"}
            return not authoritative_volume_replacement
    return False


def managed_media_issue_file_presence(con, queue_id, series_row, issue_row, managed_roots=None):
    """Return strict current file proof already bound to this exact issue.

    Callers looping over thousands of rows pass managed_roots resolved once:
    resolving them here cost four settings reads per row -- ten thousand of
    the pass's twelve and a half thousand statements, measured live."""
    series_row = dict(series_row or {})
    issue_row = dict(issue_row or {})
    series_id = str(series_row.get("id") or "").strip()
    issue_id = str(issue_row.get("id") or "").strip()
    if not series_id or not issue_id:
        return {"checked": False, "present": False, "source": "managed_media_unchecked"}
    if managed_roots is None:
        managed_roots = media_management_roots_from_connection(con)
    rows = con.execute(
        """
        select id, queue_id, path, normalized_path, status, active,
               completion_truth, folder_imported, raw_json
        from media_files
        where series_id=? and issue_id=? and active=1
        order by coalesce(last_seen_at, first_seen_at, 0) desc, id desc
        """,
        (series_id, issue_id),
    ).fetchall()
    for row in rows:
        status = str(row_value(row, "status") or "").strip().lower()
        if status not in {"present", "verified", "folder_verified", "library_visible"}:
            continue
        if not (
            str(row_value(row, "completion_truth") or "").strip().lower() == "folder"
            or int(row_value(row, "folder_imported") or 0)
        ):
            continue
        path = str(row_value(row, "path") or "").strip()
        if not path or not path_under_any_root(path, managed_roots):
            continue
        try:
            if not Path(path).is_file():
                continue
        except OSError:
            continue
        raw = json_loads(row_value(row, "raw_json") or "{}", {})
        if raw_has_nonreplaceable_artifact_safety_evidence(raw):
            return {
                "checked": True,
                "present": False,
                "missing_confirmed": False,
                "blocked": True,
                "source": "managed_media_unsafe_evidence",
                "media_file_id": row_value(row, "id"),
            }
        if folder_presence_has_negative_import_proof(con, queue_id, issue_id, path):
            continue
        semantic_guard = managed_folder_artifact_semantic_guard(path, series_row, issue_row)
        if not semantic_guard.get("compatible"):
            continue
        result = readiness_managed_path_payload(
            path,
            source="managed_media_exact_issue",
            confidence="high",
            match_reason="exact_managed_media_identity",
        )
        result["media_file_id"] = row_value(row, "id")
        result["media_queue_id"] = row_value(row, "queue_id")
        result["semantic_guard"] = semantic_guard
        return result
    return {
        "checked": True,
        "present": False,
        "missing_confirmed": False,
        "source": "managed_media_no_safe_match",
    }


def backfill_existing_folder_presence_import_results(
    con,
    now=None,
    limit=2500,
    apply_limit=250,
    *,
    after_queue_id="",
    return_progress=False,
):
    """Mark active queued issues complete when their archive already exists.

    This is the folder-first bridge for adapter/native drift: if InkDrop has a
    queued issue but the matching archive is already in either the native
    managed series folder or the legacy adapter folder, the queue should settle
    as folder-verified instead of continuing to search.
    """
    now = float(now or time.time())
    limit = max(1, min(int(limit or 500), 5000))
    apply_limit = max(1, min(int(apply_limit or 250), 1000))
    cursor = str(after_queue_id or "") if return_progress else ""
    query = """
        select q.id as queue_id, q.wanted_id, q.series_id, q.issue_id,
               q.state as queue_state, q.current_source, q.last_event,
               q.raw_json as queue_raw_json,
               w.status as wanted_status,
               s.title as series_title, s.media_type as series_media_type,
               s.year as series_year, s.publisher as series_publisher,
               s.metadata_provider as series_metadata_provider,
               s.metadata_id as series_metadata_id,
               s.source as series_source,
               s.library_root, s.library_path, s.library_adapter_path,
               i.issue_number, i.normalized_number, i.title as issue_title,
               i.release_date, i.metadata_provider as issue_metadata_provider,
               i.metadata_id as issue_metadata_id
        from queue_items q
        join series s on s.id = q.series_id
        join issues i on i.id = q.issue_id
        left join wanted_items w on w.id = q.wanted_id
        where q.active = 1
          and lower(coalesce(q.state,'')) in ('queued','searching','source_wait','downloading','importing','failed','blocked')
          and not exists (
              select 1
              from import_results ir
              where ir.queue_id = q.id
                and (
                    coalesce(ir.verified, 0) = 1
                    or coalesce(ir.folder_imported, 0) = 1
                    or lower(coalesce(ir.status,'')) in ('verified','folder_verified','library_visible','kavita_verified')
                    or lower(coalesce(ir.completion_truth,'')) = 'folder'
                )
          )
    """
    params = []
    if cursor:
        query += " and q.id > ?"
        params.append(cursor)
    query += (
        " order by q.id asc"
        if return_progress
        else " order by coalesce(q.updated_at, q.created_at, 0) asc, q.id"
    )
    query += " limit ?"
    params.append(limit)
    rows = con.execute(query, params).fetchall()
    if not rows and cursor:
        return backfill_existing_folder_presence_import_results(
            con,
            now,
            limit=limit,
            apply_limit=apply_limit,
            after_queue_id="",
            return_progress=return_progress,
        )
    checked = 0
    verified = 0
    skipped = 0
    managed_folder_cache = {}
    pass_started = time.time()
    budget_stopped = False
    # A pass that stops before processing anything must keep its place in the
    # ring -- resetting to the head would recreate the head-rescan starvation
    # under sustained budget pressure.
    last_processed_queue_id = cursor
    pass_managed_roots = media_management_roots_from_connection(con)
    for row in rows:
        if time.time() - pass_started > FOLDER_PRESENCE_BACKFILL_PASS_BUDGET_SECONDS:
            # Stop, don't starve: rows verified so far keep their proofs when
            # the sync commits and drop out of the active set; the rest are
            # simply re-eligible next pass.
            budget_stopped = True
            break
        last_processed_queue_id = str(row["queue_id"] or "")
        series_row = {
            "id": row["series_id"],
            "title": row["series_title"],
            "media_type": row["series_media_type"],
            "year": row["series_year"],
            "publisher": row["series_publisher"],
            "metadata_provider": row["series_metadata_provider"],
            "metadata_id": row["series_metadata_id"],
            "source": row["series_source"],
            "library_root": row["library_root"],
            "library_path": row["library_path"],
            "library_adapter_path": row["library_adapter_path"],
        }
        issue_row = {
            "id": row["issue_id"],
            "issue_number": row["issue_number"],
            "normalized_number": row["normalized_number"],
            "title": row["issue_title"],
            "release_date": row["release_date"],
            "metadata_provider": row["issue_metadata_provider"],
            "metadata_id": row["issue_metadata_id"],
        }
        presence = managed_media_issue_file_presence(
            con,
            row["queue_id"],
            series_row,
            issue_row,
            managed_roots=pass_managed_roots,
        )
        if not presence.get("present") and not presence.get("blocked"):
            presence = managed_folder_issue_file_presence(
                series_row,
                issue_row,
                managed_folder_cache=managed_folder_cache,
            )
        checked += 1
        if not presence.get("present"):
            skipped += 1
            continue
        dest_path = str(presence.get("path") or "").strip()
        if not dest_path:
            skipped += 1
            continue
        if folder_presence_has_negative_import_proof(con, row["queue_id"], row["issue_id"], dest_path):
            skipped += 1
            continue
        source = "folder_presence"
        status = "folder_verified"
        imported_count = 1
        completion_evidence = import_result_completion_evidence(
            status,
            True,
            imported_count,
            dest_path,
            "folder",
            False,
            folder_path_exists=True,
        )
        source_attempt_id = latest_source_attempt_id_for_queue(con, row["queue_id"], now, source=source)
        import_id = stable_id("folder_presence_import_result", row["queue_id"], dest_path)
        payload = {
            "kind": "folder_presence_backfill",
            "source": source,
            "queue_id": row["queue_id"],
            "wanted_id": row["wanted_id"],
            "series_id": row["series_id"],
            "issue_id": row["issue_id"],
            "source_attempt_id": source_attempt_id,
            "source_path": dest_path,
            "dest_path": dest_path,
            "status": status,
            "verified": True,
            "outcome": "complete",
            "display_phase": "verified",
            **completion_evidence,
            "presence": presence,
            "recorded_at": now,
            "recorded_at_iso": utc_stamp(now),
        }
        con.execute(
            """
            insert into import_results(
                id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
                status, outcome, display_phase, completion_truth, folder_imported,
                library_visibility_required, library_visibility_status, library_visibility_provider,
                verified, imported_count, skipped_count, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(id) do update set
                source_attempt_id=coalesce(excluded.source_attempt_id, import_results.source_attempt_id),
                source_path=excluded.source_path,
                dest_path=excluded.dest_path,
                status=excluded.status,
                outcome=excluded.outcome,
                display_phase=excluded.display_phase,
                completion_truth=excluded.completion_truth,
                folder_imported=excluded.folder_imported,
                library_visibility_required=excluded.library_visibility_required,
                library_visibility_status=excluded.library_visibility_status,
                library_visibility_provider=excluded.library_visibility_provider,
                verified=excluded.verified,
                imported_count=excluded.imported_count,
                skipped_count=excluded.skipped_count,
                created_at=excluded.created_at,
                raw_json=excluded.raw_json
            """,
            (
                import_id,
                row["queue_id"],
                source_attempt_id,
                row["series_id"],
                row["issue_id"],
                dest_path,
                dest_path,
                status,
                "complete",
                "verified",
                completion_evidence["completion_truth"],
                1 if completion_evidence["folder_imported"] else 0,
                1 if completion_evidence["library_visibility_required"] else 0,
                completion_evidence["library_visibility_status"],
                completion_evidence["library_visibility_provider"],
                1,
                imported_count,
                0,
                now,
                json_dumps(payload),
            ),
        )
        if not verified_import_for_queue(
            con,
            row["queue_id"],
            row["series_id"],
            row["issue_id"],
            require_existing_destination=True,
        ):
            con.execute(
                "update import_results set verified=0,status='verification_pending',outcome='pending',display_phase='importing' where id=?",
                (import_id,),
            )
            skipped += 1
            continue
        queue_raw = json_loads(row["queue_raw_json"] or "{}", {})
        queue_raw = queue_raw if isinstance(queue_raw, dict) else {}
        message = "Existing managed folder file verified; automatic search no longer needed"
        queue_raw.update(
            {
                "state": "verified",
                "current_source": source,
                "last_event": message,
                "last_import_source": source,
                "last_import_source_path": dest_path,
                "last_import_dest": dest_path,
                "last_import_status": status,
                "last_import_outcome": "complete",
                "last_import_display_phase": "verified",
                "last_import_verified": True,
                "last_import_completion_truth": completion_evidence["completion_truth"],
                "last_import_folder_imported": completion_evidence["folder_imported"],
                "last_library_visibility_required": completion_evidence["library_visibility_required"],
                "last_library_visibility_status": completion_evidence["library_visibility_status"],
                "last_library_visibility_provider": completion_evidence["library_visibility_provider"],
                "folder_presence_backfilled_at": now,
                "folder_presence_backfilled_at_iso": utc_stamp(now),
                "folder_presence_match": presence,
            }
        )
        if not mark_queue_verified_for_import(
            con,
            row["queue_id"],
            row["wanted_id"],
            now,
            message=message,
            current_source=source,
        ):
            skipped += 1
            continue
        con.execute("update queue_items set raw_json=? where id=?", (json_dumps(queue_raw), row["queue_id"]))
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("folder_presence_import_result_history", import_id, status),
                "import_result",
                import_id,
                row["series_id"],
                row["issue_id"],
                "folder_presence_import_result",
                source,
                message,
                "complete",
                "verified",
                now,
                json_dumps(payload),
            ),
        )
        verified += 1
        if verified >= apply_limit:
            budget_stopped = True
            break
    result = {"checked": checked, "verified": verified, "skipped": skipped, "apply_limit": apply_limit}
    if return_progress:
        if budget_stopped:
            # The wall-clock budget stopped the pass mid-window: resume at the
            # last row actually processed, or the rotation would silently skip
            # every unprocessed row in the fetched window.
            result["cursor"] = last_processed_queue_id
        else:
            result["cursor"] = rows[-1]["queue_id"] if len(rows) >= limit else ""
    return result


def backfill_existing_folder_presence_wanted_items(con, now=None, limit=2500, apply_limit=250):
    """Satisfy wanted rows when the matching archive is already on disk.

    Queue backfill only sees active queue rows. Some rows become plain wanted
    state after an adapter split, duplicate retirement, or a stale queue handoff;
    those should still settle if the managed folder already contains the issue.
    """
    now = float(now or time.time())
    limit = max(1, min(int(limit or 500), 5000))
    apply_limit = max(1, min(int(apply_limit or 250), 1000))
    rows = con.execute(
        """
        select w.id as wanted_id, w.series_id, w.issue_id,
               w.status as wanted_status, w.raw_json as wanted_raw_json,
               s.title as series_title, s.media_type as series_media_type,
               s.year as series_year, s.publisher as series_publisher,
               s.metadata_provider as series_metadata_provider,
               s.metadata_id as series_metadata_id,
               s.source as series_source,
               s.library_root, s.library_path, s.library_adapter_path,
               i.issue_number, i.normalized_number, i.title as issue_title,
               i.release_date, i.metadata_provider as issue_metadata_provider,
               i.metadata_id as issue_metadata_id
        from wanted_items w
        join series s on s.id = w.series_id
        join issues i on i.id = w.issue_id
        where lower(coalesce(w.status,'')) in ('wanted','queued','searching','retry','missing')
          and not exists (
              select 1
              from queue_items q
              where q.wanted_id = w.id
                and q.active = 1
          )
          and not exists (
              select 1
              from import_results ir
              where ir.issue_id = w.issue_id
                and (
                    coalesce(ir.verified, 0) = 1
                    or coalesce(ir.folder_imported, 0) = 1
                    or lower(coalesce(ir.status,'')) in ('verified','folder_verified','library_visible','kavita_verified')
                    or lower(coalesce(ir.completion_truth,'')) = 'folder'
                )
          )
        order by coalesce(w.updated_at, w.created_at, 0) asc, w.id
        limit ?
        """,
        (limit,),
    ).fetchall()
    pass_managed_roots = media_management_roots_from_connection(con)
    checked = 0
    verified = 0
    skipped = 0
    managed_folder_cache = {}
    pass_started = time.time()
    for row in rows:
        if time.time() - pass_started > FOLDER_PRESENCE_BACKFILL_PASS_BUDGET_SECONDS:
            break
        series_row = {
            "id": row["series_id"],
            "title": row["series_title"],
            "media_type": row["series_media_type"],
            "year": row["series_year"],
            "publisher": row["series_publisher"],
            "metadata_provider": row["series_metadata_provider"],
            "metadata_id": row["series_metadata_id"],
            "source": row["series_source"],
            "library_root": row["library_root"],
            "library_path": row["library_path"],
            "library_adapter_path": row["library_adapter_path"],
        }
        issue_row = {
            "id": row["issue_id"],
            "issue_number": row["issue_number"],
            "normalized_number": row["normalized_number"],
            "title": row["issue_title"],
            "release_date": row["release_date"],
            "metadata_provider": row["issue_metadata_provider"],
            "metadata_id": row["issue_metadata_id"],
        }
        # A file already attributed to this exact series and issue settles
        # the wanted row even when folder discovery cannot see its folder --
        # the year-identity rule keeps unqualified folders out of discovery,
        # and without this check every such file would be re-searched and
        # re-downloaded despite being owned and recorded.
        presence = managed_media_issue_file_presence(
            con,
            None,
            series_row,
            issue_row,
            managed_roots=pass_managed_roots,
        )
        if not presence.get("present") and not presence.get("blocked"):
            presence = managed_folder_issue_file_presence(
                series_row,
                issue_row,
                managed_folder_cache=managed_folder_cache,
            )
        checked += 1
        if not presence.get("present"):
            skipped += 1
            continue
        dest_path = str(presence.get("path") or "").strip()
        if not dest_path:
            skipped += 1
            continue
        if folder_presence_has_negative_import_proof(con, None, row["issue_id"], dest_path):
            skipped += 1
            continue
        source = "folder_presence"
        status = "folder_verified"
        completion_evidence = import_result_completion_evidence(
            status,
            True,
            1,
            dest_path,
            "folder",
            False,
            folder_path_exists=True,
        )
        import_id = stable_id("folder_presence_wanted_import_result", row["wanted_id"], dest_path)
        message = "Existing managed folder file verified; wanted row satisfied"
        payload = {
            "kind": "folder_presence_wanted_backfill",
            "source": source,
            "wanted_id": row["wanted_id"],
            "series_id": row["series_id"],
            "issue_id": row["issue_id"],
            "source_path": dest_path,
            "dest_path": dest_path,
            "status": status,
            "verified": True,
            "outcome": "complete",
            "display_phase": "verified",
            **completion_evidence,
            "presence": presence,
            "recorded_at": now,
            "recorded_at_iso": utc_stamp(now),
        }
        con.execute(
            """
            insert into import_results(
                id, queue_id, source_attempt_id, series_id, issue_id, source_path, dest_path,
                status, outcome, display_phase, completion_truth, folder_imported,
                library_visibility_required, library_visibility_status, library_visibility_provider,
                verified, imported_count, skipped_count, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            on conflict(id) do update set
                source_path=excluded.source_path,
                dest_path=excluded.dest_path,
                status=excluded.status,
                outcome=excluded.outcome,
                display_phase=excluded.display_phase,
                completion_truth=excluded.completion_truth,
                folder_imported=excluded.folder_imported,
                library_visibility_required=excluded.library_visibility_required,
                library_visibility_status=excluded.library_visibility_status,
                library_visibility_provider=excluded.library_visibility_provider,
                verified=excluded.verified,
                imported_count=excluded.imported_count,
                skipped_count=excluded.skipped_count,
                created_at=excluded.created_at,
                raw_json=excluded.raw_json
            """,
            (
                import_id,
                None,
                None,
                row["series_id"],
                row["issue_id"],
                dest_path,
                dest_path,
                status,
                "complete",
                "verified",
                completion_evidence["completion_truth"],
                1 if completion_evidence["folder_imported"] else 0,
                1 if completion_evidence["library_visibility_required"] else 0,
                completion_evidence["library_visibility_status"],
                completion_evidence["library_visibility_provider"],
                1,
                1,
                0,
                now,
                json_dumps(payload),
            ),
        )
        proof_row = con.execute("select * from import_results where id=? limit 1", (import_id,)).fetchone()
        if not import_result_strict_completion_valid(con, proof_row, row["series_id"], row["issue_id"], managed_roots=pass_managed_roots):
            con.execute(
                """
                update import_results
                   set status='verification_pending',verified=0,outcome='problem',
                       display_phase='retry_later',completion_truth='',folder_imported=0
                 where id=?
                """,
                (import_id,),
            )
            skipped += 1
            continue
        wanted_raw = json_loads(row["wanted_raw_json"] or "{}", {})
        wanted_raw = wanted_raw if isinstance(wanted_raw, dict) else {}
        wanted_raw.update(
            {
                "status": "satisfied",
                "last_event": message,
                "last_import_source": source,
                "last_import_dest": dest_path,
                "last_import_status": status,
                "last_import_outcome": "complete",
                "last_import_display_phase": "verified",
                "last_import_completion_truth": completion_evidence["completion_truth"],
                "folder_presence_backfilled_at": now,
                "folder_presence_backfilled_at_iso": utc_stamp(now),
                "folder_presence_match": presence,
            }
        )
        con.execute(
            "update wanted_items set status='satisfied', updated_at=?, raw_json=? where id=?",
            (now, json_dumps(wanted_raw), row["wanted_id"]),
        )
        con.execute(
            """
            insert or ignore into history_events(
                id, entity_type, entity_id, series_id, issue_id, event_type,
                source, message, outcome, display_phase, created_at, raw_json
            ) values(?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                stable_id("folder_presence_wanted_import_result_history", import_id, status),
                "import_result",
                import_id,
                row["series_id"],
                row["issue_id"],
                "folder_presence_wanted_import_result",
                source,
                message,
                "complete",
                "verified",
                now,
                json_dumps(payload),
            ),
        )
        verified += 1
        if verified >= apply_limit:
            break
    return {"checked": checked, "verified": verified, "skipped": skipped, "apply_limit": apply_limit}


def sync_queue_state(
    state_dir,
    db_path=None,
    *,
    retire_absent_json=False,
    export_json=False,
    export_reason="sync_queue_state",
    timeout_seconds=None,
    busy_timeout_ms=None,
    lock_attempts=4,
    lock_initial_delay=1.0,
    mode="full",
    include_summary=None,
):
    sync_mode = str(mode or "full").strip().lower()
    if sync_mode not in {"maintenance", "queue", "full"}:
        raise ValueError(f"unsupported queue sync mode: {mode}")
    if include_summary is None:
        include_summary = sync_mode == "full"

    def _sync():
        sync_started = time.perf_counter()
        timings = {}

        def timed(name, callback):
            started = time.perf_counter()
            try:
                return callback()
            finally:
                timings[name] = round(time.perf_counter() - started, 6)

        state = Path(state_dir)
        path = Path(db_path or db_path_for_state_dir(state))
        now = time.time()
        source = state_source_snapshot(state)
        with connect(path, timeout_seconds=timeout_seconds, busy_timeout_ms=busy_timeout_ms, autocommit=True) as con:
            timed("schema", lambda: init_schema(con))
            watchdog = queue_watchdog_policy(con)
            count = timed(
                "queue_ingest",
                lambda: sync_queue(
                    con,
                    state,
                    now,
                    retire_absent_json=retire_absent_json,
                    verify_filesystem=sync_mode == "full",
                    perform_backfills=sync_mode == "full",
                ),
            ) if sync_mode in {"queue", "full"} else 0
            reconciliation_count = timed(
                "download_reconciliation",
                lambda: sync_download_reconciliation(con, state, now),
            ) if sync_mode == "full" else 0
            provider_contract_backfill = timed(
                "provider_contract_backfill",
                lambda: backfill_provider_contract_fields(con),
            ) if sync_mode == "full" else 0
            maintenance_started = time.perf_counter()
            expired_queue_claims_cleaned = cleanup_expired_queue_claims(con, now)
            slskd_candidate_reservations_reconciled = reconcile_slskd_candidate_reservations(con, now)
            superseded_download_tasks_retired = cleanup_superseded_active_download_tasks(con, now)
            superseded_sent_download_tasks_retired = cleanup_superseded_sent_download_tasks(con, now)
            local_pack_superseded_handoff_tasks_retired = cleanup_local_pack_superseded_download_client_tasks(con, now)
            stale_download_client_handoff_tasks_retired = (
                cleanup_stale_download_client_handoff_tasks(con, now, watchdog["handoff_stale_seconds"])
                if watchdog["enabled"] else 0
            )
            stale_download_task_bad_candidates = sync_stale_download_task_bad_candidates(con, now)
            stale_active_slskd_download_tasks_retired = (
                cleanup_stale_active_slskd_download_tasks(
                    con,
                    now,
                    watchdog["slskd_stale_seconds"],
                    watchdog["slskd_never_started_stale_seconds"],
                )
                if watchdog["enabled"] else 0
            )
            wrong_title_active_slskd_download_tasks_retired = cleanup_active_slskd_wrong_title_download_tasks(con, now)
            retired_download_queue_items_requeued = cleanup_queue_items_with_retired_download_tasks(con, now)
            superseded_slskd_queue_active_download_tasks_retired = cleanup_superseded_slskd_queue_active_download_tasks(con, now)
            duplicate_active_handoff_tasks_retired = cleanup_duplicate_active_handoff_download_tasks(con, now)
            inactive_download_tasks_retired = cleanup_inactive_active_download_tasks(con, now)
            download_task_dupes_removed = cleanup_duplicate_download_tasks(con)
            stale_active_queue_display_cleared = cleanup_queue_items_without_active_download_work(con, now)
            non_active_searching_queue_rows_cleared = cleanup_non_active_searching_queue_rows(con, now)
            stale_slskd_wrong_title_bad_candidates = sync_stale_slskd_wrong_title_bad_candidates(con, now)
            stale_download_client_searching_cleared = (
                cleanup_stale_download_client_searching_queue_rows(con, now, watchdog["retry_delay_seconds"])
                if watchdog["enabled"] else 0
            )
            retryable_source_candidate_searching_requeued = cleanup_retryable_source_candidate_searching_queue_rows(con, now)
            timings["queue_maintenance"] = round(time.perf_counter() - maintenance_started, 6)
            integrity_started = time.perf_counter()
            missing_folder_import_proofs_retracted = (
                cleanup_missing_folder_verified_import_proofs(con, now)
                if sync_mode == "full" else 0
            )
            wrong_unit_page_pack_import_proofs_retracted = (
                cleanup_wrong_unit_page_pack_import_proofs(con, now)
                if sync_mode == "full" else 0
            )
            contradictory_completion_provenance_retracted = (
                cleanup_contradictory_completion_provenance(con, now)
                if sync_mode == "full" else 0
            )
            timings["filesystem_integrity"] = round(time.perf_counter() - integrity_started, 6)
            completion_started = time.perf_counter()
            verified_import_settled_count = (
                settle_queue_items_with_verified_imports(con, now)
                if sync_mode != "queue" else 0
            )
            verified_queue_wanted_reconciled = (
                reconcile_verified_queue_wanted_statuses(con, now)
                if sync_mode != "queue" else 0
            )
            duplicate_issue_wanted_reconciled = (
                reconcile_duplicate_issue_number_wanted_statuses(con, now)
                if sync_mode != "queue" else 0
            )
            queue_scheduler_evidence_backfilled = (
                backfill_queue_scheduler_evidence_fields(con, now)
                if sync_mode != "queue" else 0
            )
            metadata_only_wanted_queued = (
                reconcile_monitored_metadata_only_wanted(con, now)
                if sync_mode != "queue" else 0
            )
            retired_duplicate_wanted_reenrolled = (
                reconcile_retired_duplicate_wanted_enrollment(con, now)
                if sync_mode != "queue" else 0
            )
            timings["completion_reconcile"] = round(time.perf_counter() - completion_started, 6)
            folder_presence_started = time.perf_counter()
            folder_presence_backfill = (
                backfill_existing_folder_presence_import_results(con, now)
                if sync_mode == "full" else {"checked": 0, "verified": 0, "skipped": 0, "mode": "skipped"}
            )
            folder_presence_wanted_backfill = (
                backfill_existing_folder_presence_wanted_items(con, now)
                if sync_mode == "full" else {"checked": 0, "verified": 0, "skipped": 0, "mode": "skipped"}
            )
            timings["folder_presence_backfill"] = round(time.perf_counter() - folder_presence_started, 6)
            final_cleanup_started = time.perf_counter()
            collection_single_part_verified_reopened = cleanup_collection_single_part_verified_queue_rows(con, now)
            superseded_count = supersede_duplicate_queue_items(con, now)
            verification_dupes_removed = (
                cleanup_duplicate_verified_activity_attempts(con)
                if sync_mode == "full" else 0
            )
            repeated_retry_source_attempts_coalesced = cleanup_repeated_automatic_retry_source_attempts(con, now)
            timings["final_cleanup"] = round(time.perf_counter() - final_cleanup_started, 6)
            media_files = timed(
                "managed_media_inventory",
                lambda: sync_managed_media_files(con, now),
            ) if sync_mode == "full" else {"checked": 0, "upserted": 0, "missing": 0, "mode": "skipped"}
            update_sync_meta(con, now, f"queue_{sync_mode}", source.get("source_mtime"))
            timed("commit", con.commit)
        export_result = (
            export_series_autopilot_queue_json(state, path, reason=export_reason)
            if export_json
            else {"ok": True, "skipped": True, "reason": "export_json_false"}
        )
        summary = timed("state_summary", lambda: state_summary(path)) if include_summary else {
            "ok": True,
            "db_path": str(path),
        }
        summary.update(source)
        timings["total"] = round(time.perf_counter() - sync_started, 6)
        summary.update({
            "ok": True,
            "db_path": str(path),
            "sync_mode": sync_mode,
            "timings": timings,
            "synced": {
                "queue_watchdog": watchdog,
                "expired_queue_claims_cleaned": expired_queue_claims_cleaned,
                "slskd_candidate_reservations_reconciled": slskd_candidate_reservations_reconciled,
                "queue_items": count,
                "download_reconciliation": reconciliation_count,
                "provider_contract_backfill": provider_contract_backfill,
                "superseded_download_tasks_retired": superseded_download_tasks_retired,
                "superseded_sent_download_tasks_retired": superseded_sent_download_tasks_retired,
                "local_pack_superseded_handoff_tasks_retired": local_pack_superseded_handoff_tasks_retired,
                "stale_download_client_handoff_tasks_retired": stale_download_client_handoff_tasks_retired,
                "stale_download_task_bad_candidates": stale_download_task_bad_candidates,
                "stale_active_slskd_download_tasks_retired": stale_active_slskd_download_tasks_retired,
                "wrong_title_active_slskd_download_tasks_retired": wrong_title_active_slskd_download_tasks_retired,
                "retired_download_queue_items_requeued": retired_download_queue_items_requeued,
                "superseded_slskd_queue_active_download_tasks_retired": superseded_slskd_queue_active_download_tasks_retired,
                "duplicate_active_handoff_tasks_retired": duplicate_active_handoff_tasks_retired,
                "inactive_download_tasks_retired": inactive_download_tasks_retired,
                "duplicate_download_tasks_removed": download_task_dupes_removed,
                "stale_active_queue_display_cleared": stale_active_queue_display_cleared,
                "non_active_searching_queue_rows_cleared": non_active_searching_queue_rows_cleared,
                "stale_slskd_wrong_title_bad_candidates": stale_slskd_wrong_title_bad_candidates,
                "stale_download_client_searching_cleared": stale_download_client_searching_cleared,
                "retryable_source_candidate_searching_requeued": retryable_source_candidate_searching_requeued,
                "missing_folder_import_proofs_retracted": missing_folder_import_proofs_retracted,
                "wrong_unit_page_pack_import_proofs_retracted": wrong_unit_page_pack_import_proofs_retracted,
                "contradictory_completion_provenance_retracted": contradictory_completion_provenance_retracted,
                "verified_import_queue_settled": verified_import_settled_count,
                "verified_queue_wanted_reconciled": verified_queue_wanted_reconciled,
                "duplicate_issue_wanted_reconciled": duplicate_issue_wanted_reconciled,
                "queue_scheduler_evidence_backfilled": queue_scheduler_evidence_backfilled,
                "metadata_only_wanted_queued": metadata_only_wanted_queued,
                "retired_duplicate_wanted_reenrolled": retired_duplicate_wanted_reenrolled,
                "folder_presence_backfill": folder_presence_backfill,
                "folder_presence_wanted_backfill": folder_presence_wanted_backfill,
                "collection_single_part_verified_reopened": collection_single_part_verified_reopened,
                "superseded_duplicates": superseded_count,
                "duplicate_verified_activity_attempts_removed": verification_dupes_removed,
                "repeated_retry_source_attempts_coalesced": repeated_retry_source_attempts_coalesced,
                "media_files": media_files,
            },
            "retire_absent_json": bool(retire_absent_json),
            "export_json": bool(export_json),
            "export": export_result,
            "synced_at": now,
            "synced_at_iso": utc_stamp(now),
        })
        return summary

    return with_db_lock_retry(_sync, attempts=lock_attempts, initial_delay=lock_initial_delay)


def readiness_check(check_id, label, state, detail="", next_action="", metric=None):
    state = str(state or "watch").strip().lower()
    if state not in {"ready", "watch", "gap"}:
        state = "watch"
    tone = "good" if state == "ready" else ("bad" if state == "gap" else "warn")
    return {
        "id": check_id,
        "label": label,
        "state": state,
        "tone": tone,
        "detail": detail,
        "next_action": next_action,
        "metric": metric,
    }


def standalone_readiness_audit(
    *,
    native_series=0,
    adapter_series=0,
    manual_series=0,
    issues=0,
    wanted_items=0,
    queue_items=0,
    active_queue_items=0,
    queue_work_items=0,
    queue_exception_items=0,
    queue_backlog_items=0,
    queue_backlog_no_candidate_items=0,
    queue_backlog_retry_pressure_items=0,
    source_attempts=0,
    download_tasks=0,
    import_results=0,
    history_events=0,
    provider_configs=0,
    app_settings=0,
    manual_review_actionable_count=0,
    manual_review_parked_count=0,
):
    native_series = int(native_series or 0)
    adapter_series = int(adapter_series or 0)
    manual_series = int(manual_series or 0)
    issues = int(issues or 0)
    wanted_items = int(wanted_items or 0)
    queue_items = int(queue_items or 0)
    active_queue_items = int(active_queue_items or 0)
    queue_work_items = int(queue_work_items or 0)
    queue_exception_items = int(queue_exception_items or 0)
    queue_backlog_items = int(queue_backlog_items or 0)
    queue_backlog_no_candidate_items = int(queue_backlog_no_candidate_items or 0)
    queue_backlog_retry_pressure_items = int(queue_backlog_retry_pressure_items or 0)
    source_attempts = int(source_attempts or 0)
    download_tasks = int(download_tasks or 0)
    import_results = int(import_results or 0)
    history_events = int(history_events or 0)
    provider_configs = int(provider_configs or 0)
    app_settings = int(app_settings or 0)
    manual_review_actionable_count = int(manual_review_actionable_count or 0)
    manual_review_parked_count = int(manual_review_parked_count or 0)
    checks = []
    checks.append(
        readiness_check(
            "native_series",
            "Native Series",
            "ready" if native_series and adapter_series == 0 else ("watch" if native_series else "gap"),
            f"{native_series} native; {adapter_series} adapter; {manual_series} manual",
            "Move remaining adapter-backed series into InkDrop ownership." if adapter_series else "InkDrop owns current series metadata.",
            native_series,
        )
    )
    checks.append(
        readiness_check(
            "issue_wanted_state",
            "Issues / Wanted",
            "ready" if issues and wanted_items else "gap",
            f"{issues} issues; {wanted_items} wanted rows",
            "Keep syncing ComicVine issue state into wanted coverage." if issues and wanted_items else "Backfill native issues and wanted rows.",
            issues,
        )
    )
    checks.append(
        readiness_check(
            "queue_model",
            "Queue Model",
            "ready" if queue_items and source_attempts else "gap",
            f"{queue_items} queue rows; {active_queue_items} active; {source_attempts} source attempts",
            "Queue, provider attempts, and retries are reporting into InkDrop state." if source_attempts else "Record provider attempts against queue rows.",
            active_queue_items,
        )
    )
    checks.append(
        readiness_check(
            "download_tasks",
            "Download Tasks",
            "ready" if download_tasks else "gap",
            f"{download_tasks} tracked transfers",
            "Download clients and transfer lifecycle are durable InkDrop state." if download_tasks else "Track SLSKD, torrent, and usenet transfers as download tasks.",
            download_tasks,
        )
    )
    checks.append(
        readiness_check(
            "import_verification",
            "Import / Verify",
            "ready" if import_results else "gap",
            f"{import_results} import results",
            "Imports and library visibility are first-class history." if import_results else "Record imports and verification outcomes.",
            import_results,
        )
    )
    checks.append(
        readiness_check(
            "history",
            "History",
            "ready" if history_events else "gap",
            f"{history_events} events",
            "Search, queue, import, settings, and provider events are audit-ready." if history_events else "Record automation history events.",
            history_events,
        )
    )
    checks.append(
        readiness_check(
            "provider_settings",
            "Provider Settings",
            "ready" if provider_configs >= 8 and app_settings >= 5 else ("watch" if provider_configs else "gap"),
            f"{provider_configs} providers; {app_settings} app settings",
            "Provider configuration is moving into InkDrop." if provider_configs else "Seed provider configs for metadata, sources, clients, paths, and rules.",
            provider_configs,
        )
    )
    exception_state = "ready"
    exception_action = "Manual Review is an exception lane."
    if manual_review_actionable_count:
        exception_state = "watch"
        exception_action = "Resolve or park actionable manual-review exceptions."
    checks.append(
        readiness_check(
            "manual_review_exception_lane",
            "Manual Review",
            exception_state,
            f"{manual_review_actionable_count} actionable; {manual_review_parked_count} parked",
            exception_action,
            manual_review_actionable_count,
        )
    )
    backlog_state = "ready"
    backlog_action = "Automation is actively working or retrying wanted rows."
    if queue_exception_items:
        backlog_state = "watch"
        backlog_action = "Review queue exceptions before they become manual workflow."
    elif queue_backlog_no_candidate_items:
        backlog_state = "watch"
        backlog_action = "Improve source coverage and SLSKD/Prowlarr matching for no-candidate backlog."
    checks.append(
        readiness_check(
            "automation_backlog",
            "Automation Backlog",
            backlog_state,
            f"{queue_work_items} working; {queue_backlog_items} backlog; {queue_backlog_no_candidate_items} no candidate; {queue_backlog_retry_pressure_items} extended retry",
            backlog_action,
            queue_backlog_items,
        )
    )
    kapowarr_state = "ready" if adapter_series == 0 else "watch"
    checks.append(
        readiness_check(
            "kapowarr_adapter",
            "Optional legacy integration",
            kapowarr_state,
            "optional" if adapter_series == 0 else f"{adapter_series} adapter-backed series",
            "Kapowarr is not the current source of truth." if adapter_series == 0 else "Continue reducing live Kapowarr dependence.",
            adapter_series,
        )
    )
    ready_count = sum(1 for check in checks if check["state"] == "ready")
    watch_count = sum(1 for check in checks if check["state"] == "watch")
    gap_count = sum(1 for check in checks if check["state"] == "gap")
    score = round(((ready_count + watch_count * 0.5) / max(1, len(checks))) * 100)
    if gap_count:
        state = "gap"
        next_action = next((check["next_action"] for check in checks if check["state"] == "gap"), "Fill missing standalone state.")
    elif watch_count:
        state = "watch"
        next_action = next((check["next_action"] for check in checks if check["state"] == "watch"), "Harden remaining watch items.")
    else:
        state = "ready"
        next_action = "Continue reducing external adapters and improving automation."
    return {
        "state": state,
        "score": score,
        "ready": ready_count,
        "watch": watch_count,
        "gaps": gap_count,
        "total": len(checks),
        "checks": checks,
        "next_action": next_action,
        "summary": f"{ready_count}/{len(checks)} ready; {watch_count} watch; {gap_count} gaps",
    }


def sync_import_results(state_dir, db_path=None):
    def _sync():
        state = Path(state_dir)
        path = Path(db_path or db_path_for_state_dir(state))
        now = time.time()
        source = state_source_snapshot(state)
        import_status_sync = None
        with connect(path) as con:
            init_schema(con)
            # Commit per stage on purpose. This whole block used to be one
            # transaction; any stage outliving the import child's timeout
            # rolled back EVERY stage's work -- measured live 2026-07-29 as
            # hours of maintenance (wrong-unit stamps, folder-presence
            # verifications) evaporating pass after pass, and the write lock
            # held for the full multi-minute sync starving every UI write.
            # Each stage is an idempotent maintenance operation that re-runs
            # every sync, so a committed prefix is always a valid state; a
            # kill now costs at most the stage in flight, and lock hold is
            # bounded by the slowest stage, not the sum of all of them.
            import_status_sync = sync_import_status_sources(con, state, now)
            con.commit()
            count = import_status_sync["count"]
            reconciliation_count = sync_download_reconciliation(con, state, now)
            con.commit()
            bad_source_candidate_count = sync_bad_source_candidates_from_pack_history_con(con, state, now)
            con.commit()
            download_task_count = backfill_download_tasks_from_attempts(con)
            con.commit()
            provider_contract_backfill = backfill_provider_contract_fields(con)
            con.commit()
            superseded_download_tasks_retired = cleanup_superseded_active_download_tasks(con, now)
            con.commit()
            superseded_sent_download_tasks_retired = cleanup_superseded_sent_download_tasks(con, now)
            con.commit()
            local_pack_superseded_handoff_tasks_retired = cleanup_local_pack_superseded_download_client_tasks(con, now)
            con.commit()
            stale_download_client_handoff_tasks_retired = cleanup_stale_download_client_handoff_tasks(con, now)
            con.commit()
            stale_download_task_bad_candidates = sync_stale_download_task_bad_candidates(con, now)
            con.commit()
            wrong_title_active_slskd_download_tasks_retired = cleanup_active_slskd_wrong_title_download_tasks(con, now)
            con.commit()
            retired_download_queue_items_requeued = cleanup_queue_items_with_retired_download_tasks(con, now)
            con.commit()
            superseded_slskd_queue_active_download_tasks_retired = cleanup_superseded_slskd_queue_active_download_tasks(con, now)
            con.commit()
            duplicate_active_handoff_tasks_retired = cleanup_duplicate_active_handoff_download_tasks(con, now)
            con.commit()
            inactive_download_tasks_retired = cleanup_inactive_active_download_tasks(con, now)
            con.commit()
            download_task_dupes_removed = cleanup_duplicate_download_tasks(con)
            con.commit()
            stale_active_queue_display_cleared = cleanup_queue_items_without_active_download_work(con, now)
            con.commit()
            non_active_searching_queue_rows_cleared = cleanup_non_active_searching_queue_rows(con, now)
            con.commit()
            expired_import_claims_released = cleanup_expired_import_claims(con, now)
            con.commit()
            stale_slskd_wrong_title_bad_candidates = sync_stale_slskd_wrong_title_bad_candidates(con, now)
            con.commit()
            download_task_history_count = backfill_download_task_history(con)
            con.commit()
            legacy_folder_completion_backfill = backfill_legacy_folder_completion_import_results(con, now)
            con.commit()
            queue_verified_pending_scan_backfill = backfill_queue_verified_pending_scan_import_results(con, now)
            con.commit()
            optional_folder_scan_pending_promoted = promote_optional_folder_scan_pending_import_results(con, now)
            con.commit()
            pending_pack_import_backfill = backfill_pending_pack_import_results_from_attempts(con, now)
            con.commit()
            direct_import_verification = verify_pending_direct_import_results(con, path, now)
            con.commit()
            verified_backfill_count = backfill_verified_queue_import_results(con, now)
            con.commit()
            source_linked_count = backfill_import_source_attempt_links(con)
            con.commit()
            superseded_adapter_import_results = cleanup_superseded_adapter_import_results(con, now)
            con.commit()
            missing_folder_import_proofs_retracted = cleanup_missing_folder_verified_import_proofs(con, now)
            con.commit()
            wrong_unit_page_pack_import_proofs_retracted = cleanup_wrong_unit_page_pack_import_proofs(con, now)
            con.commit()
            contradictory_completion_provenance_retracted = cleanup_contradictory_completion_provenance(con, now)
            con.commit()
            active_download_queue_settled_count = settle_queue_items_with_active_download_tasks(con, now)
            con.commit()
            verified_import_settled_count = settle_queue_items_with_verified_imports(con, now)
            con.commit()
            duplicate_issue_wanted_reconciled = reconcile_duplicate_issue_number_wanted_statuses(con, now)
            con.commit()
            queue_scheduler_evidence_backfilled = backfill_queue_scheduler_evidence_fields(con, now)
            con.commit()
            optional_folder_import_settled_count = settle_queue_items_with_optional_folder_imports(con, now)
            con.commit()
            # Rotate through the active set instead of re-scanning its head.
            # The pass budget (2026-07-29) made each pass bounded, but a
            # bounded pass that always starts at the top re-pays the same
            # unproductive head rows every sync and the tail starves --
            # measured live: 202 folder-presence credits landed while Hunter x
            # Hunter, deep in the updated_at order with all 38 volumes on
            # disk, received zero. The projection job already rotates with
            # this exact schema_meta cursor; sharing the key makes every
            # import child advance the same ring instead of competing.
            folder_presence_cursor_row = con.execute(
                "select value from schema_meta where key='folder_presence_projection_cursor' limit 1"
            ).fetchone()
            folder_presence_backfill = backfill_existing_folder_presence_import_results(
                con,
                now,
                after_queue_id=str(folder_presence_cursor_row["value"] or "") if folder_presence_cursor_row else "",
                return_progress=True,
            )
            if isinstance(folder_presence_backfill, dict) and "cursor" in folder_presence_backfill:
                con.execute(
                    "insert into schema_meta(key, value) values('folder_presence_projection_cursor', ?)"
                    " on conflict(key) do update set value=excluded.value",
                    (str(folder_presence_backfill.get("cursor") or ""),),
                )
            con.commit()
            folder_presence_wanted_backfill = backfill_existing_folder_presence_wanted_items(con, now)
            con.commit()
            collection_single_part_verified_reopened = cleanup_collection_single_part_verified_queue_rows(con, now)
            con.commit()
            superseded_count = supersede_duplicate_queue_items(con, now)
            con.commit()
            verification_dupes_removed = cleanup_duplicate_verified_activity_attempts(con)
            con.commit()
            media_files = sync_managed_media_files(con, now)
            con.commit()
            update_sync_meta(con, now, "imports", source.get("source_mtime"))
            con.commit()
        retired_import_status_events = retire_import_status_events(import_status_sync["events"])
        summary = state_summary(path)
        summary.update(source)
        summary.update({"ok": True, "db_path": str(path), "synced": {"imports": count, "import_status_events": retired_import_status_events, "download_reconciliation": reconciliation_count, "bad_source_candidates": bad_source_candidate_count, "stale_download_task_bad_candidates": stale_download_task_bad_candidates, "stale_slskd_wrong_title_bad_candidates": stale_slskd_wrong_title_bad_candidates, "download_tasks": download_task_count, "provider_contract_backfill": provider_contract_backfill, "superseded_download_tasks_retired": superseded_download_tasks_retired, "superseded_sent_download_tasks_retired": superseded_sent_download_tasks_retired, "local_pack_superseded_handoff_tasks_retired": local_pack_superseded_handoff_tasks_retired, "stale_download_client_handoff_tasks_retired": stale_download_client_handoff_tasks_retired, "wrong_title_active_slskd_download_tasks_retired": wrong_title_active_slskd_download_tasks_retired, "retired_download_queue_items_requeued": retired_download_queue_items_requeued, "superseded_slskd_queue_active_download_tasks_retired": superseded_slskd_queue_active_download_tasks_retired, "duplicate_active_handoff_tasks_retired": duplicate_active_handoff_tasks_retired, "inactive_download_tasks_retired": inactive_download_tasks_retired, "duplicate_download_tasks_removed": download_task_dupes_removed, "download_task_history": download_task_history_count, "legacy_folder_completion_backfill": legacy_folder_completion_backfill, "queue_verified_pending_scan_backfill": queue_verified_pending_scan_backfill, "optional_folder_scan_pending_promoted": optional_folder_scan_pending_promoted, "pending_pack_import_backfill": pending_pack_import_backfill, "direct_import_verification": direct_import_verification, "verified_queue_backfill": verified_backfill_count, "import_source_attempt_links": source_linked_count, "superseded_adapter_import_results": superseded_adapter_import_results, "missing_folder_import_proofs_retracted": missing_folder_import_proofs_retracted, "wrong_unit_page_pack_import_proofs_retracted": wrong_unit_page_pack_import_proofs_retracted, "active_download_queue_settled": active_download_queue_settled_count, "verified_import_queue_settled": verified_import_settled_count, "duplicate_issue_wanted_reconciled": duplicate_issue_wanted_reconciled, "queue_scheduler_evidence_backfilled": queue_scheduler_evidence_backfilled, "optional_folder_import_queue_settled": optional_folder_import_settled_count, "folder_presence_backfill": folder_presence_backfill, "folder_presence_wanted_backfill": folder_presence_wanted_backfill, "collection_single_part_verified_reopened": collection_single_part_verified_reopened, "superseded_duplicates": superseded_count, "duplicate_verified_activity_attempts_removed": verification_dupes_removed, "media_files": media_files}, "synced_at": now, "synced_at_iso": utc_stamp(now)})
        summary["synced"]["rejected_import_status_events"] = len(import_status_sync["rejected"])
        summary["synced"]["contradictory_completion_provenance_retracted"] = contradictory_completion_provenance_retracted
        return summary

    return with_db_lock_retry(_sync, attempts=4, initial_delay=1.0)


def upsert_provider_config(con, provider, now):
    provider = dict(provider or {})
    provider_id = str(provider.get("id") or "").strip()
    if not provider_id:
        return False
    source = str(provider.get("source") or "runtime")
    existing = con.execute(
        "select source, base_url, secret_ref, settings_json from provider_configs where id = ?",
        (provider_id,),
    ).fetchone()
    preserve_stored = existing and source != "user"
    capabilities = provider.get("capabilities") if isinstance(provider.get("capabilities"), list) else []
    applied_by = provider.get("applied_by") if isinstance(provider.get("applied_by"), list) else []
    if preserve_stored:
        merged_settings = merge_provider_settings(existing["settings_json"], provider.get("settings") or {})
        con.execute(
            """
            update provider_configs
            set provider_type=?,
                display_name=?,
                base_url=coalesce(base_url, ?),
                secret_ref=secret_ref,
                settings_group=coalesce(?, settings_group),
                ownership=coalesce(?, ownership),
                automation_role=coalesce(?, automation_role),
                description=coalesce(?, description),
                next_action=coalesce(?, next_action),
                capabilities_json=?,
                applied_by_json=?,
                settings_json=?,
                updated_at=?
            where id=?
            """,
            (
                provider.get("provider_type") or provider.get("type") or "source",
                provider.get("display_name") or provider_id,
                provider.get("base_url"),
                provider.get("settings_group"),
                provider.get("ownership"),
                provider.get("automation_role"),
                provider.get("description"),
                provider.get("next_action"),
                json_dumps(capabilities),
                json_dumps(applied_by),
                json_dumps(merged_settings),
                now,
                provider_id,
            ),
        )
        return True
    con.execute(
        """
        insert into provider_configs(
            id, provider_type, display_name, enabled, base_url, secret_ref,
            settings_group, ownership, automation_role, description, next_action,
            capabilities_json, applied_by_json, settings_json, source, created_at, updated_at
        ) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        on conflict(id) do update set
            provider_type=excluded.provider_type,
            display_name=excluded.display_name,
            enabled=excluded.enabled,
            base_url=excluded.base_url,
            secret_ref=excluded.secret_ref,
            settings_group=excluded.settings_group,
            ownership=excluded.ownership,
            automation_role=excluded.automation_role,
            description=excluded.description,
            next_action=excluded.next_action,
            capabilities_json=excluded.capabilities_json,
            applied_by_json=excluded.applied_by_json,
            settings_json=excluded.settings_json,
            source=excluded.source,
            updated_at=excluded.updated_at
        """,
        (
            provider_id,
            provider.get("provider_type") or provider.get("type") or "source",
            provider.get("display_name") or provider_id,
            1 if provider.get("enabled", True) else 0,
            provider.get("base_url"),
            provider.get("secret_ref"),
            provider.get("settings_group"),
            provider.get("ownership"),
            provider.get("automation_role"),
            provider.get("description"),
            provider.get("next_action"),
            json_dumps(capabilities),
            json_dumps(applied_by),
            json_dumps(provider.get("settings") or {}),
            source,
            provider.get("created_at") or now,
            now,
        ),
    )
    return True


def upsert_app_setting(con, setting, now):
    setting = dict(setting or {})
    key = str(setting.get("key") or "").strip()
    if not key:
        return False
    existing = con.execute("select source from app_settings where key = ?", (key,)).fetchone()
    source = str(setting.get("source") or "runtime")
    preserve_stored = existing and source != "user"
    if preserve_stored:
        con.execute(
            """
            update app_settings
            set scope=?, label=coalesce(?, label), description=coalesce(?, description), updated_at=?
            where key=?
            """,
            (
                setting.get("scope") or "general",
                setting.get("label"),
                setting.get("description"),
                now,
                key,
            ),
        )
        return True
    con.execute(
        """
        insert into app_settings(key, scope, label, value_json, description, source, updated_at)
        values(?,?,?,?,?,?,?)
        on conflict(key) do update set
            scope=excluded.scope,
            label=excluded.label,
            value_json=excluded.value_json,
            description=excluded.description,
            source=excluded.source,
            updated_at=excluded.updated_at
        """,
        (
            key,
            setting.get("scope") or "general",
            setting.get("label") or key,
            json_dumps(setting.get("value")),
            setting.get("description") or "",
            source,
            now,
        ),
    )
    return True


# These Prowlarr child-indexer catalog templates briefly shipped with a real,
# instance-specific indexer_ids default (captured from a live Prowlarr during
# catalog authoring) instead of an empty one. Any install that seeded a
# template before the catalog fix still carries that stale value in
# provider_configs, and merge_provider_settings() always lets a stored value
# win over the (now-fixed) catalog default, so the bad value never self-heals
# on its own. Scrub it explicitly wherever the row is still catalog-owned.
LEAKED_PROWLARR_CATALOG_INDEXER_ID_FIELDS = {
    "prowlarr_nyaa": ("indexer_ids", "categoryless_fallback_indexer_ids"),
    "prowlarr_tokyo_toshokan_manga": ("indexer_ids",),
    "prowlarr_torrentleech_comics": ("indexer_ids",),
    "prowlarr_kat_comics": ("indexer_ids",),
    "prowlarr_pirate_bay_comics": ("indexer_ids",),
    "prowlarr_torrentdownload_comics": ("indexer_ids",),
    "prowlarr_dognzb_comics": ("indexer_ids",),
}


def scrub_leaked_prowlarr_catalog_indexer_ids(con):
    """Clear stale instance-specific indexer IDs from untouched catalog templates.

    Only rows still owned by source_catalog are touched; a row's source flips
    to 'user' the moment update_provider_config() saves any user edit, so this
    can never overwrite a real user-entered indexer mapping.
    """
    scrubbed = 0
    for provider_id, fields in LEAKED_PROWLARR_CATALOG_INDEXER_ID_FIELDS.items():
        row = con.execute(
            "select settings_json from provider_configs where id = ? and source = 'source_catalog'",
            (provider_id,),
        ).fetchone()
        if not row:
            continue
        settings = json_loads(row["settings_json"] or "{}", {})
        if not isinstance(settings, dict):
            continue
        changed = False
        for field in fields:
            if settings.get(field):
                settings[field] = []
                changed = True
        policy = settings.get("policy") if isinstance(settings.get("policy"), dict) else None
        if policy:
            for field in fields:
                if policy.get(field):
                    policy[field] = []
                    changed = True
        if not changed:
            continue
        con.execute(
            "update provider_configs set settings_json = ? where id = ? and source = 'source_catalog'",
            (json_dumps(settings), provider_id),
        )
        scrubbed += 1
    return scrubbed


def sync_settings(db_path, providers=None, settings=None):
    db_path = Path(db_path)
    now = time.time()
    provider_count = 0
    setting_count = 0
    with connect(db_path) as con:
        init_schema(con)
        for provider in providers or []:
            if upsert_provider_config(con, provider, now):
                provider_count += 1
        for setting in settings or []:
            if upsert_app_setting(con, setting, now):
                setting_count += 1
        scrubbed_indexer_ids = scrub_leaked_prowlarr_catalog_indexer_ids(con)
        update_sync_meta(con, now, "settings")
        con.commit()
    clear_settings_caches()
    return {
        "ok": True,
        "db_path": str(db_path),
        "synced": {
            "providers": provider_count,
            "settings": setting_count,
            "scrubbed_prowlarr_catalog_indexer_ids": scrubbed_indexer_ids,
        },
        "synced_at": now,
        "synced_at_iso": utc_stamp(now),
    }


