def provider_activity_key(value):
    text = str(value or "").strip().lower()
    text = re.sub(r"[^a-z0-9]+", "_", text).strip("_")
    aliases = {
        "soulseek": "slskd",
        "slskd_api": "slskd",
        "qb": "qbittorrent",
        "qbit": "qbittorrent",
        "qbittorrent": "qbittorrent",
        "sab": "sabnzbd",
        "sabnzbd": "sabnzbd",
        "getcomics": "rss",
        "get_comics": "rss",
        "comics_codes": "comicscodes",
        "comicscodes": "comicscodes",
        "packimport": "pack_import",
        "pack_import": "pack_import",
        "pack_importer": "pack_import",
        "pack_import_log": "pack_import",
        "pack_import_log_backfill": "pack_import",
        "pack_log_backfill": "pack_import",
    }
    return aliases.get(text, text)


def source_attempt_outcome(status, lifecycle_phase=None):
    status = str(status or "").strip().lower()
    phase = str(lifecycle_phase or "").strip().lower()
    if phase == "searched_no_candidates":
        return "no_candidate"
    if phase == "retry_later":
        if (
            "error" in status
            or "unavailable" in status
            or "provider" in status
            or "busy" in status
            or status in {"api_error", "transient_error", "source_busy"}
        ):
            return "problem"
        return "no_candidate"
    if phase in {"failed_candidate", "manual_review", "provider_wait"}:
        return "problem"
    if phase in {"downloading", "staged_or_importing", "verifying", "verified"}:
        return "productive"
    if phase in {"searching", "observed", "active"}:
        return "neutral"
    if not status:
        return "neutral"
    if (
        "no_candidate" in status
        or "no_candidates" in status
        or "checked_no_candidate" in status
        or "searched_no_candidate" in status
        or status in {"retry_exhausted", "retry_scheduled"}
    ):
        return "no_candidate"
    if (
        "fail" in status
        or "error" in status
        or "blocked" in status
        or "bad" in status
        or "stale" in status
        or "mismatch" in status
        or status in SLSKD_FAILED_IMPORT_MATCH_STATUSES
        or status in {"enqueue_response_ambiguous", "ambiguous_enqueue_response"}
    ):
        return "problem"
    if status in {
        "sent",
        "available",
        "download_started",
        "downloading",
        "started_waiting",
        "already_downloading",
        "waiting_for_transfer",
        "waiting_for_complete_source",
        "transfer_in_progress",
        "transfer_settling",
        "waiting_for_staged_file",
        "staged_file_settling",
        "staged_file_ready",
        "preview_importable",
        "ready_import",
        "import_busy",
        "verification_pending",
        "imported_not_resolved",
        "verified",
        "imported",
        "already_present",
        "resolved",
        "kavita_verified",
        "already_verified",
    }:
        return "productive"
    if "verified" in status or "imported" in status or "ready" in status or "download" in status:
        return "productive"
    if "review" in status:
        return "problem"
    return "neutral"


def source_attempt_display_phase(status, lifecycle_phase=None, outcome=None):
    status = str(status or "").strip().lower()
    phase = str(lifecycle_phase or "").strip().lower()
    outcome = str(outcome or source_attempt_outcome(status, phase)).strip().lower()
    if phase == "verified" or status in {"verified", "imported", "resolved", "kavita_verified", "already_verified"}:
        return "verified"
    if phase == "provider_wait" or status in {"provider_wait", "provider_unavailable"}:
        return "provider_wait"
    if phase == "manual_review" or "review" in status:
        return "manual_review"
    if phase == "failed_candidate":
        return "problem"
    if phase == "searched_no_candidates":
        return "no_candidate"
    if phase == "retry_later":
        if outcome == "problem":
            return "provider_wait" if (
                "provider" in status
                or "api" in status
                or "unavailable" in status
                or "busy" in status
                or status in {"transient_error", "source_busy"}
            ) else "problem"
        return "retry_later"
    if phase == "downloading":
        return "transferring"
    if phase == "staged_or_importing":
        return "importing"
    if phase == "verifying":
        return "verifying"
    if phase == "searching":
        return "searching"
    if outcome == "productive":
        if status in {"staged_file_ready", "preview_importable", "ready_import", "import_busy"}:
            return "importing"
        if "download" in status or "transfer" in status:
            return "transferring"
        return "productive"
    if outcome == "no_candidate":
        return "no_candidate"
    if outcome == "problem":
        return "problem"
    return "observed"


def backfill_source_attempt_outcome_columns(con, batch_size=1000, limit=None):
    batch_size = max(1, min(int(batch_size or 1000), 10000))
    remaining = None if limit is None else max(0, int(limit or 0))
    updated = 0
    while remaining is None or remaining > 0:
        fetch_limit = batch_size if remaining is None else min(batch_size, remaining)
        rows = con.execute(
            """
            select id, status, lifecycle_phase, outcome, display_phase
            from source_attempts
            where nullif(trim(coalesce(outcome, '')), '') is null
               or nullif(trim(coalesce(display_phase, '')), '') is null
            limit ?
            """,
            (fetch_limit,),
        ).fetchall()
        if not rows:
            break
        for row in rows:
            status = row_value(row, "status")
            lifecycle_phase = row_value(row, "lifecycle_phase")
            outcome = row_value(row, "outcome") or source_attempt_outcome(status, lifecycle_phase)
            display_phase = row_value(row, "display_phase") or source_attempt_display_phase(status, lifecycle_phase, outcome)
            con.execute(
                "update source_attempts set outcome=?, display_phase=? where id=?",
                (outcome, display_phase, row_value(row, "id")),
            )
            updated += 1
        con.commit()
        if remaining is not None:
            remaining -= len(rows)
    return updated


