def source_attempt_activity_keys(row):
    row = row if isinstance(row, dict) else dict(row or {})
    provider_id = provider_activity_key(row.get("provider_id"))
    if provider_id and provider_id != "unknown":
        keys = [provider_id]
    else:
        keys = []
        for value in (row.get("source"), row.get("provider"), row.get("download_client")):
            key = provider_activity_key(value)
            if key and key != "unknown" and key not in keys:
                keys.append(key)
    client_key = provider_activity_key(row.get("download_client"))
    if client_key in {"qbittorrent", "sabnzbd"} and client_key not in keys:
        keys.append(client_key)
    return keys


def provider_outcome_label(score, recent_outcomes):
    recent_outcomes = recent_outcomes if isinstance(recent_outcomes, dict) else {}
    productive = int(recent_outcomes.get("productive") or 0)
    no_candidate = int(recent_outcomes.get("no_candidate") or 0)
    problem = int(recent_outcomes.get("problem") or 0)
    neutral = int(recent_outcomes.get("neutral") or 0)
    if problem and problem >= max(productive, no_candidate):
        return "needs attention"
    if no_candidate and no_candidate > productive:
        return "low yield"
    if productive:
        return "productive"
    if neutral:
        return "observing"
    if score is None:
        return "no recent data"
    return "quiet"


def provider_outcome_score(recent_outcomes):
    recent_outcomes = recent_outcomes if isinstance(recent_outcomes, dict) else {}
    productive = int(recent_outcomes.get("productive") or 0)
    no_candidate = int(recent_outcomes.get("no_candidate") or 0)
    problem = int(recent_outcomes.get("problem") or 0)
    neutral = int(recent_outcomes.get("neutral") or 0)
    total = productive + no_candidate + problem + neutral
    if total <= 0:
        return None
    score = 50
    score += int(45 * productive / total)
    score -= int(35 * problem / total)
    score -= int(25 * no_candidate / total)
    score += min(10, productive)
    return max(0, min(100, score))


def provider_outcome_detail(outcomes):
    outcomes = outcomes if isinstance(outcomes, dict) else {}
    bits = []
    labels = {
        "productive": "productive",
        "no_candidate": "no candidate",
        "problem": "problem",
        "neutral": "other",
    }
    for key in ("productive", "no_candidate", "problem", "neutral"):
        count = int(outcomes.get(key) or 0)
        if count:
            bits.append(f"{count} {labels[key]}")
    return "; ".join(bits)


def provider_outcome_from_counts(total_outcomes, recent_outcomes):
    total_outcomes = {str(key): int(value or 0) for key, value in (total_outcomes or {}).items()}
    recent_outcomes = {str(key): int(value or 0) for key, value in (recent_outcomes or {}).items()}
    score = provider_outcome_score(recent_outcomes)
    label = provider_outcome_label(score, recent_outcomes)
    detail = provider_outcome_detail(recent_outcomes) or provider_outcome_detail(total_outcomes)
    return {
        "score": score,
        "label": label,
        "detail": detail,
        "total": total_outcomes,
        "recent": recent_outcomes,
    }


def provider_outcome_rollup(con, recent_seconds=86400, limit=12):
    now = time.time()
    recent_after = now - max(1, int(recent_seconds or 86400))
    providers = {}
    for row in con.execute(
        """
        select lower(coalesce(nullif(provider_id,''),'unknown')) as provider_id,
               lower(coalesce(nullif(source_type,''),'source')) as source_type,
               lower(coalesce(nullif(lifecycle_phase,''),'observed')) as lifecycle_phase,
               lower(coalesce(nullif(source,''),'unknown')) as source,
               lower(coalesce(nullif(provider,''),'unknown')) as provider,
               lower(coalesce(nullif(download_client,''),'unknown')) as download_client,
               status,
               max(coalesce(completed_at, started_at, 0)) as last_at,
               count(*) as total,
               sum(case when coalesce(completed_at, started_at, 0) >= ? then 1 else 0 end) as recent_count
        from source_attempts
        group by lower(coalesce(nullif(provider_id,''),'unknown')),
                 lower(coalesce(nullif(source_type,''),'source')),
                 lower(coalesce(nullif(lifecycle_phase,''),'observed')),
                 lower(coalesce(nullif(source,''),'unknown')),
                 lower(coalesce(nullif(provider,''),'unknown')),
                 lower(coalesce(nullif(download_client,''),'unknown')),
                 status
        """,
        (recent_after,),
    ):
        keys = source_attempt_activity_keys(row)
        status = str(row["status"] or "unknown")
        lifecycle_phase = str(row["lifecycle_phase"] or "").strip().lower()
        outcome = source_attempt_outcome(status, lifecycle_phase)
        total = int(row["total"] or 0)
        recent = int(row["recent_count"] or 0)
        last_at = safe_float(row["last_at"])
        for key in keys:
            item = providers.setdefault(
                key,
                {
                    "provider": key,
                    "total_attempts": 0,
                    "recent_attempts": 0,
                    "last_activity_at": None,
                    "last_activity_at_iso": None,
                    "last_status": None,
                    "last_lifecycle_phase": None,
                    "provider_type": row["source_type"],
                    "outcome_counts": {},
                    "recent_outcome_counts": {},
                    "lifecycle_counts": {},
                    "recent_lifecycle_counts": {},
                },
            )
            item["total_attempts"] += total
            item["recent_attempts"] += recent
            item["outcome_counts"][outcome] = int(item["outcome_counts"].get(outcome) or 0) + total
            item["lifecycle_counts"][lifecycle_phase] = int(item["lifecycle_counts"].get(lifecycle_phase) or 0) + total
            if recent:
                item["recent_outcome_counts"][outcome] = int(item["recent_outcome_counts"].get(outcome) or 0) + recent
                item["recent_lifecycle_counts"][lifecycle_phase] = int(item["recent_lifecycle_counts"].get(lifecycle_phase) or 0) + recent
            if last_at and (item["last_activity_at"] is None or last_at > item["last_activity_at"]):
                item["last_activity_at"] = last_at
                item["last_activity_at_iso"] = utc_stamp(last_at)
                item["last_status"] = status
                item["last_lifecycle_phase"] = lifecycle_phase
    rows = []
    for item in providers.values():
        outcome = provider_outcome_from_counts(item.get("outcome_counts") or {}, item.get("recent_outcome_counts") or {})
        item["outcome"] = outcome
        item["outcome_score"] = outcome.get("score")
        item["outcome_label"] = outcome.get("label")
        item["outcome_detail"] = outcome.get("detail")
        rows.append(item)
    rows.sort(
        key=lambda item: (
            0 if int(item.get("recent_attempts") or 0) else 1,
            -(int(item.get("recent_attempts") or 0)),
            safe_float(item.get("outcome_score")) if item.get("outcome_score") is not None else 101,
            item.get("provider") or "",
        )
    )
    return rows[: max(1, min(int(limit or 12), 50))]


