def series_shadow_ref_merge_apply_preview_operation(plan_row, operation):
    plan_row = plan_row if isinstance(plan_row, dict) else {}
    operation = operation if isinstance(operation, dict) else {}
    table = str(operation.get("table") or "").strip()
    ids = [str(value) for value in (operation.get("ids") or []) if value not in (None, "")]
    ids = list(dict.fromkeys(ids))
    set_values = operation.get("set_values") if isinstance(operation.get("set_values"), dict) else {}
    target_series_id = str(set_values.get("series_id") or plan_row.get("target_series_id") or "").strip()
    target_issue_id = str(set_values.get("issue_id") or "").strip()
    shadow_series_id = str(plan_row.get("shadow_series_id") or "").strip()
    if not table or not ids or not target_series_id or not target_issue_id or not shadow_series_id:
        return None
    sql_template = (
        f"update {table} "
        "set series_id = :target_series_id, issue_id = :target_issue_id "
        "where id in (:ids) and series_id = :shadow_series_id"
    )
    rollback_template = (
        f"update {table} "
        "set series_id = :shadow_series_id, issue_id = :old_issue_id_from_backup "
        "where id in (:ids) and series_id = :target_series_id"
    )
    return {
        "operation": operation.get("operation") or f"rewrite_{table}_series_issue",
        "table": table,
        "count": int(operation.get("count") or len(ids)),
        "ids": ids,
        "id_sample_count": len(ids),
        "id_list_truncated": int(operation.get("count") or len(ids)) > len(ids),
        "set": {
            "series_id": target_series_id,
            "issue_id": target_issue_id,
        },
        "where": {
            "id_in": ids,
            "series_id": shadow_series_id,
        },
        "parameters": {
            "target_series_id": target_series_id,
            "target_issue_id": target_issue_id,
            "shadow_series_id": shadow_series_id,
            "ids": ids,
        },
        "sql_template": sql_template,
        "rollback_template": rollback_template,
        "rollback_note": "Capture current rows by id before apply; rollback must restore each row's original issue_id from the backup snapshot.",
        "note": operation.get("note"),
    }


def series_shadow_ref_merge_apply_preview_row(plan_row):
    plan_row = dict(plan_row or {})
    blockers = list(plan_row.get("blocking_reasons") or [])
    warnings = list(plan_row.get("warnings") or [])
    operations = [
        item
        for item in (
            series_shadow_ref_merge_apply_preview_operation(plan_row, operation)
            for operation in (plan_row.get("planned_operations") or [])
        )
        if item
    ]
    if plan_row.get("state") != "ready_preview":
        blockers.append("source_plan_not_ready_preview")
    if not operations:
        blockers.append("no_preview_operations")
    mutation_count = sum(int(op.get("count") or 0) for op in operations)
    return {
        "id": stable_id("series_shadow_ref_merge_apply_preview", plan_row.get("shadow_series_id"), plan_row.get("target_series_id")),
        "read_only": True,
        "dry_run_only": True,
        "apply_supported": False,
        "apply_enabled": False,
        "apply_disabled_reason": "series_shadow_ref_merge_apply_not_enabled",
        "view": "series_shadow_ref_merge_apply_preview",
        "state": "blocked" if blockers else "preview_ready",
        "status": "blocked" if blockers else "preview_ready",
        "display_phase": "blocked" if blockers else "preview_ready",
        "display_phase_label": "Blocked" if blockers else "Preview Ready",
        "source_plan_id": plan_row.get("id"),
        "title": plan_row.get("title"),
        "series": plan_row.get("title"),
        "shadow_series_id": plan_row.get("shadow_series_id"),
        "target_series_id": plan_row.get("target_series_id"),
        "shadow_kind": plan_row.get("shadow_kind"),
        "library_path": plan_row.get("library_path"),
        "mutation_count": mutation_count,
        "operation_count": len(operations),
        "operations": operations,
        "issue_mappings": plan_row.get("issue_mappings") or [],
        "source_reference_counts": plan_row.get("collected_reference_counts") or {},
        "blocking_reasons": list(dict.fromkeys(blockers)),
        "warnings": list(dict.fromkeys(warnings)),
        "ready_for_apply": False,
        "eligible_for_future_apply": not blockers,
        "needs_user": False,
        "actionability": "diagnostic",
        "next_action": (
            "Preview only: exact refs are mapped, but apply remains disabled"
            if not blockers
            else "Resolve preview blockers before an apply path can be designed"
        ),
        "activity_summary": (
            f"{mutation_count} SQL-like row update(s); apply disabled"
            if not blockers
            else f"{len(blockers)} blocker(s); apply disabled"
        ),
        "linked_entities": linked_entities(series_id=plan_row.get("shadow_series_id")),
        "target_linked_entities": linked_entities(series_id=plan_row.get("target_series_id")),
    }


def series_shadow_ref_merge_apply_preview_matches(row, preview_filter):
    key = series_shadow_ref_merge_filter_key(preview_filter)
    row = row if isinstance(row, dict) else {}
    if key == "all":
        return True
    if key == "ready_preview":
        return row.get("state") == "preview_ready"
    if key == "blocked":
        return row.get("state") == "blocked"
    if key == "needs_issue_map":
        return "target_issue_match_missing" in (row.get("blocking_reasons") or [])
    if key == "import_results":
        return any(op.get("table") == "import_results" for op in row.get("operations") or [])
    if key == "history":
        return any(op.get("table") == "history_events" for op in row.get("operations") or [])
    return True


def series_shadow_ref_merge_apply_preview_rollup(rows):
    rows = rows or []
    by_state = {}
    blockers = {}
    mutation_count = 0
    operation_count = 0
    for row in rows:
        state = row.get("state") or "unknown"
        by_state[state] = by_state.get(state, 0) + 1
        mutation_count += int(row.get("mutation_count") or 0)
        operation_count += int(row.get("operation_count") or 0)
        for reason in row.get("blocking_reasons") or []:
            blockers[reason] = blockers.get(reason, 0) + 1
    return {
        "series_shadow_ref_merge_apply_preview_rows": len(rows),
        "series_shadow_ref_merge_apply_preview_ready": int(by_state.get("preview_ready") or 0),
        "series_shadow_ref_merge_apply_preview_blocked": int(by_state.get("blocked") or 0),
        "series_shadow_ref_merge_apply_preview_by_state": by_state,
        "series_shadow_ref_merge_apply_preview_blockers": blockers,
        "series_shadow_ref_merge_apply_preview_mutation_count": mutation_count,
        "series_shadow_ref_merge_apply_preview_operation_count": operation_count,
        "apply_supported": False,
        "apply_enabled": False,
        "apply_disabled_reason": "series_shadow_ref_merge_apply_not_enabled",
        "read_only": True,
        "dry_run_only": True,
    }


def series_shadow_ref_merge_apply_preview_filter_options(rows):
    rows = rows or []
    return [
        {
            "value": key,
            "label": label,
            "count": sum(1 for row in rows if series_shadow_ref_merge_apply_preview_matches(row, key)),
        }
        for key, label in SERIES_SHADOW_REF_MERGE_FILTERS.items()
    ]


