def state_sections(db_path):
    summary = state_summary(db_path)
    return state_sections_from_summary(summary, db_path, fast=False)


def state_view_total_count(summary, key, db_path=None):
    key = str(key or "").strip().lower()
    wanted = summary.get("wanted_by_status") or {}
    queue = summary.get("queue_by_state") or {}
    active_queue = summary.get("queue_by_active_state") or queue
    display_active_queue = summary.get("queue_by_display_active_state") or active_queue
    if key == "series":
        return int(summary.get("series") or 0)
    if key in {"issues", "issue", "volumes"}:
        return int(summary.get("issues") or 0)
    if key == "wanted":
        return sum(int(wanted.get(state) or 0) for state in ("blocked", "in_progress", "wanted", "grabbed"))
    if key == "queue":
        return sum(int(display_active_queue.get(state) or 0) for state in ("downloading", "importing", "searching", "needs_you", "failed", "blocked", "source_wait"))
    if key == "manual_review":
        if db_path:
            return len(manual_review_rows(db_path, 5000, manual_review_filter="actionable"))
        return int(summary.get("manual_review_actionable_count") or 0)
    if key == "history":
        return int(summary.get("history_events") or summary.get("history_count") or 0)
    if key in {"sources", "providers", "source_providers"}:
        return int(summary.get("provider_configs") or 0)
    if key in {"source_memory", "bad_source_candidates", "bad_sources", "bad-source-candidates"}:
        return int(summary.get("bad_source_candidates") or 0)
    if key in {"source_attempts", "source-attempts", "attempts"}:
        return int(summary.get("source_attempts") or 0)
    if key in {"download_tasks", "downloads", "transfers"}:
        return int(summary.get("download_tasks") or 0)
    if key == "imports":
        return int(summary.get("import_results") or 0)
    if key == "settings":
        return int(summary.get("provider_configs") or 0) + int(summary.get("app_settings") or 0)
    return 0


WANTED_FILTERS = {
    "active": ("Active", ("blocked", "in_progress", "wanted", "grabbed")),
    "missing": ("Missing", ("wanted",)),
    "in_progress": ("In Progress", ("in_progress",)),
    "grabbed": ("Grabbed", ("grabbed",)),
    "blocked": ("Blocked", ("blocked",)),
    "waiting": ("Waiting", ("blocked", "in_progress", "wanted", "grabbed")),
    "recovering": ("Recovering", ("blocked", "in_progress", "wanted", "grabbed")),
    "provider_wait": ("Source Wait", ("blocked", "in_progress", "wanted", "grabbed")),
    "satisfied": ("Satisfied", ("satisfied",)),
    "all": ("All", ("blocked", "in_progress", "wanted", "grabbed", "satisfied")),
}


def wanted_filter_statuses(wanted_filter):
    value = str(wanted_filter or "active").strip().lower().replace("-", "_")
    if value in {"source_wait", "source_limited", "provider_limited"}:
        value = "provider_wait"
    if value in {"no_candidate", "no_candidates", "searched_no_candidates", "retry_later", "retry_scheduled"}:
        value = "waiting"
    if value in {"candidate_recovery", "failed_candidate", "failed_candidate_retry"}:
        value = "recovering"
    if value in WANTED_FILTERS:
        return value, WANTED_FILTERS[value][1]
    if value in {"blocked", "in_progress", "wanted", "grabbed", "satisfied"}:
        return value, (value,)
    return "active", WANTED_FILTERS["active"][1]


def provider_wait_rows(rows):
    return [row for row in (rows or []) if row_source_wait(row)]


def scoped_series_ids(series_ids):
    out = []
    seen = set()
    for value in series_ids or []:
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        out.append(text)
    return out


def series_provider_wait_counts(db_path, series_ids=None):
    counts = {}
    path = Path(db_path)
    if not path.exists():
        return counts
    scoped_ids = scoped_series_ids(series_ids)
    if series_ids is not None and not scoped_ids:
        return counts
    scope_sql = ""
    scope_params = []
    if scoped_ids:
        scope_sql = f"and series_id in ({','.join('?' for _ in scoped_ids)})"
        scope_params = scoped_ids
    with connect_read(path) as con:
        for row in con.execute(
            f"""
            select series_id, count(*) as count
            from queue_items
            where active=1
              and coalesce(series_id, '') <> ''
              {scope_sql}
              and state not in ('downloading','importing','verified','satisfied','superseded_duplicate')
              and (
                  state='source_wait'
                  or lower(coalesce(last_event, '')) like '%provider health%'
                  or lower(coalesce(last_event, '')) like '%source health%'
                  or lower(coalesce(last_event, '')) like '%source limited%'
                  or lower(coalesce(last_event, '')) like '%backoff%'
                  or lower(coalesce(last_event, '')) like '%disabled%'
                  or lower(coalesce(last_event, '')) like '%unavailable%'
                  or (
                      lower(coalesce(current_source, '')) = 'slskd'
                      and lower(coalesce(raw_json, '')) like '%last_slskd_transfer_state%'
                  )
              )
            group by series_id
            """,
            tuple(scope_params),
        ):
            series_id = str(row["series_id"] or "").strip()
            if series_id:
                counts[series_id] = counts.get(series_id, 0) + int(row["count"] or 0)
        for row in con.execute(
            f"""
            select series_id, count(*) as count
            from review_exceptions
            where active=1
              and state='provider_wait'
              and coalesce(series_id, '') <> ''
              {scope_sql}
            group by series_id
            """,
            tuple(scope_params),
        ):
            series_id = str(row["series_id"] or "").strip()
            if series_id:
                counts[series_id] = counts.get(series_id, 0) + int(row["count"] or 0)
    return counts


def series_review_attention_counts(db_path, series_ids=None):
    counts = {}
    path = Path(db_path)
    if not path.exists():
        return counts
    scoped_ids = scoped_series_ids(series_ids)
    if series_ids is not None and not scoped_ids:
        return counts
    scoped = set(scoped_ids)
    for row in manual_review_rows(db_path, 5000, "actionable"):
        series_id = str(row.get("series_id") or "").strip()
        if series_id and (not scoped or series_id in scoped):
            counts[series_id] = counts.get(series_id, 0) + 1
    return counts


def series_attention_count(db_path):
    path = Path(db_path)
    if not path.exists():
        return 0
    return len(series_review_attention_counts(db_path))


def wanted_provider_wait_count(db_path):
    _filter, statuses = wanted_filter_statuses("provider_wait")
    return wanted_provider_status_count(db_path, "provider_wait", statuses=statuses)


def wanted_provider_status_count(db_path, status_filter, statuses=None):
    status_filter = provider_status_filter_key(status_filter)
    if not status_filter:
        return 0
    if statuses is None:
        _filter, statuses = wanted_filter_statuses(status_filter)
    path = Path(db_path)
    if not path.exists():
        return 0
    status_values = [str(value).strip().lower() for value in (statuses or []) if str(value or "").strip()]
    clauses = []
    params = []
    if status_values:
        clauses.append("w.status in ({})".format(",".join("?" for _ in status_values)))
        params.extend(status_values)
    provider_status_sql, provider_status_params = queue_provider_status_filter_sql(status_filter, "q")
    if not provider_status_sql:
        return 0
    clauses.append("q.active = 1")
    clauses.append(provider_status_sql)
    params.extend(provider_status_params)
    where = f"where {' and '.join(clauses)}" if clauses else ""
    with connect_read(path) as con:
        row = con.execute(
            f"""
            select count(distinct w.id) as count
            from wanted_items w
            left join queue_items q on q.wanted_id = w.id
            {where}
            """,
            params,
        ).fetchone()
    return int(row["count"] or 0) if row else 0


def wanted_provider_status_rows(db_path, status_filter, limit=80, statuses=None):
    status_filter = provider_status_filter_key(status_filter)
    if not status_filter:
        return []
    if statuses is None:
        _filter, statuses = wanted_filter_statuses(status_filter)
    limit = max(1, min(int(limit or 80), 5000))
    fetch_limit = max(limit, min(5000, limit * 8, limit + 160))
    rows = wanted_rows(
        db_path,
        fetch_limit,
        statuses=statuses,
        provider_status_filter=status_filter,
    )
    filtered = provider_status_filter_rows(rows, status_filter, limit)
    if len(filtered) >= limit or fetch_limit >= 5000:
        return filtered
    fallback_rows = wanted_rows(db_path, 5000, statuses=statuses)
    return provider_status_filter_rows(fallback_rows, status_filter, limit)


def wanted_filter_options(summary, db_path=None):
    wanted = summary.get("wanted_by_status") or {}
    options = []
    for value, (label, statuses) in WANTED_FILTERS.items():
        if value == "provider_wait" and db_path:
            count = wanted_provider_wait_count(db_path)
        elif value in {"waiting", "recovering"} and db_path:
            count = wanted_provider_status_count(db_path, value)
        else:
            count = sum(int(wanted.get(status) or 0) for status in statuses)
        options.append({"value": value, "label": label, "count": count})
    options.extend(completion_gate_filter_options(summary))
    return options


def compact_attempt(attempt):
    attempt = dict(attempt or {})
    return {key: value for key, value in attempt.items() if value not in (None, "")}


def compact_count(value):
    number = int(value or 0)
    if number >= 1000000:
        return f"{number / 1000000:.1f}m".replace(".0m", "m")
    if number >= 1000:
        return f"{number / 1000:.1f}k".replace(".0k", "k")
    return str(number)


