PREFLIGHT_SOURCE_KEYS = {"local"}


def first_acquisition_source(values):
    for value in values or []:
        key = str(value or "").strip().lower()
        if key and key not in PREFLIGHT_SOURCE_KEYS:
            return key
    return ""


def provider_health_from_raw(raw):
    raw = raw if isinstance(raw, dict) else {}
    health = raw.get("health") if isinstance(raw.get("health"), dict) else raw
    signature = raw.get("signature") if isinstance(raw.get("signature"), dict) else {}
    state = str(health.get("state") or signature.get("state") or "").strip().lower()
    label = str(health.get("label") or signature.get("label") or state or "unknown").strip()
    detail = str(health.get("detail") or signature.get("detail") or "").strip()
    out = {
        "state": state,
        "label": label,
        "detail": detail,
    }
    for key in (
        "api_reachable",
        "version",
        "app_name",
        "indexer_count",
        "enabled_indexer_count",
        "indexer_error",
        "base_url",
        "latency_ms",
        "server_latency_ms",
        "server_error",
        "soulseek_connected",
        "soulseek_logged_in",
        "soulseek_transitioning",
        "server_state",
        "soulseek_address",
        "health_scope",
        "download_history_scope",
        "active_downloads",
        "failed_downloads",
        "ready_imports",
        "completed_pack_manifest_cache_roots",
        "completed_pack_manifest_cache_archives",
    ):
        value = health.get(key)
        if value not in (None, "", [], {}):
            out[key] = value
    return out


SOURCE_PROVIDER_HEALTH_PROBLEM_STATES = {"backoff", "disabled", "error", "failed", "unavailable", "watch"}
DISABLED_PROVIDER_WAIT_PHASES = {
    "backoff",
    "disabled",
    "provider_limited",
    "provider_unavailable",
    "provider_wait",
    "source_limited",
    "watch",
}


def provider_config_enabled_map(con):
    if con is None or not table_exists(con, "provider_configs"):
        return {}
    return {
        provider_activity_key(row["id"]): bool(row["enabled"])
        for row in con.execute("select id, enabled from provider_configs")
        if provider_activity_key(row["id"])
    }


def provider_artifact_key(record):
    record = record if isinstance(record, dict) else {}
    return provider_activity_key(
        record.get("provider_id")
        or record.get("download_client")
        or record.get("provider")
        or record.get("source")
        or record.get("protocol")
    )


def disabled_provider_wait_artifact(record, provider_enabled):
    record = record if isinstance(record, dict) else {}
    provider_enabled = provider_enabled if isinstance(provider_enabled, dict) else {}
    provider_key = provider_artifact_key(record)
    if not provider_key or provider_enabled.get(provider_key, True):
        return False
    values = {
        str(record.get(key) or "").strip().lower()
        for key in ("status", "state", "lifecycle_phase", "display_phase", "outcome")
    }
    if inkdrop_sources is not None:
        for value in list(values):
            try:
                values.add(inkdrop_sources.lifecycle_phase(value))
            except Exception:
                pass
    reason = str(record.get("failure_reason") or "").strip().lower()
    if "cloudflare_or_host_challenge" in reason:
        values.add("provider_wait")
    return bool(values & DISABLED_PROVIDER_WAIT_PHASES)


def provider_health_download_history_only(health):
    health = health if isinstance(health, dict) else {}
    provider_id = provider_activity_key(health.get("provider_id"))
    label = str(health.get("label") or "").strip().lower()
    detail = str(health.get("detail") or health.get("message") or "").strip().lower()
    scope = str(health.get("health_scope") or health.get("scope") or "").strip().lower()
    if scope == "download_history":
        return True
    if provider_id not in {"sabnzbd", "qbittorrent", "download_client"}:
        return False
    text = f"{label} {detail}"
    return "download failures" in text or "failed downloads" in text or "ready imports" in text


def provider_health_is_problem(health):
    health = health if isinstance(health, dict) else {}
    state = str(health.get("state") or "").strip().lower()
    if state not in SOURCE_PROVIDER_HEALTH_PROBLEM_STATES:
        return False
    if provider_health_download_history_only(health):
        return False
    return True


# Six providers exist, but the map below is a grouped self-join over history_events
# (1.5M rows). refresh_queue_provider_status_columns rebuilds it to refresh a SINGLE
# queue row, and record_source_attempt calls that once per attempt: measured live on
# 2026-08-01 at 1209 rebuilds and 30.9s of one sync_download_reconciliation pass --
# all of it inside the SQLite write lock.
#
# The newest provider_health timestamp is the map's whole input, and reading it is an
# index seek (~0.005ms vs ~26ms to rebuild). Key the cache on it: two connections that
# can see the same newest event derive the same map, and a connection's own uncommitted
# insert moves its marker but not another connection's, so this stays correct across
# processes without an invalidation hook. Adding count(*) would make the marker exact
# against a same-timestamp insert, but it costs 10ms -- as much as the rebuild -- and a
# briefly stale derived status column re-settles on the next health event.
PROVIDER_HEALTH_MAP_CACHE = {}
PROVIDER_HEALTH_MAP_CACHE_LIMIT = 4


def bump_provider_health_revision(con):
    """Advance the provider-health revision by hand.

    Normally unnecessary: a trigger on history_events advances it for every
    provider_health row, whoever writes it. Relying on writers to remember was
    the first version of this and it was wrong -- a caller inserting the row
    directly got a stale map, which is the same class of bug the revision exists
    to fix. Kept for callers that synthesise health without an event row.
    """
    try:
        con.execute(
            "insert into schema_meta(key, value) values('provider_health_revision', '1') "
            "on conflict(key) do update set "
            "value = cast(cast(coalesce(schema_meta.value,'0') as integer) + 1 as text)"
        )
    except sqlite3.Error:
        pass


def provider_health_map_marker(con):
    """A revision counter, not a timestamp.

    max(created_at) looked free and correct and was neither. A batch that marks
    several providers healthy stamps them all with the same created_at, so the
    second and later rows could not invalidate a cache the first one had just
    populated: their health never reached the map, and a queue row waiting on
    that provider stayed in provider_wait indefinitely. A monotonic revision
    cannot collide that way. Reading it is a single indexed schema_meta row.
    """
    try:
        row = con.execute(
            "select value from schema_meta where key='provider_health_revision'"
        ).fetchone()
    except Exception:
        return None
    if not row:
        # No revision recorded yet is itself a stable state to cache against.
        return "0"
    return str(row[0] if not isinstance(row, sqlite3.Row) else row["value"])


def latest_provider_health_map(con):
    marker = provider_health_map_marker(con)
    if marker is not None:
        cached = PROVIDER_HEALTH_MAP_CACHE.get(marker)
        if cached is not None:
            return copy.deepcopy(cached)
    rows = con.execute(
        """
        select h.entity_id, h.message, h.created_at, h.raw_json
        from history_events h
        join (
            select entity_id, max(created_at) as created_at
            from history_events
            where entity_type='provider'
              and event_type='provider_health'
            group by entity_id
        ) latest on latest.entity_id = h.entity_id and latest.created_at = h.created_at
        where h.entity_type='provider'
          and h.event_type='provider_health'
        """
    ).fetchall()
    out = {}
    for row in rows:
        provider_id = str(row["entity_id"] or "").strip().lower()
        if not provider_id:
            continue
        raw = json_loads(row["raw_json"] or "{}", {})
        health = provider_health_from_raw(raw)
        health.update(
            {
                "provider_id": provider_id,
                "message": row["message"],
                "created_at": row["created_at"],
                "created_at_iso": utc_stamp(row["created_at"]) if row["created_at"] else None,
            }
        )
        out[provider_id] = health
    if marker is not None:
        if len(PROVIDER_HEALTH_MAP_CACHE) >= PROVIDER_HEALTH_MAP_CACHE_LIMIT:
            PROVIDER_HEALTH_MAP_CACHE.clear()
        PROVIDER_HEALTH_MAP_CACHE[marker] = copy.deepcopy(out)
    return out


def provider_health_rollup(con, limit=8):
    health_map = latest_provider_health_map(con)
    by_state = {}
    attention = []
    for provider_id, health in sorted((health_map or {}).items()):
        if not isinstance(health, dict):
            continue
        state = str(health.get("state") or "unknown").strip().lower() or "unknown"
        by_state[state] = int(by_state.get(state) or 0) + 1
        problem = provider_health_is_problem(health)
        if problem:
            attention.append(
                {
                    "provider": provider_id,
                    "provider_id": provider_id,
                    "label": source_display_label(provider_id),
                    "state": state,
                    "health_label": health.get("label") or state,
                    "detail": health.get("detail") or health.get("message") or "",
                    "message": health.get("message"),
                    "created_at": health.get("created_at"),
                    "created_at_iso": health.get("created_at_iso"),
                }
            )
    attention.sort(key=lambda item: (-(float(item.get("created_at") or 0)), item.get("provider") or ""))
    by_state = {
        key: int(value)
        for key, value in sorted(
            by_state.items(),
            key=lambda item: (-int(item[1] or 0), str(item[0])),
        )
    }
    max_rows = max(1, min(int(limit or 8), 20))
    return {
        "provider_health_items": len(health_map or {}),
        "provider_health_problem_items": len(attention),
        "provider_health_by_state": by_state,
        "provider_health_attention": attention[:max_rows],
    }


def import_ledger_cleanup_rollup(con, limit=3):
    if con is None or not table_exists(con, "history_events"):
        return {
            "import_ledger_cleanup_events": 0,
            "import_ledger_cleanup_retracted_rows": 0,
            "import_ledger_cleanup_by_table": {},
            "import_ledger_cleanup_by_reason": {},
            "import_ledger_cleanup_latest": {},
            "import_ledger_cleanup_recent": [],
        }
    max_rows = max(1, min(int(limit or 3), 12))
    rows = con.execute(
        """
        select id, event_type, entity_type, entity_id, source, message,
               outcome, display_phase, created_at, raw_json
        from history_events
        where event_type='stale_completion_retracted'
           or entity_type='import_ledger'
        order by created_at desc, id desc
        limit 100
        """
    ).fetchall()
    by_table = {}
    by_reason = {}
    recent = []
    total_retracted = 0
    for row in rows:
        raw = json_loads(row["raw_json"] or "{}", {})
        raw = raw if isinstance(raw, dict) else {}
        retracted = int(raw.get("retracted") or 0)
        total_retracted += retracted
        tables = raw.get("tables") if isinstance(raw.get("tables"), dict) else {}
        for table, table_summary in tables.items():
            if not isinstance(table_summary, dict):
                continue
            table_key = str(table or "unknown").strip() or "unknown"
            table_retracted = int(table_summary.get("retracted") or 0)
            if table_retracted:
                by_table[table_key] = int(by_table.get(table_key) or 0) + table_retracted
            reasons = table_summary.get("reasons") if isinstance(table_summary.get("reasons"), dict) else {}
            for reason, count in reasons.items():
                reason_key = str(reason or "unknown").strip() or "unknown"
                by_reason[reason_key] = int(by_reason.get(reason_key) or 0) + int(count or 0)
        created_at = safe_float(row["created_at"])
        recent.append(
            {
                "id": row["id"],
                "event_type": row["event_type"],
                "entity_type": row["entity_type"],
                "entity_id": row["entity_id"],
                "source": row["source"],
                "message": row["message"],
                "outcome": row["outcome"],
                "display_phase": row["display_phase"],
                "created_at": created_at or None,
                "created_at_iso": utc_stamp(created_at) if created_at > 0 else "",
                "retracted": retracted,
                "checked": int(raw.get("checked") or 0),
                "tables": clone_jsonish(tables),
            }
        )
    recent = recent[:max_rows]
    by_table = {
        key: int(value)
        for key, value in sorted(by_table.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
    }
    by_reason = {
        key: int(value)
        for key, value in sorted(by_reason.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
    }
    latest = recent[0] if recent else {}
    return {
        "import_ledger_cleanup_events": len(rows),
        "import_ledger_cleanup_retracted_rows": int(total_retracted),
        "import_ledger_cleanup_by_table": by_table,
        "import_ledger_cleanup_by_reason": by_reason,
        "import_ledger_cleanup_latest": latest,
        "import_ledger_cleanup_latest_message": latest.get("message") if latest else "",
        "import_ledger_cleanup_latest_at": latest.get("created_at") if latest else None,
        "import_ledger_cleanup_latest_at_iso": latest.get("created_at_iso") if latest else "",
        "import_ledger_cleanup_recent": recent,
    }


PROVIDER_HEALTH_ALIASES = {
    "download_client": ("sabnzbd", "qbittorrent"),
    "qb": ("qbittorrent",),
    "qbit": ("qbittorrent",),
    "qbittorrent": ("qbittorrent",),
    "sab": ("sabnzbd",),
    "sabnzbd": ("sabnzbd",),
    "slskd": ("slskd",),
    "soulseek": ("slskd",),
    "rss": ("rss",),
    "prowlarr": ("prowlarr",),
    "comicscodes": ("comicscodes",),
}


def provider_health_keys_for_row(row):
    row = dict(row or {})
    attempt = compact_attempt(row.get("last_attempt"))
    download_task = row.get("download_task") if isinstance(row.get("download_task"), dict) else {}
    candidates = [
        attempt.get("provider_id"),
        attempt.get("download_client"),
        attempt.get("provider"),
        download_task.get("provider_id"),
        download_task.get("download_client"),
        download_task.get("provider"),
        download_task.get("source"),
        download_task.get("protocol"),
        row.get("provider_id"),
        row.get("download_client"),
        row.get("provider"),
        row.get("source"),
        row.get("protocol"),
        row.get("display_source"),
        row.get("current_source"),
        row.get("source_key"),
    ]
    keys = []
    for value in candidates:
        key = str(value or "").strip().lower()
        if not key:
            continue
        key = key.replace(" ", "").replace("-", "")
        aliases = PROVIDER_HEALTH_ALIASES.get(key) or PROVIDER_HEALTH_ALIASES.get(str(value or "").strip().lower()) or (key,)
        for alias in aliases:
            if alias and alias not in keys:
                keys.append(alias)
    return keys


def provider_health_for_row(row, health_map):
    health_map = health_map if isinstance(health_map, dict) else {}
    problem_states = {"backoff", "disabled", "error", "failed", "unavailable", "watch"}
    matches = [health_map.get(key) for key in provider_health_keys_for_row(row)]
    matches = [item for item in matches if isinstance(item, dict)]
    if not matches:
        return None
    matches.sort(key=lambda item: (str(item.get("state") or "").lower() not in problem_states, -(float(item.get("created_at") or 0))))
    return matches[0]


def provider_queue_impact_summary(impact):
    impact = impact if isinstance(impact, dict) else {}
    bits = []
    for key, label in (
        ("provider_wait", "provider wait"),
        ("recovering", "recovering"),
        ("waiting", "waiting"),
        ("downloading", "downloading"),
        ("importing", "importing"),
        ("searching", "searching"),
    ):
        count = int(impact.get(key) or 0)
        if count:
            bits.append(f"{count} {label}")
    if not bits:
        active = int(impact.get("active_queue") or impact.get("queue_items") or 0)
        if active:
            bits.append(f"{active} active queue")
    return "; ".join(bits[:4])


def provider_queue_impact_snapshot(con, limit=5000):
    if con is None or not table_exists(con, "queue_items"):
        return {}
    limit = max(1, min(int(limit or 5000), 10000))
    queue_columns = {row["name"] for row in con.execute("pragma table_info(queue_items)")}
    source_attempt_columns = {row["name"] for row in con.execute("pragma table_info(source_attempts)")} if table_exists(con, "source_attempts") else set()
    download_task_columns = {row["name"] for row in con.execute("pragma table_info(download_tasks)")} if table_exists(con, "download_tasks") else set()

    def col(alias, column, output=None, columns=None):
        columns = columns if columns is not None else queue_columns
        output = output or column
        if column in columns:
            return f"{alias}.{column} as {output}"
        return f"null as {output}"

    source_attempt_select = ",\n               ".join(
        [
            col("la", "source", "last_attempt_source", source_attempt_columns),
            col("la", "provider_id", "last_attempt_provider_id", source_attempt_columns),
            col("la", "provider", "last_attempt_provider", source_attempt_columns),
            col("la", "protocol", "last_attempt_protocol", source_attempt_columns),
            col("la", "download_client", "last_attempt_download_client", source_attempt_columns),
        ]
    )
    download_task_select = ",\n               ".join(
        [
            col("ldt", "source", "latest_download_source", download_task_columns),
            col("ldt", "provider_id", "latest_download_provider_id", download_task_columns),
            col("ldt", "provider", "latest_download_provider", download_task_columns),
            col("ldt", "protocol", "latest_download_protocol", download_task_columns),
            col("ldt", "download_client", "latest_download_client", download_task_columns),
        ]
    )
    source_attempt_join = (
        """
        left join source_attempts la on la.id = (
            select sa.id
            from source_attempts sa
            where sa.queue_id = q.id
            order by coalesce(sa.completed_at, sa.started_at, 0) desc, sa.id desc
            limit 1
        )
        """
        if source_attempt_columns
        else ""
    )
    download_task_join = (
        """
        left join download_tasks ldt on ldt.id = (
            select dt.id
            from download_tasks dt
            where dt.queue_id = q.id
            order by
              case dt.state
                when 'downloading' then 0
                when 'import_ready' then 1
                when 'importing' then 2
                when 'queued' then 3
                when 'failed' then 5
                when 'verified' then 6
                else 4
              end,
              coalesce(dt.updated_at, dt.completed_at, dt.started_at, 0) desc,
              dt.id desc
            limit 1
        )
        """
        if download_task_columns
        else ""
    )
    rows = con.execute(
        f"""
        select q.id,
               {col("q", "state")},
               {col("q", "display_phase")},
               {col("q", "current_source")},
               {col("q", "provider_status_state")},
               {col("q", "provider_status_phase")},
               {col("q", "provider_status_provider")},
               {col("q", "provider_status_actionability")},
               {col("q", "created_at")},
               {col("q", "updated_at")},
               {source_attempt_select},
               {download_task_select}
        from queue_items q
        {source_attempt_join}
        {download_task_join}
        where {('q.active = 1' if 'active' in queue_columns else '1 = 1')}
        order by coalesce(q.updated_at, q.created_at, 0) desc
        limit ?
        """,
        (limit,),
    ).fetchall()
    out = {}
    for row in rows:
        row_payload = {
            "provider_id": row["provider_status_provider"],
            "current_source": row["current_source"],
            "source_key": row["current_source"],
            "last_attempt": {
                "source": row["last_attempt_source"],
                "provider_id": row["last_attempt_provider_id"],
                "provider": None if provider_activity_key(row["last_attempt_source"]) == "slskd" else row["last_attempt_provider"],
                "protocol": row["last_attempt_protocol"],
                "download_client": row["last_attempt_download_client"],
            },
            "download_task": {
                "source": row["latest_download_source"],
                "provider_id": row["latest_download_provider_id"],
                "provider": None if provider_activity_key(row["latest_download_source"]) == "slskd" else row["latest_download_provider"],
                "protocol": row["latest_download_protocol"],
                "download_client": row["latest_download_client"],
            },
        }
        keys = {provider_activity_key(key) for key in provider_health_keys_for_row(row_payload)}
        keys.add(provider_activity_key(row["provider_status_provider"]))
        keys.add(provider_activity_key(row["current_source"]))
        keys = {key for key in keys if key}
        if not keys:
            continue
        state = str(row["state"] or "").strip().lower()
        display_phase = str(row["display_phase"] or "").strip().lower()
        provider_state = str(row["provider_status_state"] or "").strip().lower()
        provider_phase = str(row["provider_status_phase"] or "").strip().lower()
        actionability = str(row["provider_status_actionability"] or "").strip().lower()
        updated_at = float(row["updated_at"] or row["created_at"] or 0)
        is_provider_wait = provider_state == "provider_wait" or provider_phase == "provider_wait" or state == "source_wait"
        is_recovering = provider_state == "recovering" or provider_phase in {"failed_candidate", "candidate_recovery"}
        is_waiting = provider_state == "waiting" or provider_phase in {"searched_no_candidates", "retry_later", "retry_scheduled", "no_candidate"}
        needs_user = provider_state in {"needs_you", "manual_review"} or actionability in {"manual_review", "needs_user"}
        for key in keys:
            item = out.setdefault(
                key,
                {
                    "provider_id": key,
                    "active_queue": 0,
                    "queue_items": 0,
                    "provider_wait": 0,
                    "recovering": 0,
                    "waiting": 0,
                    "needs_user": 0,
                    "searching": 0,
                    "downloading": 0,
                    "importing": 0,
                    "state_counts": {},
                    "provider_status_counts": {},
                    "phase_counts": {},
                    "last_queue_activity_at": None,
                    "last_queue_activity_at_iso": None,
                    "queue_filter": "active",
                    "queue_filter_label": "Active",
                    "actionability": "automatic",
                    "summary": "",
                },
            )
            item["active_queue"] += 1
            item["queue_items"] += 1
            if state:
                item["state_counts"][state] = int(item["state_counts"].get(state) or 0) + 1
            if provider_state:
                item["provider_status_counts"][provider_state] = int(item["provider_status_counts"].get(provider_state) or 0) + 1
            if provider_phase:
                item["phase_counts"][provider_phase] = int(item["phase_counts"].get(provider_phase) or 0) + 1
            if is_provider_wait:
                item["provider_wait"] += 1
            if is_recovering:
                item["recovering"] += 1
            if is_waiting:
                item["waiting"] += 1
            if needs_user:
                item["needs_user"] += 1
            if state == "searching" or display_phase == "searching":
                item["searching"] += 1
            if state == "downloading" or display_phase == "downloading":
                item["downloading"] += 1
            if state == "importing" or display_phase == "importing":
                item["importing"] += 1
            if updated_at and updated_at > float(item.get("last_queue_activity_at") or 0):
                item["last_queue_activity_at"] = updated_at
                item["last_queue_activity_at_iso"] = utc_stamp(updated_at)
    for item in out.values():
        if int(item.get("provider_wait") or 0):
            item["queue_filter"] = "provider_wait"
            item["queue_filter_label"] = "Provider Wait"
            item["actionability"] = "automatic_wait"
        elif int(item.get("recovering") or 0):
            item["queue_filter"] = "recovering"
            item["queue_filter_label"] = "Recovering"
            item["actionability"] = "automatic_retry"
        elif int(item.get("waiting") or 0):
            item["queue_filter"] = "waiting"
            item["queue_filter_label"] = "Waiting"
            item["actionability"] = "automatic_retry"
        else:
            item["queue_filter"] = "active"
            item["queue_filter_label"] = "Active"
        item["summary"] = provider_queue_impact_summary(item)
    return out


def _series_source_recommendation_family(series, publisher="", media_type=""):
    title_key = normalize_key(series)
    publisher_key = normalize_key(publisher)
    media_key = normalize_key(media_type).replace(" ", "_")
    if (
        media_key in MANGA_MEDIA_TYPES
        or publisher_key in MANGA_PUBLISHER_HINTS
        or any(hint and hint in title_key for hint in MANGA_TITLE_HINTS)
    ):
        return "manga"
    if (
        media_key in WESTERN_COMIC_MEDIA_TYPES
        or publisher_key in WESTERN_COMIC_PUBLISHER_HINTS
        or any(hint and hint in title_key for hint in WESTERN_COMIC_TITLE_HINTS)
    ):
        return "western_comic"
    return ""


def _source_recommendation_provider_ids(series, publisher="", media_type=""):
    family = _series_source_recommendation_family(series, publisher=publisher, media_type=media_type)
    if family == "manga":
        return ["prowlarr_nyaa", "prowlarr_tokyo_toshokan_manga"]
    if family == "western_comic":
        return [
            "prowlarr_torrentleech_comics",
            "prowlarr_dognzb_comics",
            "prowlarr_kat_comics",
            "prowlarr_pirate_bay_comics",
            "prowlarr_torrentdownload_comics",
        ]
    return []


def _sorted_count_rows(mapping, limit=6):
    return [
        {"key": str(key or ""), "count": int(value or 0)}
        for key, value in sorted(
            (mapping or {}).items(),
            key=lambda item: (-int(item[1] or 0), str(item[0] or "")),
        )[: max(1, int(limit or 6))]
        if str(key or "").strip()
    ]


def _source_attempt_fetch_evidence(raw):
    raw = raw if isinstance(raw, dict) else {}
    nested_raw = raw.get("raw") if isinstance(raw.get("raw"), dict) else {}
    fetch = nested_raw.get("fetch") if isinstance(nested_raw.get("fetch"), dict) else None
    if not fetch:
        fetch = raw.get("fetch") if isinstance(raw.get("fetch"), dict) else None
    return fetch or {}


def _source_attempt_suwayomi_source_pool_evidence(raw):
    fetch = _source_attempt_fetch_evidence(raw)
    if not fetch:
        return {}
    selection = fetch.get("suwayomi_source_selection") if isinstance(fetch.get("suwayomi_source_selection"), dict) else {}
    cooldown = fetch.get("suwayomi_source_error_cooldown") if isinstance(fetch.get("suwayomi_source_error_cooldown"), dict) else {}
    if not selection and not cooldown:
        return {}
    selected_sources = [row for row in selection.get("selected_sources") or [] if isinstance(row, dict)]
    skipped_sources = [row for row in selection.get("skipped_sources") or [] if isinstance(row, dict)]
    selected_count = int(safe_float(selection.get("selected_count"), 0)) or len(selected_sources)
    skipped_count = int(safe_float(selection.get("skipped_count"), 0)) or len(skipped_sources)
    reason_counts = {}
    cooldown_skipped = 0
    for source in skipped_sources:
        reason = metadata_provider_key(source.get("reason"))
        if not reason:
            continue
        reason_counts[reason] = int(reason_counts.get(reason) or 0) + 1
        if reason == "source_error_cooldown":
            cooldown_skipped += 1
    cooldown_sources = [row for row in cooldown.get("sources") or [] if isinstance(row, dict)]
    persistent_quarantine_count = sum(
        1
        for row in cooldown_sources
        if str(row.get("cooldown_kind") or "").strip().lower() == "persistent_source_error_quarantine"
    )
    if selected_count <= 0 and skipped_count <= 0 and not cooldown_sources:
        return {}
    selected_source_names = []
    for source in selected_sources:
        name = str(source.get("source_name") or source.get("source_base_name") or source.get("source_id") or "").strip()
        if name and name not in selected_source_names:
            selected_source_names.append(name)
    skipped_source_names = []
    for source in skipped_sources:
        name = str(source.get("source_name") or source.get("source_base_name") or source.get("source_id") or "").strip()
        if name and name not in skipped_source_names:
            skipped_source_names.append(name)
    out = {
        "selected_count": selected_count,
        "skipped_count": skipped_count,
        "source_error_cooldown_skipped_count": cooldown_skipped,
        "persistent_quarantine_source_count": int(safe_float(cooldown.get("quarantine_source_count"), 0))
        or persistent_quarantine_count,
        "cooldown_source_count": int(safe_float(cooldown.get("source_count"), 0)) or len(cooldown_sources),
        "skipped_reason_counts": {
            key: int(value)
            for key, value in sorted(
                reason_counts.items(),
                key=lambda item: (-int(item[1] or 0), str(item[0])),
            )
        },
        "selected_source_names": selected_source_names[:8],
        "skipped_source_names": skipped_source_names[:8],
        "source_pool_reduced": skipped_count > 0,
    }
    return {key: value for key, value in out.items() if value not in (None, "", [], {})}


GENERIC_NO_CANDIDATE_REASONS = {
    "",
    "no_candidate",
    "no_candidates",
    "searched_no_candidates",
    "checked_no_candidates",
    "no_actionable_candidate",
}


NO_CANDIDATE_REASON_LABELS = {
    "suwayomi_volume_metadata_missing": "Suwayomi volume metadata missing",
    "suwayomi_volume_page_evidence_missing": "Suwayomi volume page evidence missing",
    "suwayomi_chapter_page_evidence_missing": "Suwayomi chapter page evidence missing",
    "suwayomi_source_pool_errors_no_match": "Suwayomi source-pool errors with no title match",
    "suwayomi_manga_lookup_partial_failure": "Suwayomi manga lookup partial failure",
    "suwayomi_page_lookup_partial_failure": "Suwayomi page lookup partial failure",
    "suwayomi_title_mismatch_from_search_results": "Suwayomi title mismatch from search results",
    "suwayomi_empty_search_results": "Suwayomi empty search results",
    "suwayomi_no_candidates": "Suwayomi no candidates",
}


def no_candidate_reason_label(reason):
    key = metadata_provider_key(reason)
    if key in NO_CANDIDATE_REASON_LABELS:
        return NO_CANDIDATE_REASON_LABELS[key]
    return str(reason or "").replace("_", " ").strip().title()


def _source_attempt_no_candidate_evidence(raw):
    raw = raw if isinstance(raw, dict) else {}
    candidates = [
        raw.get("no_candidate_evidence"),
        (raw.get("raw") or {}).get("no_candidate_evidence") if isinstance(raw.get("raw"), dict) else None,
    ]
    nested_raw = (raw.get("raw") or {}).get("raw") if isinstance(raw.get("raw"), dict) else None
    if isinstance(nested_raw, dict):
        candidates.append(nested_raw.get("no_candidate_evidence"))
    for candidate in candidates:
        if isinstance(candidate, dict):
            return candidate
    return {}


def _source_attempt_suwayomi_variant_counts(evidence):
    result_count = 0
    matching_manga_count = 0
    for row in evidence.get("variant_result_counts") or []:
        if not isinstance(row, dict):
            continue
        try:
            result_count += int(row.get("results") if row.get("results") not in (None, "") else row.get("result_count") or 0)
        except Exception:
            pass
        try:
            matching_manga_count += int(
                row.get("matching_manga")
                if row.get("matching_manga") not in (None, "")
                else row.get("matching_manga_count") or 0
            )
        except Exception:
            pass
    return result_count, matching_manga_count


def _source_attempt_suwayomi_evidence_summary(evidence):
    evidence = evidence if isinstance(evidence, dict) else {}
    if not evidence:
        return {}
    out = {}
    for key in (
        "provider_payload",
        "wanted_unit_type",
        "wanted_volume",
        "wanted_chapter",
        "no_candidate_reason",
    ):
        value = str(evidence.get(key) or "").strip()
        if value:
            out[key] = value
    int_keys = (
        "search_result_count",
        "matching_manga_count",
        "source_search_error_count",
        "manga_lookup_error_count",
        "page_lookup_error_count",
        "chapter_count",
        "chapter_has_volume_count",
        "pages_by_chapter_count",
    )
    for key in int_keys:
        value = int(safe_float(evidence.get(key), 0))
        if value or (key in evidence and evidence.get(key) not in (None, "")):
            out[key] = value
    variant_result_count, variant_matching_count = _source_attempt_suwayomi_variant_counts(evidence)
    if variant_result_count and not out.get("search_result_count"):
        out["search_result_count"] = int(variant_result_count)
    if variant_matching_count and not out.get("matching_manga_count"):
        out["matching_manga_count"] = int(variant_matching_count)
    observed_values = evidence.get("observed_volume_numbers")
    if observed_values in (None, "", [], {}):
        observed_values = evidence.get("observed_volumes")
    observed = []
    if isinstance(observed_values, (list, tuple)):
        for value in observed_values:
            value = str(value or "").strip()
            if value and value not in observed:
                observed.append(value)
    else:
        value = str(observed_values or "").strip()
        if value:
            observed.append(value)
    if observed:
        out["observed_volumes"] = observed[:12]
        out["observed_volume_count"] = len(observed)
    partial_errors = evidence.get("partial_errors") if isinstance(evidence.get("partial_errors"), list) else []
    if partial_errors:
        stages = {}
        for row in partial_errors:
            if not isinstance(row, dict):
                continue
            stage = metadata_provider_key(row.get("stage"))
            if stage:
                stages[stage] = int(stages.get(stage) or 0) + 1
        if stages:
            out["partial_error_stage_counts"] = {
                key: int(value)
                for key, value in sorted(stages.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
            }
    return out


def _source_attempt_suwayomi_gap_counts(evidence, reason=""):
    evidence_summary = _source_attempt_suwayomi_evidence_summary(evidence)
    if not evidence_summary:
        return {}
    counts = {}

    def bump(key, amount=1):
        key = metadata_provider_key(key)
        if key:
            counts[key] = int(counts.get(key) or 0) + int(amount or 0)

    reason_key = metadata_provider_key(reason or evidence_summary.get("no_candidate_reason"))
    if reason_key:
        bump(reason_key)
    wanted_unit_type = metadata_provider_key(evidence_summary.get("wanted_unit_type"))
    wanted_volume = str(evidence_summary.get("wanted_volume") or "").strip()
    wanted_chapter = str(evidence_summary.get("wanted_chapter") or "").strip()
    if wanted_unit_type:
        bump(f"wanted_{wanted_unit_type}_payloads")
    elif wanted_volume:
        bump("wanted_volume_payloads")
    elif wanted_chapter:
        bump("wanted_chapter_payloads")
    matching_manga_count = int(safe_float(evidence_summary.get("matching_manga_count"), 0))
    chapter_count = int(safe_float(evidence_summary.get("chapter_count"), 0))
    chapter_has_volume_count = int(safe_float(evidence_summary.get("chapter_has_volume_count"), 0))
    pages_by_chapter_count = int(safe_float(evidence_summary.get("pages_by_chapter_count"), 0))
    if matching_manga_count > 0:
        bump("matching_manga_payloads")
    if chapter_count > 0:
        bump("chapter_payloads")
    wants_volume = wanted_unit_type == "volume" or bool(wanted_volume)
    wants_chapter = wanted_unit_type == "chapter" or bool(wanted_chapter)
    if wants_volume and chapter_count > 0 and chapter_has_volume_count <= 0:
        bump("volume_metadata_missing_payloads")
    if wants_volume and chapter_count > 0 and pages_by_chapter_count <= 0:
        bump("volume_page_evidence_missing_payloads")
    if wants_chapter and chapter_count > 0 and pages_by_chapter_count <= 0:
        bump("chapter_page_evidence_missing_payloads")
    for key in ("source_search_error_count", "manga_lookup_error_count", "page_lookup_error_count"):
        if int(safe_float(evidence_summary.get(key), 0)) > 0:
            bump(key.replace("_count", "_payloads"))
    return counts


def _source_attempt_suwayomi_no_candidate_reason(evidence):
    evidence = evidence if isinstance(evidence, dict) else {}
    reason = metadata_provider_key(evidence.get("no_candidate_reason"))
    if reason:
        return reason
    result_count = int(safe_float(evidence.get("search_result_count"), 0))
    matching_manga_count = int(safe_float(evidence.get("matching_manga_count"), 0))
    if result_count <= 0 or matching_manga_count <= 0:
        variant_result_count, variant_matching_count = _source_attempt_suwayomi_variant_counts(evidence)
        result_count = result_count or variant_result_count
        matching_manga_count = matching_manga_count or variant_matching_count
    source_search_error_count = int(safe_float(evidence.get("source_search_error_count"), 0))
    manga_lookup_error_count = int(safe_float(evidence.get("manga_lookup_error_count"), 0))
    page_lookup_error_count = int(safe_float(evidence.get("page_lookup_error_count"), 0))
    partial_errors = evidence.get("partial_errors") if isinstance(evidence.get("partial_errors"), list) else []
    if partial_errors:
        source_search_error_count = source_search_error_count or sum(
            1
            for row in partial_errors
            if isinstance(row, dict) and str(row.get("stage") or "") == "source_search"
        )
        manga_lookup_error_count = manga_lookup_error_count or sum(
            1
            for row in partial_errors
            if isinstance(row, dict)
            and str(row.get("stage") or "") in {"manga_chapters", "manga_chapters_no_meta_fallback"}
        )
        page_lookup_error_count = page_lookup_error_count or sum(
            1
            for row in partial_errors
            if isinstance(row, dict)
            and str(row.get("stage") or "") in {"chapter_pages", "chapter_pages_no_meta_fallback"}
        )
    wanted_volume = str(evidence.get("wanted_volume") or "").strip()
    wanted_chapter = str(evidence.get("wanted_chapter") or "").strip()
    chapter_count = int(safe_float(evidence.get("chapter_count"), 0))
    chapter_has_volume_count = int(safe_float(evidence.get("chapter_has_volume_count"), 0))
    pages_by_chapter_count = int(safe_float(evidence.get("pages_by_chapter_count"), 0))
    if wanted_volume and matching_manga_count and chapter_count and chapter_has_volume_count <= 0:
        return "suwayomi_volume_metadata_missing"
    if wanted_volume and matching_manga_count and chapter_count and pages_by_chapter_count <= 0:
        return "suwayomi_volume_page_evidence_missing"
    if wanted_chapter and matching_manga_count and chapter_count and pages_by_chapter_count <= 0:
        return "suwayomi_chapter_page_evidence_missing"
    if source_search_error_count and not matching_manga_count:
        return "suwayomi_source_pool_errors_no_match"
    if manga_lookup_error_count and matching_manga_count:
        return "suwayomi_manga_lookup_partial_failure"
    if page_lookup_error_count and matching_manga_count:
        return "suwayomi_page_lookup_partial_failure"
    if result_count and not matching_manga_count:
        return "suwayomi_title_mismatch_from_search_results"
    if not result_count:
        return "suwayomi_empty_search_results"
    return "suwayomi_no_candidates"


def source_attempt_no_candidate_reason(attempt=None, raw=None):
    attempt = attempt if isinstance(attempt, dict) else {}
    raw = raw if isinstance(raw, dict) else {}
    evidence = _source_attempt_no_candidate_evidence(raw)
    evidence_reason = metadata_provider_key(evidence.get("no_candidate_reason") if isinstance(evidence, dict) else "")
    if evidence_reason:
        return evidence_reason
    provider_payload = metadata_provider_key(evidence.get("provider_payload") if isinstance(evidence, dict) else "")
    source_key = metadata_provider_key(
        attempt.get("provider_key")
        or attempt.get("provider_id")
        or attempt.get("source")
        or raw.get("provider_id")
        or raw.get("source")
        or ""
    )
    if provider_payload == "suwayomi" or source_key == "suwayomi":
        if evidence:
            return _source_attempt_suwayomi_no_candidate_reason(evidence)
    fallback = metadata_provider_key(
        attempt.get("failure_reason")
        or attempt.get("reason")
        or raw.get("failure_reason")
        or raw.get("reason")
        or ""
    )
    if fallback in GENERIC_NO_CANDIDATE_REASONS:
        return ""
    return fallback if fallback in NO_CANDIDATE_REASON_LABELS else ""


def _suwayomi_source_problem_key(source_id="", source_name=""):
    source_id = str(source_id or "").strip()
    if source_id:
        return f"id:{source_id}"
    source_name = str(source_name or "").strip()
    return f"name:{normalize_key(source_name)}" if source_name else ""


def _suwayomi_problem_source_item(items, *, source_id="", source_name=""):
    key = _suwayomi_source_problem_key(source_id, source_name)
    if not key:
        return None
    item = items.setdefault(
        key,
        {
            "source_id": str(source_id or "").strip(),
            "source_name": str(source_name or "").strip(),
            "error_count": 0,
            "runtime_skip_count": 0,
            "source_search_error_count": 0,
            "queries": {},
            "errors": {},
            "queues": {},
            "series": {},
            "latest_at": 0.0,
        },
    )
    if source_id and not item.get("source_id"):
        item["source_id"] = str(source_id or "").strip()
    if source_name and not item.get("source_name"):
        item["source_name"] = str(source_name or "").strip()
    return item


def _suwayomi_add_problem_source_evidence(
    items,
    evidence,
    row,
    *,
    kind,
    source_id="",
    source_name="",
    query="",
    error="",
):
    item = _suwayomi_problem_source_item(items, source_id=source_id, source_name=source_name)
    if not item:
        return
    item["error_count"] = int(item.get("error_count") or 0) + 1
    if kind == "runtime_skip":
        item["runtime_skip_count"] = int(item.get("runtime_skip_count") or 0) + 1
    elif kind == "source_search_error":
        item["source_search_error_count"] = int(item.get("source_search_error_count") or 0) + 1
    query = str(query or "").strip()
    if query:
        item["queries"][query] = int(item["queries"].get(query) or 0) + 1
    error = str(error or "").strip()
    if error:
        item["errors"][error] = int(item["errors"].get(error) or 0) + 1
    queue_id = str(row["queue_id"] or "").strip()
    if queue_id:
        item["queues"][queue_id] = int(item["queues"].get(queue_id) or 0) + 1
        evidence["queues"][queue_id] = True
    series = str(row["series"] or row["attempt_title"] or "").strip()
    if series:
        item["series"][series] = int(item["series"].get(series) or 0) + 1
        evidence["series"][series] = True
    seen_at = safe_float(row["attempt_at"], 0.0)
    if seen_at > safe_float(item.get("latest_at"), 0.0):
        item["latest_at"] = seen_at
        item["latest_at_iso"] = utc_stamp(seen_at)


def _suwayomi_source_health_recommendation_snapshot(con, *, limit=5000):
    if con is None or not table_exists(con, "source_attempts") or not table_exists(con, "provider_configs"):
        return {}
    provider_row = con.execute("select settings_json from provider_configs where id='suwayomi' limit 1").fetchone()
    if not provider_row:
        return {}
    provider_settings = json_loads(provider_row["settings_json"] or "{}", {})
    provider_settings = provider_settings if isinstance(provider_settings, dict) else {}
    disabled_ids = set(
        _provider_setting_values(
            provider_settings,
            ("suwayomi_disabled_source_ids", "disabled_source_ids", "excluded_source_ids"),
        )
    )
    disabled_name_keys = set(
        _provider_setting_values(
            provider_settings,
            ("suwayomi_disabled_source_names", "disabled_source_names", "excluded_source_names"),
            normalize=True,
        )
    )
    rows = con.execute(
        """
        select sa.queue_id, sa.series_id, sa.issue_id, sa.status, sa.failure_reason,
               sa.title as attempt_title, sa.raw_json,
               coalesce(sa.completed_at, sa.started_at, 0) as attempt_at,
               coalesce(s.title, sa.title, q.query, 'Unknown') as series,
               i.issue_number
        from source_attempts sa
        left join queue_items q on q.id = sa.queue_id
        left join series s on s.id = sa.series_id
        left join issues i on i.id = sa.issue_id
        where lower(coalesce(sa.provider_id, sa.provider, sa.source, '')) = 'suwayomi'
        order by coalesce(sa.completed_at, sa.started_at, 0) desc, sa.id desc
        limit ?
        """,
        (max(1, min(int(limit or 5000), 10000)),),
    ).fetchall()
    sources = {}
    evidence = {"queues": {}, "series": {}}
    for row in rows:
        raw = json_loads(row["raw_json"] or "{}", {})
        fetch = _source_attempt_fetch_evidence(raw)
        if not fetch:
            continue
        for skip in fetch.get("source_runtime_skips") or []:
            if not isinstance(skip, dict):
                continue
            _suwayomi_add_problem_source_evidence(
                sources,
                evidence,
                row,
                kind="runtime_skip",
                source_id=skip.get("source_id"),
                source_name=skip.get("source_display_name") or skip.get("source_name"),
                query=skip.get("query"),
                error=skip.get("previous_error") or skip.get("reason"),
            )
        for error in fetch.get("partial_errors") or []:
            if not isinstance(error, dict):
                continue
            if str(error.get("stage") or "").strip() != "source_search":
                continue
            _suwayomi_add_problem_source_evidence(
                sources,
                evidence,
                row,
                kind="source_search_error",
                source_id=error.get("source_id"),
                source_name=error.get("source_display_name") or error.get("source_name"),
                query=error.get("query"),
                error=error.get("error"),
            )
    if not sources:
        return {}
    problem_sources = []
    for item in sources.values():
        source_id = str(item.get("source_id") or "").strip()
        source_name = str(item.get("source_name") or source_id or "unknown").strip()
        source_name_key = normalize_key(source_name)
        already_disabled = bool(
            (source_id and source_id in disabled_ids)
            or (source_name_key and source_name_key in disabled_name_keys)
        )
        query_rows = _sorted_count_rows(item.get("queries") or {}, limit=4)
        error_rows = _sorted_count_rows(item.get("errors") or {}, limit=4)
        problem_sources.append(
            {
                "source_id": source_id,
                "source_name": source_name,
                "already_disabled": already_disabled,
                "error_count": int(item.get("error_count") or 0),
                "runtime_skip_count": int(item.get("runtime_skip_count") or 0),
                "source_search_error_count": int(item.get("source_search_error_count") or 0),
                "queue_count": len(item.get("queues") or {}),
                "series_count": len(item.get("series") or {}),
                "query_counts": query_rows,
                "error_counts": error_rows,
                "latest_at": safe_float(item.get("latest_at"), 0.0),
                "latest_at_iso": item.get("latest_at_iso"),
            }
        )
    problem_sources = sorted(
        problem_sources,
        key=lambda row: (-int(row.get("error_count") or 0), str(row.get("source_name") or "")),
    )
    pending_problem_sources = [row for row in problem_sources if not row.get("already_disabled")]
    already_disabled_count = len(problem_sources) - len(pending_problem_sources)
    recommended_ids = [row["source_id"] for row in pending_problem_sources if str(row.get("source_id") or "").strip()]
    recommended_names = [
        row["source_name"]
        for row in pending_problem_sources
        if str(row.get("source_name") or "").strip() and not str(row.get("source_id") or "").strip()
    ]
    recommended_settings_patch = {}
    if recommended_ids:
        recommended_settings_patch["suwayomi_disabled_source_ids"] = recommended_ids[:10]
    if recommended_names:
        recommended_settings_patch["suwayomi_disabled_source_names"] = recommended_names[:10]
    queue_count = len(evidence.get("queues") or {})
    series_count = len(evidence.get("series") or {})
    source_names = [row.get("source_name") or row.get("source_id") for row in problem_sources]
    sample_text = ", ".join(str(name) for name in source_names[:3] if str(name or "").strip())
    summary = (
        f"Suwayomi source health recommends reviewing {len(problem_sources)} source"
        f"{'s' if len(problem_sources) != 1 else ''}"
    )
    if queue_count:
        summary += f" seen across {queue_count} queue row{'s' if queue_count != 1 else ''}"
    if sample_text:
        summary += f": {sample_text}"
    if already_disabled_count and pending_problem_sources:
        summary += f"; {already_disabled_count} already disabled in Settings"
    elif already_disabled_count and not pending_problem_sources:
        summary += "; all are already disabled in Settings"
    if recommended_settings_patch:
        next_action = (
            "Review Suwayomi Settings and add repeated failing sources to "
            "`suwayomi_disabled_source_ids` or `suwayomi_disabled_source_names`; "
            "the source-search cooldown/quarantine can keep running and matching gates stay unchanged."
        )
    else:
        next_action = (
            "No Suwayomi source-disable action is pending; repeated failing sources are already disabled "
            "or only present as historical source-health evidence. Keep automatic retry on the remaining source pool."
        )
    return {
        "suwayomi": {
            "provider_id": "suwayomi",
            "recommendation_key": "suwayomi_source_health_settings_review",
            "recommendation_label": "Review Suwayomi source health",
            "queue_filter": "provider_wait",
            "queue_filter_label": "Provider Wait",
            "actionability": "settings_review" if recommended_settings_patch else "settings_applied",
            "source_mode_change": "none",
            "auto_enable": False,
            "queue_count": queue_count,
            "series_count": series_count,
            "series_sample": list((evidence.get("series") or {}).keys())[:5],
            "summary": summary,
            "detail": summary,
            "next_action": next_action,
            "recommended_provider_ids": ["suwayomi"],
            "source_settings_fields": [
                "suwayomi_disabled_source_ids",
                "suwayomi_disabled_source_names",
                "suwayomi_skip_source_after_search_error",
                "suwayomi_source_error_cooldown_enabled",
                "suwayomi_source_error_quarantine_enabled",
                "suwayomi_source_error_quarantine_seconds",
                "suwayomi_source_error_quarantine_threshold",
            ],
            "problem_sources": problem_sources[:10],
            "recommended_disabled_source_ids": recommended_ids[:10],
            "recommended_disabled_source_names": recommended_names[:10],
            "recommended_settings_patch": recommended_settings_patch,
            "already_disabled_source_count": already_disabled_count,
            "pending_disabled_source_count": len(pending_problem_sources),
            "apply_action": {
                "endpoint": "/api/inkdrop-settings/provider/recommendation/apply",
                "provider_id": "suwayomi",
                "recommendation_key": "suwayomi_source_health_settings_review",
                "action_label": "Apply source disables",
                "settings_patch": recommended_settings_patch,
            }
            if recommended_settings_patch
            else None,
            "source_runtime_skip_count": sum(int(row.get("runtime_skip_count") or 0) for row in problem_sources),
            "source_search_error_count": sum(int(row.get("source_search_error_count") or 0) for row in problem_sources),
        }
    }


DIRECT_SOURCE_PROBLEM_RECOMMENDATIONS = {
    "comicscodes": {
        "label": "ComicsCodes",
        "settings_fields": [
            "enabled",
            "source_order",
            "per_provider_limits",
            "retry_backoff",
        ],
    },
}


def _direct_source_problem_recommendation_snapshot(con, *, now=None, limit=5000):
    if con is None or not table_exists(con, "source_attempts") or not table_exists(con, "provider_configs"):
        return {}
    now = time.time() if now is None else float(now)
    recent_after = now - 86400
    recommendations = {}
    target_ids = tuple(sorted(DIRECT_SOURCE_PROBLEM_RECOMMENDATIONS))
    placeholders = ",".join("?" for _ in target_ids)
    if not placeholders:
        return {}
    configured_rows = con.execute(
        f"""
        select id, display_name, provider_type, enabled
        from provider_configs
        where lower(id) in ({placeholders})
        """,
        target_ids,
    ).fetchall()
    configured = {provider_activity_key(row["id"]): row for row in configured_rows}
    if not configured:
        return {}
    rows = con.execute(
        f"""
        select lower(coalesce(nullif(provider_id, ''), nullif(provider, ''), nullif(source, ''), '')) as provider_key,
               outcome,
               status,
               queue_id,
               coalesce(completed_at, started_at, 0) as attempt_at
        from source_attempts
        where lower(coalesce(nullif(provider_id, ''), nullif(provider, ''), nullif(source, ''), '')) in ({placeholders})
        order by coalesce(completed_at, started_at, 0) desc
        limit ?
        """,
        (*target_ids, max(1, min(int(limit or 5000), 10000))),
    ).fetchall()
    stats = {}
    for row in rows:
        provider_key = provider_activity_key(row["provider_key"])
        if provider_key not in configured:
            continue
        item = stats.setdefault(
            provider_key,
            {
                "total": {"productive": 0, "no_candidate": 0, "problem": 0, "neutral": 0},
                "recent": {"productive": 0, "no_candidate": 0, "problem": 0, "neutral": 0},
                "queues": {},
                "status_counts": {},
                "latest_at": 0.0,
            },
        )
        outcome = source_attempt_outcome(row["status"]) if not str(row["outcome"] or "").strip() else metadata_provider_key(row["outcome"])
        if outcome not in item["total"]:
            outcome = "neutral"
        item["total"][outcome] = int(item["total"].get(outcome) or 0) + 1
        attempt_at = safe_float(row["attempt_at"], 0.0)
        if attempt_at >= recent_after:
            item["recent"][outcome] = int(item["recent"].get(outcome) or 0) + 1
        queue_id = str(row["queue_id"] or "").strip()
        if queue_id:
            item["queues"][queue_id] = True
        status_key = metadata_provider_key(row["status"])
        if status_key:
            item["status_counts"][status_key] = int(item["status_counts"].get(status_key) or 0) + 1
        if attempt_at > safe_float(item.get("latest_at"), 0.0):
            item["latest_at"] = attempt_at
    for provider_id, item in stats.items():
        provider_row = configured.get(provider_id)
        if not provider_row or not int(provider_row["enabled"] or 0):
            continue
        total = item.get("total") or {}
        recent = item.get("recent") or {}
        productive = int(total.get("productive") or 0)
        problem = int(total.get("problem") or 0)
        no_candidate = int(total.get("no_candidate") or 0)
        recent_productive = int(recent.get("productive") or 0)
        recent_problem = int(recent.get("problem") or 0)
        total_attempts = productive + problem + no_candidate + int(total.get("neutral") or 0)
        queue_count = len(item.get("queues") or {})
        problem_ratio = (problem / total_attempts) if total_attempts else 0.0
        low_yield = productive <= 1 and no_candidate >= 10 and no_candidate >= max(10, productive * 20)
        broken_yield = productive <= 1 and problem >= 25 and problem >= max(25, productive * 25)
        recent_broken = recent_productive <= 0 and recent_problem >= 10
        if not (broken_yield or recent_broken or (low_yield and queue_count >= 10)):
            continue
        provider_meta = DIRECT_SOURCE_PROBLEM_RECOMMENDATIONS.get(provider_id, {})
        provider_label = str(provider_row["display_name"] or provider_meta.get("label") or source_display_label(provider_id)).strip()
        reason = "high_problem_low_productivity" if broken_yield or recent_broken else "high_no_candidate_low_productivity"
        status_rows = _sorted_count_rows(item.get("status_counts") or {}, limit=5)
        summary = (
            f"{provider_label} looks low-producing: {productive} productive, "
            f"{problem} problem, {no_candidate} no-candidate attempt"
            f"{'s' if (productive + problem + no_candidate) != 1 else ''}"
        )
        if queue_count:
            summary += f" across {queue_count} queue row{'s' if queue_count != 1 else ''}"
        next_action = (
            f"Consider pausing or demoting {provider_label} until source health improves; "
            "keep higher-confidence SLSKD, Prowlarr/NZB/torrent, pack, and API sources ahead of it."
        )
        recommendations[provider_id] = {
            "provider_id": provider_id,
            "recommendation_key": "pause_problem_direct_source",
            "recommendation_label": "Pause or demote low-producing source",
            "queue_filter": "source_noise",
            "queue_filter_label": "Source Noise",
            "actionability": "settings_review",
            "source_mode_change": "pause_or_demote",
            "auto_enable": False,
            "apply_action": None,
            "queue_count": queue_count,
            "series_count": 0,
            "series_sample": [],
            "summary": summary,
            "detail": summary,
            "next_action": next_action,
            "recommended_provider_ids": [provider_id],
            "source_settings_fields": list(provider_meta.get("settings_fields") or []),
            "reason": reason,
            "total_attempts": total_attempts,
            "productive_count": productive,
            "problem_count": problem,
            "no_candidate_count": no_candidate,
            "recent_productive_count": recent_productive,
            "recent_problem_count": recent_problem,
            "problem_ratio": round(problem_ratio, 4),
            "status_counts": status_rows,
            "latest_at": safe_float(item.get("latest_at"), 0.0),
            "latest_at_iso": utc_stamp(item.get("latest_at")) if safe_float(item.get("latest_at"), 0.0) > 0 else "",
        }
    return recommendations


def source_provider_recommendation_snapshot(con, now=None, limit=5000):
    """Return settings-backed provider recommendations from source-coverage queue pressure."""

    if con is None or not table_exists(con, "queue_items") or not table_exists(con, "provider_configs"):
        return {}
    now = time.time() if now is None else float(now)
    limit = max(1, min(int(limit or 5000), 10000))
    configured = {
        provider_activity_key(row["id"])
        for row in con.execute("select id from provider_configs")
        if provider_activity_key(row["id"])
    }
    target_ids = {
        provider_id
        for provider_id in (
            "prowlarr_torrentleech_comics",
            "prowlarr_dognzb_comics",
            "prowlarr_kat_comics",
            "prowlarr_pirate_bay_comics",
            "prowlarr_torrentdownload_comics",
            "prowlarr_nyaa",
            "prowlarr_tokyo_toshokan_manga",
        )
        if provider_id in configured
    }
    if not target_ids and "suwayomi" not in configured:
        return {}
    attempt_count_expr = (
        """
               (
                   select count(*)
                   from source_attempts sa
                   where sa.queue_id = q.id
               ) as attempt_count
        """
        if table_exists(con, "source_attempts")
        else "0 as attempt_count"
    )
    rows = con.execute(
        f"""
        select q.id as queue_id, q.series_id, q.query, q.current_source, q.last_event,
               q.retry_after, q.retry_after_iso, q.raw_json, q.updated_at,
               q.source_order_json, q.recovery_steps_json,
               coalesce(s.title, q.query, 'Unknown') as series,
               coalesce(s.publisher, '') as publisher,
               coalesce(s.media_type, '') as media_type,
               i.issue_number,
               {attempt_count_expr}
        from queue_items q
        left join series s on s.id = q.series_id
        left join issues i on i.id = q.issue_id
        where q.active = 1 and q.state = 'queued'
        order by coalesce(q.updated_at, q.created_at, 0) desc
        limit ?
        """,
        (limit,),
    ).fetchall()
    recommendations = {}
    for row in rows:
        retry_raw = apply_queue_retry_columns_to_raw({}, row)
        if not retry_raw and row["raw_json"] and "retry_after" in row["raw_json"]:
            retry_raw = json_loads(row["raw_json"] or "{}", {})
        retry = queue_retry_info(retry_raw, now)
        plan = source_plan_from_values(
            row["source_order_json"],
            row["recovery_steps_json"],
            row["current_source"],
            row["last_event"],
        )
        reason_key = queue_wait_reason_key("queued", row["current_source"], row["last_event"])
        cause = automation_cause_for_row(
            {
                "state": "queued",
                "current_source": row["current_source"],
                "last_event": row["last_event"],
                "wait_reason_key": reason_key,
                "wait_reason_label": QUEUE_WAIT_REASON_LABELS.get(reason_key, reason_key),
                "retry": retry,
                "attempt_count": int(row["attempt_count"] or 0),
                "source_plan": plan,
            }
        )
        if str(cause.get("category") or "").strip().lower() != "source_coverage":
            continue
        provider_ids = [
            provider_id
            for provider_id in _source_recommendation_provider_ids(row["series"], row["publisher"], row["media_type"])
            if provider_id in target_ids
        ]
        if not provider_ids:
            continue
        retry_after = safe_float(retry.get("retry_after"))
        retry_bucket = "due" if retry.get("retry_due") else ("later" if retry_after > 0 else "unscheduled")
        for provider_id in provider_ids:
            item = recommendations.setdefault(
                provider_id,
                {
                    "provider_id": provider_id,
                    "recommendation_key": "targeted_prowlarr_source_coverage",
                    "recommendation_label": "Recommended for source coverage",
                    "queue_filter": "no_candidate",
                    "queue_filter_label": "No Candidate",
                    "actionability": "settings_review",
                    "source_mode_change": "none",
                    "auto_enable": False,
                    "queue_count": 0,
                    "due": 0,
                    "later": 0,
                    "unscheduled": 0,
                    "series": {},
                    "publishers": {},
                    "media_types": {},
                    "samples": [],
                },
            )
            item["queue_count"] = int(item.get("queue_count") or 0) + 1
            item[retry_bucket] = int(item.get(retry_bucket) or 0) + 1
            series_title = str(row["series"] or row["query"] or "Unknown").strip() or "Unknown"
            series_item = item["series"].setdefault(
                series_title,
                {
                    "series": series_title,
                    "series_id": row["series_id"],
                    "publisher": row["publisher"],
                    "media_type": row["media_type"],
                    "count": 0,
                },
            )
            series_item["count"] = int(series_item.get("count") or 0) + 1
            publisher_key = str(row["publisher"] or "unknown").strip() or "unknown"
            item["publishers"][publisher_key] = int(item["publishers"].get(publisher_key) or 0) + 1
            media_key = str(row["media_type"] or "unknown").strip() or "unknown"
            item["media_types"][media_key] = int(item["media_types"].get(media_key) or 0) + 1
            if len(item["samples"]) < 5:
                item["samples"].append(
                    {
                        "queue_id": row["queue_id"],
                        "series": series_title,
                        "series_id": row["series_id"],
                        "issue_number": row["issue_number"],
                        "query": row["query"],
                        "publisher": row["publisher"],
                        "media_type": row["media_type"],
                        "retry_bucket": retry_bucket,
                        "next_source": plan.get("next_acquisition_source") or plan.get("next_concrete_source") or "",
                    }
                )
    out = {}
    for provider_id, item in recommendations.items():
        series_rows = sorted(
            item.get("series", {}).values(),
            key=lambda row: (-int(row.get("count") or 0), str(row.get("series") or "")),
        )
        queue_count = int(item.get("queue_count") or 0)
        series_count = len(series_rows)
        series_sample = series_rows[:5]
        sample_names = [str(row.get("series") or "") for row in series_sample if str(row.get("series") or "").strip()]
        provider_label = source_display_label(provider_id)
        sample_text = ", ".join(sample_names[:3])
        summary = (
            f"{provider_label} is recommended for {queue_count} source-coverage row"
            f"{'s' if queue_count != 1 else ''} across {series_count} series"
        )
        if sample_text:
            summary = f"{summary}: {sample_text}"
        next_action = (
            f"Enable or configure {provider_label} in Settings to add targeted Prowlarr coverage for "
            f"{queue_count} stalled no-candidate row{'s' if queue_count != 1 else ''}; matching and download gates stay unchanged."
        )
        out[provider_id] = {
            **item,
            "series": series_sample,
            "series_count": series_count,
            "series_sample": sample_names[:5],
            "publisher_counts": _sorted_count_rows(item.get("publishers") or {}, limit=6),
            "media_type_counts": _sorted_count_rows(item.get("media_types") or {}, limit=6),
            "summary": summary,
            "detail": summary,
            "next_action": next_action,
            "recommended_provider_ids": [provider_id],
        }
    out.update(_direct_source_problem_recommendation_snapshot(con, now=now, limit=limit))
    out.update(_suwayomi_source_health_recommendation_snapshot(con, limit=limit))
    return out


def source_plan_from_values(source_order, recovery_steps, current_source=None, last_event=None):
    order = json_loads(source_order or "[]", []) if isinstance(source_order, str) else source_order
    recovery = json_loads(recovery_steps or "[]", []) if isinstance(recovery_steps, str) else recovery_steps
    order = [str(item).strip().lower() for item in (order or []) if str(item or "").strip()]
    recovery = [str(item).strip().lower() for item in (recovery or []) if str(item or "").strip()]
    current = str(current_source or "").strip().lower()
    event = str(last_event or "").strip().lower()
    if current in {"failed_retry", "retry"} or "retrying next" in event:
        next_source = recovery[0] if recovery else "failed_retry"
    elif current and current not in {"source_ladder", "queue"}:
        next_source = current
    elif (
        "automatic sources had no actionable candidate" in event
        or "automatic sources exhausted" in event
        or "low-confidence slskd candidates" in event
        or "not safe enough to auto-pick" in event
        or "not confident enough to auto-pick" in event
        or "source ladder attempted" in event
        or "continuing source ladder" in event
        or "source errored" in event
        or "download api hiccup" in event
        or "searching slskd candidates" in event
        or ("retry scheduled" in event and ("no actionable" in event or "source ladder" in event))
    ):
        next_source = "source_ladder"
    else:
        next_source = order[0] if order else "source_ladder"
    next_concrete_source = next_source
    if next_source == "source_ladder":
        next_concrete_source = order[0] if order else "source_ladder"
    elif next_source in {"failed_retry", "retry"}:
        next_concrete_source = recovery[0] if recovery else next_source
    if next_source in {"source_ladder", "local", "queue"}:
        next_acquisition_source = first_acquisition_source(order) or next_concrete_source
    elif next_source in {"failed_retry", "retry"}:
        next_acquisition_source = first_acquisition_source(recovery) or next_concrete_source
    else:
        next_acquisition_source = next_source
    labels = [source_display_label(item) for item in order]
    recovery_labels = [source_display_label(item) for item in recovery]
    return {
        "source_order": order,
        "source_order_labels": labels,
        "recovery_steps": recovery,
        "recovery_step_labels": recovery_labels,
        "next_source": next_source,
        "next_source_label": source_display_label(next_source),
        "next_concrete_source": next_concrete_source,
        "next_concrete_source_label": source_display_label(next_concrete_source),
        "next_acquisition_source": next_acquisition_source,
        "next_acquisition_source_label": source_display_label(next_acquisition_source),
        "summary": " -> ".join(labels),
        "recovery_summary": " -> ".join(recovery_labels),
    }


def active_source_key(row):
    row = dict(row or {})
    attempt = compact_attempt(row.get("last_attempt"))
    return str(
        row.get("current_source")
        or attempt.get("source")
        or attempt.get("download_client")
        or attempt.get("provider")
        or "source_ladder"
    ).strip().lower()


