            f"{int(item.get('no_attempts') or 0)} never touched" if int(item.get("no_attempts") or 0) else "",
            f"{int(item.get('old_no_attempts') or 0)} old no-attempt" if int(item.get("old_no_attempts") or 0) else "",
            f"{int(item.get('stale_active') or 0)} stale active" if int(item.get("stale_active") or 0) else "",
            f"{int(item.get('due') or 0)} due" if int(item.get("due") or 0) else "",
            f"{int(item.get('later') or 0)} retry later" if int(item.get("later") or 0) else "",
            f"{int(item.get('unscheduled') or 0)} unscheduled" if int(item.get("unscheduled") or 0) else "",
