def source_provider_filter_key(provider_filter):
    value = str(provider_filter or "all").strip().lower().replace("-", "_")
    aliases = {
        "any": "all",
        "source": "all",
        "sources": "all",
        "provider": "all",
        "providers": "all",
        "indexer": "indexers",
        "download_source": "download_sources",
        "direct_download": "download_sources",
        "download_client": "download_clients",
        "paths": "paths_rules",
        "rules": "paths_rules",
        "path": "paths_rules",
        "rule": "paths_rules",
        "adapter": "adapters",
        "metadata_adapter": "adapters",
        "problem": "attention",
        "problems": "attention",
        "needs_attention": "attention",
        "needs_you": "attention",
        "bad": "source_memory",
        "bad_source": "source_memory",
        "bad_sources": "source_memory",
        "bad_candidate": "source_memory",
        "bad_candidates": "source_memory",
        "source_memory": "source_memory",
        "source_memories": "source_memory",
        "source_wait": "provider_wait",
        "provider_wait": "provider_wait",
        "source_limited": "provider_wait",
        "provider_limited": "provider_wait",
    }
    value = aliases.get(value, value)
    return value if value in SOURCE_PROVIDER_FILTERS else "all"


