def queue_provider_filter_key(provider_filter):
    raw = str(provider_filter or "").strip().lower().replace("-", "_").replace(" ", "_")
    if not raw or raw in QUEUE_PROVIDER_FILTER_IGNORE_VALUES:
        return ""
    value = provider_activity_key(raw)
    if not value or value in QUEUE_PROVIDER_FILTER_IGNORE_VALUES:
        return ""
    return value


def queue_row_provider_keys(row):
    row = row if isinstance(row, dict) else {}
    keys = set()

    def add(value):
        key = provider_activity_key(value)
        if key:
            keys.add(key)

    add(row.get("provider_status_provider"))
    add(row.get("current_source"))
    add(row.get("source_key"))
    add(row.get("last_blocking_source"))
    add(row.get("next_acquisition_source"))
    add(row.get("next_concrete_source"))
    health = row.get("provider_health") if isinstance(row.get("provider_health"), dict) else {}
    add(health.get("provider_id"))
    status = row.get("provider_status") if isinstance(row.get("provider_status"), dict) else {}
    add(status.get("provider_id"))
    add(status.get("source_attempt_filter"))
    source_plan = row.get("source_plan") if isinstance(row.get("source_plan"), dict) else {}
    add(source_plan.get("next_acquisition_source"))
    source_evidence = row.get("source_evidence") if isinstance(row.get("source_evidence"), dict) else {}
    add(source_evidence.get("last_provider"))
    add(source_evidence.get("last_source"))
    add(source_evidence.get("next_acquisition_source"))
    add(source_evidence.get("attempt_filter"))
    automation_status = row.get("automation_status") if isinstance(row.get("automation_status"), dict) else {}
    add(automation_status.get("last_blocking_source"))
    add(automation_status.get("download_task_source"))
    add(automation_status.get("next_acquisition_source"))
    last_attempt = compact_attempt(row.get("last_attempt"))
    add(last_attempt.get("provider_id"))
    add(last_attempt.get("provider"))
    add(last_attempt.get("download_client"))
    add(last_attempt.get("source"))
    download_task = row.get("download_task") if isinstance(row.get("download_task"), dict) else {}
    add(download_task.get("provider_id"))
    add(download_task.get("provider"))
    add(download_task.get("download_client"))
    add(download_task.get("source"))
    add(download_task.get("protocol"))
    return keys


def queue_row_matches_provider_filter(row, provider_filter):
    provider_filter = queue_provider_filter_key(provider_filter)
    if not provider_filter:
        return True
    aliases = {provider_filter}
    for alias in SOURCE_ATTEMPT_ALIASES.get(provider_filter, ()):
        aliases.add(provider_activity_key(alias))
    aliases = {alias for alias in aliases if alias}
    return bool(queue_row_provider_keys(row) & aliases)


def queue_provider_filter_rows(rows, provider_filter, limit=None):
    provider_filter = queue_provider_filter_key(provider_filter)
    if not provider_filter:
        out = list(rows or [])
    else:
        out = [row for row in (rows or []) if queue_row_matches_provider_filter(row, provider_filter)]
    if limit is not None:
        return out[: max(0, int(limit or 0))]
    return out


def source_provider_type_label(provider_type):
    key = str(provider_type or "").strip().lower()
    return SOURCE_PROVIDER_TYPE_LABELS.get(key, source_display_label(key or "provider"))


def source_provider_ownership(provider_id, provider_type=None, source=None):
    provider_id = str(provider_id or "").strip().lower()
    provider_type = str(provider_type or "").strip().lower()
    source = str(source or "").strip().lower()
    if provider_id == "kapowarr" or provider_type == "metadata_adapter":
        return "adapter"
    known_native = set(SOURCE_PROVIDER_ROLES) | set(SOURCE_PROVIDER_CAPABILITIES) | set(SOURCE_PROVIDER_CONSUMERS)
    known_native.discard("kapowarr")
    if provider_id in known_native:
        return "native"
    if provider_type in {"metadata", "indexer", "download_source", "direct_download", "download_client", "library", "path", "rule"}:
        return "native"
    if source == "user":
        return "user"
    return "native"


def source_provider_health(provider):
    provider = provider if isinstance(provider, dict) else {}
    health = provider.get("provider_health") if isinstance(provider.get("provider_health"), dict) else None
    if not health:
        health = provider.get("health") if isinstance(provider.get("health"), dict) else None
    return health or {}


def source_provider_health_problem(provider):
    health = source_provider_health(provider)
    return provider_health_is_problem(health)


def source_provider_is_download_source_type(provider_type):
    provider_type = str(provider_type or "").strip().lower()
    return provider_type in {"direct_download", "download_source", "metadata_download_source"}


def source_provider_is_inactive_tracking(provider):
    provider = provider if isinstance(provider, dict) else {}
    if not provider.get("enabled"):
        return False
    if source_provider_health_problem(provider):
        return False
    provider_type = str(provider.get("provider_type") or "").strip().lower()
    if not source_provider_is_download_source_type(provider_type):
        return False
    activity = provider.get("activity") if isinstance(provider.get("activity"), dict) else {}
    queue_impact = provider.get("queue_impact") if isinstance(provider.get("queue_impact"), dict) else {}
    if int(activity.get("recent_attempts") or 0) > 0:
        return False
    if int(activity.get("total_attempts") or 0) > 0:
        return False
    if int(activity.get("bad_source_candidates") or 0) > 0:
        return False
    if int(queue_impact.get("active_queue") or queue_impact.get("queue_items") or 0) > 0:
        return False
    return int(activity.get("series_count") or 0) > 0 or int(activity.get("monitored_series_count") or 0) > 0


def source_provider_ui_visibility(provider, recommendation=None):
    provider = provider if isinstance(provider, dict) else {}
    recommendation = recommendation if isinstance(recommendation, dict) else {}
    provider_id = provider_activity_key(provider.get("id") or provider.get("provider_id"))
    settings = provider.get("settings") if isinstance(provider.get("settings"), dict) else {}
    recommendation_key = str(recommendation.get("recommendation_key") or "").strip()
    if provider_id in {"getcomics", "rss_getcomics"}:
        return "experimental", "end_to_end_import_not_certified"
    if settings.get("source_template") and str(settings.get("implementation_status") or "").lower() != "implemented":
        return "experimental_hidden", "implementation_not_available"
    if source_provider_is_inactive_tracking(provider):
        return "experimental_inactive_tracking", "inactive_tracking"
    if recommendation_key == "pause_problem_direct_source":
        return "experimental_low_producer", "pause_problem_direct_source"
    return "normal", ""


def source_provider_capability_contract(provider):
    provider = provider if isinstance(provider, dict) else {}
    settings = provider.get("settings") if isinstance(provider.get("settings"), dict) else {}
    policy = settings.get("policy") if isinstance(settings.get("policy"), dict) else {}
    raw = provider.get("capabilities") if isinstance(provider.get("capabilities"), list) else []
    keys = {
        re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")
        for value in raw
        if str(value or "").strip()
    }
    implemented = str(settings.get("implementation_status") or "implemented").lower() == "implemented"
    discovery = bool(keys & {"discovery", "feed", "rss", "catalog", "metadata", "local_file_watch", "search"})
    search = "search" in keys
    candidate_production = bool(keys & {"candidate_production", "search", "direct_download", "page_download", "staged_import", "local_file_watch"})
    download = bool(keys & {"download", "direct_download", "page_download", "file_download", "torrent_handoff", "usenet_handoff"})
    import_capability = bool(keys & {"import", "staged_import", "folder_verification", "cbz_packaging"})
    if implemented and policy.get("import_handoff_expectation"):
        import_capability = True
    return {
        "discovery": bool(implemented and discovery),
        "search": bool(implemented and search),
        "candidate_production": bool(implemented and candidate_production),
        "download": bool(implemented and download),
        "import": bool(implemented and import_capability),
        "reported": sorted(keys),
    }


def source_provider_configured(provider):
    provider = provider if isinstance(provider, dict) else {}
    settings = provider.get("settings") if isinstance(provider.get("settings"), dict) else {}
    if not settings.get("source_template"):
        return True
    has_secret_values = settings.get("has_secret_values") if isinstance(settings.get("has_secret_values"), dict) else {}
    return bool(provider.get("enabled") or provider.get("base_url") or provider.get("secret_ref") or has_secret_values)


def source_provider_presentation_visibility(provider, source_ui_visibility):
    provider = provider if isinstance(provider, dict) else {}
    visibility = str(source_ui_visibility or "").strip().lower()
    if visibility.startswith("experimental"):
        return "experimental"
    if visibility == "hidden" or str(provider.get("source") or "").lower() in {"state_memory", "activity"}:
        return "hidden"
    if source_provider_configured(provider):
        return "configured"
    return "available"


def source_provider_health_contract(provider_health):
    health = provider_health if isinstance(provider_health, dict) else {}
    state = str(health.get("state") or "").strip().lower()
    if state in {"healthy", "available", "connected", "ok"}:
        normalized = "healthy"
    elif state in {"watch", "degraded", "attention", "provider_wait", "limited"}:
        normalized = "degraded"
    elif state in {"unavailable", "offline", "failed", "error"}:
        normalized = "unavailable"
    else:
        normalized = "unknown"
    return {
        "state": normalized,
        "reason": str(health.get("detail") or health.get("label") or "").strip(),
    }


def source_provider_attempt_filter(provider_id):
    provider_id = provider_activity_key(provider_id)
    if provider_id in SOURCE_ATTEMPT_ALIASES:
        return provider_id
    return provider_id or "all"


def configured_provider_keys(db_path):
    db_path = Path(db_path)
    if not db_path.exists():
        return set()
    try:
        with connect(db_path) as con:
            return {
                provider_activity_key(row["id"])
                for row in con.execute("select id from provider_configs")
                if provider_activity_key(row["id"])
            }
    except Exception:
        return set()


def source_provider_state(provider):
    if not provider.get("enabled"):
        return "disabled"
    if source_provider_health_problem(provider):
        return "attention"
    activity = provider.get("activity") if isinstance(provider.get("activity"), dict) else {}
    queue_impact = provider.get("queue_impact") if isinstance(provider.get("queue_impact"), dict) else {}
    outcome = activity.get("outcome") if isinstance(activity.get("outcome"), dict) else {}
    outcome_label = str(outcome.get("label") or "").strip().lower()
    last_status = str(activity.get("last_status") or "").strip().lower()
    if any(token in last_status for token in ("fail", "error", "blocked", "bad", "stale")):
        return "attention"
    if outcome_label in {"needs attention"}:
        return "attention"
    if int(activity.get("recent_attempts") or 0) > 0 or int(activity.get("wanted_item_count") or 0) > 0:
        return "active"
    if int(queue_impact.get("active_queue") or queue_impact.get("queue_items") or 0) > 0:
        return "active"
    if int(activity.get("bad_source_candidates") or 0) > 0:
        return "tracking"
    if source_provider_is_inactive_tracking(provider):
        return "inactive_tracking"
    if int(activity.get("series_count") or 0) > 0:
        return "tracking"
    provider_type = str(provider.get("provider_type") or "").strip().lower()
    if provider_type in {"path", "rule"}:
        return "configured"
    return "enabled"


def source_provider_next_action(row):
    state = str(row.get("state") or "").lower()
    provider_id = str(row.get("id") or "").lower()
    outcome_label = str(row.get("outcome_label") or "").lower()
    recommendation = row.get("source_recommendation") if isinstance(row.get("source_recommendation"), dict) else {}
    if recommendation.get("next_action"):
        return recommendation.get("next_action")
    if state == "disabled":
        return "Enable or configure this provider if InkDrop should use it"
    if state == "inactive_tracking":
        return "Inactive tracking row; hide from normal source triage unless you want to re-enable this source"
    health = row.get("provider_health") if isinstance(row.get("provider_health"), dict) else {}
    if state == "attention" and health:
        label = str(health.get("label") or health.get("state") or "health").strip()
        detail = str(health.get("detail") or "").strip()
        return f"Resolve provider health: {label}{(': ' + detail) if detail else ''}"
    if state == "attention":
        return "Open Attempts to inspect recent provider failures"
    queue_impact = row.get("queue_impact") if isinstance(row.get("queue_impact"), dict) else {}
    provider_wait = int(queue_impact.get("provider_wait") or 0)
    recovering = int(queue_impact.get("recovering") or 0)
    waiting = int(queue_impact.get("waiting") or 0)
    if provider_wait:
        return f"{provider_wait} queue rows are waiting on this provider; check health or let automatic retry continue"
    if recovering:
        return f"{recovering} queue rows are recovering from failed candidates; inspect Queue or Attempts if it keeps repeating"
    if waiting:
        return f"{waiting} queue rows are waiting for source coverage; automatic retry remains scheduled"
    if provider_id == "slskd":
        return "Tune auto-grab limits and watch transfer/import attempts"
    if provider_id == "prowlarr":
        return "Tune categories and indexer timeouts for wanted searches"
    if provider_id in {"rss", "comicscodes"}:
        return "Keep discovery limits conservative when sources throttle"
    if provider_id in {"sabnzbd", "qbittorrent"}:
        return "Keep categories and save paths aligned with import roots"
    if provider_id == "kapowarr":
        return "Keep as adapter-only while InkDrop owns new series"
    if provider_id in {"pack_import", "bad_source_memory"}:
        return "Use bad-source memory to avoid retrying broken local pack candidates"
    if provider_id == "quality_language_rules":
        return "Tune language, PDF, pack, and extension policy for automatic grabs"
    if outcome_label == "low yield":
        return "Review no-candidate attempts and retry policy"
    if state == "active":
        return "Provider is participating in active automation"
    return "Provider is configured for InkDrop automation"


def boolish_config_value(value, default=False):
    if isinstance(value, bool):
        return value
    if value is None:
        return bool(default)
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def normalized_config_extensions(values):
    out = set()
    for value in values or []:
        text = str(value or "").strip().lower()
        if not text:
            continue
        out.add(text if text.startswith(".") else f".{text}")
    return out


def user_app_setting_values(snapshot):
    values = {}
    for setting in (snapshot or {}).get("settings") or []:
        if not isinstance(setting, dict):
            continue
        if setting.get("source") != "user":
            continue
        key = str(setting.get("key") or "").strip()
        if key:
            values[key] = setting.get("value")
    return values


def effective_quality_policy(provider, app_values=None):
    provider = provider if isinstance(provider, dict) else {}
    settings = provider.get("settings") if isinstance(provider.get("settings"), dict) else {}
    app_values = app_values if isinstance(app_values, dict) else {}
    preferred = str(settings.get("preferred_language") or "english").strip().lower() or "english"
    if boolish_config_value(settings.get("allow_non_english"), False):
        preferred = "any"
    pdf_allowed = boolish_config_value(settings.get("pdf_allowed"), True)
    packs_allowed = boolish_config_value(settings.get("packs_allowed"), True)
    allowed_extensions = normalized_config_extensions(settings.get("allowed_manual_extensions") or [".cbz", ".cbr", ".pdf"])
    allowed_extensions.update({".cbz", ".cbr"})
    if pdf_allowed:
        allowed_extensions.add(".pdf")
    else:
        allowed_extensions.discard(".pdf")
    pack_archives = normalized_config_extensions(settings.get("pack_archives") or [".zip", ".rar", ".7z"])
    if packs_allowed:
        allowed_extensions.update(pack_archives)
    else:
        allowed_extensions.difference_update({".zip", ".rar", ".7z"})
    source = "provider_config"
    if app_values.get("quality.preferred_language") not in (None, ""):
        preferred = str(app_values.get("quality.preferred_language")).strip().lower() or preferred
        source = "user_app_settings"
    if app_values.get("quality.allow_non_english") is not None:
        if boolish_config_value(app_values.get("quality.allow_non_english"), False):
            preferred = "any"
        elif preferred == "any":
            preferred = str(app_values.get("quality.preferred_language") or "english").strip().lower() or "english"
        source = "user_app_settings"
    if app_values.get("quality.allow_pdfs") is not None:
        pdf_allowed = boolish_config_value(app_values.get("quality.allow_pdfs"), pdf_allowed)
        source = "user_app_settings"
    if app_values.get("quality.allow_packs") is not None:
        packs_allowed = boolish_config_value(app_values.get("quality.allow_packs"), packs_allowed)
        source = "user_app_settings"
    preferred_extensions = normalized_config_extensions(app_values.get("quality.preferred_extensions") or [])
    if preferred_extensions:
        allowed_extensions = preferred_extensions | {".cbz", ".cbr"}
        source = "user_app_settings"
    if pdf_allowed:
        allowed_extensions.add(".pdf")
    else:
        allowed_extensions.discard(".pdf")
    if packs_allowed:
        allowed_extensions.update({".zip", ".rar", ".7z"})
    else:
        allowed_extensions.difference_update({".zip", ".rar", ".7z"})
    blocked_terms = [
        str(term).strip().lower()
        for term in (app_values.get("quality.blocked_release_terms") or [])
        if str(term or "").strip()
    ]
    return {
        "preferred_language": preferred,
        "allow_non_english": preferred == "any",
        "pdf_allowed": pdf_allowed,
        "packs_allowed": packs_allowed,
        "allowed_extensions": sorted(allowed_extensions),
        "blocked_release_terms": sorted(blocked_terms),
        "source": source,
    }


def quality_policy_summary_bits(policy):
    policy = policy if isinstance(policy, dict) else {}
    preferred = str(policy.get("preferred_language") or "english").strip().lower()
    language = "any language" if preferred == "any" else f"{preferred} preferred"
    pdf = "PDFs allowed" if policy.get("pdf_allowed", True) else "PDFs blocked"
    packs = "packs allowed" if policy.get("packs_allowed", True) else "packs blocked"
    extensions = ", ".join((policy.get("allowed_extensions") or [])[:6])
    bits = [language, pdf, packs]
    if extensions:
        bits.append(f"extensions {extensions}")
    blocked = policy.get("blocked_release_terms") or []
    if blocked:
        bits.append(f"blocks {', '.join(blocked[:4])}")
    return bits


def provider_lifecycle_summary(activity, recent=False, limit=4):
    activity = activity if isinstance(activity, dict) else {}
    counts = activity.get("recent_lifecycle_counts" if recent else "lifecycle_counts")
    counts = counts if isinstance(counts, dict) else {}
    labels = {
        "searched_no_candidates": "no candidate",
        "retry_later": "retry later",
        "failed_candidate": "failed candidate",
        "manual_review": "review",
        "staged_or_importing": "staged/importing",
        "provider_wait": "provider wait",
    }
    ordered = sorted(
        ((str(key), int(value or 0)) for key, value in counts.items() if int(value or 0)),
        key=lambda item: (-item[1], item[0]),
    )
    return "; ".join(f"{count} {labels.get(key, key.replace('_', ' '))}" for key, count in ordered[: max(1, int(limit or 4))])


def source_provider_row(provider):
    provider = dict(provider or {})
    settings = provider.get("settings") if isinstance(provider.get("settings"), dict) else {}
    activity = provider.get("activity") if isinstance(provider.get("activity"), dict) else {}
    outcome = activity.get("outcome") if isinstance(activity.get("outcome"), dict) else provider_outcome_from_counts(
        activity.get("outcome_counts") or {},
        activity.get("recent_outcome_counts") or {},
    )
    provider_id = str(provider.get("id") or "").strip()
    provider_type = str(provider.get("provider_type") or "").strip()
    provider_key = provider_activity_key(provider_id) or provider_id.lower()
    display_name = provider.get("display_name") or source_display_label(provider_key) or provider_id
    provider_health = source_provider_health(provider)
    queue_impact = provider.get("queue_impact") if isinstance(provider.get("queue_impact"), dict) else {}
    editable = settings.get("editable_fields") if isinstance(settings.get("editable_fields"), list) else []
    secret_fields = settings.get("secret_fields") if isinstance(settings.get("secret_fields"), list) else []
    ownership = str(provider.get("ownership") or "").strip().lower() or source_provider_ownership(provider_id, provider_type, provider.get("source"))
    capabilities = provider.get("capabilities") if isinstance(provider.get("capabilities"), list) else None
    if not capabilities:
        capabilities = list(SOURCE_PROVIDER_CAPABILITIES.get(provider_id.lower(), (source_provider_type_label(provider_type),)))
    consumers = provider.get("applied_by") if isinstance(provider.get("applied_by"), list) else None
    if not consumers:
        consumers = list(SOURCE_PROVIDER_CONSUMERS.get(provider_id.lower(), ()))
    automation_role = str(provider.get("automation_role") or "").strip() or SOURCE_PROVIDER_ROLES.get(provider_id.lower(), source_provider_type_label(provider_type))
    state = source_provider_state(provider)
    recent = int(activity.get("recent_attempts") or 0)
    total = int(activity.get("total_attempts") or 0)
    bad_candidate_count = int(activity.get("bad_source_candidates") or 0)
    recent_bad_candidate_count = int(activity.get("recent_bad_source_candidates") or 0)
    outcome_label = outcome.get("label") or "quiet"
    lifecycle_summary = provider_lifecycle_summary(activity)
    recent_lifecycle_summary = provider_lifecycle_summary(activity, recent=True)
    queue_impact_summary = provider_queue_impact_summary(queue_impact)
    source_recommendation = provider.get("source_recommendation") if isinstance(provider.get("source_recommendation"), dict) else {}
    recommendation_summary = str(source_recommendation.get("summary") or "").strip()
    if recommendation_summary and not queue_impact_summary:
        queue_impact_summary = recommendation_summary
    queue_impact_count = int(queue_impact.get("active_queue") or queue_impact.get("queue_items") or 0)
    queue_wait_count = int(queue_impact.get("provider_wait") or 0)
    queue_recovering_count = int(queue_impact.get("recovering") or 0)
    queue_waiting_count = int(queue_impact.get("waiting") or 0)
    inactive_tracking = source_provider_is_inactive_tracking(provider)
    source_ui_visibility, source_ui_hidden_reason = source_provider_ui_visibility(provider, source_recommendation)
    source_ui_hide_default = source_ui_visibility != "normal"
    configured = source_provider_configured(provider)
    presentation_visibility = source_provider_presentation_visibility(provider, source_ui_visibility)
    capability_contract = source_provider_capability_contract(provider)
    health_contract = source_provider_health_contract(provider_health)
    apply_action = source_recommendation.get("apply_action")
    integration_role = "provider"
    if provider_id.lower() == "suwayomi":
        integration_role = "adapter"
    elif provider_id.lower() == "suwayomi_managed_folder":
        integration_role = "adapter_managed_folder"
    activity_class = "inactive_tracking" if inactive_tracking else (
        "active" if recent or queue_impact_count else (
            "historical" if total or bad_candidate_count else "configured"
        )
    )
    quality_policy = provider.get("effective_policy") if isinstance(provider.get("effective_policy"), dict) else None
    quality_bits = quality_policy_summary_bits(quality_policy) if provider_id.lower() == "quality_language_rules" else []
    detail_bits = [
        source_provider_type_label(provider_type),
        "InkDrop-owned" if ownership == "native" else ("Adapter" if ownership == "adapter" else "User configured"),
        *quality_bits,
        queue_impact_summary,
        recommendation_summary if recommendation_summary != queue_impact_summary else None,
        f"{recent} recent attempts" if recent else (f"{total} attempts" if total else None),
        f"{recent_bad_candidate_count} recent bad candidates" if recent_bad_candidate_count else (f"{bad_candidate_count} bad candidates" if bad_candidate_count else None),
        outcome_label,
        f"{int(activity.get('wanted_item_count') or 0)} wanted" if int(activity.get("wanted_item_count") or 0) else None,
        f"{len(editable)} editable" if editable else "read only",
    ]
    row = {
        "kind": "provider",
        "id": provider_id,
        "provider": provider_key,
        "provider_id": provider_key,
        "provider_key": provider_key,
        "label": display_name,
        "display_name": display_name,
        "title": display_name,
        "provider_type": provider_type,
        "provider_type_label": source_provider_type_label(provider_type),
        "state": state,
        "enabled": bool(provider.get("enabled")),
        "configured": configured,
        "visibility": presentation_visibility,
        "base_url": provider.get("base_url"),
        "secret_ref": provider.get("secret_ref"),
        "source": provider.get("source"),
        "ownership": ownership,
        "settings_group": provider.get("settings_group"),
        "automation_role": automation_role,
        "description": provider.get("description"),
        "config_next_action": provider.get("next_action"),
        "capabilities": capabilities,
        "capability_contract": capability_contract,
        "integration_role": integration_role,
        "applied_by": consumers,
        "effective_policy": quality_policy,
        "editable_count": len(editable),
        "secret_count": len(secret_fields),
        "activity": activity,
        "provider_health": provider_health or None,
        "health": provider_health or None,
        "health_state": health_contract["state"],
        "health_reason": health_contract["reason"],
        "queue_impact": queue_impact or None,
        "queue_impact_summary": queue_impact_summary,
        "source_recommendation": source_recommendation or None,
        "source_recommendation_summary": recommendation_summary,
        "recommended_for_queue_count": int(source_recommendation.get("queue_count") or 0),
        "recommended_for_series_count": int(source_recommendation.get("series_count") or 0),
        "recommended_series_sample": clone_jsonish(source_recommendation.get("series_sample") or []),
        "recommended_provider_ids": clone_jsonish(source_recommendation.get("recommended_provider_ids") or []),
        "queue_impact_count": queue_impact_count,
        "queue_wait_count": queue_wait_count,
        "queue_recovering_count": queue_recovering_count,
        "queue_waiting_count": queue_waiting_count,
        "is_inactive_tracking": inactive_tracking,
        "source_activity_class": activity_class,
        "source_ui_visibility": source_ui_visibility,
        "source_ui_hide_default": source_ui_hide_default,
        "source_ui_hidden_reason": source_ui_hidden_reason,
        "last_success_at": activity.get("last_success_at"),
        "last_success_at_iso": activity.get("last_success_at_iso"),
        "last_failure_at": activity.get("last_failure_at"),
        "last_failure_at_iso": activity.get("last_failure_at_iso"),
        "last_failure_summary": activity.get("last_failure_summary") or "",
        "apply_action": apply_action if isinstance(apply_action, (dict, str)) else None,
        "queue_filter": queue_impact.get("queue_filter") if queue_impact else None,
        "queue_filter_label": queue_impact.get("queue_filter_label") if queue_impact else None,
        "total_attempts": total,
        "recent_attempts": recent,
        "bad_source_candidates": bad_candidate_count,
        "recent_bad_source_candidates": recent_bad_candidate_count,
        "bad_source_candidate_failure_count": int(activity.get("bad_source_candidate_failure_count") or 0),
        "bad_source_candidate_by_reason": dict(activity.get("bad_source_candidate_by_reason") or {}),
        "bad_source_candidate_by_source": dict(activity.get("bad_source_candidate_by_source") or {}),
        "bad_source_candidate_by_provider": dict(activity.get("bad_source_candidate_by_provider") or {}),
        "last_bad_source_candidate_at": activity.get("last_bad_source_candidate_at"),
        "last_bad_source_candidate_at_iso": activity.get("last_bad_source_candidate_at_iso"),
        "last_bad_source_candidate_reason": activity.get("last_bad_source_candidate_reason"),
        "last_bad_source_candidate_title": activity.get("last_bad_source_candidate_title"),
        "last_bad_source_candidate_series": activity.get("last_bad_source_candidate_series"),
        "last_bad_source_candidate_source_path": activity.get("last_bad_source_candidate_source_path"),
        "last_activity_at": activity.get("last_activity_at"),
        "last_activity_at_iso": activity.get("last_activity_at_iso"),
        "last_status": activity.get("last_status"),
        "last_lifecycle_phase": activity.get("last_lifecycle_phase"),
        "last_series": activity.get("last_series"),
        "last_issue_number": activity.get("last_issue_number"),
        "last_title": activity.get("last_title"),
        "last_queue_id": activity.get("last_queue_id"),
        "last_wanted_id": activity.get("last_wanted_id"),
        "series_count": int(activity.get("series_count") or 0),
        "monitored_series_count": int(activity.get("monitored_series_count") or 0),
        "wanted_item_count": int(activity.get("wanted_item_count") or 0),
        "outcome": outcome,
        "outcome_label": outcome_label,
        "outcome_score": outcome.get("score"),
        "outcome_detail": outcome.get("detail"),
        "lifecycle_counts": dict(activity.get("lifecycle_counts") or {}),
        "recent_lifecycle_counts": dict(activity.get("recent_lifecycle_counts") or {}),
        "lifecycle_summary": lifecycle_summary,
        "recent_lifecycle_summary": recent_lifecycle_summary,
        "source_attempt_filter": source_provider_attempt_filter(provider_id),
        "settings_target": "inkdropSettings",
        "updated_at": provider.get("updated_at"),
        "activity_at": activity.get("last_activity_at") or provider.get("updated_at"),
    }
    last_subject = row["last_series"] or row["last_title"]
    if row["last_series"] and row["last_issue_number"]:
        last_subject = f"{row['last_series']} #{row['last_issue_number']}"
    row["activity_summary"] = " · ".join(
        str(bit)
        for bit in (
            row["automation_role"],
            "enabled" if row["enabled"] else "disabled",
            provider_health_activity_bit({"provider_health": provider_health}) if provider_health and source_provider_health_problem({"provider_health": provider_health}) else None,
            queue_impact_summary,
            recommendation_summary if recommendation_summary != queue_impact_summary else None,
            recent_lifecycle_summary,
            f"{recent_bad_candidate_count} recent bad candidates" if recent_bad_candidate_count else (f"{bad_candidate_count} bad candidates" if bad_candidate_count else None),
            row["outcome_detail"],
            f"last {row['last_status']}" if row.get("last_status") else None,
            last_subject,
        )
        if bit
    )
    row["detail"] = " · ".join(str(bit) for bit in detail_bits if bit)
    row["next_action"] = source_provider_next_action(row) or provider.get("next_action")
    row["provider_status"] = canonical_provider_status(row, row_kind="provider", provider_type=provider_type)
    row["linked_entities"] = {}
    return row


def source_provider_row_matches_filter(row, provider_filter):
    provider_filter = source_provider_filter_key(provider_filter)
    provider_type = str(row.get("provider_type") or "").strip().lower()
    state = str(row.get("state") or "").strip().lower()
    outcome_label = str(row.get("outcome_label") or "").strip().lower()
    queue_impact = row.get("queue_impact") if isinstance(row.get("queue_impact"), dict) else {}
    if provider_filter == "all":
        return True
    if provider_filter in {"visible", "default"}:
        return not bool(row.get("source_ui_hide_default"))
    if provider_filter in {"hidden", "hidden_sources"}:
        return bool(row.get("source_ui_hide_default"))
    if provider_filter == "experimental":
        return str(row.get("source_ui_visibility") or "").startswith("experimental_")
    if provider_filter == "inactive_tracking":
        return bool(row.get("is_inactive_tracking")) or str(row.get("source_activity_class") or "") == "inactive_tracking"
    if provider_filter == "enabled":
        return bool(row.get("enabled"))
    if provider_filter == "disabled":
        return not bool(row.get("enabled"))
    if provider_filter == "active":
        return state in {"active", "tracking"} or int(row.get("recent_attempts") or 0) > 0 or int(queue_impact.get("active_queue") or 0) > 0
    if provider_filter == "attention":
        return state == "attention" or outcome_label == "needs attention"
    if provider_filter == "provider_wait":
        return (
            row_matches_provider_status_filter(row, "provider_wait")
            or source_provider_health_problem(row)
            or int(queue_impact.get("provider_wait") or 0) > 0
        )
    if provider_filter == "productive":
        return outcome_label == "productive" or int((row.get("outcome") or {}).get("recent", {}).get("productive") or 0) > 0
    if provider_filter == "low_yield":
        recommendation = row.get("source_recommendation") if isinstance(row.get("source_recommendation"), dict) else {}
        return outcome_label == "low yield" or str(recommendation.get("recommendation_key") or "") == "pause_problem_direct_source"
    if provider_filter == "source_memory":
        return int(row.get("bad_source_candidates") or 0) > 0
    if provider_filter == "metadata":
        return provider_type in {"metadata", "metadata_adapter"}
    if provider_filter == "indexers":
        return provider_type == "indexer"
    if provider_filter == "download_sources":
        return provider_type in {"download_source", "direct_download"}
    if provider_filter == "download_clients":
        return provider_type == "download_client"
    if provider_filter == "library":
        return provider_type == "library"
    if provider_filter == "paths_rules":
        return provider_type in {"path", "rule"}
    if provider_filter == "adapters":
        return str(row.get("ownership") or "") == "adapter" or provider_type == "metadata_adapter"
    return True


def source_provider_rows_from_snapshot(snapshot, provider_health=None, provider_queue_impact=None, provider_recommendations=None):
    provider_health = provider_health if isinstance(provider_health, dict) else {}
    provider_queue_impact = provider_queue_impact if isinstance(provider_queue_impact, dict) else {}
    provider_recommendations = provider_recommendations if isinstance(provider_recommendations, dict) else {}
    app_values = user_app_setting_values(snapshot)
    rows = []
    seen = set()
    for provider in snapshot.get("providers") or []:
        if not isinstance(provider, dict):
            continue
        item = dict(provider)
        provider_key = provider_activity_key(item.get("id"))
        seen.add(provider_key)
        if provider_key == "quality_language_rules":
            item["effective_policy"] = effective_quality_policy(item, app_values)
        health = provider_health.get(provider_key)
        if isinstance(health, dict):
            item["provider_health"] = health
            item["health"] = health
        queue_impact = provider_queue_impact.get(provider_key)
        if isinstance(queue_impact, dict):
            item["queue_impact"] = queue_impact
        recommendation = provider_recommendations.get(provider_key)
        if isinstance(recommendation, dict):
            item["source_recommendation"] = recommendation
        rows.append(source_provider_row(item))
    extra_keys = sorted(set(provider_health) | set(provider_queue_impact))
    for provider_key in extra_keys:
        health = provider_health.get(provider_key)
        queue_impact = provider_queue_impact.get(provider_key)
        if provider_key in seen or (not isinstance(health, dict) and not isinstance(queue_impact, dict)):
            continue
        if not isinstance(health, dict) and provider_key in GENERIC_PROVIDER_IMPACT_KEYS:
            continue
        rows.append(
            source_provider_row(
                {
                    "id": provider_key,
                    "provider_type": "download_source",
                    "display_name": source_display_label(provider_key),
                    "enabled": True,
                    "source": "health" if isinstance(health, dict) else "queue",
                    "provider_health": health if isinstance(health, dict) else {},
                    "health": health if isinstance(health, dict) else {},
                    "queue_impact": queue_impact if isinstance(queue_impact, dict) else {},
                    "settings": {},
                    "activity": {},
                }
            )
        )
    return rows


def cached_source_provider_rows(db_path):
    db_path = Path(db_path)
    cache_key = str(db_path)
    now = time.time()
    cached = SOURCE_PROVIDER_VIEW_CACHE.get(cache_key)
    if (
        isinstance(cached, dict)
        and cached.get("rows") is not None
        and now - float(cached.get("ts") or 0) <= SOURCE_PROVIDER_VIEW_TTL_SECONDS
    ):
        return clone_jsonish(cached.get("rows") or [])
    snapshot = settings_snapshot(db_path)
    if not snapshot.get("ok"):
        rows = []
    else:
        with connect_read(db_path) as con:
            provider_health = latest_provider_health_map(con)
            provider_queue_impact = provider_queue_impact_snapshot(con)
            provider_recommendations = source_provider_recommendation_snapshot(con)
        rows = source_provider_rows_from_snapshot(snapshot, provider_health, provider_queue_impact, provider_recommendations)
    SOURCE_PROVIDER_VIEW_CACHE[cache_key] = {"ts": time.time(), "rows": clone_jsonish(rows)}
    return rows


def source_provider_rows(db_path, limit=80, provider_filter=None):
    limit = max(1, min(int(limit or 80), 300))
    provider_filter = source_provider_filter_key(provider_filter)
    rows = cached_source_provider_rows(db_path)
    rows = [row for row in rows if source_provider_row_matches_filter(row, provider_filter)]
    rows.sort(
        key=lambda row: (
            0 if row.get("state") == "attention" else 1,
            0 if row.get("enabled") else 1,
            -(int(row.get("recent_attempts") or 0)),
            row.get("provider_type_label") or "",
            row.get("title") or "",
        )
    )
    return clone_jsonish(rows[:limit])


def source_provider_filter_options(db_path):
    rows = cached_source_provider_rows(db_path)
    options = []
    for value, label in SOURCE_PROVIDER_FILTERS.items():
        options.append(
            {
                "value": value,
                "label": label,
                "count": sum(1 for row in rows if source_provider_row_matches_filter(row, value)),
            }
        )
    return options


def source_provider_count(db_path, provider_filter=None):
    provider_filter = source_provider_filter_key(provider_filter)
    return next(
        (int(item.get("count") or 0) for item in source_provider_filter_options(db_path) if item.get("value") == provider_filter),
        0,
    )


def compact_history_details(raw):
    if not isinstance(raw, dict):
        return {}
    details = {}
    for key in (
        "reason",
        "status",
        "query",
        "series",
        "issue",
        "queue_identity",
        "current_source",
        "error",
        "fatal_error",
        "review_id",
        "state",
        "download_client",
        "provider",
        "protocol",
        "title",
        "external_id",
    ):
        value = raw.get(key)
        if value in (None, "", [], {}):
            continue
        if isinstance(value, (dict, list)):
            continue
        text = str(value)
        details[key] = text[:220] + ("..." if len(text) > 220 else "")
    source_order = raw.get("source_order")
    if isinstance(source_order, list) and source_order:
        details["source_order"] = " -> ".join(str(item) for item in source_order[:8])
    candidate = raw.get("candidate") if isinstance(raw.get("candidate"), dict) else {}
    if candidate:
        title = candidate.get("title") or candidate.get("name")
        if title:
            details["candidate"] = str(title)[:220]
        for key in ("protocol", "indexer", "size"):
            if candidate.get(key) not in (None, ""):
                details[f"candidate_{key}"] = str(candidate.get(key))[:120]
    health = raw.get("health") if isinstance(raw.get("health"), dict) else {}
    if health:
        for key in ("state", "label", "detail"):
            if health.get(key) not in (None, ""):
                value = str(health.get(key))
                details[f"health_{key}"] = value[:220] + ("..." if len(value) > 220 else "")
    return details


def history_activity_fields(
    *,
    event_type="",
    entity_type="",
    history_kind="",
    status="",
    lifecycle_phase="",
    task_state="",
    source_key="",
    message="",
    raw=None,
):
    raw = raw if isinstance(raw, dict) else {}
    event_type = str(event_type or "").strip().lower()
    entity_type = str(entity_type or "").strip().lower()
    history_kind = str(history_kind or "").strip().lower()
    status_key = str(status or "").strip().lower()
    lifecycle_phase = str(lifecycle_phase or "").strip().lower()
    task_state = str(task_state or raw.get("state") or "").strip().lower()
    source_key = str(source_key or "").strip().lower()
    message = str(message or "").strip().lower()
    raw_outcome = str(raw.get("outcome") or "").strip().lower()
    raw_phase = str(raw.get("display_phase") or "").strip().lower()

    if event_type == "autopilot_series_run" or history_kind == "autopilot_series_run":
        if raw_outcome or raw_phase:
            return raw_outcome or "neutral", raw_phase or "observed"
        if any(token in message for token in ("auto grab", "grabbed", "download", "import", "verified", "moved at least one")):
            return "productive", "searching"
        if any(token in message for token in ("no safe", "no usable", "no candidate", "0 candidates", "retry")):
            return "no_candidate", "retry_later"
        if any(token in message for token in ("fail", "error", "blocked")):
            return "problem", "problem"
        return "neutral", "observed"

    if event_type == "source_attempt" or entity_type == "source_attempt":
        outcome = raw_outcome or source_attempt_outcome(status_key, lifecycle_phase)
        phase = raw_phase or source_attempt_display_phase(status_key, lifecycle_phase, outcome)
        return outcome, phase

    if event_type == "download_task" or entity_type == "download_task" or history_kind == "download":
        state = task_state or download_task_state(status_key)
        outcome = raw_outcome or download_task_outcome(state, status_key, lifecycle_phase)
        phase = raw_phase or download_task_display_phase(state, status_key, lifecycle_phase, outcome)
        return outcome, phase

    if event_type.startswith("import") or entity_type == "import_result" or history_kind in {"import", "verification"}:
        verified = bool(raw.get("verified") or raw.get("import_verified") or history_kind == "verification" or event_type == "import_verified")
        imported_count = raw.get("imported_count")
        skipped_count = raw.get("skipped_count") or raw.get("already_present_count")
        outcome = raw_outcome or import_result_outcome(status_key, verified, imported_count, skipped_count)
        phase = raw_phase or import_result_display_phase(status_key, verified, imported_count, skipped_count, outcome)
        if history_kind == "verification" and phase != "problem":
            phase = "verified"
            outcome = "productive"
        return outcome, phase

    if event_type == "provider_health" or entity_type == "provider" or history_kind == "provider":
        provider_health = raw.get("health") if isinstance(raw.get("health"), dict) else {"state": status_key}
        if provider_health_is_problem(provider_health):
            return raw_outcome or "problem", raw_phase or "provider_wait"
        return raw_outcome or "neutral", raw_phase or "observed"

    if event_type == "queue_event" or history_kind == "queue":
        if status_key in {"verified", "satisfied", "already_verified", "completed", "imported"} or any(
            token in message
            for token in ("kavita verified", "kavita already has issue", "no longer missing", "reconciliation says satisfied")
        ):
            return raw_outcome or "productive", raw_phase or "verified"
        if status_key in {"downloading", "download_started", "transfer_in_progress", "transfer_settling"}:
            return raw_outcome or "productive", raw_phase or "transferring"
        if status_key in {"importing", "staged_file_ready", "preview_importable", "ready_import", "verification_pending"}:
            return raw_outcome or "productive", raw_phase or "importing"
        if status_key == "searching":
            return raw_outcome or "productive", raw_phase or "searching"
        if status_key in {"needs_you", "failed", "blocked"}:
            return raw_outcome or "problem", raw_phase or ("manual_review" if status_key == "needs_you" else "problem")
        if any(token in message for token in ("no actionable candidate", "no safe", "no usable", "not confident", "not safe enough", "retry scheduled", "source ladder attempted")):
            return raw_outcome or "no_candidate", raw_phase or "retry_later"
        if any(token in message for token in ("fail", "error", "blocked", "bad archive", "stale")):
            return raw_outcome or "problem", raw_phase or "problem"
        return raw_outcome or "neutral", raw_phase or "observed"

    if event_type in {"series_search_requested", "wanted_search_requested", "queue_retry_requested"}:
        return raw_outcome or "productive", raw_phase or "searching"
    if event_type in {"series_add_failed"}:
        return raw_outcome or "problem", raw_phase or "problem"
    return raw_outcome or "neutral", raw_phase or "observed"


def history_event_type_label(event_type):
    key = str(event_type or "").strip().lower()
    labels = {
        "library_frontend_sync_requested": "reader sync requested",
    }
    return labels.get(key, key.replace("_", " "))


def history_kind_summary_label(history_kind, event_type=""):
    key = str(history_kind or "").strip().lower()
    if key == "reader_sync":
        return history_event_type_label(event_type)
    return key.replace("_", " ")


HISTORY_TAXONOMY_VERSION = 2
HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATES = {"import_ready", "importing", "verified", "completed", "succeeded"}
HISTORY_TERMINAL_DOWNLOAD_FAILURE_STATES = {"failed", "blocked"}
HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATUSES = {
    "completed", "completed_in_client", "imported", "resolved", "already_verified", "verified",
    "folder_verified", "library_visible", "kavita_verified", "queue_verified", "queue_satisfied", "succeeded",
}


def history_first_text(*values):
    for value in values:
        text = str(value or "").strip().lower()
        if text:
            return text
    return ""


def history_download_taxonomy(row, raw=None):
    """Classify an event-time download outcome without rewriting legacy history_kind."""
    row = row if isinstance(row, dict) else {}
    raw = raw if isinstance(raw, dict) else {}
    event_type = history_first_text(row.get("event_type"))
    entity_type = history_first_text(row.get("entity_type"))
    is_download_task = event_type == "download_task" or entity_type == "download_task"
    is_source_attempt = event_type == "source_attempt" or entity_type == "source_attempt"
    event_source = history_first_text(raw.get("source"), row.get("source"), row.get("source_attempt_source"))
    provider_or_client = history_first_text(
        raw.get("provider_id"), raw.get("download_client"), row.get("source_provider_id"),
        row.get("source_download_client"), row.get("source_provider"), row.get("source_protocol"),
    )
    status = history_first_text(raw.get("status"), row.get("download_task_status"), row.get("source_status"))
    state = history_first_text(raw.get("state"), row.get("download_task_state"))
    lifecycle_phase = history_first_text(raw.get("lifecycle_phase"), row.get("lifecycle_phase"))
    outcome = history_first_text(raw.get("outcome"), row.get("outcome"))
    linked_task = bool(row.get("source_attempt_has_download_task"))
    download_like_attempt = is_source_attempt and (
        event_source == "download_client"
        or history_source_attempt_looks_like_download(event_source or provider_or_client, "", status)
    )
    record_type = "download_task" if is_download_task else ("legacy_source_attempt" if download_like_attempt and not linked_task else "")
    result = {
        "history_taxonomy_version": HISTORY_TAXONOMY_VERSION,
        "history_view_bucket": "activity",
        "download_outcome_terminal": False,
        "download_outcome": None,
        "download_record_type": record_type or None,
    }
    if not record_type:
        return result
    effective_state = state or download_task_state(status)
    if (
        effective_state in {"queued", "downloading"}
        or lifecycle_phase in {"queued", "waiting", "provider_wait", "downloading"}
        or status in DOWNLOAD_TASK_WAITING_STATUSES | DOWNLOAD_TASK_TRANSFERRING_STATUSES
    ):
        return result
    if (
        effective_state in HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATES
        or status in HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATUSES
        or lifecycle_phase in {"staged_or_importing", "verified", "completed"}
    ):
        result.update({"history_view_bucket": "downloads", "download_outcome_terminal": True, "download_outcome": "completed"})
        return result
    if (
        effective_state in HISTORY_TERMINAL_DOWNLOAD_FAILURE_STATES
        or download_task_state(status) == "failed"
        or lifecycle_phase in {"failed_candidate", "failed", "blocked"}
        or (outcome == "problem" and status not in {"provider_wait", "provider_unavailable"})
    ):
        result.update({"history_view_bucket": "downloads", "download_outcome_terminal": True, "download_outcome": "failed"})
    return result


def history_row_from_record(row):
    out = dict(row or {})
    created_at = safe_float(out.get("created_at"))
    if created_at:
        out["created_at_iso"] = utc_stamp(created_at)
    event_type = str(out.get("event_type") or "history")
    entity_type = str(out.get("entity_type") or "").strip()
    entity_id = out.get("entity_id")
    out["linked_entities"] = linked_entities(
        series_id=out.get("series_id") or (entity_id if entity_type == "series" else None),
        issue_id=out.get("issue_id"),
        wanted_id=out.get("wanted_id") or (entity_id if entity_type == "wanted_item" else None),
        queue_id=out.get("queue_id") or (entity_id if entity_type == "queue_item" else None),
        source_attempt_id=out.get("source_attempt_id") or (entity_id if entity_type == "source_attempt" else None),
        download_task_id=out.get("download_task_id") or (entity_id if entity_type == "download_task" else None),
        import_id=out.get("import_id") or (entity_id if entity_type == "import_result" else None),
    )
    source_provider_id = str(out.get("source_provider_id") or out.get("download_task_provider_id") or "").strip()
    source = str(source_provider_id or out.get("source") or out.get("download_task_source") or out.get("queue_current_source") or "").strip()
    provider = str(out.get("source_provider") or out.get("download_task_provider") or "").strip()
    download_client = str(out.get("source_download_client") or out.get("download_task_client") or out.get("download_task_protocol") or "").strip()
    raw = json_loads(out.get("raw_json") or "{}", {})
    stored_outcome = str(out.get("outcome") or "").strip().lower()
    stored_display_phase = str(out.get("display_phase") or "").strip().lower()
    if isinstance(raw, dict) and (stored_outcome or stored_display_phase):
        raw = dict(raw)
        if stored_outcome:
            raw.setdefault("outcome", stored_outcome)
        if stored_display_phase:
            raw.setdefault("display_phase", stored_display_phase)
    if isinstance(raw, dict):
        source_provider_id = source_provider_id or str(raw.get("provider_id") or "").strip()
    ownership = history_row_ownership(row=out)
    if ownership:
        out.update({
            "owner": ownership["owner"],
            "ownership": ownership["ownership"],
            "source_of_truth": ownership["source_of_truth"],
            "source_of_truth_label": ownership["source_of_truth_label"],
            "source_of_truth_detail": ownership["source_of_truth_detail"],
            "source_of_truth_confidence": ownership["source_of_truth_confidence"],
            "source_of_truth_evidence": ownership["source_of_truth_evidence"],
            "metadata_authority": ownership["metadata_authority"],
            "metadata_authority_id": ownership["metadata_authority_id"],
            "metadata_authority_role": ownership["metadata_authority_role"],
            "adapter_provider": ownership["adapter_provider"],
            "adapter_role": ownership["adapter_role"],
            "adapter_backed": ownership["adapter_backed"],
            "kapowarr_role": ownership["kapowarr_role"],
            "ownership_evidence": ownership,
        })
    provider_key = provider_activity_key(source_provider_id or source or provider or download_client)
    lifecycle_phase = str(out.get("lifecycle_phase") or (raw.get("lifecycle_phase") if isinstance(raw, dict) else "") or "").strip().lower()
    candidate_identity = str(out.get("candidate_identity") or (raw.get("candidate_identity") if isinstance(raw, dict) else "") or "").strip()
    failure_reason = str(out.get("failure_reason") or (raw.get("failure_reason") if isinstance(raw, dict) else "") or "").strip()
    retry_eligible = bool(out.get("retry_eligible") or (raw.get("retry_eligible") if isinstance(raw, dict) else False))
    raw_status = (raw.get("status") or raw.get("state")) if isinstance(raw, dict) else ""
    if event_type == "queue_event":
        status = raw_status or out.get("queue_state") or event_type
    elif event_type == "download_task" or entity_type == "download_task":
        status = (
            out.get("download_task_status")
            or raw_status
            or out.get("download_task_state")
            or event_type
        )
    else:
        status = (
            out.get("source_status")
            or out.get("import_status")
            or raw_status
            or out.get("queue_state")
            or event_type
        )
    out.pop("raw_json", None)
    if event_type == "provider_health" and isinstance(raw, dict):
        raw_health = raw.get("health") if isinstance(raw.get("health"), dict) else {}
        status = raw_health.get("state") or raw_health.get("label") or status
    if out.get("download_task_id"):
        out["download_task"] = compact_download_task_payload(
            {
                "id": out.get("download_task_id"),
                "download_task_id": out.get("download_task_id"),
                "source_attempt_id": out.get("source_attempt_id"),
                "source": out.get("download_task_source"),
                "provider_id": out.get("source_provider_id"),
                "provider": out.get("download_task_provider"),
                "protocol": out.get("download_task_protocol"),
                "download_client": out.get("download_task_client"),
                "display_source": source_display_label(download_client or source or provider or out.get("download_task_source")),
                "title": out.get("download_task_title") or out.get("source_title"),
                "status": out.get("download_task_status"),
                "state": out.get("download_task_state"),
                "category": out.get("download_task_category"),
                "size_bytes": out.get("download_task_size_bytes"),
                "progress": out.get("download_task_progress"),
                "started_at": out.get("download_task_started_at"),
                "updated_at": out.get("download_task_updated_at"),
                "completed_at": out.get("download_task_completed_at"),
            }
        )
    message = str(out.get("message") or "").strip()
    if not message:
        message = event_type.replace("_", " ")
    status_key = str(status or "").strip().lower()
    task_state_key = str(out.get("download_task_state") or (raw.get("state") if isinstance(raw, dict) else "") or "").strip().lower()
    source_key = str(provider_key or source or provider or download_client or "").strip().lower()
    visibility_provider = str(
        (
            raw.get("library_visibility_provider")
            if isinstance(raw, dict)
            else ""
        )
        or out.get("library_visibility_provider")
        or (source_key if source_key in {"kavita", "komga"} else "")
    ).strip().lower()
    library_visible_action = library_visibility_next_action(visibility_provider)
    if event_type == "download_task" or entity_type == "download_task":
        history_kind = "download"
        effective_state = task_state_key or download_task_state(status_key)
        if effective_state == "downloading":
            next_action = "Downloader transfer is active or settling"
        elif effective_state == "import_ready":
            next_action = "File is staged and ready for import"
        elif effective_state == "importing":
            next_action = "Import or library visibility is in progress"
        elif effective_state == "verified":
            next_action = "Transfer resolved and verified"
        elif effective_state in {"failed", "blocked"}:
            next_action = "Transfer failed; automatic retry or cleanup should continue"
        elif effective_state == "queued":
            next_action = "Waiting for downloader/source status update"
        else:
            next_action = "Download task recorded"
    elif event_type in {"library_frontend_sync_requested", "library_frontend_visibility_rechecked"}:
        history_kind = "reader_sync"
        next_action = "Reader frontend scan requested; InkDrop folder/import truth remains unchanged"
    elif event_type == "import_verified" or out.get("import_verified"):
        history_kind = "verification"
        next_action = library_visible_action
    elif history_field_kind(event_type, entity_type, source, message) == "verification":
        history_kind = "verification"
        next_action = library_visible_action or "Import or reader visibility was verified"
    elif event_type == "source_attempt" and source_key in {"kavita", "komga"} and status_key == "verified":
        history_kind = "verification"
        next_action = library_visible_action
    elif event_type in {"import_pack_finished", "pack_import_finished"}:
        history_kind = "import"
        next_action = "Local pack finished; no action needed"
    elif event_type.startswith("import"):
        history_kind = "import"
        next_action = "Import recorded"
    elif event_type == "source_attempt" and source_key == "importer" and status_key in {"verified", "imported"}:
        history_kind = "verification"
        next_action = "Import verified"
    elif event_type == "source_attempt" and source == "slskd" and history_source_attempt_looks_like_download(source, message, status_key):
        history_kind = "download"
        if status_key in {
            "started_waiting",
            "importing",
            "downloading",
            "download_started",
            "already_downloading",
            "waiting_for_transfer",
            "transfer_in_progress",
            "transfer_settling",
            "waiting_for_staged_file",
            "staged_file_settling",
        }:
            next_action = "Monitoring SLSKD transfer/import"
        elif status_key in {"staged_file_ready", "preview_importable", "ready_import", "verification_pending", "imported_not_resolved"}:
            next_action = "Importing SLSKD file, then verify library visibility"
        elif status_key in {"searching", "candidate_found", "review"}:
            next_action = "Searching SLSKD candidates"
        elif status_key in {"provider_unavailable", "provider_wait"}:
            next_action = "SLSKD provider is unavailable; retrying automatically"
        elif status_key in {"transient_error", "download_api_error", "download_preflight_api_error"}:
            next_action = "SLSKD hiccup; retrying automatically"
        elif status_key in {"transfer_failed", "transfer_stalled", "candidate_failed"}:
            next_action = "Retrying the next SLSKD candidate"
        elif status_key in {"no_candidate_retry", "retry_exhausted", "retry_scheduled"}:
            next_action = "No safe SLSKD auto-pick; retry/source ladder continues"
        elif status_key in {"verified", "imported"}:
            next_action = "SLSKD result verified/imported"
        else:
            next_action = "SLSKD attempt recorded"
    elif event_type == "source_attempt" and source == "slskd":
        history_kind = "source"
        if status_key in {"searching", "candidate_found", "review"}:
            next_action = "SLSKD search result recorded"
        elif status_key in {"no_candidate_retry", "retry_exhausted", "retry_scheduled"}:
            next_action = "No SLSKD candidate; retry/source ladder continues"
        elif status_key in {"provider_unavailable", "provider_wait"}:
            next_action = "SLSKD provider is unavailable; retrying automatically"
        elif status_key in {"transient_error", "download_api_error", "download_preflight_api_error", "error", "failed"}:
            next_action = "SLSKD source issue; retrying automatically"
        else:
            next_action = "SLSKD source attempt recorded"
    elif event_type == "source_attempt" and (source_key == "download_client" or download_client):
        history_kind = "download"
        if status_key in {"failed_download", "bad_archive", "stale_no_local_file", "wrong_series_or_subseries"}:
            next_action = "Download client result needs retry/cleanup"
        elif status_key in {"verified", "imported"}:
            next_action = "Download verified/imported"
        else:
            next_action = "Download client attempt recorded"
    elif event_type == "source_attempt":
        history_kind = "source"
        next_action = "Source attempt recorded"
    elif event_type == "queue_event" and (
        status_key in {"verified", "satisfied", "already_verified", "completed", "imported"}
        or any(
            token in message.lower()
            for token in (
                "library visibility confirmed",
                "kavita verified",
                "kavita already has issue",
                "downloader/import reconciliation says satisfied",
                "no longer missing",
            )
        )
    ):
        history_kind = "verification"
        next_action = library_visible_action
    elif event_type == "queue_event" and status_key == "superseded_duplicate":
        history_kind = "cleanup"
        next_action = "Duplicate queue row retired"
    elif event_type == "queue_event" and any(
        token in message.lower()
        for token in ("retry scheduled", "source ladder attempted", "no actionable candidate", "no safe", "no usable", "not confident", "not safe enough")
    ):
        history_kind = "queue"
        next_action = "Automatic retry scheduled; no action needed"
    elif event_type == "queue_event" and any(token in message.lower() for token in ("fail", "error", "blocked", "bad archive", "stale")):
        history_kind = "queue"
        next_action = "Automatic retry or cleanup continues"
    elif event_type == "queue_event" and source_key == "slskd" and status_key in {
        "downloading",
        "download_started",
        "transfer_in_progress",
        "transfer_settling",
        "waiting_for_staged_file",
        "staged_file_settling",
    }:
        history_kind = "download"
        next_action = "Monitoring SLSKD transfer/import"
    elif event_type == "queue_event" and source_key == "slskd" and status_key in {
        "importing",
        "staged_file_ready",
        "preview_importable",
        "ready_import",
        "verification_pending",
        "imported_not_resolved",
    }:
        history_kind = "import"
        next_action = "Importing SLSKD file, then verify library visibility"
    elif event_type in {"queue_retry_requested", "wanted_search_requested"}:
        history_kind = "queue"
        next_action = "Search/retry queued"
    elif event_type == "queue_event":
        history_kind = "queue"
        next_action = "Queue state changed"
    elif event_type in {"series_added", "series_add_failed", "series_monitor_synced", "series_search_requested"}:
        history_kind = "series"
        if event_type == "series_add_failed":
            next_action = "Series add failed"
        elif event_type == "series_monitor_synced":
            next_action = "Existing series monitor synced"
        elif event_type == "series_search_requested":
            next_action = "Series search queued"
        else:
            next_action = "Series monitor recorded"
    elif event_type == "provider_health":
        history_kind = "provider"
        if status_key in {"healthy", "configured", "running"}:
            next_action = "Provider healthy"
        elif status_key in {"backoff", "disabled", "error", "failed", "unavailable", "watch"}:
            next_action = "Provider health is limiting automation"
        else:
            next_action = "Provider health recorded"
    elif event_type == "provider_test":
        history_kind = "provider"
        next_action = "Provider test recorded"
    elif event_type in {"provider_update", "settings_update", "settings_sync"}:
        history_kind = "settings"
        next_action = "Settings change recorded"
    elif event_type == "autopilot_series_run":
        history_kind = "source"
        raw_outcome_key = str(raw.get("outcome") or "").strip().lower() if isinstance(raw, dict) else ""
        raw_phase_key = str(raw.get("display_phase") or "").strip().lower() if isinstance(raw, dict) else ""
        if raw_outcome_key == "productive" or raw_phase_key in {"searching", "downloading", "importing", "verified"}:
            next_action = "Autopilot found usable source progress; InkDrop continues automatically"
        elif raw_outcome_key == "no_candidate" or raw_phase_key in {"retry_later", "source_wait", "provider_wait"}:
            next_action = "No safe automatic candidate found; retry/source ladder continues"
        elif raw_outcome_key == "problem" or raw_phase_key == "problem":
            next_action = "Source ladder hit a problem; automatic retry or cleanup continues"
        else:
            next_action = "Autopilot source-ladder pass recorded"
    else:
        history_kind = history_event_type_label(event_type)
        next_action = message
    outcome, display_phase = history_activity_fields(
        event_type=event_type,
        entity_type=entity_type,
        history_kind=history_kind,
        status=status,
        lifecycle_phase=lifecycle_phase,
        task_state=task_state_key,
        source_key=source_key,
        message=message,
        raw=raw,
    )
    bits = []
    if history_kind:
        bits.append(history_kind_summary_label(history_kind, event_type))
    if provider_key:
        bits.append(source_display_label(provider_key))
    elif source:
        bits.append(source)
    if lifecycle_phase:
        bits.append(lifecycle_phase.replace("_", " "))
    if provider and provider != source:
        bits.append(provider)
    if download_client and download_client not in {source, provider}:
        bits.append(download_client)
    if status:
        status_label = str(status).replace("_", " ")
        if not lifecycle_phase or status_label.lower() != lifecycle_phase.replace("_", " ").lower():
            bits.append(status_label)
    if message:
        bits.append(message)
    out["status"] = status
    out["outcome"] = outcome
    out["display_phase"] = display_phase
    out["display_phase_label"] = DISPLAY_PHASE_LABELS.get(display_phase, str(display_phase or "").replace("_", " ").title())
    out["history_kind"] = history_kind
    out["provider_id"] = provider_key or None
    out["provider_key"] = provider_key or None
    out["source_provider_id"] = source_provider_id or None
    out["lifecycle_phase"] = lifecycle_phase or None
    out["candidate_identity"] = candidate_identity or None
    out["failure_reason"] = failure_reason or None
    out["retry_eligible"] = retry_eligible
    out["display_source"] = provider_key or source or provider or download_client
    out["activity_summary"] = " · ".join(str(bit) for bit in bits if bit not in (None, ""))
    out["next_action"] = next_action
    out["details"] = compact_history_details(raw)
    out["raw_available"] = bool(raw)
    download_taxonomy = history_download_taxonomy(out, raw)
    out.update(download_taxonomy)
    if history_kind == "import":
        out["history_view_bucket"] = "imports"
    elif history_kind == "verification":
        out["history_view_bucket"] = "verification"
    elif history_kind == "cleanup":
        out["history_view_bucket"] = "cleanup"
    out.pop("queue_raw_json", None)
    out.pop("series_source", None)
    out.pop("series_metadata_provider", None)
    out.pop("series_metadata_id", None)
    out.pop("series_kapowarr_id", None)
    return out


def history_row_ownership(row):
    row = row if isinstance(row, dict) else {}
    queue_raw = json_loads(row.get("queue_raw_json") or "{}", {})
    if not isinstance(queue_raw, dict):
        queue_raw = {}
    series_source = str(row.get("series_source") or "").strip().lower()
    series_metadata_provider = str(row.get("series_metadata_provider") or "").strip().lower()
    series_metadata_id = row.get("series_metadata_id")
    series_kapowarr_id = row.get("series_kapowarr_id")
    history_raw = row.get("raw_json") if isinstance(row.get("raw_json"), dict) else json_loads(row.get("raw_json") or "{}", {})
    if not isinstance(history_raw, dict):
        history_raw = {}
    source = str(
        queue_raw.get("source")
        or queue_raw.get("currentSource")
        or queue_raw.get("current_source")
        or row.get("queue_current_source")
        or ""
    ).strip().lower()
    metadata_provider = str(
        queue_raw.get("metadata_provider")
        or queue_raw.get("metadataProvider")
        or queue_raw.get("metadata_source")
        or series_metadata_provider
        or history_raw.get("metadata_provider")
        or history_raw.get("metadataProvider")
        or ""
    ).strip().lower()
    metadata_id = (
        queue_raw.get("metadata_id")
        or queue_raw.get("metadataId")
        or queue_raw.get("metadataid")
        or queue_raw.get("kapowarrMetadataId")
        or history_raw.get("metadata_id")
        or history_raw.get("metadataId")
        or history_raw.get("metadataid")
        or history_raw.get("kapowarrMetadataId")
    )
    if metadata_id in (None, ""):
        metadata_id = series_metadata_id
    kapowarr_id = (
        queue_raw.get("kapowarr_id")
        or queue_raw.get("kapowarrId")
        or queue_raw.get("kapowarrid")
        or history_raw.get("kapowarr_id")
        or history_raw.get("kapowarrId")
    )
    if kapowarr_id in (None, ""):
        kapowarr_id = series_kapowarr_id
    if not (source or metadata_provider or series_source or metadata_id not in (None, "") or kapowarr_id not in (None, "")):
        return None
    source = source or series_source
    metadata_provider = metadata_provider or series_metadata_provider
    return ownership_evidence(
        source=source or series_source,
        metadata_provider=metadata_provider,
        metadata_id=metadata_id,
        kapowarr_id=kapowarr_id,
        raw=queue_raw or history_raw,
    )


def backfill_history_event_activity_columns(con, batch_size=1000, limit=None):
    if not table_exists(con, "history_events"):
        return 0
    columns = {row["name"] for row in con.execute("pragma table_info(history_events)")}
    if "outcome" not in columns or "display_phase" not in columns:
        return 0
    batch_size = max(1, min(int(batch_size or 1000), 5000))
    source_attempt_columns = {row["name"] for row in con.execute("pragma table_info(source_attempts)")}
    download_task_columns = {row["name"] for row in con.execute("pragma table_info(download_tasks)")}
    sa_provider_id = "sa.provider_id" if "provider_id" in source_attempt_columns else "null"
    import_sa_provider_id = "import_sa.provider_id" if "provider_id" in source_attempt_columns else "null"
    dt_provider_id = "dt.provider_id" if "provider_id" in download_task_columns else "null"
    sa_source_type = "sa.source_type" if "source_type" in source_attempt_columns else "null"
    import_sa_source_type = "import_sa.source_type" if "source_type" in source_attempt_columns else "null"
    sa_lifecycle_phase = "sa.lifecycle_phase" if "lifecycle_phase" in source_attempt_columns else "null"
    import_sa_lifecycle_phase = "import_sa.lifecycle_phase" if "lifecycle_phase" in source_attempt_columns else "null"
    dt_lifecycle_phase = "dt.lifecycle_phase" if "lifecycle_phase" in download_task_columns else "null"
    sa_candidate_identity = "sa.candidate_identity" if "candidate_identity" in source_attempt_columns else "null"
    import_sa_candidate_identity = "import_sa.candidate_identity" if "candidate_identity" in source_attempt_columns else "null"
    sa_failure_reason = "sa.failure_reason" if "failure_reason" in source_attempt_columns else "null"
    import_sa_failure_reason = "import_sa.failure_reason" if "failure_reason" in source_attempt_columns else "null"
    sa_retry_eligible = "sa.retry_eligible" if "retry_eligible" in source_attempt_columns else "null"
    sa_score = "sa.score" if "score" in source_attempt_columns else "null"
    import_sa_score = "import_sa.score" if "score" in source_attempt_columns else "null"
    dt_score = "dt.score" if "score" in download_task_columns else "null"
    remaining = None if limit is None else max(0, int(limit or 0))
    updated = 0
    while remaining is None or remaining > 0:
        fetch_limit = batch_size if remaining is None else min(batch_size, remaining)
        rows = con.execute(
            f"""
            with target as (
                select id
                from history_events
                where nullif(trim(coalesce(outcome, '')), '') is null
                   or nullif(trim(coalesce(display_phase, '')), '') is null
                order by created_at desc, id desc
                limit ?
            )
            select h.id, h.entity_type, h.entity_id, h.created_at,
                   h.event_type, h.source, h.message, h.outcome, h.display_phase, h.raw_json,
                   coalesce(h.series_id, sa.series_id, ir.series_id, dt.series_id, q.series_id) as series_id,
                   coalesce(h.issue_id, sa.issue_id, ir.issue_id, dt.issue_id, q.issue_id) as issue_id,
                   q.id as queue_id,
                   q.wanted_id as wanted_id,
                   coalesce(sa.id, ir.source_attempt_id, dt.source_attempt_id) as source_attempt_id,
                   case when h.entity_type = 'source_attempt' and exists (
                       select 1 from download_tasks linked_dt where linked_dt.source_attempt_id = h.entity_id
                   ) then 1 else 0 end as source_attempt_has_download_task,
                   dt.id as download_task_id,
                   dt.state as download_task_state,
                   dt.status as download_task_status,
                   dt.source as download_task_source,
                   dt.provider as download_task_provider,
                   dt.protocol as download_task_protocol,
                   dt.download_client as download_task_client,
                   dt.title as download_task_title,
                   dt.category as download_task_category,
                   dt.size_bytes as download_task_size_bytes,
                   dt.progress as download_task_progress,
                   dt.started_at as download_task_started_at,
                   dt.updated_at as download_task_updated_at,
                   dt.completed_at as download_task_completed_at,
                   ir.id as import_id,
                   s.title as series, i.issue_number,
                   coalesce(sa.status, import_sa.status, dt.status) as source_status,
                   coalesce(sa.title, import_sa.title, dt.title) as source_title,
                   coalesce({sa_provider_id}, {import_sa_provider_id}, {dt_provider_id}) as source_provider_id,
                   coalesce({sa_source_type}, {import_sa_source_type}) as source_type,
                   coalesce({sa_lifecycle_phase}, {import_sa_lifecycle_phase}, {dt_lifecycle_phase}) as lifecycle_phase,
                   coalesce({sa_candidate_identity}, {import_sa_candidate_identity}) as candidate_identity,
                   coalesce({sa_failure_reason}, {import_sa_failure_reason}) as failure_reason,
                   {sa_retry_eligible} as retry_eligible,
                   coalesce(sa.provider, import_sa.provider, dt.provider) as source_provider,
                   coalesce(sa.download_client, import_sa.download_client, dt.download_client) as source_download_client,
                   coalesce(sa.protocol, import_sa.protocol, dt.protocol) as source_protocol,
                   sa.source as source_attempt_source,
                   coalesce({sa_score}, {import_sa_score}, {dt_score}) as source_score,
                   ir.status as import_status, ir.verified as import_verified,
                   ir.dest_path as import_dest_path,
                   q.state as queue_state, q.current_source as queue_current_source
            from target t
            join history_events h on h.id = t.id
            left join series s on s.id = h.series_id
            left join issues i on i.id = h.issue_id
            left join source_attempts sa on h.entity_type = 'source_attempt' and sa.id = h.entity_id
            left join import_results ir on h.entity_type = 'import_result' and ir.id = h.entity_id
            left join download_tasks dt on h.entity_type = 'download_task' and dt.id = h.entity_id
            left join source_attempts import_sa on import_sa.id = ir.source_attempt_id
            left join queue_items q on q.id = case
                when h.entity_type = 'queue_item' then h.entity_id
                when h.entity_type = 'source_attempt' then sa.queue_id
                when h.entity_type = 'import_result' then ir.queue_id
                when h.entity_type = 'download_task' then dt.queue_id
                else null
            end
            order by h.created_at desc, h.id desc
            """,
            (fetch_limit,),
        ).fetchall()
        if not rows:
            break
        for row in rows:
            item = history_row_from_record(row)
            outcome = str(item.get("outcome") or "neutral").strip().lower() or "neutral"
            display_phase = str(item.get("display_phase") or "observed").strip().lower() or "observed"
            con.execute(
                "update history_events set outcome=?, display_phase=? where id=?",
                (outcome, display_phase, row["id"]),
            )
            updated += 1
        con.commit()
        if remaining is not None:
            remaining -= len(rows)
    return updated


HISTORY_FILTERS = {
    "activity": ("Lifecycle", "activity"),
    "downloads": ("Downloads", "downloads"),
    "imports": ("Imports", "imports"),
    "verification": ("Verification", "verification"),
    "all": ("Diagnostics", None),
    "series": ("Series", "series"),
    "sources": ("Sources", "sources"),
    "reader_sync": ("Reader Sync", "reader_sync"),
    "providers": ("Providers", "providers"),
    "settings": ("Settings", "settings"),
    "queue": ("Queue", "queue"),
    "cleanup": ("Cleanup", "cleanup"),
    "exceptions": ("Exceptions", "exceptions"),
}


def history_filter_key(history_filter):
    value = str(history_filter or "activity").strip().lower().replace("-", "_")
    return value if value in HISTORY_FILTERS else "activity"


EXPENSIVE_HISTORY_FILTERS = {"activity", "downloads", "sources", "queue", "verification", "cleanup", "exceptions"}


HISTORY_LEGACY_DOWNLOAD_ATTEMPT_STATUSES = set(DOWNLOAD_TASK_STATUSES) | {"importing"}
HISTORY_SOURCE_ATTEMPT_NON_DOWNLOAD_STATUSES = {
    "provider_wait",
    "provider_unavailable",
}


HISTORY_TERMINAL_DOWNLOAD_FAILURE_STATUSES = {
    status for status in DOWNLOAD_TASK_STATUSES if download_task_state(status) == "failed"
}


def history_sql_values(values):
    return ",".join("'" + str(value).replace("'", "''") + "'" for value in sorted(values))


def history_terminal_download_sql_clause(alias="h"):
    raw = f"case when json_valid({alias}.raw_json) then {alias}.raw_json else '{{}}' end"
    sql_whitespace = "' ' || char(9) || char(10) || char(11) || char(12) || char(13)"

    def json_text(path):
        return f"nullif(trim(cast(json_extract({raw}, '{path}') as text), {sql_whitespace}), '')"

    def typed_text(expression):
        return f"nullif(trim(cast({expression} as text), {sql_whitespace}), '')"

    raw_status = f"lower(coalesce({json_text('$.status')}, ''))"
    raw_state = f"lower(coalesce({json_text('$.state')}, ''))"
    raw_phase = f"lower(coalesce({json_text('$.lifecycle_phase')}, ''))"
    raw_outcome = f"lower(coalesce({json_text('$.outcome')}, {typed_text(f'{alias}.outcome')}, ''))"
    raw_event_source = f"""lower(coalesce(
        {json_text('$.source')},
        {typed_text(f'{alias}.source')},
        (select {typed_text('sa.source')} from source_attempts sa where sa.id={alias}.entity_id),
        ''
    ))"""
    raw_provider_or_client = f"""lower(coalesce(
        {json_text('$.provider_id')},
        {json_text('$.download_client')},
        (select coalesce(
             {typed_text('sa.provider_id')}, {typed_text('sa.download_client')},
             {typed_text('sa.provider')}, {typed_text('sa.protocol')}, ''
         )
         from source_attempts sa where sa.id={alias}.entity_id),
        ''
    ))"""
    task_status = f"coalesce(nullif({raw_status}, ''), (select lower(coalesce({typed_text('dt.status')},'')) from download_tasks dt where dt.id={alias}.entity_id))"
    task_state = f"coalesce(nullif({raw_state}, ''), (select lower(coalesce({typed_text('dt.state')},'')) from download_tasks dt where dt.id={alias}.entity_id))"
    task_phase = f"coalesce(nullif({raw_phase}, ''), (select lower(coalesce({typed_text('dt.lifecycle_phase')},'')) from download_tasks dt where dt.id={alias}.entity_id))"
    attempt_status = f"coalesce(nullif({raw_status}, ''), (select lower(coalesce({typed_text('sa.status')},'')) from source_attempts sa where sa.id={alias}.entity_id))"
    attempt_state = raw_state
    attempt_phase = f"coalesce(nullif({raw_phase}, ''), (select lower(coalesce({typed_text('sa.lifecycle_phase')},'')) from source_attempts sa where sa.id={alias}.entity_id))"
    active_statuses = history_sql_values(DOWNLOAD_TASK_WAITING_STATUSES | DOWNLOAD_TASK_TRANSFERRING_STATUSES)
    success_states = history_sql_values(HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATES)
    failure_states = history_sql_values(HISTORY_TERMINAL_DOWNLOAD_FAILURE_STATES)
    success_statuses = history_sql_values(HISTORY_TERMINAL_DOWNLOAD_SUCCESS_STATUSES)
    failure_statuses = history_sql_values(HISTORY_TERMINAL_DOWNLOAD_FAILURE_STATUSES)
    legacy_statuses = history_sql_values(HISTORY_LEGACY_DOWNLOAD_ATTEMPT_STATUSES)

    def terminal(state, status, phase):
        return f"""
            {state} not in ('queued','downloading')
            and {phase} not in ('queued','waiting','provider_wait','downloading')
            and {status} not in ({active_statuses})
            and (
                {state} in ({success_states},{failure_states})
                or {status} in ({success_statuses},{failure_statuses})
                or {phase} in ('staged_or_importing','verified','completed','failed_candidate','failed','blocked')
                or ({raw_outcome}='problem' and {status} not in ('provider_wait','provider_unavailable'))
            )
        """

    return f"""
        (
            ({alias}.event_type='download_task' or {alias}.entity_type='download_task')
            and ({terminal(task_state, task_status, task_phase)})
        )
        or (
            ({alias}.event_type='source_attempt' or {alias}.entity_type='source_attempt')
            and not exists (select 1 from download_tasks linked_dt where linked_dt.source_attempt_id={alias}.entity_id)
            and (
                {raw_event_source}='download_client'
                or (({raw_event_source}='slskd' or {raw_provider_or_client}='slskd') and {attempt_status} in ({legacy_statuses}))
            )
            and ({terminal(attempt_state, attempt_status, attempt_phase)})
        )
    """


def history_text_has_status(text, statuses):
    normalized = re.sub(r"[\s-]+", "_", str(text or "").strip().lower())
    return any(status in normalized for status in statuses)


def history_source_attempt_looks_like_download(source="", message="", status=""):
    source = str(source or "").strip().lower()
    status = str(status or "").strip().lower()
    if source == "download_client":
        return True
    if source != "slskd":
        return False
    if status and status in HISTORY_SOURCE_ATTEMPT_NON_DOWNLOAD_STATUSES:
        return False
    if not status and history_text_has_status(message, HISTORY_SOURCE_ATTEMPT_NON_DOWNLOAD_STATUSES):
        return False
    if status:
        return status in HISTORY_LEGACY_DOWNLOAD_ATTEMPT_STATUSES
    return history_text_has_status(message, HISTORY_LEGACY_DOWNLOAD_ATTEMPT_STATUSES)


def history_lifecycle_sql_clause(alias="h"):
    """Canonical persisted download/import lifecycle category."""
    return f"{alias}.history_bucket='lifecycle'"


def history_field_kind(event_type, entity_type="", source="", message=""):
    event_type = str(event_type or "").strip().lower()
    entity_type = str(entity_type or "").strip().lower()
    source = str(source or "").strip().lower()
    message = str(message or "").strip().lower()
    if event_type in {"library_frontend_sync_requested", "library_frontend_visibility_rechecked"}:
        return "reader_sync"
    if event_type == "stale_completion_retracted" or entity_type == "import_ledger":
        return "cleanup"
    if (
        event_type == "import_verified"
        or source == "kavita"
        or (event_type == "source_attempt" and source == "importer" and "verified" in message)
        or "kavita verified" in message
        or "kavita already has issue" in message
        or "downloader/import reconciliation says satisfied" in message
    ):
        return "verification"
    if "superseded" in message or "duplicate queue row" in message:
        return "cleanup"
    if event_type.startswith("import"):
        return "import"
    if event_type == "download_task" or entity_type == "download_task":
        return "download"
    if event_type == "source_attempt" and history_source_attempt_looks_like_download(source, message):
        return "download"
    if event_type == "source_attempt" and source not in {"", "kavita", "importer"}:
        return "source"
    if event_type == "autopilot_series_run":
        return "source"
    if event_type in {"provider_test", "provider_update", "provider_health"} or entity_type == "provider":
        return "provider"
    if event_type in {"provider_update", "settings_update", "settings_sync"} or entity_type == "setting":
        return "settings"
    if event_type in {"queue_retry_requested", "wanted_search_requested", "series_search_requested"}:
        return "queue"
    if event_type == "queue_event":
        return "queue"
    if event_type in {"series_added", "series_add_failed", "series_monitor_synced"} or entity_type == "series":
        return "series"
    return event_type.replace("_", " ")


def history_filter_matches_fields(history_filter, event_type, entity_type="", source="", message=""):
    value = history_filter_key(history_filter)
    if value == "all":
        return True
    event_type = str(event_type or "").strip().lower()
    entity_type = str(entity_type or "").strip().lower()
    source = str(source or "").strip().lower()
    message = str(message or "").strip().lower()
    kind = history_field_kind(event_type, entity_type, source, message)
    if value == "activity":
        return (
            event_type == "download_task"
            or entity_type == "download_task"
            or event_type.startswith("import")
            or entity_type == "import_result"
            or kind == "verification"
        )
    if value == "series":
        return event_type in {"series_added", "series_add_failed", "series_monitor_synced", "series_search_requested"} or entity_type == "series"
    if value == "sources":
        return event_type == "source_attempt" and source not in {"kavita", "importer"}
    if value == "downloads":
        return event_type == "download_task" or entity_type == "download_task" or (
            event_type == "source_attempt" and history_source_attempt_looks_like_download(source, message)
        )
    if value == "reader_sync":
        return kind == "reader_sync"
    if value == "providers":
        return event_type in {"provider_test", "provider_update", "provider_health"} or entity_type == "provider"
    if value == "settings":
        return event_type in {"provider_update", "settings_update", "settings_sync"} or entity_type == "setting"
    if value == "queue":
        return kind == "queue"
    if value == "imports":
        return event_type.startswith("import")
    if value == "verification":
        return kind == "verification"
    if value == "cleanup":
        return kind == "cleanup"
    if value == "exceptions":
        return any(token in message for token in ("fail", "error", "blocked", "exhausted"))
    return True


def history_filter_matches_row(history_filter, row):
    value = history_filter_key(history_filter)
    row = row or {}
    kind = str(row.get("history_kind") or "").strip().lower()
    lifecycle_phase = str(row.get("lifecycle_phase") or "").strip().lower()
    status = str(row.get("status") or "").strip().lower()
    message = str(row.get("message") or "").strip().lower()
    if value == "all":
        return True
    if kind:
        if value == "activity":
            return (
                str(row.get("event_type") or "").strip().lower().startswith("import")
                or str(row.get("entity_type") or "").strip().lower() == "import_result"
                or kind == "verification"
                or str(row.get("event_type") or "").strip().lower() == "download_task"
                or str(row.get("entity_type") or "").strip().lower() == "download_task"
            )
        if value == "sources":
            return kind == "source"
        if value == "downloads":
            return bool(row.get("download_outcome_terminal")) and row.get("history_view_bucket") == "downloads"
        if value == "reader_sync":
            return kind == "reader_sync"
        if value == "providers":
            return kind == "provider"
        if value == "settings":
            return kind == "settings"
        if value == "queue":
            return kind == "queue"
        if value == "imports":
            return kind == "import"
        if value == "verification":
            return kind == "verification"
        if value == "cleanup":
            return kind == "cleanup"
        if value == "exceptions":
            return (
                lifecycle_phase in {"failed_candidate", "manual_review", "provider_wait"}
                or any(token in status for token in ("fail", "error", "blocked", "exhausted"))
                or any(token in message for token in ("fail", "error", "blocked", "exhausted"))
            )
    return history_filter_matches_fields(
        value,
        row.get("event_type"),
        row.get("entity_type"),
        row.get("source") or row.get("display_source"),
        row.get("message"),
    )


def history_filter_clause(history_filter):
    value = history_filter_key(history_filter)
    if value == "all":
        return value, "", []
    if value == "activity":
        return value, history_lifecycle_sql_clause("h"), []
    if value == "sources":
        return value, """
            h.event_type = 'autopilot_series_run'
            or (
                h.event_type = 'source_attempt'
                and lower(coalesce(
                    (select sa.provider_id from source_attempts sa where sa.id = h.entity_id),
                    h.source,
                    ''
                )) not in ('kavita','importer')
                and lower(coalesce(
                    (select sa.source_type from source_attempts sa where sa.id = h.entity_id),
                    ''
                )) <> 'library'
            )
        """, []
    if value == "downloads":
        return value, history_terminal_download_sql_clause("h"), []
    if value == "reader_sync":
        return value, "h.event_type in ('library_frontend_sync_requested', 'library_frontend_visibility_rechecked')", []
    if value == "series":
        return value, "h.event_type in ('series_added', 'series_add_failed', 'series_monitor_synced', 'series_search_requested') or h.entity_type = 'series'", []
    if value == "providers":
        return value, "h.event_type in ('provider_test', 'provider_update', 'provider_health') or h.entity_type = 'provider'", []
    if value == "settings":
        return value, "h.event_type in ('provider_update', 'settings_update', 'settings_sync') or h.entity_type = 'setting'", []
    if value == "queue":
        return value, """
            h.event_type in ('queue_retry_requested', 'wanted_search_requested', 'series_search_requested')
            or (
                h.event_type = 'queue_event'
                and lower(coalesce(h.message,'')) not like '%superseded%'
                and lower(coalesce(h.message,'')) not like '%duplicate queue row%'
                and lower(coalesce(h.message,'')) not like '%kavita verified%'
                and lower(coalesce(h.message,'')) not like '%kavita already has issue%'
                and lower(coalesce(h.message,'')) not like '%downloader/import reconciliation says satisfied%'
            )
        """, []
    if value == "imports":
        return value, "h.event_type like 'import%'", []
    if value == "verification":
        return value, """
            h.event_type = 'import_verified'
            or lower(coalesce(h.source,'')) = 'kavita'
            or (h.event_type = 'source_attempt' and lower(coalesce(h.source,'')) = 'importer' and lower(coalesce(h.message,'')) like '%verified%')
            or lower(coalesce(h.message,'')) like '%kavita verified%'
            or lower(coalesce(h.message,'')) like '%kavita already has issue%'
            or lower(coalesce(h.message,'')) like '%downloader/import reconciliation says satisfied%'
        """, []
    if value == "cleanup":
        return value, """
            h.event_type = 'stale_completion_retracted'
            or h.entity_type = 'import_ledger'
            or lower(coalesce(h.message,'')) like '%superseded%'
            or lower(coalesce(h.message,'')) like '%stale completion%'
        """, []
    if value == "exceptions":
        return value, """
            lower(coalesce(h.message, '')) like '%fail%'
            or lower(coalesce(h.message, '')) like '%error%'
            or lower(coalesce(h.message, '')) like '%blocked%'
            or lower(coalesce(h.message, '')) like '%exhausted%'
            or exists (
                select 1 from source_attempts sa
                where sa.id = h.entity_id
                  and lower(coalesce(sa.lifecycle_phase,'')) in ('failed_candidate', 'manual_review', 'provider_wait')
            )
            or exists (
                select 1 from download_tasks dt
                where dt.id = h.entity_id
                  and lower(coalesce(dt.lifecycle_phase,'')) in ('failed_candidate', 'manual_review', 'provider_wait')
            )
        """, []
    return value, "", []


def history_base_from_join():
    return """
        from history_events h
        left join series s on s.id = h.series_id
        left join issues i on i.id = h.issue_id
        left join source_attempts sa on h.entity_type = 'source_attempt' and sa.id = h.entity_id
        left join import_results ir on h.entity_type = 'import_result' and ir.id = h.entity_id
        left join download_tasks dt on h.entity_type = 'download_task' and dt.id = h.entity_id
        left join queue_items q on q.id = case
            when h.entity_type = 'queue_item' then h.entity_id
            when h.entity_type = 'source_attempt' then sa.queue_id
            when h.entity_type = 'import_result' then ir.queue_id
            when h.entity_type = 'download_task' then dt.queue_id
            else null
        end
    """


def recent_history(db_path, limit=40, history_filter=None, focus=None):
    db_path = Path(db_path)
    if not db_path.exists():
        return []
    history_filter, where_sql, where_params = history_filter_clause(history_filter)
    focus = normalize_focus_entities(focus)
    limit = max(1, int(limit or 40))
    with connect_read(db_path) as probe_con:
        history_columns = {row["name"] for row in probe_con.execute("pragma table_info(history_events)")}
        source_attempt_columns = {row["name"] for row in probe_con.execute("pragma table_info(source_attempts)")}
        download_task_columns = {row["name"] for row in probe_con.execute("pragma table_info(download_tasks)")}
    outcome_expr = "h.outcome" if "outcome" in history_columns else "null"
    display_phase_expr = "h.display_phase" if "display_phase" in history_columns else "null"
    sa_provider_id = "sa.provider_id" if "provider_id" in source_attempt_columns else "null"
    import_sa_provider_id = "import_sa.provider_id" if "provider_id" in source_attempt_columns else "null"
    dt_provider_id = "dt.provider_id" if "provider_id" in download_task_columns else "null"
    sa_source_type = "sa.source_type" if "source_type" in source_attempt_columns else "null"
    import_sa_source_type = "import_sa.source_type" if "source_type" in source_attempt_columns else "null"
    sa_lifecycle_phase = "sa.lifecycle_phase" if "lifecycle_phase" in source_attempt_columns else "null"
    import_sa_lifecycle_phase = "import_sa.lifecycle_phase" if "lifecycle_phase" in source_attempt_columns else "null"
    dt_lifecycle_phase = "dt.lifecycle_phase" if "lifecycle_phase" in download_task_columns else "null"
    sa_candidate_identity = "sa.candidate_identity" if "candidate_identity" in source_attempt_columns else "null"
    import_sa_candidate_identity = "import_sa.candidate_identity" if "candidate_identity" in source_attempt_columns else "null"
    sa_failure_reason = "sa.failure_reason" if "failure_reason" in source_attempt_columns else "null"
    import_sa_failure_reason = "import_sa.failure_reason" if "failure_reason" in source_attempt_columns else "null"
    sa_retry_eligible = "sa.retry_eligible" if "retry_eligible" in source_attempt_columns else "null"
    sa_score = "sa.score" if "score" in source_attempt_columns else "null"
    import_sa_score = "import_sa.score" if "score" in source_attempt_columns else "null"
    dt_score = "dt.score" if "score" in download_task_columns else "null"
    if history_filter in EXPENSIVE_HISTORY_FILTERS or focus:
        candidate_floor = 10000 if history_filter in {"activity", "downloads"} else 1000
        candidate_limit = max(candidate_floor, min(10000, limit * 100))
        direct_series_focus = set(focus) == {"series_id"}
        direct_issue_focus = set(focus) == {"issue_id"}
        focus_joins = """
            left join source_attempts focus_sa on h.entity_type='source_attempt' and focus_sa.id=h.entity_id
            left join import_results focus_ir on h.entity_type='import_result' and focus_ir.id=h.entity_id
            left join download_tasks focus_dt on h.entity_type='download_task' and focus_dt.id=h.entity_id
            left join queue_items focus_q on focus_q.id=case
                when h.entity_type='queue_item' then h.entity_id
                when h.entity_type='source_attempt' then focus_sa.queue_id
                when h.entity_type='import_result' then focus_ir.queue_id
                when h.entity_type='download_task' then focus_dt.queue_id
                else null end
        """ if focus and not (direct_series_focus or direct_issue_focus) else ""
        focus_clauses = []
        focus_params = []
        if focus.get("series_id"):
            focus_clauses.append("h.series_id=?" if direct_series_focus else "coalesce(h.series_id,focus_sa.series_id,focus_ir.series_id,focus_dt.series_id,focus_q.series_id)=?")
            focus_params.append(focus["series_id"])
        if focus.get("issue_id"):
            focus_clauses.append("h.issue_id=?" if direct_issue_focus else "coalesce(h.issue_id,focus_sa.issue_id,focus_ir.issue_id,focus_dt.issue_id,focus_q.issue_id)=?")
            focus_params.append(focus["issue_id"])
        if focus.get("queue_id"):
            focus_clauses.append("focus_q.id=?")
            focus_params.append(focus["queue_id"])
        if focus.get("wanted_id"):
            focus_clauses.append("focus_q.wanted_id=?")
            focus_params.append(focus["wanted_id"])
        if focus.get("source_attempt_id"):
            focus_clauses.append("(focus_sa.id=? or focus_ir.source_attempt_id=? or focus_dt.source_attempt_id=?)")
            focus_params.extend((focus["source_attempt_id"],) * 3)
        if focus.get("download_task_id"):
            focus_clauses.append("(h.entity_type='download_task' and h.entity_id=?)")
            focus_params.append(focus["download_task_id"])
        if focus.get("import_id"):
            focus_clauses.append("(h.entity_type='import_result' and h.entity_id=?)")
            focus_params.append(focus["import_id"])
        candidate_clauses = []
        candidate_params = []
        if focus_clauses:
            candidate_clauses.append("(" + " or ".join(focus_clauses) + ")")
            candidate_params.extend(focus_params)
        candidate_where = "where " + " and ".join(candidate_clauses) if candidate_clauses else ""
        bounded_where = f"where {where_sql}" if history_filter == "downloads" else ""
        bounded_limit = "limit ?" if history_filter in {"activity", "downloads"} else ""
        # A focused history read resolves through per-entity indexed branches, never the
        # focus_joins form below. The join form evaluates four LEFT JOINs across every
        # history_events row before the limit applies; on a 1.5M row table that measured
        # ~79s, and it recovers no extra rows -- of the rows with no issue_id, zero
        # resolve to an issue through those joins (they are provider/series/state_repair
        # events that were never unit-scoped). Only the lifecycle-bucket predicate is
        # filter-dependent, so it is parameterized rather than hardcoded here.
        lifecycle_only = history_filter == "activity"
        bucket_pred = "history_bucket='lifecycle' and " if lifecycle_only else ""
        bucket_and = " and h.history_bucket='lifecycle'" if lifecycle_only else ""
        focus_branches = []
        entity_params = []
        if focus:
            def direct_history_branch(index_name, column, value):
                focus_branches.append(f"select id,created_at from (select id,created_at from history_events indexed by {index_name} where {bucket_pred}{column}=? order by created_at desc,id desc limit ?)")
                entity_params.extend((value, candidate_limit))

            def linked_history_branch(table, index_name, column, value, entity_type):
                focus_branches.append(f"select h.id,h.created_at from (select id from {table} indexed by {index_name} where {column}=? limit ?) target cross join history_events h indexed by idx_history_entity_created where h.entity_type='{entity_type}' and h.entity_id=target.id{bucket_and}")
                entity_params.extend((value, candidate_limit))

            if focus.get("series_id"):
                value = focus["series_id"]
                direct_history_branch(
                    "idx_history_bucket_series_created" if lifecycle_only else "idx_history_series_created",
                    "series_id",
                    value,
                )
                linked_history_branch("source_attempts", "idx_source_attempts_series_recent", "series_id", value, "source_attempt")
                linked_history_branch("download_tasks", "idx_download_tasks_series_issue_updated", "series_id", value, "download_task")
                linked_history_branch("import_results", "idx_import_results_series_created", "series_id", value, "import_result")
                linked_history_branch("queue_items", "idx_queue_series_state_active_updated", "series_id", value, "queue_item")
            if focus.get("issue_id"):
                value = focus["issue_id"]
                direct_history_branch(
                    "idx_history_bucket_issue_created" if lifecycle_only else "idx_history_issue_created",
                    "issue_id",
                    value,
                )
                linked_history_branch("source_attempts", "idx_source_attempts_issue_recent", "issue_id", value, "source_attempt")
                linked_history_branch("download_tasks", "idx_download_tasks_issue_updated", "issue_id", value, "download_task")
                linked_history_branch("import_results", "idx_import_results_issue_verified_created", "issue_id", value, "import_result")
                linked_history_branch("queue_items", "idx_queue_issue_updated", "issue_id", value, "queue_item")
            if focus.get("queue_id"):
                value = focus["queue_id"]
                direct_history_branch("idx_history_entity_created", "entity_type='queue_item' and entity_id", value)
                linked_history_branch("source_attempts", "idx_source_attempts_queue_recent", "queue_id", value, "source_attempt")
                linked_history_branch("download_tasks", "idx_download_tasks_queue_updated", "queue_id", value, "download_task")
                linked_history_branch("import_results", "idx_import_results_queue_created", "queue_id", value, "import_result")
            if focus.get("wanted_id"):
                value = focus["wanted_id"]
                linked_history_branch("queue_items", "idx_queue_wanted_updated", "wanted_id", value, "queue_item")
                linked_history_branch("source_attempts", "idx_source_attempts_wanted_recent", "wanted_id", value, "source_attempt")
                linked_history_branch("download_tasks", "idx_download_tasks_wanted_updated", "wanted_id", value, "download_task")
                focus_branches.append(f"select h.id,h.created_at from (select ir.id from queue_items q indexed by idx_queue_wanted_updated join import_results ir indexed by idx_import_results_queue_created on ir.queue_id=q.id where q.wanted_id=? limit ?) target cross join history_events h indexed by idx_history_entity_created where h.entity_type='import_result' and h.entity_id=target.id{bucket_and}")
                entity_params.extend((value, candidate_limit))
            if focus.get("source_attempt_id"):
                value = focus["source_attempt_id"]
                direct_history_branch("idx_history_entity_created", "entity_type='source_attempt' and entity_id", value)
                linked_history_branch("download_tasks", "idx_download_tasks_source_attempt", "source_attempt_id", value, "download_task")
                linked_history_branch("import_results", "idx_import_results_source_attempt_created", "source_attempt_id", value, "import_result")
            if focus.get("download_task_id"):
                direct_history_branch("idx_history_entity_created", "entity_type='download_task' and entity_id", focus["download_task_id"])
            if focus.get("import_id"):
                direct_history_branch("idx_history_entity_created", "entity_type='import_result' and entity_id", focus["import_id"])
        if focus_branches:
            recent_cte_sql = f"""
                focus_candidate_pool as materialized ({' union all '.join(focus_branches)}),
                focus_candidate_ids as materialized (select id,max(created_at) as created_at from focus_candidate_pool group by id),
                recent_h as materialized (
                    select h.*
                    from focus_candidate_ids target join history_events h on h.id=target.id
                    order by target.created_at desc,target.id desc
                    limit ?
                )
            """
            # bounded_where/bounded_limit are only emitted for some filters, so bind
            # exactly the placeholders that made it into the outer statement.
            bounded_params = (
                *entity_params,
                candidate_limit,
                *(where_params if history_filter == "downloads" else ()),
                *((limit,) if bounded_limit else ()),
            )
        elif history_filter == "activity":
            recent_cte_sql = f"""
                recent_h as materialized (
                    select h.*
                    from history_events as h indexed by idx_history_bucket_created
                    where h.history_bucket='lifecycle'
                    order by h.created_at desc, h.id desc
                    limit ?
                )
            """
            bounded_params = (candidate_limit, limit)
        else:
            recent_cte_sql = f"""
                recent_h as materialized (
                    select h.*
                    from history_events h
                    {focus_joins}
                    {candidate_where}
                    order by h.created_at desc, h.id desc
                    limit ?
                )
            """
            bounded_params = (
                *candidate_params,
                candidate_limit,
                *(where_params if history_filter == "downloads" else []),
                *((limit,) if history_filter == "downloads" else ()),
            )
        with connect(db_path) as con:
            rows = con.execute(
                f"""
                with {recent_cte_sql}
                select h.id, h.entity_type, h.entity_id, h.created_at,
                       h.event_type, h.source, h.message, {outcome_expr} as outcome, {display_phase_expr} as display_phase, h.raw_json,
                       coalesce(h.series_id, sa.series_id, ir.series_id, dt.series_id, q.series_id) as series_id,
                       q.raw_json as queue_raw_json,
                       s.source as series_source,
                       s.metadata_provider as series_metadata_provider,
                       s.metadata_id as series_metadata_id,
                       s.kapowarr_id as series_kapowarr_id,
                       coalesce(h.issue_id, sa.issue_id, ir.issue_id, dt.issue_id, q.issue_id) as issue_id,
                       q.id as queue_id,
                       q.wanted_id as wanted_id,
                       coalesce(sa.id, ir.source_attempt_id, dt.source_attempt_id) as source_attempt_id,
                       case when h.entity_type = 'source_attempt' and exists (
                           select 1 from download_tasks linked_dt where linked_dt.source_attempt_id = h.entity_id
                       ) then 1 else 0 end as source_attempt_has_download_task,
                       dt.id as download_task_id,
                       dt.state as download_task_state,
                       dt.status as download_task_status,
                       dt.source as download_task_source,
                        dt.provider as download_task_provider,
                        dt.protocol as download_task_protocol,
                        dt.download_client as download_task_client,
                        dt.title as download_task_title,
                        dt.category as download_task_category,
                        dt.size_bytes as download_task_size_bytes,
                        dt.progress as download_task_progress,
                        dt.started_at as download_task_started_at,
                        dt.updated_at as download_task_updated_at,
                        dt.completed_at as download_task_completed_at,
                        ir.id as import_id,
                       s.title as series, i.issue_number,
                       coalesce(sa.status, import_sa.status, dt.status) as source_status,
                       coalesce(sa.title, import_sa.title, dt.title) as source_title,
                       coalesce({sa_provider_id}, {import_sa_provider_id}, {dt_provider_id}) as source_provider_id,
                       coalesce({sa_source_type}, {import_sa_source_type}) as source_type,
                       coalesce({sa_lifecycle_phase}, {import_sa_lifecycle_phase}, {dt_lifecycle_phase}) as lifecycle_phase,
                       coalesce({sa_candidate_identity}, {import_sa_candidate_identity}) as candidate_identity,
                       coalesce({sa_failure_reason}, {import_sa_failure_reason}) as failure_reason,
                       {sa_retry_eligible} as retry_eligible,
                       coalesce(sa.provider, import_sa.provider, dt.provider) as source_provider,
                       coalesce(sa.download_client, import_sa.download_client, dt.download_client) as source_download_client,
                       coalesce(sa.protocol, import_sa.protocol, dt.protocol) as source_protocol,
                       sa.source as source_attempt_source,
                       coalesce({sa_score}, {import_sa_score}, {dt_score}) as source_score,
                       ir.status as import_status, ir.verified as import_verified,
                       ir.dest_path as import_dest_path,
                       q.state as queue_state, q.current_source as queue_current_source
                from recent_h h
                left join issues i on i.id = h.issue_id
                left join source_attempts sa on h.entity_type = 'source_attempt' and sa.id = h.entity_id
                left join import_results ir on h.entity_type = 'import_result' and ir.id = h.entity_id
                left join download_tasks dt on h.entity_type = 'download_task' and dt.id = h.entity_id
                left join source_attempts import_sa on import_sa.id = ir.source_attempt_id
                left join queue_items q on q.id = case
                    when h.entity_type = 'queue_item' then h.entity_id
                    when h.entity_type = 'source_attempt' then sa.queue_id
                    when h.entity_type = 'import_result' then ir.queue_id
                    when h.entity_type = 'download_task' then dt.queue_id
                    else null
                 end
                 left join series s on s.id = coalesce(h.series_id, sa.series_id, ir.series_id, dt.series_id, q.series_id)
                 {bounded_where}
                 order by h.created_at desc, h.id desc
                 {bounded_limit}
                 """,
                bounded_params,
            ).fetchall()
        out = []
        for row in rows:
            item = history_row_from_record(row)
            if history_filter_matches_row(history_filter, item):
                out.append(item)
                if len(out) >= limit:
                    break
        return out
    where_sql = f"where {where_sql}" if where_sql else ""
    with connect(db_path) as con:
        rows = con.execute(
            f"""
            with recent_h as (
                select h.*
                from history_events h
                {where_sql}
                order by h.created_at desc, h.id desc
                limit ?
            )
                select h.id, h.entity_type, h.entity_id, h.created_at,
                       h.event_type, h.source, h.message, {outcome_expr} as outcome, {display_phase_expr} as display_phase, h.raw_json,
                       coalesce(h.series_id, sa.series_id, ir.series_id, dt.series_id, q.series_id) as series_id,
                       q.raw_json as queue_raw_json,
                       s.source as series_source,
                       s.metadata_provider as series_metadata_provider,
                       s.metadata_id as series_metadata_id,
                       s.kapowarr_id as series_kapowarr_id,
                       coalesce(h.issue_id, sa.issue_id, ir.issue_id, dt.issue_id, q.issue_id) as issue_id,
                   q.id as queue_id,
                   q.wanted_id as wanted_id,
                   coalesce(sa.id, ir.source_attempt_id, dt.source_attempt_id) as source_attempt_id,
                   case when h.entity_type = 'source_attempt' and exists (
                       select 1 from download_tasks linked_dt where linked_dt.source_attempt_id = h.entity_id
                   ) then 1 else 0 end as source_attempt_has_download_task,
                   dt.id as download_task_id,
                   dt.state as download_task_state,
                   dt.status as download_task_status,
                   dt.source as download_task_source,
                    dt.provider as download_task_provider,
                    dt.protocol as download_task_protocol,
                    dt.download_client as download_task_client,
                    dt.title as download_task_title,
                    dt.category as download_task_category,
                    dt.size_bytes as download_task_size_bytes,
                    dt.progress as download_task_progress,
                    dt.started_at as download_task_started_at,
                    dt.updated_at as download_task_updated_at,
                    dt.completed_at as download_task_completed_at,
                    ir.id as import_id,
                   s.title as series, i.issue_number,
                   coalesce(sa.status, import_sa.status, dt.status) as source_status,
                   coalesce(sa.title, import_sa.title, dt.title) as source_title,
                   coalesce({sa_provider_id}, {import_sa_provider_id}, {dt_provider_id}) as source_provider_id,
                   coalesce({sa_source_type}, {import_sa_source_type}) as source_type,
                   coalesce({sa_lifecycle_phase}, {import_sa_lifecycle_phase}, {dt_lifecycle_phase}) as lifecycle_phase,
                   coalesce({sa_candidate_identity}, {import_sa_candidate_identity}) as candidate_identity,
                   coalesce({sa_failure_reason}, {import_sa_failure_reason}) as failure_reason,
                   {sa_retry_eligible} as retry_eligible,
                   coalesce(sa.provider, import_sa.provider, dt.provider) as source_provider,
                   coalesce(sa.download_client, import_sa.download_client, dt.download_client) as source_download_client,
                   coalesce(sa.protocol, import_sa.protocol, dt.protocol) as source_protocol,
                   sa.source as source_attempt_source,
                   coalesce({sa_score}, {import_sa_score}, {dt_score}) as source_score,
                   ir.status as import_status, ir.verified as import_verified,
                   ir.dest_path as import_dest_path,
                   q.state as queue_state, q.current_source as queue_current_source
             from recent_h h
             left join issues i on i.id = h.issue_id
             left join source_attempts sa on h.entity_type = 'source_attempt' and sa.id = h.entity_id
             left join import_results ir on h.entity_type = 'import_result' and ir.id = h.entity_id
             left join download_tasks dt on h.entity_type = 'download_task' and dt.id = h.entity_id
             left join source_attempts import_sa on import_sa.id = ir.source_attempt_id
             left join queue_items q on q.id = case
                 when h.entity_type = 'queue_item' then h.entity_id
                 when h.entity_type = 'source_attempt' then sa.queue_id
                 when h.entity_type = 'import_result' then ir.queue_id
                 when h.entity_type = 'download_task' then dt.queue_id
                 else null
             end
             left join series s on s.id = coalesce(h.series_id, sa.series_id, ir.series_id, dt.series_id, q.series_id)
                order by h.created_at desc, h.id desc
                """,
            (*where_params, int(limit)),
        ).fetchall()
        return [history_row_from_record(row) for row in rows]


def history_filter_count(db_path, history_filter):
    db_path = Path(db_path)
    if not db_path.exists():
        return 0
    history_filter, where_sql, where_params = history_filter_clause(history_filter)
    where_sql = f"where {where_sql}" if where_sql else ""
    with connect(db_path) as con:
        row = con.execute(
            f"select count(*) as count from history_events h {where_sql}",
            where_params,
        ).fetchone()
    return int(row["count"] or 0) if row else 0


def history_filter_options(db_path, exact_download_count=True):
    db_path = Path(db_path)
    if not db_path.exists():
        return []
    # Facets are deliberately derived from a fixed recent window.  The old
    # Downloads facet ran the terminal taxonomy predicate over the complete
    # history_events table (including correlated lookups), which could make
    # the normal History page time out on long-lived installations.
    sample_limit = 1000
    counts = {value: 0 for value in HISTORY_FILTERS}
    rows = recent_history(db_path, sample_limit, history_filter="all")
    for row in rows:
        for value in HISTORY_FILTERS:
            if history_filter_matches_row(value, row):
                counts[value] += 1
    return [
        {
            "value": value,
            "label": label,
            "count": counts.get(value, 0),
            "sampled": True,
            "sample_limit": sample_limit,
        }
        for value, (label, _kind) in HISTORY_FILTERS.items()
    ]


def history_view_summary(db_path):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    try:
        mtime_ns = path.stat().st_mtime_ns
    except OSError:
        mtime_ns = None
    with connect_read(path) as con:
        wanted_by_status = {
            row["status"]: int(row["count"] or 0)
            for row in con.execute("select status, count(*) as count from wanted_items group by status")
        }
        queue_by_state = {
            row["state"]: int(row["count"] or 0)
            for row in con.execute("select state, count(*) as count from queue_items group by state")
        }
        queue_by_active_state = {
            row["state"]: int(row["count"] or 0)
            for row in con.execute("select state, count(*) as count from queue_items where active=1 group by state")
        }
        history_count = table_count(con, "history_events")
        summary = {
            "ok": True,
            "db_path": str(path),
            "schema_version": SCHEMA_VERSION,
            "summary_cache": "history_fast_path",
            "summary_cache_age_seconds": 0,
            "mtime_ns": mtime_ns,
            "series": table_count(con, "series"),
            "issues": table_count(con, "issues"),
            "wanted_items": table_count(con, "wanted_items"),
            "wanted_by_status": wanted_by_status,
            "queue_items": table_count(con, "queue_items"),
            "queue_by_state": queue_by_state,
            "active_queue_items": table_count(con, "queue_items", "where active=1"),
            "queue_by_active_state": queue_by_active_state,
            "queue_by_display_active_state": queue_by_active_state,
            "source_attempts": source_attempt_count_from_connection(con),
            "download_tasks": table_count(con, "download_tasks"),
            "import_results": table_count(con, "import_results"),
            "history_events": history_count,
            "history_count": history_count,
            "provider_configs": table_count(con, "provider_configs"),
            "app_settings": table_count(con, "app_settings"),
        }
    return summary


def resolve_series_ids_by_title(db_path, query_text, limit=6):
    """Series whose title/sort_title contains query_text, best match first.

    The series table tops out in the low thousands of rows even on a large
    library, so an unindexed substring scan here is cheap -- unlike the same
    approach against history_events, which is why History search resolves
    to a series first and then re-uses recent_history()'s indexed
    series_id focus path instead of scanning history_events by text.
    """
    query_text = str(query_text or "").strip()
    if not query_text:
        return []
    path = Path(db_path)
    if not path.exists():
        return []
    needle = query_text.lower()
    like = f"%{needle}%"
    with connect_read(path) as con:
        rows = con.execute(
            """
            select id, title
            from series
            where lower(title) like ? or lower(coalesce(sort_title,'')) like ?
            order by
                case when lower(title)=? then 0 else 1 end,
                length(title) asc
            limit ?
            """,
            (like, like, needle, max(1, int(limit or 6))),
        ).fetchall()
    return [{"id": row["id"], "title": row["title"]} for row in rows]


def recent_history_search(db_path, query_text, limit=80, history_filter=None):
    """History rows for every series whose title matches query_text.

    Resolves the free-text query to series ids first, then re-uses
    recent_history()'s existing indexed series_id focus branch (proven at
    ~0.3-0.5s on a 1.5M-row production table, see
    idx_history_bucket_series_created) once per matched series and merges
    in Python. This deliberately avoids extending recent_history()'s SQL
    with a text predicate over history_events itself: the unbounded
    LEFT-JOIN focus branches in that function are already known to take
    ~79s on prod for non-series-id focus shapes, and a message/title LIKE
    scan over 1.5M+ rows would land in that same slow bucket.
    """
    matches = resolve_series_ids_by_title(db_path, query_text)
    if not matches:
        return [], []
    history_filter = history_filter_key(history_filter)
    per_series_limit = max(int(limit or 80), 40)
    merged = {}
    for match in matches:
        for row in recent_history(db_path, per_series_limit, history_filter=history_filter, focus={"series_id": match["id"]}):
            merged[row.get("id")] = row
    ordered = sorted(
        merged.values(),
        key=lambda row: (safe_float(row.get("created_at"), 0), str(row.get("id") or "")),
        reverse=True,
    )
    return ordered, matches


def dedupe_repeated_history_rows(rows):
    """Collapse repeated re-confirmations of the same issue into one row.

    A recurring managed-folder scan re-emits an identical "verified"
    history row for files that were already verified on a previous pass --
    on production this repeats every ~20-30 minutes for the same set of
    already-imported issues, at roughly 300 rows per pass. That's real
    write volume, not a bug in this function's input, but showing every
    occurrence buries the one NEW event a user is actually looking for
    under hundreds of reconfirmations of things they already have. Keeps
    the newest occurrence and folds the rest into repeat_count/first_seen.
    Rows carry no issue_id (series-level/provider-level events) are left
    alone -- collapsing those risks merging unrelated events that just
    happen to share generic message text.
    """
    seen = {}
    out = []
    for row in rows or []:
        issue_key = str(row.get("issue_id") or "").strip()
        message_key = str(row.get("message") or "").strip().lower()
        if not issue_key or not message_key:
            out.append(row)
            continue
        dedupe_key = (issue_key, str(row.get("event_type") or ""), message_key)
        existing = seen.get(dedupe_key)
        if existing is not None:
            existing["repeat_count"] = int(existing.get("repeat_count") or 1) + 1
            existing["first_seen_at"] = row.get("created_at")
            continue
        row = dict(row)
        row["repeat_count"] = 1
        row["first_seen_at"] = row.get("created_at")
        seen[dedupe_key] = row
        out.append(row)
    return out


def history_state_view(db_path, limit=80, history_filter=None, focus=None, summary_mode=None, row_mode=None, search=None):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "view": "history", "db_path": str(path)}
    history_filter = history_filter_key(history_filter)
    focus = normalize_focus_entities(focus)
    search = str(search or "").strip()
    search_matches = None
    fetch_limit = 5000 if focus else max(1, min(int(limit or 80), 300))
    if search and not focus:
        capped_limit = max(1, min(int(limit or 80), 300))
        rows, search_matches = recent_history_search(path, search, capped_limit, history_filter=history_filter)
        rows = dedupe_repeated_history_rows(rows) if history_filter != "all" else rows
        rows = rows[:capped_limit]
    else:
        rows = recent_history(path, fetch_limit, history_filter=history_filter, focus=focus)
        if not focus and history_filter != "all":
            rows = dedupe_repeated_history_rows(rows)
    focused_match_count = None
    focused_count_sampled = False
    if focus:
        rows = focus_rows(rows, focus)
        focused_match_count = len(rows)
        focused_count_sampled = focused_match_count >= fetch_limit
        rows = rows[: max(1, min(int(limit or 80), 300))]
    loaded_count = len(rows)
    filters = history_filter_options(path)
    selected_filter = next((item for item in filters if item.get("value") == history_filter), None)
    if search_matches is not None:
        total_count = loaded_count
    elif focus:
        total_count = focused_match_count
    else:
        total_count = max(loaded_count, int((selected_filter or {}).get("count") or 0))
    summary_mode = str(summary_mode or "full").strip().lower().replace("-", "_")
    row_mode = normalize_state_view_row_mode(row_mode)
    summary = history_view_summary(path)
    response_summary = compact_state_view_summary(summary, "history") if summary_mode in {"compact", "minimal"} else summary
    if history_filter == "activity":
        response_summary = dict(response_summary or {})
        response_summary.update({
            "history_activity_grouped": False,
            "history_activity_sample_limit": 10000,
            "history_activity_sampled_events": min(int(summary.get("history_events") or 0), 10000),
        })
    return {
        "ok": True,
        "view": "history",
        "summary": response_summary,
        "row_mode": row_mode,
        "count": loaded_count,
        "loaded_count": loaded_count,
        "total_count": total_count,
        "limit": max(1, min(int(limit or 80), 300)),
        "rows": compact_state_view_rows("history", rows, row_mode),
        "db_path": str(path),
        "focus": focus,
        "focused": bool(focus),
        "history_filter": history_filter,
        "history_scope": "download_import_lifecycle" if history_filter == "activity" else history_filter,
        "history_candidate_limit": 10000 if history_filter in {"activity", "downloads"} else 1000,
        "history_grouped": False,
        "total_count_sampled": False if search_matches is not None else (focused_count_sampled if focus else True),
        "focused_result_limit": fetch_limit if focus else None,
        "history_taxonomy_version": HISTORY_TAXONOMY_VERSION,
        "history_search": search or None,
        "history_search_matches": search_matches,
        "filters": filters,
        "related_views": [
            {
                "view": "source_memory",
                "label": "Blocklist",
                "detail": "Releases flagged bad and guarded from automatic retry",
            }
        ],
        "fast_path": True,
    }


def history_activity_group_key(row):
    row = row if isinstance(row, dict) else {}
    series_id = str(row.get("series_id") or "").strip()
    series = str(row.get("series") or "").strip()
    if series_id or series:
        return "series", series_id or normalize_key(series), series or "Unknown Series"
    provider = provider_activity_key(row.get("provider_id") or row.get("display_source") or row.get("source") or "")
    if provider and provider != "unknown":
        return "provider", provider, source_display_label(provider)
    entity_type = str(row.get("entity_type") or "activity").strip().lower() or "activity"
    return "unlinked", entity_type, "Unlinked Activity"


def history_activity_event_excerpt(row):
    row = row if isinstance(row, dict) else {}
    return {
        key: clone_jsonish(row.get(key))
        for key in (
            "id",
            "event_type",
            "history_kind",
            "status",
            "outcome",
            "display_phase",
            "display_phase_label",
            "message",
            "next_action",
            "activity_summary",
            "created_at",
            "created_at_iso",
            "series",
            "series_id",
            "issue_number",
            "issue_id",
            "provider_id",
            "display_source",
            "linked_entities",
        )
        if key in row and row.get(key) not in (None, "", [], {})
    }


def history_activity_lite_next_action(history_kind="", outcome="", display_phase="", status="", event_type="", message=""):
    history_kind = str(history_kind or "").strip().lower()
    outcome = str(outcome or "").strip().lower()
    display_phase = str(display_phase or "").strip().lower()
    status = str(status or "").strip().lower()
    event_type = str(event_type or "").strip().lower()
    message = str(message or "").strip()
    if display_phase == "provider_wait" or status in {"provider_wait", "provider_unavailable"}:
        return "Provider/source is waiting; InkDrop will retry automatically"
    if outcome == "problem" or display_phase in {"problem", "manual_review", "failed_candidate"}:
        return "Review recent problem events"
    if display_phase in {"verified"} or outcome == "productive":
        if history_kind in {"download", "import", "verification"}:
            return "Import/download progress recorded"
        return "Automation progress recorded"
    if history_kind == "queue":
        return "Queue activity recorded"
    if history_kind == "source":
        return "Source attempt recorded"
    if history_kind == "provider":
        return "Provider health recorded"
    if history_kind == "series":
        return "Series activity recorded"
    return message or event_type.replace("_", " ").strip() or "Activity recorded"


def history_activity_lite_row(row):
    try:
        row = dict(row or {})
    except Exception:
        row = {}
    event_type = str(row.get("event_type") or "history").strip()
    entity_type = str(row.get("entity_type") or "").strip()
    entity_id = row.get("entity_id")
    source = str(row.get("source") or "").strip()
    message = str(row.get("message") or "").strip()
    history_kind = history_field_kind(event_type, entity_type, source, message)
    outcome = str(row.get("outcome") or "").strip().lower()
    display_phase = str(row.get("display_phase") or "").strip().lower()
    if not outcome or not display_phase:
        fallback_outcome, fallback_phase = history_activity_fields(
            event_type=event_type,
            entity_type=entity_type,
            history_kind=history_kind,
            status=event_type,
            source_key=source,
            message=message,
            raw={},
        )
        outcome = outcome or fallback_outcome
        display_phase = display_phase or fallback_phase
    created_at = safe_float(row.get("created_at"))
    provider_key = provider_activity_key(source)
    linked = linked_entities(
        series_id=row.get("series_id") or (entity_id if entity_type == "series" else None),
        issue_id=row.get("issue_id"),
        queue_id=entity_id if entity_type == "queue_item" else None,
        source_attempt_id=entity_id if entity_type == "source_attempt" else None,
        download_task_id=entity_id if entity_type == "download_task" else None,
        import_id=entity_id if entity_type == "import_result" else None,
    )
    status = str(row.get("status") or event_type).strip().lower()
    bits = []
    if history_kind:
        bits.append(history_kind_summary_label(history_kind, event_type))
    if provider_key:
        bits.append(source_display_label(provider_key))
    if status and status != str(event_type).strip().lower():
        bits.append(status.replace("_", " "))
    if message:
        bits.append(message)
    out = {
        "id": row.get("id"),
        "entity_type": entity_type,
        "entity_id": entity_id,
        "series_id": row.get("series_id"),
        "issue_id": row.get("issue_id"),
        "event_type": event_type,
        "source": source,
        "message": message,
        "outcome": outcome or "neutral",
        "display_phase": display_phase or "observed",
        "display_phase_label": DISPLAY_PHASE_LABELS.get(display_phase, str(display_phase or "observed").replace("_", " ").title()),
        "created_at": created_at,
        "created_at_iso": utc_stamp(created_at) if created_at else None,
        "series": row.get("series"),
        "issue_number": row.get("issue_number"),
        "history_kind": history_kind,
        "provider_id": provider_key or None,
        "provider_key": provider_key or None,
        "display_source": provider_key or source,
        "linked_entities": linked,
    }
    out["status"] = status
    out["activity_summary"] = " · ".join(str(bit) for bit in bits if bit not in (None, ""))
    out["next_action"] = history_activity_lite_next_action(
        history_kind=history_kind,
        outcome=out["outcome"],
        display_phase=out["display_phase"],
        status=status,
        event_type=event_type,
        message=message,
    )
    return out


def recent_history_activity_lite(db_path, sample_limit=1000):
    db_path = Path(db_path)
    if not db_path.exists():
        return []
    sample_limit = max(1, min(int(sample_limit or 1000), 2000))
    with connect_read(db_path) as con:
        rows = con.execute(
            """
            select h.id, h.entity_type, h.entity_id, h.series_id, h.issue_id,
                   h.event_type, h.source, h.message, h.outcome, h.display_phase,
                   h.created_at, s.title as series, i.issue_number
            from history_events h
            left join series s on s.id = h.series_id
            left join issues i on i.id = h.issue_id
            order by h.created_at desc
            limit ?
            """,
            (sample_limit,),
        ).fetchall()
    out = []
    for row in rows:
        item = history_activity_lite_row(row)
        if str(item.get("history_kind") or "").strip().lower() in {"verification", "cleanup"}:
            continue
        out.append(item)
    return out


def history_activity_group_state(group):
    outcome_counts = group.get("outcome_counts") if isinstance(group.get("outcome_counts"), dict) else {}
    phase_counts = group.get("phase_counts") if isinstance(group.get("phase_counts"), dict) else {}
    kind_counts = group.get("kind_counts") if isinstance(group.get("kind_counts"), dict) else {}
    if int(group.get("problem_count") or 0) or int(outcome_counts.get("problem") or 0):
        return "attention"
    if int(group.get("provider_wait_count") or 0) or int(phase_counts.get("provider_wait") or 0):
        return "provider_wait"
    if any(int(phase_counts.get(key) or 0) for key in ("searching", "transferring", "downloading", "importing", "verifying")):
        return "active"
    if any(int(kind_counts.get(key) or 0) for key in ("download", "import", "source", "queue")):
        return "activity"
    return "tracking"


def finalize_history_activity_group(group):
    group = group if isinstance(group, dict) else {}
    state = history_activity_group_state(group)
    kind_counts = group.get("kind_counts") if isinstance(group.get("kind_counts"), dict) else {}
    source_counts = group.get("source_counts") if isinstance(group.get("source_counts"), dict) else {}
    latest = group.get("latest_event") if isinstance(group.get("latest_event"), dict) else {}
    source_rows = [
        {"source": key, "label": source_display_label(key), "count": int(value or 0)}
        for key, value in sorted(source_counts.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
        if int(value or 0) > 0
    ]
    kind_bits = [
        f"{int(kind_counts.get(key) or 0)} {label}"
        for key, label in (
            ("source", "source"),
            ("download", "download"),
            ("import", "import"),
            ("queue", "queue"),
            ("provider", "provider"),
        )
        if int(kind_counts.get(key) or 0) > 0
    ]
    special_bits = []
    if int(group.get("provider_wait_count") or 0):
        special_bits.append(f"{int(group.get('provider_wait_count') or 0)} provider wait")
    if int(group.get("problem_count") or 0):
        special_bits.append(f"{int(group.get('problem_count') or 0)} problem")
    if int(group.get("verified_count") or 0):
        special_bits.append(f"{int(group.get('verified_count') or 0)} verified")
    latest_summary = str(latest.get("activity_summary") or latest.get("message") or latest.get("event_type") or "").strip()
    bits = [f"{int(group.get('event_count') or 0)} recent events"]
    bits.extend(kind_bits[:4])
    bits.extend(special_bits[:3])
    if latest_summary:
        bits.append(f"latest {latest_summary}")
    group.update(
        {
            "state": state,
            "status": state,
            "display_phase": "provider_wait" if state == "provider_wait" else ("problem" if state == "attention" else "activity"),
            "display_phase_label": DISPLAY_PHASE_LABELS.get(state, state.replace("_", " ").title()),
            "activity_summary": " · ".join(bit for bit in bits if bit),
            "next_action": (
                "Open Queue provider-wait rows for this series/provider"
                if state == "provider_wait"
                else ("Review recent problem events" if state == "attention" else "Review recent automation activity")
            ),
            "source_rollup": source_rows[:6],
            "kind_counts": dict(sorted(kind_counts.items())),
            "phase_counts": dict(sorted((group.get("phase_counts") or {}).items())),
            "source_counts": dict(sorted(source_counts.items())),
        }
    )
    return group


def history_activity_drilldown_rows(db_path, limit=40, sample_limit=None):
    limit = max(1, min(int(limit or 40), 300))
    sample_limit = max(limit, min(int(sample_limit or max(200, limit * 20)), 2000))
    events = recent_history_activity_lite(db_path, sample_limit=sample_limit)
    groups = {}
    for row in events:
        row = row if isinstance(row, dict) else {}
        bucket, key, label = history_activity_group_key(row)
        group_id = stable_id("history_activity_group", bucket, key)
        group = groups.setdefault(
            group_id,
            {
                "kind": "activity_group",
                "id": group_id,
                "history_kind": "activity",
                "bucket": bucket,
                "key": key,
                "title": label,
                "series": row.get("series") if bucket == "series" else label,
                "series_id": row.get("series_id") if bucket == "series" else None,
                "event_count": 0,
                "source_attempt_count": 0,
                "download_count": 0,
                "import_count": 0,
                "queue_count": 0,
                "provider_wait_count": 0,
                "problem_count": 0,
                "verified_count": 0,
                "kind_counts": {},
                "outcome_counts": {},
                "phase_counts": {},
                "source_counts": {},
                "latest_at": None,
                "latest_at_iso": None,
                "activity_at": None,
                "created_at": None,
                "latest_event": None,
                "recent_events": [],
                "linked_entities": {},
            },
        )
        created_at = safe_float(row.get("created_at"))
        history_kind = str(row.get("history_kind") or "activity").strip().lower() or "activity"
        outcome = str(row.get("outcome") or "neutral").strip().lower() or "neutral"
        phase = str(row.get("display_phase") or "").strip().lower()
        source = provider_activity_key(row.get("provider_id") or row.get("display_source") or row.get("source") or "")
        group["event_count"] += 1
        group["kind_counts"][history_kind] = int(group["kind_counts"].get(history_kind) or 0) + 1
        group["outcome_counts"][outcome] = int(group["outcome_counts"].get(outcome) or 0) + 1
        if phase:
            group["phase_counts"][phase] = int(group["phase_counts"].get(phase) or 0) + 1
        if source:
            group["source_counts"][source] = int(group["source_counts"].get(source) or 0) + 1
        if history_kind == "source":
            group["source_attempt_count"] += 1
        elif history_kind == "download":
            group["download_count"] += 1
        elif history_kind == "import":
            group["import_count"] += 1
        elif history_kind == "queue":
            group["queue_count"] += 1
        if phase == "provider_wait" or str(row.get("status") or "").strip().lower() in {"provider_wait", "provider_unavailable"}:
            group["provider_wait_count"] += 1
        if outcome == "problem" or phase in {"problem", "manual_review", "failed_candidate"}:
            group["problem_count"] += 1
        if phase == "verified" or (outcome == "productive" and history_kind in {"verification", "import"}):
            group["verified_count"] += 1
        if bucket == "series":
            if row.get("series") and not group.get("series"):
                group["series"] = row.get("series")
                group["title"] = row.get("series")
            if row.get("series_id") and not group.get("series_id"):
                group["series_id"] = row.get("series_id")
        links = row.get("linked_entities") if isinstance(row.get("linked_entities"), dict) else {}
        for link_key in ("series_id", "issue_id", "wanted_id", "queue_id", "source_attempt_id", "download_task_id", "import_id"):
            if links.get(link_key) and not group["linked_entities"].get(link_key):
                group["linked_entities"][link_key] = links.get(link_key)
        excerpt = history_activity_event_excerpt(row)
        if len(group["recent_events"]) < 5:
            group["recent_events"].append(excerpt)
        if created_at and (group["latest_at"] is None or created_at > group["latest_at"]):
            group["latest_at"] = created_at
            group["activity_at"] = created_at
            group["created_at"] = created_at
            group["latest_at_iso"] = utc_stamp(created_at)
            group["latest_event"] = excerpt
    rows = [finalize_history_activity_group(group) for group in groups.values()]
    rows.sort(key=lambda item: (-(safe_float(item.get("latest_at")) or 0), str(item.get("title") or "")))
    return rows[:limit], len(rows), len(events), sample_limit


def history_activity_cache_signature(db_path):
    try:
        with connect_read(db_path) as con:
            row = con.execute("select count(*) as count, max(created_at) as latest_at from history_events").fetchone()
            if row is None:
                return (0, None)
            return (int(row["count"] or 0), safe_float(row["latest_at"]))
    except Exception:
        return None


def cached_history_activity_drilldown_rows(db_path, limit=40):
    path = Path(db_path)
    limit = max(1, min(int(limit or 40), 300))
    signature = history_activity_cache_signature(path)
    cache_key = (str(path), signature, limit)
    now = time.time()
    cached = HISTORY_ACTIVITY_VIEW_CACHE.get(cache_key)
    if isinstance(cached, dict) and now - float(cached.get("ts") or 0) <= HISTORY_ACTIVITY_VIEW_TTL_SECONDS:
        return (
            clone_jsonish(cached.get("rows") or []),
            int(cached.get("total_count") or 0),
            int(cached.get("sampled_events") or 0),
            int(cached.get("sample_limit") or 0),
            "hit",
            round(now - float(cached.get("ts") or now), 3),
        )
    rows, total_count, sampled_events, sample_limit = history_activity_drilldown_rows(path, limit=limit)
    HISTORY_ACTIVITY_VIEW_CACHE.clear()
    HISTORY_ACTIVITY_VIEW_CACHE[cache_key] = {
        "ts": now,
        "rows": clone_jsonish(rows),
        "total_count": int(total_count or 0),
        "sampled_events": int(sampled_events or 0),
        "sample_limit": int(sample_limit or 0),
    }
    return rows, total_count, sampled_events, sample_limit, "miss", 0


def history_activity_drilldown_view(db_path, limit=40, summary_mode=None, row_mode=None, focus=None):
    db_path = Path(db_path)
    if not db_path.exists():
        return {"ok": False, "reason": "state_db_missing", "view": "history", "db_path": str(db_path)}
    limit = max(1, min(int(limit or 40), 300))
    normalized_row_mode = normalize_state_view_row_mode(row_mode)
    rows, total_count, sampled_events, sample_limit, cache_state, cache_age_seconds = cached_history_activity_drilldown_rows(
        db_path,
        limit=limit,
    )
    kind_totals = {}
    state_totals = {}
    for row in rows:
        for key, value in (row.get("kind_counts") or {}).items():
            kind_totals[key] = int(kind_totals.get(key) or 0) + int(value or 0)
        state = str(row.get("state") or "activity")
        state_totals[state] = int(state_totals.get(state) or 0) + 1
    return {
        "ok": True,
        "view": "history",
        "summary": {
            "ok": True,
            "db_path": str(db_path),
            "summary_mode": "compact" if str(summary_mode or "").strip().lower().replace("-", "_") in {"compact", "minimal"} else "full",
            "history_activity_groups": total_count,
            "history_activity_sampled_events": sampled_events,
            "history_activity_sample_limit": sample_limit,
            "history_activity_grouped": True,
            "history_activity_by_kind": kind_totals,
            "history_activity_by_state": state_totals,
            "history_activity_cache": cache_state,
            "history_activity_cache_age_seconds": cache_age_seconds,
        },
        "row_mode": normalized_row_mode,
        "count": len(rows),
        "loaded_count": len(rows),
        "total_count": total_count,
        "limit": limit,
        "rows": compact_state_view_rows("history", rows, normalized_row_mode),
        "db_path": str(db_path),
        "focus": normalize_focus_entities(focus),
        "focused": False,
        "history_filter": "activity",
        "history_grouped": True,
        "filters": history_filter_options(db_path, exact_download_count=False),
    }


FOCUS_ENTITY_KEYS = (
    "series_id",
    "issue_id",
    "wanted_id",
    "queue_id",
    "source_attempt_id",
    "download_task_id",
    "import_id",
    "review_id",
)


def normalize_focus_entities(focus=None):
    focus = focus if isinstance(focus, dict) else {}
    out = {}
    for key in FOCUS_ENTITY_KEYS:
        value = focus.get(key)
        if value in (None, "", [], {}):
            continue
        out[key] = str(value)
    return out


def row_entity_values(row, key):
    values = set()
    if not isinstance(row, dict):
        return values
    for value in (row.get(key), (row.get("linked_entities") or {}).get(key) if isinstance(row.get("linked_entities"), dict) else None):
        if value not in (None, "", [], {}):
            values.add(str(value))
    return values


def row_matches_focus(row, focus):
    focus = normalize_focus_entities(focus)
    if not focus:
        return True
    for key, expected in focus.items():
        if expected in row_entity_values(row, key):
            return True
    return False


def focus_rows(rows, focus):
    focus = normalize_focus_entities(focus)
    if not focus:
        return rows or []
    return [row for row in (rows or []) if row_matches_focus(row, focus)]


def state_view_summary(db_path, scope=STATE_SUMMARY_SCOPE_FULL):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    scope = normalize_state_summary_scope(scope)
    # Deliberately NOT keyed on the database's mtime. Acquisition workers write
    # to this database many times a second, so an mtime-keyed entry was stale
    # almost as soon as it was written and every click paid the full rebuild --
    # measured at 8.4s on a 331-series library. These are counts and rollups
    # for a dashboard, not a ledger; a bounded age is the right trade, and the
    # age is reported in the payload so the UI can say how fresh it is.
    cache_key = f"{path}::{scope}"
    now = time.time()
    with STATE_SUMMARY_CACHE_LOCK:
        cached = STATE_VIEW_SUMMARY_CACHE.get("summary")
        cached_at = float(STATE_VIEW_SUMMARY_CACHE.get("ts") or 0)
        cached_key = STATE_VIEW_SUMMARY_CACHE.get("db_path")
    if (
        isinstance(cached, dict)
        and cached.get("ok")
        and cached_key == cache_key
        and now - cached_at <= STATE_VIEW_SUMMARY_TTL_SECONDS
    ):
        out = clone_jsonish(cached)
        out["summary_cache"] = "hit"
        out["summary_cache_age_seconds"] = round(now - cached_at, 3)
        return out

    def _summary():
        with connect_read(path) as con:
            status_rows = {
                row["status"]: int(row["count"] or 0)
                for row in con.execute("select status, count(*) as count from wanted_items group by status")
            }
            queue_rows_by_state = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute("select state, count(*) as count from queue_items group by state")
            }
            queue_active_rows = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute("select state, count(*) as count from queue_items where active = 1 group by state")
            }
            queue_display_active_rows = queue_display_active_state_counts(con, queue_active_rows)
            review_rows = review_exception_state_counts(con)
            download_tasks = download_task_rollup(con)
            meta = {row["key"]: row["value"] for row in con.execute("select key, value from schema_meta")}
            queue_retry = queue_retry_rollup(con)
            provider_health = provider_health_rollup(con, limit=5)
            bad_source_candidates = bad_source_candidate_rollup(con, limit=5, include_impact=False)
            deferred_queue_syncs = deferred_queue_sync_rollup(con)
            import_ledger_cleanup = import_ledger_cleanup_rollup(con)
            worker_activity = worker_activity_rollup(con)
            duplicate_series_metrics = duplicate_series_title_metrics(con, limit=10)
            # The two most expensive rollups in the whole summary: measured on
            # a 331-series library, queue_backlog_rollup is 5.7s (of which
            # queue_provider_timeout_pressure_rollup, which it calls, is 5.0s)
            # and queue_throughput_rollup is 2.0s. They answer "why is the
            # queue stuck", which the Series and Issues views never show, and
            # every one of those page loads was paying for them and throwing
            # the answer away. The keys they produce are simply absent under
            # the counts scope; compact_state_view_summary already builds by
            # `if key in summary`, so an absent key drops out cleanly.
            queue_analytics = {}
            queue_backlog = {}
            queue_throughput = {}
            if scope != STATE_SUMMARY_SCOPE_COUNTS:
                queue_backlog = queue_backlog_rollup(con)
                queue_throughput = queue_throughput_rollup(con)
                queue_analytics = {
                "queue_backlog_by_reason": queue_backlog["queue_backlog_by_reason"],
                "queue_backlog_by_cause": queue_backlog["queue_backlog_by_cause"],
                "queue_backlog_by_cause_category": queue_backlog["queue_backlog_by_cause_category"],
                "queue_backlog_by_next_source": queue_backlog["queue_backlog_by_next_source"],
                "queue_backlog_by_next_concrete_source": queue_backlog["queue_backlog_by_next_concrete_source"],
                "queue_backlog_by_next_acquisition_source": queue_backlog["queue_backlog_by_next_acquisition_source"],
                "queue_backlog_source_coverage_drilldown": queue_backlog["queue_backlog_source_coverage_drilldown"],
                "queue_backlog_source_coverage_items": queue_backlog["queue_backlog_source_coverage_items"],
                "queue_backlog_provider_wait_items": queue_backlog["queue_backlog_provider_wait_items"],
                "queue_backlog_retry_backoff_items": queue_backlog["queue_backlog_retry_backoff_items"],
                "queue_backlog_candidate_recovery_items": queue_backlog["queue_backlog_candidate_recovery_items"],
                "queue_backlog_policy_blocked_items": queue_backlog["queue_backlog_policy_blocked_items"],
                "queue_backlog_retry_pressure_items": queue_backlog["queue_backlog_retry_pressure_items"],
                "queue_backlog_retry_pressure_by_tier": queue_backlog["queue_backlog_retry_pressure_by_tier"],
                "queue_throughput_items": queue_throughput["queue_throughput_items"],
                "queue_throughput_by_bucket": queue_throughput["queue_throughput_by_bucket"],
                "queue_throughput_no_attempt_items": queue_throughput["queue_throughput_no_attempt_items"],
                "queue_throughput_old_no_attempt_items": queue_throughput["queue_throughput_old_no_attempt_items"],
                "queue_throughput_touched_items": queue_throughput["queue_throughput_touched_items"],
                "queue_throughput_stale_active_items": queue_throughput["queue_throughput_stale_active_items"],
                }
            source_attempts = source_attempt_count_from_connection(con)
            return {
                "ok": True,
                "summary_scope": scope,
                "schema_version": int(meta.get("schema_version") or SCHEMA_VERSION),
                "last_sync_at": float(meta["last_sync_at"]) if meta.get("last_sync_at") else None,
                "last_sync_at_iso": meta.get("last_sync_at_iso"),
                "last_sync_scope": meta.get("last_sync_scope") or "full",
                "db_path": str(path),
                "series": table_count(con, "series"),
                "issues": table_count(con, "issues"),
                "wanted_items": table_count(con, "wanted_items"),
                "wanted_by_status": status_rows,
                "queue_items": table_count(con, "queue_items"),
                "queue_by_state": queue_rows_by_state,
                "active_queue_items": table_count(con, "queue_items", "where active = 1"),
                "queue_by_active_state": queue_active_rows,
                "queue_by_display_active_state": queue_display_active_rows,
                "queue_work_items": sum(int(queue_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                "queue_display_work_items": sum(int(queue_display_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                "queue_exception_items": sum(int(queue_active_rows.get(state) or 0) for state in ("needs_you", "failed", "blocked")),
                "queue_source_wait_items": int(queue_display_active_rows.get("source_wait") or 0),
                **queue_retry,
                **queue_backlog,
                **queue_throughput,
                "source_attempts": source_attempts,
                **download_tasks,
                "import_results": table_count(con, "import_results"),
                "review_exceptions": table_count(con, "review_exceptions", "where active=1"),
                "review_exceptions_by_state": review_rows,
                "manual_review_actionable_count": sum(int(review_rows.get(state) or 0) for state in ("needs_you", "failed", "blocked")),
                "manual_review_parked_count": int(review_rows.get("provider_wait") or 0),
                "history_events": table_count(con, "history_events"),
                "history_count": table_count(con, "history_events"),
                "provider_configs": table_count(con, "provider_configs"),
                "app_settings": table_count(con, "app_settings"),
                **provider_health,
                **bad_source_candidates,
                **deferred_queue_syncs,
                **import_ledger_cleanup,
                **worker_activity,
                **duplicate_series_metrics,
                "standalone_foundation": {
                    "active_queue_items": table_count(con, "queue_items", "where active = 1"),
                    "queue_work_items": sum(int(queue_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                    "queue_display_work_items": sum(int(queue_display_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                    "queue_source_wait_items": int(queue_display_active_rows.get("source_wait") or 0),
                **queue_analytics,
                    "deferred_queue_syncs": deferred_queue_syncs["deferred_queue_syncs"],
                    "deferred_queue_syncs_pending": deferred_queue_syncs["deferred_queue_syncs_pending"],
                    "deferred_queue_syncs_applied": deferred_queue_syncs["deferred_queue_syncs_applied"],
                    "deferred_queue_syncs_acked": deferred_queue_syncs["deferred_queue_syncs_acked"],
                    "deferred_queue_syncs_outstanding": deferred_queue_syncs["deferred_queue_syncs_outstanding"],
                    "deferred_queue_syncs_stale_threshold_seconds": deferred_queue_syncs["deferred_queue_syncs_stale_threshold_seconds"],
                    "deferred_queue_syncs_stale_outstanding": deferred_queue_syncs["deferred_queue_syncs_stale_outstanding"],
                    "deferred_queue_syncs_stale_count": deferred_queue_syncs["deferred_queue_syncs_stale_count"],
                    "deferred_queue_syncs_oldest_outstanding_age_seconds": deferred_queue_syncs["deferred_queue_syncs_oldest_outstanding_age_seconds"],
                    "deferred_queue_syncs_oldest_outstanding_status": deferred_queue_syncs["deferred_queue_syncs_oldest_outstanding_status"],
                    "import_ledger_cleanup_events": import_ledger_cleanup["import_ledger_cleanup_events"],
                    "import_ledger_cleanup_retracted_rows": import_ledger_cleanup["import_ledger_cleanup_retracted_rows"],
                    "import_ledger_cleanup_latest": import_ledger_cleanup["import_ledger_cleanup_latest"],
                    "worker_activity": worker_activity["worker_activity"],
                    "worker_activity_active": worker_activity["worker_activity_active"],
                    "worker_activity_stale": worker_activity["worker_activity_stale"],
                    "worker_activity_problem": worker_activity["worker_activity_problem"],
                    "worker_activity_by_state": worker_activity["worker_activity_by_state"],
                    "worker_activity_by_lane": worker_activity["worker_activity_by_lane"],
                },
            }

    summary = with_db_lock_retry(_summary, attempts=3, initial_delay=0.35)
    if isinstance(summary, dict) and summary.get("ok"):
        summary["summary_cache"] = "miss"
        summary["summary_cache_age_seconds"] = 0
        with STATE_SUMMARY_CACHE_LOCK:
            STATE_VIEW_SUMMARY_CACHE.update({
                "db_path": cache_key,
                "ts": time.time(),
                "summary": clone_jsonish(summary),
            })
    return summary


def state_view_operational_table_summary(db_path, view=None):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    view_key = str(view or "").strip().lower().replace("-", "_")

    def _summary():
        with connect_read(path) as con:
            status_rows = {
                row["status"]: int(row["count"] or 0)
                for row in con.execute("select status, count(*) as count from wanted_items group by status")
            }
            queue_rows_by_state = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute("select state, count(*) as count from queue_items group by state")
            }
            queue_active_rows = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute("select state, count(*) as count from queue_items where active = 1 group by state")
            }
            queue_display_active_rows = queue_display_active_state_counts(con, queue_active_rows)
            review_rows = review_exception_state_counts(con)
            meta = {row["key"]: row["value"] for row in con.execute("select key, value from schema_meta")}
            retry = queue_retry_rollup(con)
            download_tasks = download_task_rollup(con)
            provider_health = provider_health_rollup(con, limit=4)

            _filter, states = queue_filter_states("all")
            state_values = [str(value).strip().lower() for value in (states or []) if str(value or "").strip()]
            reason_counts = {}
            if state_values:
                for row in con.execute(
                    f"""
                    select state, current_source, last_event
                    from queue_items
                    where active = 1
                      and state in ({",".join("?" for _ in state_values)})
                    """,
                    tuple(state_values),
                ):
                    reason_key = queue_wait_reason_key(row["state"], row["current_source"], row["last_event"])
                    if reason_key:
                        reason_counts[reason_key] = int(reason_counts.get(reason_key) or 0) + 1

            provider_wait = int(reason_counts.get("provider_limited") or 0)
            no_candidate = int(reason_counts.get("no_candidate") or 0)
            retry_backoff = int(reason_counts.get("retry_scheduled") or 0)
            candidate_recovery = int(reason_counts.get("failed_candidate_retry") or 0)
            policy_blocked = int(reason_counts.get("language_blocked") or 0)
            source_wait = int(queue_display_active_rows.get("source_wait") or 0)
            summary = {
                "ok": True,
                "schema_version": int(meta.get("schema_version") or SCHEMA_VERSION),
                "last_sync_at": float(meta["last_sync_at"]) if meta.get("last_sync_at") else None,
                "last_sync_at_iso": meta.get("last_sync_at_iso"),
                "last_sync_scope": meta.get("last_sync_scope") or "full",
                "db_path": str(path),
                "summary_mode": "compact",
                "summary_scope": "operational_table",
                "series": table_count(con, "series"),
                "issues": table_count(con, "issues"),
                "wanted_items": table_count(con, "wanted_items"),
                "wanted_by_status": status_rows,
                "queue_items": table_count(con, "queue_items"),
                "queue_by_state": queue_rows_by_state,
                "active_queue_items": table_count(con, "queue_items", "where active = 1"),
                "queue_by_active_state": queue_active_rows,
                "queue_by_display_active_state": queue_display_active_rows,
                "queue_work_items": sum(int(queue_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                "queue_display_work_items": sum(int(queue_display_active_rows.get(state) or 0) for state in ("downloading", "importing")),
                "queue_exception_items": sum(int(queue_active_rows.get(state) or 0) for state in ("needs_you", "failed", "blocked")),
                "queue_source_wait_items": source_wait,
                **retry,
                "queue_backlog_by_reason": reason_counts,
                "queue_backlog_no_candidate_items": no_candidate,
                "queue_backlog_source_limited_items": provider_wait,
                "queue_backlog_provider_wait_items": provider_wait + source_wait,
                "queue_backlog_retry_backoff_items": retry_backoff,
                "queue_backlog_candidate_recovery_items": candidate_recovery,
                "queue_backlog_policy_blocked_items": policy_blocked,
                "queue_backlog_language_blocked_items": policy_blocked,
                "queue_backlog_source_coverage_items": no_candidate,
                "source_attempts": source_attempt_count_from_connection(con),
                **download_tasks,
                "import_results": table_count(con, "import_results"),
                "review_exceptions": table_count(con, "review_exceptions", "where active=1"),
                "review_exceptions_by_state": review_rows,
                "manual_review_actionable_count": sum(int(review_rows.get(state) or 0) for state in ("needs_you", "failed", "blocked")),
                "manual_review_parked_count": int(review_rows.get("provider_wait") or 0),
                "history_events": table_count(con, "history_events"),
                "history_count": table_count(con, "history_events"),
                "provider_configs": table_count(con, "provider_configs"),
                "app_settings": table_count(con, "app_settings"),
                **provider_health,
            }
            if view_key == "series":
                ownership_counts = {}
                for row in con.execute(
                    f"""
                    select source, metadata_provider, kapowarr_id
                    from series s
                    where {series_not_removed_sql('s')}
                    """
                ):
                    ownership = series_ownership(row["source"], row["metadata_provider"], row["kapowarr_id"])
                    ownership_counts[ownership] = int(ownership_counts.get(ownership) or 0) + 1
                summary["series_by_ownership"] = ownership_counts
                summary.update(duplicate_series_title_metrics(con, limit=5))
            return summary

    summary = with_db_lock_retry(_summary, attempts=3, initial_delay=0.2)
    if isinstance(summary, dict) and summary.get("ok"):
        summary["summary_cache"] = "operational_table"
        summary["summary_cache_age_seconds"] = 0
    return summary


def state_view_focused_issue_summary(db_path, focus=None):
    path = Path(db_path)
    if not path.exists():
        return {"ok": False, "reason": "state_db_missing", "db_path": str(path)}
    focus = normalize_focus_entities(focus)
    series_id = focus.get("series_id")
    issue_id = focus.get("issue_id")
    if not series_id and not issue_id:
        return state_view_summary(path)

    issue_where = "i.series_id = ?"
    issue_params = [series_id]
    entity_where = "series_id = ?"
    entity_params = [series_id]
    if issue_id:
        issue_where = "i.id = ?"
        issue_params = [issue_id]
        entity_where = "issue_id = ?"
        entity_params = [issue_id]

    def _summary():
        with connect_read(path) as con:
            meta = {row["key"]: row["value"] for row in con.execute("select key, value from schema_meta")}
            wanted_by_status = {
                row["status"]: int(row["count"] or 0)
                for row in con.execute(
                    f"select status, count(*) as count from wanted_items where {entity_where} group by status",
                    tuple(entity_params),
                )
            }
            queue_by_state = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute(
                    f"select state, count(*) as count from queue_items where {entity_where} group by state",
                    tuple(entity_params),
                )
            }
            queue_by_active_state = {
                row["state"]: int(row["count"] or 0)
                for row in con.execute(
                    f"select state, count(*) as count from queue_items where active = 1 and {entity_where} group by state",
                    tuple(entity_params),
                )
            }
            issue_count = int(
                con.execute(
                    f"select count(*) as count from issues i where {issue_where}",
                    tuple(issue_params),
                ).fetchone()["count"]
                or 0
            )
            return {
                "ok": True,
                "schema_version": int(meta.get("schema_version") or SCHEMA_VERSION),
                "last_sync_at": float(meta["last_sync_at"]) if meta.get("last_sync_at") else None,
                "last_sync_at_iso": meta.get("last_sync_at_iso"),
                "last_sync_scope": meta.get("last_sync_scope") or "full",
                "db_path": str(path),
                "summary_cache": "focused_issue",
                "summary_cache_age_seconds": 0,
                "summary_scope": "issue_focus",
                "focused": True,
                "focus": focus,
                "series": 1 if series_id else int(bool(issue_id)),
                "issues": issue_count,
                "wanted_items": sum(int(value or 0) for value in wanted_by_status.values()),
                "wanted_by_status": wanted_by_status,
                "queue_items": sum(int(value or 0) for value in queue_by_state.values()),
                "queue_by_state": queue_by_state,
                "active_queue_items": sum(int(value or 0) for value in queue_by_active_state.values()),
                "queue_by_active_state": queue_by_active_state,
                "queue_by_display_active_state": dict(queue_by_active_state),
                "queue_work_items": sum(int(queue_by_active_state.get(state) or 0) for state in ("downloading", "importing")),
                "queue_display_work_items": sum(int(queue_by_active_state.get(state) or 0) for state in ("downloading", "importing")),
                "queue_exception_items": sum(int(queue_by_active_state.get(state) or 0) for state in ("needs_you", "failed", "blocked")),
                "queue_source_wait_items": int(queue_by_active_state.get("source_wait") or 0),
                "source_attempts": int(
                    con.execute(
                        f"select count(*) as count from source_attempts where {entity_where}",
                        tuple(entity_params),
                    ).fetchone()["count"]
                    or 0
                ),
                "import_results": int(
                    con.execute(
                        f"select count(*) as count from import_results where {entity_where}",
                        tuple(entity_params),
                    ).fetchone()["count"]
                    or 0
                ),
            }

    return with_db_lock_retry(_summary, attempts=3, initial_delay=0.2)


