def compact_automation_status_payload(value, include_nested=True):
    compact = compact_nested_dict(
        value,
        {
            "kind",
            "state",
            "state_label",
            "reason_key",
            "reason_label",
            "source",
            "source_label",
            "next_source",
            "next_source_label",
            "next_concrete_source",
            "next_concrete_source_label",
            "next_acquisition_source",
            "next_acquisition_source_label",
            "source_plan_summary",
            "recovery_summary",
            "attempt_count",
            "last_attempt_source",
            "last_attempt_status",
            "download_task_id",
            "download_task_state",
            "download_task_source",
            "retry_label",
            "retry_due",
            "retry_after",
            "retry_after_iso",
            "retry_wait_seconds",
            "cause_key",
            "cause_category",
            "cause_label",
            "actionability",
            "needs_user",
            "automatic",
            "next_action",
            "summary",
        },
    ) or {}
    if isinstance(value, dict) and include_nested:
        cause = compact_automation_cause_payload(value.get("cause"))
        evidence = compact_source_evidence_payload(value.get("source_evidence"))
        if cause:
            compact["cause"] = cause
        if evidence:
            compact["source_evidence"] = evidence
    return compact or None


