def state_section_endpoint(section):
    section = dict(section or {})
    key = str(section.get("key") or "").strip().lower()
    if not key:
        return ""
    if key == "settings":
        return "/api/inkdrop-settings"
    params = {
        "limit": "80",
        "summary": "compact",
    }
    if key in SECTION_COMPACT_ROWS:
        params["rows"] = "compact"
    filter_param = SECTION_FILTER_PARAMS.get(key)
    if filter_param:
        params[filter_param] = str(section.get("default_filter") or SECTION_DEFAULT_FILTERS.get(key) or "all")
    return f"/api/inkdrop-state/{key}?{urlencode(params)}"


def state_sections_shell(db_path):
    summary = state_view_operational_table_summary(db_path, view="sections")
    if not summary.get("ok"):
        return summary
    compact_summary = compact_state_view_summary(summary)
    sections = []
    for row in state_sections_from_summary(summary, db_path, fast=True):
        section = dict(row or {})
        endpoint = state_section_endpoint(section)
        if endpoint:
            section["endpoint"] = endpoint
        sections.append(section)
    section_links = {
        str(row.get("key") or ""): row.get("endpoint")
        for row in sections
        if row.get("key") and row.get("endpoint")
    }
    out = dict(compact_summary)
    out.update(
        {
            "ok": True,
            "view": "sections",
            "dashboard_shell": True,
            "preview_mode": "deferred",
            "queue_preview_deferred": True,
            "history_preview_deferred": True,
            "sections": sections,
            "section_count": len(sections),
            "section_links": section_links,
            "summary": compact_summary,
            "queue_summary": {
                "active": summary.get("active_queue_items"),
                "work": summary.get("queue_display_work_items"),
                "source_wait": summary.get("queue_source_wait_items"),
                "retry_due": summary.get("queue_retry_due_items"),
                "retry_later": summary.get("queue_retry_later_items"),
                "no_candidate": summary.get("queue_backlog_no_candidate_items"),
                "provider_wait": summary.get("queue_backlog_provider_wait_items"),
            },
            "source_health_summary": {
                "problem_items": summary.get("provider_health_problem_items"),
                "by_state": clone_jsonish(summary.get("provider_health_by_state") or {}),
                "attention": clone_jsonish(summary.get("provider_health_attention") or []),
            },
            "source_memory_summary": clone_jsonish(summary.get("source_memory_summary") or {}),
            "db_path": str(db_path),
        }
    )
    return out
